pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are heavily penalized (non-linear quadratic ramp).
    let dead_threshold: f64 = 30.0;
    if (post_residual as f64) < dead_threshold {
        let gap = dead_threshold - post_residual as f64;
        score += 4.0 * gap * gap;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Perfect-fill lookahead: if the next item exactly fills the post-residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits comfortably: mild bonus proportional to leftover slack.
        score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residual: penalize proportionally to wasted space.
        score += 8.0 * post_residual as f64 / dead_threshold;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let openness = open_bins_count as f64 / (1.0 + total_items as f64);
    score += 10.0 * openness * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is already low
    // (i.e., consolidate into nearly-full bins).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 6.0 * dev;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let urgency = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 20.0 * urgency + 0.5 * open_bins_count as f64;
        if post_residual as f64 >= dead_threshold {
            score -= 10.0;
        }
    }

    // Stream progression: late in the stream, be more conservative about waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (<= 10, min item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderately small gaps are hard to fill too.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Exact fit for the lookahead item: strongly favor.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Dead space relative to lookahead: leaving a gap the next item can't use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight fills
    // (small post_residual) even more; few open bins -> tolerate new bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 30.0;

    // New-bin candidate: only attractive when existing residuals are poor fits
    // (e.g. current item barely fits anywhere or would leave a tiny gap).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by how bad the best alternative is.
        let gap_waste = if post_residual > 0 && post_residual < 10 { 40.0 } else { 0.0 };
        score = bin_capacity as f64 * 0.55 + gap_waste
            - pressure * 5.0
            - if fitting_bins_count == 0 { 30.0 } else { 0.0 };
    }

    // Late in the stream, tighten up: waste penalized harder.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to the item (tight fit relative measure).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual dominates).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // 2-step lookahead: reward residuals that can host the next item exactly/well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score += 0.25 * gap;
        } else {
            // next item can't fit here; slight penalty proportional to shortfall
            let short = (next_item_size - post_residual) as f64;
            score += 0.1 * short;
        }
    } else {
        // Last item: strongly prefer minimal waste.
        score -= 20.0;
    }

    // Compare against mean residual: penalize bins that are already tight
    // (would create dead space relative to fleet average).
    let res = post_residual as f64;
    if res < mean_residual * 0.5 {
        score += 4.0 * (mean_residual - res) / bin_capacity as f64;
    } else if res > mean_residual * 1.5 {
        score -= 2.0 * (res - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only fitting bin, avoid wasting it on a bad fit.
    if fitting_bins_count == 1 {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if waste_ratio > 0.3 {
            score += 15.0 * waste_ratio;
        } else {
            score -= 10.0;
        }
    }

    // New-bin candidate: default mild penalty; allow opening a new bin only when
    // all open bins would leave large dead space.
    if bin_residual == bin_capacity {
        let best_possible = if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            0.0 // chainable pair, new bin is attractive
        } else {
            8.0
        };
        score = 25.0 + best_possible - (fitting_bins_count as f64) * 3.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly useless.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 14.0; // small gaps heavily penalized
    }
    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward using a bin whose residual was already fragmented/low-value,
    // i.e. prefer packing into bins with small residuals (best-fit core).
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.5;

    // Pressure from open bin count: with many open bins, prefer consolidating
    // into existing bins rather than spreading.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 90.0;
    }
    // Penalize if post_residual cannot hold the next item and is small (dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 && post_residual < 25 {
        score += 30.0;
    }

    // New-bin candidate handling: empty bin gets a baseline score that makes it
    // attractive only when the fit into open bins would be poor.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55
            + open_bins_count as f64 * -0.2
            + (item_size as f64 / bin_capacity as f64) * 30.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: must open a new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // large current item suggests fresh bin is fine
        }
    }

    // Mild progression term: late in the stream, be slightly more conservative
    // about opening bins (consolidate).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // Prefer bins whose residual is close to the mean (balanced usage) slightly.
    score -= ((bin_residual as f64 - mean_residual).abs()) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are worthless.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver penalty
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Penalize large post_residual less if a known next item can use it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 {
        score += (next_item_size as f64 - post_residual as f64).min(40.0);
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, allow it.
    let pressure = (open_bins_count as f64).ln() * 4.0;
    score += pressure;

    // New-bin candidate: make it attractive only when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // New bin is good for large items or when few fitting bins exist.
        score = 30.0 - 20.0 * tightness - 35.0 * (fitting_bins_count == 1) as i32 as f64;
        if post_residual == bin_capacity {
            // empty bin baseline: compare against mean residual of open bins
            score += mean_residual * 0.2;
        }
    }

    // Mild phase adjustment: later in stream, prefer consolidating (lower post_residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    } else if post_residual < 20 {
        score += 150.0 * (20.0 - post_residual as f64) / 20.0;
    } else if post_residual == 0 {
        // Perfect fit is maximally rewarded.
        score -= 300.0;
    } else {
        // Reward tight fits proportionally.
        score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Coupling with next item: if the next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 80.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post residual cannot host the next item: penalize proportionally to gap size.
        score += 30.0 * (post_residual as f64 / 100.0);
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins when residuals are similar.
    score += open_bins_count as f64 * 3.0;

    // Prefer bins whose residual deviates below the mean (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Early in the stream, be more willing to open new bins for large items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive for large items early, penalized later.
        score -= 60.0 * (1.0 - progress) - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for exact or near-exact fills (post_residual near 0).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space super-linearly: small leftovers are very wasteful.
        let pr = post_residual as f64;
        score += pr * pr / 60.0;

        // 2-step lookahead: if the next item fits the post-residual, this is a
        // great pairing — reward it. Otherwise penalize a mismatch.
        if next_item_size > 0 {
            let n = next_item_size as f64;
            if next_item_size <= post_residual {
                // Next item fits: reward tightness of the two-item packing.
                let pair_waste = post_residual - next_item_size;
                score -= 40.0 - pair_waste as f64 * 0.5;
            } else {
                // Next item won't fit here: mild penalty scaled by overshoot.
                score += (n - pr).min(40.0) * 0.3;
            }
        }

        // Compare against mean residual of open bins: prefer bins that end up
        // below the mean residual (tighter than average).
        score += 0.5 * (pr - mean_residual);

        // Last-chance bin: strongly favor using it before opening a new bin.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }

        // Late in the stream, tighten packing (avoid opening bins needlessly).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 3.0;

        // Many open bins: prefer consolidating into existing ones.
        score += open_bins_count as f64 * 0.5;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Make the empty-bin score mediocre so good
    // existing fits beat it, but poor fits (large post_residual) lose to it.
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 0.3 - 10.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps are nearly unusable
    // (min item size is small, but gaps <= 12 waste capacity long-term).
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 8.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Tight fit reward: post_residual < next_item_size means gap can't
    // serve the upcoming item either.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.2 * post_residual as f64;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // existing bins fit fine.
    if bin_residual < bin_capacity {
        score += 0.35 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins whose residual is already below the mean (consolidate
    // fullness), penalize chipping away at large-residual bins.
    score += 0.4 * (mean_residual - post_residual as f64);

    // Mild stream-position damping of new-bin attractiveness.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Penalize large dead space, scaled by how unusable it is:
    // dead space smaller than the smallest plausible item is worse.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 60.0 * (10.0 - dead);
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // next item still fits here; mild reward proportional to leftover after chain
            score -= 30.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize more if this bin's leftover is tiny
            score += 10.0 * (next_item_size as f64 - post_residual as f64).min(50.0);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits; add small dispersion penalty.
        score += (fitting_bins_count as f64).ln() * 3.0;
    }

    // Global state: if mean residual across open bins is high (lots of slack),
    // prefer filling existing bins rather than opening new ones.
    let slack_ratio = mean_residual / bin_capacity as f64;
    score -= 25.0 * slack_ratio;

    // New-bin candidate handling: only attractive early in the stream or when
    // the current bin would leave a very awkward residual.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new bin: base cost, discounted early in the stream
        score += 120.0 * (1.0 - 0.5 * (1.0 - progress));
        // attractive if item is large (uses a fresh bin efficiently)
        score -= 40.0 * (item_size as f64 / bin_capacity as f64);
        // less attractive if plenty of open bins with slack exist
        score += 30.0 * slack_ratio;
    } else {
        // existing bin: mild preference as stream progresses to consolidate
        score -= 10.0 * progress;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // unless it is a near-exact fit which is already rewarded.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Tiny tie-breaker favoring fuller bins.
    score += 0.01 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space is bad if unusable
    let dead = post_residual as f64 / bin_capacity as f64;
    score += dead * dead * 40.0;

    // Penalize post_residual in "awkward" classes (small unusable slivers)
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 25.0; // sliver
    }
    // Modulo-10 class coupling: residual divisible by 10 is more reusable
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            score -= 15.0;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin bonus: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Encourage tight packing when many bins are open
    score += (open_bins_count as f64) * 0.5;

    // New-bin candidate handling: opening a new bin is expensive unless
    // current residuals are all poor fits
    if bin_residual == bin_capacity {
        // fresh bin baseline: slight penalty so it's chosen only when better
        score += 5.0;
        if mean_residual < item_size as f64 {
            // no open bin can usefully absorb -> new bin is good
            score -= 80.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - 10 {
            score -= 30.0; // large next item benefits from fresh bin
        }
    }

    // Progress-aware tightening: later in stream, be more conservative
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= 10) are pure waste; penalize heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small gaps are only usable by tiny items; scale penalty.
        score += 25.0 + (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // If this bin can also fit the lookahead item exactly after placement,
    // strongly favor it (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }
    // If the lookahead item would be blocked by the resulting residual,
    // mild penalty unless residual becomes near-useless anyway.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 6.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, opening a new bin is less costly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.8 + 0.4 * progress);

    // New-bin candidate handling: an empty bin has perfect flexibility but
    // should only win when the fit into existing bins is poor. Base its
    // score on the mean residual landscape.
    if bin_residual == bin_capacity {
        score = 30.0 + mean_residual * 0.5;
        // Late in the stream, prefer closing out existing bins.
        score += 15.0 * progress;
        // If several bins already fit, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 10.0 + 5.0 * fitting_bins_count as f64;
        }
        // But if the only fitting bin would leave a large dead gap, allow
        // the new bin to win.
        if fitting_bins_count == 1 && post_residual >= 10 && post_residual < 30 {
            score -= 20.0;
        }
    }

    // Mild bonus for keeping residuals aligned with common item sizes
    // (multiples of 10 are most reusable).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space: residuals too small to fit a typical future item.
    let min_useful = 10u32;
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0;
    } else if post_residual < 20 {
        score += 8.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size <= bin_residual {
            // current bin could have served next item; mild penalty
            score += 5.0;
        }
        // reward leaving space compatible with the next item's complement
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score += 0.05 * gap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is expensive when few bins
    // are open or many bins already exist with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.1);
        score += 25.0 + 10.0 * progress - 0.2 * pressure;
        // opening a new bin is fine if it perfectly hosts the item
        if item_size == bin_capacity {
            score -= 60.0;
        }
    }

    // Prefer bins whose residual is close to item_size (best-fit flavor),
    // scaled by global slack so tight streams reward consolidation.
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * diff * (mean_residual / bin_capacity as f64).max(0.5);

    // Mild preference to fill bins with above-average residual (balance load).
    score += 0.03 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic class of post_residual: classify dead space by capacity fraction.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (post_residual / 25) as f64; // integer division: 0..4 harmonic class
    let mod10 = (post_residual % 10) as f64;

    // Reward large post_residual classes (more usable space), i.e. subtract for classes 3-4.
    score -= 8.0 * quarter;

    // Penalize awkward small-but-nonzero residuals (dead space): class 0 with pr > 0.
    if post_residual > 0 && quarter == 0.0 {
        score += 6.0 + mod10 * 0.5;
    }

    // Perfect fit: zero residual is excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item slots exactly or leaves good class.
            let nxt_mod = (next_item_size as f64) * 0.05;
            score -= 10.0 - nxt_mod;
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0; // exact divisor: harmonic tiling
            }
        } else {
            // Next item won't fit here: residual risks becoming dead space.
            score += 4.0 + (next_item_size as f64 - pr).min(30.0) * 0.2;
        }
    } else {
        // Last item: prefer closing bins tightly.
        score -= 5.0;
    }

    // Last-chance bonus: only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 * 0.4 + mean_residual * 0.05;
        let poor_fit = if post_residual as f64 > cap - item_size as f64 { 0.0 } else { 0.0 };
        let _ = poor_fit;
        // New bin starts with residual == capacity, so quarter == 4 gives base reward.
        // Penalize it unless few bins fit the item or mean residual is low.
        score += 14.0 - crowded - if fitting_bins_count <= 1 { 20.0 } else { 0.0 }
                 - (cap - mean_residual).max(0.0) * 0.1 - progress * 3.0;
    }

    // Mild preference for filling fuller bins (low mean residual pressure).
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: perfect fits and residuals that
    // match common item sizes (modulo classes) are valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward residuals that are "usable" — divisible into plausible item sizes.
    if post_residual >= 10 {
        let div10 = post_residual % 10 == 0;
        let div20 = post_residual % 20 == 0;
        if div10 { score -= 12.0; }
        if div20 { score -= 8.0; }
        // Harmonic fraction: residual as fraction of capacity; small usable fractions good.
        let frac = pr / cap;
        if frac < 0.2 {
            score -= 10.0 * (0.2 - frac);
        } else {
            score += 5.0 * (frac - 0.2);
        }
    } else if post_residual > 0 {
        // Dead space penalty for tiny unusable remainders (1..9).
        score += 25.0;
    }

    // Coupling with lookahead item: if next item fits exactly in post_residual,
    // strongly favor this bin (chained perfect packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 200.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
        // Harmonic pairing: next item leaves a multiple-of-10 remainder too.
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        // Next item cannot use this residual: penalize proportionally.
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate (fresh empty bin): penalize unless current bins are crowded
    // or the item is large and fits alone nicely.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 15.0 || open_bins_count == 0;
        let big_item = (item_size as f64) > 0.6 * cap;
        if crowded || big_item {
            score -= 60.0;
        } else {
            // Prefer filling existing bins; new bin only if residual waste is high.
            score += 30.0 + 0.5 * mean_residual;
        }
    }

    // Progress term: early in stream, tolerate more open bins; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (post_residual as f64 / cap);

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    score = post_residual as f64 * 1.5;

    // Strict dead-space avoidance: gaps too small for the next item (or the
    // minimum item size) are "dead" — penalize them hard.
    let min_size = 1u32;
    let dead_threshold = if next_item_size > 0 { next_item_size.min(80) } else { min_size };
    if post_residual < dead_threshold {
        score += 25.0 * (dead_threshold - post_residual) as f64;
    }

    // Perfect fit is golden
    if post_residual == 0 {
        score -= 40.0;
    }

    // Small-but-alive residual is fine; large leftover waste is mild penalty
    if post_residual > 0 && post_residual < dead_threshold.max(10) {
        score -= 10.0; // gap still usable for tiny items
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few,
    // filling bins tightly is fine.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += pressure * 0.5;

    // Prefer bins whose residual is near the item (coupling with mean residual)
    score += (mean_residual - bin_residual as f64).abs() * 0.2;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 35.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // creates dead space for the known next item
        score += 15.0;
    }

    // New-bin candidate: only attractive when current bin residual is badly
    // fragmented (very small residual) or no open bin fits well.
    if bin_residual == bin_capacity {
        // neutral baseline with slight penalty so it only wins when open bins score poorly
        score += 20.0 + open_bins_count as f64 * -0.1;
        if fitting_bins_count <= 1 {
            score -= 25.0; // nothing fits elsewhere well -> new bin OK
        }
    }

    // Reward bins that can still hold a generic future item after placement
    if post_residual >= 50 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Reward bins whose residual matches next item size (lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bonus: only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Pressure from many open bins: favor filling existing bins over opening new ones.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: penalize opening a new bin unless existing bins are crowded.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * -0.4;
    }

    // Slight progress pressure: later in stream, prefer consolidation.
    score += (step_index as f64 / total_items.max(1) as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward leaving a residual that exactly
    // accommodates the next item (chained perfect packing).
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64 - nr).abs() < 0.5 {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // Good: next item still fits; scale reward by tightness of match.
            let slack = post_residual as f64 - nr;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Bad: dead space the next item cannot use; penalize the gap.
            score += 2.0 * (nr - post_residual as f64);
        }
    }

    // Penalize residuals that are small but unusable (below minimum item size 1
    // is impossible here, but tiny residuals are still waste relative to mean).
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.5 {
            score += 0.5 * (mean_residual - pr);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
        if post_residual <= 10 {
            score -= 60.0; // near-perfect last-chance fit
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are poor. Make the empty-bin call (residual == capacity)
    // moderately expensive so it is chosen only when open-bin fits are bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if the next item is large and this item is small, a fresh bin
        // preserves large contiguous space — slightly cheaper to open.
        if next_item_size > 0 && next_item_size > post_residual + 10 {
            score -= 20.0;
        }
    }

    // Slight late-stream pressure: prefer consolidating into fewer bins as
    // the stream progresses to avoid bin-count blowup.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item can use are pure waste.
    // Any gap smaller than the smallest possible item (1) is impossible, but gaps that
    // cannot fit the lookahead item are strongly penalized (wasted relative to lookahead).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space with respect to the next item: penalize proportionally,
            // extra harsh when the gap is tiny (unusable for most sizes).
            score += (next_item_size - post_residual) as f64 * 1.5;
            if post_residual < 10 {
                score += 20.0;
            }
        } else {
            // Reward bins whose leftover can still host the next item.
            score -= 5.0;
        }
    }

    // Non-linear penalty on very small post_residuals (classic "best-fit trap"):
    // a residual of exactly 0 is perfect; residuals of 1..=5 are near-dead.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score += (6 - post_residual) as f64 * 4.0;
    }

    // Open-bin pressure: discourage scattering items across many open bins
    // unless the fit is excellent. Scales with fraction of stream completed.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild preference toward bins tighter than average (good consolidation).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: neutral-ish baseline; only chosen when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 10.0 + post_residual as f64 * 0.5;
        // Opening a new bin is more acceptable early when few bins are open.
        score -= open_bins_count as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 60.0 - chain_waste * 0.5;
        } else {
            // next item won't fit here; penalize leaving awkward gaps
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(40.0) * 0.8;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let pressure = (open_bins_count as f64).ln().max(1.0);
        // base penalty for opening a new bin
        score += 120.0;
        // but if existing residuals are small (poor fits), new bin becomes better
        score -= (1.0 - crowding) * 200.0;
        // early in stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 30.0;
        // large item that barely fits anywhere: new bin is clean
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 50.0;
        }
        let _ = pressure;
    }

    // Prefer filling bins with larger mean residual less aggressively
    score -= (mean_residual - post_residual as f64) * 0.1;

    // Mild preference to keep number of open bins stable
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (min item size 1..100, but typical items are
    // chunky) are pure waste. Penalize a "dead zone" band harshly.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold {
        // Quadratic penalty inside the dead zone: smaller gap => worse.
        score += (dead_threshold - post_residual as f64).powi(2) * 0.8;
    }

    // Reward tight fits (small post_residual) super-linearly.
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    score -= fit_ratio * fit_ratio * 15.0;

    // Perfect/near-perfect closure gets a strong bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 3 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // Even better: next item leaves its own small residual too.
        let next_left = post_residual - next_item_size;
        if next_left <= 5 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; leftover is likely dead space.
        if post_residual > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than spreading; penalize this bin less
    // if open_bins_count is high (favor using existing bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score -= pressure * 2.0;

    // Mean residual coupling: if this bin's residual is far below the
    // mean, it's already "fragmented" relative to the fleet; using it
    // up is good. If it's near the mean and post_residual is large,
    // keep it for future items.
    let res_diff = mean_residual - bin_residual as f64;
    score += res_diff * 0.3;

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin has full residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no existing bin fits
        // well; make it moderately expensive so tight fits win.
        score += 12.0;
        // But if the item is large, a fresh bin is actually ideal.
        if item_size >= 60 {
