    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item nests perfectly into this bin's future space
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 40.0 * snug;
        } else {
            // next item won't fit here: mild penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 8.0 * (over / cap).min(1.0);
        }
    }

    // Modulo-class harmony: prefer leftover whose residue mod 10 is small
    // (aligns with typical granularity of item sizes).
    let rem = (post_residual % 10) as f64;
    score -= 6.0 * (1.0 - rem / 10.0);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using
    // it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive early
    // in the stream or when many bins are already open and this fit is poor.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // cheaper to open new bins early (stream just started)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        // if many open bins already, discourage spreading
        score += 2.0 * open_bins_count as f64;
    } else {
        // mild bonus for using an existing bin generally
        score -= 5.0;
    }

    // Slight preference for bins with residuals below the mean residual
    // (tighter bins get filled first, keeping loose bins flexible).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals that are too small to hold
    // any plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Penalize "awkward" residuals: small but not zero gaps (10..=20)
    // are hard to fill later; scale penalty by how close to dead zone.
    if post_residual >= 10 && post_residual <= 20 {
        score += 12.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward placements that leave room for the lookahead item exactly.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 10 {
        score -= 8.0;
    }
    // Penalize leaving a gap the next item cannot use at all.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is great.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin's fit is poor
    // (large post_residual) or item barely fits. Penalize default new bin
    // mildly so it is chosen only for bad fits.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * (bin_residual as f64 - item_size as f64);
        // If many bins fit already, opening new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 10.0;
        }
    }

    // Prefer bins with below-mean residual (fill emptier bins first keeps
    // tight bins available for small items).
    score += (mean_residual - post) * 0.3;

    // Late in the stream, tighten up: prioritize closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: zero post residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 300.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        if gap == 0.0 {
            score -= 500.0; // exact 2-step chain: item fills, next item fills remainder
        }
        // Penalize post_residual too small for next item if it wastes space anyway
        if (post_residual as u64) < (next_item_size as u64) && post_residual > 0 {
            score += 0.5 * post_residual as f64;
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    score -= 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // Penalize creating tiny unusable slivers (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Mild preference for keeping larger residuals consolidated when many bins open.
    score += 0.1 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin is a good fit.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 250.0 - 600.0 * pressure
            + if next_item_size > 0 { (item_size as f64 + next_item_size as f64).min(200.0) } else { 0.0 };
        if fitting_bins_count <= 1 {
            score -= 300.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor placements that nearly fill the bin.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for future items
    // (items range 1..100; residual below ~10 is nearly dead).
    if post_residual > 0 && post_residual < 12 {
        score += 15.0;
    }

    // Lookahead coupling: reward if the next item fits exactly into post_residual,
    // penalize if next item almost fits but not quite.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 10.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // next item cannot fit in leftover; mild penalty scaled by overflow
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.15 * overflow;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be more exploratory (penalize fragmenting
    // many bins); late in the stream, prefer filling existing bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.05 * open_bins_count as f64;

    // Global residual pressure: if mean residual across open bins is low,
    // opening new capacity is more acceptable; if mean residual is high,
    // push toward consuming existing bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: compare against mean residual of open bins.
        // Opening a new bin is penalized when open bins have plenty of slack
        // that could absorb the item, unless the item is huge (poor fit anywhere).
        let slack_pressure = mean_residual - item_size as f64;
        score += 5.0 + 0.3 * slack_pressure.max(0.0);
        // Late stream: new bins are cheaper to open when few alternatives exist.
        score -= 20.0 * progress * (1.0 - (open_bins_count as f64 / 50.0).min(1.0));
        // Huge items fit better in a fresh bin than fragmenting a partially used one.
        if item_size > bin_capacity * 3 / 4 {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward using it more when mean residual is high (avoid sprawl).
        score -= 0.1 * mean_residual.max(0.0).min(100.0) / 100.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Mild penalty proportional to wasted fraction, non-linear.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste * waste * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post residual, mildly discounted as stream progresses
    let mut score = post * (1.0 - 0.25 * progress);

    // Smooth polynomial coupling: penalize tiny dead space quadratically near zero,
    // but reward very tight fits (post near 0) via a dip.
    let tightness = post / cap;
    let poly = tightness * tightness * (3.0 - 2.0 * tightness); // smoothstep in [0,1]
    score += 12.0 * poly * (1.0 - 0.5 * progress);

    // Reward filling the bin well relative to capacity
    score -= 8.0 * (item / cap) * (item / cap) * (1.0 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // New-bin candidate: penalize unless residual is very tight (item almost fills it)
    if bin_residual == bin_capacity {
        let fill = item / cap;
        score += 25.0 * (1.0 - fill) * (1.0 - fill) * (1.0 + progress);
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 + 6.0 * progress;
    } else if next_item_size > 0 {
        // next item won't fit: penalize proportionally to wasted space
        score += 3.0 * (post - (post % next_item_size.max(1) as f64)) / cap;
    }

    // Many open bins: slight penalty to discourage bin proliferation
    score += 0.4 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    score += 0.15 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space in (0,10) is nearly unusable
    // for items >=10, so penalize small positive residuals sharply.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: highly desirable
    } else if pr < 10 {
        score += (10 - pr) as f64 * 4.0; // dead space penalty
    } else {
        // Reward residuals that belong to "harmonic" classes matching common item
        // sizes: multiples of 10 and values like 50 (half-capacity) are reusable.
        let m10 = pr % 10;
        if m10 == 0 {
            score -= 12.0;
        } else if m10 <= 3 || m10 >= 8 {
            score += 6.0; // awkward remainder class
        }
        // Half-capacity residuals pair well with mid-size items.
        if pr == bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post-residual, strong bonus.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            // Fractional tightness of the follow-up fit.
            let tight = (next_item_size as f64) / (pr as f64);
            score -= 20.0 * tight;
        } else {
            score += 10.0; // next item cannot use this bin's remainder
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or stream is early and bins are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let frac = item_size as f64 / cap;
        score += 55.0 - 40.0 * frac - 20.0 * (1.0 - progress);
        // If existing bins are crowded (low mean residual), a fresh bin is cheaper.
        if mean_residual < 15.0 {
            score -= 30.0;
        }
    }

    // Mild preference for filling bins that are already more depleted.
    score -= 0.15 * (cap - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are dead.
    // Penalize post_residual hard when it falls into an unusable band (0 < post < 10),
    // and progressively less as the gap becomes more reusable.
    if post > 0.0 {
        if post < 10.0 {
            score += 60.0 * (1.0 - post / 10.0); // near-perfect fill rewarded, tiny gap punished
        } else if post < 20.0 {
            score += 12.0; // awkward gap band
        } else {
            score -= 8.0; // large residual is a reusable resource
        }
    } else {
        // Perfect fill is the best outcome: strong reward.
        score -= 40.0;
    }

    // Tight-fit bonus: reward closeness of item to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Open-bin pressure: discourage scattering across many bins unless the fit is excellent.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 3.0);
    score += 3.0 * pressure * (1.0 - fit_ratio.min(1.0));

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits into the post residual, reward leaving
    // that exact space; if it does not fit, penalize a residual that is just barely
    // too small (near-miss dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 15.0 * (1.0 - ((post - nxt) / cap).min(1.0));
        } else if post > 0.0 && nxt - post <= 10.0 {
            score += 10.0 * (1.0 - (nxt - post) / 10.0);
        }
    }

    // New-bin candidate handling: a fresh empty bin is attractive when the current fit
    // is loose (large post_residual relative to capacity) or when mean residual across
    // open bins is already high (open bins are cluttered).
    if bin_residual == bin_capacity {
        let loose_fit = post / cap; // = 1 - item/cap for empty bin
        let clutter = (mean_residual / cap).min(1.0);
        score = 25.0 + 30.0 * (1.0 - loose_fit) + 25.0 * clutter + 2.0 * open_bins_count as f64;
        // Make new bin clearly unattractive when the item fits an open bin tightly.
        if fit_ratio > 0.6 && fitting_bins_count >= 1 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (dead space eliminated).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    }
    // Partial lookahead credit: next item fits into the leftover space.
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 40.0 * (next_item_size as f64 / post_residual as f64);
    }
    // Penalize leftovers that no plausible item can use (post_residual < 10 or < next item).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }
    if next_item_size > post_residual && post_residual > 0 {
        score += 60.0;
    }

    // Tightness of the current fit: prefer bins where item occupies a large fraction.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 50.0 * fill_ratio;

    // Relative to mean residual: prefer using bins with below-average residual
    // (compact bins) to keep large-residual bins available for large items.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New empty bin candidate: penalize opening a new bin unless current
    // residuals are all poorly matched (post_residual small relative to item).
    if bin_residual == bin_capacity {
        score += 250.0;
        // Allow new bin if it would be almost perfectly used by next item too.
        if next_item_size > 0 && (bin_capacity - item_size - next_item_size) <= 5 {
            score -= 400.0;
        }
    }

    // Late in the stream, avoid opening bins aggressively.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 150.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that can never be reused by typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Extra reward if next item fills the bin almost exactly after that.
        let two_step_waste = post_residual - next_item_size;
        score -= 20.0 * (1.0 - two_step_waste as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual too small for lookahead item: penalize proportionally.
        score += 8.0 * (next_item_size as f64 - post_residual as f64) / item_size.max(1) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: only attractive when open bins are crowded
    // (mean residual small) or stream is early with few open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 35.0;
        // Less penalty early in the stream (future flexibility worth more).
        score -= 20.0 * (1.0 - progress);
        // Less penalty when open bins are tight (mean_residual low).
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 30.0 * mean_tightness;
        // If very few bins fit the item, opening a bin is more acceptable.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // Slight penalty for bin sprawl late in stream.
        score += (open_bins_count as f64).ln().max(0.0) * 3.0 * progress;
    } else {
        // Mild bonus for using already-open bins, scaled by how full they are.
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 10.0 * fill;
    }

    // Global balance: prefer bins whose residual is near the mean (keeps
    // residuals uniform, preserving future packing options).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Small time-dependent tightening: as stream progresses, prioritize
    // minimizing current waste more aggressively.
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: quadratic waste penalty on post_residual (dead space grows quadratically).
    let mut score = pr * pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack (favor large residuals); late, punish waste harder.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score += pr * progress_coupling;

    // Reward tight fits smoothly: subtract a polynomial bonus that peaks when
    // post_residual is small relative to the item.
    let tightness = 1.0 - (pr / cap);
    score -= cap * tightness * tightness * fit_ratio * (1.0 + progress);

    // Lookahead: smooth reward if next item fits the post-residual, polynomial falloff.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let compat = 1.0 - gap / cap;
        if compat > 0.0 {
            score -= 8.0 * compat * compat * (1.0 + 0.5 * progress);
        } else {
            score += 3.0 * (-compat) * (1.0 - 0.5 * progress);
        }
    }

    // Last-chance bin: strong smooth discount to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly early (reuse bins), relax late in the stream
    // via smooth polynomial in progress; also scale with number of open bins.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).sqrt();
        score += 12.0 * (1.0 - progress * progress) * (1.0 + openness);
    }

    // Mean residual alignment: smooth penalty if this bin deviates from the fleet mean.
    let dev = (pr - mean_residual).abs() / cap;
    score += 4.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Fraction of capacity left after placement
    let frac = post_residual as f64 / cap_f;

    // Harmonic class of the post residual: which "slot band" it lands in.
    // Bands: 0 (perfect/very tight), 1 (small), 2 (medium), 3 (large).
    let band = match post_residual {
        0 => 0u8,
        r if r <= bin_capacity / 10 => 0,
        r if r <= bin_capacity / 4 => 1,
        r if r <= bin_capacity / 2 => 2,
        _ => 3,
    };
    score += match band {
        0 => -25.0,          // near-perfect fill, strongly reward
        1 => -8.0,           // decent fill
        2 => 6.0,            // mediocre
        _ => 15.0,           // wasteful large residual
    };

    // Modulo-style coupling: residuals that are "harmonics" of common item
    // sizes (multiples of 10, 20, 25) are more likely to be reusable.
    let harmonic = (post_residual % 10 == 0) || (post_residual % 25 == 0);
    if harmonic {
        score -= 4.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well the next item uses the leftover
            let fill_next = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * fill_next;
            // extra bonus for harmonic pairing (sums to capacity)
            if item_size + next_item_size == bin_capacity {
                score -= 20.0;
            }
        } else {
            // next item cannot use this leftover: penalize by wasted fraction
            score += 8.0 * frac;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    // Prefer it only when the item is large and no good fit exists,
    // otherwise discourage (score = capacity residual is naturally high,
    // but make it explicitly worse unless item is big).
    if bin_residual == bin_capacity {
        let big = item_size as f64 / cap_f;
        if big >= 0.8 {
            score -= 5.0; // large item: fresh bin is fine
        } else {
            score += 20.0 * (1.0 - big); // small item: strongly prefer existing bins
        }
    }

    // Mild preference for keeping number of open bins low early in stream
    if open_bins_count > 3 && band <= 1 {
        score -= 2.0;
    }

    // Slight tightening pressure as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * frac * (1.0 - progress);

    // Tie-break toward bins near mean residual (balanced packing)
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps are nearly unusable
    // (min item size is small, but gaps <= 12 waste capacity long-term).
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 8.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Tight fit reward: post_residual < next_item_size means gap can't
    // serve the upcoming item either.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.2 * post_residual as f64;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // existing bins fit fine.
    if bin_residual < bin_capacity {
        score += 0.35 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins whose residual is already below the mean (consolidate
    // fullness), penalize chipping away at large-residual bins.
    score += 0.4 * (mean_residual - post_residual as f64);

    // Mild stream-position damping of new-bin attractiveness.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward heavily (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize leaving awkward leftovers.
            let waste = post_residual as f64;
            score += 0.05 * waste * waste;
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global state: with many open bins, prefer consolidating into existing
    // bins (penalize opening new ones); with few bins, be more permissive.
    let pressure = (open_bins_count as f64) / ((open_bins_count as f64) + 4.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when there is already pressure
        // and existing fitting bins are available.
        score += 12.0 * pressure;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // Early in the stream, opening a fresh bin is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    } else {
        // Existing bin: small reward for using already-open bins.
        score -= 3.0 * pressure;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "junk" bin; using it up is good. If far above mean, be careful.
    let residual_f = bin_residual as f64;
    let dev = (residual_f - mean_residual) / (bin_capacity as f64);
    score += 10.0 * dev;

    // Time horizon: late in the stream, avoid creating any new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * progress * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Mild preference for filling larger residuals with larger items
    // (avoid putting small items into big holes when alternatives exist).
    let item_f = item_size as f64;
    score -= 0.02 * item_f * (residual_f / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.6 * progress * fit_norm * fit_norm);

    // Smooth penalty when the leftover is too small to be useful later.
    let small = 1.0 - fit_norm;
    score += 12.0 * small * small * small * (1.0 - progress);

    // Reward tight fits smoothly via cubic of normalized fill.
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill * fill * fill * (0.5 + 0.5 * progress);

    // Lookahead: bonus if next item fits the post residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (pr - nxt).max(0.0) / cap;
        let compat = (1.0 - (pr / nxt.max(1.0))).abs().min(1.0);
        score -= 8.0 * fits * (1.0 - compat) * (1.0 - progress);
    }

    // Last-chance bin: smooth reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - fit_norm);
    }

    // Mild pressure from many open bins, scaled by progress.
    score += 0.05 * open_bins_count as f64 * progress * fit_norm;

    // Deviation from mean residual, polynomial smoothing.
    let dev = (pr as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: keep it neutral-ish but slightly penalized early,
    // more attractive late via smooth progress coupling.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: absolute reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the resulting gap: residuals divisible by common
    // item sizes (10, 20, 25, 50) are reusable, others are dead space.
    let mut harmony = 0.0;
    for &d in &[10u32, 20, 25, 50] {
        if post_residual % d == 0 && post_residual > 0 {
            harmony += 30.0 + d as f64;
        }
    }
    score -= harmony;

    // Penalize awkward gaps that no plausible item (1..=80) can use well:
    // gaps in (80, 100) exclusive of exact multiples are nearly dead.
    if post_residual > 80 && post_residual < 100 {
        score += 40.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly
    // or nearly (k=2 chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 80.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: mild penalty scaled by
            // how wasteful the leftover is.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate (empty bin): penalize so it is chosen only when
    // no open bin offers a decent fit. Scale with stream progress and
    // existing open-bin count (bin consolidation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 + 10.0 * open_bins_count as f64 + 50.0 * progress;
        // But if the item is large relative to mean residual, opening a
        // fresh bin may be wise: reduce the penalty.
        if item_size as f64 > mean_residual {
            score -= 60.0;
        }
    }

    // Mild preference for bins whose residual is close to the item
    // (tight packing), expressed via capacity fraction.
    let fill_fraction = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_fraction;

    // Penalize bins far below mean residual (they are already crowded,
    // keep balanced bins usable).
    if (bin_residual as f64 - mean_residual).abs() > 0.0 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev; // lower residual (crowded bin) => lower score => favored
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: a tiny leftover gap that no item (>=1) can
    // use efficiently is worse than a large residual. Penalize residuals in
    // the "dead zone" (1..=15) quadratically.
    if post_residual > 0 && post_residual <= 15 {
        score += 40.0 * (16.0 - post_residual as f64);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 15 {
            score -= 15.0;
        }
        // If next item cannot fit here anyway, slight bonus for leaving big space.
        if next_item_size > post_residual {
            score -= 5.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading out.
    score += 0.35 * open_bins_count as f64;

    // Prefer bins with residual close to the mean (keeps bin sizes balanced).
    score += 0.10 * ((bin_residual as f64 - mean_residual).abs());

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: opening a new bin should only win when no open bin
    // offers a decent fit. Penalize the fresh bin moderately, and more when
    // open-bin pressure is low or the item is small.
    if bin_residual == bin_capacity {
        let waste_penalty = (bin_capacity - item_size) as f64;
        score += 25.0 + 0.6 * waste_penalty + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size && next_item_size > 50 {
            score -= 30.0; // big item coming: a fresh bin may be worth it
        }
    }

    // Early in the stream, be slightly more willing to keep bins tidy.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can exactly/comfortably host the NEXT item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: the bigger the slack beyond next item, the more wasted space.
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 60.0 + 0.5 * next_item_size as f64 - 0.3 * chain_slack;
            // Perfect chain (post_residual == next_item_size) is ideal.
            if post_residual == next_item_size {
                score -= 40.0;
            }
        } else {
            // Chain broken: penalize proportionally to how far the next item misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.4 * miss;
        }
    } else {
        // Last item: prefer tightest fit only.
        score += 0.0;
    }

    // Reward tight fits relative to residual (waste minimization).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness;

    // Penalize creating dead space that no typical item (10..80) can use,
    // but keep usable small slacks cheap.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable dead space
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Compare against mean residual: bins already below mean residual are
    // "tight" bins; prefer filling them further.
    score -= 0.2 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: neutral base, but allow opening a new bin
    // only when the item would leave a huge awkward residual in existing bins.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; lookahead chain fit still applies above.
        score += 55.0;
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items as f64;
        score += 30.0 * progress;
        // If many bins already fit the item, opening a new one is wasteful.
        score += 8.0 * (fitting_bins_count as f64);
    } else {
        // Mild preference to reuse existing bins as stream progresses.
        let progress = step_index as f64 / total_items as f64;
        score -= 10.0 * progress;
    }

    // Prefer bins with fewer open competitors (consolidation).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Lookahead: reward if next item fits into post_residual (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward if post_residual exactly accommodates next item.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Penalize leaving dead space that the next item cannot use.
        let waste = post_residual.min(next_item_size.saturating_sub(1)) as f64;
        score += 0.15 * waste;
    }

    // Last chance: strongly favor the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent fits exist; allow it only for large items
    // or when mean residual across open bins is small (fragmented state).
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        let fragmentation = 1.0 - (mean_r / bin_capacity as f64);
        score += 25.0 + 20.0 * fragmentation;
        // Late in the stream, opening new bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
        // Large items are fine to start fresh bins.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild penalty for bins whose residual deviates far from mean (keep diversity).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer filling nearly-full bins to close them out.
    if post_residual < 10 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    // Base: quadratic penalty on post residual (dead space), modulated by progress
    let mut score = pr * (1.0 + 1.5 * norm_pr * (0.5 + progress));
    // Smooth non-linear coupling: residual^2 scaled by stream progress
    score += norm_pr * norm_pr * cap * (0.3 + 0.7 * progress * progress);
    // Reward tight fits with a smooth saturating term
    let tightness = 1.0 - norm_pr;
    score -= norm_item * tightness * tightness * 20.0;
    // Penalize bins that leave residual unusable for the lookahead item (smooth gating)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = norm_pr - nx;
        let gate = 1.0 / (1.0 + (-gap * 12.0).exp());
        score += gate * (1.0 - (-gap * gap * 30.0).exp()) * 8.0;
    }
    // Last-chance bonus: smooth function of fitting bins count
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= scarcity * 6.0 * (1.0 - progress * 0.5);
    // Mild penalty for spreading across many open bins when residuals are large
    score += open_bins_count as f64 * 0.05 * mean_residual / cap;
    // Small smooth preference to consolidate early vs late
    score += progress * norm_pr * 3.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose leftover falls into
    // "useful" residue classes (multiples of small denominators) are favored,
    // since future items are more likely to fill them exactly.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Class A: residual divisible by 5 or 10 -> highly reusable.
    if pr == 0 {
        score -= 30.0; // perfect closure, best possible outcome
    } else if pr % 10 == 0 {
        score -= 12.0;
    } else if pr % 5 == 0 {
        score -= 6.0;
    }

    // Integer-division thresholds on post_residual: tiny leftovers are dead space.
    if pr > 0 && pr < 10 {
        score += 18.0; // unusable sliver
    } else if pr < 20 {
        score += 6.0;
    } else if pr <= 40 {
        score -= 4.0; // sweet zone: fits common small items
    }

    // Fractional capacity coupling: how full the bin becomes.
    let fill = 1.0 - prf / cap;
    score -= 8.0 * fill * fill; // reward high fill ratio quadratically

    // Lookahead harmonic coupling: does next_item_size divide into post_residual?
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= pr {
            if pr % n == 0 {
                score -= 10.0; // next item exactly consumes the leftover
            } else {
                score -= 3.0; // next item at least fits
            }
        } else {
            score += 5.0; // lookahead item cannot use this bin's leftover
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins
    // are all poor fits; scale with stream progress and open bin count.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.02 * open_bins_count as f64
            + 5.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild tie-break toward bins below mean residual (tighter bins first).
    score += 0.05 * (mean_residual - prf);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste, but residuals that can't fit a "typical" mid-size item
    // (say < 10) are especially toxic — penalize them quadratically.
    if post_residual < 10 {
        score += (10.0 - post_residual as f64) * (10.0 - post_residual as f64) * 1.5;
    }
    // Dead space that cannot host the lookahead item is worse than useless.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 12.0;
    }

    // Reward tight fits (post residual near zero).
    score -= (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6) * 8.0;

    // Perfect or near-perfect fill gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize new-bin candidates.
    score += open_bins_count as f64 * 0.8;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when current bins are crowded
        // or this bin would be a dead-end otherwise.
        score += 15.0 + mean_residual * 0.15;
        // Early in the stream, opening a fresh bin is cheaper.
        score -= (1.0 - step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding an otherwise forced new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor)
    // beyond raw post_residual ordering.
    score -= (bin_residual as f64 - item_size as f64).abs().recip() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely desirable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Two-step lookahead: if the next item fits exactly in the post residual,
    // this is an ideal pairing.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to how snugly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 - slack.min(100.0);
        } else {
            // Next item won't fit in leftover: penalize tiny dead space
            // that is smaller than any plausible item.
            if post_residual < 10 {
                score += 50.0;
            }
        }
    }

    // Penalize leaving residual smaller than the minimum item size (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Mild preference for using existing bins over opening new ones,
    // scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 40.0 + 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post-residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: residual too small for any future item (min size 1..100, be conservative at 10).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: reward bins where the next item also fits the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the fit here is bad (large post_residual) or bins are few.
    if bin_residual == bin_capacity {
        // Penalize new bins generally, scaled by how much room remains elsewhere.
        let global_room = mean_residual * (open_bins_count as f64);
        score += 15.0 + 0.05 * global_room;
        // Early in the stream, opening bins is cheaper (need parallel bins).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If the item is huge, a fresh bin guarantees a good fit.
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    // Prefer filling bins that are already below the mean residual (balance toward fullness).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 5.0 * (mean_residual - resid_f) / (bin_capacity as f64);
    } else {
        score += 3.0 * (resid_f - mean_residual) / (bin_capacity as f64);
    }

    // Mild penalty for very large item into a nearly-full bin creating fragmentation.
    let frag = (post_residual as f64) / (bin_capacity as f64);
    score += 8.0 * frag * (1.0 - frag) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;

    // Smooth polynomial coupling: post_residual penalized more harshly as stream progresses
    let base = post * (1.0 + 1.5 * progress * post_norm);

    // Dead-space penalty: quadratic in post_residual relative to capacity
    let dead = 40.0 * post_norm * post_norm * (0.5 + progress);

    // Reward tight fits (small post_residual) with a saturating non-linear term
    let tight = -30.0 * (-4.0 * post_norm).exp();

    // Last-chance bonus: strongly prefer using the only fitting bin
    let last_chance = if fitting_bins_count == 1 { -25.0 } else { 0.0 };

    // Lookahead: reward bins whose post_residual can hold the next item
    let lookahead = if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx { -12.0 * (1.0 - (post - nx) / cap) } else { 6.0 * (nx - post) / cap }
    } else { 0.0 };

    // Mild preference for bins deviating below the mean residual (consolidation)
    let consolidation = -0.3 * (mean_residual - post);

    // Slight new-bin aversion that decays with progress (late stream: reuse more)
    let new_bin_bias = if bin_residual == bin_capacity {
        15.0 * (1.0 - 0.5 * progress) + 0.05 * open_bins_count as f64
    } else { 0.0 };

    base + dead + tight + last_chance + lookahead + consolidation + new_bin_bias
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fractions (eighths of C=100)
    let item_class = item_size / 13; // coarse harmonic bucket
    let post_class = post_residual / 13;

    // Reward tight fits: small post_residual is good
    score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);

    // Penalize "dead space": post_residual too small for any plausible future item (1..=100)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Harmonic pairing: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // perfect complement (post_residual == next_item_size)
        if next_item_size == post_residual {
            score -= 35.0;
        }
    }
    // next item nearly fits (within small slack) -> mild penalty for wasting the slot
    if next_item_size > post_residual && next_item_size - post_residual <= 10 && post_residual > 0 {
        score += 8.0;
    }

    // Modulo arithmetic on post_residual: residuals that are "nice" class sizes
    // (multiples of ~25 or ~33, i.e., 1/4 or 1/3 of capacity) are reusable
    if post_residual % 25 == 0 || post_residual % 33 == 0 {
        score -= 6.0;
    }
    // Awkward primes-ish residuals are less reusable
    let awkward = |r: u32| -> bool { r % 7 != 0 && r % 11 != 0 && r % 13 != 0 && r % 25 != 0 && r % 33 != 0 };
    if post_residual > 0 && awkward(post_residual) {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    }
    // Many alternatives -> this bin must earn its place
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Prefer filling bins below mean residual (keeps bins balanced, closes bins sooner)
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Class coupling: large items into large-residual bins
    let item_big = item_class >= 5; // item_size >= 65
    let bin_big = (bin_residual as f64 / bin_capacity as f64) >= 0.5;
    if item_big && bin_big {
        score -= 12.0;
    }
    if !item_big && bin_big && bin_residual > 70 {
        // don't waste a mostly-empty bin on a tiny item unless nothing better
        score += 10.0;
    }

    // Early stream: be slightly more liberal opening bins to build a good pool
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline cost, cheaper early, expensive late
        score = 55.0 + 40.0 * progress;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            // next item can't share this fresh bin anyway; neutral
            score -= 5.0;
        }
        if fitting_bins_count == 1 {
            score += 50.0; // never open new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host any
    // plausible future item (below the minimum size band) are pure waste.
    let dead_zone = 20.0; // items can be as small as 1..10; residuals below ~10 are dead
    if (post_residual as f64) < dead_zone {
        // Heavy penalty proportional to unusable gap depth.
        score += (dead_zone - post_residual as f64) * 4.0;
    }

    // Tight-fit reward: the smaller the waste relative to the item, the better.
    if item_size > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Next-item lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin; if post residual can't host the next item while
    // another placement could, mild penalty.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: penalize creating new bins when many are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 5.0 * open_bins_count as f64;
        // But if mean residual across open bins is tiny, opening fresh is fine.
        if mean_residual < 15.0 {
            score -= 25.0;
        }
    }

    // Mild preference to fill bins with large residuals early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_residual as f64 / bin_capacity as f64) * (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Post residual can still fit next item: strong bonus proportional to tightness.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack * 0.5;
    }

    // Penalize dead space too small for the next item (wasted gap).
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 150.0 * (10.0 - dead) / 10.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Tight fits are good: bonus when item nearly fills the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 100.0 * fill;

    // Compare against mean residual: prefer bins that reduce imbalance.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Penalize leaving tiny unusable fragments regardless of lookahead.
    if post_residual > 0 && post_residual < 5 {
        score += 250.0;
    }

    // New-bin candidate: make it unattractive unless it beats all open bins
    // (empty bin leaves post_residual = capacity - item, usually large).
    if bin_residual == bin_capacity {
        score += 400.0 + open_bins_count as f64 * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal waste, with a non-linear penalty on tiny dead space
    // (residuals below the smallest item size are pure waste).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Reward tight fits (high fill ratio of the bin after placement).
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * fill * fill;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly
    // or nearly; penalize bins that will strand space the next item cannot use.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // New-bin candidate logic: an empty bin is attractive when open bins have
    // high mean residual (fragmented state) or late in the stream.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 10.0 + 25.0 * fragmentation;
        if fitting_bins_count <= 2 {
            score += 15.0; // don't hoard bins when a decent fit exists
        }
    }

    // Time horizon: early in the stream, keep bins flexible (penalize very
    // small post_residual to preserve future options); late, pack greedily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.5 {
        score += 6.0 * (1.0 - progress * 2.0) * (1.0 - post_residual as f64 / bin_capacity as f64);
    } else {
        score -= 5.0 * progress * fill;
    }

    // Mild penalty for spreading across many open bins when residuals are low.
    score += 0.05 * open_bins_count as f64 * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Early stream: tolerate larger residuals less; late stream: tighten packing
    score += (1.0 + 2.0 * p2 + 3.0 * p3) * norm_pr * 20.0;

    // Reward tight fits smoothly (quartic decay of residual)
    score -= 15.0 * (1.0 - norm_pr).powi(4);

    // Lookahead coupling: penalize residual that neither wastes nor helps next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let diff = pr - ni;
        // Perfect follow-up fit: strongly reward
        let match_term = 1.0 - (diff / cap).abs();
        score -= 12.0 * match_term.max(0.0).powi(2);
        // Residual too small for next item: smooth dead-space penalty
        if diff < 0.0 {
            score += (-diff) * (0.5 + progress);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 + 6.0 * progress;
    }

    // Mean-residual coupling: prefer bins whose residual is close to mean (balance)
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev * (1.0 + p2);

    // Open-bin pressure: with many open bins, prefer filling existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - norm_pr);

    // New-bin candidate: smooth sigmoid gate on openness
    let gate = 1.0 / (1.0 + (-(norm_pr - 0.5) * 8.0).exp());
    score += gate * 30.0 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: which capacity fraction band does post_residual fall into?
    // Classes (integer division thresholds on capacity): [0..9]=dead, [10..24]=tiny, [25..49]=half-ish,
    // [50..74]=large, [75..99]=near-empty.
    let class = match post_residual / 10 {
        0 => 0.0,           // 0..9 : nearly perfect fit, reward heavily
        1..=2 => 1.0,       // 10..24: dead space, only small items (>=10) fit
        3..=4 => 2.0,       // 25..49: medium dead space
        5..=7 => 3.0,       // 50..74: still useful
        _ => 4.0,           // 75..: very usable
    };

    // Reward tight fits (low class) strongly, penalize mid classes.
    score -= (bin_capacity as f64 - class * 25.0) * 0.9;

    // Dead-space penalty: leftover that no future item (min size 1..10 unknown, assume >=10 band)
    // can fill. If post_residual is in (0, 10) it's perfect; if it's just above a class boundary
    // it's wasted. Penalize residual that is small but non-zero relative to min plausible item.
    if post_residual > 0 && post_residual < 10 {
        score -= 40.0; // perfect fill
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0; // awkward leftover
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: this bin remains useful for the next item.
            score -= 15.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item won't fit here; mildly penalize if we leave a large unusable gap.
            let gap = next_item_size - post_residual;
            if gap <= 15 {
                score += gap as f64 * 0.8; // near-miss: painful near-fit waste
            } else {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin (bin_residual == bin_capacity) should only win
    // when no open bin offers a decent fit. Make the fresh bin moderately attractive by default
    // but let tight fits of existing bins beat it.
    if bin_residual == bin_capacity {
        score = (bin_capacity - post_residual) as f64; // == item_size
        score += 55.0; // default cost of opening a new bin
        // Cheaper to open bins early in the stream when few bins are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
        // If nothing else fits, opening is necessary: drop the penalty.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // If many bins are open with high mean residual, prefer consolidation instead.
        if open_bins_count > 3 && mean_residual > item_size as f64 {
            score += 15.0;
        }
    }

    // Mild consolidation pressure: bins with residual close to mean_residual are "typical";
    // prefer filling below-average-residual bins to keep a spread of large residuals.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.05;

    // Harmonic modulo flavor: reward when item harmonizes with bin residual
    // (residual divisible into item-sized chunks).
    if bin_residual % item_size.max(1) == 0 && bin_residual > item_size {
        score -= 6.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0; // leftover aligns with the classic size-10 class
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible follow-up items are pure waste. Penalize them quadratically.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 12.0;
    }

    // Penalize "awkward" residuals that can only host very large items poorly:
    // gap in [1..=15] is dead, [16..=30] is semi-dead.
    if post_residual >= 1 && post_residual <= 15 {
        score += 25.0;
    } else if post_residual > 15 && post_residual <= 30 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few open
    // bins, opening a new one is cheap so the empty-bin candidate stays viable.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln() * 6.0 * (0.5 + 0.5 * progress);

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward heavily; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 10.0;
        }
    }

    // Mean-residual coupling: prefer bins close to the mean residual
    // (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate calibration: an empty bin gets a moderate base cost so
    // it only wins when existing bins would create severe dead space.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to how close we were.
        let gap = (next_item_size - post_residual) as f64;
        score += 10.0 + 0.3 * gap;
    }

    // Penalize creating residual far below the mean (wasted dead space).
    if (post_residual as f64) < mean_residual {
        score += 0.5 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Early in stream: keep bins tight; late: consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    // New-bin candidate should only win when nothing fits well:
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream (time horizon).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness reward: the smaller the post_residual, the better (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * bin_capacity as f64 * 0.1;

    // Penalize large leftover dead space quadratically.
    score += 0.02 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 6.0 * slack_fit;
        } else {
            // Dead space relative to the next item: penalize.
            let waste = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 4.0 * waste * waste * 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global state: when many bins are open with high mean residual,
    // prefer filling existing bins over opening new ones.
    if open_bins_count > 1 {
        let crowding = (open_bins_count as f64).ln();
        score -= 1.5 * crowding * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate handling: an empty bin is a fresh start; make it
    // attractive only when existing bins would leave big unusable gaps,
    // or early in the stream when we have room to explore.
    if bin_residual == bin_capacity {
        let gap_penalty = if next_item_size > 0 && post_residual < next_item_size { 8.0 } else { 0.0 };
        score += 5.0 + 3.0 * progress - gap_penalty;
        // Discard new-bin opening late in the stream unless nothing fits well.
        if fitting_bins_count > 0 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Mild time coupling: early on, slightly favor consolidation; later,
    // accept looser fits to avoid opening bins near the end.
    score -= 2.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, slightly compressed non-linearly
    let mut score = pr - 12.0 * (1.0 - pr_norm).powi(2);

    // Polynomial coupling of residual with stream progress
    let prog2 = progress * progress;
    score += 20.0 * pr_norm * pr_norm * (0.5 + prog2);
    score -= 25.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - progress);

    // Favor tight fits more as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 30.0 * tightness.powi(3) * (1.0 + progress);

    // Lookahead: reward residual that fits next item
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 15.0 * fits_next * (1.0 - progress);
        let waste = (pr - next_item_size as f64).max(0.0) / cap;
        score += 10.0 * waste * waste;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 * (1.0 - progress);
    }

    // Penalize crowding when many bins open with large mean residual
    score += 3.0 * (open_bins_count as f64).ln() * pr_norm;
    score += 5.0 * (mean_residual / cap - pr_norm).abs();

    // New-bin candidate handling: make empty bin attractive only when fits are poor
    if bin_residual == bin_capacity {
        score += 8.0 - 10.0 * tightness * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "useless"
    // (very small but nonzero) get penalized; perfect zero residual rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, best outcome
    } else if pr < 10 {
        score += 45.0; // dead space: too small for any item
    } else if pr >= 10 && pr < 20 {
        score += 15.0; // only fits tiny items
    }

    // Modulo-class logic on post_residual against capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * bin_capacity / 4;
    let residue_class = (pr as i64) % (half as i64).max(1);
    let _ = residue_class;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            // Reward tight next-fit, penalize large leftover after next item
            score -= 25.0 * (1.0 - slack / cap);
            if slack < 10.0 {
                score += 20.0; // would create dead space after next item
            }
        } else {
            score += 10.0; // next item can't use this residual
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap; // high mean residual = open bins have room
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        // Penalize new bins unless open bins are nearly full / few fit options.
        score += 70.0 + 40.0 * crowding - 30.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 55.0; // no good alternative, new bin is reasonable
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 && mean_residual < (next_item_size as f64) {
            score -= 45.0; // open bins can't hold next item; fresh bin helps
        }
    }

    // Prefer filling bins that are already substantially used (harmonic tiers).
    let used_frac = (bin_capacity - bin_residual) as f64 / cap;
    score -= 20.0 * used_frac * used_frac;

    // Slight penalty for proliferating bins when residual space is abundant.
    if open_bins_count > 4 && mean_residual > 0.5 * cap && bin_residual != bin_capacity {
        score += 8.0;
    }

    // Integer-division threshold: residual divisible by common item sizes is valuable.
    if pr > 0 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0) {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (too small for the smallest plausible future item) are heavily penalized.
    let dead_zone: f64 = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 8.0;
    }

    // Perfect fit is a jackpot.
    if post_residual == 0 {
        score -= 30.0;
    } else {
        // Reward tight fits proportionally to fill ratio.
        let fill = item_size as f64 / bin_capacity as f64;
        score -= fill * 25.0;
    }

    // Prefer bins whose residual is close to the item (waste minimization).
    let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += waste * 20.0;

    // Open-bin pressure: with many open bins, avoid fragmenting further;
    // with few bins, prefer spreading load to keep future options open.
    let pressure = (open_bins_count as f64 / (total_items.max(1) as f64)).min(1.0);
    score += pressure * 6.0;
    if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it over opening a new bin.
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post residual, this placement
    // sets up a chain — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
        // Next item can't use the leftover: mild penalty scaled by gap size.
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    // (large mean residual spread / high dead-space risk).
    if bin_residual == bin_capacity {
        let poor_fit = mean_residual - item_size as f64;
        if poor_fit < 0.0 {
            // Existing bins are tighter than needed elsewhere; new bin is fine.
            score -= 10.0;
        } else {
            // Opening a new bin wastes the mean residual of open bins.
            score += mean_residual * 0.35 + 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits in the remaining space: reward proportional fit tightness.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = next_item_size as f64 / post_residual as f64;
        score -= 50.0 * tightness;
    }
    // Next item does NOT fit: penalize creating dead space, worse when residual is tiny.
    else if next_item_size > 0 {
        let dead = post_residual as f64;
        score += 30.0 * (1.0 - dead / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize unless open bins are nearly full / crowded.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64;
        let fullness = mean_residual / bin_capacity as f64;
        score += 120.0 - 15.0 * crowded - 60.0 * fullness;
    }

    // Prefer bins tighter than the mean residual (good consolidation).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Late in stream: be more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins closed exactly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness reward: relative waste of the residual capacity.
        let tight = (post_residual as f64) / (bin_capacity as f64);
        score -= (1.0 - tight) * 40.0;

        // Dead-space penalty: residuals too small for the smallest plausible item.
        if post_residual < 10 {
            score += 60.0 * (1.0 - post_residual as f64 / 10.0);
        }
    }

    // Lookahead: bonus if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: mild penalty proportional to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 20.0 * (gap / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere else or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: grows as the stream progresses (commitment).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_cost = 250.0 + 150.0 * progress;

        // If the mean residual across open bins is small (bins nearly full),
        // opening a new bin becomes more acceptable.
        new_bin_cost -= 100.0 * (1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0));

        // Many open bins: slight extra reluctance to add more.
        new_bin_cost += 5.0 * (open_bins_count as f64).ln().max(0.0);

        score = new_bin_cost;

        // Perfect-fit-style lookahead for a fresh bin: item + next item fill it.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 400.0;
        }
    }

    // Mild global pressure: prefer filling existing bins when many are open.
    if bin_residual != bin_capacity {
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_it = it / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: waste after placement, mildly discounted early in the stream.
    let mut score = pr * (0.9 + 0.6 * progress);

    // Smooth non-linear coupling: reward tight fits quadratically.
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * norm_it;

    // Lookahead: residual that exactly hosts the next item is valuable.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 12.0 * (-gap / 15.0) * (1.0 - progress);
        // Penalize residuals just below the next item size (dead space trap).
        score += 8.0 * (next_item_size as f64 - pr).max(0.0) / cap;
    }

    // Polynomial interaction of residual with stream progress.
    score += 20.0 * norm_pr * norm_pr * (0.5 + 0.5 * progress);

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize proportionally to how many bins are open,
    // and to unused capacity it locks in; smoothed, no hard threshold.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64 + 10.0 * norm_pr * (1.0 - progress);
    }

    // Slight preference for bins below mean residual (balance load smoothly).
    score += 2.0 * ((pr - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by common item
    // granularities (10/20/25/50) are more reusable than odd residues.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit
    } else if pr % 50 == 0 {
        -25.0
    } else if pr % 25 == 0 {
        -18.0
    } else if pr % 20 == 0 {
        -15.0
    } else if pr % 10 == 0 {
        -10.0
    } else if pr % 5 == 0 {
        -3.0
    } else {
        8.0 // odd residue: dead space risk
    };
    score += class_bonus;

    // Does the lookahead item fit exactly into the post-residual?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == pr {
            score -= 45.0; // chainable perfect fit
        } else if next_item_size <= pr {
            score -= 12.0 * (nx / cap);
        } else {
            score += 6.0; // lookahead cannot use this bin's remainder
        }
        // Harmonic pairing: item + next fills bin exactly (mod class match)
        if item_size + next_item_size == bin_residual {
            score -= 30.0;
        }
    }

    // Integer-division thresholds on post_residual: small unusable slivers
    let sliver = (pr / 10) as f64; // number of full 10-blocks
    if sliver < 1.0 && pr > 0 {
        score += 10.0; // <10 residual is nearly dead space
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer opening fresh bin only when no open bin has
    // a decent harmonic residual class and mean residual is fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 55.0 + fragmentation * 0.3;
        if open_bins_count == 0 {
            score = -100.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 25.0; // no open bin likely fits next item either
        }
    }

    // Progress-based mild tightening: later in stream, value tight fits more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= class_bonus * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 25 {
        score += 15.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward tight fits strongly.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space is worse if it cannot fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when existing
    // bins would leave bad dead space or no bin fits well.
    if bin_residual == bin_capacity {
        let bad_fit = tightness < 0.5 || (post_residual > 0 && post_residual < 10);
        if bad_fit {
            score -= 15.0;
        } else {
            score += 30.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Slight preference to keep residuals near the mean (balance load).
    score += 0.1 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: strongly favor bins where the item leaves almost nothing.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let nx = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 400.0; // exact 2-step match: chain placement
        } else if post_residual >= next_item_size {
            let slack = pr - nx;
            // small slack after chaining is great; large slack wastes space
            score -= 200.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // next item cannot chain into this bin: mild penalty proportional to gap
            score += 0.5 * (nx - pr);
        }
        // Coupling with mean residual: a bin whose post_residual is far below the
        // mean residual is a tight fit relative to the fleet — reward it.
        score -= 0.3 * (mean_residual - pr);
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is badly fragmented.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 + 50.0;
        // Opening a new bin is attractive only if no open bin fits well
        // (handled by the last-chance bonus above) and fleet is already fragmented.
        if open_bins_count > 0 && fitting_bins_count > 1 {
            score += 100.0;
        }
    } else {
        // Penalize leaving large unusable dead space relative to typical next item sizes.
        if post_residual > 0 && post_residual < 10 {
            score += 0.0; // tiny residual is fine (dead space negligible)
        } else {
            score += 0.1 * (post_residual as f64).powf(1.2);
        }
    }

    // Slight stream-position adaptation: early on, be more open to new bins (exploration).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when the item
    // fits poorly everywhere else (large post_residual in any existing bin is fine,
    // but a near-perfect existing fit should win).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 12.0;
        // Cheaper to open a new bin early when few bins are open.
        score -= 6.0 / (1.0 + open_bins_count as f64);
        // If the item would leave a large residual in this new bin, penalize less
        // (fresh bin has full flexibility for future items).
        score -= 4.0;
        // If no existing bin fits well (fitting bins scarce relative to open bins),
        // opening a new bin becomes more attractive.
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else if (fitting_bins_count as f64) < 0.5 * open_bins_count.max(1) as f64 {
            score -= 8.0;
        }
    } else {
        // Prefer bins whose residual is below the mean (consolidate emptier space).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; slight penalty if post_residual is large
            // enough that it may become stranded.
            if post_residual >= 10 && next_item_size > post_residual {
                score += 3.0;
            }
        }
    }

    // Time horizon: later in the stream, be greedier (avoid leaving scattered residuals).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear curvature on normalized residual.
    let mut score = pr as f64 * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // later in the stream, compact residuals matter more (dead space penalty grows).
    let coupling = 3.0 * progress * (1.0 - progress) + 2.0 * progress * progress;
    score += coupling * pr * (pr / 100.0);

    // Last-chance bin: strongly reward using it.
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead: reward leaving room for the next item (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score += 0.25 * gap * gap / cap;
        if pr >= nx {
            score -= 0.35 * nx * (1.0 - progress);
        }
    } else {
        // Last item: minimize leftover aggressively.
        score += 0.5 * pr;
    }

    // Prefer bins with residual close to the mean (balance), smooth penalty.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Mild penalty when many bins are open (encourage consolidation early).
    score += 0.02 * open_bins_count as f64 * norm_pr * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 / mod 5
    let r10 = (post_residual % 10) as f64;
    let r5 = (post_residual % 5) as f64;
    // Penalize awkward residues (dead space unlikely to be filled)
    if post_residual > 0 {
        score += r10 * 0.6 + r5 * 0.4;
    }

    // Integer-division thresholds: post_residual in "harmonic" bands
    let band = post_residual / 10;
    // Reward near-full bins (small post_residual) superlinearly
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 25.0 - band as f64;
    } else if post_residual <= 30 {
        score -= 8.0;
    }

    // Big dead space penalty, stronger if next item cannot use it
    if next_item_size > 0 {
        if post_residual > 0 && next_item_size > post_residual {
            score += 12.0 + (post_residual as f64) * 0.25;
        }
        // Reward leaving space that exactly fits the next item
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 15.0;
        }
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Coupling with mean residual: prefer bins tighter than average
    let frac = bin_residual as f64 / cap;
    score += (frac - 0.5) * 10.0 - (mean_residual - post_residual as f64) * 0.3;

    // Progress-dependent tightening: late in stream, pack tighter
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    // New-bin candidate: penalize opening a new bin unless all fits are bad
    if bin_residual == bin_capacity {
        let bad_fit = if fitting_bins_count == 0 { 0.0 } else {
            // how poorly does the best existing fit look? approximate via mean residual
            (mean_residual - item_size as f64).abs()
        };
        score = cap * 0.9 + bad_fit * 0.1 - if fitting_bins_count == 0 { 1000.0 } else { 0.0 };
        // allow new bin late in stream when item is large
        if item_size > 60 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly useless.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 14.0; // small gaps heavily penalized
    }
    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward using a bin whose residual was already fragmented/low-value,
    // i.e. prefer packing into bins with small residuals (best-fit core).
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.5;

    // Pressure from open bin count: with many open bins, prefer consolidating
    // into existing bins rather than spreading.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 90.0;
    }
    // Penalize if post_residual cannot hold the next item and is small (dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 && post_residual < 25 {
        score += 30.0;
    }

    // New-bin candidate handling: empty bin gets a baseline score that makes it
    // attractive only when the fit into open bins would be poor.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55
            + open_bins_count as f64 * -0.2
            + (item_size as f64 / bin_capacity as f64) * 30.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: must open a new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // large current item suggests fresh bin is fine
        }
    }

    // Mild progression term: late in the stream, be slightly more conservative
    // about opening bins (consolidate).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // Prefer bins whose residual is close to the mean (balanced usage) slightly.
    score -= ((bin_residual as f64 - mean_residual).abs()) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        // Perfect match: next item exactly fills the post residual -> strongly reward.
        let exact = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += exact * 0.9;

        // Perfect fill bonus (next item exactly consumes the leftover space).
        if post_residual == next_item_size {
            score -= 40.0;
        }

        // If next item fits into the post residual, mild reward scaled by tightness.
        if next_item_size <= post_residual {
            let tight = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 12.0 * (1.0 - tight);
        } else {
            // Next item cannot follow here: penalize proportionally to wasted potential.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.35 * overflow.min(60.0);
        }
    } else {
        // Last item: any residual is dead space, weight it fully.
        score += post_residual as f64 * 0.5;
    }

    // --- Relative-to-mean residual shaping ---
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        // Prefer leaving residuals near the fleet mean (keeps future pairing options).
        let dev = (pr - mean_residual).abs();
        score += 0.15 * dev;
        // Small residuals relative to mean are precious; reward tightening below mean.
        if pr < mean_residual {
            score -= 0.25 * (mean_residual - pr).min(50.0);
        }
    }

    // --- Last-chance bin bonus ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // If this is the only bin that fits and a new bin would otherwise be needed,
        // strongly favor using it (avoids bin proliferation).
        score -= 30.0;
        // Extra reward if the fit is tight.
        score -= 0.3 * (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive for big items or when all open bins
        // would leave badly fragmented space.
        let frag_penalty = if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            20.0
        } else {
            0.0
        };
        // Base new-bin cost: discourage opening unless existing fits are poor.
        score += 25.0 - frag_penalty;
        // Large items justify a fresh bin more readily.
        score -= 0.2 * item_size as f64;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // --- Tightness reward for the current placement ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio;

    // Small tie-breaker favoring bins with more residual consumed overall.
    score -= 0.01 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 12.0;

    // Penalize dead space that is too small for typical items (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins attractive only when the
    // item is large relative to residual or existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin, modulated by stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 + 20.0 * progress;

        // If item is large, a fresh bin is fine (big item in fresh bin wastes less).
        if item_size as f64 / bin_capacity as f64 > 0.6 {
            score -= 18.0;
        }
        // If next item is large too, opening a fresh bin may help pair large items.
        if next_item_size > 0 && next_item_size + item_size >= bin_capacity {
            score -= 10.0;
        }
        // Many open bins with high mean residual: discourage yet another bin.
        if open_bins_count > 3 && mean_residual > item_size as f64 {
            score += 15.0;
        }
    } else {
        // Prefer bins whose residual is close to item size (best-fit flavor).
        let fit_gap = (bin_residual as f64 - item_size as f64).abs();
        score += fit_gap * 0.05;

        // Lookahead: reward leaving post_residual that can host next item exactly.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 15.0;
            } else if post_residual >= next_item_size {
                score -= 3.0;
            } else {
                // post_residual can't host next item: mild penalty scaled by waste.
                score += (next_item_size - post_residual) as f64 * 0.15;
            }
        }

        // Slight preference for bins below mean residual (balance residuals).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.8 * progress * norm_post);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space: small post-residual that is still unusable
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += (nxt - post) * (1.0 + 0.5 * progress);
        } else {
            // reward leaving space exactly usable by next item
            score -= 4.0 * (1.0 - ((post - nxt) / cap).abs());
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Mild penalty when bin residual deviates from mean residual (balance pressure)
    score += 0.05 * (post - mean_residual).abs();

    // New-bin candidate: neutral-ish baseline, slightly penalized so it is
    // chosen only when open bins score poorly
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual into capacity fractions
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let sixteenth = bin_capacity / 16;

    // Dead-space penalty: leftover too small to hold typical small items (1..=16)
    if post_residual > 0 && post_residual < sixteenth {
        score += 40.0;
    } else if post_residual < eighth {
        score += 12.0;
    } else if post_residual < quarter {
        score += 4.0;
    } else {
        // generous leftover is good: reward proportional to usable fraction
        score -= (post_residual as f64 / cap) * 8.0;
    }

    // Exact-fit reward: leftover is a harmonic class that a future item can exactly fill
    if post_residual > 0 {
        let pr = post_residual;
        if cap as u32 % pr == 0 || pr % 10 == 0 || pr == quarter || pr == eighth || pr == sixteenth {
            score -= 15.0;
        }
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains perfectly into this bin
            let tight = (next_item_size as f64 / post_residual as f64).min(1.0);
            score -= 10.0 + 10.0 * tight;
        } else {
            // next item cannot use this leftover: penalize proportional to waste
            score += (next_item_size as f64) * 0.05;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer dense bins: lower residual before placement is attractive
    score += (bin_residual as f64 / cap) * 3.0;

    // Mild pressure to reuse open bins as stream progresses (avoid bin sprawl)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 5.0 * progress;
    } else {
        // new-bin candidate: penalize unless it would be a clean harmonic start
        score += 6.0 + 10.0 * progress;
        if item_size % 10 == 0 {
            score -= 4.0;
        }
    }

    // Mean residual context: if open bins are already tight overall, reuse more aggressively
    if bin_residual < bin_capacity && (mean_residual as u32) <= post_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals too small to fit the smallest plausible item (<= 10)
    // are effectively unusable; penalize them heavily.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        // Risky zone: only very small items could still use this gap.
        score += 18.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit bonus: item fills most of the bin's residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize leaving a gap just below the next item's size (blocks lookahead item).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward leaving a gap that exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (i.e., make opening a new bin less attractive).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or stream is early.
        score += 15.0 + 6.0 * pressure + 10.0 * (1.0 - progress);
    } else {
        // Existing bin: reward slightly under pressure to close bins out.
        score -= 4.0 * pressure * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins whose residual is already below average (closer to being closed out).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching:
    // reward bins whose post_residual exactly matches the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            // Perfect 2-step match: strongly reward.
            score -= 40.0 + 0.5 * (next_item_size as f64);
        } else if post_residual > next_item_size {
            // Next item still fits here: mild reward proportional to closeness.
            score -= 10.0 / (1.0 + diff);
        } else {
            // Dead space: next item cannot use the remainder.
            // Penalize more when the leftover is small (highly unusable).
            let dead = post_residual as f64;
            score += 15.0 * (1.0 - dead / bin_capacity as f64);
        }
    }

    // Exact fill of the current item is always ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer it over
    // opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin wastes its full residual
    // unless the item is large relative to capacity. Penalize the new bin
    // moderately so it is only chosen when no good open-bin fit exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 25.0 * (1.0 - fill_ratio);
    }

    // Relative-to-mean adjustment: bins with residual well below the mean are
    // "tight" bins; using them consolidates space. Bins far above the mean
    // should be kept for larger future items.
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Late-stream tightening: as the stream progresses, prefer closing bins
    // tightly (small post_residual weighted more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Prefer tight fits: penalize large relative waste
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 60.0;

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // dead space relative to lookahead
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: prefer opening a new bin only when fits are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline cost of opening a new bin
        score += 40.0;
        // open new bin if no bin fits, or if this item is large and fit would be very loose
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && item_size >= bin_capacity / 2 {
            score -= 30.0;
        }
        // late in stream, avoid proliferation of many small-residual bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count > 4 && mean_residual < 25.0 {
            score -= 20.0 * progress;
        }
    } else {
        // Slight preference for bins below mean residual (consolidate small leftovers)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Penalize creating residuals that are unusably small for the known size range (1..=100)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Mild pressure to reuse existing bins as open-bin count grows
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate loose fits; late, penalize wasted space more strongly
    let coupling = 1.0 + 1.5 * progress * progress;
    score *= coupling;

    // Interaction: post_residual vs mean residual deviation
    let dev = pr - mean_residual;
    score += 0.3 * dev * (0.5 + progress);

    // Reward filling bins that can only fit this item (last chance)
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - norm_pr);
    }

    // Penalize opening a new bin when existing bins fit reasonably well
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let waste = (bin_residual as f64 - item_size as f64) / cap;
        score += 4.0 + 6.0 * (1.0 - progress) * (1.0 - waste.abs() - 0.5).abs();
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            score -= 2.0 * (1.0 - (pr - ns) / cap);
        } else {
            score += 1.5 * (ns - pr) / cap;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual space after placement (capacity fractions, modulo logic)
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize dead-space classes: residuals in (0, 10] are nearly unusable for items >= 10
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    }
    // Modulo-10 harmonic classes: residuals that are multiples of 10 are "harmonic" and reusable
    let harmonic = post_residual % 10 == 0 && post_residual > 0;
    if harmonic {
        score -= 6.0;
    } else if post_residual > 0 {
        // distance to nearest lower multiple of 10 -> inharmonic dead space
        let off = post_residual % 10;
        score += off as f64 * 0.8;
    }

    // Integer-division thresholds: quarter/half/full residual classes
    if post_residual >= bin_capacity / 2 {
        score -= 8.0; // roomy bin, good
    } else if post_residual >= bin_capacity / 4 {
        score -= 3.0;
    } else if post_residual > 0 {
        score += 4.0; // cramped class
    }

    // Lookahead coupling: does next item fit the post residual (harmonic chaining)?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + next_item_size as f64 * 0.05;
        } else {
            // next item won't fit: residual becomes waste for the lookahead
            let waste = (next_item_size - post_residual) as f64;
            score += waste.min(40.0) * 0.25;
        }
    } else {
        // last item: minimize leftover
        score -= 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin unless fit is terrible
    if fitting_bins_count == 1 && post_residual < bin_residual {
        score -= 12.0 + frac * 5.0;
    }

    // New-bin candidate handling: empty bin starts with full residual
    if bin_residual == bin_capacity {
        // opening new bins is costly when many bins are already open and stream is late
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 60.0 + open_bins_count as f64 * 2.0 + progress * 20.0;
        // but attractive if no harmonic open bin exists (mean residual far from usable classes)
        let mean_class = (mean_residual as u32) % 10;
        score = base + if mean_class != 0 { 5.0 } else { 0.0 };
        // small items (<= 20) fit anywhere; discourage new bin
        if item_size <= 20 {
            score += 30.0;
        }
    }

    // Mild preference to fill bins tighter as stream progresses
    score *= 1.0 + (step_index as f64 / (total_items.max(1) as f64)) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals that are too small to hold even the
    // minimum item (size 1) are fine only if zero; tiny-but-nonzero gaps are
    // effectively wasted. Penalize gaps in (0, 10) harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + 2.0 * (10 - post_residual) as f64;
    }

    // Reward exact fills strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residuals that can still fit the lookahead item after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Lookahead won't fit here: mild penalty proportional to wasted potential.
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // existing bins would leave bad dead space; otherwise discourage.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
    }

    // Open-bins pressure: mildly favor bins that reduce fragmentation when
    // many bins are open.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Tightness coupling: prefer bins where the item fills a large fraction.
    score -= 10.0 * (item_size as f64 / bin_residual.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base reward for tight fits (small post_residual)
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 0.8 * tightness * cap;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // 2-step lookahead: reward when next item fits the post_residual well
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = (next_item_size as f64) / (post_residual as f64);
        // best when next item fills most of remaining space
        score -= 20.0 * chain_fit;
        if post_residual == next_item_size {
            score -= 15.0; // perfect 2-item fill
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // dead space: next item cannot use the leftover
        score += 15.0;
        // worse if leftover is small (unusable sliver)
        if post_residual < 10 {
            score += 10.0;
        }
    }

    // Compare against mean residual: prefer bins with below-average residual
    // (use up the emptiest-capacity bins first, keep roomier bins flexible)
    if post_residual as f64 > mean_residual {
        score += 0.4 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent open bins exist,
    // but allow it if item is large and no bin fits well
    if bin_residual == bin_capacity {
        let new_bin_penalty = 40.0
            + 0.3 * (post_residual as f64)
            - if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        score += new_bin_penalty;
    }

    // Late in stream: be more conservative, prefer tighter packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: blend from "fill existing bins" early to "waste less" late.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Lookahead synergy: reward bins whose post-residual exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 * (1.0 - progress * 0.5);
        } else if post_residual > next_item_size {
            // Partial synergy: how tightly the next item would fit afterwards.
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (-gap / 30.0).exp();
        }
        // Penalize residuals too small for the next item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0 + 0.15 * post_residual as f64;
        }
    } else {
        // Last item: prefer tightest fit, ignore future.
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post-residual is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 + 0.2 * item_size as f64;
    }

    // Penalize opening new bins when many bins are already open and could fit.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        score += 20.0 + 2.5 * crowd.sqrt() + 30.0 * progress;
        // Allow new bin if mean residual across open bins is small (all bins tight).
        score -= 0.6 * mean_residual;
    } else {
        // Favor bins that are already somewhat filled (smaller residual => tighter packing).
        score -= 0.35 * (bin_residual as f64 - post_residual as f64);
        // Slight preference for bins below mean residual (balancing).
        score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // Dead-space penalty: residuals that no plausible item (>=1) can use are fine,
    // but tiny residuals (1..=5) are near-useless — mild extra penalty scaled by progress.
    if post_residual > 0 && post_residual <= 5 {
        score += 10.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear sharpening
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress:
    // early in the stream, tolerate larger residuals (favor consolidation later)
    let progress_coupling = pr * (0.5 - progress) * (1.0 - progress) * 2.0;
    score += progress_coupling;

    // Penalize residuals that cannot fit the next item (quadratic dead-space term)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += gap * gap / cap;
        // Reward when post_residual exactly leaves room for next item
        let fit_gap = (pr - next_item_size as f64).abs();
        score -= (1.0 - fit_gap / cap).max(0.0) * 4.0;
    }

    // Last-chance bonus: only one fitting bin -> strong incentive to use it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += (open_bins_count as f64).ln() * 0.5 + (mean_residual - pr) * 0.05;

    // New-bin candidate: penalize opening a fresh bin unless residuals are tight
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize dead space into capacity fractions.
    let post_frac = post_residual as f64 / cap;
    // Class 0: perfect fit (post_residual == 0) -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space classes: residuals that are "unusable" (small) are penalized,
        // residuals that could host common small items (harmonic divisors) are fine.
        let class = post_residual / 10; // integer division threshold classes: 0..10
        match class {
            0 => score += 60.0,          // 1..9: nearly dead space
            1 => score += 35.0,          // 10..19: only tiny items fit
            2 => score += 15.0,          // 20..29
            3 => score -= 5.0,           // 30..39: useful slot
            4 => score -= 10.0,          // 40..49
            5 => score -= 12.0,          // 50..59: half-bin sweet spot
            6 => score -= 8.0,
            7 => score -= 5.0,
            8 => score -= 3.0,
            9 => score -= 1.0,
            _ => {}                       // 100: fresh bin class handled below
        }
        // Modulo-10 harmonic: residuals divisible by 10 align with item granularity.
        if post_residual % 10 == 0 {
            score -= 4.0;
        }
        // Modulo-20 alignment: strong harmonic with common item sizes.
        if post_residual % 20 == 0 {
            score -= 4.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item fits: how tightly?
            let slack = post_residual - next_item_size;
            score -= 20.0 * (1.0 - slack as f64 / cap);
        } else {
            // next item won't fit here: this bin becomes dead after placement;
            // penalize proportionally to how much space is wasted.
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Fresh-bin candidate handling: only prefer it when open bins are badly fragmented
    // or the fit here is terrible.
    if bin_residual == bin_capacity {
        // Base competitiveness: new bin starts with full residual.
        score = cap * 0.5;
        // If mean residual across open bins is small (fragmented), opening is attractive.
        score -= (mean_residual / cap) * 10.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // Many open bins already: discourage proliferation.
        score += 2.0 * open_bins_count as f64;
        // If next item is huge, a fresh bin is valuable (it can host both).
        if next_item_size > 50 && item_size <= 50 {
            score -= 15.0;
        }
    }

    // Mild preference for tighter bins overall (best-fit flavor) scaled by fragmentation.
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are heavily penalized.
    // Anything below the smallest possible item (1..100 range) is dead; gaps below the
    // lookahead item are likely dead too.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else {
        let dead_threshold = next_item_size.max(1);
        if post_residual < dead_threshold {
            // unusable gap -> strong penalty scaled by how "wasted" it is
            score += 25.0 + (post_residual as f64) * 0.5;
        } else {
            // usable residual: mild reward proportional to tightness
            let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
            score -= 10.0 * tightness;
        }
    }

    // Reward near-perfect fits extra (post_residual very small but nonzero)
    if post_residual > 0 && post_residual <= 3 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        // existing bin: reward more when many bins are open
        score -= 2.0 * pressure * (0.5 + 0.5 * progress);
    } else {
        // brand-new bin candidate: penalize proportionally to open bins pressure
        score += 5.0 + 3.0 * pressure;
    }

    // Mean-residual coupling: if average residual is large, prefer bins that reduce it most
    score -= 0.05 * (mean_residual - post_residual as f64).max(0.0);

    // Lookahead synergy: reward if post_residual exactly matches next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: post_residual close to 0 is excellent.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else {
        // Penalize small-but-unusable leftovers (dead space below min item size 1..=small)
        if post_residual < 10 {
