    // Aggressive 2-step lookahead: if the next item fits exactly in post_residual,
    // strongly favor this bin (chained perfect packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits: reward proportionally to tightness of the chain
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= (100.0 - chain_slack.min(100.0)) * 0.8;
        } else {
            // next item does NOT fit here: penalize creating residual that
            // is smaller than next_item_size (stranding capacity)
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.6;
            }
        }
    }

    // Compare residual against mean residual: prefer bins that reduce variance
    // (balance residuals across open bins).
    let residual_f = post_residual as f64;
    let dev = residual_f - mean_residual;
    score += dev.abs() * 0.3;

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item would leave a very awkward residual in every existing bin, or when
    // few bins are open early in the stream.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // No alternative: must open new bin.
            score -= 2000.0;
        } else if next_item_size > 0 && next_item_size >= item_size && item_size >= 50 {
            // Large item early with a comparable next item: fresh bin gives
            // clean pairing potential.
            let progress = step_index as f64 / total_items.max(1) as f64;
            if progress < 0.5 {
                score -= 60.0;
            } else {
                score += 50.0;
            }
        } else {
            // Default: discourage opening new bins when existing ones fit.
            score += 150.0 + open_bins_count as f64 * 2.0;
        }
    }

    // Prefer filling bins that are already mostly full (tight packing).
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fullness * 30.0;

    // Slight preference for fewer open bins overall.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

