    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Chain fit: prefer leaving exactly a usable gap for the next item.
        if post_residual == next_item_size {
            score -= 6.0;
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (penalize cramming into open bins); later, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    // Global state: many open bins with slack -> discourage spreading;
    // few open bins -> opening a new bin is cheaper.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins already have plenty of
        // slack that fits the item; discount when open bins are crowded.
        let slack = mean_residual.max(0.0);
        score += slack * 0.35;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin anyway
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Existing bin: mild reward when open bins are numerous (consolidate).
        score -= (open_bins_count.min(20) as f64) * 0.4;
    }

    // Prefer using bins whose residual is close to the item (minimal waste).
    let waste_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * waste_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: minimize wasted space, with non-linear penalty for tiny dead space.
    let mut score = pr as f64;

    // Smooth polynomial coupling of post residual with stream progress:
    // early on, prefer tighter packing (low post_residual); later, the
    // relative value of residual space shifts non-linearly.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += (x - 0.5) * (x - 0.5) * (20.0 + 40.0 * p2) * (1.0 - p3);

    // Dead-space penalty: residuals too small for any plausible item (1..100)
    // are wasted; penalize smoothly as x approaches unusable range.
    let unusable = ((0.20 - x).max(0.0) / 0.20).powi(3);
    score += 60.0 * unusable;

    // Reward filling the bin nearly completely (x near 0) with smooth gain.
    score -= 15.0 * (1.0 - x).powi(4);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 - p3);
    }

    // Lookahead: reward leaving room for the next item (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let room = (x - nx).max(0.0);
        score -= 10.0 * room * (1.0 + progress);
        // Penalize if post residual is just barely below next item size.
        let miss = ((nx - x).max(0.0)).powi(2);
        score += 25.0 * miss;
    }

    // Mild preference to use existing bins vs opening new ones as stream grows.
    score += (open_bins_count as f64).ln() * 0.5;

    // Smooth bias toward keeping mean residual balanced with this bin's outcome.
    score += 0.3 * (mean_residual - pr as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 define
    // "usable" dead-space classes. Residues 0 (perfect fill) are best;
    // small residues 1..=9 are progressively worse dead space.
    let residue = (post_residual % 10) as f64;
    if post_residual == 0 {
        score -= 30.0; // perfect closure — reward strongly
    } else if residue <= 2.0 {
        score -= 6.0; // near-perfect class
    } else if residue >= 8.0 {
        score -= 3.0; // large residual still usable by small items
    } else {
        score += residue * 1.5; // penalize awkward mid-class dead space
    }

    // Integer-division threshold on post_residual: bins whose leftover
    // can still host the smallest items (<=10) are valuable.
    if post_residual >= 10 {
        score -= 4.0;
    } else if post_residual > 0 {
        score += 8.0; // dead space below the minimum item size
    }

    // Lookahead coupling: harmonic class of next_item_size.
    if next_item_size > 0 {
        let next_class = next_item_size % 10;
        if post_residual >= next_item_size {
            // This bin can also serve the next item; reward if the
            // post-fit residual stays in a good class for it.
            let after_next = post_residual - next_item_size;
            if after_next % 10 == 0 {
                score -= 10.0;
            } else if after_next < 10 && after_next > 0 {
                score += 5.0;
            }
            score -= 2.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // residual too small for the lookahead item: penalize by
            // the gap between them.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // If next item is in the "big" class (>= 10 threshold via /10),
        // prefer conserving roomy bins for it.
        if next_item_size / 10 >= 5 && post_residual >= 50 {
            score += 4.0;
        }
    }

    // New-bin candidate handling: residual == capacity means empty bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is discouraged unless it's the only option
        // or the current item would leave terrible dead space elsewhere.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = fitting_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin anyway
        } else {
            // Penalize new bins more when many alternatives exist and
            // early in the stream (future items need those bins).
            score += 12.0 + 20.0 * (1.0 - progress) + 3.0 * pressure;
            // But if this item is huge (harmonic class 8/10 of capacity),
            // a fresh bin giving a clean fit is fine.
            if item_size >= 80 && post_residual <= 20 {
                score -= 15.0;
            }
        }
    } else {
        // Last-chance bin: strongly prefer using it to avoid waste.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Tight fits are good: item fills most of the bin.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= fill_ratio * 8.0;
    }

    // Mean-residual coupling: placing into a bin far below the mean
    // residual balances the fleet; placing into an already-full-ish
    // bin (residual well below mean) risks stranding it.
    let dev = mean_residual - post_residual as f64;
    score += 0.05 * dev;

    // Late-stream bonus for closing bins completely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual < 10 {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest item (1) are pure waste;
    // residuals below the typical item scale are "unusable" gaps.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward tight fits (small post_residual relative to bin).
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    score -= fit_ratio * 15.0;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8 * (0.5 + 0.5 * (1.0 - progress));

    // Mean-residual coupling: if the fleet average residual is high, prefer bins that
    // reduce dispersion (place into below-average-residual bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        if slack_after_next < dead_threshold {
            score -= 10.0;
        } else {
            score -= 4.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when open bins offer poor fits.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so early on and when other bins exist.
        score += 30.0 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is mandatory
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward bins whose post-residual matches the next item size (2-step lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_quality = 1.0 - ((post_residual as f64 - next_item_size as f64) / bin_capacity as f64).abs();
        score -= 40.0 * match_quality * match_quality;
    } else if next_item_size > 0 {
        // Penalize creating dead space the next item cannot use.
        let dead = post_residual as f64;
        score += 0.5 * dead;
    }

    // Reward leaving residuals near the mean (keeps flexibility) but not too near.
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score -= 5.0 / (1.0 + mean_gap);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when existing bins fit well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_penalty = 10.0 + 20.0 * (open_bins_count as f64 / (1.0 + progress * 10.0));
        score += open_penalty;
        // Allow new bin if current item is large and would leave tiny unusable residue elsewhere.
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Slight preference for tighter fits overall.
    score -= 0.2 * (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more strongly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead-aware).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space for the lookahead item: penalize proportionally to wasted gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        } else {
            // Reward bins that can also host the next item (chaining).
            score -= 4.0;
        }
    } else {
        // Last item: pure tightness matters most; extra reward for near-perfect fill.
        if post_residual <= 2 {
            score -= 20.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, to discriminate among them.
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state: prefer filling bins in bins with below-average residual
    // (compact the bin set), penalize drawing from above-average-residual bins
    // when the item fits poorly.
    let res_dev = bin_residual as f64 - mean_residual;
    score += 0.15 * res_dev * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep options open); late in the stream, consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize it increasingly as stream progresses,
        // but allow it early or when the fit in existing bins is hopeless.
        score += 40.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        }
        // A fresh bin is attractive if it can host the next item too.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0 * (1.0 - progress);
        }
    } else {
        // Existing bins get a slight consolidation bonus late in the stream.
        score -= 5.0 * progress;
    }

    // Mild penalty on opening too many bins relative to stream size.
    if open_bins_count as f64 > 0.5 * total_items as f64 {
        score += 3.0;
    }

    // Small deterministic tie-break: prefer bins whose residual is an
    // "easy-to-fill" multiple band (residual close to common item sizes 10..80).
    let band_fit = (1..=8)
        .map(|k| ((bin_residual as f64 - 10.0 * k as f64).abs()))
        .fold(f64::INFINITY, f64::min);
    score -= 0.05 * (80.0 - band_fit.min(80.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, penalize them quadratically.
    let w = 1.0 + 2.0 * progress * progress;
    score += 0.9 * (post / cap) * (post / cap) * cap * w * 0.1;

    // Smooth reward for tight fits (small post_residual relative to item size)
    let tight = (item_size as f64 / bin_residual.max(1) as f64).powi(2);
    score -= 8.0 * tight * (1.0 + progress);

    // Lookahead: reward if next item fits into post_residual, smooth falloff
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 6.0 * (-gap / 30.0) * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New empty bin candidate: penalize unless residuals are fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap - 0.5).abs();
        score += 10.0 - 8.0 * frag * (1.0 + progress);
        score += 0.5 * open_bins_count as f64;
    } else {
        // Favor bins with residual close to mean (balance load) smoothly
        score += 0.3 * ((bin_residual as f64 - mean_residual) / cap).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (best fit), scaled
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: residues that are "usable" by typical
    // small items (multiples of small denominators) are less penalized.
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;
    // dead-space penalty grows when post_residual is small-but-nonzero
    // (unusable sliver), while exact 0 is perfect.
    if post_residual == 0 {
        score -= 50.0; // perfect fit bonus
    } else if post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0; // sliver penalty
    }

    // Modulo harmonic classes: post_residual divisible by common item sizes
    // (or near-divisible) is reusable -> reward.
    for d in [10u32, 20, 25, 40, 50].iter() {
        if *d <= post_residual && post_residual % d == 0 {
            score -= 8.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score += gap as f64 * 0.5;
            // harmonic match: gap divisible by small classes
            if gap % 10 == 0 { score -= 5.0; }
        } else {
            // next item can't use this bin anyway; residual is "final" dead space
            score += post_residual as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize mildly so we only open new bins
    // when fits are poor; the base post_residual (=capacity-item_size) already
    // reflects the fresh residual.
    if bin_residual == bin_capacity {
        score += 15.0;
        // early in stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Many open bins with high mean residual: discourage spreading, prefer
    // tight packing into existing bins.
    if open_bins_count > 2 && mean_residual > (bin_capacity as f64) * 0.4 {
        score += 5.0;
    } else if open_bins_count > 0 {
        score -= 2.0;
    }

    // Integer-division threshold coupling: reward when item size and residual
    // share harmonic structure (item ~ divides residual).
    if item_size > 0 && bin_residual % item_size.max(1) == 0 && item_size <= bin_residual {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 3.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size {
        // Dead space relative to the known next item.
        score += (next_item_size - post_residual as u32) as f64 * 0.5;
    }

    // Mean residual coupling: prefer bins below mean residual (more filled).
    score += (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate baseline: make it competitive only when open bins are bad.
    if bin_residual == bin_capacity {
        score += 10.0 + pressure * 0.5;
        // Opening a new bin is fine if no good fit exists elsewhere.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic penalty for wasted post_residual.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Dead-space penalty: residuals too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: keep room for the next item if it can nest here.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // this bin can host the next item too
        } else {
            // penalize leaving a sliver that blocks the next item
            let gap = next_item_size as f64 - post_residual as f64;
            if gap < 10.0 {
                score += 18.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // New-bin candidate handling: only attractive when item is large
    // relative to all residuals or open bins are congested.
    if bin_residual == bin_capacity {
        let mean_fit = mean_residual;
        let item_f = item_size as f64;
        // If item barely fits anywhere, a fresh bin is fine.
        let tightness = if mean_fit > 0.0 { item_f / mean_fit } else { 1.0 };
        score = item_f * 0.9; // baseline cost of opening a new bin
        if tightness > 1.5 {
            score -= 20.0 * (tightness - 1.5).min(2.0);
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
        if open_bins_count > 8 {
            score += (open_bins_count as f64 - 8.0) * 2.0;
        }
        return score;
    }

    // Prefer bins with smaller residual among equally good fits (best-fit bias).
    score += bin_residual as f64 * 0.05;

    // Global load balancing: mildly discourage bins far below mean residual.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score += 0.08 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) - norm_pr * progress * 0.5;
    score += poly * cap * 0.8;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 20.0 * progress);

    // Penalize wasted space relative to mean residual of open bins
    score += (norm_pr - mean_residual / cap).abs() * 5.0;

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = (pr - ns).abs();
        score += diff * 0.3;
        if pr >= ns {
            score -= 8.0 * (1.0 - diff / cap);
        }
    }

    // Mild penalty for accumulating too many open bins early
    score += open_bins_count as f64 * progress * 0.5;

    // New-bin candidate: prefer opening a new bin when existing fits are poor
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (eighths). Smaller class = tighter fit = better.
    let eighth = bin_capacity as f64 / 8.0;
    let class = (post_residual as f64 / eighth).floor().min(7.0);
    score += class * 2.0;

    // Perfect or near-perfect closure is heavily rewarded.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Dead-space penalty: residuals below the smallest item are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: does the next item fit exactly into the leftover?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use this bin's leftover; penalize large leftovers
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Harmonic modulo logic on post_residual: residuals that are multiples of
    // common small item sizes (10, 20, 25) are more reusable.
    if post_residual % 10 == 0 { score -= 6.0; }
    if post_residual % 20 == 0 { score -= 3.0; }
    if post_residual % 25 == 0 { score -= 3.0; }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no good fit exists elsewhere (few fitting bins, large mean residual waste).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { (1.0 / fitting_bins_count as f64).min(1.0) };
        let waste = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 100.0 - 30.0 * pressure - 20.0 * waste;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin likely useful for the upcoming item too
        }
    }

    // Prefer filling bins with larger residual when many bins are open (bin consolidation).
    score += (open_bins_count as f64) * (bin_residual as f64 - post_residual as f64) / bin_capacity as f64 * 0.5;

    // Slight early-stream bias toward tight fits to establish good structure.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be useful.
    // Gaps in [1, 15) are nearly dead weight (min item size is 1, but small gaps rarely fit).
    if post_residual > 0 && post_residual < 15 {
        score += 40.0 + (15 - post_residual) as f64 * 3.0;
    }

    // Perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fits (small post_residual but usable) mildly rewarded.
    score -= 2.0 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // Lookahead: if the next item fits into the post residual, reward; else penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Open-bin pressure: prefer bins that reduce the count of open bins indirectly,
    // i.e., fill existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.15 * (1.0 - progress);

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin when decent existing options exist.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3;
    }

    // Mild preference for bins with residual close to mean (keeps balance).
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 30.0;
    score += tightness * tightness * 40.0;

    // 2-step lookahead: if next item fits exactly into post_residual, big bonus
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: bin becomes exactly full after next item
        } else if post_residual >= next_item_size {
            let next_post = post_residual - next_item_size;
            // reward leaving room for next item, penalize large leftover after it
            score -= 25.0;
            score += (next_post as f64 / bin_capacity as f64) * 35.0;
        } else {
            // next item cannot follow here; penalize proportionally to wasted space
            score += 15.0;
        }
    } else {
        // last item: just minimize leftover
        score += post_residual as f64 * 0.5;
    }

    // Compare against mean residual: bins tighter than average are good targets
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's clearly better
    if bin_residual == bin_capacity {
        let base_penalty = 45.0 + 10.0 * (open_bins_count as f64).sqrt();
        score += base_penalty;
        // Early in the stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
        // If next item is large, a fresh bin is more attractive
        if next_item_size > 0 {
            score -= (next_item_size as f64 / bin_capacity as f64) * 10.0;
        }
    }

    // Mild penalty for spreading across too many open bins
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the fuller the bin becomes, the bigger the discount.
    let fill = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * fill.powi(3);

    // Lookahead coupling (k=2): reward bins whose leftover can host the next item,
    // penalize leftovers that strand the next item.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 12.0;
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap.min(80.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating above-average dead space (global state coupling).
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    // Dynamic time horizon: as the stream progresses, weight residual waste more
    // heavily (consolidation pressure grows over time).
    let t = step_index as f64 / total_items.max(1) as f64;
    score += t * (post_residual as f64 / 10.0);

    // New-bin candidate: baseline cost of opening a fresh bin, slightly cheaper
    // late in the stream when leftover fragmentation is harder to use.
    if bin_residual == bin_capacity {
        score = 100.0 + 18.0 - 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: prefer small post residual, with smooth polynomial shaping.
    let x = post / cap; // normalized post residual in [0,1]
    let mut score = x * x * (3.0 - 2.0 * x) * 40.0 + x * 20.0;

    // Dead-space penalty grows smoothly as post residual becomes unusably small
    // relative to typical item sizes, amplified late in the stream.
    let dead = ((1.0 - x) * (1.0 - x)) * 30.0;
    score -= dead * (0.3 + 0.7 * progress);

    // Lookahead: penalize post residual that barely fails to fit next item,
    // reward post residual that accommodates it smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap < 0.0 {
            let shortfall = (-gap / cap).clamp(0.0, 1.0);
            score += shortfall * shortfall * 25.0;
        } else {
            let slack = (gap / cap).clamp(0.0, 1.0);
            score -= (1.0 - slack) * (1.0 - slack) * 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: mildly penalize early, allow late when residuals are fragmented.
    if is_new_bin {
        score += 10.0 + 30.0 * (1.0 - progress) - (mean_residual / cap).clamp(0.0, 2.0) * 8.0;
    } else {
        // Slight reward for reducing mean residual (consolidation).
        score -= ((mean_residual - post) / cap).clamp(-1.0, 1.0) * 5.0;
    }

    // Smooth open-bin pressure: many open bins -> favor consolidation into existing bins.
    let pressure = (open_bins_count as f64).ln_1p();
    score += pressure * x * 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 4.0).floor() as i32; // 0..3 harmonic buckets

    // Penalize leftovers by class: small slivers (class 0) are dead space.
    score += match class {
        0 => 12.0,
        1 => 4.0,
        2 => 1.0,
        _ => 0.0,
    };

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: reward leaving space exactly usable by the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot fit in leftover: mild penalty scaled by gap.
            score += 3.0 + (next_item_size - post_residual) as f64 / 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer tighter bins among fitting bins.
    score -= (bin_residual as f64 - post_residual as f64) * 0.1; // equals item_size, tie-break neutral
    score -= (bin_capacity - bin_residual) as f64 * 0.05; // reward fuller bins

    // New-bin candidate: penalize opening a new bin unless current residuals are poor.
    if bin_residual == bin_capacity {
        let avg_bad = mean_residual / bin_capacity as f64;
        score += 15.0 + 30.0 * avg_bad;
        // Early in stream, opening bins is cheaper; later, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Modulo harmonic coupling: leftovers congruent to common item sizes are reusable.
    let common = [10u32, 20, 25, 30, 40, 50];
    for &c in &common {
        if post_residual >= c && (post_residual % c) == 0 {
            score -= 2.0;
            break;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps below the minimum useful size are heavily penalized.
    let min_useful = 10.0f64; // smallest item size historically
    if (post_residual as f64) < min_useful {
        score += 60.0 * (min_useful - post_residual as f64) / min_useful;
    }

    // Nonlinear penalty on tiny-but-nonzero leftovers (fragmentation pressure).
    if post_residual > 0 && post_residual < 20 {
        score += 25.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, prefer compacting into existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    if bin_residual != bin_capacity {
        score -= pressure * (item_size as f64 / bin_capacity as f64);
    }

    // Prefer bins whose residual is close to what we consume (tight fit relative to mean state).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Late in the stream, compact harder into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        // Penalize opening new bins more as the stream progresses.
        score += 15.0 * progress;
    }

    // Slight preference toward bins below mean residual (concentrate waste).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fill: small post_residual is good.
    score -= 12.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(4);

    // 2-step lookahead: if the next item exactly fits the post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 20.0 * (-diff / 8.0).exp();
        // Penalize post_residuals that are too small to fit the next item
        // but large enough to be tempting dead space.
        if (post_residual as i64) < (next_item_size as i64) {
            score += 4.0 * (post_residual as f64 / 20.0);
        }
    } else {
        // Last item: any residual is pure waste; reward tight fits extra.
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Compare against mean residual: bins with residual well below mean
    // are already "tight"; using them avoids fragmenting large residuals.
    if post_residual as f64 > mean_residual {
        score += 0.8 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize the brand-new empty bin candidate unless the fit is poor
    // or the stream is early (strategic opening for future large items).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64 / bin_capacity as f64) > 0.45;
        if poor_fit || progress < 0.15 {
            score -= 10.0;
        } else {
            score += 25.0;
        }
    }

    // Mild penalty for very large dead space.
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0; // nearly full bin is excellent
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize dead space that can never be used again (post_residual < min item size 1 -> waste).
    if post_residual == 0 {
        score -= 25.0; // perfect fit is excellent
    } else if post_residual < 10 {
        score += 6.0; // tiny unusable sliver
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0 + 0.05 * next_item_size as f64;
        } else {
            // Penalize leaving a gap just below the next item (frustrated fit).
            let gap = (next_item_size as f64 - post_residual as f64).max(0.0);
            score += 0.08 * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: prefer reusing open bins unless the fit is poor
    // or global residuals are bloated.
    if bin_residual == bin_capacity {
        // New bin baseline: slightly worse than a decent existing fit.
        score += 3.0;
        // If many open bins already exist with slack, discourage hoarding new bins.
        score += 0.15 * open_bins_count as f64;
        // But if mean residual across open bins is small (all bins tight),
        // opening a fresh bin is reasonable.
        score -= 0.05 * mean_residual;
    } else {
        // Prefer fuller bins among open ones (best-fit bias).
        score -= 0.05 * (bin_capacity - bin_residual) as f64;
    }

    // Time-horizon modulation: early in stream, be conservative (favor tight packing);
    // late in stream, prioritize closing out bins (reduce open-bin count pressure).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 0.03 * post_residual as f64;
    score -= (1.0 - progress) * 0.02 * post_residual as f64;

    // Mild penalty for spreading across many bins when residuals are large.
    score += 0.01 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress.
    let mut score = pr;

    // Polynomial penalty for wasted space, modulated by progress:
    // early on, waste is tolerable (future items can fill it); late, waste is costly.
    let waste_poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr.powi(4) * progress;
    score += 40.0 * waste_poly;

    // Reward tight fits via smooth cubic of item fraction.
    let fill_frac = item_size as f64 / cap;
    score -= 25.0 * fill_frac * fill_frac * (1.0 - fill_frac) * (1.0 + progress);

    // Lookahead coupling: smooth polynomial interaction between post_residual and next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        // Perfect follow-up fit: strongly reward.
        if diff >= 0.0 {
            let d = diff / cap;
            score -= 18.0 * (1.0 - d * d) * (1.0 - 0.5 * progress);
        } else {
            let d = (-diff) / cap;
            score += 18.0 * d * d * (1.0 + progress);
        }
    }

    // Last-chance bonus: only one fitting bin -> encourage using it over opening new.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: penalize slightly so we prefer existing bins unless residuals are poor.
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * (1.0 - progress) + 5.0 * (open_bins_count as f64).sqrt();
    } else {
        // Mild preference for bins with residuals close to mean (balance).
        let dev = (bin_residual as f64 - mean_residual).abs() / cap;
        score += 6.0 * dev * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how cleanly it divides the capacity
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward small post-residuals non-linearly (tight fits)
    score -= (1.0 - pr / c).powi(6) * 18.0;

    // Modulo classes: residuals divisible by small harmonics are reusable
    if post_residual > 0 {
        let mod10 = post_residual % 10;
        let mod20 = post_residual % 20;
        let mod25 = post_residual % 25;
        let mut harm = 0.0;
        if mod10 == 0 { harm += 3.0; }
        if mod20 == 0 { harm += 2.0; }
        if mod25 == 0 { harm += 2.0; }
        if mod10 == 5 { harm += 1.0; }
        score -= harm;

        // Penalize awkward residual classes (1..9 dead space zones)
        if post_residual < 10 {
            score += 8.0;
        }
    } else {
        // Perfect closure is excellent
        score -= 25.0;
    }

    // Lookahead coupling: does the residual class match the next item's class?
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= (1.0 - gap / c).powi(4) * 12.0;
        // Harmonic match: next item leaves a clean residual too
        if (post_residual - next_item_size) % 10 == 0 { score -= 3.0; }
    } else if next_item_size > 0 {
        // Next item cannot fit here: this is a terminal placement
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are badly fragmented
    if bin_residual == bin_capacity {
        let pressure = mean_residual / c;
        score += 12.0 * pressure;
        if fitting_bins_count > 0 { score += 6.0; }
        // Early stream: be slightly more willing to open bins
        let t = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - t) * 4.0;
    }

    // Mild fragmentation penalty relative to fleet mean residual
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (<= 10, min item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderately small gaps are hard to fill too.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Exact fit for the lookahead item: strongly favor.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Dead space relative to lookahead: leaving a gap the next item can't use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight fills
    // (small post_residual) even more; few open bins -> tolerate new bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 30.0;

    // New-bin candidate: only attractive when existing residuals are poor fits
    // (e.g. current item barely fits anywhere or would leave a tiny gap).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by how bad the best alternative is.
        let gap_waste = if post_residual > 0 && post_residual < 10 { 40.0 } else { 0.0 };
        score = bin_capacity as f64 * 0.55 + gap_waste
            - pressure * 5.0
            - if fitting_bins_count == 0 { 30.0 } else { 0.0 };
    }

    // Late in the stream, tighten up: waste penalized harder.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to the item (tight fit relative measure).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next_item_size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits but leaves more dead space; penalize leftover slack.
            score += diff as f64 * 0.4;
        } else {
            // next item cannot fit here; penalize creating unusable dead space.
            score += diff as f64 * 0.7;
        }
    }

    // Tight fit reward relative to mean residual.
    let mean_r = mean_residual.max(1.0);
    if (post_residual as f64) < mean_r {
        score -= (mean_r - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_r) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 + 30.0 * (1.0 - progress);
    }

    // Slight preference for bins with less residual before placement (best-fit core).
    score += bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize post-residual dead space that cannot fit the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 * (next_item_size as f64 - post_residual as f64);
    } else if next_item_size > 0 {
        // Reward leaving space exactly usable by the next item.
        score -= 8.0;
    }

    // Reward tight fits (small waste relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.3 * item_size as f64;
    }

    // Penalize opening new bins when many bins are already open and fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
        // But if mean residual is small (open bins are full-ish), new bin is fine.
        score -= 0.4 * mean_residual;
    }

    // Prefer bins below mean residual (compact bins get filled, fragmented ones saved).
    if !is_new_bin {
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    // Dynamic time horizon: early in stream, be conservative with big items;
    // late in stream, squeeze into existing bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (bin_residual as f64 - item_size as f64).max(0.0) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with a smooth non-linear bias
    // that grows as the stream progresses (squeezing becomes more valuable).
    let mut score = pr * (1.0 + 1.5 * progress * x);

    // Smooth penalty for awkward mid-range dead space (neither tight nor roomy),
    // strongest around x ~ 0.4, vanishing at x=0 and x=1.
    let bump = 16.0 * x * (1.0 - x) * (x - 0.4).abs() * 2.0;
    score += bump;

    // Reward tight fits more aggressively as stream progresses.
    score -= 12.0 * progress * (1.0 - x).powi(3);

    // Lookahead coupling: reward if the next item fits into the post residual,
    // penalize if post residual is just barely too small for the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 10.0 * progress * (1.0 - (pr - ni) / cap);
        } else if pr > 0 && pr + ni <= cap {
            score += 6.0 * (1.0 - pr / ni);
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x);
    }

    // New-bin candidate (empty bin): penalize mildly so it is chosen only
    // when no open bin offers a decent fit; penalty eases late in the stream
    // when residual fragmentation is high.
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - 0.5 * progress) + 4.0 * (mean_residual / cap).min(1.0);
    }

    // Mild global pressure: many open bins with high mean residual
    // -> encourage consolidation into existing bins.
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap) * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: capacity fractions ---
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left after placement

    // Exact fit: perfect, reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space classes: post_residual too small to ever be useful.
    // Harmonic thresholds via integer division on capacity.
    let q = post_residual / (bin_capacity / 4); // 0..4 class
    match q {
        0 => {
            // post_residual < 25% capacity: likely dead space unless next item fits
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 60.0; // lookahead fits: excellent packing
            } else {
                score += 120.0; // dead space penalty
            }
        }
        1 => {
            // 25..50% residual class
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 40.0;
            } else {
                score += 30.0;
            }
        }
        2 => {
            // 50..75% residual class: still flexible
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 55.0;
            }
            score -= 10.0;
        }
        _ => {
            // nearly empty bin after placement: keep flexibility, mild penalty
            score += 15.0;
        }
    }

    // Modulo arithmetic on post_residual: residuals that are "harmonics"
    // of common item sizes are more likely to be filled later.
    let h = post_residual % 10;
    if h == 0 {
        score -= 20.0; // round residual: many item sizes fit exactly
    } else if h < 5 {
        score += 10.0 * (5 - h) as f64; // awkward small remainder
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only open a new bin when all open bins
    // would leave bad dead space (post_residual < quarter capacity and
    // lookahead doesn't fit anywhere).
    if bin_residual == bin_capacity {
        // Brand-new bin: score = full capacity minus discount, adjusted by
        // stream position and current bin count.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = cap - 25.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        // If next item is large, a fresh bin is attractive.
        if next_item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    } else {
        // Open bins: prefer tighter residual overall (best-fit baseline).
        score += (mean_residual - post) * 0.1;
    }

    // Coupling: if this bin's residual class matches the item size class
    // (harmonic alignment), reward it.
    let item_class = item_size / (bin_capacity / 4);
    let res_class = bin_residual / (bin_capacity / 4);
    if item_class == res_class {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space: residuals too small for any item (min size 1, but practically < 12)
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits (small post_residual relative to item)
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 25.0 * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let la_fit = (post_residual - next_item_size) as f64;
        if la_fit < 12.0 {
            score -= 35.0;
        } else {
            score -= 12.0;
        }
    }
    // If next item cannot fit in post_residual, dead end for this bin
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // New-bin candidate handling: prefer existing bins unless this is last chance or bin is empty
    if bin_residual == bin_capacity {
        // Opening a new bin: penalize unless no alternatives
        let pressure = (open_bins_count as f64) * 1.5;
        score += 55.0 + pressure;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in stream, opening fresh bins is fine
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * progress;
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it
        score -= 45.0;
    }

    // Open bins pressure: encourage consolidation into fewer bins
    score += (open_bins_count as f64) * 0.8;

    // Prefer bins with residuals below mean (use up nearly-full bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact or near-exact match with next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            // reward proportionally to how much of post_residual the next item consumes
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
        } else {
            // next item cannot use this residual: penalize dead space severity
            let waste_ratio = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 25.0 * waste_ratio;
        }
    }

    // Compare residual against mean residual across open bins:
    // prefer bins with residual close to item size (tight fit), penalize outliers.
    let tightness = (bin_residual as f64 - item_size as f64) - (mean_residual - item_size as f64);
    score += 0.15 * tightness.abs();

    // Penalize very small leftover dead space that is likely unusable
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Favor filling bins that are already relatively full
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fullness;

    // Late in the stream, be more aggressive about closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight penalty for spreading across too many open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively as stream progresses.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * (0.5 + progress);

    // Penalize leaving dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good: lookahead item can still fit here; reward proportionally.
            score -= 4.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // Dead space relative to lookahead; penalize especially if gap is small.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
        // Extra incentive when bin residual is large enough to matter.
        if bin_residual as f64 > mean_residual {
            score -= 8.0;
        }
    }

    // Mild penalty when many bins are open and this one is relatively full
    // (prefer filling fuller bins, keeping roomier bins flexible).
    if open_bins_count > 1 {
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 3.0 * fill;
    }

    // New-bin candidate (empty bin): make it unattractive unless the item fits
    // very poorly anywhere else, i.e., post_residual tiny but item nearly fills bin.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 30.0;
        // Allow new bin when item is large relative to capacity (poor fit candidates elsewhere).
        let large_item = item_size as f64 / bin_capacity as f64;
        if large_item > 0.7 {
            score -= 20.0 * (large_item - 0.7) / 0.3;
        }
        // Late in the stream, opening new bins is fine since leftovers are less reusable.
        if progress > 0.8 {
            score -= 10.0 * (progress - 0.8) / 0.2;
        }
    }

    // Global state coupling: when mean residual is low, conserve space tightly.
    let mean_ratio = mean_residual / bin_capacity as f64;
    score += 5.0 * mean_ratio * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Reward tight fits: small post_residual relative to capacity, amplified non-linearly.
    let pr_frac = post_residual as f64 / cap;
    let tightness = (1.0 - pr_frac).powi(3);
    score -= 12.0 * tightness * (1.0 + progress);

    // Penalize dead space: quadratic in wasted residual, scaled by mean residual pressure.
    let waste = pr_frac * pr_frac;
    score += 8.0 * waste * (1.0 + mean_residual / cap);

    // Non-linear coupling of item size with progress: large items early prefer open bins.
    let item_frac = item_size as f64 / cap;
    let size_coupling = item_frac * (1.0 - item_frac) * 4.0; // peaks at mid-size items
    score -= 5.0 * size_coupling * (1.0 - progress);

    // Lookahead: if next item fits the post-residual, reward this bin smoothly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 6.0 * snug * snug;
    } else if next_item_size > post_residual {
        score += 3.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - pr_frac);
    }

    // New-bin candidate: penalize opening a new bin, more so as stream progresses,
    // unless it would be a very tight fit for the lookahead chain.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
        if next_item_size > 0 {
            let chain = (item_size as f64 + next_item_size as f64) / cap;
            score += 15.0 * (chain - 1.0).abs();
        }
    }

    // Mild dispersion penalty: prefer bins whose residual deviates from the mean
    // in a non-linear (cubic) fashion to consolidate similar residuals.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space is residual too small to
    // hold any plausible future item. Classify by capacity fractions.
    let quarter = bin_capacity / 4;
    let tenth = bin_capacity / 10;
    if post_residual > 0 {
        if post_residual < tenth {
            // Unusable sliver: strong penalty (waste).
            score += 60.0;
        } else if post_residual < quarter {
            // Small pocket: mild penalty unless it exactly matches next item.
            if next_item_size != post_residual {
                score += 15.0;
            }
        }
    }

    // Reward if the lookahead item exactly fills the post-residual (chained fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 200.0;
    }
    // Reward if lookahead fits into post_residual (keeps chain alive).
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 25.0;
    }
    // Penalize if post_residual cannot hold the lookahead item (dead-end risk),
    // scaled by how far off it is.
    if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Tight-fit reward: item fills most of the bin's current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.75 {
        score -= 40.0 * fill_ratio;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless post_residual would be a tiny sliver).
    if fitting_bins_count == 1 && post_residual >= tenth {
        score -= 80.0;
    }

    // New-bin candidate (empty bin): make it attractive only when this bin
    // would leave a bad residual or when many bins are open with slack.
    if bin_residual == bin_capacity {
        // Baseline moderate score; adjust by stream position and mean slack.
        score = 30.0 + mean_residual * 0.3;
        if post_residual >= quarter {
            score -= 10.0; // fresh bins keep large flexibility
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= (bin_capacity - next_item_size) as f64 * 0.1;
        }
    }

    // Prefer bins whose residual is below the mean (consolidate slack).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for "dead space": gaps too small for the smallest plausible item
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0; // exact fill: perfect
    } else if post_residual < next_item_size && next_item_size > 0 {
        // gap cannot hold the next item: dead space unless tiny
        score += 6.0 + 0.5 * post_residual as f64;
    }

    // Reward tight fits (small post_residual) super-linearly
    score -= 12.0 * (-post_residual as f64 / 10.0).exp();

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Pressure from number of open bins: discourage proliferation,
    // but only mildly so tight fits still win
    score += 0.35 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: baseline cost of opening a bin
    if bin_residual == bin_capacity {
        score += 8.0;
        // opening a new bin is fine if no tight fit exists elsewhere
        if fitting_bins_count == 0 {
            score -= 12.0;
        }
        // with lookahead, opening a bin whose residual fits the next item is good
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    // Slight preference to keep mean residual balanced
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward bins where next item fits the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = post_residual - next_item_size;
        score -= 60.0 + leftover_after_next as f64 * 0.4;
        if leftover_after_next == 0 {
            score -= 120.0; // exact two-item packing
        }
    } else if next_item_size > 0 {
        // penalize dead space that next item cannot use
        score += (next_item_size as f64 - post_residual as f64).max(0.0) * 0.5;
    }

    // Compare residual to mean: prefer using fuller-than-average bins
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Prefer keeping small residuals consolidated; penalize opening new bin
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.5;
    }

    // Tightness coupling: reward filling a large fraction of current residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 40.0;

    // Late in stream: be greedier about closing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is excellent.
    score -= (1.0 - post_residual as f64 / cap) * 12.0;

    // Heavily penalize leaving dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny sliver: nearly unusable
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: bonus if next item exactly fits post_residual (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // Next item won't fit here; slight penalty for blocking it.
            score += 5.0;
        }
    }

    // Prefer filling bins with large residuals when many bins are open (consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let residual_ratio = bin_residual as f64 / cap;
    score += (residual_ratio - mean_residual / cap).abs() * 8.0 * (1.0 - progress);

    // Prefer bins already below mean residual early (keep big bins for big items),
    // but late in the stream just fill anything tightly.
    if residual_ratio > mean_residual / cap {
        score += 6.0 * (1.0 - progress);
    }

    // Mild penalty for opening a new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let decent_fit_elsewhere = fitting_bins_count > 0 && post_residual <= 20;
        if !decent_fit_elsewhere {
            score -= 15.0;
        } else {
            score += 10.0;
        }
    }

    // Discourage wasting a nearly-full bin on a small item.
    if item_size < 30 && residual_ratio < 0.35 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual

    // Smooth polynomial base: reward tight fits (small post_residual) with non-linear coupling
    let mut score = 3.0 * x - 2.2 * x * x + 1.4 * x * x * x;

    // Dead-space penalty: residuals too small to fit anything useful (min item 1..100 unknown, use mean_residual as scale)
    let dead_threshold = (mean_residual * 0.12 + 1.0).min(20.0);
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) / dead_threshold * 4.0;
    }

    // Lookahead: penalize if next item could have used this residual better
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt <= pr) && (nxt > item_size as f64) {
            score += 2.0 * (nxt - item_size as f64) / cap;
        }
        // reward if post residual still fits next item (chaining)
        if nxt <= pr && nxt <= item_size as f64 {
            score -= 1.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0 * (1.0 - progress);
    }

    // Stream progress: later in the stream, prefer consolidating into existing bins
    score -= 2.0 * progress * (1.0 - pr / cap);

    // Prefer bins with residual near the item (best-fit flavor) via smooth coupling
    let fit_tightness = 1.0 - (pr / (bin_residual as f64 + 1.0));
    score -= 1.5 * fit_tightness * fit_tightness;

    // Many open bins: discourage spreading, favor filling existing ones
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * x;

    // New-bin candidate: make empty bin moderately attractive only when current fit is terrible
    if bin_residual == bin_capacity {
        score = 2.0 + 6.0 * (1.0 - fit_tightness) + 3.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which quarter of the bin it falls in.
    let quarter = post_residual / (bin_capacity / 4).max(1);
    score += match quarter {
        0 => -60.0,                 // nearly full bin: excellent fit, strongly reward
        1 => -25.0,                 // leaves <=25 dead space: good
        2 => 5.0,                   // mediocre
        _ => 25.0 + post_residual as f64 * 0.2, // large hole: penalize
    };

    // Exact-fit harmonics via modulo: post_residual divisible by small ints is
    // more likely reusable by future items of common sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 18.0; }
        else if post_residual % 5 == 0 { score -= 8.0; }
        else { score += 6.0; }
    }

    // Lookahead coupling: does the next item fit the resulting hole?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains perfectly -> big reward, stronger the tighter it is
            let tight = (post_residual - next_item_size) as f64;
            score -= 30.0 - tight * 0.3;
        } else {
            // next item won't fit: the hole becomes dead space for k=2
            score += 12.0 + (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the item
    // is large relative to capacity (poor fits elsewhere justify it).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        score = 90.0 - frac * 70.0;
        if fitting_bins_count == 0 { score -= 100.0; }
        if fitting_bins_count == 1 { score += 30.0; }
        // late in stream, prefer closing out existing bins
        score += (step_index as f64 / total_items.max(1) as f64) * 20.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    // Tie-break toward bins below mean residual (balance load).
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // realistic future item (1..=10) are pure waste — penalize quadratically.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual) as f64 * (11 - post_residual) as f64 * 3.0;
    }

    // Reward near-perfect fits strongly (post_residual close to 0).
    if post_residual <= 5 {
        score -= 25.0 - (post_residual as f64) * 5.0;
    }

    // If the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (post_residual as f64 - next_item_size as f64).max(0.0) * 0.2;
    } else if next_item_size > 0 {
        // Next item won't fit here: slightly penalize leaving a mid-gap.
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, minus its perfect
        // flexibility (full residual is valuable early, less so late).
        score += 20.0 + pressure * 2.0 - progress * 15.0;
    } else {
        // Existing bins get a mild pressure-consistent tiebreak toward
        // filling the emptiest useful space first.
        score += (mean_residual - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * next_item_size as f64;
    }
    // Penalize post-residuals just below the next item size (dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Tight fits are excellent: small post residual relative to mean
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;
    if (post_residual as f64) < mean_residual * 0.5 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Discourage opening a new bin when a decent fit exists among open bins
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin still good if it sets up next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual.
    score -= 6.0 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(3);

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (next_item_size as f64 / post_residual as f64).min(1.0));
        } else {
            // Penalize leaving a residual too small for the next item (dead space risk).
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: pure tightness matters most.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when many bins are open (amortization favors reuse).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // But if open bins would leave huge dead space, soften the penalty.
        let waste = (mean_residual - item_size as f64).max(0.0);
        score -= 0.15 * waste;
    }

    // Prefer bins whose residual is already below average (consolidate waste).
    score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);

    // Mild penalty for very large leftover fragments that likely become dead space.
    if post_residual > 0 && post_residual < 10 {
        score -= 4.0; // tiny leftover is fine (near-perfect fit)
    } else if post_residual >= 10 && post_residual < 25 {
        score += 2.0; // awkward mid-range fragment
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / (total_items as f64).max(1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: wasted space, mildly discounted as stream progresses (waste matters more later).
    let mut score = post * (0.6 + 0.6 * t * t);

    // Smooth non-linear coupling: strongly penalize large residuals, but reward
    // near-full fills via a saturating term (1 - norm_post^3).
    score -= 12.0 * (1.0 - norm_post * norm_post * norm_post);

    // Penalize tight fits only mildly when the next item can use the leftover;
    // smooth interaction between post_residual and next_item_size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = post - next;
        if gap >= 0.0 {
            // next item fits exactly into post_residual: reward perfect chaining.
            score -= 6.0 * (1.0 - (gap / cap).powf(2.0));
        } else {
            // post_residual too small for next item: dead-space penalty, smoothed.
            score += 5.0 * ((-gap / cap) * (-gap / cap));
        }
    }

    // Scarcity bonus: when few bins fit, prefer this one (smooth 1/n coupling).
    if fitting_bins_count > 0 {
        score -= 4.0 / fitting_bins_count as f64;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Mean-residual coupling: if this bin's post-residual deviates below the mean,
    // it's a good compaction; reward proportionally (smooth quadratic).
    let dev = (mean_residual - post) / cap;
    score -= 3.0 * dev;

    // New-bin candidate: penalize opening new bins when many bins are open,
    // with a smooth saturating term; relax late in the stream.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 10.0 * (1.0 - (-open_f / (4.0 + 4.0 * t)).exp());
    }

    // Tiny smooth tie-breaker on item size (larger items prefer tighter bins).
    score += 0.5 * norm_item * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity fractions (1/8 granularity).
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as i32; // 0..8

    // Reward tight fits: post_residual near zero is best.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 12 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    } else {
        // Penalize dead space: residuals that no typical item (1..100) can fill well.
        // Residual classes 3/8..6/8 (37..75) are awkward: too big to waste, too small for big items.
        if class >= 3 && class <= 6 {
            score += 20.0 + 8.0 * (class as f64 - 2.0);
        }
    }

    // Coupling with next item: reward leaving residual that the NEXT item can exactly/nearly fill.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 80.0; // chains perfectly
        } else if gap <= 10 {
            score -= 30.0;
        } else if gap <= 25 {
            score -= 12.0;
        }
        // Harmonic divisibility: residual is a multiple of next item's likely companions
        if post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this residual: mild penalty proportional to overshoot class.
        let over = next_item_size - post_residual;
        if over <= 20 {
            score += 8.0;
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is only good when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: keep it slightly worse than a decent fit.
        score += 35.0;
        // But if many open bins are fragmented (high mean residual spread), fresh bin is fine.
        score -= 0.15 * open_bins_count as f64;
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // If item is large, a fresh bin is attractive (avoids fragmentation).
        if item_size > 60 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual is far below the mean (they are "nearly done"); keep mean-residual bins for future.
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Small tie-breaker on bin fullness to prefer fuller bins.
    score -= 0.02 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for small unusable gaps (dead space that no item 1..100 can pair with well)
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 60.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
    }

    // Reward tight fits
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // If this is the only fitting bin, strongly favor using it (last chance)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Pressure from number of open bins: prefer consolidating when many bins are open
    score += 4.0 * open_bins_count as f64;

    // Prefer bins with residual below mean residual (denser bins first)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Lookahead: if next item fits in the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }
    // Penalize leaving a gap that just barely fails to fit the next item
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin fits well
    if bin_residual == bin_capacity {
        let open_pressure = 6.0 * open_bins_count as f64;
        score = 120.0 + open_pressure - 30.0 * fill_ratio;
        if fitting_bins_count == 0 {
            score -= 300.0; // no alternative: new bin is fine
        }
        if fitting_bins_count == 1 {
            score += 60.0; // an open bin is a last chance; keep it alive
        }
        // Late in the stream, avoid spreading out
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead fit: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // perfect chain: item + next item fill bin exactly
        } else {
            score -= 40.0 * (-diff / 20.0).exp(); // graded lookahead reward
        }
        // Penalize post_residual that is small but not equal to next item (dead space)
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: strongly prefer tightest fit
        score -= 30.0;
    }

    // Compare post_residual to mean residual: leaving near-mean residual is neutral,
    // leaving much less (tight fit) is good.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could fit, unless current open bins
    // are very full (low mean residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        if mean_residual < 25.0 && next_item_size > 0 {
            score -= 30.0; // open bins nearly full: new bin justified
        }
    }

    // Slight preference for bins with larger residual (more room to consolidate)
    score -= 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale by relative fill of the bin.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 6.0 * fill * fill;

    // Penalize dead space: residual too small to ever hold a typical item.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score -= 50.0; // perfect fit bonus
    } else if post_residual < item_size.min(20).max(1) {
        score += 8.0; // leftover sliver unlikely to be reused
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; large post_residual wasted
            score += 0.02 * (post_residual as f64 - next_item_size as f64).max(0.0);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // heavily reward using it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // base penalty so full open bins are preferred unless they're bad
        score += 10.0;
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // many open bins with large mean residual: reuse them
        score += (open_bins_count as f64).sqrt() * 1.5;
        score += (mean_residual / bin_capacity as f64) * 12.0;
    } else {
        // mild bonus for using bins that are already open and fragmented
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins whose residual is close to the item (best-fit sharpening).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 15.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let p = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p2 = p * p;

    // Fit tightness: fraction of bin filled by this item
    let fill = item_size as f64 / bin_capacity as f64;
    let tight = 1.0 - post_residual as f64 / bin_capacity as f64;

    // Reward tight fits, more strongly as stream progresses (smooth polynomial coupling)
    score -= 60.0 * fill * fill * (0.5 + p);
    score -= 40.0 * tight * tight * p2;

    // Penalize residual waste relative to capacity (dead space), amplified late
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste * waste * waste * (0.3 + 0.7 * p);

    // Lookahead: reward if next item fits into post_residual (smooth interaction)
    if next_item_size > 0 {
        let next_fit = if post_residual > 0 {
            (next_item_size as f64 / post_residual as f64).min(1.0)
        } else { 1.0 };
        if next_item_size as f64 <= post_residual as f64 {
            score -= 30.0 * (1.0 - next_fit) * (0.4 + 0.6 * p);
        } else {
            // Penalize residuals too small for the next item
            let gap = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
            score += 20.0 * gap * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 - waste) * (0.5 + 0.5 * p);
    }

    // Mild penalty when many bins are open and residual is far above mean (fragmentation)
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev * (1.0 + p2) / (1.0 + open_bins_count as f64);

    // Prefer existing bins over opening new ones, more so early in the stream
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * (1.0 - p);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual modulo capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity remaining

    // Dead-space penalty: residuals that no item (1..=100) can use well
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // unusable sliver
    }

    // Modulo classes: residuals congruent to common item sizes are reusable
    let common: [u32; 12] = [10, 15, 20, 25, 30, 33, 40, 50, 60, 70, 75, 80];
    let mut best_diff = 100i64;
    for &c in common.iter() {
        if post_residual >= c {
            let d = (post_residual - c) as i64;
            if d < best_diff { best_diff = d; }
        }
    }
    score += best_diff as f64 * 0.5;

    // Perfect-fit harmonic reward: post_residual exactly matches a common size
    if common.contains(&post_residual) {
        score -= 8.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    }

    // Integer-division threshold on post_residual / next_item_size
    if next_item_size > 0 && next_item_size <= post_residual {
        let k = post_residual / next_item_size; // how many next items fit
        score -= k as f64 * 6.0;
        // extra reward if next item fits exactly
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot use this residual: penalize proportional to waste
        score += (next_item_size as f64 - pr).min(cap) * 0.3;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Tightness reward: prefer bins that were already tight before placement
    let pre_frac = bin_residual as f64 / cap;
    score += pre_frac * 4.0;

    // New-bin candidate: penalize moderately so it's chosen only when nothing fits well
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * (open_bins_count as f64).sqrt();
    }

    // Mild exploration term over stream progression (harmonic phase)
    let phase = (step_index as f64 / total_items.max(1) as f64) * std::f64::consts::PI;
    score += phase.sin() * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item (>=1) can use are pure waste.
    if post_residual > 0 {
        // unusable-ish small gap: below the minimum item size band -> heavy penalty
        if post_residual < 10 {
            score += 40.0;
        } else if post_residual <= 20 {
            score += 15.0;
        }
        // dead-space ratio penalty (non-linear)
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score += (1.0 - fill_ratio) * (1.0 - fill_ratio) * 30.0;
    } else {
        // perfect fit: strong reward
        score -= 60.0;
    }

    // Reward bins that can also host the lookahead item after this placement (k=2 chaining)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // this placement strands space the next item could otherwise use elsewhere
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading into new/partially-filled bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // Prefer bins whose residual is close to this item (tightest fit orientation)
    score += ((bin_residual - item_size) as f64 - mean_residual).abs() * 0.1;

    // New-bin candidate: only attractive when no open bin fits well or bins are saturated
    if bin_residual == bin_capacity {
        let saturation = mean_residual / bin_capacity as f64;
        // base penalty so existing bins usually win
        score += 20.0;
        // but if open bins are nearly full / few fit, opening is cheap
        if fitting_bins_count == 0 || saturation < 15.0 {
            score -= 30.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    if next_item_size > 0 {
        // 2-step lookahead: reward when next item fits perfectly into post_residual.
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= (bin_capacity as f64 - gap) * 0.6;
            if gap == 0.0 {
                score -= 60.0; // perfect 2-step match
            }
        } else {
            // Next item won't fit here: penalize small dead residuals.
            let waste = post_residual as f64;
            score += waste * 0.5;
            // Extra penalty if residual is small and unusable (dead space).
            if post_residual < 10 {
                score += 50.0;
            }
        }
        // If current bin could chain both items nearly perfectly.
        if item_size + next_item_size <= bin_residual {
            let chain_gap = (bin_residual - item_size - next_item_size) as f64;
            score -= (bin_capacity as f64 - chain_gap) * 0.3;
        }
    } else {
        // Last item: strongly prefer minimal residual.
        score -= (bin_capacity as f64 - post_residual as f64) * 1.0;
    }

    // Relative-to-mean coupling: bins below mean residual are tighter, prefer them.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual <= 10 {
            score -= 40.0; // near-perfect fill, definitely use it
        }
    }

    // New-bin candidate (empty bin): make it attractive only when the item
    // is large or existing fits are poor.
    if bin_residual == bin_capacity {
        score = item_size as f64 * 1.2 + 20.0;
        if item_size >= 60 {
            score -= 25.0; // large items start fresh bins
        }
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // Late in the stream, prefer closing out open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Slight preference to spread load when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 45.0 * tight * tight;

    // Perfect fit gets a strong discount.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward if the next item fits into the post-residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after = post_residual - next_item_size;
        score -= 18.0 * (1.0 - slack_after as f64 / cap);
    }
    // Penalize if next item is large and this placement strands space it could use.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Penalize scattering across many open bins when residuals are already large.
    if open_bins_count > 2 {
        score += 2.5 * (open_bins_count as f64).ln() * (mean_residual / cap);
    }

    // Prefer bins whose residual is close to the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Early stream: be a bit greedy about filling; late stream: consolidate harder.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * t * tight;

    // New-bin candidate (empty bin): make it expensive so it is chosen only
    // when no open bin offers a decent fit (post_residual == item_size there).
    if bin_residual == bin_capacity {
        score = cap + 30.0 - 20.0 * tight + 15.0 * (1.0 - t);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth quadratic penalty for mid-range residuals (awkward dead space)
    let awkward = pr_norm * (1.0 - pr_norm);
    score += 40.0 * awkward * (1.0 - progress);

    // Reward tight fits (small post_residual) with a super-linear bonus
    score -= (1.0 - pr_norm).powi(3) * 25.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Penalize bins that are outliers vs mean residual (prefer homogeneous fills)
    score += 0.3 * (pr - mean_residual).abs();

    // Lookahead coupling: if the next item fits exactly into post_residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if gap < 1.0 {
            score -= 35.0;
        } else {
            score += 0.15 * gap * (1.0 - progress);
        }
    }

    // Mild penalty for proliferating open bins late in the stream
    score += 0.5 * open_bins_count as f64 * progress;

    // New-bin candidate: keep it neutral-to-slightly-high unless residual-based terms favor it
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: waste buckets via integer division.
    let cls = post_residual / 10; // 0..10 harmonic class
    // Dead-space penalty grows super-linearly for small unusable residuals.
    if post_residual > 0 {
        // residual that no future item (min size 1) can pair with is worst;
        // penalize residuals in awkward middle classes (e.g. 1..=9 mod classes)
        let awkward = (post_residual % 10) as f64;
        score += awkward * 0.35;
    }
    // Reward tight fits strongly.
    score -= (item_size as f64 / cap) * 18.0;

    // Harmonic pairing: if next item exactly fills post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next fits here: reward proportionally to fill ratio
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot use this residual: penalize large leftover
            score += 6.0 * (next_item_size as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open new bin if existing fits are bad.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = cap * 0.9;
        if fitting_bins_count == 0 {
            score = 0.0; // must open
        } else if post_residual >= 60 {
            // plenty of room remains in existing bins; discourage new bin
            score += 20.0;
        } else if next_item_size > 0 && next_item_size >= post_residual {
            // lookahead suggests big item coming; fresh bin useful
            score -= 15.0;
        }
        // early stream: prefer consolidating into few bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 10.0;
    }

    // Prefer bins with residual near mean (balance load) mildly.
    score += ((post_residual as f64 - mean_residual) / cap).abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else {
        score += 0.05 * post_residual as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead space is worse if it cannot host the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 40.0;
        if poor_fit {
            score -= 25.0;
        } else {
            score += 35.0;
        }
    }

    // Late in stream, tighten up: prefer filling existing bins fully.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect 2-step fit: big bonus.
        if diff < 0.5 {
            score -= 60.0;
        } else if post_residual as f64 > nxt {
            // Next item still fits here: mild bonus proportional to closeness.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize wasted lookahead potential.
            score += 10.0 * (diff / bin_capacity as f64);
        }
    } else {
        // Last item: only tightness matters.
        score -= 5.0;
    }

    // Penalize post_residual that is unusably small (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins tighter than the mean residual (good fits first).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Mild pressure against opening new bins when many bins are open and stream is progressing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream matures and open bins exist.
        score += 15.0 + 25.0 * progress + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward near-perfect fits (small dead space)
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize dead space relative to mean residual: leaving a residual that
    // no future item (min size 1, typical >10) can use is wasteful.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // awkward sliver
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; discourage it
    // unless it enables a perfect fit for the pair (item + next item).
    if is_new_bin {
        let pair_exact = next_item_size > 0 && (item_size + next_item_size) == bin_capacity;
        if pair_exact {
            score -= 40.0; // fresh bin perfectly packs the pair
        } else {
            score += 15.0
                + 5.0 * open_bins_count as f64 * (0.5 + 0.5 * t)
                - 0.05 * mean_residual;
        }
    } else {
        // Mild reward for keeping bins balanced / consolidating residual mass
        score -= 0.02 * (bin_residual as f64 - mean_residual).abs().recip().min(5.0);
    }

    // Early in the stream, be slightly more willing to spread items (hedge);
    // late in the stream, consolidate tightly.
    score *= 1.0 + 0.1 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, smoothed by quadratic coupling with progress
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Non-linear polynomial interaction of post_residual with stream progress:
    // late in the stream, tighter fits (small post_residual) are rewarded more strongly
    let tightness = 1.0 - pr_norm;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize large dead space more aggressively as the stream progresses (cubic coupling)
    score += 20.0 * pr_norm * pr_norm * pr_norm * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Mild penalty proportional to crowding of open bins
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + 2.0 * progress);

    // Lookahead: reward if next item fits well into the post residual (smooth coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (pr - nxt).abs();
        score -= 10.0 * (1.0 - fit_gap / cap).max(0.0) * (0.5 + 0.5 * progress);
        // Penalize if next item would leave a very small residual (fragmentation risk)
        if pr >= nxt {
            let future_post = (pr - nxt) / cap;
            score += 15.0 * future_post * (1.0 - future_post) * (1.0 - progress);
        }
    }

    // Deviation from mean residual: prefer bins whose post residual aligns with fleet mean (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (0.5 + 0.5 * (1.0 - progress));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: reward post_residual values that are "friendly"
    // for future items (multiples of common size classes).
    let pr = post_residual;
    let mut bonus = 0.0;

    // Perfect fit is ideal.
    if pr == 0 {
        bonus -= 500.0;
    } else {
        // Class of post_residual modulo common item-size harmonics.
        // Residuals divisible by 10/25/50 are reusable by many size classes.
        if pr % 10 == 0 { bonus -= 8.0; }
        if pr % 25 == 0 { bonus -= 6.0; }
        if pr % 50 == 0 { bonus -= 6.0; }

        // Integer-division thresholds: classify residual into dead-space tiers.
        let tier = pr / 10; // 0..10
        match tier {
            0 => bonus += 25.0,          // 1-9: near-total dead space
            1 => bonus += 12.0,          // 10-19: hard to fill
            2 => bonus += 5.0,           // 20-29
            3 => bonus -= 3.0,           // 30-39: useful
            4 => bonus -= 5.0,           // 40-49
            5 => bonus -= 8.0,           // 50-59: very useful
            6 => bonus -= 6.0,
            7 => bonus -= 4.0,
            _ => bonus -= 2.0,
        }

        // Lookahead: reward residuals that exactly fit the next item.
        if next_item_size > 0 {
            if pr == next_item_size {
                bonus -= 120.0;
            } else if pr >= next_item_size {
                let rem = pr - next_item_size;
                // Reward small leftover after serving next item (harmonic remainder).
                if rem % 10 == 0 { bonus -= 10.0; }
                if rem < 10 { bonus += 8.0; }
            } else {
                // Next item cannot follow here; penalize small residuals more.
                bonus += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        bonus -= 60.0;
    }

    // New-bin candidate: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * 4.0 + mean_residual * 0.5;
        bonus += 30.0 + crowded.min(70.0);
    }

    // Late in the stream, tighten packing (dead space matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    bonus -= progress * (post_residual as f64) * 0.15;

    score += bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible future item (<= 10) are pure waste; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Residuals that cannot fit the lookahead item but could fit a generic small
    // item: mild penalty proportional to how "trapped" the space is.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Reward tight fits: fraction of bin consumed by this placement.
        let tightness = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * tightness;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading across
    // more bins; when few bins are open, filling them is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual deviates from the mean in a fillable direction
    // (larger residual bins get used first, keeping mean residual low).
    score -= 0.1 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive if the item is huge relative to
    // capacity or all open bins would leave tiny dead space.
    if bin_residual == bin_capacity {
        let huge = item_size as f64 / bin_capacity as f64 > 0.75;
        let poor_fit_everywhere = next_item_size > 0 && post_residual < next_item_size && post_residual > 0;
        if huge || poor_fit_everywhere {
            score -= 30.0;
        } else {
            score += 40.0;
        }
    }

    // Lookahead synergy: if the next item fits exactly into the post-residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space: leftover cannot host the next item -> penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.5;
    } else if next_item_size > 0 {
        // Leftover still usable for next item: mild reward scaled by slack
        score -= (post_residual - next_item_size) as f64 * 0.05;
    }

    // Reward placing into fuller (denser) bins relative to the mean residual
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Reward large items consuming big chunks of a bin
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: penalize so it only wins when fits are bad;
    // penalty softens late in the stream (fewer chances to consolidate)
    if bin_residual == bin_capacity {
        score += 35.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose leftover is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Exact or near-exact fills are gold.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Lookahead: penalize leaving a gap that the next item cannot use,
    // reward leaving a gap it can snugly use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap_after = post_residual - next_item_size;
            score -= 6.0;
            if gap_after < 10 {
                score -= 12.0;
            }
        } else {
            // next item won't fit in the leftover: mild penalty for dead space
            score += 4.0;
        }
        // If next item fits this bin too, keeping it alive is valuable
        if next_item_size <= bin_residual {
            score -= 3.0;
        }
    }

    // New-bin candidate logic: an empty bin is only attractive when
    // open bins are badly fragmented or this is a poor fit overall.
    if bin_residual == bin_capacity {
        // base reluctance to open new bins
        score += 22.0;
        // more open bins => more reluctance
        score += (open_bins_count as f64) * 2.5;
        // if mean residual is large (bins are roomy), no need for a new bin
        score += (mean_residual / bin_capacity as f64) * 15.0;
        // but if no existing bin fits well (post_residual large relative to others),
        // the empty-bin call naturally gets the tightness bonus of 100 residual,
        // which this penalty partially offsets when fragmentation is high.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // early in stream, opening bins is cheap and builds flexibility
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Mild preference for fuller bins when many bins are open (consolidation).
    score += (open_bins_count as f64) * 0.4 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to the item (minimal waste fraction).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let norm_pr = pr / cap;

    // Base: waste created by this placement, mildly damped at high fill.
    let mut score = pr.powf(1.15);

    // Reward tight fits (small post_residual) with a smooth non-linear term.
    score -= (1.0 - norm_pr).powi(3) * 0.8 * cap;

    // Stream-progress coupling: as the stream advances, penalize residual waste more
    // aggressively (late-stream slack is less likely to be recovered).
    let progress_coupling = progress * norm_pr.powf(0.75) * cap * 1.2;
    score += progress_coupling;

    // Interaction: post_residual vs mean residual — prefer bins whose resulting slack
    // is close to the fleet mean (keeps residuals homogeneous / reusable).
    let mean_gap = (pr - mean_residual) / cap;
    score += mean_gap.abs() * cap * 0.35;

    // Lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - (pr - nxt) / cap;
            score -= fit_quality.powi(2) * cap * 0.6;
        } else {
            // Next item cannot use the residual: penalize proportional to overflow need.
            score += ((nxt - pr) / cap).powf(1.3) * cap * 0.25;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 {
        score -= cap * 1.5;
    }

    // Mild penalty for opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += cap * (0.4 + 0.05 * open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual: which capacity fraction band does post_residual land in
    let frac = post_residual as f64 / cap;
    // Penalize dead space in the awkward band (0,10] and (50,60] — hard to fill later
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    }
    if post_residual > 50 && post_residual < 60 {
        score += 15.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Modulo-class logic: if next item exactly fills post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            // reward proportional to how well next item fits into the resulting space
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * next_fit;
            // harmonic class of leftover after next item
            let leftover = post_residual - next_item_size;
            if leftover <= 10 && leftover > 0 {
                score += 20.0; // leaves awkward sliver
            }
        } else {
            // next item cannot use this bin's residual; slight penalty if residual is large
            score += 0.05 * (post_residual as f64 - 20.0).max(0.0);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets baseline cost
    if bin_residual == bin_capacity {
        // prefer reusing open bins unless they'd leave big dead space
        score = cap - 5.0 + (post_residual as f64) * 0.1;
        if item_size as f64 > 0.8 * cap {
            score -= 20.0; // big item: fresh bin is fine
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        }
    }

    // Mild preference for tighter bins overall
    score += (mean_residual - post_residual as f64) * 0.1;

    // Progression-aware: early in stream, be slightly conservative about slivers
    let progress = step_index as f64 / total_items.max(1) as f64;
    if frac < 0.1 && post_residual > 0 {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small for the lookahead item are also weak spots, mildly penalized.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward tight fits (small post_residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bins pressure: prefer bins that keep the count of open bins from growing;
    // penalize opening new bins when open bins could fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 35.0 + 4.0 * open_bins_count as f64;
        // Late in the stream, opening new bins is even less desirable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Prefer bins whose residual is below mean (consolidating fuller bins),
    // leaving larger residuals in other bins for future items.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Lookahead synergy: reward bins where the next item also fits after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next_item_size exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0);

        // Perfect 2-chain: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item fits snugly after this placement (small slack).
        if next_item_size <= post_residual && post_residual - next_item_size <= 10 {
            score -= 25.0;
        }
        // Penalize leaving a gap that the next item cannot use.
        if next_item_size > post_residual {
            score += 10.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty discourages opening new bins when decent fits exist.
        score += 55.0;
        // If the item would leave a large dead space in every open bin, a fresh bin is fine.
        if post_residual < 20 {
            score -= 45.0;
        }
        // Perfect 2-chain in a fresh bin is very attractive.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 40.0;
        }
        // Late in the stream, avoid proliferating bins.
        score += 20.0 * progress;
    }

    // Penalize very small dead space that no future item (>=1) can use efficiently.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

