    score -= 3.0 * (-post_residual as f64 / 15.0).exp() * 10.0;

    // Penalize creating dead space that is too small for typical items,
    // unless the fit was perfect.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chaining effect).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / 40.0).max(0.0);
        } else {
