    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Prefer bins below the mean residual (fill emptier bins first keeps
    // tight bins available for tight items... but classic best-fit prefers
    // filling tightest first). Use mean to break ties toward tight bins.
    let mean_res_u = mean_residual;
    if (bin_residual as f64) < mean_res_u {
        score -= 1.5;
    } else {
        score += 0.5;
    }

    // New-bin candidate: penalize opening a new bin, but relax the penalty
    // when the item is large or stream is nearly done.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 14.0;
        // Large items leave less usable residual elsewhere; opening fresh bins
        // for very large items is often fine.
        new_bin_penalty -= (item_size as f64 / 100.0) * 6.0;
        // Late in the stream, avoid proliferating bins.
        new_bin_penalty += progress * 4.0;
        // Many open bins: discourage adding another.
        new_bin_penalty += (open_bins_count as f64).ln().max(0.0) * 1.5;
        score += new_bin_penalty.max(2.0);
    }

    // Mild preference to keep open-bin count from exploding.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    score += 8.0 * pr_norm * pr_norm * (1.0 + t);
    score -= 6.0 * pr_norm * (1.0 - t) * (1.0 - t);

    // Penalize dead space that is too small to be useful, weighted by progress
    let useless = if pr < next_item_size as f64 && next_item_size > 0.0 {
        (next_item_size as f64 - pr) / cap
    } else { 0.0 };
    score += 20.0 * useless * (0.5 + t);

    // Reward tight fits (small post_residual) more strongly early on
    score -= (1.0 - pr_norm).powi(3) * 5.0 * (1.0 - t);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Mild preference for bins deviating below mean residual (balance residuals)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev - 2.0 * dev * (1.0 - t);

    // Deter opening new bins when many bins are open and good fits exist
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * (1.0 - pr_norm) * (open_bins_count as f64).sqrt() * 0.1;
        // Opening a new bin is attractive if item is large relative to lookahead room
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: reward residuals that are "friendly" ---
    // Class A: post_residual == 0 (perfect fit) -> strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Class B: post_residual is a multiple of 10 -> cleanly reusable.
    else if post_residual % 10 == 0 {
        score -= 40.0;
    }
    // Class C: post_residual in 1..10 -> tiny dead space, mildly penalize.
    else if post_residual < 10 {
        score += 15.0;
    }
    // Class D: post_residual % 10 in 1..9 -> awkward remainder, penalize by remainder size.
    else {
        let rem = (post_residual % 10) as f64;
        score += rem * 2.0;
    }

    // Harmonic zone: residual divisible by 25 pairs well with mid-size items.
    if post_residual % 25 == 0 {
        score -= 25.0;
    }

    // --- Integer-division thresholds on next_item_size ---
    if next_item_size > 0 {
        // If the next item fits exactly in post_residual -> big reward.
        if next_item_size == post_residual {
            score -= 500.0;
        }
        // Next item fits with small waste (<=5) -> reward.
        else if next_item_size <= post_residual && post_residual - next_item_size <= 5 {
            score -= 120.0;
        }
        // Next item fits at all -> mild reward scaled by leftover harmony.
        else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 30.0 + (leftover % 10) as f64 * 1.5;
        }
        // Next item does NOT fit: post_residual becomes a waiting buffer.
        // Reward if it is large enough to be generally useful (>= 20).
        else if post_residual >= 20 {
            score -= 10.0;
        } else {
            score += 20.0;
        }
    } else {
        // Last item: minimize waste everywhere.
        score -= 50.0;
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // --- Mean residual coupling: penalize bins far from the mean residual ---
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.3;

    // --- Stream progression: early on, be greedy with tight fits; later, consolidate ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    // --- Open-bin pressure: many open bins -> favor filling existing bins over new ones ---
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when several open bins can already fit the item.
        score += open_bins_count as f64 * 12.0;
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    } else {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        // Larger usable leftovers are mildly rewarded.
        score -= 5.0;
    }

    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += (open_bins_count as f64) * 1.5;

    // Discourage bins whose residual is far above the mean (fragmented state),
    // but only mildly so tight fits elsewhere still win.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Lookahead: if next item would fit the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item leaves a tiny dead gap, penalize.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 15.0;
    }

    // New-bin candidate: default is worse than a decent existing fit,
    // but attractive when the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        score += 70.0;
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits in the post-residual (good lookahead compatibility)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here afterwards: penalize proportionally
        let miss = (next_item_size - post_residual) as f64;
        score += 15.0 * (miss / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent fits exist among open bins
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0; // new bin more attractive for big upcoming items
        }
    }

    // Tight fits are good: small post_residual relative to mean residual
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Late in the stream, consolidate: prefer bins with small residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor near-exact fills.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no plausible item can use.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { post_residual as f64 };
        score += 0.35 * dead;
    }

    // Lookahead synergy: reward bins whose leftover can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let synergy = (next_item_size as f64 / bin_capacity as f64).powf(0.7);
        score -= 14.0 * synergy;
    } else if next_item_size > post_residual {
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let mean_fit_quality = if mean_residual > 0.0 { item_size as f64 / mean_residual } else { 1.0 };
        let pressure = (open_bins_count as f64).ln().max(0.0);
        // Opening a new bin is penalized unless existing residuals are bad fits.
        let open_penalty = 22.0 - 8.0 * pressure;
        let fit_badness = (mean_fit_quality - 1.0).clamp(0.0, 1.5);
        score += open_penalty - 16.0 * fit_badness;
        // Late in the stream, prefer consolidating into open bins.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * t;
    }

    // Mild preference for filling fuller bins among comparable options.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post-residual, with non-linear penalty on dead space
    let mut score = pr;
    score += 40.0 * norm_pr * norm_pr * cap;

    // Stream-progress coupling: later in stream, prefer tighter packing (larger items, smaller residual)
    let prog_term = 1.0 + progress;
    score *= prog_term;

    // Reward bins whose post-residual matches the next item (lookahead chaining)
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64) / cap;
        score -= 25.0 * (-diff * diff * 8.0).exp();
        // Penalize residual that is too small to be useful at all
        let unusable = (norm_pr * 10.0).min(1.0);
        score += 15.0 * unusable * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 + 10.0 * progress;
    }

    // Many open bins: discourage spreading; prefer filling existing bins
    score -= 3.0 * (fitting_bins_count as f64).ln().max(0.0);

    // Coupling with mean residual: if this bin's residual deviates from mean, mild penalty
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Reward high fill ratio non-linearly
    score -= 30.0 * norm_item * norm_item * (1.0 + progress);

    // New-bin candidate: keep neutral baseline so it wins only when fits are poor
    if bin_residual == bin_capacity {
        score = cap * (1.0 + progress) + 10.0 * norm_next;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands in a "usable"
    // residue class (still able to hold small items) are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = post / cap;

    // Class thresholds via integer division of post_residual into harmonic bands.
    let band = post_residual / 10; // 0..=10 bands
    match band {
        0 => score -= 12.0,           // near-perfect fill
        1 => score -= 9.0,            // excellent
        2 => score -= 6.0,
        3 => score -= 3.0,
        4 => score -= 0.5,
        5 => score += 2.0,            // half-empty: mediocre
        6 => score += 4.0,
        7 => score += 6.5,
        8 => score += 9.0,
        9 => score += 11.0,           // large dead space
        _ => {}                       // fresh/empty bin band handled below
    }

    // Dead-space penalty: leftover too small for typical items (10..80 -> min 1 here).
    let min_item = 1.0f64;
    if post < min_item {
        score += 20.0;
    }

    // Lookahead coupling: reward if post_residual can still host next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Harmonic pair bonus: scaled by how snugly next item fits.
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 8.0 + 6.0 * snug;
        } else {
            // Leftover can't host the next item: penalize proportionally to waste.
            let waste = (next_item_size.saturating_sub(post_residual)) as f64;
            score += 4.0 + 3.0 * (waste / cap);
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin, more when
    // other bins fit and the stream is progressing.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = cap * 0.55 + 10.0 * progress;
        if fitting_bins_count > 0 {
            new_bin_score += 18.0 * (fitting_bins_count as f64).sqrt();
        }
        // Opening new bins early can pay off when many bins are open but mean
        // residual is low (fragmented state) — soften penalty then.
        if open_bins_count > 2 && mean_residual < cap * 0.25 {
            new_bin_score -= 12.0;
        }
        // If the item exactly fills a fresh bin, opening is attractive.
        if item_size >= bin_capacity * 9 / 10 {
            new_bin_score -= cap as f64 * 0.4;
        }
        score = new_bin_score;
    }

    // Mild global pressure: prefer filling already-open bins as they accumulate.
    score += 0.35 * open_bins_count as f64 * (frac);

    // Small tie-breaker toward bins tighter than the mean residual.
    score += 0.15 * (mean_residual - (bin_residual as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 80.0; // perfect fit, heavily rewarded
    } else {
        // Penalize large wasted gaps quadratically, scaled by capacity fraction.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * waste_frac * waste_frac;
    }

    // If a lookahead item can consume the post_residual exactly or nearly, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // gap can't fit the next item -> likely dead space
        score += 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 5.0 * open_bins_count as f64;
        // But allow new bin if existing fit is terrible (large post_residual).
        score -= 0.4 * post_residual as f64;
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it to avoid opening a bin.
        score -= 45.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a
    // "lonely" gap; filling it consolidates space.
    let res = bin_residual as f64;
    score -= 0.15 * (mean_residual - res);

    // Progress term: late in the stream, prefer tighter packs (less waste tolerated).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty when item barely fits but leaves awkward residual vs item size.
    if post_residual > 0 && post_residual < item_size {
        score += 8.0; // gap smaller than item: hard to reuse
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

