    score += 0.02 * open_bins_count as f64;

    // New-bin candidate: attractive only if no open bin gives a good 2-step fit.
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
