        let base_penalty = 18.0 + 10.0 * (1.0 - progress);
        // less penalty if open bins have little room on average
        let relief = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += base_penalty * (1.0 - 0.6 * relief);
        // prefer new bin when no existing bin fits well
        if post_residual == 0 {
            score -= 5.0;
        }
    }

    // Slight preference for fuller bins among open bins
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 4.0 * fill;

