    let mut score = pr;

    // non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = pr * (0.5 + 1.5 * p2 + 2.0 * p3);
    score += 0.02 * coupling;

    // tightness reward (small post_residual) amplified over time
    let tight = (cap - pr) / cap;
    score -= 3.0 * tight * tight * (0.3 + 0.7 * p2);

    // penalize large dead space non-linearly
    score += 0.001 * pr * pr * (1.0 + progress);

    // lookahead: reward leaving room for next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack_fit = (pr - nxt) / cap;
            score -= 1.5 * (1.0 - slack_fit * slack_fit);
        } else {
            score += 1.0 * (nxt - pr) / cap;
        }
    }

    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 2.0;
    }

    // discourage opening new bins when good fits exist
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * progress;
    }

    // spread pressure: prefer bins below mean residual early
    let dev = (pr - mean_residual) / cap;
    score += 0.5 * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of common small item sizes) are more valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward post_residuals that are harmonic with typical small item sizes.
    let harmonics: [u32; 6] = [10, 20, 25, 30, 40, 50];
    let mut harm_bonus = 0.0;
    for h in harmonics.iter() {
        if post_residual >= *h && post_residual % *h == 0 {
            harm_bonus += 6.0;
        }
    }
    score -= harm_bonus;

    // Penalize dead space: post_residual too small to fit the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Integer-division threshold: classify post_residual into deciles of capacity.
    let decile = (post_residual * 10) / bin_capacity;
    score -= decile as f64 * 1.5;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            // harmonic check on the double-fill leftover
            if gap == 0 || gap % 10 == 0 {
                score -= 12.0;
            } else if gap < 10 {
                score += 10.0;
            }
            score += gap as f64 * 0.3;
        } else {
            // next item won't fit here; leftover becomes terminal
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer tighter bins generally (relative fill).
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= fill * 10.0;

    // Mean-residual coupling: avoid leaving this bin far from the pack average.
    score += ((pr - mean_residual).abs()) * 0.15;

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * fill;

    // New-bin candidate bias: make empty bins slightly unattractive unless
    // nothing else fits well (post_residual == capacity means fresh bin).
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to be useful later are strongly penalized.
    // Items are >= 1, but gaps below a "useful threshold" are likely wasted.
    let useful_threshold: f64 = 25.0;
    if (post_residual as f64) < useful_threshold && post_residual > 0 {
        score += (useful_threshold - post_residual as f64) * 3.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward heavily
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty if we leave a big gap
        score += 2.0;
    }

    // Open bins pressure: penalize opening new bins / using many bins
    if bin_residual == bin_capacity {
        // New bin candidate: penalize proportionally to open bin count
        score += 10.0 + open_bins_count as f64 * 2.0;
    } else {
        // Slight reward for using existing bins as they accumulate
        score -= open_bins_count as f64 * 0.3;
    }

    // Mean residual coupling: prefer bins whose residual is close to the mean
    // (keeps residuals balanced, avoids fragmented tiny gaps)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // Progress-aware: early on, be more conservative about dead space (long stream ahead)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if (post_residual as f64) < useful_threshold && post_residual > 0 {
        score += (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        // Perfect chain (post_residual == next_item_size) is highly desirable.
        score -= (next_item_size as f64) * (1.0 + slack_after_next as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item cannot use this bin's leftover: penalize dead space creation.
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.25;
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable to fill exactly.
    let tightness = mean_residual - post_residual as f64;
    score += tightness * 0.15;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize leaving very small unusable slivers (< 10) unless next item consumes them.
    if post_residual > 0 && post_residual < 10 && !(next_item_size > 0 && next_item_size <= post_residual) {
        score += 20.0;
    }

    // Mild stream-progression adaptation: later in stream, prefer consolidating into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 5.0 * progress;
    } else {
        // New-bin candidate: only attractive when current bins are crowded.
        score += 8.0 * (1.0 - progress) + (open_bins_count as f64).sqrt() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalty grows dead-space cost.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize leaving a residual that cannot host the next item
    // (dead space), but reward residuals that can still fit it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // Reward leaving exactly enough room for the next item (chained fit).
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // New-bin candidate: only attractive when current bins are congested
    // or this bin would leave unusable fragments.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = mean_residual / bin_capacity as f64;
        // Penalize new bins mildly; the penalty shrinks when open bins are
        // fragmented (low mean residual) or many bins already open.
        score = bin_capacity as f64
            - 30.0 * (1.0 - congestion)
            - 0.5 * open_bins_count as f64
            + 10.0 * progress;
        // If the item is huge relative to typical residuals, new bin is fine.
        if item_size as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Mild preference for fuller bins overall.
    score -= 0.15 * (bin_residual - post_residual) as f64;

    // Time horizon: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Smooth non-linear base: reward tight fits via quartic decay of post-residual.
    let mut score = pr * (1.0 + fit_norm * fit_norm);

    // Polynomial coupling with stream progress: later in the stream, dead space
    // is increasingly penalized (quadratic in progress), favoring consolidation.
    let prog2 = progress * progress;
    score += 40.0 * prog2 * fit_norm;

    // Cubic interaction: tight fits (small post_residual) get extra reward late.
    score -= 30.0 * prog2 * (1.0 - fit_norm) * (1.0 - fit_norm);

    // Last-chance bonus: smooth sigmoid-like reward when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Discourage opening new bins when many bins are open and mean residual is large.
    let open_norm = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize relative to how well the item would fill it,
        // more strongly as mean residual across open bins grows.
        let fill = item_size as f64 / cap;
        score += 15.0 * (1.0 - fill) * (1.0 + open_norm) + 10.0 * (mean_residual / cap).min(1.0);
    } else {
        // Mild penalty for bins far from the mean residual (fragmentation aversion).
        let dev = (bin_residual as f64 - mean_residual).abs() / cap;
        score += 5.0 * dev * dev;
    }

    // Lookahead: if next item fits into post_residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 12.0 * (nx / cap) * (1.0 + progress);
        } else {
            score += 6.0 * ((nx - pr) / cap) * (1.0 - fit_norm);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: neutral-ish baseline; only wins when fits are poor.
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count > 0 {
            open_bins_count as f64 / (open_bins_count as f64 + 5.0)
        } else {
            0.0
        };
        let lookahead_waste = if next_item_size > 0 && next_item_size > bin_capacity {
            0.0
        } else {
            0.0
        };
        // Penalize new bin slightly more when many bins open and mean residual large.
        let mut nb = 55.0 + open_pressure * 40.0 + mean_residual * 0.15;
        // If this bin is the last chance, opening new is bad -> raise score.
        if fitting_bins_count == 1 {
            nb += 25.0;
        }
        // Late in stream, avoid opening bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        nb += progress * 20.0;
        score = nb + lookahead_waste;
        return score;
    }

    // Exact fit: overwhelming reward.
    if post_residual == 0 {
        return -1000.0;
    }

    // Harmonic class logic: classify post_residual by modulo classes.
    let m10 = post_residual % 10;
    let m5 = post_residual % 5;
    let div = post_residual / 10; // integer division threshold class

    // Small dead space classes are excellent (leave tiny unusable slivers).
    let class_bonus: f64 = match m10 {
        0 => -12.0,                 // perfectly divisible leftover
        1 => -8.0,                  // near-perfect
        2 => 2.0,
        3 => 4.0,
        4 => 6.0,
        5 => -6.0,                  // divisible by 5
        6 => 3.0,
        7 => 5.0,
        8 => 7.0,
        _ => 8.0,
    };
    if m5 == 0 {
        score -= 4.0;
    }

    // Dead-space threshold: leftovers below typical minimum item size are "sealed".
    if post_residual < 10 {
        score -= 15.0; // unusable sliver -> great outcome
    } else if post_residual < 20 {
        score -= 5.0;
    } else if post_residual > 60 {
        score += 10.0; // large leftover wastes the bin
    }

    score += class_bonus - div as f64 * 0.5;

    // Lookahead: does next item fit the post residual exactly / well?
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let nm = (post_residual % next_item_size.max(1)) as f64;
        score -= 6.0 - nm * 0.3; // reward bins that chain with next item
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty if leftover is in awkward class.
        if m10 >= 6 {
            score += 3.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else {
        score += 1.0;
    }

    // Prefer bins tighter than the mean (best-fit flavor).
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    // Late-stream consolidation: favor filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 2.0 + open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful again are heavily penalized (they are wasted capacity).
    let min_useful = if next_item_size > 0 { next_item_size.min(80) } else { 10 };
    if post_residual > 0 && post_residual < min_useful {
        // Dead space: penalty grows as the gap becomes less usable.
        let unusability = 1.0 - (post_residual as f64 / min_useful as f64);
        score += 40.0 + 60.0 * unusability;
    }

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Reward tight fits (small post_residual relative to item size).
        let tightness = post_residual as f64 / item_size.max(1) as f64;
        score += 10.0 * tightness;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here; mild penalty for stranding this bin.
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins when few
    // fitting bins exist (last-chance bins are precious).
    if fitting_bins_count <= 1 {
        score -= 25.0;
    } else {
        score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mild pressure proportional to number of open bins: prefer filling
    // existing bins over opening new ones as the bin count grows.
    score += 0.5 * open_bins_count as f64;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "nearly full" bin; finishing it off is good.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.2 * dev;

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Penalize the fresh bin unless the item is
    // large and the stream is early (plenty of future items to fill it).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let largeness = item_size as f64 / bin_capacity as f64;
        score += 55.0 - 30.0 * largeness - 20.0 * (1.0 - progress);
        if post_residual == 0 { score -= 50.0; } // full-capacity item: neutral
    }

    // Small stream-progress term: later in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let fit_ratio = (item_size as f64) / (bin_residual as f64);
    score -= 2.0 * fit_ratio * fit_ratio * (item_size as f64);

    // Penalize leaving dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers are wasted capacity
    }

    // Lookahead coupling: if next item fits in the post residual, reward heavily.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 6.0 + 0.05 * (next_item_size as f64);
        } else {
            score += 0.3 * (next_item_size as f64) * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins with residual below the mean (fill the emptier ones less).
    if bin_residual as f64 > mean_residual {
        score += 0.5 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - bin_residual as f64);
    }

    // Time horizon: early in the stream, keep bins balanced (open more bins),
    // late in the stream, pack tightly into whatever exists.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate handling: only attractive for large items early on.
    if bin_residual == bin_capacity {
        let early_bias = 1.0 - progress;
        let large_item_bonus = if item_size > bin_capacity / 2 { 1.0 } else { 0.0 };
        score = post_residual as f64 + 5.0
            - 12.0 * early_bias * large_item_bonus
            - (if fitting_bins_count == 0 { 20.0 } else { 0.0 });
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste term, mildly convex in post_residual
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; later, penalize them more.
    let prog_coupling = 1.0 + 0.8 * progress * progress + 0.6 * progress * (1.0 - progress);
    score *= prog_coupling;

    // Interaction: post_residual vs mean_residual — prefer bins tighter than average
    let mr = mean_residual.max(0.0);
    score += 0.25 * (pr - mr) * (1.0 + progress);

    // Smooth penalty when post_residual is small but nonzero (dead space)
    let dead = if pr > 0.0 && pr < item_size as f64 { 1.0 } else { 0.0 };
    score += dead * 6.0 * (1.0 - progress * 0.5);

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as i32 as f64;
        let next_frac = next_item_size as f64 / cap;
        score -= fits_next * (8.0 + 20.0 * next_frac) * (1.0 + 0.5 * progress);
        // penalize if post residual is just barely below next item (near-miss waste)
        let miss = if pr < next_item_size as f64 { (next_item_size as f64 - pr) / cap } else { 0.0 };
        score += miss * 10.0 * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + 0.5 * progress);
    }

    // New-bin candidate: prefer opening new bins early, less later
    if bin_residual == bin_capacity {
        score = cap as f64 * (1.2 - 0.7 * progress) + 3.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Mild congestion term
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by integer division.
    // Classes: 0 (perfect/very tight), then decile classes of capacity.
    let post_class = (post_residual * 10) / bin_capacity; // 0..=10
    let item_class = (item_size * 10) / bin_capacity;

    // Reward tight fits strongly (post_residual near 0 is best).
    score -= 40.0 * (-post_residual as f64 / 12.0).exp();

    // Harmonic penalty: leftover in "dead zone" classes (small, hard-to-fill remainders)
    // are penalized super-linearly via modular structure.
    if post_residual > 0 {
        let dead_zone = if post_class >= 1 && post_class <= 3 { 1.0 } else { 0.0 };
        score += 18.0 * dead_zone * (post_residual as f64 / cap_f);
        // Modulo coupling: leftover that is NOT a harmonic fraction of capacity is worse.
        let harmonic = |x: u32| -> bool {
            x == 0 || bin_capacity % x == 0 || bin_capacity % (x + 1) == 0
        };
        if !harmonic(post_residual) {
            score += 6.0;
        }
    }

    // Lookahead: if next item exactly fills the post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how much of the leftover it consumes.
            let fill = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 25.0 * fill;
        } else {
            // Next item cannot use this leftover; penalize large leftovers.
            score += 10.0 * (post_residual as f64 / cap_f);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual
    // spread across open bins. Penalize new bins unless current fit is bad.
    if bin_residual == bin_capacity {
        let waste = mean_residual * (open_bins_count as f64).sqrt();
        let bad_fit = post_residual as f64 > 0.35 * cap_f && next_item_size > post_residual;
        if !bad_fit {
            score += 45.0 + waste;
        } else {
            score += waste * 0.3;
        }
    }

    // Prefer bins whose residual is close to item_size (best-fit core, sharpened).
    let gap = (bin_residual - item_size) as f64;
    score += 0.35 * gap * gap / cap_f;

    // Slight preference for bins below mean residual (consolidate emptier bins).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Mild exploration bonus early in the stream for opening bins to diversify classes.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.1 && item_class >= 5 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to ever hold a future item
    // (assume minimum item size ~10) are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits strongly (small post_residual relative to item size).
    if item_size > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fill_ratio * fill_ratio;
    }

    // Penalize leaving gaps that don't match the lookahead item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect lookahead fit
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 10.0; // lookahead cannot use the remainder
        }
    }

    // Last-chance bonus: this is the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading;
    // with few open bins, opening a new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += 0.8 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: prefer it only when the fit would be terrible
    // (large leftover dead space) and many bins are open.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.5 * open_bins_count as f64;
        if item_size >= 60 {
            score -= 15.0; // big items start fresh bins happily
        }
    }

    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already encoded).

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize dead space proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    }

    // Relative-to-mean residual coupling: bins below mean residual are "tighter",
    // favor filling them; bins above mean waste potential.
    let dev = post_residual as f64 - mean_residual;
    score += 0.25 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large post_residual penalty for empty bin unless lookahead perfect).
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size == 0 || next_item_size > bin_capacity {
            score += 10.0;
        }
        // late in stream, prefer reusing open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Penalize leaving tiny unusable slivers (< min item size 1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Tight-fit reward: strongly favor small post_residual (non-linear).
    let tight = 1.0 - (post / cap);
    score -= 60.0 * tight * tight * tight;

    // Exact / near-exact fit jackpot.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let nxt_tight = 1.0 - ((post - nxt) / cap);
            score -= 50.0 * nxt_tight * nxt_tight;
            if (post - nxt) as u32 == 0 {
                score -= 100.0;
            }
        } else {
            // Next item won't fit here; residual is dead space for the horizon.
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Prefer bins whose residual is close to the mean (keep residuals homogeneous),
    // penalize outliers that fragment the state.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Early stream: be pickier (large residual waste matters over long horizon).
    // Late stream: accept decent fits to close out bins.
    let horizon = 1.0 - progress;
    score += 10.0 * post / cap * horizon;
    score -= 10.0 * (1.0 - horizon);

    // Many open bins: consolidate, penalize spreading into a fresh-ish bin.
    if open_bins_count > 4 {
        score += 0.5 * (open_bins_count as f64 - 4.0);
    }

    // NEW-BIN CANDIDATE handling: empty bin must lose unless existing fits are bad.
    if bin_residual == bin_capacity {
        score = cap * 1.5 + 100.0 - 30.0 * progress;
        // If no open bin fits well (large item), opening fresh is reasonable.
        if item > 0.6 * cap {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64 / bin_capacity as f64;
    let fill = 1.0 - pr;
    // non-linear coupling of post_residual with stream progress
    score += 8.0 * pr * pr * (0.5 + 0.5 * progress);
    // reward high fill ratio quadratically, amplified late in the stream
    score -= 6.0 * fill * fill * (0.3 + 0.7 * progress);
    // smooth interaction: item size vs residual, penalize near-miss dead space
    let it = item_size as f64 / bin_capacity as f64;
    score += 4.0 * (pr - it) * (pr - it);
    // lookahead coupling: if next item fits smoothly into post_residual, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64 / bin_capacity as f64;
        let slack = pr - nx;
        if slack >= 0.0 {
            score -= 5.0 * slack * (1.0 - slack) * (0.5 + 0.5 * progress);
        } else {
            score += 3.0 * (-slack) * pr;
        }
    }
    // last-chance bonus: only one fitting bin, avoid opening new bins
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 7.0 * (0.4 + 0.6 * progress);
    }
    // penalize scattering across many open bins, smoothly in open_bins_count
    score += 0.15 * (open_bins_count as f64).ln_1p() * pr;
    // deviation from mean residual: prefer bins near mean (balanced packing)
    score += 1.5 * (post_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    // new-bin candidate: mildly penalize so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score += 2.0 + 6.0 * progress * (1.0 - it);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals in "usable" classes
    // (residuals that likely fit future items: multiples of 10, or >= 10).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, excellent
    } else if pr < 10 {
        score += 40.0; // dead space below min item size
    } else {
        // modulo-10 harmonic class bonus
        let class = pr % 10;
        if class == 0 {
            score -= 8.0;
        } else {
            score += (10 - class) as f64 * 0.6;
        }
        // larger usable residual is mildly better
        score -= (pr as f64 / bin_capacity as f64) * 10.0;
    }

    // Lookahead: if next item fits in post_residual, reward strongly
    if next_item_size > 0 && next_item_size <= pr {
        score -= 25.0 + (next_item_size as f64) * 0.2;
    } else if next_item_size > 0 && next_item_size > pr {
        score += 10.0; // next item won't fit here
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Penalize opening new bins when decent open bins exist
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost of a fresh bin
        score = bin_capacity as f64 * 0.9;
        if fitting_bins_count == 0 {
            score = 0.0; // no alternative, must open
        } else if next_item_size > 0 && next_item_size <= bin_capacity - item_size
            && next_item_size > mean_residual {
            score -= 20.0; // open bin residuals can't hold next item
        }
        return score;
    }

    // Tightness coupling: bins with small residual relative to mean are
    // "nearly full" — favor filling them further
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    }

    // Late in the stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (1..=10) are pure waste -> heavy penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Tight-fit reward: post_residual very small relative to capacity is great.
    let tightness = post_residual as f64 / bin_capacity as f64;
    if tightness <= 0.05 {
        score -= 30.0;
    } else if tightness <= 0.12 {
        score -= 15.0;
    }

    // Penalize bins whose residual is barely above item_size (bad fit).
    let slack = (bin_residual - item_size) as f64;
    if slack > 0.0 && slack < 10.0 {
        score += 25.0 - 2.5 * slack;
    }

    // Reward using a bin whose residual closely matches the item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    score += 0.6 * open_bins_count as f64;

    // New-bin candidate handling: an empty bin should only win when the item
    // fits poorly everywhere else. Make empty-bin score high unless it's a
    // large item (which would otherwise leave awkward gaps elsewhere).
    if bin_residual == bin_capacity {
        score = 55.0 + 0.5 * open_bins_count as f64;
        if item_size >= 60 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 25.0;
        } else if gap < 10 {
            score -= 10.0;
        }
    }

    // Slight preference to fill older/more-full bins as stream progresses.
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead fit: strongly reward exact match for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Reward leftover that still accommodates the next item,
            // scaled by how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post-residual too small for the lookahead item: penalize dead space.
            score += 15.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: discourage spreading items, encourage consolidation.
    score += 0.3 * open_bins_count as f64;

    // Early in the stream, be slightly more willing to fill tight fits;
    // late in the stream, prefer minimal residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Penalize near-full-but-wasteful residuals slightly nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect or near-perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into post_residual, penalize if it
    // would leave this bin's leftover useless for the known next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // dead space relative to the known next item
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Crowding: with many open bins, prefer consolidating (favor existing bins
    // over opening new ones less aggressively); with few bins, be freer.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin is penalized more when mean residual across open
        // bins is large (wasted space already) and when many bins are open.
        score += 30.0 + 0.6 * open_bins_count as f64 + 0.5 * mean_residual;
        // Late in the stream, avoid spreading; early on, allow exploration.
        score += 25.0 * progress;
        // If item is large relative to typical residual, new bin is fine.
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
    } else {
        // Fitting into an existing bin is rewarded, more so when the fit is snug.
        let snugness = item_size as f64 / bin_residual.max(1) as f64;
        score -= 8.0 + 12.0 * snugness;
    }

    // Mild preference to fill bins with larger residual when several fit.
    if fitting_bins_count > 1 {
        score -= 0.1 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: non-linear polynomial in post_residual
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr) + 12.0 * norm_pr * norm_pr;

    // Coupling with stream progress: penalize residual more as stream advances
    score += 30.0 * norm_pr * (progress * progress);

    // Tight fit reward (small post_residual) grows with progress
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Lookahead: reward if next item can use the post_residual
    if next_item_size > 0 {
        let usable = if norm_next <= norm_pr { 1.0 - (norm_pr - norm_next) } else { 0.0 };
        score -= 20.0 * usable * norm_item * (1.0 + progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_item) * (1.0 + 0.5 * progress);
    } else {
        score += 3.0 * ((fitting_bins_count as f64 - 1.0).min(5.0) / 5.0);
    }

    // Mean residual coupling: penalize bins far from mean residual (wasted spread)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: make it slightly less attractive unless residuals are all poor
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress - 6.0 * norm_item;
    }

    // Mild penalty for many open bins
    score += 0.5 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that form "good" classes
    // (small, or exactly matching typical next-item sizes via modular structure).
    let pr = post_residual;
    if pr == 0 {
        score -= 500.0; // perfect fill
    } else if pr <= 5 {
        score -= 200.0;
    } else if pr <= 10 {
        score -= 100.0;
    } else {
        // Penalize dead space in harmonic bands
        let band = pr / 10; // integer division threshold class
        score += band as f64 * 8.0;
        // Modulo-classes: residuals divisible by common item sizes are reusable
        if pr % 10 == 0 { score -= 25.0; }
        if pr % 20 == 0 { score -= 15.0; }
        if pr % 25 == 0 { score -= 15.0; }
        if pr % 50 == 0 { score -= 20.0; }
    }

    // Lookahead: strongly reward post_residual that fits the next item exactly
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 300.0;
        } else if pr >= next_item_size {
            score -= 40.0;
            let slack = (pr - next_item_size) as f64;
            score -= (100.0 / (slack + 10.0)) * 10.0;
        } else {
            score += 30.0; // next item cannot use this residual
        }
    } else {
        // Last item: prefer zero residual
        score += pr as f64 * 0.5;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_ratio = (bin_capacity - item_size) as f64 / bin_capacity as f64;
        score = 400.0 + waste_ratio * 200.0;
        // late in stream, prefer consolidating into open bins
        score += (1.0 - progress) * 50.0;
        // if only this bin fits, opening new is fine
        if fitting_bins_count <= 1 {
            score -= 250.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && (bin_capacity - item_size) >= next_item_size {
            score -= 60.0; // new bin will serve next item too
        }
    }

    // Slight preference for fuller bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.1;
    // Tie-break with mean residual alignment
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever fit
    // another item (sizes >= 1, but practically small gaps are waste) are
    // heavily penalized.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Non-linear penalty on unusable mid-range gaps: a gap that cannot fit
    // typical upcoming items is worse than a large residual.
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // reward strongly (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, favor filling existing ones
    // over opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure.
        score += 10.0 + pressure * 2.0;
    } else {
        score -= pressure.min(8.0);
    }

    // Tight-fit reward: placing an item that nearly fills the bin is ideal.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 10.0;
    }

    // Mean residual alignment: prefer bins whose post_residual stays near mean
    // to keep flexibility, penalize extreme divergence.
    let divergence = ((post_residual as f64) - mean_residual).abs();
    score += divergence * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64));
        // exact match bonus
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // penalize leaving dead space that next item can't use but is small
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: prefer tightest fit
        score -= 20.0;
    }

    // Compare post_residual against mean residual of open bins
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Penalize leaving very small unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 15.0;
        // opening a new bin is attractive if item fits poorly everywhere
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    // Late in stream: prefer compacting into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins with less residual overall (tighter bins first)
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize large dead space relative to the smallest possible item (1).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // nearly-unusable sliver
    }

    // Lookahead: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted pairing chance
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when few open bins fit or mean residual is fragmented.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let fragmentation = (mean_residual / bin_capacity as f64 - 0.5).max(0.0) * 2.0;
        let base = 30.0
            + pressure * 80.0
            + fragmentation * 20.0
            + (open_bins_count as f64).sqrt() * 5.0;
        // Time horizon: late in the stream, prefer reusing bins more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += base * (1.0 - 0.4 * progress);
    }

    // Mild penalty for spreading across many open bins: encourage consolidation.
    score += 0.8 * open_bins_count as f64;

    // Slight preference for bins below mean residual (keeps balance).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Time-dependent tightness weighting: early stream, exploit tight fits harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 10.0 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // smooth polynomial coupling of residual with progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 40.0 * poly * cap;
    // penalize tight fits less as stream progresses
    let tight = 1.0 - norm_pr;
    score -= 25.0 * tight * tight * (0.5 + progress);
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 30.0;
    }
    // lookahead coupling: favor leaving room for next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        score -= 15.0 * (1.0 - (diff / cap).abs()).max(0.0);
    }
    // new-bin candidate: mild penalty unless residuals are fragmented
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (mean_residual / cap);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class decomposition of post_residual ---
    // Class 0: perfect fit (post_residual == 0) -> strongest reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Class 1: post_residual is a divisor-style "harmonic" of capacity
        // (capacity / k for k = 1..8): these residuals are maximally reusable
        let cap = bin_capacity as f64;
        let mut harmonic_bonus = 0.0;
        for k in 1..=8u32 {
            let h = bin_capacity / k;
            if post_residual == h {
                harmonic_bonus = 60.0 / k as f64;
            }
        }
        score -= harmonic_bonus;

        // Class 2: modulo arithmetic on post_residual in [1,100]
        let pr = post_residual;
        // multiples of 10 are "aligned" classes -> reusable by typical items
        if pr % 10 == 0 {
            score -= 25.0;
        }
        // multiples of 5 secondary alignment
        else if pr % 5 == 0 {
            score -= 10.0;
        }
        // odd tiny fragments are dead space -> penalize via integer division tiers
        let tier = pr / 5; // integer division threshold
        if tier == 0 {
            score += 40.0; // residual < 5: nearly dead
        } else if tier <= 2 {
            score += 20.0; // residual 5..14: hard to fill
        }

        // --- Lookahead coupling: next_item_size harmonic match ---
        if next_item_size > 0 {
            if next_item_size <= pr {
                // next item fits here too: reward, stronger if exact harmonic fit
                score -= 35.0;
                if next_item_size == pr {
                    score -= 120.0; // chain of perfect fits
                } else if pr % next_item_size == 0 {
                    score -= 30.0;  // divisible chain: multiple future fits
                }
                // reward if next item lands post_residual in an aligned class
                let pr2 = pr - next_item_size;
                if pr2 % 10 == 0 {
                    score -= 20.0;
                } else if pr2 % 5 == 0 {
                    score -= 8.0;
                }
            } else {
                // next item does NOT fit here: if this bin would become the
                // only holder of the next item's class, mild penalty
                if next_item_size > pr && pr < 10 {
                    score += 15.0;
                }
            }
        }
    }

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // this is the only open bin that fits; avoid opening a new bin
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer tighter fit relative to other candidates
        // (implicit via post_residual, add small diversity term)
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // --- New-bin candidate logic ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit badly:
        // score it slightly worse than a decent existing fit but better than
        // a fragmented one. Base on open bin count and mean residual.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 55.0 + mean_residual * 0.3 + open_bins_count as f64 * 1.5;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            new_bin_score -= 10.0; // fresh bin can host next item too
        }
        if progress > 0.9 {
            new_bin_score += 15.0; // late stream: prefer consolidating
        }
        score = new_bin_score + (post_residual as f64) * 0.0;
    }

    // --- Mean-residual drift coupling ---
    // If this bin's residual is far below mean, it's a laggard bin; using it
    // consolidates. If far above mean, it's already roomy, deprioritize slightly.
    let resid_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = (resid_f - mean_residual) / mean_residual;
        score += dev * 8.0;
    }

    // --- Stream phase modulation ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    // early: be flexible (mild), late: squeeze hard
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small nonzero gaps are unusable for typical items.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap) / 10.0;
        } else if gap < 20.0 {
            score += 25.0 * (20.0 - gap) / 10.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to residual (waste fraction).
    if bin_residual > 0 {
        score += 20.0 * (post_residual as f64 / bin_residual as f64);
    }

    // Lookahead: if next item fits the post-residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 6.0;
        }
    }

    // Pressure to reuse open bins rather than proliferate them.
    score += 4.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: leaving no residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits: penalize proportionally to leftover dead space after it
            let after_next = post_residual - next_item_size;
            score += after_next as f64 * 0.3;
            if after_next == 0 {
                score -= 300.0;
            }
        } else {
            // next item won't fit here: mild penalty proportional to overshoot
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Prefer bins whose residual is close to mean (typical-fit) —
    // penalize outliers slightly.
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit.
    if bin_residual == bin_capacity {
        // penalize opening a new bin; aggressive lookahead may override via rewards above
        score += 60.0 + open_bins_count as f64 * 2.0;
        // if next item is large, opening fresh bin is more attractive
        if next_item_size > 50 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits (small post residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Penalize leaving dead space smaller than the smallest plausible item (1)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            score -= 30.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted gap
            score += 10.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin fit is bad
    if bin_residual == bin_capacity {
        score += 120.0;
        // opening new bins is more acceptable early in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 80.0 * (1.0 - progress);
        // if many bins are open with large mean residual, prefer filling them instead
        score += mean_residual * 0.5;
        score += open_bins_count as f64 * 5.0;
    }

    // Mild pressure to balance residuals toward mean
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Slight preference for fuller bins as stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - tightness) * 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit_norm = norm_pr * norm_pr;

    let mut score = pr;

    // Tight fits rewarded more strongly as stream progresses (smooth polynomial coupling)
    let tightness = (1.0 - norm_pr).powi(3);
    score -= 14.0 * tightness * (0.5 + progress);

    // Penalize large dead space non-linearly, escalating late in the stream
    score += 24.0 * fit_norm * fit_norm * (0.4 + 0.6 * progress);

    // Lookahead: bonus if next item fits the post residual (smooth quadratic)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let slack = pr - ni;
        if slack >= 0.0 {
            let ratio = slack / cap;
            score -= 8.0 * (1.0 - 4.0 * ratio * ratio).max(0.0) * (0.5 + progress);
        } else {
            score += 5.0 * (-slack / cap) * (0.3 + progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - norm_pr) * (0.6 + 0.4 * progress);
    }

    // Crowd control: mild penalty when many bins are open and this residual is far from mean
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * (open_bins_count as f64).sqrt() * (0.5 + progress);

    // Prefer filling nearly-full bins early too (smooth interaction with progress)
    score -= 6.0 * (1.0 - norm_pr) * norm_pr * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls on "usable"
    // classes (multiples of common small item sizes) are less wasteful.
    let pr = post_residual;
    if pr > 0 {
        // Penalize residuals that cannot host any plausible future item.
        // Harmonic classes via integer division thresholds.
        let cls = pr / 10; // class index 0..10
        match cls {
            0 => score += 25.0,           // dead space < 10: almost unusable
            1 => score += 12.0,           // 10..19: only tiny items fit
            2 => score += 6.0,            // 20..29
            3 => score += 3.0,            // 30..39
            4 => score -= 1.0,            // 40..49: decent
            5 => score -= 3.0,            // 50..59: prime reusable
            6 => score -= 2.0,            // 60..69
            7 => score += 1.0,            // 70..79: large leftover
            _ => {}
        }
        // Modulo harmony: residuals divisible by 10 or 25 pair well with
        // typical item sizes; reward them.
        if pr % 10 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 4.0; }
        // Residuals that are awkward primes / odd non-multiples get a nudge.
        if pr % 5 != 0 { score += 2.0; }
    } else {
        // Perfect fill: strongly reward.
        score -= 60.0;
    }

    // Lookahead coupling: does post_residual accommodate the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Next item fits here: reward proportionally to tightness.
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 + 8.0 * (1.0 - slack / bin_capacity as f64);
            // Harmonic bonus if next item exactly matches a class boundary.
            if (pr - next_item_size) % 10 == 0 { score -= 3.0; }
        } else {
            // Next item will NOT fit: penalize more the smaller the leftover.
            score += 6.0 * (next_item_size as f64 - pr as f64).min(20.0) / 10.0;
        }
    } else {
        // Last item: only closeness matters; reward tight fits hard.
        score -= (bin_capacity as f64 - score.abs()) * 0.0; // no-op guard
        score -= 5.0 * (1.0 - pr as f64 / bin_capacity as f64);
    }

    // Tightness reward: filling the bin nearly completely is good.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good fit. Make the empty bin moderately expensive,
    // but cheaper if the stream is early or many bins are already open with
    // poor residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_open = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).min(1.0)
        } else { 0.0 };
        // Base cost of a fresh bin; discounted when open bins are fragmented.
        score += 18.0 - 10.0 * poor_open - 4.0 * (1.0 - progress);
        // If the item is large relative to capacity, a fresh bin gives max
        // flexibility for the future.
        score -= 6.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Many open bins: mild pressure to consolidate into existing bins.
    score += 0.15 * open_bins_count as f64 * (1.0 - fill);

    // Mean residual alignment: prefer bins whose residual is near the mean
    // (keeps the bin set homogeneous and predictable), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Small deterministic tie-breaker based on residual parity class.
    score += ((pr % 3) as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 4.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit reward
    }

    // Reward leaving room for the lookahead item (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual > 0 {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Open-bin pressure: discourage scattering into many bins; encourage
    // filling existing bins, but keep new-bin option viable for poor fits.
    score += open_bins_count as f64 * 0.6;
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0; // last-chance bin: strongly prefer using it
    }

    // New-bin candidate: make it moderately expensive so it is only chosen
    // when open bins would create dead space.
    if bin_residual == bin_capacity {
        score += 18.0 + open_bins_count as f64 * 0.4;
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
    }

    // Mild alignment with mean residual state.
    score += (post_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that can never be used by typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    }

    // Lookahead coupling: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            score += 8.0; // next item can't follow here
        }
    }

    // Last-chance bin: heavily favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: encourage consolidation into already-open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (1.0 - progress);

    // Compare against mean residual: bins with much less residual than average
    // are "almost full" -> prefer filling them.
    let diff = mean_residual - bin_residual as f64;
    score -= 0.5 * diff;

    // New-bin candidate handling: make fresh bin attractive only when no open bin
    // fits well (post_residual small relative to capacity) — otherwise discourage.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 55.0;
        // If item is large, a fresh bin is natural (big chunk of capacity used).
        score -= 0.4 * item_size as f64;
        // Early in the stream, opening bins is cheaper.
        score -= 15.0 * (1.0 - progress);
        // If many bins already open and this item is small, prefer existing bins.
        if item_size < 40 && open_bins_count > 2 {
            score += 10.0;
        }
        // Lookahead: if next item is large too, fresh bin keeps room.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Mild noise-free tie-break: prefer lower-index effect via residual ordering.
    score += 0.01 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear polynomial shaping
    let mut score = pr as f64;
    score += 0.9 * cap * norm_pr * norm_pr; // quadratic penalty on dead space

    // Coupling with stream progress: early on tolerate slack, later demand tight fits
    score -= 8.0 * (1.0 - progress) * norm_pr;
    score += 12.0 * progress * norm_pr * norm_pr;

    // Lookahead: reward if next item fits the post-residual
    let next_fits = (next_item_size as f64) <= pr && next_item_size > 0;
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        if next_fits {
            score -= 6.0 + 4.0 * (1.0 - gap / cap);
        } else {
            score += 3.0 * (next_item_size as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mean residual coupling: penalize bins far from the open-bin average (keeps residuals uniform)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev;

    // Mild penalty for proliferating bins when a fit exists
    let openness = open_bins_count as f64;
    score += 0.3 * openness * norm_pr;

    // New-bin candidate: make empty bin attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * progress + 0.5 * openness;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and integer division thresholds.
    let class = post_residual / 10;
    let residue = post_residual % 10;
    // Penalize awkward small residues (dead space unlikely to be filled).
    if residue > 0 && residue < 5 {
        score += 3.0;
    }
    // Reward post-residuals in "useful" harmonic classes (small buckets).
    score -= match class {
        0 => 8.0,
        1 => 5.0,
        2 => 2.0,
        3 => 0.5,
        _ => 0.0,
    };

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: does the next item fit exactly into the post-residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let left = post_residual - next_item_size;
            score -= 10.0 - (left as f64) * 0.3;
        } else {
            // next item won't fit here; mild penalty scaled by overflow
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
        // Harmonic pair check: next item shares a divisor class with post_residual
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Fit tightness: reward small relative slack.
    let tightness = post_residual as f64 / cap;
    score += tightness * 10.0;

    // Prefer filling nearly-full bins vs spreading across many open bins.
    if open_bins_count > 3 {
        score -= 2.0 * (bin_residual as f64 / cap - mean_residual / cap);
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin; allow it only if item is large relative to capacity
        score += 20.0 - 15.0 * (item_size as f64 / cap);
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big next item: fresh bin may help
        }
    }

    // Late-stream consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0 * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Mid-range "awkward gap" penalty: residuals 10..25 are hard to fill.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tightness relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is genuinely good.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let mean_tight = mean_residual / bin_capacity as f64;
        if fitting_bins_count > 0 && mean_tight < 0.35 {
            score += 30.0; // open bins still roomy: keep filling them
        } else {
            score -= 8.0 * mean_tight; // near-full bins: new bin is fine
        }
        // Early in the stream, a fresh bin is cheap insurance.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * (1.0 - progress);
    }

    // Lookahead (k=2): reward leaving a gap that can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize leaving a gap just barely smaller than the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // next item fits: penalize proportional to leftover waste after both placements
            let double_leftover = post_residual - next_item_size;
            score += double_leftover as f64 * 0.5;
        } else {
            // next item won't fit here: penalize small dead space that can't host next item
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Compare residual against mean residual across open bins
    score -= (post_residual as f64 - mean_residual) * 0.3;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening new bins when open bins can fit the item
    if bin_residual == bin_capacity {
        score += 80.0;
        // early stream: more willing to open bins; late stream: reluctant
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 40.0;
    }

    // Slight preference for bins with tighter residual (better fit density)
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Penalize leaving tiny unusable slivers (< 10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize large dead space that can only hold tiny items
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // nearly perfect fit bonus
    } else if post_residual >= 10 && post_residual < 20 {
        score -= 8.0;
    } else if post_residual > 60 {
        score += 6.0; // large leftover is wasteful unless bin is new
    }

    // New-bin candidate handling: only attractive when existing fits are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening new bins mildly; reward if no good fit exists
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Lookahead: if next item fits in post_residual, big reward (pairing)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else {
            // Penalize leaving a residual just barely too small for next item
            let gap = (next_item_size as f64) - (post_residual as f64);
            if gap > 0.0 && gap < 12.0 {
                score += 10.0 * (1.0 - gap / 12.0);
            }
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate
    let excess_bins = (open_bins_count as f64) - (mean_residual / bin_capacity as f64).max(0.0);
    if mean_residual > 50.0 && !is_new_bin {
        score -= 6.0;
    }
    let _ = excess_bins;

    // Time-horizon modulation: early stream favors exploration (spread), late favors packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress) * tightness;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Small deterministic tie-breaker based on residual structure
    score += (post_residual % 7) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64 / bin_capacity as f64;
    let poly = pr * pr * (1.0 + 2.0 * progress) - pr * progress * (1.0 - progress);
    score += 30.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pr;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across too many bins early on
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Pull toward mean residual to keep bins balanced
    score += 0.2 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let bad_fit = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        score += 10.0 - 8.0 * bad_fit + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near multiples of 10 are
    // "harmonic" — they match common item sizes and are more reusable.
    let residue = post_residual % 10;
    let harmonic_bonus = match residue {
        0 => 12.0,
        1 | 9 => 8.0,
        2 | 8 => 5.0,
        3 | 7 => 2.0,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Dead-space penalty: post_residual that cannot host the next item is wasted.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize proportionally to how far short we fall (harmonic ladder).
            let shortfall = (next_item_size - post_residual) as f64;
            let class = ((shortfall / 10.0).floor() + 1.0) * 6.0;
            score += class;
        } else {
            // Reward a fit that leaves a harmonic (multiple-of-10) residue again.
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 10.0;
            } else if next_post % 5 == 0 {
                score -= 5.0;
            }
        }
    }

    // Capacity-fraction classes: prefer post_residual in useful fractional bands.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.1 {
        score += 4.0; // nearly full: fine, small penalty for tightness risk
    } else if frac < 0.25 {
        score -= 3.0; // good compact fit
    } else if frac > 0.75 {
        score += 6.0; // wasting a mostly-empty bin on this item
    }

    // Integer-division threshold on post_residual / item_size ratio.
    let ratio_class = post_residual / item_size.max(1);
    if ratio_class >= 3 {
        score -= 2.0; // bin could host several more items
    } else if ratio_class == 0 {
        score += 3.0; // item barely fits: risky
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: keep it neutral-ish; only attractive when open bins
    // are heavily fragmented (low mean residual) or many bins already open.
    if bin_residual == bin_capacity {
        score = 40.0
            + mean_residual * 0.3
            + (open_bins_count as f64).sqrt() * 2.0
            - (step_index as f64 / (total_items as f64).max(1.0)) * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Fresh bin guarantees a harmonic 100-residue start.
            score -= 5.0;
        }
    }

    // Mild global pressure: consolidate into fewer bins as stream progresses.
    score += mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (<= 10) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 40.0;
    }

    // "Awkward gap" zone: residuals just above small-item sizes tend to never
    // be filled; add a non-linear bump for 10..=20.
    if post_residual >= 10 && post_residual <= 20 {
        score += 12.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize mildly per open bin.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: if this is the only bin that fits, heavily favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make opening a new bin only attractive when the
    // current fit is poor (large post_residual) relative to capacity.
    if bin_residual == bin_capacity {
        // Empty bin: baseline cost of consuming fresh capacity.
        score = 100.0 + (open_bins_count as f64) * 2.0;
        // If the item would leave a huge residual anyway in any bin, new bin
        // is fine; scale down slightly with item size.
        score -= (item_size as f64) * 0.3;
        // Lookahead: if next item is large, opening a fresh bin is safer.
        if next_item_size > 60 {
            score -= 15.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item would fit into post_residual at all, mild reward.
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Progress-based tightening: later in the stream, be stricter about
    // dead space (fewer chances to recover).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * 10.0 * progress;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already tight; reward using it.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff.min(50.0) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.9;

    // 2-step lookahead: reward when next item fits into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = post_residual - next_item_size;
        score -= 25.0 + (post_residual - next_item_size) as f64 * 0.5;
        if leftover_after_next == 0 {
            score -= 30.0; // perfect chain fill
        }
    } else if next_item_size > 0 && next_item_size <= bin_capacity {
        // Next item won't fit here: penalize leaving large gaps.
        score += (post_residual as f64).min(next_item_size as f64) * 0.4;
    }

    // Relative to mean residual: prefer bins with residuals near the item size.
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless no good fit exists.
    if bin_residual == bin_capacity {
        score += 40.0 + item_size as f64 * 0.3;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Penalize dead space that is too small for the minimum item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Slight preference to fill older bins as stream progresses.
    score += (step_index as f64 / total_items.max(1) as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post residual can't host the next item: mild penalty scaled by wasted potential.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: any placement is fine; prefer fullest bin.
        score -= 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, heavily favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is discouraged unless
    // all open bins would leave large unusable residuals.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Cost of a new bin grows with number of open bins and mean residual waste.
        score += 15.0 + 2.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);
        // If open bins fit poorly (high mean residual relative to item), new bin is OK.
        if mean_residual < item_size as f64 * 1.2 {
            score -= 25.0;
        }
        if pressure > 0.6 {
            score -= 10.0;
        }
    } else {
        // Existing bin: mild bonus to consolidate load when many bins are open.
        score -= (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins whose residual is close to mean (balance), small effect.
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer minimal post residual, smoothed non-linearly
    let mut score = post * (1.0 + 0.5 * norm_post * norm_post);

    // Dead-space penalty: residuals too small to ever be useful
    let dead_threshold = 10.0f64.min(cap * 0.1);
    if post < dead_threshold {
        score += (dead_threshold - post) * 2.0;
    }

    // Perfect-fit reward (non-linear decay of reward with residual)
    if post == 0 {
        score -= 50.0 + 30.0 * progress;
    }

    // Last-chance bin bonus: only bin that fits -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 - progress);
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // penalize leaving residual that blocks the next item
        score += 5.0 + 5.0 * progress;
    }

    // New-bin candidate handling: penalize opening a new bin unless
    // existing bins are fragmented / full-ish
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        // Opening is attractive when mean residual is low (bins nearly full)
        score = cap * (1.0 - fragmentation) + 10.0 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
        if fitting_bins_count > 0 {
            // discourage skipping a usable bin unless fragmentation is severe
            score += 25.0 * (1.0 - fragmentation).min(1.0);
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score += 100.0;
        }
    }

    // Mild stream-progress coupling: later in stream, tolerate slightly worse fits less
    score += progress * post * 0.3;

    // Reward filling bins that are already partially loaded (avoid bin proliferation)
    if bin_residual != bin_capacity {
        let fill = 1.0 - (bin_residual as f64) / cap;
        score -= 8.0 * fill * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: small post_residual is good (tight fit).
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Reward tight fits: post_residual in [0, 10) is near-perfect.
    if post_residual == 0 {
        score -= 500.0; // perfect fit, always prefer
    } else if post_residual < 10 {
        score -= 300.0;
    } else if post_residual < 20 {
        score -= 150.0;
    }

    // Dead-space penalty: post_residual too small for typical future items (1..100).
    // Residual < next_item_size is useless for the immediate lookahead.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 40.0; // cannot host the lookahead item
        } else if post_residual == next_item_size {
            score -= 200.0; // lookahead will perfectly fill this bin
        } else {
            // fraction of the lookahead item that fits
            score -= 20.0 * (post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // Modulo arithmetic on post_residual: harmonic classes.
    // Residuals that are multiples of 10 pair well with common item sizes.
    let harmonic = (post_residual % 10) as f64;
    score += harmonic * 2.5; // prefer residuals aligned to decade grid

    // Integer division thresholds: classify residual quality.
    let q = post_residual / 25; // 0..=4 quarter classes
    score -= match q {
        0 => 60.0, // residual < 25: mostly dead space unless tight
        1 => 20.0,
        2 => 0.0,
        _ => 10.0, // large residual = mostly empty bin, weak use
    };

    // Last-chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
        // but if the fit is terrible (post_residual tiny but nonzero), soften
        if post_residual > 0 && post_residual < 5 {
            score += 50.0;
        }
    }

    // New-bin candidate handling: empty bin should lose unless all fits are bad.
    if bin_residual == bin_capacity {
        score = cap * 0.5; // baseline 50
        // open a new bin early when many items remain and few bins open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        // don't open a new bin if a perfect/near-perfect fit exists elsewhere
        if post_residual == 0 {
            score += 400.0; // this is the empty bin itself; post_residual == cap
        }
        // penalize opening new bins when lookahead fits the empty bin perfectly
        if next_item_size > 0 && next_item_size == bin_capacity - item_size {
            score -= 80.0;
        }
        // keep bin count lean: penalize new bins when many already open
        score += (open_bins_count as f64).sqrt() * 5.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (i.e., filling the fullest bins first keeps more large residuals open).
    if (bin_residual as f64) < mean_residual {
        score -= 25.0;
    } else {
        score += 10.0;
    }

    // Small global pressure toward tight packing as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Large gaps are valuable; reward keeping them if next item can use them.
    if next_item_size > 0 && post_residual >= next_item_size as f64 {
        score -= 8.0 + 0.1 * (post_residual as f64 - next_item_size as f64).min(50.0);
    } else if next_item_size > 0 && post_residual > 0 {
        // gap too small for lookahead item: penalize proportionally to wasted potential
        score += 0.3 * (next_item_size as f64 - post_residual as f64).min(30.0);
    }

    // Open bins pressure: with many open bins, prefer filling existing ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 20.0);
    score += 0.6 * pressure;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are terrible.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && (next_item_size as f64) >= 0.9 * bin_capacity as f64 {
            score -= 20.0; // huge item coming, keep capacity free
        }
    }

    // Late in stream, tighten packing (less tolerance for residual spread).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain fit: post_residual exactly matches next item.
            let exact = (post_residual as f64 - next_item_size as f64).abs() / bin_capacity as f64;
            score -= 30.0 * (1.0 - exact);
        } else {
            // Lookahead mismatch penalty: dead space next item can't use.
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Penalize large post_residual relative to mean residual (wasteful bin).
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer tighter bins overall (small pre-residual slack).
    score += 0.05 * (bin_residual as f64 - item_size as f64);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual as f64 - item_size as f64) < mean_residual * 0.5;
        if poor_fit && fitting_bins_count <= 1 {
            score -= 10.0;
        } else {
            score += 20.0;
        }
    }

    // Late-stream consolidation: tighten packing as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 14.0 * fit_ratio * fit_ratio;

    // Penalize large dead space, especially if nothing small could ever use it.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // near-perfect fill
    }
    if post_residual > 40 {
        score += 5.0 * (post_residual as f64 - 40.0) / 60.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 3.0;
        }
        // Penalize wasting a bin that would fit both current and next item poorly.
        if bin_residual >= item_size + next_item_size {
            score -= 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: prefer new bin only when open bins are crowded
    // and mean residual is high relative to item size.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = (open_bins_count as f64).ln().max(1.0);
        if mean_residual > item_size as f64 * 1.6 {
            score -= 5.0 + 3.0 * progress / crowded;
        } else {
            score += 12.0;
        }
    }

    // Global state: with many open bins, encourage consolidating into existing bins.
    score += 0.15 * (open_bins_count as f64).powf(0.8);
    score -= 0.05 * mean_residual;

    // Time horizon: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let t = progress;
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep-like, no piecewise constants
    score += poly * pr * (1.0 - pr / cap) * 0.5;

    // Penalize large residual that wastes space, scaled by how full bins are overall.
    let norm_res = pr / cap;
    score += norm_res * norm_res * cap * 0.3 * (mean_residual / cap);

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= (1.0 - norm_res) * (1.0 - norm_res) * 10.0 * (0.5 + poly);

    // Last-chance bin bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + poly);
    }

    // Lookahead coupling: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let slack = (post_residual - next_item_size as u32) as f64;
        score -= 8.0 * (1.0 - slack / cap) * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here: mildly penalize leaving a medium dead zone.
        score += 5.0 * norm_res * (1.0 - norm_res);
    }

    // New-bin candidate handling: make empty bin attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + poly) + 15.0 * (fitting_bins_count as f64);
        if fitting_bins_count == 0 {
            score = -50.0;
        }
    }

    // Mild penalty for too many open bins early on.
    score += (open_bins_count as f64).sqrt() * 2.0 * (1.0 - poly);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // capacity fractions (1/2, 1/3, 1/4) and integer-division thresholds.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly reward.
        score -= 500.0;
    } else if pr <= cap * 0.25 {
        // Small leftover, likely still usable by small items.
        score -= 60.0;
    } else if pr <= cap / 3.0 {
        score -= 25.0;
    } else if pr <= cap / 2.0 {
        score += 15.0;
    } else {
        // Large dead space class: penalize heavily.
        score += 80.0;
    }

    // Modulo-arithmetic harmony: leftover that is a multiple of a common
    // small size is more reusable.
    for k in [10u32, 20, 25, 50] {
        if pr > 0 && pr % k == 0 {
            score -= 8.0;
        }
    }

    // Lookahead coupling: does next item fit exactly or well into the leftover?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0; // perfect chain
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            if gap <= cap * 0.2 {
                score -= 40.0;
            } else {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here: leftover becomes a "waiting" slot.
            score += 20.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current item is large and no good class exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 40.0
            + 0.3 * (item_size as f64)
            - 15.0 * progress;
        // If many bins can fit, opening a new one is wasteful.
        new_bin_score += 10.0 * fitting_bins_count as f64;
        // Keep mean residual low: opening new bin raises mean waste.
        new_bin_score += 0.5 * mean_residual;
        score = new_bin_score;
    }

    // Slight pressure against accumulating many open bins with fat residuals.
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized (non-linearly).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable gap = pure waste
    } else if post_residual < 25 {
        // gap only usable by small items: penalty grows as gap shrinks
        score += (25.0 - post_residual as f64) * 2.0;
    }

    // Reward tight fits: item nearly fills the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // If the bin's residual exactly matches the item, near-perfect fit.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward;
    // otherwise penalize leaving a gap that tempts a bad future fit.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, opening a new bin is cheaper, so raise scores slightly.
    let open_pressure = open_bins_count as f64;
    score += open_pressure * 1.5;

    // New-bin candidate: neutral baseline tuned against open-bin pressure.
    if bin_residual == bin_capacity {
        // A new bin is attractive only if the item is small relative to
        // capacity and existing bins have large mean residual (poor fits).
        score = 55.0 - fill_ratio * 20.0 + mean_residual * 0.3;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If only one fitting bin exists, opening new is bad.
        if fitting_bins_count == 1 {
            score += 30.0;
        }
    }

    // Mild tie-break by residual closeness to mean (prefer balanced bins).
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item fits exactly into the post residual with some slack tolerance
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward tight couplings: smaller slack after next placement is better
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        // Extra bonus if next item also fits the residual well relative to mean
        if slack as u32 <= item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item will NOT fit here: penalize dead space proportionally
        let overflow = (next_item_size - post_residual) as f64;
        score += 0.5 * overflow;
    }

    // Penalize creating very small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Reward tight fits relative to bin capacity
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // Penalize opening new bins when good fitting bins exist
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let avg_needed = mean_residual.max(0.0);
        // New bin is attractive only if mean residual across open bins is small
        // relative to the item, or late in the stream with many bins open
        let fit_ratio = item_size as f64 / (avg_needed + 1.0);
        score += 120.0 - 60.0 * fit_ratio.min(2.0) - 30.0 * progress;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: new bin is necessary
        }
    }

    // Mild penalty proportional to how far post_residual deviates from mean residual
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (waste-aware quadratic penalty on slack).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 3.0 * tightness * tightness * bin_capacity as f64;

    // Penalize leaving residual smaller than the smallest plausible item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins where the next item can also fit into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.15 * next_item_size as f64;
    }
    // Penalize if next item is a near-perfect fit for current residual but we consume it now.
    if next_item_size > 0 && next_item_size == bin_residual {
        score += 20.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item is large or all fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = poor_fit * (1.5 + pressure)
            - 5.0 * progress
            - if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        // Opening new bins late is costly; discourage slightly with open-bin count.
        score += 0.5 * open_bins_count as f64;
    }

    // Mild global pressure: prefer filling bins with large mean residual when many bins open.
    if bin_residual != bin_capacity {
        score -= 0.05 * mean_residual;
    }

    // Progress-scaled waste tolerance: early on, keep bins flexible; later, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;
    let mut score = pr;
    // smooth non-linear interaction: residual value decays with progress
    score -= 20.0 * (prn * prn) * (1.0 - progress);
    // penalize near-empty post-residuals (wasted slivers) more strongly later in stream
    let sliver = 1.0 - (prn * 4.0 - 1.0).powi(2).max(0.0).min(1.0);
    score += 15.0 * sliver * (0.5 + progress);
    // lookahead: reward residual that fits next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = (pr >= nx) as i32 as f64;
        let tight = 1.0 - ((pr - nx) / cap).abs();
        score -= 10.0 * fits * tight * tight;
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }
    // new-bin candidate: mildly discouraged early, more acceptable late
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress) - 5.0 * progress;
    }
    // smooth coupling with mean residual deviation
    score += 0.05 * (pr - mean_residual) * (1.0 + progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" classes (0..=10) are nearly perfect fits -> strong reward.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // capacity fraction of leftover

    // Reward tight fits: leftover <= 10 is ideal (dead space ~ 0).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 45.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    } else if post_residual <= 30 {
        score -= 10.0;
    }

    // Harmonic class of post_residual via integer division: leftover that is
    // divisible by common item granularity (10s) is reusable by future items.
    let class = post_residual / 10;
    let class_bonus = match class {
        0 => 18.0,
        1 => 12.0,
        2 => 6.0,
        3 => 2.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Lookahead coupling: if next item fits exactly into the post residual,
    // this placement chains perfectly -> big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after chaining
            let chain = post_residual - next_item_size;
            score -= (20.0 * (chain as f64) / cap).min(15.0);
        } else {
            // next item cannot use this leftover: penalize large wasted gaps
            score += 8.0 * frac;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (huge leftover fraction).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has maximal residual; make it
    // attractive only when existing bins would create bad fits, otherwise
    // discourage opening new bins (prefer filling open ones).
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 35.0;
        // but if many open bins are fragmented (high mean residual spread),
        // a fresh bin is cleaner
        if mean_residual > 0.5 * cap && open_bins_count > 3 {
            score -= 30.0;
        }
        if post_residual <= 20 {
            score -= 10.0; // huge item nearly fills a fresh bin
        }
    }

    // Progress modulation: late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - frac);

    // Mild penalty proportional to leftover fraction to always prefer tighter bins.
    score += 15.0 * frac * frac;

    // Modulo harmonic nudge: leftover congruent to small multiples of 5 pairs
    // well with typical item granularities.
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< ~10, or below the
    // plausible minimum item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 25 {
        score += 25.0;
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Coupling with lookahead: reward if the next item fits the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else if post_residual > 0 {
            // Post residual too small for the next item -> dead space for k=2 lookahead.
            score += 15.0;
        }
    }

    // Open bins pressure: penalize bins proportionally to how many are open,
    // discouraging spreading items across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates below the mean
    // (tighter packing) slightly.
    score += (mean_residual - post_residual as f64) * 0.05;

    // New-bin candidate: make it moderately attractive only when no good fit
    // exists (post_residual large means the item fits loosely here anyway).
    if bin_residual == bin_capacity {
        score += 30.0 + 3.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits.
    score += 0.15 * (bin_residual as f64 - item_size as f64).abs();

    // Reward when the next item exactly fills the post residual (perfect 2-step chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how well it uses the leftover.
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill_ratio;
        } else {
            // Next item won't fit: penalize large dead space left behind.
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 0.3 * dead;
            }
        }
    }

    // Compare post residual against mean residual across open bins.
    // Leaving more than average residual wastes capacity elsewhere.
    if post_residual as f64 > mean_residual {
        score += 0.2 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.1 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: keep it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.5 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits anywhere: must open new bin
        } else if next_item_size > 0 && post_residual == bin_residual && next_item_size >= 60 {
            score -= 10.0; // large next item may warrant a fresh bin
        }
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly prefer placements that nearly fill the bin.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 2.5 * tightness * tightness * bin_capacity as f64 * 0.01;

    // Penalize dead space: residuals that are too small to hold typical items.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) + 9 {
        score += 30.0;
    }
    // Non-linear dead-space penalty: residuals just below a common item size are wasted.
    let wasted = (post_residual > 0 && post_residual < 20) as f64;
    score += 12.0 * wasted * (1.0 + (bin_residual as f64 / bin_capacity as f64));

    // Lookahead coupling: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        // Perfect pairing bonus
        if slack == 0.0 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Post residual cannot host next item: mild penalty scaled by how close it was.
        let miss = (post_residual as f64 - next_item_size as f64).abs();
        score += 3.0 * (1.0 - miss / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits, else a new bin opens.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowding = (open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0)) * (0.5 + progress);
    score += 0.05 * crowding * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin should only win when it's genuinely better.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin, decaying as stream progresses.
        score = 0.35 * bin_capacity as f64
            + 0.25 * mean_residual
            - 8.0 * progress
            + (open_bins_count as f64).sqrt() * 2.0;
        // If no existing bin fits, opening is unavoidable-ish: soften cost.
        if fitting_bins_count == 0 {
            score -= 0.30 * bin_capacity as f64;
        }
        // Perfect pair ahead: opening a fresh bin is great if item + next fits.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Small tie-breaker toward larger residual bins (keep small pockets for small items).
    score -= 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer tight fits (low post_residual) strongly.
    // Late stream: tolerate moderate residuals but punish extreme dead space.
    let poly = fit_norm * fit_norm * (1.0 - t) * 40.0
             + fit_norm * t * 15.0
             - (fit_norm * (1.0 - fit_norm)) * (1.0 - t) * 20.0;
    score += poly;

    // Reward bins that leave room for the lookahead item (smooth interaction).
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = pr - nxt;
        let bonus = if gap >= 0.0 {
            let g = gap / cap;
            18.0 * g * (1.0 - g) * (1.0 + t)
        } else {
            (gap / cap) * (gap / cap) * 25.0
        };
        score -= bonus;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - fit_norm * fit_norm);
    }

    // Mild pressure to consolidate when many bins are open.
    let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 10.0);
    score -= open_norm * fit_norm * 8.0;

    // Coupling with mean residual: avoid leaving residuals far above the mean.
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * (0.5 + t);

    // Slight preference for filling bins deeply as stream progresses.
    score -= (1.0 - fit_norm) * t * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residuals in the same
    // "harmonic band" (multiples of small divisors of capacity) are more
    // reusable by future items.
    let cap = bin_capacity as f64;

    // Reward residuals that are multiples of common item granularity
    // classes (10, 20, 25, 50 divide the 1..100 space nicely).
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 3.0; }
        if pr % 20 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 2.0; }
        if pr % 50 == 0 { score -= 4.0; }
    } else {
        // Perfect fit: best possible outcome.
        score -= 60.0;
    }

    // Penalize tiny dead space (unusable by typical items >= 1..100):
    // residuals in 1..=5 are almost certainly wasted.
    if pr > 0 && pr <= 5 {
        score += 12.0;
    }

    // Harmonic compatibility with the lookahead item: if the next item
    // exactly fills the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size < pr {
            // Next item fits here too: mild reward scaled by how well it
            // harmonizes (integer division leaves small remainder).
            let rem = pr % next_item_size.max(1);
            score -= 5.0 - (rem as f64) * 0.3;
        } else {
            // Next item cannot use this bin's residual: penalize relative
            // to how much of the residual is stranded.
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has huge post_residual.
    // Make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score = cap * 0.5;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            // Pairing lookahead with fresh bin is fine
            score -= 2.0;
        }
        // Early in the stream, opening bins cheaply is fine.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins with below-average residual (tighter packing).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Slight preference for using existing bins over accumulating many
    // open bins late in the stream.
    score += 0.02 * open_bins_count as f64 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else if post_residual < 20 { 0.6 } else { 0.0 };
        score += dead * post_residual as f64 * 2.5;
    } else {
        // Perfect fit is heavily rewarded.
        score -= 60.0;
    }

    // Open bins pressure: prefer filling existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // Mean residual coupling: bins far below mean residual are less attractive
    // (keep "fresher" bins for future large items).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would be blocked by this placement in a tight gap, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // open bins are scarce or residuals are tight.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        score += 30.0 - 40.0 * scarcity - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward when next item exactly fits the post-residual (perfect 2-step match).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.8;
        if post_residual == next_item_size {
            score -= 40.0; // exact 2-chain: strongly prefer
        }
        // Penalize leaving a residual too small for any item (dead space)
        if post_residual < 10 && post_residual > 0 {
            score += 25.0;
        }
    } else {
        // Last item: just minimize waste
        score += 5.0;
    }

    // Compare against mean residual: prefer bins whose post-residual is below mean
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it unattractive unless existing fits are terrible
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
    }

    // Slight preference for tighter bins early, spreading later in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tightest fit (lowest post_residual) via non-linear shaping
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac * frac; // penalize large leftover space quadratically

    // Lookahead: if the next item can fit into post_residual, this bin is even more
    // valuable (chain packing) -> reward. If next item cannot fit, leftover risks
    // becoming dead space -> penalize proportionally.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (next_item_size as f64 / post_residual.max(1) as f64));
        } else {
            score += 10.0 * frac;
        }
    }

    // Last-chance bonus: if this is the only open bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: an empty bin (residual == capacity) should only
    // win when no open bin offers a decent fit, i.e. when mean residual is small
    // or existing residuals are poor.
    if bin_residual == bin_capacity {
        // default penalty for opening a new bin
        let mut new_bin_penalty = 60.0;
        // if mean residual across open bins can't accommodate the item well,
        // relax the penalty
        if (mean_residual < item_size as f64) || (fitting_bins_count == 0) {
            new_bin_penalty -= 45.0;
        }
        // late in the stream, opening new bins is less costly in expectation
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty -= 10.0 * progress;
        // many open bins already: slight extra reluctance
        new_bin_penalty += 1.5 * open_bins_count as f64;
        score += new_bin_penalty.max(0.0);
    }

    // Global state coupling: if mean residual is large, prefer reusing bins with
    // residual close to mean (avoid fragmenting large residuals elsewhere)
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += 2.0 * (diff / bin_capacity as f64);

    // Reward near-perfect fills
    if post_residual < 5 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits (low post_residual); late in the stream,
    // dead space is less costly so the polynomial weight decays smoothly.
    let decay = (1.0 - progress).powi(2);
    score -= decay * (pr - norm_pr * pr) * 0.5;

    // Smooth convex penalty for very small residuals (dead space),
    // scaled by progress so it matters more early on.
    let dead = (1.0 - norm_pr).powi(3);
    score += progress * dead * 8.0;

    // Reward bins whose residual is close to the mean residual (smooth quadratic coupling).
    let dev = (pr as f64 - mean_residual) / cap;
    score += dev * dev * 4.0;

    // Last-chance bonus: strongly favor the only bin that fits, smoothly scaled.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Lookahead coupling: reward leaving space for the next item,
    // smoothly via a quadratic interaction with post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = pr - nx;
        if diff >= 0.0 {
            score -= 5.0 * (1.0 - (diff / cap).powi(2));
        } else {
            score += 3.0 * (-diff / cap);
        }
    }

    // Mild penalty on opening a brand-new bin (bin_residual == bin_capacity),
    // smoothly reduced when few bins are open or progress is late.
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) * (1.0 / (1.0 + open_bins_count as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus (harmonic class 0)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: bins whose residual falls into
    // "reusable" classes (multiples of common small sizes) are favored.
    let pr = post_residual;
    let reusable = pr % 10 == 0 || pr % 25 == 0 || pr % 20 == 0;
    if reusable {
        score -= 12.0;
    } else if pr < 10 {
        // dead space below minimum item size is nearly unusable
        score += 30.0;
    } else {
        // fractional dead-space penalty scaled by distance to nearest class
        let nearest = (pr % 10).min(10 - pr % 10) as f64;
        score += nearest * 1.5;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack % 10 == 0 {
                score -= 40.0;
            }
            score += slack as f64 * 0.5;
        } else {
            // next item won't fit here: mildly penalize keeping large residual trapped
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate handling: neutral-ish baseline, penalized unless
    // current bin would leave awkward residual
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size % 10 == 0 {
            score -= 20.0; // clean split of a fresh bin
        }
    }

    // Progress coupling: later in the stream, prefer tighter packs
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * 0.3 * progress;

    // Prefer bins below mean residual (tighter bins first)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    // Many open bins: encourage closing bins out
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit: strongly reward completely filling a bin.
    if post_residual == 0 {
        score -= 50.0;
    }
    // Strict dead-space avoidance: quadratic penalty for small unusable gaps.
    else if pr < 15.0 {
        let gap = 15.0 - pr;
        score += gap * gap * 1.2;
    }

    // Lookahead coupling (k=2): reward residuals that can still serve the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            score -= 6.0;
        } else if pr < 15.0 {
            // Residual is too small for the next item AND generally unusable.
            score += 12.0;
        }
    }

    // Last-chance pressure: if this is the only open bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate penalty: opening a bin is penalized more when many bins
    // are already open, when open-bin residuals are small (fits are good),
    // and later in the stream (consolidation pressure).
    if bin_residual == bin_capacity {
        score += 35.0
            + 2.5 * open_bins_count as f64
            + 0.4 * mean_residual.max(0.0)
            + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead space minimization).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Exact fit: huge reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = next_item_size as f64 / post_residual as f64;
        score -= 40.0 * chain_fit;
        if post_residual == next_item_size {
            score -= 80.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving dead space
        // that is too small for the next item.
        score += 15.0 + 0.3 * post_residual as f64;
    }

    // Compare post_residual against mean residual: keep residual
    // distribution balanced, avoid creating outliers below mean.
    if (post_residual as f64) < mean_residual {
        score += 0.5 * (mean_residual - post_residual as f64);
    } else {
        score -= 0.2 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin when decent existing options exist,
    // unless stream is early and bins are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_penalty = 25.0 + 40.0 * progress;
        score += open_penalty;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Slight preference for tighter bins early on (best-fit bias).
    score += 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    let cap_f = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap_f;
    score -= 14.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead waste).
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 2.2 * waste;
        // Extra penalty if the leftover is very small (unusable sliver).
        if post_residual < item_size / 2 {
            score += 8.0;
        }
    }

    // Reward perfect/zero residual strongly.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Early in stream: prefer consolidating into existing bins to keep bin count low.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = 1.0 - progress;
    score += consolidation * 6.0 * (open_bins_count as f64).sqrt();

    // Many open bins with high mean residual: encourage filling existing bins.
    if mean_residual > (2.0 * item_size as f64) && open_bins_count > 2 {
        score -= 5.0;
    }

    // Late in stream: avoid creating tiny residuals that will never be used.
    if progress > 0.7 && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Slight preference for bins whose residual is close to item size (best fit).
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap_f;
    score += 10.0 * fit_gap * fit_gap;

    // New-bin candidate: make it unattractive unless item is huge relative to capacity
    // or no good fit exists (handled by last-chance logic).
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size as f64 > 0.8 * cap_f {
            score -= 30.0; // big items deserve fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly sub-linear via square to emphasize large dead space
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Non-linear coupling of post_residual with stream progress:
    // early in stream, tight fits matter less; late, they matter more
    let coupling = 1.0 + 2.5 * progress * progress;
    score *= coupling;

    // Reward filling bin tightly (post_residual near zero) with smooth term
    score -= 20.0 * (-pr / 15.0).exp() * (1.0 + progress);

    // Penalize leaving residual that barely fits the next item poorly:
    // smooth interaction between post_residual and next_item_size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (pr - nxt).abs();
        score += 8.0 * (1.0 - (-fit_gap / 20.0).exp());
        // Reward exact-feasible next fit smoothly
        score -= 10.0 * (-((pr - nxt).abs() / 8.0).powi(2)).exp();
    }

    // Last-chance bonus: if only this bin fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Mean residual coupling: prefer bins whose residual deviates below mean
    // (consolidating small residuals), smooth quadratic term
    let dev = pr - mean_residual;
    score += 0.5 * dev * dev / cap;

    // Mild penalty for opening new bins when many open bins exist
    if bin_residual == bin_capacity {
        score += 5.0 + 1.5 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic class of post_residual: how well it aligns with typical item sizes
    let pr_class = post_residual % 10;
    let pr_div = post_residual / 10;
    // Reward post_residuals that are either 0 (perfect fill) or large enough to host
    // another common item class (10..80)
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always best
    } else if post_residual >= 80 {
        score -= 60.0; // still very reusable
    } else if post_residual >= 40 {
        score -= 20.0;
    } else if post_residual >= 10 {
        score -= 5.0;
    } else {
        score += 40.0; // dead space (<10 unusable)
    }

    // Modulo coupling: residuals divisible by 10 are more reusable
    if pr_class == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Half/quarter capacity classes
    if post_residual == bin_capacity / 2 {
        score -= 10.0;
    }
    if post_residual * 2 == bin_capacity {
        score -= 6.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 - slack * 0.5;
        } else {
            // next item won't fit here; penalize small residual mildly
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bonus: only this bin can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin; reduce when many items remain or few bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.85 - 40.0 * progress;
        if open_bins_count == 0 {
            score -= 500.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // if mean residual across open bins is large, prefer reusing them
        score += mean_residual * 0.8;
    }

    // Tight-fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Mild penalty for spreading across too many bins
    score += open_bins_count as f64 * 0.5;

    // Integer-division threshold on pr_div to shape residual classes
    score -= pr_div as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero post_residuals are poison.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: heavy penalty.
            score += 60.0 - (post_residual as f64) * 2.0;
        } else if post_residual < 20 {
            score += 25.0 - (post_residual as f64) * 0.8;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 50.0;
    }

    // Reward tight fits relative to bin residual (waste fraction penalty).
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_frac * 15.0;

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item just barely misses, penalize slightly (chained dead space).
    if next_item_size > 0 && next_item_size > post_residual && post_residual < next_item_size && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the empty-bin candidate gets penalized proportionally.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 6.0 + 10.0;
        // Late in the stream, new bins are even less desirable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    } else {
        // Using existing bins is favored when many are open.
        score -= (open_bins_count as f64) * 1.5;
    }

    // Mild tie-break toward bins tighter than the mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        score += diff as f64 * 0.9;
        // Strong bonus for exact 2-step match (residual exactly fits next item).
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Also reward a fit that leaves the next item placeable with small slack.
        if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
        // Penalize if placing here makes next item unplaceable in this bin.
        if post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    } else {
        // Last item: prefer tightest fit only.
        score -= 5.0;
    }

    // Prefer bins below mean residual (using up "wasted" space) when fit is good.
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.5 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize new-bin candidate slightly so we only open when fits are poor.
    if bin_residual == bin_capacity {
        score += 8.0;
        // But if no open bin can fit, opening is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // If next item is large and this bin would be opened anyway, mild bonus.
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 3.0;
        }
    }

    // Dead-space penalty: very small post_residual is fine, but mid-range gaps are bad.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score -= 3.0; // nearly perfect packing
    } else if pr >= 10.0 && pr <= 30.0 {
        score += 1.0; // awkward dead zone
    }

    // Mild time pressure: as stream progresses, favor consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space: residuals too small to fit a typical future item.
    let min_useful = 10u32;
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0;
    } else if post_residual < 20 {
        score += 8.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size <= bin_residual {
            // current bin could have served next item; mild penalty
            score += 5.0;
        }
        // reward leaving space compatible with the next item's complement
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score += 0.05 * gap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is expensive when few bins
    // are open or many bins already exist with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.1);
        score += 25.0 + 10.0 * progress - 0.2 * pressure;
        // opening a new bin is fine if it perfectly hosts the item
        if item_size == bin_capacity {
            score -= 60.0;
        }
    }

    // Prefer bins whose residual is close to item_size (best-fit flavor),
    // scaled by global slack so tight streams reward consolidation.
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * diff * (mean_residual / bin_capacity as f64).max(0.5);

    // Mild preference to fill bins with above-average residual (balance load).
    score += 0.03 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling: quadratic dead-space penalty growing with stream progress
    let dead_space = norm_pr * norm_pr;
    score += 40.0 * progress * dead_space * cap;

    // Cubic interaction: penalize large residuals more as stream advances
    score += 15.0 * progress * norm_pr * norm_pr * norm_pr * cap;

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 30.0 * progress);

    // Last-chance bonus: only one bin fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 12.0 * progress;
    } else if next_item_size > 0 {
        // next item won't fit here; mildly penalize wasting residual space
        score += 5.0 * norm_pr * (1.0 - progress);
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins) smoothly
    let dev = (mean_residual - pr) / cap;
    score += 6.0 * dev * dev * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless residual would be large and stream is late
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
        if post_residual as f64 > 0.5 * cap {
            score -= 6.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that fall into
    // "useful" classes (small dead space, divisible nicely by common item sizes).
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Fraction of capacity left as dead space; penalize small-but-nonzero
        // residuals (unusable slivers) more than proportionally.
        let frac = pr / cap_f;
        if frac < 0.10 {
            score += 40.0 * (0.10 - frac) / 0.10; // sliver penalty
        }
        // Integer-division classes: residual in [1,10] is nearly dead.
        let dead_class = post_residual / 10; // 0 => 0..9 residual
        if dead_class == 0 {
            score += 25.0;
        }
        // Reward residuals that are multiples of common size classes (10s).
        if post_residual % 10 == 0 && post_residual >= 10 {
            score -= 12.0;
        }
        // Lookahead harmonic: does next_item_size fit exactly or in a good class?
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 200.0; // chain-perfect fit
            } else if next_item_size < post_residual {
                let nxt_post = post_residual - next_item_size;
                if nxt_post % 10 == 0 { score -= 15.0; }
                if nxt_post < 10 { score += 10.0; } // creates sliver after next
                score -= (nxt_post as f64) * 0.15; // prefer bins usable by next item
            } else {
                score += 8.0; // next item won't fit here
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin gets a mild opening cost so we
    // prefer existing bins unless they fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
    }

    // Prefer bins tighter than average (below-mean residual => better fit).
    score += (pr - mean_residual) * 0.5;

    // Slight progression-aware pressure to consolidate late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * (0.1 + 0.2 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving a gap that the lookahead item can use.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if post_residual cannot fit the next item (dead space relative to lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bins pressure: more open bins -> penalize placements that waste space
    // (encourage closing out bins with tight fits, discourage sprawl).
    score += open_bins_count as f64 * 0.6 * (post_residual as f64 / bin_capacity as f64);

    // Tight fit relative to mean residual is attractive.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when the item is large and would leave
    // a well-shaped residual; otherwise discourage opening a new bin.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        if fill > 0.5 {
            score -= 15.0 * fill;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect chain (item + next item fills bin) is heavily rewarded.
    if next_item_size > 0 {
        let chain = post_residual as i64 - next_item_size as i64;
        if chain == 0 {
            score -= 120.0; // exact two-item fill: ideal
        } else if chain > 0 && chain <= 10 {
            score -= 60.0; // near-exact chain fill, minimal dead space after both items
        } else if chain < 0 && (-chain) as u32 <= post_residual {
            // next item fits but leaves slack; reward proportional to small slack
            score -= 25.0 * (1.0 - (chain.abs() as f64) / 30.0).max(0.0);
        } else if chain < 0 {
            score += 10.0; // next item won't fit here anyway
        }
        // Reward bins whose post_residual sits close to next_item_size (soft matching)
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        score -= 20.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
    } else {
        // Last item: just minimize waste
        score -= 30.0;
    }

    // Penalize creating tiny unusable dead space (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Relative-to-mean coupling: prefer tighter-than-average bins
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: only fitting bin -> avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Early in stream: encourage consolidation into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64 / (total_items.max(1) as f64)).min(1.0);

    // Mild penalty for opening a new bin when open bins exist and fit
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness;

    // Penalize unusable dead space: residual too small for the smallest plausible item.
    let min_item = 1.0;
    if (post_residual as f64) > 0.0 && (post_residual as f64) < min_item {
        score += 50.0;
    }
    // Soft penalty for residuals that are likely dead (very small but nonzero).
    if post_residual > 0 && post_residual < 8 {
        score += 6.0 * (8.0 - post_residual as f64);
    }

    // Lookahead: if the next item would exactly fill post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits here too: mildly good, but leaving room matters.
            score -= 5.0 * (next_item_size as f64 / cap);
        } else {
            // Next item cannot use this bin's leftover: penalize proportionally.
            score += 3.0 * (post_residual as f64 / cap);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying over the stream horizon.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 0.85 * cap + 10.0 * (1.0 - progress);
        // If no open bin can fit the item, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Prefer opening new bins early when mean residual is high (fragmentation).
        if mean_residual > 0.5 * cap {
            score -= 15.0;
        }
    }

    // Global fragmentation pressure: many open bins with high mean residual -> consolidate.
    let frag = (open_bins_count as f64).sqrt() * (mean_residual / cap);
    if bin_residual != bin_capacity {
        score -= 4.0 * frag * (bin_residual as f64 / cap);
    }

    // Mild time-horizon term: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - (post_residual as f64 / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap; // normalized post-residual in [0,1]

    // Base: reward small post-residual (good fit), non-linearly
    let mut score = 100.0 * norm_pr.powf(1.7);

    // Smooth quadratic coupling of post-residual with stream progress:
    // later in the stream, compact placements matter more
    score += 25.0 * norm_pr * norm_pr * (0.5 + progress);

    // Penalize large residual when item is small relative to bin (wasteful fit)
    let fit_ratio = item_size as f64 / cap;
    score -= 30.0 * fit_ratio * (1.0 - norm_pr).powf(2.0);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = pr - nxt;
        if slack >= 0.0 {
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            score += 8.0 * ((-slack) / cap);
        }
    }

    // Mild penalty when bin is far below mean residual (creates outlier dead space)
    score += 5.0 * ((mean_residual - pr).abs() / cap);

    // New-bin candidate: discourage opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - progress) + 15.0 * fit_ratio;
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues modulo 10.
    // Residues in [1,9] are "dead space" classes (no item of size 10..80 fits),
    // while residue 0 (or 100-class) is harmonic and reusable.
    let r = post_residual % 10;
    if post_residual > 0 && r != 0 {
        // Penalize dead-space residues; smaller nonzero residues are worse.
        score += (10 - r) as f64 * 3.0;
    }

    // Perfect fit: harmonic residue 0 gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if r == 0 {
        score -= 12.0;
    }

    // Check if the next item fits exactly into the post-residual (harmonic chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 55.0; // chain closes perfectly
        } else if gap % 10 == 0 {
            score -= 20.0; // harmonic chain
        } else {
            score += (gap % 10) as f64 * 0.8; // non-harmonic chain leaves debris
        }
    } else if next_item_size > 0 {
        // Next item cannot reuse this bin's leftover: leftover is likely dead.
        score += post_residual as f64 * 0.35;
    }

    // Last-chance bin before opening a new bin: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): post_residual = capacity - item_size.
    // Penalize opening a new bin unless the residual is large and harmonic,
    // i.e. the item is small; encourage reuse of open bins otherwise.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 20.0 * progress + 0.15 * open_bins_count as f64;
        if post_residual % 10 == 0 && post_residual >= 20 {
            score -= 18.0; // small item opening a harmonic bin is acceptable
        }
    }

    // Slight preference for bins whose residual deviates from the mean
    // (consume the outliers, keep homogeneous residuals).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (min size 10) can use are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }
    // Gaps in [10, 30) are hard to fill: escalating penalty.
    if post_residual >= 10 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits (small post_residual relative to bin).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = (post_residual - next_item_size) as f64;
        score -= 60.0 - next_tight * 1.5;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin's leftover: penalize leaving stranded space.
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // but encourage consolidation when few bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open.
        score += 40.0 + bin_pressure * 6.0;
    } else {
        // Slight reward for filling existing bins, scaled by pressure.
        score -= bin_pressure.min(30.0) * 0.5;
    }

    // Prefer bins whose residual is below mean (tighter bins get priority).
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let waste = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - waste / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // post residual too small for next item: penalize dead space
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Relative to mean residual: prefer bins with residual below mean (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize new-bin opening when existing bins fit reasonably well
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
    }

    // Slight preference to fill bins that are already fairly full
    score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(3) * 40.0;

    // Penalize dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size <= bin_residual && post_residual > 0 {
            score += 8.0;
        }
        // Bonus if next item exactly fills post_residual (perfect pairing).
        if post_residual == next_item_size && next_item_size > 0 {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: only open a new bin when current fits are poor
    // or the item is large and would leave a badly fragmented open bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = fit_ratio > 0.5 || (fitting_bins_count == 0);
        let big_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if poor_fits || (big_item && open_bins_count > 2) {
            score -= 15.0 + 10.0 * progress;
        } else {
            score += 35.0;
        }
    }

    // Global fragmentation pressure: if mean residual is high, prefer filling
    // the bins with larger residuals less; encourage balancing.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64 * fit_ratio;

    // Time horizon: later in the stream, tighten up (prefer exact fills more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, waste matters more, so amplify post_residual quadratically.
    let amp = 1.0 + 2.0 * progress * progress;
    score *= amp;

    // Reward tight fits: small post_residual relative to capacity gets subtracted smoothly.
    let tight = (1.0 - post / cap).powi(3);
    score -= 25.0 * tight * (0.5 + progress);

    // Lookahead: if the next item fits the post residual, reward this placement smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_frac = (next_item_size as f64) / cap;
        score -= 12.0 * (fit_frac * (1.0 + progress)) * (post / cap);
    } else if next_item_size > 0 {
        // Penalize creating residual that next item cannot use.
        score += 6.0 * (1.0 - post / cap) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize slightly when open bins exist, more so early/mid stream.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 8.0 + 15.0 * (1.0 - progress) + (open_bins_count as f64).sqrt() * 2.0;
    } else {
        // Favor bins whose residual deviates from mean residual (consolidate waste).
        let dev = (bin_residual as f64 - mean_residual).abs() / cap;
        score -= 5.0 * dev * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Harmonic class of post_residual: residuals that are "nice" multiples
    // (multiples of 10 or 25) are reusable by common item sizes -> reward.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect closure
    } else if pr % 10 == 0 {
        score -= 8.0;
        if pr % 50 == 0 { score -= 6.0; }
    } else if pr % 5 == 0 {
        score -= 3.0;
    } else {
        score += 5.0; // awkward residual
    }

    // Dead-space penalty: residual too small for the smallest plausible item (<=10)
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: does post_residual fit the next item exactly / at all?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // perfect chain
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
            // integer-division threshold: how many next-items could stack
            let k = pr / next_item_size.max(1);
            if k >= 2 { score -= 5.0 * (k.min(4) as f64); }
        } else {
            score += 12.0; // next item won't fit here; residual becomes dead
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // when many bins fit, tighten selection pressure
        score += (fitting_bins_count as f64) * 1.5;
    }

    // New-bin candidate handling: empty bin gets a moderate opening cost,
    // but attractive when current bin would leave bad residual.
    if bin_residual == bin_capacity {
        score += 15.0;
        if post_residual % 10 == 0 && post_residual > 0 { score -= 5.0; }
        if open_bins_count == 0 { score -= 30.0; }
    }

    // Stream progression: later in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (mean_residual - post_residual as f64).abs() * 0.05 * (1.0 + progress);

    // Mild penalty for spreading across too many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Heavy penalty for small unusable dead space (gaps that likely can't fit future items)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Open bins pressure: penalize creating many open bins, reward filling existing ones
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would leave this bin unusable anyway, slight penalty
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average (tighter bins)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: make empty bin attractive only when open bins are tight
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 / 8.0) + (mean_residual / bin_capacity as f64);
        score += 20.0 - pressure * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual is already the base score).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item fits exactly into the leftover: strong reward.
            if diff <= 2.0 {
                score -= 300.0;
            } else if diff <= 10.0 {
                score -= 100.0 / (1.0 + diff);
            } else {
                score -= 60.0 / diff;
            }
        } else {
            // Next item won't fit in the leftover: penalize large unusable gap
            // relative to mean residual.
            score += 0.3 * diff + 0.2 * (mean_residual - post_residual as f64).abs();
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when decent open bins exist,
    // unless the item is large and would leave a bad residual elsewhere.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count > 0 {
            // New bin is only attractive for large items that fit poorly elsewhere.
            score += 40.0 + 60.0 * (1.0 - tightness);
        } else {
            score -= 100.0; // must open a new bin anyway
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // Slight preference early in the stream to keep residuals balanced.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64 > mean_residual.max(1.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        if poor_fit {
            score -= 12.0 + 10.0 * progress;
        } else {
            score += 15.0 + 5.0 * (1.0 - progress);
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward; if it
    // would be blocked, penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 10.0 {
                score -= 8.0; // perfect chain fit
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    if open_bins_count > 3 && mean_residual > 40.0 && bin_residual as f64 <= mean_residual {
        score -= 5.0;
    }

    // Mild preference for filling emptier bins when few remain usable.
    if fitting_bins_count <= 2 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress);
    score += 40.0 * poly;

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the next item (smooth quadratic gate)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        score += 25.0 * gap * gap * (1.0 + progress);
        // Reward leaving room exactly for the next item
        let match_term = 1.0 - ((pr - next_item_size as f64).abs() / cap).min(1.0);
        score -= 20.0 * match_term * match_term;
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Mild pressure from mean residual and open bin count
    score += 0.05 * (mean_residual - pr).abs();
    score += 0.1 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: penalize opening a bin unless residual is very tight elsewhere
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: harmonic classes of post_residual (mod 10 buckets)
    let class = post_residual % 10;
    match class {
        0 => score -= 30.0,          // perfectly clean residual class
        1 | 2 => score -= 18.0,      // near-perfect
        3 | 4 => score -= 8.0,
        5 => score += 5.0,           // half-empty class: mediocre
        6 | 7 => score += 3.0,
        _ => score += 1.0,
    }

    // Dead-space penalty: residuals below 10 are nearly unusable (min item 1..100, small items rare)
    if post_residual < 10 {
        score += 12.0;
    }

    // Reward filling the bin deeply relative to capacity fraction
    let fill_frac = 1.0 - post / cap;
    score -= fill_frac * 20.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // partial reward scaled by how well next item uses leftover
        score -= 10.0 * (next_item_size as f64 / post.max(1.0));
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // leftover too small for next item: penalize wasted potential
        score += 6.0 * (1.0 - post / cap);
    }

    // New-bin candidate handling: empty bin (residual == capacity)
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only if the stream is early or current bins are crowded
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalize new bin by default, less when many bins open (spread load)
        let mut nb = 15.0;
        nb -= (open_bins_count as f64).sqrt() * 2.0;
        nb -= progress * 10.0;
        // if next item is large, a fresh bin may serve it better
        if next_item_size >= 70 {
            nb -= 12.0;
        }
        // if mean residual across open bins is small, new bin is justified
        if mean_residual < (item_size as f64) * 1.2 {
            nb -= 20.0;
        }
        score += nb;
    }

    // Slight preference for bins already below mean residual (balance avoidance of fragmentation)
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead-space penalty scales with how small the gap is relative to the
    // smallest conceivable item (1..100 interface range).
    if post_residual < item_size {
        // gap can't fit even a copy of the current item: likely dead space
        score += 0.5 * (item_size as f64 - post_residual as f64);
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += 0.3 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the dead space is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if post_residual < 10 && post_residual > 0 {
            score += 20.0; // still penalize terrible dead space even at last chance
        }
    }

    // New-bin candidate handling: make empty bin attractive only when the item
    // is large and would leave a big clean residual, or when fits elsewhere are awful.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64;
        if item_size >= 50 {
            score -= 8.0;
        }
        // Early in stream, opening bins is cheap; later, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If many bins fit the item, opening a new bin is wasteful.
        score += 5.0 * (fitting_bins_count as f64).min(5.0);
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // next item won't fit here; dead space likely
    }

    // Mild preference to fill bins that are already relatively full.
    score += 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-item completion
        } else if next_item_size <= post_residual {
            let slack_after = post_residual - next_item_size;
            score -= 25.0 * (1.0 - slack_after as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: penalize dead space more
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Penalize residuals too small for typical future items (dead space)
    if post_residual < 10 {
        score += 15.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: mildly penalized so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 12.0;
        // but if lookahead suggests next item pairs well with a fresh bin, ease penalty
        if next_item_size >= 90 {
            score -= 10.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, with non-linear decay.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly use.
    // Items are >= 1; residual smaller than the smallest plausible item is waste.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slightly penalize leaving awkward space.
            score += 2.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing bins fit poorly (large post_residual) or bins are scarce.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, decaying as stream progresses
        // (early on, spreading items is cheaper; late, consolidate).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 14.0 * progress;

        // If many bins fit the item, discourage opening yet another bin.
        if fitting_bins_count > 1 {
            score += 8.0 * (fitting_bins_count as f64).ln();
        }
        // If no other bin fits well, new bin becomes competitive naturally.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can host the next item too; small discount.
            score -= 3.0;
        }
    }

    // Prefer filling bins that are already small-residual relative to the mean
    // (keeps a few bins tight rather than many bins loose).
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0).min(50.0) * 0.1;

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual, modulated by stream progress
    let mut score = pr * (1.0 + progress * (1.0 - norm_pr));

    // Cubic coupling: late in stream, small residuals are punished more
    score += progress * norm_pr * norm_pr * cap * 0.35;

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 12.0 * (0.5 + progress);

    // Penalize leaving residual close to mean residual (wasted overlap)
    score += 0.5 * (norm_pr - mean_residual / cap).abs() * cap * 0.2;

    // Last-chance bonus: only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (0.5 + progress);
    }

    // Lookahead: if next item fits exactly in post residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty on opening new bins when many bins open
    if bin_residual == bin_capacity {
        score += 6.0 + 0.4 * open_bins_count as f64 - 5.0 * progress;
        // But allow new bin if item is large relative to residual space in existing bins
        score -= 8.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fills are gold, tiny residues are good,
    // mid-range residues are dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 10 {
        score -= 18.0; // near-perfect fill
    } else {
        // Dead-space penalty: residue too small to host the lookahead item.
        if next_item_size > 0 && (pr as u64) < (next_item_size as u64) {
            score += 12.0 * (next_item_size - pr) as f64 / 20.0;
        } else {
            score -= 6.0;
        }
    }

    // Modulo-harmonic classes: residues that are multiples of 10 (or 5) remain
    // "usable" for the common size granularities.
    if pr > 0 && pr % 10 == 0 {
        score -= 5.0;
    } else if pr > 0 && pr % 5 == 0 {
        score -= 2.0;
    }

    // Last-chance bin: if this is the only open bin that fits, use it rather
    // than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate (pristine bin): penalize opening a new bin by default.
    if bin_residual == bin_capacity {
        score += 28.0;
        // Large items justify fresh bins (they leave harmonically small residues).
        if item_size >= 50 {
            score -= 16.0;
        }
        if item_size >= 70 {
            score -= 8.0;
        }
        // No open bin can host the item at all -> must open.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // If the fresh residue would be dead space for the lookahead item,
        // opening is still preferable to a mid-range residue elsewhere.
        if next_item_size > 0 && (pr as u64) < (next_item_size as u64) {
            score -= 12.0;
        }
    }

    // Reward large items entering bins (dense packing), scaled by capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    // Mild stream-phase coupling: early in the stream, be slightly more willing
    // to spread items across bins (more future flexibility).
    let phase = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 6.0 * (1.0 - phase);
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter bins first).
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
