    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize slightly so it's only chosen when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional progress through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: strongly reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (item_size as f64);

    // Penalize dead space that is too small for typical future items (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly / well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
            // Perfect lookahead fit is excellent.
            if post_residual == next_item_size {
                score -= 30.0;
            }
        } else {
            // Next item won't fit here; slight penalty proportional to leftover gap.
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Crowding effect: with many open bins, prefer consolidating into existing ones.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins whose residual is above the mean (consume the "fatter" space first),
    // scaled by stream progress so late placements become greedier.
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * (0.5 + progress);

    // New-bin candidate handling: opening a fresh bin should only win when the fit
    // into existing bins is poor or no bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of a new bin, reduced when many bins are open or early in stream.
        let mut new_bin_cost = 55.0 + 0.3 * open_bins_count as f64;
        new_bin_cost *= 1.0 - 0.4 * progress;
        // If the next item is huge, a fresh bin with full capacity is attractive.
        if next_item_size >= 60 {
            new_bin_cost -= 15.0;
        }
        score = new_bin_cost + item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, modulated smoothly by stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear polynomial coupling of post-residual with progress:
    // later in stream, penalize residual waste super-linearly.
    score += 40.0 * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // Reward tight fits (post_residual near zero) more strongly over time.
    score -= 30.0 * (1.0 - norm_pr).powi(6) * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits exactly in post-residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = (pr - nxt) / cap;
            score -= 20.0 * (1.0 - gap).powi(3);
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Slight penalty for spreading across many open bins relative to mean residual.
    score += 2.0 * ((open_bins_count as f64).ln().max(0.0)) * norm_pr;

    // Prefer bins whose residual is below the mean (consolidate waste).
    score += 5.0 * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that are "dead" (small, hard to fill) get penalized.
    let dead_zone = post_residual < 10;
    if dead_zone {
        score -= 40.0; // perfect closure is good
    } else {
        // modulo classes: residuals mod 10 near 0 are more reusable
        let residue = post_residual % 10;
        let class_bonus = match residue {
            0 => 12.0,
            1 | 9 => 6.0,
            2 | 8 => 3.0,
            _ => 0.0,
        };
        score -= class_bonus;
        // penalize mid-range dead space quadratically
        score += 0.15 * (post_residual as f64).powi(2) / bin_capacity as f64;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // reward if next item leaves another tight fit
        let next_post = post_residual - next_item_size;
        if next_post < 10 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here anyway; slight penalty for wasting space it could have used
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open new bin if current bin fit is terrible.
    if bin_residual == bin_capacity {
        // neutral baseline; adjust by stream progress and open bins pressure
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
        if post_residual == bin_capacity {
            // item is huge relative to capacity? not applicable; keep baseline
        }
    }

    // Prefer fuller bins (smaller post_residual) relative to mean residual.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Integer-division threshold: bins whose residual can hold a "half capacity" chunk are valuable.
    if post_residual >= bin_capacity / 2 {
        score += 10.0;
    } else if post_residual >= bin_capacity / 4 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    } else if post_residual < 20 {
        score += 150.0 * (20.0 - post_residual as f64) / 20.0;
    } else if post_residual == 0 {
        // Perfect fit is maximally rewarded.
        score -= 300.0;
    } else {
        // Reward tight fits proportionally.
        score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Coupling with next item: if the next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 80.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post residual cannot host the next item: penalize proportionally to gap size.
        score += 30.0 * (post_residual as f64 / 100.0);
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins when residuals are similar.
    score += open_bins_count as f64 * 3.0;

    // Prefer bins whose residual deviates below the mean (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Early in the stream, be more willing to open new bins for large items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive for large items early, penalized later.
        score -= 60.0 * (1.0 - progress) - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: exact match of post_residual with next item is gold.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain: next item exactly fills this bin afterwards.
        if diff == 0.0 {
            score -= 60.0;
        } else if next_item_size as f64 <= post_residual as f64 {
            // Next item still fits: reward closeness to a perfect second fit.
            score -= 25.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item won't fit here: penalize dead space left behind.
            score += 8.0 + 0.15 * post_residual as f64;
        }
    }

    // Prefer bins whose residual is already below average (tight packing),
    // penalize wasting large-residual bins on small items.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 6.0 * (mean_residual - res) / bin_capacity as f64;
    } else {
        score += 4.0 * (res - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when nothing fits well anywhere
    // or the item is huge relative to all residuals.
    if bin_residual == bin_capacity {
        let poor_fit_everywhere = fitting_bins_count == 0
            || (item_size as f64 > mean_residual * 0.9 && fitting_bins_count <= 1);
        if poor_fit_everywhere {
            score -= 20.0;
        } else {
            // Discourage opening new bins while good fits exist.
            score += 40.0 + 0.5 * (open_bins_count as f64);
        }
    }

    // Late in the stream, tighten up: waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) with a non-linear bonus.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.02;

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (bin_capacity as f64 - slack) * 0.3;
    } else if next_item_size > 0 {
        // Next item cannot use leftover; penalize dead space creation.
        score += post_residual as f64 * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= bin_capacity as f64 * 0.5;
    }

    // New-bin candidate: mildly penalize, but allow opening when current bins are crowded
    // or this is a perfect split for the next item.
    if bin_residual == bin_capacity {
        score += bin_capacity as f64 * 0.4;
        if item_size >= bin_capacity / 2 {
            score -= bin_capacity as f64 * 0.35; // big items are fine in a fresh bin
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= bin_capacity as f64 * 0.25; // planned pairing
        }
        score -= progress * bin_capacity as f64 * 0.1; // late stream: consolidate more
    }

    // Global state coupling: when mean residual is high, prefer reusing bins with
    // residuals near the mean (avoid fragmenting).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Prefer bins whose residual is small relative to remaining stream length.
    if post_residual < 10 {
        score -= 20.0; // nearly perfect fill
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (low post_residual), non-linearly scaled.
    let mut score = pr * (1.0 + 0.8 * (pr / cap) * (pr / cap));

    // Smooth interaction: post_residual vs stream progress.
    score += 12.0 * pr * progress * (1.0 - progress);

    // Penalize dead space relative to mean residual across open bins.
    score += 0.35 * (pr - mean_residual).abs();

    // Lookahead: reward bins whose post-residual fits the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 6.0 * (1.0 - pr / cap) * (nxt / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - pr / cap);
    }

    // Mild pressure against spreading across many bins early on.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Slight reward for filling existing bins as stream progresses.
    score -= 3.0 * progress * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "useful"
    // modular classes (multiples of 5, and small remainders) are preferred.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit: strongly reward
    } else if pr % 5 == 0 {
        -12.0 // clean multiple of 5: likely to match future item sizes
    } else if pr <= 10 {
        -6.0 // small dead space, nearly full bin
    } else if pr % 10 == 0 {
        -8.0 // multiple of 10: harmonic with capacity fractions
    } else {
        // penalize awkward remainders, worse for odd primes-ish values
        ((pr % 7) as f64) * 1.5
    };
    score += class_bonus;

    // Lookahead coupling: does post_residual fit the next item exactly or well?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let gap = pr - next_item_size;
            if gap == 0 {
                score -= 20.0; // chains a perfect fit
            } else if gap % 5 == 0 || gap <= 10 {
                score -= 8.0;
            } else {
                score -= 2.0;
            }
        } else {
            // post_residual cannot host next item: penalize proportionally
            score += ((next_item_size - pr) as f64) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible (large post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + (bin_capacity - pr) as f64 * 0.05;
    }

    // New-bin candidate handling: an empty bin should win only when open bins
    // offer poor fits (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        // neutral baseline: slight preference for reusing bins
        score += 15.0;
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0; // fresh bin guarantees next fit
        }
    }

    // Fractional capacity pressure: reward tight fills using capacity fractions.
    let fill = (bin_residual as f64) / (bin_capacity as f64);
    score -= fill * 5.0;

    // Mean residual spread: if this bin is far below mean residual, it is a
    // good "garbage collector" bin; if far above, placing here wastes space.
    let dev = (bin_residual as f64) - mean_residual;
    score += dev * 0.15;

    // Many open bins: encourage consolidation into tighter bins.
    if open_bins_count > 8 {
        score += (post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (small leftovers that few future items can fill) are heavily penalized.
    let gap = post_residual as f64;
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (13.0 - gap) / 13.0; // worst for residual ~1..12
    } else if post_residual > 12 && post_residual < 30 {
        score += 15.0 * (30.0 - gap) / 18.0; // mild penalty for awkward mid gaps
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item can exactly use the leftover, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            let leftover2 = post_residual as u32 - next_item_size;
            if leftover2 <= 12 {
                score -= 25.0; // chain of tight fits
            } else {
                score -= 8.0;
            }
        } else {
            // next item can't use this residual: leftover likely dead space
            score += 10.0 + nxt * 0.2;
        }
    }

    // Prefer bins whose residual is close to the item (best-fit core signal).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.5;

    // Open-bin pressure: discourage spreading across many open bins,
    // encourage filling existing bins rather than opening new ones.
    score += open_bins_count as f64 * 1.5;

    // If this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless it is truly needed
    // (i.e., many open bins already, or mean residual is very low).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 4.0 + mean_residual * 2.0;
        score += 35.0 + pressure * 0.5;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0; // fresh bin useful for huge next item
        }
    }

    // Mild drift: early in stream, slightly prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize any dead space beyond what the next item could consume.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post >= next {
            // Perfect 2-step match: this bin will be exactly refilled by the next item.
            let match_gap = post - next;
            score -= 40.0 / (1.0 + match_gap);
            // Extra reward for an exact chain fit (post_residual == next_item_size).
            if match_gap == 0.0 {
                score -= 25.0;
            }
        } else {
            // Post-residual too small for next item: dead space penalty grows with
            // how close (but short) we came, since it's a near-miss waste.
            let miss = next - post;
            score += 10.0 + miss * 0.5;
        }
    } else {
        // Last item: pure tightness maximization.
        score -= 20.0;
    }

    // Reward tight fits of the current item relative to the bin's previous slack.
    let fit_tightness = item_size as f64 / bin_residual as f64;
    score -= fit_tightness * 15.0;

    // Compare against mean residual across open bins: placing into a bin whose
    // residual is below average keeps many partially-filled bins alive.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.1;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Discourage opening a new bin when existing bins can reasonably absorb the item
    // (post_residual leaves a usable chunk >= typical small item size).
    if bin_residual == bin_capacity {
        let usable = post_residual as f64 >= 10.0;
        if usable && next_item_size > 0 && (post_residual as f64) < next_item_size as f64 + 10.0 {
            score += 15.0; // new bin would leave awkward large residual
        } else if post_residual == 0 {
            score -= 10.0; // perfect fill in a fresh bin
        }
    }

    // Slight preference for consolidating into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 30.0;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; penalize wasting residual it could have used elsewhere
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    let pressure = mean_residual / bin_capacity as f64;
    if open_bins_count > 2 && pressure > 0.3 {
        score -= 10.0 * pressure;
    }

    // Time horizon: early in stream, allow new bins for flexibility; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize late in stream, reward early.
        score += progress * 50.0;
        score -= (1.0 - progress) * 5.0;
        // Don't open a new bin when existing bins fit well.
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    } else {
        // Existing bin: slight reward late in stream.
        score -= progress * 10.0;
    }

    // Prefer bins whose residual is close to item size (minimize waste).
    let slack = (bin_residual - item_size) as f64;
    score += slack * 0.3;

    // Non-linear coupling of open bins and residual balance.
    score += (open_bins_count as f64).ln().max(0.0) * (slack / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: penalize wasted space, quadratically for large dead zones
    let mut score = pr + 12.0 * pr_norm * pr_norm * cap;

    // Smooth progress coupling: later in stream, reward tight fits more strongly
    let tightness = (1.0 - pr_norm).powi(3);
    score -= (8.0 + 14.0 * progress) * tightness * (1.0 + fit_ratio);

    // Interaction: post_residual vs mean residual — prefer bins below mean residual
    let mean_norm = mean_residual / cap;
    score += 6.0 * (pr_norm - mean_norm) * (0.5 + progress);

    // Lookahead: bonus if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 + 4.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // penalize leaving residual that nothing typical can use
        score += 3.0 * (pr / (next_item_size as f64).max(1.0)).sqrt();
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 * (0.5 + progress);
    }

    // Crowding: mild penalty when many bins open, encouraging consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * pr_norm;

    // New-bin candidate: make empty bin attractive only when item is large relative to residuals
    if bin_residual == bin_capacity {
        score = 18.0 + 30.0 * fit_ratio * (1.0 - progress) + 10.0 * (1.0 - fit_ratio) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover space into capacity fractions.
    let q = (post_residual * 4) / bin_capacity; // 0..3 classes
    let class_penalty = match q {
        0 => -6.0,  // dead space < 25%: bin is "sealed", good placement
        1 => 0.0,
        2 => 2.0,   // leaves awkward mid-size gap
        _ => 4.0,   // nearly empty bin after placing: wasteful
    };
    score += class_penalty;

    // Exact fit reward
    if post_residual == 0 {
        score -= 10.0;
    }

    // Lookahead coupling: does the leftover class accommodate the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item chains into this bin: reward, scaled by chain tightness
            let tightness = (next_item_size as f64) / (post_residual as f64);
            score -= 4.0 * tightness;
            // harmonic chain check: next item also leaves a low-class residue
            let next_post = post_residual - next_item_size;
            let nq = (next_post * 4) / bin_capacity;
            if nq == 0 {
                score -= 3.0;
            }
        } else {
            // leftover cannot host next item: penalize dead space creation
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive if this bin is crowded relative to mean
    if bin_residual == bin_capacity {
        let crowded = mean_residual < (bin_capacity as f64) * 0.35;
        if crowded {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Mid-stream: prefer filling existing bins; early stream: allow more bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (open_bins_count as f64) * 0.15;

    // Prefer bins tighter than the mean residual
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to hold
    // even the smallest plausible item are wasted forever -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (low post_residual relative to item size).
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 30.0 * (1.0 - fit_ratio.min(1.0));

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += (open_bins_count as f64) * 1.5;

    // If this is the only bin that fits, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for the next item: dead space penalty.
        score += 15.0;
    }

    // Mean-residual coupling: prefer bins whose residual deviates below the mean
    // (consolidating small leftovers into fewer bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.5 * dev;

    // New-bin candidate: opening a fresh bin is only attractive when no open bin
    // offers a decent fit (this call has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Extra pressure when many bins are already open.
        score += (open_bins_count as f64) * 2.0;
        // If other bins fit, make new bin clearly worse than any reasonable fit.
        if fitting_bins_count > 0 {
            score += 45.0;
        }
        // If the next item is large, a fresh bin preserves capacity for it.
        if next_item_size >= item_size && next_item_size > bin_capacity / 2 {
            score -= 35.0;
        }
    }

    // Slight early-stream leniency: keep bins flexible at the start.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.35 * next_item_size as f64;
    }

    // Penalize dead space that next item cannot use
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.25 * post_residual as f64;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight fit relative to bin residual
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Prefer reusing bins over opening new ones as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins open or high progress
        score += 10.0 + 8.0 * progress + 0.05 * open_bins_count as f64;
        // But if next item is large and no current bin likely fits both, allow new bin
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if nr <= pr {
            let slack = pr - nr;
            if slack == 0.0 {
                score -= 45.0;
            } else if slack <= 10.0 {
                score -= 20.0;
            } else {
                score += slack * 0.3;
            }
        } else {
            // Next item won't fit here; mild penalty proportional to gap.
            score += (nr - pr).min(50.0) * 0.2;
        }
    }

    // Prefer filling bins with small residuals when many bins are open.
    let openness = open_bins_count as f64 / (1.0 + step_index as f64);
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // As stream progresses, encourage consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.1;

    // New-bin candidate: make it less attractive unless residual is very poor.
    if bin_residual == bin_capacity {
        score += 25.0 + openness * 10.0;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: reward small post-residual with non-linear (quadratic) penalty for waste
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth coupling with stream progress: later in stream, penalize waste more
    score += 30.0 * progress * norm_pr;

    // Dead-space term: residuals too small for any item (min size 1, but typical small items)
    // smoothly penalize residuals in the awkward band via a smooth bump
    let band_center = 25.0;
    let band = ((pr - band_center) / 20.0).powi(2);
    score += 15.0 * (-band).exp() * (1.0 - progress);

    // Lookahead: reward leaving space for the next item smoothly
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit = (ns / pr).min(1.0).max(0.0);
        score -= 12.0 * fit * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for many open bins with high mean residual (fragmentation pressure)
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space penalty grows for small residuals
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction-of-capacity classes for post residual
    let frac = pr / c;
    if frac < 0.10 {
        score -= 30.0; // near-perfect fit, strongly reward
    } else if frac < 0.25 {
        score -= 10.0;
    } else if frac < 0.50 {
        score += 5.0;
    } else {
        score += 15.0; // half-empty bin wasted
    }

    // Integer-division thresholds on post_residual: harmonic residue classes
    let class = post_residual / 10;
    match class {
        0 => score -= 20.0,
        1 => score -= 8.0,
        2 => score -= 2.0,
        3 => score += 3.0,
        _ => score += 6.0,
    }

    // Modulo arithmetic: residuals divisible by common item sizes are reusable
    if post_residual > 0 {
        let mut reusable = 0u32;
        for m in [10u32, 20, 25, 50] {
            if post_residual % m == 0 {
                reusable += 1;
            }
        }
        score -= 6.0 * reusable as f64;
    } else {
        score -= 40.0; // exact fill
    }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // bonus if next item also lands in a harmonic class
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placements are poor
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 20.0; // big item coming, fresh bin may be wise
        }
    }

    // Stream progression: later in stream, consolidate more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - frac);

    // Mean residual coupling: prefer bins near the mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (1..=9) are almost unusable
    // since items are >= 1 but typically larger; heavily penalize them.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Medium dead space (10..=19) is only usable by small items; mild penalty.
    else if post_residual > 9 && post_residual <= 19 {
        score += 8.0 + 0.5 * (19.0 - post_residual as f64);
    }

    // Reward tight fits (post_residual near 0 but not dead space).
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    }

    // Last chance before opening a new bin: strongly favor using this bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: many open bins -> prefer consolidating into
    // existing bins; few open bins -> opening a new bin is cheaper.
    score += 0.6 * open_bins_count as f64;

    // If this is the brand-new empty bin candidate, make it attractive
    // only when existing bins would leave large dead space or pressure is low.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) + 0.6 * open_bins_count as f64;
        // Opening a new bin is bad when many bins are already open.
        score += 2.0 * open_bins_count as f64;
        // If the next item is large, keeping residual space elsewhere matters;
        // opening fresh space is fine early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits exactly in post_residual, reward this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Deviation from mean residual: prefer bins whose residual is close to
    // the mean (balanced packing) slightly.
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can
    // host the next item (chained placements are highly desirable).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits: strong bonus, scaled by how snugly it fits
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 25.0 + 0.5 * (bin_capacity as f64 - slack_after_next);
        } else {
            // Next item does not fit: penalize wasted potential,
            // worse when the leftover gap is small (dead space).
            let gap = post_residual as f64;
            score += 10.0 + (bin_capacity as f64 - gap) * 0.05;
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are
    // better targets for filling; loose bins are deprioritized.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize new-bin candidates mildly so they are only chosen
    // when all open bins score poorly (poor fits / dead space).
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    // Slight tightening pressure as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: heavily penalize wasted space relative to capacity.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_ratio * waste_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many bins compete, push toward best fit.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = post_residual - next_item_size;
        score -= 20.0 * (1.0 - leftover_after_next as f64 / bin_capacity as f64);
        if leftover_after_next == 0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty if it creates dead space.
        if post_residual < 10 {
            score += 10.0;
        }
    }

    // New-bin candidate logic: only attractive when current fit is poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, decaying over the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 35.0 * (1.0 - 0.5 * progress);

        // Extra penalty if this item fits reasonably well somewhere already.
        let fit_quality = 1.0 - (item_size as f64 / bin_residual as f64);
        if fit_quality < 0.5 {
            score += 50.0;
        }
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += 0.3 * mean_residual.max(0.0);
        // Few open bins with high mean residual -> definitely keep using them.
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 15.0;
        }
    }

    // Encourage consolidation: bins with residual far below mean are "odd" bins;
    // prefer filling them to normalize state.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= 0.1 * diff;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    let poly = 1.0 + 0.6 * progress - 1.2 * prog2 + 0.8 * prog3;
    score *= poly;

    // Reward tight fits: penalize (subtract) when post_residual is small relative to capacity
    let tight = (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 12.0 * tight * item_size as f64;

    // Penalize dead space that is too small to be useful (quadratic in norm_pr near zero)
    if norm_pr > 0.0 {
        let dead = (1.0 - norm_pr * 10.0).max(0.0);
        score += 8.0 * dead * dead;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_quality = 1.0 - ((pr - nxt) / cap).abs();
            score -= 10.0 * fit_quality * fit_quality * (1.0 + progress);
        } else {
            score += 4.0 + 6.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild pressure toward consolidation when many bins are open
    score += 0.5 * (open_bins_count as f64).log2().max(0.0) * (1.0 - tight);

    // Align with mean residual: prefer bins with residual below mean (more filled)
    let mr = mean_residual / cap;
    score += 5.0 * (norm_pr - mr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that sit in
    // "usable" classes (multiples of common small item sizes).
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect closure is best
    } else if pr % 10 == 0 {
        -25.0
    } else if pr % 5 == 0 {
        -12.0
    } else if pr % 3 == 0 {
        -6.0
    } else {
        8.0 // awkward dead space
    };
    score += class_bonus;

    // Coupling with lookahead: if the next item fits exactly into the
    // post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let new_post = pr - next_item_size;
            // harmonic quality of the residual after the lookahead item
            if new_post % 10 == 0 {
                score -= 18.0;
            } else if new_post % 5 == 0 {
                score -= 8.0;
            } else if new_post > 0 {
                score += (new_post % 5) as f64 * 2.5;
            }
        } else {
            // next item won't fit here: penalize more if residual is small
            // and thus wasted
            score += (pr as f64) * 0.15;
        }
    }

    // Fractional fill level: prefer bins that become well-filled.
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= fill * fill * 20.0;

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0 + 0.1 * (post_residual as f64);
    }

    // New-bin candidate: make empty bins moderately unattractive so we
    // reuse open bins unless the fit is clearly better (lower post_residual).
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if the stream is early and many bins are open, allow
        // spreading a bit more
        if open_bins_count > 4 {
            score -= 5.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a tight fit — reward compacting the stream.
    let dev = mean_residual - post_residual as f64;
    score -= dev * 0.3;

    // Late-stream tightening: near the end, close bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for even the
    // smallest plausible item (<= 10) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 40.0 + 2.0 * (10 - post_residual) as f64;
    } else {
        // Prefer tight fits: reward small usable residuals.
        score -= (bin_capacity - post_residual) as f64 * 0.3;
    }

    // New-bin candidate handling: opening a new bin is attractive when the
    // current bin would leave a bad gap, or when this is the last fitting bin
    // and the lookahead item would not fit anyway.
    if bin_residual == bin_capacity {
        // Slight preference for a fresh bin when open-bin pressure is low,
        // but avoid opening new bins excessively when many are open.
        score += 8.0 + 0.5 * open_bins_count as f64;
        // If the next item is large and the current bin fits it well, a new
        // bin is less attractive.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 0.05 * next_item_size as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Dead-space coupling with lookahead: if the post-residual cannot hold
    // the next item but is still nonzero, it risks becoming waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 6.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += 0.15 * open_bins_count as f64;

    // Mean-residual alignment: prefer bins whose residual is close to the
    // mean (keeps the pool of usable space balanced).
    score += 0.2 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the post residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Perfect chain: next item exactly fills the remainder afterwards.
        let chain_residual = post_residual - next_item_size;
        score -= 12.0 + 8.0 * (1.0 - chain_residual as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize dead space that the next item cannot use, scaled by how close it came.
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score += 4.0 + 6.0 * (gap / bin_capacity as f64);
    }

    // Relative residual vs mean: prefer bins that are tighter than average (waste-focused).
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 10.0 + 10.0 * fill_ratio;
    }

    // Brand-new bin candidate: penalize unless current bin would leave unusable dead space
    // and the next item is small enough to matter.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let dead = post_residual as f64;
        let next_fits_dead = next_item_size > 0 && post_residual >= next_item_size;
        // Opening a new bin is attractive when the alternative creates dead space
        // that the next item cannot consume.
        if !next_fits_dead && dead < 10.0 {
            score -= 6.0 + 4.0 * progress;
        } else {
            score += 5.0 + 10.0 * (1.0 - progress);
        }
    }

    // Small bonus for near-perfect fills (post residual tiny).
    if post_residual <= 3 {
        score -= 8.0;
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: reward if the next item fits the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // extra reward for near-exact chain fit
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= (1.0 - chain_waste / bin_capacity as f64) * 6.0;
        } else {
            // next item won't fit here; penalize small post residuals that strand space
            score += (post_residual as f64 / next_item_size as f64).max(0.0) * 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Global pressure: many open bins -> prefer filling existing bins tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score -= pressure * 0.8 + progress * 5.0;

    // Deviation from mean residual: prefer bins whose residual is below mean (denser bins).
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.15;

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; cheaper early when few bins are open.
        score = 55.0 + open_bins_count as f64 * 1.5 - progress * 15.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        // If next item is large and current item small, a fresh bin is more flexible.
        if next_item_size > 0 && next_item_size > post_residual + item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    // Smooth penalty growing with progress: leftover dead space matters more late.
    let coupling = norm_pr * norm_pr * (0.5 + 1.5 * progress * progress);
    score += 20.0 * coupling;

    // Reward tight fits (small post_residual) with smooth sigmoid-like bonus.
    let tight = 1.0 - norm_pr;
    score -= 10.0 * tight * tight * tight * (0.5 + progress);

    // Penalize waste relative to mean residual (non-linear interaction).
    let waste = (pr - mean_residual).max(0.0) / bin_capacity as f64;
    score += 8.0 * waste * waste * (1.0 + progress);

    // Last-chance bin bonus: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward leaving space for the next item (smooth quadratic).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.15 * gap * gap / bin_capacity as f64;
    }

    // Mild preference to consolidate into fewer bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        return -1000.0;
    }

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Residuals in the tiny "dead space" classes
    // are penalized unless a lookahead item can use them.
    let tiny_thresh = bin_capacity / 10;           // <=10 : nearly dead
    let small_thresh = bin_capacity / 5;           // <=20 : hard to reuse
    let half_thresh = bin_capacity / 2;            // <=50 : moderately reusable

    let next_fits = next_item_size > 0 && next_item_size <= post_residual;
    let next_fits_after = next_item_size > 0 && next_item_size <= post_residual.saturating_sub(1);

    if post_residual <= tiny_thresh {
        if next_fits {
            score -= 30.0; // tiny leftover is fine if lookahead uses it
        } else {
            score += 25.0; // dead space penalty
        }
    } else if post_residual <= small_thresh {
        if next_fits {
            score -= 20.0;
        } else {
            score += 8.0;
        }
    } else if post_residual <= half_thresh {
        if next_fits {
            score -= 12.0;
        } else {
            score -= 2.0; // mid-size leftover still broadly reusable
        }
    }

    // Integer-division harmonic class of item size: big items (>= half capacity)
    // should prefer near-exact bins; small items tolerate loose bins.
    if item_size >= bin_capacity / 2 {
        // reward minimal waste for large items
        score += (post_residual as f64) * 0.5;
    } else if item_size <= bin_capacity / 4 {
        score -= (post_residual as f64) * 0.1; // small items can absorb slack
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if next_fits_after {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Its raw score is capacity - item_size (large). Give it a mild discount so
    // it wins when open bins would create dead space, but not when a decent
    // fit exists.
    if bin_residual == bin_capacity {
        score -= 5.0;
        // penalize opening a bin for a small item early in the stream
        if item_size < bin_capacity / 3 {
            score += 10.0;
        }
    }

    // Lookahead coupling: reward bins whose post residual matches the next
    // item's harmonic class (modulo-10 bucket alignment).
    if next_item_size > 0 && post_residual >= next_item_size {
        let bucket_gap = (post_residual - next_item_size) % 10;
        score -= (10 - bucket_gap) as f64 * 0.8;
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (mean_residual - post_residual as f64).abs().min(10.0);

    // Slight preference for bins with residual near the mean (keeps spread even).
    score += ((post_residual as f64) - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.3 * next_item_size as f64;
    }
    // Penalize leaving a gap just below the next item (near-miss).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 30.0 + 4.0 * open_bins_count as f64;
    } else {
        score += 2.0 * open_bins_count as f64;
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably.
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Progression: later in the stream, be slightly more conservative with new bins.
    if total_items > 0 {
        let t = step_index as f64 / total_items as f64;
        if new_bin {
            score += 20.0 * t;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (small post_residual) is better.
    // Normalize post_residual by capacity.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = post / cap;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            // Next item fits perfectly: strong reward proportional to match quality.
            let match_q = 1.0 - gap / cap;
            score -= 25.0 * match_q * match_q;
            // Perfect chain (post == next) is ideal.
            if gap == 0.0 {
                score -= 20.0;
            }
        } else {
            // Next item does NOT fit in post_residual: penalize wasted lookahead space,
            // scaled by how much of the residual would be dead.
            let dead = nxt - post;
            score += 0.15 * dead.min(cap);
        }
    }

    // Compare post_residual against mean residual across open bins.
    // Leaving post_residual far below mean residual creates fragmented space.
    let dev = post - mean_residual;
    score += 0.08 * dev;

    // Penalize small unusable residuals (dead space < typical min item size).
    if post > 0.0 && post < 10.0 {
        score += 30.0 * (10.0 - post) / 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive early in the
    // stream or when no open bin offers a decent fit. An empty bin has huge
    // post_residual (= capacity) which already scores badly via the base term;
    // add extra penalty late in the stream to force consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
        // But if next item is large and this bin is fresh, slightly soften.
        if next_item_size as f64 >= 0.5 * cap {
            score -= 8.0;
        }
    }

    // Mild bonus for filling bins nearly completely (encourage closing bins).
    if post == 0 {
        score -= 12.0;
    }

    // Slight preference for bins with above-average residual when item is large.
    if item_size as f64 > 0.6 * cap {
        score -= 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual more than linearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect or near-perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            score -= 5.0; // keeps room for the next item
        } else {
            score += 3.0; // next item cannot use this bin's remainder anyway
        }
    }

    // Penalize opening new bins when there are many open bins with slack.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty grows with open bins and mean residual.
        score += 10.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.5;
        // Early in the stream, new bins are cheaper; late in the stream, fill existing ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 20.0;
        // If next item is large and this bin is empty, opening fresh can be good.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 12.0;
        }
    } else {
        // Reward using bins whose residual deviates favorably from the mean (consolidating slack).
        let dev = (bin_residual as f64 - mean_residual).abs();
        if (bin_residual as f64) < mean_residual {
            score -= dev * 0.3;
        } else {
            score += dev * 0.1;
        }
    }

    // Mild penalty when many bins fit the item: prefer the tightest anyway via quadratic term;
    // add small noise-free tie-breaker based on bin index proxy (residual ordering).
    if fitting_bins_count > 3 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post-residual with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.8 * x * (1.0 - x) * 4.0);

    // Polynomial coupling of post_residual with stream progress
    let coupling = x * x * (1.0 - progress) * 30.0
                 - x * progress * progress * 20.0
                 + x.powi(3) * (1.0 - progress) * 25.0;
    score += coupling;

    // Tight fit reward, stronger early in the stream
    let tightness = 1.0 - x;
    score -= tightness * tightness * item_size as f64 * (1.2 - 0.6 * progress);

    // Penalize dead space when few bins can fit the item
    if fitting_bins_count <= 1 {
        score -= 12.0 + 8.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 6.0 * (1.0 - ((pr - n) / cap).abs() - 0.5).abs().min(1.0);
        } else {
            score += 4.0 * (n - pr) / cap;
        }
    }

    // Mean residual interaction: prefer bins deviating smoothly from the mean
    let dev = (pr as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev * (0.5 + progress);

    // Mild pressure against hoarding too many open bins late in the stream
    score += open_bins_count as f64 * progress * 0.3;

    // New-bin candidate: prefer it when post-residual is large and progress is high
    if bin_residual == bin_capacity {
        score += 3.0 + 15.0 * progress * x;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: residual buckets via integer division thresholds
    let post = post_residual;
    let class = post / 10; // 0..=10 harmonic class of leftover space

    // Reward tight fits: small post_residual gets strong subtraction
    score -= (10.0 - class as f64) * 6.0;

    // Dead-space penalty: residual too small for typical items (1..100, min 1)
    if post > 0 && post < 10 {
        score += 25.0; // unusable sliver
    }

    // Harmonic modulo coupling: does next item divide nicely into post_residual?
    if next_item_size > 0 && post > 0 {
        if next_item_size <= post {
            // next item fits here: reward exact/near-exact division
            let nxt = next_item_size as f64;
            let ratio = post as f64 / nxt;
            if (ratio - ratio.round()).abs() < 0.01 {
                score -= 20.0; // perfect harmonic division
            } else {
                score -= 12.0; // next item fits, chain continues
            }
        } else {
            // next item won't fit in this bin's leftover
            score += (next_item_size - post) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize when many bins could fit (prefer concentrating load? no:
    // prefer spreading to keep flexibility — mild penalty for crowded bins)
    if fitting_bins_count > 3 {
        score += (fitting_bins_count as f64 - 3.0) * 1.5;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / cap; // low mean_residual => bins nearly full
        // Opening a new bin costs; penalize unless existing residuals are poor
        score += 55.0;
        score -= (1.0 - crowding) * 40.0; // if mean residual large, new bin unattractive
        score -= progress * 5.0;
        // If next item is huge, a fresh bin is valuable
        if next_item_size as f64 > 0.8 * cap {
            score -= 15.0;
        }
    }

    // Mild preference for bins below mean residual (balance load)
    score += (post as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (<= 9) are pure waste; penalize them hard.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }
    // Near-perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Penalize residuals just above small item sizes that waste capacity
    // (dead zone: 20..30 cannot host mid/large items efficiently).
    if post_residual >= 20 && post_residual < 30 {
        score += 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large relative to capacity or no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win by default.
        score += 30.0;
        // Large items pair well with a fresh bin (room for the lookahead too).
        if item_size >= 60 {
            score -= 25.0;
        }
        // If the next item can share a fresh bin with the current one, boost.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0;
        }
        // Heavy open-bin pressure makes a new bin more attractive.
        score -= (open_bins_count as f64) * 1.5;
    } else {
        // Reward placing into bins whose residual is well above item size
        // spread (avoid fragmenting many bins simultaneously).
        if (bin_residual as f64) > mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Lookahead coupling: if the post residual exactly accommodates the next
    // item, this placement chains perfectly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 12.0;
    }

    // Mild stream progression: later in the stream, consolidation matters
    // more, so penalize spreading into many open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (open_bins_count as f64) * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual, especially perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let fit_ratio = post_residual as f64 / bin_capacity as f64;
        score -= 30.0 * (1.0 - fit_ratio).powi(3);
    }

    // Penalize dead space: post_residual that is too small for any plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't chain here; mild penalty proportional to leftover.
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer the fullest (smallest residual).
        score += 0.1 * bin_residual as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits poorly everywhere else. Give it a baseline cost that grows with stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 + 30.0 * progress;
        // But if item is large, opening fresh may be wise.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into existing bins rather than opening new ones.
    if mean_residual > item_size as f64 {
        score -= 5.0;
    } else {
        score += 0.2 * (item_size as f64 - mean_residual);
    }

    // Slight preference for bins whose residual is close to item_size (minimal waste).
    let waste_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * waste_gap;

    // Time horizon: early in stream, be slightly more liberal with new bins;
    // late in stream, pack tightly.
    score -= 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling: penalize residual more strongly as stream progresses
    let progress_coupling = pr * (0.5 + progress * progress);
    score += 0.35 * progress_coupling;

    // Quadratic dead-space penalty for small residuals
    score += 0.9 * ((cap * 0.2 - pr) / cap).max(0.0).powi(2) * cap;

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= pr) as f64;
        score -= 12.0 * fits_next * (1.0 - progress * 0.5);
        score += 6.0 * (1.0 - fits_next) * (pr / cap).powi(3);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - 0.3 * progress);
    }

    // Mean-residual divergence: penalize bins far from the mean
    score += 0.4 * (pr - mean_residual).abs() / cap;

    // New-bin candidate handling: slightly penalize opening bins early, allow late
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).max(1.0);
        score += (30.0 - 18.0 * progress) / scarcity;
    }

    // Mild tie-break on tightness of fit
    score += 0.15 * (item_size as f64 / cap) * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space below the smallest
    // possible item (size 1) is pure waste, but small usable gaps matter more
    // depending on which harmonic band they fall into.
    let cap_f = bin_capacity as f64;

    // Class the post_residual into capacity fractions (harmonic bands).
    let frac = post_residual as f64 / cap_f; // in [0, 1]
    if frac < 0.05 {
        // Near-perfect fit: strongly reward.
        score -= 30.0;
    } else if frac < 0.15 {
        // Tiny gap: likely dead space, penalize.
        score += 12.0;
    } else if frac < 0.35 {
        // Mid harmonic band: mild penalty.
        score += 4.0;
    } else {
        // Large residual: still flexible, mild reward relative to raw value.
        score -= 6.0;
    }

    // Integer-division threshold: post_residual divisible by common item
    // classes (multiples of 10 / 5) is more likely reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 8.0;
        } else if post_residual % 5 == 0 {
            score -= 3.0;
        }
        // Odd leftover below 10 is nearly unusable.
        if post_residual < 10 {
            score += 10.0;
        }
    } else {
        // Perfect closure.
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this is a harmonic chain — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let nfrac = next_item_size as f64 / post_residual.max(1) as f64;
            if nfrac > 0.7 {
                score -= 10.0;
            } else if nfrac < 0.2 {
                score += 5.0; // leaves another sliver behind
            }
        } else {
            // Next item won't fit here regardless; neutral.
            score += 1.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual < 10 {
            score -= 5.0; // closing it out entirely is fine
        }
    }

    // New-bin candidate: neutral raw score = capacity. Encourage opening a new
    // bin only when existing bins would leave bad gaps, and discourage when
    // many bins already fit the item.
    if bin_residual == bin_capacity {
        score += (fitting_bins_count as f64) * 4.0;
        // Early in the stream, opening bins is cheap; later, prefer packing.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates favorably from the mean
    // (tighter-than-average bins get priority to consolidate waste).
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 4.0;
    } else {
        // Larger usable residuals are mildly rewarded.
        score -= 2.0;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tightness reward: fraction of bin filled by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the fit is poor
    // or the item is large enough to justify fresh space.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= 50 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    score += 0.3 * open_bins_count as f64;

    // Prefer bins with below-mean residual (tighter bins get filled first).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item would fit into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item is large and this bin can't help it, slight penalty for wasting a good bin.
    if next_item_size > bin_residual {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can exactly/nearly accommodate the next item (chained placements).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // Reward chains; exact match gets the biggest bonus.
            let gap = post_residual as f64 - nxt;
            score -= 60.0 - gap.min(60.0);
        } else {
            // Penalize creating dead space the next item cannot use,
            // scaled by how close the next item is to fitting.
            let shortfall = nxt - post_residual as f64;
            score += 0.5 * shortfall.min(40.0);
        }
    }

    // Penalize wasted space relative to the fleet's mean residual:
    // bins far below mean residual are "tight" — prefer filling them
    // (lower score), bins above mean are loose.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a good (near-exact) fit. Give the fresh bin a
    // moderate penalty that good chain matches can overcome.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in the stream, new bins are cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If mean residual across open bins is small, open bins are nearly
        // full — a new bin becomes attractive.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 15.0;
    }

    // Slight preference for tight bins (small residual before placement).
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Mild penalty for scattering across many open bins.
    score += (open_bins_count as f64).sqrt() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill after placement.
    let fill = (item_size as f64) / cap;
    score -= 40.0 * fill * fill;

    // Penalize small dead space that is hard to reuse (post_residual far from 0 but below typical item sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / cap;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when item fits poorly in existing bins
    // (i.e., item is large relative to typical residual) or many bins are already open.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / mean_residual.max(1.0);
        let crowded = (open_bins_count as f64) / (1.0 + (step_index as f64).max(1.0) / (total_items.max(1) as f64));
        if pressure > 1.5 || fitting_bins_count == 0 {
            score -= 20.0; // opening a new bin is reasonable
        } else {
            score += 30.0 + 10.0 * (1.0 - fill); // discourage wasting a fresh bin
        }
        let _ = crowded;
    }

    // Mild preference for bins below mean residual (balance load).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Late in the stream, tighten packing (avoid spreading).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with a mild concave reward so tiny
    // residuals are disproportionately favored (tight packing).
    let mut score = pr_norm * (1.0 - 0.5 * pr_norm);

    // Smooth polynomial coupling with stream progress: as the stream
    // advances, penalize leftover space more strongly (encourage closing
    // bins tightly later in the stream).
    let progress_coupling = pr_norm.powi(2) * (0.5 + 2.0 * progress * (1.0 - progress) * 4.0);
    score += progress_coupling * cap * 0.1;

    // Lookahead: reward leaving room for the next item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_quality = 1.0 - (pr - nxt).abs() / cap;
        let usable = (fit_quality.max(0.0)).powi(2);
        score -= 2.0 * usable * (0.5 + progress);
    }

    // Last-chance bonus: strongly favor using the only bin that fits,
    // scaled smoothly by how full the bin already is.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fill = 1.0 - bin_residual as f64 / cap;
        score -= 5.0 + 5.0 * fill * fill;
    }

    // New-bin candidate: neutral baseline, slightly penalized when good
    // fits exist, so we only open new bins when residuals are bad.
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual / cap - 0.5).abs();
        score += 3.0 + 2.0 * mean_gap - 3.0 * progress;
    }

    // Mild penalty for spreading across many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftover mod capacity-fractions.
    // Residuals that are "harmonic" (divisible into common item sizes) are less wasteful.
    let r = post_residual;
    let harmonic = if r == 0 { 3.0 }
        else if r % 50 == 0 { 2.0 }
        else if r % 25 == 0 { 1.5 }
        else if r % 10 == 0 { 1.0 }
        else if r % 5 == 0 { 0.5 }
        else { 0.0 };
    score -= harmonic * 6.0;

    // Perfect fit: huge reward.
    if r == 0 { score -= 200.0; }

    // Dead space penalty: very small leftovers that no item (>=1, but practically >=10)
    // can use are wasted. Penalize tiny nonzero leftovers harder.
    if r > 0 && r < 10 { score += 40.0; }

    // Lookahead: does the next item fit into post_residual exactly / at all?
    if next_item_size > 0 {
        if next_item_size <= r {
            // Next item fits: reward, extra if it's a perfect follow-up fit.
            score -= 30.0;
            if next_item_size == r { score -= 60.0; }
            // Harmonic chaining: next item leaves another harmonic residual.
            let r2 = r - next_item_size;
            if r2 % 10 == 0 { score -= 15.0; }
        } else {
            // Next item won't fit here: mild penalty for this bin.
            score += 12.0;
        }
    }

    // Last chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is justified when the item fits poorly everywhere else
        // or the best existing leftover would be tiny/dead.
        // Base cost of opening a bin:
        score += 55.0;
        // Slightly cheaper to open early in the stream when few bins are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        // If many open bins already, discourage proliferation.
        score += 2.0 * (open_bins_count as f64).sqrt();
        // If next item is large, a fresh bin with room may be valuable.
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    } else {
        // Prefer tighter existing bins: reward small post_residual relative to mean.
        score -= (mean_residual - post_residual as f64).max(0.0) * 0.5;
    }

    // Prefer bins whose current residual was close to the item size (good fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: gaps that no item (>=1) can use are pure waste;
    // gaps in the "hard to fill" band (1..10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64;
    }

    // Perfect fits are gold.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to capacity.
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
        // But a new bin is fine if it enables a great lookahead pairing.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
    } else {
        // Existing-bin bonus scaled by how far the stream has progressed.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 + 10.0 * progress;
    }

    // Prefer bins below the mean residual (fill emptier bins first to consolidate).
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Lookahead synergy: if next item fits the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0 + 0.5 * next_item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }

    // Reward if next item still fits in this bin after placement (2-step lookahead)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + (post_residual - next_item_size) as f64 * 0.35;
    } else if next_item_size > 0 {
        // Dead space penalty scaled by how much next item overshoots
        let miss = (next_item_size - post_residual) as f64;
        score += 8.0 + miss * 0.6;
    }

    // Penalize post-residual that is too small to ever be useful (below min item size 1 => waste)
    if post_residual < 10 {
        score += 15.0;
    }

    // Relative-to-mean coupling: bins with residual far from mean are less attractive
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.25;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large and current residuals are tight
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = mean_residual < 25.0;
        let mut new_bin_score = 40.0 + progress * 20.0;
        if tight && item_size > 70 {
            new_bin_score -= 55.0;
        }
        if fitting_bins_count > 0 {
            new_bin_score += 30.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - chain / bin_capacity as f64);
        } else {
            score += 6.0;
        }
        // Perfect pairing: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Crowding: when many bins are open, prefer consolidation (tight fits).
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.15 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early on, be exploratory (slight preference for emptier bins);
    // late in stream, prioritize minimizing residual.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.05 * (bin_residual as f64 - post_residual as f64);
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: penalize bins far below mean residual (fragmented space).
    score += 0.08 * (mean_residual - bin_residual as f64).abs();

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        let open_waste = mean_residual;
        let good_fit_exists = fitting_bins_count > 0 && (bin_capacity as f64 - item_size as f64) > 0.0;
        // Base penalty so new bins are not opened casually.
        let mut new_bin_penalty = 45.0;
        // If item is large and mean residual is low, opening a bin is reasonable.
        if item_size > 60 && open_waste < item_size as f64 {
            new_bin_penalty -= 30.0;
        }
        // If lookahead item is large and no chain possible, new bin helps.
        if next_item_size > 50 && post_residual < next_item_size as f64 {
            new_bin_penalty -= 12.0;
        }
        if good_fit_exists && open_waste > item_size as f64 {
            new_bin_penalty += 20.0;
        }
        score += new_bin_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let prn = pr / cap;

    // Base: prefer small post-residual, with non-linear tightening
    let mut score = pr * (1.0 + 0.6 * prn * prn);

    // Smooth polynomial coupling of residual with stream progress:
    // late in the stream, small residuals become more valuable (pack tight)
    let late_boost = progress * progress * (3.0 - 2.0 * progress);
    score -= 8.0 * late_boost * (1.0 - prn);

    // Penalize residuals that no plausible future item can use (dead space)
    let dead = if pr > 0.0 { (prn * prn) * cap * 0.5 } else { 0.0 };
    score += dead;

    // Lookahead: reward bins whose post-residual fits the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_frac = 1.0 - (pr - nxt) / cap;
            score -= 6.0 * fit_frac * fit_frac;
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild pressure against proliferating bins when mean residual is high
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap);

    // New-bin candidate: keep it neutral-to-slightly-costly so it's chosen
    // only when no open bin offers a good fit
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * late_boost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post residual: residuals that are "nice" fractions
    // of capacity (0, 10, 20, 25, 50) are more reusable.
    let nice = |r: u32| -> f64 {
        let cls = match r % bin_capacity {
            0 => 0.0,
            10 | 20 | 25 | 50 => 1.0,
            _ => 2.0,
        };
        cls * 6.0
    };
    score += nice(post_residual);

    // Dead-space penalty: tiny unusable leftovers (1..10) are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead harmony: reward if the next item fits exactly into post_residual,
    // or into a harmonic companion (post_residual - next_item_size small).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let gap = post - nxt;
            score -= 10.0 - gap.min(10.0);
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 8.0; // exact divisor fit: perfect packing chain
            }
        } else {
            score += 4.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer filling bins below the mean residual (tighter bins first).
    score -= 0.3 * (mean_residual - post).max(0.0);

    // Modulo threshold on capacity fraction: penalize leaving > half empty
    // unless the bin is fresh.
    if post > cap * 0.5 && bin_residual != bin_capacity {
        score += 5.0;
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post / cap);

    // Mild penalty for opening a new bin when others fit, scaled by stream progress.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 12.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_useful = 10u32;
    if post_residual < min_useful && post_residual > 0 {
        // Dead space below the smallest possible item: totally wasted.
        score += (min_useful - post_residual) as f64 * 25.0;
    } else if post_residual > 0 {
        // Penalize residuals that are too small to fit the next item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 4.0;
        }
        // Mild convexity: prefer tight fits (small post_residual) nonlinearly.
        let pr = post_residual as f64;
        score += (pr / bin_capacity as f64).powi(3) * 30.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0 + (item_size as f64 / bin_residual as f64) * 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Prefer bins whose residual is close to the mean (keeps balance),
    // but only mildly, so tight fits dominate.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: make empty bins attractive only when the item
    // is large relative to capacity or no good fit exists elsewhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        // Large items start fresh bins cheaply; small items should reuse bins.
        score += 15.0 - fill_frac * 40.0;
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Slight late-stream tightening: as stream progresses, be greedier.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to bin capacity.
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64);

    // 2-step lookahead: reward when next item fits the post residual exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual as u32 - next_item_size) as f64;
        score -= 1.5 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize dead space.
        score += 0.8 * post_residual as f64 / bin_capacity as f64;
    }

    // Penalize bins far from mean residual (prefer typical bins unless last chance).
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: make it unattractive unless post residual is perfect for the future.
    if bin_residual == bin_capacity {
        score += 5.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Late in stream, tighten up: avoid wasting space near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual more than linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.85 {
        score -= 12.0 * (fit_ratio - 0.85) / 0.15;
    }

    // Penalize dead space that no future item (>=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty if post_residual is stranded
            if post_residual < next_item_size && post_residual > 0 {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Time horizon: early in stream, prefer consolidating into few bins;
    // late in stream, prefer tight fits / new bins for clean packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins with residual above mean (balance residuals across bins).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: open a new bin only if all open bins would leave bad leftovers.
    if bin_residual == bin_capacity {
        let bad_open = if post_residual == bin_capacity as f64 as u32 { 0.0 } else { 0.0 };
        let _ = bad_open;
        // Base cost of a new bin, discounted when open bins are crowded or fit is poor.
        let crowded = if open_bins_count == 0 { 0.0 } else { mean_residual / bin_capacity as f64 };
        score = 45.0 - 20.0 * crowded;
        // If next item is large and current open bins are full-ish, new bin is good.
        if next_item_size >= 60 && mean_residual < 30.0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear polynomial shaping
    let mut score = pr
        + 40.0 * norm_pr * norm_pr
        - 60.0 * norm_pr * norm_pr * norm_pr
        + 30.0 * norm_pr * norm_pr * norm_pr * norm_pr;

    // Progress coupling: later in the stream, penalize waste more strongly
    score *= 1.0 + 0.8 * progress * norm_pr;

    // Tight-fit reward (smooth, non-linear)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 * (next_item_size as f64 / cap);
    }

    // Penalty when this bin's residual deviates badly from the mean residual
    score += 5.0 * (pr - mean_residual).abs() / cap;

    // Slight penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    score *= 1.0 + (post_residual as f64 / bin_capacity as f64) * 2.0;

    // Harmonic classes: classify post_residual into capacity-fraction buckets.
    // Quarters of capacity: dead space in the lowest quarter is very bad.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual < quarter {
        score -= 25.0; // excellent: nearly full bin
    } else if post_residual < half {
        score -= 10.0; // good
    } else if post_residual < 3 * quarter {
        score += 5.0; // mediocre
    } else {
        score += 15.0; // poor: bin left mostly empty
    }

    // Integer-division classes: reward when post_residual is a multiple of a
    // small quantum (common small-item sizes), making future reuse likely.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 5 == 0) {
        score -= 3.0;
    }
    // Penalize awkward residues (odd, non-divisible slivers).
    if pr > 0 && pr % 2 == 1 && pr < 10 {
        score += 8.0;
    }

    // Lookahead: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chaining: next item exactly fills the leftover.
            if next_item_size == post_residual {
                score -= 30.0;
            } else {
                score -= 12.0;
            }
        } else {
            // Next item won't fit here; leftover becomes dead space risk.
            let waste = post_residual as f64;
            score += waste.min(20.0) * 0.5;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // heavily favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer existing bins unless the fit is bad and the stream is young.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening a new bin is cheap early, expensive late.
        let openness = 60.0 * (1.0 - progress);
        // Open a new bin only if no existing bin fits decently.
        if item_size > bin_capacity / 2 || fitting_bins_count == 0 {
            score -= openness;
        } else {
            // Slight penalty so a reasonable existing fit wins.
            score += 5.0;
        }
        // If mean residual across open bins is large, prefer packing there.
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    }

    // Mild penalty for proliferating bins.
    score += open_bins_count as f64 * 0.5;

    // Small nudge toward using bins with residual close to item size.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small dead space: post_residual that nothing can fit into
    // (items >= 1, so anything > 0 is technically usable, but small gaps below
    // typical item sizes waste capacity). Penalize gaps < 10 heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit reward: zero post_residual is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead space penalty scaled by how tight the gap is relative to capacity.
    if post_residual > 0 {
        score += 20.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Open bins pressure: with many open bins, discourage opening a new one
    // (new bin has bin_residual == bin_capacity, gets penalized here since
    // its post_residual is huge, but add explicit pressure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * open_bins_count as f64 + 20.0 * progress;
    }

    // Lookahead: if next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Prefer bins below mean residual (tighter packing).
    score += 0.3 * (mean_residual - bin_residual as f64).max(-50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when the next item exactly fills the post residual
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // reward if next item fits into post residual (chain packing)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + (post_residual - next_item_size) as f64 * 0.15;
    } else if next_item_size > 0 {
        // next item cannot use the leftover space -> dead space risk
        score += (next_item_size - post_residual) as f64 * 0.25;
    }

    // penalize tiny unusable leftovers (< 10% capacity)
    if post_residual < bin_capacity / 10 {
        score += 20.0;
    }

    // prefer bins tighter than average
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // mild pressure to close out bins when many are open
    score += open_bins_count as f64 * 0.5;

    // early stream: keep bins flexible; late stream: consolidate
    if total_items > 0 {
        let t = step_index as f64 / total_items as f64;
        score -= t * 8.0;
    }

    // make the new-bin candidate (empty bin) slightly unattractive unless leftovers are bad
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
        // Extra reward if next item exactly fills the remaining space.
        if post_residual == next_item_size {
            score -= 80.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize creating dead space too small for the next item.
        score += 0.5 * (post_residual as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Penalize dumping small items into nearly-full bins (preserve them for large items).
    if item_size <= 20 && bin_residual <= 40 {
        score += 40.0;
    }

    // Global state coupling: if mean residual is high, prefer consolidating into fuller bins
    // (i.e., bins with residual well below mean).
    let residual_gap = mean_residual - bin_residual as f64;
    score -= 0.3 * residual_gap;

    // Time horizon: early in the stream, be more willing to open/spread (mild new-bin tolerance);
    // late in the stream, strongly avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as the stream progresses.
        score += 30.0 + 120.0 * progress;
        // But if no open bin fits well (post_residual large), allow opening a fresh bin.
        if post_residual < 15 {
            score -= 50.0;
        }
    }

    // Encourage using bins when many are open (reduce fragmentation).
    if open_bins_count > 4 {
        score -= 0.5 * (open_bins_count as f64).min(20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Base: prefer tight fits, with non-linear (quadratic) waste penalty.
    let tight = item_size as f64 / cap;
    score += 6.0 * (pr / cap) * (pr / cap) * (1.0 + tight);

    // Smooth progress coupling: later in the stream, waste is more costly.
    score -= 8.0 * (1.0 - progress) * (pr / cap);
    score += 10.0 * progress * (pr / cap) * (pr / cap);

    // Last-chance bonus (smooth via reciprocal of fitting count).
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 2.0 / fitting_bins_count as f64;
    }

    // Lookahead: reward leaving room for the next item (smooth coupling).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score -= 4.0 * (1.0 - gap / cap).max(0.0);
        score += 3.0 * (gap / cap) * (gap / cap);
    }

    // Mean-residual coupling: penalize bins far from the mean (fragmentation).
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: mildly penalize opening a new bin unless residuals are low.
    if bin_residual == bin_capacity {
        score += 3.0 + 12.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits; penalize large dead space quadratically.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64 * 2.0);

    // Harmonic class of post_residual: modulo classes on capacity.
    let cap = bin_capacity as u32;
    let class = post_residual % (cap / 4); // classes 0..24
    // Residuals near class boundaries are more reusable; reward low classes.
    score -= (24 - class as f64) * 0.35;

    // Perfect-fit harmonic classes: residual divisible by common small divisors
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 25 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
    } else {
        score -= 15.0; // exact fill is excellent
    }

    // Integer-division threshold: residual >= next_item_size means chain-friendly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // Harmonic pairing: post_residual mod next_item_size small => good future fit
            let m = post_residual % next_item_size;
            score -= (next_item_size - m) as f64 * 0.15;
        } else {
            score += 5.0; // dead-ends the bin for the lookahead item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin would leave awkward residue.
    if bin_residual == bin_capacity {
        let awkward = (post_residual as f64) < 10.0 && post_residual > 0;
        if awkward {
            score += 12.0; // don't open new bin for near-perfect fit
        } else {
            score += 8.0; // mild bias toward filling existing bins
        }
        // Early stream: allow more bins; late stream: penalize opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 6.0 - progress * 4.0;
    }

    // Coupling with mean residual: bins far from the mean are handled harmonically.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Reward bins whose residual is in a "usable" harmonic band (10..=50).
    if post_residual >= 10 && post_residual <= 50 {
        score -= 4.0;
    }
    if post_residual > 80 {
        score += 2.0; // large leftovers risk waste
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead-space-aware penalty: post residual that cannot fit next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + (next_item_size as f64 - post_residual as f64) * 0.4;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 3.0;
    } else {
        // Slight preference for bins below mean residual (fills emptier bins less).
        if (bin_residual as f64) > mean_residual {
            score -= 3.0;
        }
        // Encourage tight fits relative to residual.
        score -= (item_size as f64 / bin_residual.max(1) as f64) * 10.0;
    }

    // Late-stream urgency: close bins tightly as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect / near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    }

    // 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if nxt <= post {
            // next item fits: reward proportional to leftover-after-next
            let after_next = post - nxt;
            score -= 300.0 + (post_residual as f64 - after_next) * 0.5;
            if after_next == 0.0 {
                score -= 400.0; // exact 2-item chain fill
            }
        } else {
            // next item won't fit: penalize leaving a gap just below next_item_size
            score += (nxt - post).min(50.0) * 2.0;
        }
    }

    // Relative residual vs mean: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 1.5;

    // Last-chance bin bonus: only fitting bin, use it before opening new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 120.0 + open_bins_count as f64 * 0.5;
        // but allow new bin if item is huge and no open bin fits well
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Dead-space penalty for large unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // small scraps still usable for tiny items
    } else if post_residual > 60 {
        score += 20.0; // large leftover may be wasteful split
    }

    // Late-stream conservatism: near the end, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Penalize small dead space that nothing can use (waste pockets)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            score -= 30.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty scaled by wasted gap
            score += 10.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: prefer existing bins unless this placement is bad
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost, plus more expensive later in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 + 80.0 * progress;
        // If many bins are open with lots of residual, discourage new bin
        score += 5.0 * open_bins_count as f64;
        // If next item is large and this item is small, a fresh bin keeps flexibility
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 40.0;
        }
    } else {
        // Reward using bins that are below mean residual (consolidate emptier bins)
        if (bin_residual as f64) < mean_residual {
            score -= 15.0;
        } else {
            score += 10.0;
        }
    }

    // Mild time-decay: later in stream, prioritize tight fits even more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: penalize post residual, but with a smooth non-linear shape
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerating residual is cheaper; late, pack tightly.
    let tight = (0.5 + 0.5 * progress).powi(2);
    score += 30.0 * tight * norm_pr * norm_pr;

    // Reward near-perfect fills (small residual) more as stream progresses
    score -= 20.0 * (1.0 - norm_pr).powi(3) * (0.3 + 0.7 * progress);

    // Lookahead: reward if next item fits the post-residual (smooth kernel)
    if next_item_size > 0 {
        let fit_gap = (pr - next_item_size as f64) / cap;
        let kernel = (-4.0 * fit_gap * fit_gap).exp();
        score -= 15.0 * kernel;
        // Penalize leaving residual that is awkwardly close to but below next item
        let miss = ((pr - next_item_size as f64) / cap).abs();
        score += 8.0 * (-30.0 * miss).exp() * (pr < next_item_size as f64) as i32 as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.3 * progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * norm_item;

    // Coupling with mean residual: prefer bins near the mean residual (balance)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: make it mildly attractive early, unattractive late
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes via integer division thresholds
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 10.0;
    } else if pr <= 30 {
        score -= 2.0;
    } else {
        score += (pr as f64 - 30.0) * 0.15; // large dead space penalty
    }

    // Modulo arithmetic on post_residual: values divisible by 10 are "harmonic"
    // (usable by typical item sizes 10..80)
    let harmonic = (pr % 10) == 0;
    if harmonic {
        score -= 8.0;
    } else {
        score += (10 - (pr % 10)) as f64 * 0.4; // non-harmonic waste
    }

    // Fraction of capacity wasted
    let waste_frac = pr as f64 / cap;
    score += waste_frac * waste_frac * 30.0;

    // Lookahead: if next item fits into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 35.0 + 0.3 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // how close next item is to fitting (harmonic distance)
        let gap = (next_item_size - post_residual.min(next_item_size)) as f64;
        score += 0.2 * gap;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is only good if current fit is terrible
        // or many bins are open with poor residuals
        let fit_badness = if post_residual > 40 { 1.0 } else { 0.0 };
        let crowding = (open_bins_count as f64 / 8.0).min(1.0);
        score = 80.0 - fit_badness * 40.0 - crowding * 15.0
            + (mean_residual / cap).min(1.0) * 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin good for upcoming large item
        }
    }

    // Late in stream: prefer closing bins tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - waste_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual gap is "dead" if it is too small for the smallest plausible item (1..100 range).
    // Treat gaps below a small threshold as pure waste; scale penalty non-linearly.
    let dead_threshold = 9.0; // gaps <= 9 are nearly unusable for typical items
    if post_residual > 0 && (post_residual as f64) <= dead_threshold {
        score += (dead_threshold - post_residual as f64) * 25.0;
    } else if post_residual == 0 {
        // Perfect fit is highly desirable.
        score -= 60.0;
    } else {
        // Larger usable gaps are mildly penalized but less than dead space.
        score += ((post_residual as f64) / 10.0).powi(2) * 0.5;
    }

    // Reward tight fits: small positive post_residual (but usable) is good.
    if post_residual > 0 && (post_residual as f64) > dead_threshold && post_residual <= 20 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits but leaves another gap; mild reward scaled by tightness.
        let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 15.0 * tight;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual too small for next item: penalize proportionally to how dead it is.
        score += (post_residual as f64 / 10.0) * 3.0;
    }

    // Open bins pressure: penalize selecting existing bins when many are open,
    // to avoid overloading a single bin while others sit idle... actually we want
    // to consolidate: fewer open bins is better, so reward placing into open bins
    // when open_bins_count is high (closing bins out).
    if bin_residual != bin_capacity {
        // Existing bin: reward consolidation, stronger when many bins open.
        score -= (open_bins_count as f64) * 2.0;
    } else {
        // New-bin candidate: penalize opening new bins when pressure is high.
        score += (open_bins_count as f64) * 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Stream progression: early in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 10.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a
    // laggard bin; prefer filling it to close it out.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.5;
    } else {
        score += (res_f - mean_residual) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack left
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 30.0 - 2.0 * slack;
        }
    }
    // Next item does NOT fit in this bin after placement: penalize dead space
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Very small post-residuals are likely unusable dead space
    if post_residual < 10 {
        score += 15.0 * (10.0 - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins tighter than the mean residual (compact packing)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Early in the stream, slightly discourage hoarding bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linearly).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tight * tight;

    // Penalize leaving dead space that nothing else could use well.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 5.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here; mild penalty proportional to wasted potential
        score += 1.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Many open bins: prefer consolidating into existing ones.
    score -= 0.4 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins with less residual (fuller bins)
    score += 0.5 * ((bin_residual as f64) - mean_residual).max(-20.0).min(20.0) / 10.0;

    // New-bin candidate handling: only attractive when item is large relative to
    // current residuals or no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Penalize opening new bins mildly; worse early in stream.
        score += 15.0 + 10.0 * (1.0 - progress) - 12.0 * fill_ratio;
        // If no open bin could fit, opening is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // If next item is huge and this item is small, opening fresh bin may pay off.
        if next_item_size > 60 && item_size < 30 {
            score -= 6.0;
        }
    }

    // Time horizon: late in stream, squeeze harder into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, smoothed with a non-linear polynomial coupling to progress
    let mut score = pr;

    // Quadratic dead-space penalty: small residuals are wasted space, penalty grows
    // as the stream progresses (end-game bins are less likely to be reused).
    let dead = (1.0 - norm_pr) * (1.0 - norm_pr);
    score += 12.0 * dead * (0.3 + 0.7 * progress);

    // Cubic interaction: reward tight fits (small post_residual) more strongly
    // as progress increases, using a smooth polynomial term.
    let tight = (1.0 - norm_pr).powi(3);
    score -= 9.0 * tight * (0.4 + 0.6 * progress);

    // Coupling with mean residual: bins whose post-residual deviates below the
    // mean are good fits; penalize if post-residual far exceeds mean (bad fit).
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * (1.0 - dev.abs()) * (0.5 + 0.5 * progress);

    // Lookahead: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - gap / cap) * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity.
    // Penalize it mildly early (prefer filling existing bins), but let it win
    // when progress is high and remaining bins are fragmented.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) * (1.0 - progress) - 4.0 * progress;
    }

    // Slight pressure to consolidate: fewer open bins relative to items is good.
    score += 0.15 * open_bins_count as f64 / (progress + 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space (integer division into capacity/5 classes)
    let class_width = (bin_capacity / 5).max(1);
    let post_class = post_residual / class_width;
    let next_class = (next_item_size as u32) / class_width;

    // Reward when the leftover falls into a class matching the next item's class
    if next_item_size > 0 && post_residual >= next_item_size as u32 {
        let class_match = (post_class as i64 - next_class as i64).abs();
        score -= 18.0 * (1.0 - (class_match as f64 / 5.0).min(1.0));
        // Exact near-fit for the lookahead item
        let slack = post_residual as i64 - next_item_size as i64;
        if slack >= 0 && slack <= 10 {
            score -= 22.0;
        } else if slack >= 0 && slack <= 25 {
            score -= 9.0;
        }
    }

    // Penalize dead space below the smallest plausible item (harmonic floor)
    let floor = (bin_capacity / 10).max(1);
    if post_residual < floor {
        score += 15.0;
    }

    // Modulo-3 residue of post_residual: small residues are "cleaner" fits
    let residue3 = (post_residual % 3) as f64;
    score -= 2.5 * (1.0 - residue3 / 2.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge or bin nearly empty
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = item_size as f64 > 0.75 * cap;
        let many_open = open_bins_count as f64 > 6.0;
        if !big_item && !(many_open && progress > 0.5) {
            score += 55.0;
        } else {
            score += 12.0;
        }
    }

    // Tight fit bonus: reward small post_residual relative to capacity fraction
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 10.0 * tightness * tightness;

    // Mild penalty for wasting a large bin on a small item
    if (item_size as f64) < 0.25 * cap && post_residual as f64 > 0.6 * cap {
        score += 8.0;
    }

    // Drift term to break ties and adapt to stream position
    score += 0.02 * ((step_index % 7) as f64) * (mean_residual / cap.max(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    let min_item = 1u32; // unknown distribution, assume small items possible
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny gap = dead space
    } else if post_residual == 0 {
        score -= 15.0; // perfect fit reward
    }

    // Penalize post_residual that cannot fit the lookahead item (dead space for next step)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0; // leaves room for next item
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones.
    let pressure = open_bins_count as f64 / 20.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: penalize slightly so it's only chosen when fits are bad.
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    // Mild tightness reward: less leftover relative to capacity is better.
    score -= (item_size as f64 / bin_capacity as f64) * 3.0;

    // Progress coupling: later in stream, be more conservative with dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 * 0.1);

    // Mean residual coupling: if open bins are already loose, discourage adding loose space.
    if post_residual as f64 > mean_residual {
        score += 2.0;
    } else {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled by capacity pressure.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Aggressive 2-step lookahead: reward when next item exactly fits the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chaining: this bin will be exactly filled by the next item.
            score -= 100.0;
        } else if next_item_size <= post_residual {
            // Next item still fits here; reward proportional to how well it chains.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= (1.0 - chain_waste / bin_capacity as f64) * 40.0;
        } else {
            // Next item cannot use the leftover; penalize dead space relative to gap size.
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(bin_capacity as f64) * 0.8;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average leftover is good (compact usage).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well,
    // unless the stream is early and spreading bins is beneficial.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress);
        if fitting_bins_count > 0 && post_residual <= 10 {
            score += 60.0; // don't open a new bin for a near-perfect existing fit
        }
    }

    // Slight penalty for leaving very small, hard-to-use slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild preference to consolidate into bins when many bins are already open.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).min(20.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { post_residual as f64 };
        score += 0.35 * dead;
    }

    // Lookahead: if next item fits in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // chain fit quality
        let chain_left = (post_residual - next_item_size) as f64;
        score -= 4.0 * (1.0 - chain_left / bin_capacity as f64);
    } else if next_item_size > 0 {
        score += 2.0; // next item won't chain here
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global residual pressure: if mean residual is high, prefer filling existing bins.
    let residual_gap = (bin_residual as f64 - mean_residual).max(0.0);
    score += 0.25 * residual_gap;

    // Time horizon: early in stream, be conservative (favor new bins for big items);
    // late in stream, squeeze everything into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * tightness;

    // New-bin candidate handling: empty bins get a mild penalty unless item is huge
    // or stream is early with many bins already open.
    if bin_residual == bin_capacity {
        let big = (item_size as f64) / (bin_capacity as f64);
        score += 10.0 - 10.0 * big * big;
        score += 1.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);
    }

    // Small bonus for perfectly filling a bin.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: mildly favor tight fits; later: strongly favor tight fits.
    let w = 0.5 + 2.5 * progress * progress;
    score -= w * (1.0 - (pr / bin_capacity as f64).powi(3)) * bin_capacity as f64 * 0.05;

    // Penalize dead space that next item cannot use (smoothly).
    if next_item_size > 0 {
        let waste = (next_item_size as f64 - pr).max(0.0);
        score += 1.5 * waste * (0.5 + progress);
        // Reward if next item fits exactly in the post residual.
        let fit_gap = (pr - next_item_size as f64).abs();
        score -= 0.8 * (1.0 - fit_gap / bin_capacity as f64).max(0.0) * (pr / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 30.0 * progress;
    }

    // Penalize opening new bins when many bins exist and fit is decent.
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * (open_bins_count as f64).ln().max(0.0) + 10.0 * (1.0 - progress);
        // Allow new bin if item is huge and mean residual is small.
        let huge = item_size as f64 / bin_capacity as f64;
        score -= 25.0 * huge * huge * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
    } else {
        // Slight preference for fuller bins (smaller residual).
        score += 0.05 * (bin_residual as f64);
    }

    // Smooth coupling with mean residual: prefer bins below mean residual (fuller).
    score += 0.3 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 create "dead zones".
    // Residuals that are multiples of 10 (or small residues) are reusable.
    let r = post_residual;
    let residue = (r % 10) as f64;
    // Penalize awkward residues (not near multiples of 10).
    score += residue * 0.8;
    // Reward exact multiples of 10 (perfect harmonic slots).
    if r % 10 == 0 && r > 0 {
        score -= 12.0;
    }

    // Integer division thresholds: classify post_residual into capacity fractions.
    let frac = r as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score -= 8.0; // large residual left: bin still very usable
    } else if frac > 0.2 {
        score += 2.0; // medium dead space
    } else if r > 0 {
        score += 10.0; // tiny sliver, nearly dead
    }

    // Perfect fit reward.
    if r == 0 {
        score -= 40.0;
    }

    // Lookahead harmonic coupling: does the next item divide into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            // next item fits here exactly or leaves a harmonic residue
            if r % next_item_size == 0 {
                score -= 15.0;
            } else {
                score -= 6.0;
            }
            // penalize if next item would leave a tiny useless remainder
            let rem = r - next_item_size;
            if rem > 0 && rem < 10 {
                score += 8.0;
            }
        } else {
            // next item cannot fit here; slight penalty for hoarding space
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bin attractive only when current
    // fit is poor (large post-residual waste) or few fitting bins.
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: its residual is the capacity
        score = bin_capacity as f64 * 0.55;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative
        }
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 5.0;
        }
        // early in stream, prefer consolidating: penalize new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    }

    // Tie-break with mean residual alignment: prefer bins whose residual
    // stays close to the mean (balanced packing).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Slight preference for filling already-open bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    // A residual is "dead" if no plausible future item (>= 1) can use it well.
    // Penalize heavily when post_residual falls into the awkward small band.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect fits (small post_residual relative to item size).
    if item_size > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.9 {
            score -= 30.0;
        } else if fill_ratio > 0.75 {
            score -= 15.0;
        }
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into a
    // fresh bin; with few open bins, consolidating is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; only attractive when
        // mean residual across open bins is too small to matter.
        score = bin_capacity as f64 + pressure * 10.0 - mean_residual * 0.5;
        // If the next item could still use the current bin's leftover space,
        // opening a new bin is less attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 20.0;
        }
    } else {
        // Reward using a bin whose leftover still fits the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        } else if next_item_size > 0 && post_residual > 0 {
            score += 5.0; // leftover too small for next item: mild penalty
        }
        // Slight preference for bins with larger residuals when pressure is low.
        score -= pressure * 2.0;
    }

    // Late in the stream, tighten up: avoid leaving scattered residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness
            score -= 200.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item does NOT fit: penalize leaving awkward gap
            score += 80.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Compare post_residual relative to mean residual: avoid fragmenting
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize unless current open bins are too full/fragmented
    if bin_residual == bin_capacity {
        score = 150.0 + mean_residual * 0.3;
        if next_item_size > 0 && next_item_size >= 90 {
            score -= 100.0; // big next item: prefer fresh bin
        }
        if post_residual == 0 { score += 1000.0; } // never "open" for perfect fit case
    }

    // Late stream: tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness * tightness;

    // Penalize leftover dead space that is too small for typical items (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 6.0; // hard-to-fill zone
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0; // perfect two-item pairing
        } else if post_residual >= next_item_size {
            score -= 10.0 * (post_residual as f64 - next_item_size as f64).min(30.0) / 30.0;
        } else {
            score += 8.0; // next item won't fit here; keep residual flexible instead
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a bin is cheap early, expensive late (fewer items left to fill it).
        score += 20.0 + 45.0 * progress;
        // If many open bins already fit the item, discourage a new bin.
        score += 8.0 * (fitting_bins_count.saturating_sub(1)) as f64;
        // If mean residual is large, existing bins have room; discourage new bin.
        score += 0.4 * mean_residual;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 60 {
            score -= 18.0;
        }
    } else {
        // Prefer bins with smaller residual overall (best-fit bias) modulated by open-bin count.
        score += 0.05 * (open_bins_count as f64) * (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    }

    // Late-stream consolidation: near the end, prefer filling existing bins completely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 {
        score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: wasted space after placement, mildly discounted as stream matures.
    let mut score = pr * (1.0 - 0.25 * progress);

    // Non-linear penalty on large dead space (quadratic coupling, normalized).
    let waste_frac = pr / cap;
    score += 30.0 * waste_frac * waste_frac * (0.5 + progress);

    // Reward leaving room for the lookahead item (smooth coupling with progress).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let tight = 1.0 - ((pr - nx) / cap); // tighter leftover fit -> larger bonus
            score -= 12.0 * tight * (1.0 - progress) + 6.0 * tight * progress;
        } else {
            // Post-residual cannot host next item: penalize proportionally to shortfall.
            let shortfall = (nx - pr) / cap;
            score += 8.0 * shortfall * shortfall;
        }
    }

    // Reward agreement between this bin's residual and global mean residual
    // (prefer bins whose residual is already small / consistent).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Last-chance bin before opening a new bin: strong smooth reward.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - waste_frac) * (0.6 + 0.4 * progress);
    }

    // Prefer consolidation when many bins are open (coupled with progress).
    let ob = open_bins_count as f64;
    score += 2.0 * (pr / cap) * (ob / (ob + 5.0)) * (1.0 + progress);

    // New empty bin candidate: penalize opening unless residual savings are real.
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress;
        // Allow opening when item is large (would leave little waste anyway)
        score -= 0.1 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band does it land in?
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / cap * 8.0).floor() as i32; // 0..8 harmonic classes

    // Reward tight fits (low class) progressively.
    score -= (8 - class.max(0)) as f64 * 2.0;

    // Perfect / near-perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Penalize dead space in awkward ranges (residuals that few item sizes can use).
    let awkward = |r: u32| -> f64 {
        match r {
            0 => 0.0,
            1..=9 => 0.5,
            10..=19 => -1.0,   // small items exist (>=1) so reusable
            20..=34 => 2.0,
            35..=49 => 0.0,
            50..=64 => 1.5,
            _ => 0.0,
        }
    };
    score += awkward(post_residual);

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // extra reward if next item nearly fills what remains
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; penalize wasted residual slightly
        score += pr * 0.05;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: default mild penalty so we prefer existing bins,
    // unless current fit is very poor (large post_residual) and mean residual is low.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64; // baseline residual of fresh bin
        score += open_bins_count as f64 * 1.0;
        // if this item would leave a huge hole in any existing bin, new bin looks good
        if post_residual >= 40 {
            score -= 10.0;
        }
        // early stream: allow more bins to spread
        if (step_index as f64) / (total_items.max(1) as f64) < 0.2 {
            score -= 5.0;
        }
    }

    // Modulo-threshold logic on post_residual: residuals in (50..60) are classic
    // dead zones (most items > 40 won't fit, small items waste space).
    if post_residual > 50 && post_residual <= 60 {
        score += 8.0;
    }
    // Residuals near half-capacity are highly reusable.
    if post_residual >= 45 && post_residual <= 50 {
        score -= 6.0;
    }

    // Slight preference to fill fuller bins first when many bins are open.
    score -= (bin_residual as f64 / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero post_residual is highly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead (k=2): reward residuals that can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a gap just below the next item size (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity, so its larger
    // post_residual is naturally penalized, but add extra coupling).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) + 10.0 * progress;
    } else {
        // Reward filling existing bins more when many are open.
        score -= 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
    }

    // Coupling with mean residual: prefer bins whose residual deviates
    // favorably from the mean (tighter than average bins get priority).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize proportional waste
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio;

    // 2-step lookahead: reward when post_residual closely matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_quality = 1.0 / (1.0 + gap / 10.0);
        if post_residual >= next_item_size {
            score -= 30.0 * match_quality;
        } else {
            score += 10.0 * (next_item_size as f64 - post_residual as f64) / 50.0;
        }
    }

    // Compare against mean residual: prefer bins below mean (tighter bins get used)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New bin candidate: penalize unless current bins have poor fits
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 15.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= item_size + next_item_size {
            score -= 15.0; // pair fits perfectly in fresh bin
        }
    }

    // Late stream: consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small leftover space.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * (1.0 - tight) * (1.0 - tight) * (1.0 - tight);

    // Exact / near-exact fit jackpot.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 5 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 15.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: slight penalty for leaving large unusable gaps.
            score += 5.0 * (post_residual as f64) / (bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.5 * item_size as f64;
    }

    // Penalize wasting large residual capacity when many bins are open.
    let waste = post_residual as f64 / bin_capacity as f64;
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += 8.0 * waste * waste * pressure;

    // Coupling with global mean residual: prefer bins whose residual deviates
    // favorably from the mean (below-mean residual bins get priority).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev;

    // Time horizon: early in the stream, be conservative (favor packing into
    // existing bins); late in the stream, allow more aggressive tight-fit chasing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * progress * (1.0 - waste);

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no decent fit exists.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is mandatory
        } else if item_size >= 60 && waste >= 0.2 {
            score -= 30.0; // large item, acceptable fresh placement
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let t = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: non-linear waste penalty (quartic-ish, smooth in x)
    let mut score = 2.0 * x + 3.0 * x * x + 1.5 * x * x * x * x;

    // Reward leaving exactly room for the lookahead item (smooth coupling)
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = (pr - nxt).abs() / cap;
        score -= 4.0 * (1.0 - gap * gap).max(0.0);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Late in the stream: consolidate into existing bins, avoid opening new bins
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (2.0 + 6.0 * t * t);

    // Penalize creating dead space far from both 0 and next-item fit, scaled by stream progress
    let dead = x * (1.0 - x) * (1.0 - x);
    score += 5.0 * dead * (0.5 + t);

    // Mild diversity term: prefer bins whose residual deviates from mean
    let dev = (pr as f64 - mean_residual) / cap;
    score -= 0.8 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify post_residual into capacity fractions
    let frac = post_residual as f64 / cap; // fraction of capacity left after placement
    let class = (frac * 8.0).floor() as i64; // 8 harmonic classes [0..1)

    // Penalize dead-space classes: residuals in (0,10) are nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward "perfect" small residuals that pair with common item sizes
    if post_residual >= 10 && post_residual <= 20 {
        score -= 6.0;
    }

    // Modulo arithmetic on post_residual: multiples of 10 are friendly slots
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    // Odd residuals are awkward
    if post_residual % 2 == 1 {
        score += 1.5;
    }

    // Lookahead coupling: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect follow-up fill
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item cannot use this residual: penalize by leftover size
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
        }
        // Harmonic pair check: post_residual + next_item_size sums near capacity multiples
        let s = post_residual + next_item_size;
        if s % 100 == 0 {
            score -= 10.0;
        } else if s > 100 {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing fits are poor
        // (high post_residual waste elsewhere) or stream is early
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_pressure = (mean_residual - post_residual as f64).max(0.0);
        score = 55.0 + 30.0 * progress - waste_pressure * 0.5;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: must open
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size > 50 {
            score -= 5.0; // big items coming, keep flexibility
        }
    }

    // Prefer tighter bins generally (smaller bin_residual => better fill)
    score += (bin_residual as f64 - post_residual as f64) * 0.0; // no-op anchor
    score += (mean_residual - frac * cap) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Residuals that cannot host the lookahead item are moderately penalized.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.25 * (next_item_size - post_residual) as f64;
    }
    // Reward tight fits: post_residual near zero (but not dead) is good.
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else {
        let fit_quality = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fit_quality;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading into
    // new bins; a fresh empty bin gets a penalty proportional to open count.
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * open_bins_count as f64;
    } else {
        // Slight reward for consolidating into already-open bins.
        score -= 2.0 * open_bins_count as f64 / (1.0 + open_bins_count as f64);
    }

    // Prefer bins whose residual is close to the item (low waste relative to
    // the fleet mean residual).
    score += 0.10 * (bin_residual as f64 - mean_residual).max(0.0);

    // Late in the stream, waste tolerance tightens: penalize leftover space more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.20 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for exact or near-exact fills (post_residual near 0).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space super-linearly: small leftovers are very wasteful.
        let pr = post_residual as f64;
        score += pr * pr / 60.0;

        // 2-step lookahead: if the next item fits the post-residual, this is a
        // great pairing — reward it. Otherwise penalize a mismatch.
        if next_item_size > 0 {
            let n = next_item_size as f64;
            if next_item_size <= post_residual {
                // Next item fits: reward tightness of the two-item packing.
                let pair_waste = post_residual - next_item_size;
                score -= 40.0 - pair_waste as f64 * 0.5;
            } else {
                // Next item won't fit here: mild penalty scaled by overshoot.
                score += (n - pr).min(40.0) * 0.3;
            }
        }

        // Compare against mean residual of open bins: prefer bins that end up
        // below the mean residual (tighter than average).
        score += 0.5 * (pr - mean_residual);

        // Last-chance bin: strongly favor using it before opening a new bin.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }

        // Late in the stream, tighten packing (avoid opening bins needlessly).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 3.0;

        // Many open bins: prefer consolidating into existing ones.
        score += open_bins_count as f64 * 0.5;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Make the empty-bin score mediocre so good
    // existing fits beat it, but poor fits (large post_residual) lose to it.
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 0.3 - 10.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the (known) next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving room exactly usable by next item.
            let gap = (post_residual - next_item_size) as f64;
            score -= 0.3 * (-gap / 20.0).exp();
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 8.0 * tightness;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress);

    // Penalize bins far above/below mean residual to keep residual distribution tight.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit = fitting_bins_count <= 1
            || (post_residual as f64) > mean_residual.max(1.0);
        if poor_fit {
            score -= 10.0;
        } else {
            score += 20.0; // discourage opening new bin when existing fits exist
        }
    }

    // Mild late-stream bias toward filling bins completely.
    score -= 3.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Normalize residuals
    let pr = post_residual as f64 / bin_capacity as f64;
    let fit = item_size as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate large residuals; later, penalize dead space more.
    let progress_weight = 1.0 + 2.0 * t * t;
    score += 40.0 * progress_weight * pr * pr;

    // Smooth reward for tight fits (small post_residual), stronger mid-stream
    let tightness = (1.0 - pr).powi(3);
    score -= 15.0 * tightness * (0.5 + t);

    // Penalize bins whose residual deviates from mean residual (fragmentation)
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev * dev / (1.0 + t);

    // Reward using bins when many are open (avoid bin proliferation)
    score -= 1.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - pr);

    // Lookahead: reward leaving residual that can host next item (smooth kernel)
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 12.0 * (-8.0 * gap * gap).exp();
    } else if next_item_size > 0 {
        score += 6.0 * pr;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: mild penalty so it's chosen only when clearly better
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: dead space penalized super-linearly.
    score += 0.35 * (post * post) / cap;

    // Harmonic class of post_residual: residual divisible into coarse classes.
    let class = post_residual / 10;
    score += match class {
        0 => -12.0,          // near-perfect fit
        1 => -4.0,
        2 => 2.0,
        3 => 6.0,
        4 => 10.0,
        _ => 14.0,
    } as f64;

    // Lookahead synergy: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = post_residual - next_item_size;
        if diff == 0 {
            score -= 25.0;
        } else if diff <= 5 {
            score -= 12.0;
        } else {
            score -= 5.0 * (1.0 - diff as f64 / cap);
        }
    } else if next_item_size > post_residual {
        // Next item can't use this bin anyway; penalize leaving medium dead space mildly less.
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: default attractiveness; prefer it only when fits are poor
    // and many bins are open with large mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let poor_fit = post_residual >= 40;
        let frag = mean_residual / cap;
        if poor_fit && open_bins_count > 3 && frag > 0.35 {
            score -= 10.0 * frag;
        } else {
            score += 20.0; // discourage opening bins when a reasonable fit exists
        }
    }

    // Slight late-stream conservatism: consolidate more as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to
    // fit any plausible future item (items >= 1, so treat tiny gaps as waste).
    if post_residual > 0 {
        // Gap below the minimum item size is pure dead space.
        if post_residual < 1 {
            score += 1000.0;
        }
        // Non-linear penalty: small gaps are exponentially worse.
        let gap_frac = post_residual as f64 / bin_capacity as f64;
        if gap_frac < 0.20 {
            score += (0.20 - gap_frac) * 250.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
        if post_residual as f64 <= mean_residual {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a good fit, or when open-bin pressure is high.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // If many bins are open, prefer packing into existing bins.
        score += (open_bins_count as f64).sqrt() * 12.0;
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0;
        }
        // Early in the stream, opening bins is cheaper (future flexibility).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 15.0;
        // If no other bin fits well (large post_residual elsewhere), new bin ok.
        if mean_residual < item_size as f64 * 1.2 {
            score -= 30.0;
        }
    } else {
        // Reward tight fits into open bins relative to the mean residual.
        if (post_residual as f64) < mean_residual {
            score -= (mean_residual - post_residual as f64) * 0.5;
        }
        // Open-bin pressure: mild reward for consolidating when many bins open.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Lookahead: if the next item exactly fills the post-residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    }
    // If next item fits in the post-residual, mild reward.
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // If next item cannot fit in the post-residual, the gap is riskier.
    else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), with non-linear sharpening.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_bonus = 40.0 * (-diff / 20.0).exp();
        score -= match_bonus;
        // If next item fits exactly after this placement, strongly favor.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual too small for next item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Relative to mean residual: prefer using bins with more space than average
    // when the fit is loose, but prefer tight bins when the fit is tight.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing else fits well.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in the stream, opening bins is cheaper.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 30.0 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.max(1) {
            score -= 20.0; // next item pairs well with current in a fresh bin
        }
    }

    // Mild preference for fewer open bins when stream is near its end.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * open_bins_count as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: bonus if the next item fits into the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
            // Extra reward if next item nearly fills post-residual (chained tight fit).
            let chain_tight = 1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64);
            score -= 15.0 * chain_tight;
        } else {
            // Penalize leaving a gap that wastes space relative to next item.
            let gap = post_residual as f64;
            if gap < next_item_size as f64 {
                score += 0.3 * (next_item_size as f64 - gap).min(bin_capacity as f64);
            }
        }
    } else {
        // Last item: strongly prefer bins that fit it tightly.
        score -= 25.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should only win when current fit is poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, softened early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 - 20.0 * progress;
        // If many bins are open, discourage adding more.
        score += 2.0 * (open_bins_count as f64).sqrt();
    }

    // Prefer bins with below-average residual (fill emptier bins less, keep big holes).
    if bin_residual != bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.15 * dev;
    }

    // Mild preference for bins with more residual when item is large.
    if item_size > bin_capacity / 2 {
        score -= 0.05 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Reward tight fits with a smooth non-linear polynomial in fit quality and progress
    let tightness = fit_quality * fit_quality * (1.0 + progress);
    score -= 12.0 * tightness;

    // Perfect fill reward (smooth exponential decay of residual)
    score -= 8.0 * (-post_residual as f64 / 15.0).exp();

    // Lookahead coupling: favor residual that matches next item size
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        let match_score = (gap / bin_capacity as f64).powi(2);
        score -= 6.0 * (1.0 - match_score) * (1.0 - progress);
    }

    // Last chance bin: strong reward if this is the only bin that fits
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    } else if fitting_bins_count > 1 {
        // Slight penalty for spreading across many fitting bins
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Penalize bins whose residual deviates far above the mean residual (fragmentation)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.03 * dev * (1.0 + progress);

    // Penalize opening new bins early in the stream, allow it late
    if bin_residual == bin_capacity {
        let pressure = 1.0 - (fitting_bins_count as f64 / (open_bins_count as f64 + 1.0).max(1.0));
        score += 15.0 * (1.0 - progress) * pressure - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well it aligns with capacity fractions
    let pr = post_residual;
    // Reward post-residuals that are exact fractions of capacity (clean reusable pockets)
    let frac = (pr as f64) / cap;
    if pr > 0 {
        if pr % 50 == 0 { score -= 18.0; }
        else if pr % 25 == 0 { score -= 12.0; }
        else if pr % 10 == 0 { score -= 8.0; }
        else if pr % 5 == 0 { score -= 4.0; }
    } else {
        // perfect fill
        score -= 60.0;
    }

    // Penalize small dead pockets that few item sizes can use (items >= 10 in classic case,
    // but sizes 1..100 unknown, so use next_item_size as probe)
    if pr > 0 && next_item_size > pr {
        // dead space relative to lookahead
        score += (next_item_size - pr) as f64 * 0.6;
        // extra penalty if no other bin can take the next item either
        if fitting_bins_count <= 1 { score += 10.0; }
    }

    // Reward if lookahead fits exactly into post_residual (perfect chaining)
    if next_item_size > 0 && next_item_size == pr {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size < pr {
        // harmonic fit quality of chained residual
        let chain = pr - next_item_size;
        if chain % 10 == 0 { score -= 6.0; }
        score -= 3.0;
    }

    // Integer-division threshold classes on post_residual
    let class = pr / 10; // decade class
    score += (10 - class.min(10)) as f64 * 0.5; // lower post-residual (tighter pack) favored

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bin attractive only when current bin fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline cost of opening a bin
        score += 30.0;
        // but if this bin would waste a lot (post_residual too small to be useful), open new bin
        if pr > 0 && pr < 15 {
            score -= 40.0;
        }
        // early in stream, opening bins is cheaper (spread risk)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
        // many open bins with high mean residual -> prefer reusing
        if open_bins_count > 3 && mean_residual > (item_size as f64) * 1.2 {
            score += 12.0;
        }
    }

    // Slight preference for bins tighter than the mean residual (best-fit flavor)
    if (bin_residual as f64) < mean_residual && !is_new_bin {
        score -= 5.0;
    }

    // Coupling: item size relative to capacity classes (quarter classes)
    let q = item_size / 25;
    score += q as f64 * 1.5; // larger items slightly prefer tighter bins implicitly via residual

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical items are "dead". Penalize heavily when post_residual falls
    // into the unusable gap zone (0 < post_residual < min item size).
    let min_item = 1u32; // sizes can be as small as 1
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 1000.0;
    }

    // Dead-space zone: post_residual too small to be useful for any but
    // the smallest items. Penalize proportionally to how "stranded" the
    // gap is relative to the mean residual of open bins.
    let dead_threshold = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fits (post_residual close to zero but nonzero).
    if post_residual > 0 && post_residual <= 5 {
        score -= 25.0;
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward using bins that are already fairly full (small bin_residual),
    // i.e., consolidate into nearly-full bins rather than spreading.
    let fill_fraction = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_fraction * 15.0;

    // Open-bins pressure: when many bins are open, discourage opening new
    // ones; favor packing into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.6;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when the item leaves a
    // large, reusable residual or no existing bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by open-bin pressure.
        score += 35.0 + pressure * 0.8;
        // But a new bin is good if it would be the last-chance situation
        // anyway (no open bin fits): fitting_bins_count reflects only this
        // candidate then.
        if fitting_bins_count <= 1 {
            score -= 80.0;
        }
        // Lookahead: if the next item is large, a fresh bin is valuable.
        if next_item_size > 0 {
            let next_frac = next_item_size as f64 / bin_capacity as f64;
            score -= next_frac * 20.0;
        }
    } else {
        // Existing-bin lookahead: if next item fits in the post residual,
        // reward this placement (keeps a chain of fits going).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
        // If placing here strands a gap that the next item cannot use,
        // penalize mildly.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is close to the
    // mean (avoid creating extreme outliers in residual distribution).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual relative to item size.
    if item_size > 0 {
        score -= 0.5 * (item_size as f64 / (bin_residual as f64)) * (item_size as f64);
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain placement
        } else if next_item_size < post_residual {
            // partial fit: reward proportionally, penalize leftover dead space
            let waste = (post_residual - next_item_size) as f64;
            score -= 25.0 * (next_item_size as f64 / post_residual as f64);
            score += 0.3 * waste;
        }
    }

    // Compare against mean residual across open bins: prefer using bins with large residual
    // (consolidate space) rather than leaving many half-full bins.
    score -= 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate penalty: only open a new bin when all open bins leave bad fits
    // (post_residual too small for the next item, or item barely fits nowhere well).
    if bin_residual == bin_capacity {
        // Penalize new bins more when there are already many open bins.
        score += 30.0 + 2.0 * (open_bins_count as f64);
        // But if no open bin fits well (post_residual would be tiny or zero elsewhere),
        // the base post_residual = 100 - item_size keeps new bin attractive for large items.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin can host a chain of similar items
        }
    }

    // Dead-space penalty: residuals below typical small-item size are wasted.
    if post_residual < 10 {
        score += 20.0; // perfectly full is fine actually — zero waste
        score -= 20.0; // cancel: post_residual == 0 means perfect fill
    } else if post_residual < 20 {
        score += 8.0; // small dead space, hard to reuse
    }

    // Early in stream, be slightly conservative about fragmenting bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (best-fit core)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for future items (1..100 range)
    if post_residual > 0 {
        let usable = if post_residual >= 50 { 1.0 } else { (post_residual as f64) / 50.0 };
        score += (1.0 - usable) * 8.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for wasting potential
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Global state: when many bins are open, prefer filling existing bins
    let crowding = (open_bins_count as f64).ln() / 5.0;
    score += crowding * (post_residual as f64 / bin_capacity as f64) * 5.0;

    // Deviation from mean residual: prefer bins below mean residual (tighter bins)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 6.0 * dev;

    // Time horizon: late in stream, be greedy and pack tight; early, keep flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * tightness;
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin should only win when fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 6.0 * progress;
        if fitting_bins_count == 0 {
            score -= 25.0; // no open bin fits, must open new bin
        } else if post_residual > 0 && post_residual < 10 {
            score -= 12.0; // otherwise poor-fit item into fresh bin keeps it clean
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear emphasis
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth stream-progress coupling: tighten packing as stream advances
    let coupling = 1.0 + 1.5 * progress * progress;
    score *= coupling;

    // Reward bins whose post_residual can host the next item (lookahead)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            score -= 12.0 * (1.0 - slack / cap) * (0.5 + progress);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Penalize opening new bins when many bins are open and mean residual is high
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (30.0 + 20.0 * mean_residual / cap * progress * open_bins_count as f64);

    // Mild pressure against leaving large dead space relative to mean residual
    score += 8.0 * (norm_pr - mean_residual / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands in
    // "useful" residue classes (multiples of common small item sizes) are
    // more likely to be filled later, so reward them.
    let pr = post_residual;
    if pr > 0 {
        // Reward post-residuals divisible by common sizes (10, 20, 25, 50)
        if pr % 50 == 0 {
            score -= 6.0;
        } else if pr % 25 == 0 {
            score -= 4.0;
        } else if pr % 10 == 0 {
            score -= 3.0;
        } else if pr % 5 == 0 {
            score -= 1.5;
        } else {
            // Odd residue: dead-space risk, penalize by fraction wasted
            score += 2.0 + (pr % 5) as f64;
        }
        // Very small leftovers are nearly dead space
        if pr < 10 {
            score += 8.0 - pr as f64 * 0.5;
        }
    } else {
        // Perfect fit: strongly favored
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 4.0 - slack * 0.05;
            if (pr % next_item_size.max(1)) == 0 {
                score -= 3.0;
            }
        } else {
            // Next item cannot use this leftover at all
            score += 2.0;
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 7.0;
    }

    // Prefer tight fits overall (small relative waste)
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * waste_ratio * 10.0;

    // Early in the stream, be pickier (more future items to serve)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate: only attractive when open bins are congested /
    // mean residual is low relative to the item.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64;
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 0.0 {
            // existing bins mostly too full -> new bin reasonable
            score -= 3.0 + congestion * 0.2;
        } else {
            // existing bins have room; discourage new bin
            score += 5.0 + mean_gap * 0.1;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are worthless. Penalize them super-linearly.
    let min_item = 1u32.max(item_size.min(next_item_size.max(1) )).min(10);
    let gap_dead = (post_residual as f64) / 100.0;
    if post_residual > 0 && post_residual < 10 {
        // unusable sliver: strong penalty
        score += (10.0 - post_residual as f64) * 12.0;
    } else if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        // gap cannot host the lookahead item: moderate penalty scaled by tightness
        score += (next_item_size - post_residual) as f64 * 0.8;
    } else if post_residual > 0 {
        // usable gap: mild reward for leaving flexible space
        score -= gap_dead * 0.5;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins; opening new bins becomes costlier.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 50.0);
    score += pressure * 2.0;

    // Last-chance bin: if this is the only bin that fits, avoid pushing us
    // into opening a bin unless the fit is genuinely bad.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin is attractive when current
    // bins would leave bad dead space or when open-bin pressure is low.
    if bin_residual == bin_capacity {
        let best_existing = if post_residual > 0 && post_residual < 10 { true } else { false };
        let _ = best_existing;
        // base cost of a fresh bin
        score = 45.0 + pressure * 1.5;
        // if lookahead item is large, a fresh bin with full flexibility is valuable
        if next_item_size > 50 {
            score -= 10.0;
        }
        // late in the stream, prefer consolidation over new bins
        score += (step_index as f64 / total_items.max(1) as f64) * 20.0;
    }

    // Slight nudge toward bins with larger residuals when mean residual is low
    // (keeps a spread of bin states for future items).
    if (bin_residual as f64) > mean_residual {
        score -= 1.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is highly desirable.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match for the next item -> strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score += 0.8 * diff;
        }
        // If next item could also fit here after this placement, mild reward.
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize dead space relative to mean residual across open bins.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Prefer fuller bins (small residuals) when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base penalty so existing bins are usually preferred...
        score += 25.0;
        // ...unless this is a large item leaving a very tight residual nowhere,
        // or the stream is early and building fresh bins is cheap.
        if post_residual > 0 && post_residual < 10 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual == 0 {
            score -= 50.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Discard placements that leave awkward small residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets a discount.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space that can't hold typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0; // only small items can use it
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // If next item would NOT fit here but would fit the current residual, penalize wasting space.
    if next_item_size > post_residual && next_item_size <= bin_residual && next_item_size != item_size {
        score += 8.0;
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    let pressure = mean_residual / bin_capacity as f64;
    if open_bins_count > 2 {
        score -= 10.0 * pressure * ((open_bins_count as f64).ln() + 1.0);
    }

    // Time horizon: early in stream, be more willing to open new bins (explore);
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses / few open bins.
        score += 20.0 + 45.0 * progress - 8.0 * pressure;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    } else {
        // Existing bin: reward more late in the stream.
        score -= 15.0 * progress;
    }

    // Mild penalty when this bin is much emptier than average (keep bins balanced-ish,
    // concentrate waste into few bins).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 5.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear penalty on dead space: residual that is too small to fit
    // typical future items is wasted; cubic coupling with stream progress.
    let norm_pr = pr / cap;
    let dead = (1.0 - norm_pr).powi(3) * (1.0 - norm_pr).powi(3);
    score += 20.0 * dead * (0.5 + progress);

    // Reward tight fits: small post_residual relative to capacity.
    score -= 15.0 * (-(norm_pr * norm_pr) * 8.0).exp();

    // Lookahead coupling: if next item fits exactly in the post-residual,
    // strongly favor this bin (perfect chain); penalize near-miss gaps.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 12.0 * (-(gap / cap).powi(2) * 10.0).exp();
        if nxt > pr {
            score += 4.0 * ((nxt - pr) / cap); // next item won't fit here
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: smooth sigmoid penalty growing with open bins count
    // and stream progress, so late in the stream we prefer filling existing bins.
    let is_new = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let open_norm = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).tanh();
    score += is_new * (25.0 + 30.0 * open_norm * (0.3 + 0.7 * progress));

    // Mild preference for bins with residuals below the mean (consolidate small ones).
    score += 3.0 * ((bin_residual as f64 - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (best-fit core)
    score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify post_residual into dead-space classes
    // Residuals < 10 (min item size) are dead space; penalize them strongly.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Classify post_residual by harmonic bands using integer division on 100-capacity
    let band = post_residual / 20; // 0..5
    score += band as f64 * 5.0;

    // Reward keeping residual in "usable" classes: multiples of common sizes
    if post_residual % 10 == 0 {
        score -= 8.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: penalize opening a new bin when open bins exist
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 25.0;
        }
        // Opening a new bin is more attractive early when many items remain
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // Avoid new bin if next item could fit current residual pattern poorly
        if next_item_size > 0 && next_item_size <= post_residual.min(bin_residual) {
            score += 10.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 120.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }

    // Compare against mean residual: bins with residual far below mean are scarce space,
    // using them is good (their residual is precious).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Prefer filling bins that are already quite full (small residual)
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 10.0;

    // Late in stream, consolidate: fewer bins preferred
    if step_index as f64 / total_items.max(1) as f64 > 0.8 {
        score += open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    // Treat post_residual in (0, 10) as nearly worthless — heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward placements that leave room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Leaves a gap just below the next item: penalize proportionally.
        score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing ones,
    // discourage opening new bins unless fit is poor.
    score += 1.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when this bin's fit is terrible.
    if bin_residual == bin_capacity {
        // Baseline new-bin score: slightly worse than a decent fit,
        // better than a very poor fit (large post_residual).
        score = 55.0 + 1.0 * open_bins_count as f64;
        // If lookahead fits nicely in a fresh bin and current fit is bad, favor new bin.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && (post_residual as f64) > 45.0 {
            score -= 10.0;
        }
    }

    // Mild preference for tighter fits overall (relative fill).
    score -= 0.1 * (item_size as f64 / bin_residual.max(1) as f64) * 100.0;

    // Progress coupling: late in the stream, prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect / near-perfect fills
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // 2-step lookahead: prefer bins whose leftover matches the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // chain: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // dead space the next item cannot use
            let waste = (next_item_size - post_residual) as f64;
            score += 10.0 * (waste / 100.0);
        }
    }

    // Penalize leaving residuals far from the mean (fragmentation)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Late in the stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Make brand-new bins slightly unattractive unless residuals are all large
    if bin_residual == bin_capacity {
        score += 8.0 + 0.1 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty for small post-residual
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 18.0 + item_size as f64 * 0.1;
    }

    // Lookahead: penalize if next item fits exactly in post_residual (save the space)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let leftover_after_next = post_residual - next_item_size;
            score += leftover_after_next as f64 * 0.25;
            if leftover_after_next == 0 {
                score -= 12.0; // chain of perfect fits is great
            }
        } else if post_residual > 0 {
            // dead space that next item can't use
            score += (post_residual as f64 - (post_residual as f64 % next_item_size as f64)) * 0.05;
        }
    }

    // Global residual pressure: if mean residual is low, prefer reusing bins
    let pressure = 1.0 - (mean_residual / bin_capacity as f64);
    score += pressure * 6.0;

    // Prefer bins with residual close to item size (best-fit sharpening)
    let diff = (bin_residual - item_size) as f64;
    score += diff * 0.15;

    // Early stream: be conservative, keep bins flexible; late stream: pack aggressively
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * (post_residual as f64 / bin_capacity as f64) * 10.0;
    score -= t * 4.0;

    // Many open bins: discourage fragmentation, favor consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // New-bin candidate: only attractive when item is large or open bins are too full
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual < item_size as f64;
        if fitting_bins_count > 0 && !avg_fit {
            score += 30.0; // prefer existing bins generally
        }
        if item_size > bin_capacity / 2 {
            score -= 10.0; // large items may deserve fresh bin
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 5.0; // item + next won't share a bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * t * t);

    // Penalize small-but-not-tight residuals more as stream progresses (dead space)
    let dead = (1.0 - pr_norm).powi(2);
    score += 8.0 * dead * pr_norm * (1.0 + t);

    // Reward tight fits (low post residual) especially late in the stream
    score -= (1.0 - pr_norm).powi(3) * 10.0 * (0.5 + t);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (0.5 + t);
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (next_item_size as f64 / cap) * (1.0 + t);
    }

    // Prefer bins with residuals below mean (consolidate small spaces)
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild penalty when many bins are open (encourage filling existing ones)
    score += 0.2 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: bins whose residual falls into "nice"
    // classes (multiples of common item sizes) are more reusable.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -12.0 // perfect fill
    } else if pr % 10 == 0 {
        -6.0
    } else if pr % 5 == 0 {
        -3.0
    } else {
        0.0
    };
    score += class_bonus;

    // Dead-space penalty: residuals too small for the smallest plausible item
    let dead = if pr > 0 && pr < 10 { 15.0 } else { 0.0 };
    score += dead;

    // Lookahead coupling: reward if next item fits post_residual exactly or well
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 10.0;
        } else if next_item_size <= pr {
            score -= 4.0;
        } else {
            score += 3.0; // next item won't fit here
        }
        // harmonic class match between next item and post residual
        if pr >= next_item_size && (pr % next_item_size.max(1)) == 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: make empty bin attractive only when current
    // fit is poor (large post_residual relative to capacity) or many bins open.
    if bin_residual == bin_capacity {
        let tightness = post / cap; // = 1.0 for empty bin
        let pressure = open_bins_count as f64;
        // Prefer new bin when existing bins are crowded / fit is loose
        score = cap * (0.55 + 0.02 * pressure) - 5.0 * (1.0 - tightness);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    }

    // Mild progression term: late in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * (mean_residual / cap);

    // Penalize bins far from mean residual (fragmentation avoidance)
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Strict dead-space avoidance: residuals that no item (min size 1, but
    // practically small gaps) can ever use are pure waste. Penalize tiny
    // nonzero residuals super-linearly.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 12.0;
    } else if post_residual < 25 {
        score += 15.0 + (25 - post_residual) as f64 * 1.5;
    }

    // Reward residuals that can still host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + next_item_size as f64 * 0.5;
    } else if next_item_size > 0 {
        // Lookahead won't fit here: mild penalty unless gap is tiny anyway.
        score += 8.0;
    }

    // Open-bins pressure: discourage spreading across many bins when few
    // fitting options exist; encourage using last-chance bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0; // last chance: avoid opening a new bin
    }
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate handling: only attractive when the current bin's fit
    // would create a dead gap or the bin is nearly full anyway.
    if bin_residual == bin_capacity {
        // Opening a new bin: base cost, plus pressure term so it is chosen
        // only when all existing fits are bad.
        score = 45.0 + open_bins_count as f64 * 0.5;
        if item_size >= 70 {
            score -= 20.0; // big items start fresh bins happily
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
        // Early in stream, slightly prefer consolidating: make new bins pricier.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    } else {
        // Slight preference for fuller bins (tighter packing).
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Mean-residual coupling: if this bin is far below average fullness,
    // nudge toward using it (balance residual consumption).
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 && bin_res_f > mean_residual {
        score -= (bin_res_f - mean_residual) * 0.15;
    } else if mean_residual > 0.0 {
        score += (mean_residual - bin_res_f) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit (tight packing).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // 2-step lookahead: reward if the NEXT item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 - slack * 2.0;
        } else {
            // Next item cannot use this bin's leftover: penalize leftover waste.
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.8;
        }
    }

    // Relative to mean residual: bins with unusually large residual are good targets
    // (they can absorb the item with less harm).
    let r = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (mean_residual - r) * 0.5;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize new-bin candidate mildly unless residuals are tight or item is huge.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual < item_size as f64 * 1.2;
        if !tight && item_size < 60 {
            score += 150.0 + 100.0 * (1.0 - progress);
        } else {
            score += 30.0;
        }
    }

    // Slight preference for bins with larger residual among similar fits.
    score -= r * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score by how well the item fills the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 18.0 * fill_ratio;

    // Penalize small unusable post-residuals relative to typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item cannot fit here, this bin becomes dead space.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 8.0 + 0.15 * next_item_size as f64;
        } else {
            // Reward bins that can also accommodate the lookahead item.
            score -= 6.0;
            // Extra reward if post-fit is tight for the next item too.
            let next_left = post_residual - next_item_size;
            if next_left < 10 {
                score -= 5.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when decent fits exist.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // Late in the stream, opening new bins is costlier.
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 * progress;
    }

    // Mild preference for bins below mean residual (balances load, keeps
    // large-residual bins free for larger future items).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Prefer filling more crowded configurations slightly less (avoid fragmenting).
    if open_bins_count > 4 {
        score += 0.3 * open_bins_count as f64 * 0.01;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let t = progress;
    let poly = 1.0 + t * (1.0 - t) * 4.0; // hump peaking mid-stream
    score += poly * (pr * pr) / (cap * cap) * 8.0;

    // Penalize large residuals more as stream matures (less time to fill them).
    score += t * t * pr * 0.5;

    // Reward tight fits: subtract when post_residual is small.
    score -= (1.0 - pr / cap) * (1.0 - pr / cap) * 10.0;

    // Lookahead: reward leaving space exactly fitting the next item.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= (1.0 - diff / cap).max(0.0) * 6.0;
        // Penalize leaving space that cannot fit the next item but is small waste.
        if pr < next_item_size as f64 && pr > 0.0 {
            score += 4.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: mildly penalize opening new bins early, more later.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * t;
    }

    // Prefer bins below mean residual (consolidating fuller bins).
    score += (mean_residual - pr) * 0.05;

    // Mild penalty for many open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space bucketed by capacity/8.
    let class = post_residual / (bin_capacity / 8).max(1);
    score += class as f64 * 3.0;

    // Penalize large residuals that no typical item (<=80) can ever fill.
    if post_residual > 80 {
        score += 40.0;
    } else if post_residual > 60 {
        score += 12.0;
    } else if post_residual > 40 {
        score += 4.0;
    }

    // Perfect or near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Coupling with lookahead: reward if next item fits the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Harmonic match: next item exactly divides the leftover class.
        let q = post_residual / next_item_size.max(1);
        if q >= 1 {
            score -= 5.0 * q.min(4) as f64;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: penalize proportionally.
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        score = 130.0 - pressure * 2.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        if fitting_bins_count <= 1 {
            score += 0.0; // keep neutral; last-chance reward above dominates
        } else {
            score += 25.0; // discourage abandoning usable bins
        }
    }

    // Mild progression term: early in the stream, be more frugal with bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // anything useful (below the minimum plausible item size) are dead space.
    // Penalize them quadratically on top of the raw post_residual.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Post-residuals in the awkward 10..20 band are semi-dead: only small
    // items fit. Apply a moderate nonlinear penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward near-perfect fits (post_residual small but nonzero) strongly.
    if post_residual > 0 && post_residual <= 5 {
        score -= 25.0;
    }
    // Exact fit: perfect closure of the bin.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the ONLY bin that can fit the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has a huge raw post_residual
    // (capacity - item), which is naturally high. Boost it further unless the
    // item is large relative to capacity or no open bin fits well.
    if bin_residual == bin_capacity {
        // Opening new bins is costly when the stream is early/long.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 30.0 * (1.0 - progress);
        // If no existing bin fits (fitting_bins_count == 0 excludes the new
        // bin), the new bin is the only option: remove the penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Large items leave less residual in a fresh bin; slightly favor
        // opening a new bin for them when mean residual is bloated.
        if item_size as f64 > 0.7 * bin_capacity as f64 && mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward
    // this placement (creates a perfect slot for the next item).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    // If the next item would NOT fit in post_residual but fits in the
    // pre-residual, this placement "burns" the slot for the next item:
    // penalize mildly.
    if next_item_size > post_residual && next_item_size <= bin_residual && next_item_size > 0 {
        score += 8.0;
    }

    // Prefer bins whose residual is close to what is needed (best-fit flavor):
    // the raw post_residual already encodes this, but add a coupling that
    // scales the penalty with how much of the bin is being consumed.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "nearly full" bin — using it up is good for consolidation.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (low post_residual).
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit is great: subtract proportionally to how snugly next item fits.
            let chain_tightness = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 12.0 * (1.0 - chain_tightness);
        } else {
            // Penalize leaving space too small for the next item (dead space risk).
            score += 6.0;
        }

        // If next item is large, slightly prefer filling bins now to keep big slots free.
        if next_item_size > bin_capacity / 2 && post_residual < next_item_size {
            score -= 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        score += 8.0 * pressure * (0.5 + mean_fill);
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * pressure * progress;
        // Few open bins with big mean residual -> new bin is less costly.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - mean_fill);
    }

    // Mild reward for using bins that are already fairly full (fragmentation control).
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 4.0 * fill_ratio * fill_ratio;

    // Penalize creating residuals that are awkwardly small (unusable dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Global state coupling: many open bins -> tighten selection pressure.
    score += (open_bins_count as f64) * 0.15 * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins below-average residual (fuller bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect fit reward (strong, smooth quadratic decay as post_residual shrinks)
    let pr = post_residual as f64;
    score -= 60.0 * (1.0 - pr / bin_capacity as f64).powi(3);

    // Dead-space penalty: residual left that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 * (next_item_size as f64 - pr) / next_item_size as f64;
    }

    // Reward bins whose post-residual can still host the next item (smooth coupling)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (-slack / 30.0).exp();
    }

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm = pr / bin_capacity as f64;
    score += progress * norm * norm * 40.0 - (1.0 - progress) * norm * 20.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin, especially when good alternatives exist
    if bin_residual == bin_capacity {
        score += 45.0 + 10.0 * (open_bins_count as f64).sqrt();
    }

    // Mild preference for tighter bins relative to mean residual
    score += 0.1 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Integer division thresholds on post_residual (harmonic classes of C/8)
    let class = post_residual / (bin_capacity / 8).max(1);
    score -= (class as f64) * 3.0;

    // Reward near-perfect fits: post_residual in tiny classes
    if post_residual <= bin_capacity / 16 {
        score -= 25.0;
    }
    if post_residual == 0 {
        score -= 60.0;
    }

    // Modulo arithmetic: dead space that is useless for typical item sizes
    // (residual not reachable by common sizes) gets penalized.
    let unreachable = |r: u32| -> f64 {
        // sizes 1..=100 unknown; treat small odd gaps < 10 as dead if below min size class
        if r > 0 && r < 10 { 12.0 } else { 0.0 }
    };
    score += unreachable(post_residual);

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // harmonic class match between next item and post residual
            let nc = next_item_size / (bin_capacity / 8).max(1);
            let pc = post_residual / (bin_capacity / 8).max(1);
            if nc == pc {
                score -= 20.0;
            }
            score -= 10.0;
        } else {
            // next item won't fit here: residual becomes dead space for lookahead
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly
    if bin_residual == bin_capacity {
        score += 40.0;
        // allow new bin early in stream or when few bins fit
        if next_item_size > 0 && next_item_size > item_size && fitting_bins_count <= 1 {
            score -= 45.0;
        }
        // as stream progresses, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mean residual coupling: avoid bins far below the mean residual (waste concentration)
    score += (mean_residual - post_residual as f64).abs() * 0.15;

    // Mild preference for tighter bins overall
    score += frac * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are pure waste.
    // Items can be as small as 1, so a residual below ~10 is nearly unusable dead space.
    if post_residual < 10 {
        score += 60.0; // hard penalty for creating tiny unusable gap
    } else if post_residual < 20 {
        score += 25.0; // risky gap: only very small items fit
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Perfect or near-perfect fills are excellent: reward heavily.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward when the residual left behind exactly matches (or nearly matches) the next item:
    // this bin becomes perfectly reusable by the lookahead item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 50.0;
        } else if gap <= 3 {
            score -= 20.0;
        } else if (next_item_size as i64 - post_residual as i64) > 0 && post_residual < 10 {
            // next item cannot use this bin's leftover; extra dead-space pressure
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: opening a new bin is only attractive when open-bin pressure is high
    // and this item fits poorly everywhere (large post_residual penalty elsewhere).
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin, growing with number of open bins.
        score = 80.0 + 2.0 * open_bins_count as f64;
        // If the item is large, a fresh bin is more attractive (avoids fragmenting open bins).
        if item_size > 60 {
            score -= 25.0;
        }
        // Early in the stream, allow new bins more freely.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 20.0 * (1.0 - progress);
        }
        // If mean residual across open bins is large, plenty of room exists: discourage new bin.
        score += 0.5 * mean_residual;
        // If no bins fit at all, the new bin is the only option: make it cheap.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing space.
    score += 0.3 * open_bins_count as f64;

    // Prefer bins whose residual is close to the item (tight fit) — reward low slack ratio.
    if bin_residual > 0 && bin_residual != bin_capacity {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 10.0 * tightness;
    }

    // Mild reward for placing into bins with below-average residual (fill the fullest bins first).
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: reward post_residual that closely matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match (next item fits exactly) gets a strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward closeness of the match.
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit in the leftover: penalize proportionally to waste.
            score += 15.0 * (gap / bin_capacity as f64);
        }
    } else {
        // Last item: prefer minimal leftover.
        score += 5.0;
    }

    // Penalize large unusable dead space (below minimum item size 1, treat < 10 as dead).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny dead space is nearly worthless
    }

    // Relative-to-mean coupling: bins with residual far below mean are scarcer space;
    // using them is fine, but leaving them near-empty is wasteful.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of consuming fresh capacity.
        score += 55.0;
        // Late in the stream or many bins open: discourage fragmentation less,
        // since consolidation matters more early.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
        // If the item fits tightly in a fresh bin, opening is more reasonable.
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 35.0;
        }
        // If next item is large and would pair well, opening a fresh bin is fine.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size
            && (bin_capacity - item_size) - next_item_size < 10 {
            score -= 45.0;
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.81;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - progress) * 2.0
             + pr_norm * progress * 1.5
             + (pr_norm * pr_norm * pr_norm) * 4.0;
    score += poly * cap;

    // Penalize creating dead space that cannot fit the next item (smooth term)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score += 0.8 * (gap / cap) * (1.0 + gap / cap);
    }

    // Reward tight fits smoothly
    score -= 3.0 * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 2.5;
    }

    // Mild preference to fill bins when many are open
    score += 0.05 * open_bins_count as f64 * pr_norm;

    // Prefer bins below mean residual (balance exploitation)
    score += 0.3 * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quantized into capacity fractions.
    let post = post_residual as f64;
    let frac = post / cap; // 0..1
    // Class index: 8 harmonic buckets (0 = tight fit, 7 = nearly empty bin)
    let class = ((frac * 8.0).floor() as i32).clamp(0, 7);
    // Non-linear penalty per class: small residuals are "dead space" -> penalize,
    // but very large residuals mean the bin was nearly empty (fine).
    let class_penalty = match class {
        0 => -6.0,  // near-perfect fit, reward strongly
        1 => -3.0,
        2 => -1.0,
        3 => 1.5,
        4 => 3.0,
        5 => 4.5,
        6 => 2.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division threshold: residual divisible classes pair well with
    // common item sizes; reward residuals that are multiples of 10 or 20.
    if post_residual % 10 == 0 {
        score -= 1.5;
    }
    if post_residual % 20 == 0 {
        score -= 1.0;
    }

    // Lookahead: reward if next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 8.0;
        } else if next_item_size <= post_residual {
            // how well next item fills the leftover
            let fill = next_item_size as f64 / post.max(1.0);
            score -= 4.0 * fill;
        } else {
            // next item cannot use this residual: penalize large leftovers
            score += 0.02 * post;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0;
    }

    // New-bin candidate handling: only attractive when open bins are poor fits
    // (mean residual much smaller than item) or early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64).sqrt();
        let desperation = (item_size as f64 - mean_residual).max(0.0) / cap;
        score = cap * 0.75 - 6.0 * desperation - 3.0 * (1.0 - progress.min(1.0));
        if fitting_bins_count == 0 {
            score -= 10.0; // no alternative: new bin is required
        }
    } else {
        // Prefer fuller bins: penalize bins with much slack relative to mean.
        score += 0.05 * (mean_residual - post).max(0.0);
    }

    // Mild pressure to close bins when many are open.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers that no item can use are costly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable gap
    } else if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 12.0; // gap unusable by the next item
    } else if post_residual > 0 {
        // Reward (subtract) when the leftover is large enough to remain useful
        score -= 3.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits: fraction of the residual consumed
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are open
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current bins are nearly full on average
        score = 60.0 + mean_residual * 0.4 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // a fresh bin trivially fits the next item
        }
        if mean_residual > item_size as f64 * 1.5 {
            score += 25.0; // discourage new bin when existing space is plentiful
        }
    } else {
        // Mild pressure to consolidate into fewer bins
        score -= open_bins_count as f64 * 0.3;
    }

    // Late-stream tightening: as the stream progresses, prefer tighter packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            // Perfect chain: next item fits exactly into the leftover space.
            let diff = (pr - nxt).abs();
            score -= 60.0 * (1.0 - diff / 50.0).max(0.0);
            // Exact match bonus.
            if diff < 1e-6 {
                score -= 40.0;
            }
        } else {
            // Next item won't fit here; penalize large unusable leftovers.
            score += 0.3 * (nxt - pr).min(50.0);
        }
    }

    // Penalize leaving post_residual that is small but useless (< min item size 1 handled implicitly);
    // small nonzero residuals are dead space unless chainable.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 15.0 * (10.0 - pr) / 10.0;
    }

    // Compare against mean residual across open bins: prefer bins tighter than average.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Early in stream: consolidate into few bins; late: allow more freedom.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * (1.0 - progress);

    // New-bin candidate: make empty bin attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (item_size as f64) * 0.5;

    // Penalize creating dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else {
            // Reward bins that can also host the lookahead item.
            score -= 6.0;
        }
        // Perfect lookahead fill: post_residual exactly fits next item.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this is a poor fit everywhere.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 0.5;
        let early = (step_index as f64) / (total_items.max(1) as f64) < 0.3;
        if open_bins_count > 0 && !crowded && !early {
            score += 30.0 + mean_residual * 0.2;
        } else if open_bins_count == 0 || early {
            score -= 5.0;
        }
        // Opening a bin wastes potential; penalize mildly when many bins open.
        score += open_bins_count as f64 * 0.5;
    } else {
        // Prefer filling existing bins when many are open.
        score -= open_bins_count as f64 * 0.3;
        // Prefer bins below mean residual (fill emptier side less; use fuller bins).
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Time-horizon scaling: tighten packing more aggressively as stream progresses.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    score *= 1.0 + 0.35 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize leftover space, with non-linear (quadratic + cubic) coupling
    // to normalized stream progress: late in the stream, dead space hurts more.
    let mut score = post;
    let norm_post = post / cap;
    let coupling = norm_post * norm_post * (1.0 + 2.0 * progress) + norm_post.powi(3) * (0.5 + progress);
    score += coupling * cap * (0.3 + 0.7 * progress);

    // Tight fit reward: subtract when post_residual is small relative to item size.
    let item = item_size as f64;
    let tightness = 1.0 - (post / item.max(1.0));
    if tightness > 0.0 {
        score -= tightness * tightness * item * 0.5;
    }

    // Lookahead: reward leaving room for the next item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        let cover = 1.0 - gap / cap;
        if post >= nxt {
            score -= cover * cover * nxt * 0.6;
        } else {
            score += gap * 0.4 * (1.0 - progress);
        }
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= item * 1.5;
    }

    // Penalize bins far from mean residual (prefer homogeneity, smooth term).
    let dev = (post - mean_residual) / cap;
    score += dev.abs() * cap * 0.2 * (0.5 + progress);

    // Prefer filling already-open bins over opening new ones, more so early on.
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // New-bin candidate: make empty bin less attractive unless post_residual is large.
    if bin_residual == bin_capacity {
        score += cap * 0.35 * (1.0 - progress) + post * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fits. Reward exact fit strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover space: classify post_residual into
    // residue classes modulo 10 (item granularity). Leftovers that are
    // "usable" (>= 10, the smallest item) are less penalized than dead space.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead space penalty: leftover too small for any item (post_residual in 1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic class bonus: leftover that is an exact multiple of 10
    // is maximally reusable by future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Class of leftover relative to next item: if next item fits exactly
    // or with small waste, favor this bin (lookahead k=2 coupling).
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_waste = post_residual - next_item_size;
        if next_waste == 0 {
            score -= 120.0;
        } else {
            // harmonic tier on next_waste
            let tier = match next_waste {
                0..=5 => 3.0,
                6..=15 => 2.0,
                16..=30 => 1.0,
                _ => 0.0,
            };
            score -= tier * 25.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // This bin becomes dead after placement if next item can't use it:
        // penalize proportionally to how "orphaned" the leftover is.
        score += 20.0 * (1.0 - post / 40.0);
    }

    // Integer-division threshold on fill ratio: prefer bins that become
    // at least half-full after placement.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    if fill >= 0.75 {
        score -= 30.0;
    } else if fill >= 0.5 {
        score -= 10.0;
    } else if fill < 0.25 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when current bins are mostly full
        // (high mean fill) or many bins are already near capacity; otherwise
        // discourage spreading items thin.
        let mean_fill = 1.0 - (mean_residual / cap);
        // Penalize new bin when open bins are underutilized.
        score += 55.0 - 60.0 * mean_fill;
        // Late in the stream, consolidation matters more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If next item is large, having a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 25.0;
        }
        // If only one bin fits and it's not this one... (this IS the new bin,
        // so fitting_bins_count==1 means an open bin fits too): mild penalty
        // already covered above by mean_fill logic.
    }

    // Mild preference for fuller bins among equals (best-fit reinforcement).
    score -= 0.05 * (cap - post);

    // Small tie-break noise-free deterministic coupling with step parity
    // to diversify class exploration without randomness.
    if (step_index + post_residual as usize) % 3 == 0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: small gaps that likely cannot host a future item
    // are heavily penalized (non-linearly), especially when the gap is smaller
    // than the lookahead item (guaranteed dead space for the next step).
    let gap = post_residual as f64;
    if gap > 0.0 {
        if gap < 10.0 {
            score += (10.0 - gap) * 6.0; // tiny slivers are wasted capacity
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 3.0; // can't host next item
        }
    }

    // Reward tight fits (near-zero residual) with a strong subtraction.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 30.0;

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing ones (penalize the new-bin candidate / discourage spreading).
    score += (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64) * 5.0;

    // Mild lookahead synergy: if the next item exactly fills the post-residual,
    // strongly favor this bin (perfect two-item packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // New-bin candidate (empty bin) should only win when open bins have poor fits:
    // penalize it progressively as open bins accumulate.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + (open_bins_count as f64) * 2.0;
    }

    // Early stream: slightly prefer filling fresh bins fully; late stream:
    // squeeze into whatever exists.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), scaled relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Strong reward for perfect fit.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Exact 2-step match is ideal.
            if slack == 0.0 {
                score -= 120.0;
            } else {
                score -= 60.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Placing here leaves residual too small for next item -> dead space penalty.
            score += 40.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Coupling with mean residual: prefer bins tighter than the mean (fill crowded space),
    // penalize dumping into bins that are already loose.
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }
    // Many fitting bins: mild penalty to encourage diversity of tight choices.
    if fitting_bins_count > 3 {
        score += 5.0;
    }

    // New-bin candidate: opening a new bin is only attractive when item is large
    // relative to typical residual capacity (poor fits everywhere).
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64 / bin_capacity as f64)
            * (mean_residual / bin_capacity as f64);
        // Late in the stream, discourage bin proliferation more strongly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let base = 150.0 - 60.0 * pressure - 30.0 * progress;
        score += base.max(10.0);
    }

    // Slight preference for compact bins as stream grows long.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post-residual quadratically.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Dead-space penalty: residual that likely no future item (>=1) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty for leaving awkward space.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.6 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins with residual close to mean residual (balance load).
    let bin_res = bin_residual as f64;
    score += 0.15 * (bin_res - mean_residual).abs();

    // Time horizon: early in stream, be more exploratory (favor new bins less);
    // late in stream, tighten packing.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * t * (1.0 - pr / bin_capacity as f64);

    // New-bin candidate: only attractive when no good fits exist.
    if bin_residual == bin_capacity && item_size > 0 {
        // Base handicap so existing bins win unless they're poor.
        score += 30.0;
        // If current item is large relative to capacity, fresh bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 20.0;
        }
        // If open bins are fragmented (high mean residual spread), new bin ok.
        if mean_residual < 0.25 * bin_capacity as f64 && open_bins_count > 2 {
            score -= 10.0;
        }
        // Late in stream, avoid opening new bins.
        score += 15.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Reward tight fits: quadratic decay of post_residual, stronger early in stream
    let tightness = 1.0 - (pr / cap).powi(2);
    score -= 18.0 * tightness * (1.0 + 0.5 * (1.0 - progress));

    // Penalize large dead space non-linearly, amplified late in the stream
    score += 6.0 * (pr / cap).powi(3) * (1.0 + 2.0 * progress);

    // Smooth interaction: post_residual * progress coupling
    score += 4.0 * (pr / cap) * progress * (pr / cap);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly unless post_residual of existing bins is hopeless
    if bin_residual == bin_capacity {
        score += 10.0 - 8.0 * (mean_residual / cap).powi(2);
    } else {
        // Favor bins whose residual is close to mean (keep residuals uniform)
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 5.0 * dev * dev;
    }

    // Lookahead: reward leaving space for the next item (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 8.0 * (-(gap / cap).powi(2)).exp();
    }

    // Slight pressure to consolidate into fewer bins
    score += 0.5 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "useful" classes (multiples of 10, or large enough) should be favored.
    let post_class = (post_residual / 10) % 10; // 0..9 harmonic digit
    match post_class {
        0 => score -= 12.0,             // perfect / decade fit
        1 | 2 => score += 8.0,          // tiny dead space, hard to reuse
        3 | 4 => score -= 3.0,          // medium, reusable
        5 | 6 => score -= 6.0,          // half-class, very reusable
        _ => score -= 1.0,              // large residual, flexible
    }

    // Lookahead coupling: reward if next item fits the post residual exactly
    // or into a harmonic class of it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;              // chain perfect fit
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 7.0;           // next placement keeps decade alignment
            }
            score -= slack as f64 * 0.05;
        } else {
            // next item cannot use this bin's remainder: penalize small leftovers
            if post_residual < 20 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no good fitting exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_open = if fitting_bins_count == 0 { 0.0 } else { 25.0 };
        score += bad_open - 5.0 * mean_residual / bin_capacity as f64 - 3.0 * progress;
    }

    // Prefer filling bins below the mean residual (tighter bins first).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Slight preference for many-bin states to keep bins consolidated.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest plausible item are wasted.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving a gap that can still fit the next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0; // next item won't fit here; this bin becomes dead-ish for lookahead
        }
    }

    // Tight fit reward: item fills a large fraction of the bin's residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Last-chance bin: strongly prefer using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += 0.8 * open_bins_count as f64;

    // New-bin candidate handling: opening a new bin is only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Empty bin: neutral residual baseline; penalize when open bins already fit the item well.
        if fitting_bins_count > 0 {
            score += 55.0 + 3.0 * fitting_bins_count as f64;
        } else {
            score -= 20.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer bins with residuals close to the mean (keeps bin population balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slight preference for fuller bins overall.
    score += 0.1 * (bin_capacity - bin_residual) as f64 * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: prefer tight fits (small post_residual already does this).

    // 2-step lookahead: reward when the next item exactly fills the post_residual.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - next_f).abs();
        // Perfect chaining bonus: next item exactly consumes leftover space.
        if gap < 0.5 {
            score -= 25.0;
        } else {
            // Penalize proportional to mismatch, scaled by how much of the
            // residual the next item would use.
            let use_ratio = (next_f / post.max(1.0)).min(2.0);
            score += gap * (0.5 + 0.5 * (1.0 - use_ratio.min(1.0)));
        }
        // If next item cannot fit in post_residual at all, mild penalty for
        // creating dead space that blocks the lookahead item.
        if next_f > post {
            score += 3.0 * (next_f - post).min(30.0) / 10.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current bins are
    // nearly full on average or the fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin starts with full residual; make it unattractive unless
        // open bins are crowded or this is a large item with poor fits.
        let crowded = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        let fit_quality = item_size as f64 / bin_capacity as f64;
        let openness = crowded - 0.55 * fit_quality;
        // Default penalty so we reuse open bins; reward when bins are full-ish.
        score += 18.0 - 30.0 * openness.max(-1.0).min(1.0);
    } else {
        // Reward bins whose residual is below the mean (consolidating waste).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
        }
        // Penalize bins whose residual is far above the mean but barely fits
        // the item (wasteful large-capacity use for a small item).
        let waste = (bin_residual - item_size) as f64;
        if waste > 20.0 {
            score += 0.15 * (waste - 20.0);
        }
    }

    // Slight preference for filling bins as the stream progresses
    // (encourage closing out bins late in the stream).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 2.0 * progress * (1.0 - (bin_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized waste penalty (quadratic in dead space).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Perfect fill is extremely desirable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 0.5 * item_size as f64;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0;
        } else if next_item_size <= post_residual {
            // mild setup bonus proportional to how well next item fits
            let setup = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 60.0 * setup;
        } else {
            // next item cannot use the leftover: penalize large dead space
            let dead = post_residual as f64 / next_item_size as f64;
            score += 20.0 * dead.min(3.0);
        }
    }

    // Compare against mean residual across open bins: placing into a bin
    // whose residual is already small concentrates waste (good for packing).
    let res_frac = bin_residual as f64 / bin_capacity as f64;
    let mean_frac = mean_residual / bin_capacity as f64;
    score -= 25.0 * (mean_frac - res_frac);

    // Time horizon: late in the stream, prefer consolidating into existing
    // bins (avoid spreading); early, allow more exploration.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * res_frac;

    // Many open bins: encourage filling existing ones rather than opening more.
    if open_bins_count > 4 {
        score -= 3.0 * (open_bins_count as f64).ln() * res_frac;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // More attractive early in the stream or when few bins fit the item.
        score -= 30.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // If the current item is large, a fresh bin wastes little capacity.
        score -= 0.4 * item_size as f64;
        // If next item is large too, a fresh bin gives flexibility.
        if next_item_size >= 50 {
            score -= 25.0;
        }
        // Discourage new bins when many open bins already have room.
        if fitting_bins_count > 2 {
            score += 40.0;
        }
    }

    // Slight preference for bins with residuals just above the item (tightness).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 10.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, mildly discounted early (spread items), penalized late
    let mut score = pr * (1.0 - 0.35 * (1.0 - progress));

    // Non-linear polynomial coupling of residual with progress
    let t = progress;
    let poly = 1.0 + 1.2 * t * t + 0.8 * t * t * t;
    score += 4.0 * norm_pr * norm_pr * poly;

    // Reward near-perfect fits (small post residual), stronger as stream progresses
    let fit_bonus = (1.0 - norm_pr).powf(3.0);
    score -= 6.0 * fit_bonus * (0.5 + t);

    // Penalize post residual that cannot fit the lookahead item (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (0.6 + 0.8 * t);
        } else {
            // reward bins that can still take the next item
            score -= 1.5 * (1.0 - ((pr - nxt) / cap)).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Penalize bins with residual far from mean residual (fragmentation avoidance)
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev * (0.5 + t);

    // New-bin candidate: prefer it only when it enables a tight future pairing
    if bin_residual == bin_capacity {
        score = pr + 10.0;
        if next_item_size > 0 {
            let gap = (cap - item_size as f64 - next_item_size as f64).abs();
            score -= 12.0 * (1.0 - gap / cap);
        }
        score += 3.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: quantize post_residual into capacity-fraction classes.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post_class = post_residual / eighth; // 0..=8 harmonic class
    match post_class {
        0 => score -= 30.0,                       // near-perfect fit
        1 => score -= 18.0,                       // very good fit
        2 => score -= 8.0,                        // decent fit
        3 => score += 4.0,                        // mediocre
        4 => score += 10.0,                       // half-empty bin
        _ => score += 18.0,                       // mostly empty, poor packing
    }

    // Dead-space penalty: leftover smaller than the smallest plausible next item is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits harmonically into the leftover.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Exact / near-exact lookahead fit is very valuable.
            let look_gap = post_residual - next_item_size;
            if look_gap == 0 {
                score -= 22.0;
            } else if look_gap <= eighth {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
            // Harmonic complement: leftover splits into halves/quarters of next item.
            if post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here: leftover becomes dead space for the lookahead.
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        score += 35.0; // base cost of opening a bin
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        } else if fitting_bins_count == 1 {
            score -= 10.0; // weak alternative
        }
        // Early in the stream, keeping bins tight is less critical; late, avoid sprawl.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 10.0 - progress * 5.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Prefer bins whose residual is already committed (low residual = well used).
        score += (bin_residual as f64 / bin_capacity as f64) * 5.0;
        // Slight preference toward bins below the mean residual (more packed bins).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Item-size harmonic classes: large items (>= half capacity) should go into emptiest bins.
    if item_size >= bin_capacity / 2 {
        score += (bin_residual as f64) * 0.05;
    } else if item_size <= bin_capacity / 4 {
        // Small items are flexible; slight preference for bins with matching modular leftover.
        if post_residual % quarter == 0 && post_residual > 0 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (<= 10) are pure waste.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small gaps are only useful if the NEXT item fits them (k=2 lookahead).
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0; // gap is usable by lookahead -> reward
        } else {
            score += 30.0; // likely dead space
        }
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Medium/large gaps that accommodate the lookahead item are attractive.
        score -= 12.0;
    }

    // Reward tight fits (low post_residual relative to what was available).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += 0.3 * ((bin_residual as f64 - item_size as f64) - post_residual as f64).abs();

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new bin is cheaper so penalize less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 4.0 * progress);

    // Deviation from mean residual: prefer bins that are already fuller than average
    // (consolidation), penalize picking emptier-than-average bins.
    score += 0.4 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: an empty bin is attractive only if the item
    // is large (leaving little waste) or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        if item_size >= 70 {
            score -= 20.0; // large item -> fresh bin is efficient
        } else if item_size <= 25 {
            score += 35.0; // small item into fresh bin wastes capacity
        } else {
            score += waste * 0.25;
        }
        // Late in the stream, slightly prefer reusing existing bins.
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs();
        if post_residual as i64 >= next_item_size as i64 {
            // next item fits exactly-ish: strong reward scaled by tightness
            score -= 120.0 * (1.0 - lookahead_gap as f64 / 100.0);
        } else {
            // next item won't fit: penalize dead space creation
            score += 30.0 + 0.5 * lookahead_gap as f64;
        }
        // Exact 2-step match bonus
        if post_residual == next_item_size {
            score -= 200.0;
        }
    }

    // Relative-to-mean residual coupling: prefer bins tighter than the mean
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize new-bin candidate slightly when other bins fit (prefer reuse)
    if bin_residual == bin_capacity {
        score += 60.0 + 0.3 * item_size as f64;
        // But open a new bin if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Late-stream consolidation: tighten bin selection as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale post_residual by relative fill quality
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 8.0;

    // Penalize creating small unusable slivers (dead space below typical item sizes)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fill is ideal
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 15.0 + 20.0 * next_fit;
    }
    // If next item would NOT fit in post_residual, mild penalty (wasted potential)
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets baseline penalty so it's only
    // chosen when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in stream, opening bins is cheaper; late in stream, pack tighter
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score -= 20.0 * (1.0 - progress);
        // If many open bins already, discourage opening yet another
        score += (open_bins_count as f64).ln().max(0.0) * 10.0;
    }

    // Global state coupling: prefer bins whose residual is near the mean
    // (keeps residuals homogeneous, easier to combine with future items)
    let dev = ((bin_residual as f64) - mean_residual).abs();
    score += dev * 0.15;

    // Prefer larger residuals slightly when item is small (save tight bins for big items)
    if item_size <= 30 && bin_residual >= 70 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual
    let n = next_item_size as f64;

    // Non-linear coupling: small post-residuals are good, penalize mid-range waste
    score -= 30.0 * (1.0 - x) * (1.0 - x) * (1.0 - t);

    // Penalize residual slightly above typical next item size (dead space)
    if n > 0.0 {
        let d = (x * cap - n) / cap;
        score += 12.0 * d * d.abs() * (1.0 - t);
        // Reward exact-ish fit for the lookahead item
        score -= 20.0 * (-((x * cap - n).powi(2)) / 50.0).exp();
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer fuller bins as stream progresses (smooth polynomial in t)
    score += t * t * 15.0 * x;

    // Prefer bins below mean residual (balance toward fuller bins)
    score += 0.3 * (pr - mean_residual);

    // New-bin candidate: mild penalty so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify by capacity fractions (1/8 steps)
    let class = (post_residual * 8 + bin_capacity - 1) / bin_capacity; // 0..8
    // Dead-space penalty grows for mid-range residual classes (hard to fill later)
    let class_penalty: f64 = match class {
        0 => -30.0,                      // perfect fit
        1 => -8.0,                       // near-perfect
        2 => 4.0,
        3 => 10.0,
        4 => 14.0,                       // ~half empty: moderate
        5 => 10.0,
        6 => 4.0,
        7 => -6.0,                       // large residual still useful
        _ => -20.0,                      // fresh bin
    };
    score += class_penalty;

    // Modulo arithmetic on post_residual: residuals that are multiples of small
    // harmonics (10, 20, 25) pair well with typical item sizes.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 6.0;
    }
    if post_residual > 0 && post_residual % 10 == 5 {
        score += 5.0; // odd half-step residual: awkward
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
            // harmonic pairing: post_residual - next_item divisible by 10
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
        } else {
            score += 6.0; // next item can't use this residual
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: keep it attractive early, discourage later
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 - 25.0 * progress;
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 10.0; // prefer existing bins when any fit
        }
    }

    // Waste-averse coupling: penalize when this residual is far above mean
    let dev = post_residual as f64 - mean_residual;
    if open_bins_count > 1 {
        score += 0.15 * dev;
    }

    // Tightness reward: fraction of bin consumed
    let tightness = item_size as f64 / cap;
    score -= 20.0 * tightness * tightness;

    // Integer-division threshold on post_residual: residuals < 10 are dead space
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps more than proportionally.
    // A residual below the smallest possible item (1) is impossible, but gaps below ~10
    // are effectively dead space given typical item sizes; scale penalty as gap shrinks.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Smooth super-linear penalty on small residuals even above the hard threshold.
    if post_residual > 0 {
        score += 40.0 / (post_residual as f64).powf(0.8);
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward placements that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.15 * next_item_size as f64;
    }
    // Penalize if the post residual would be too small for the next item but nonzero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // bins would create heavy dead space or open-bin pressure is low.
    if bin_residual == bin_capacity {
        // Base cost of a new bin: moderate, so it loses against good fits.
        score = bin_capacity as f64 + 15.0;
        // When few bins are open, opening is cheaper (less pressure to fill existing).
        score -= 10.0 * (1.0 / (1.0 + open_bins_count as f64));
        // If many bins are open, discourage new bins to consolidate.
        if open_bins_count > 8 {
            score += 20.0;
        }
    }

    // Open-bins pressure: with many open bins, favor placements that tighten residuals
    // (i.e., larger items into bins), encouraging consolidation.
    score += 0.05 * open_bins_count as f64 * (item_size as f64 / bin_capacity as f64);

    // Progress-aware nudge: late in the stream, slightly prefer filling existing bins
    // tightly to reduce total count.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff); // strong reward for tight 2-step fit
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain bonus
        }
        // Penalize post_residual that is uselessly small (dead space) but not usable
        if post_residual < 10 && post_residual > 0 {
            score += 12.0;
        }
    }

    // Penalize large wasted residual relative to mean residual of open bins.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (pr - mean_residual) / mean_residual;
        score += 8.0 * rel.max(-1.0);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer the tightest fit via post_residual already.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let tightness = if next_item_size > 0 { (next_item_size as f64 / bin_capacity as f64).min(1.0) } else { 0.5 };
        // A new bin is good when the stream is early or item is large and no tight fit exists.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 100.0 - 20.0 * tightness - 10.0 * (1.0 - progress);
        // If this is a last-chance situation among open bins, make new bin unattractive.
        if fitting_bins_count <= 1 && open_bins_count > 0 {
            score += 50.0;
        }
    }

    // Slight preference to fill fuller bins earlier in the stream.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit: reward small post_residual relative to capacity
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.0 * tight * tight * (item_size as f64);

    // Penalize large dead space that likely becomes unusable
    if post_residual > 0 {
        let dead = post_residual as f64;
        let usable = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
        if dead < usable {
            score += 0.5 * (usable - dead); // dead space can't hold next item
        }
        // dead space thresholds
        if dead < 10.0 {
            score += 15.0; // tiny sliver, nearly useless
        } else if dead > 50.0 {
            score -= 0.3 * (dead - 50.0); // large residual is flexible
        }
    }

    // Lookahead synergy: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 20.0 + 0.5 * slack as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: neutral-ish baseline, better when open bins are crowded
    if bin_residual == bin_capacity {
        score += 10.0;
        // opening a new bin is more attractive early (long horizon to amortize)
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - t);
        // if mean residual is large, prefer reusing existing bins
        score += 0.4 * mean_residual;
        // many open bins: discourage fragmentation
        score += 2.0 * open_bins_count as f64;
    } else {
        // reward reusing existing bins, more so when many bins are open
        score -= 1.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to item (best-fit style) via mean residual contrast
    if (bin_residual as f64) > mean_residual {
        score -= 0.2 * (bin_residual as f64 - mean_residual);
    } else {
        score += 0.2 * (mean_residual - bin_residual as f64);
    }

    // Late in stream: prioritize closing bins tightly (fewer wasted slivers)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if t > 0.8 {
        score += 0.3 * post_residual as f64 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Non-linear polynomial coupling: post_residual shaped by stream progress
    score += norm_pr * norm_pr * (1.0 - progress) * 40.0;
    score -= norm_pr * (1.0 - norm_pr) * progress * 30.0;

    // Reward tight fits via cubic term on normalized fill
    let fill = 1.0 - norm_pr;
    score -= fill * fill * fill * 25.0;

    // Dead-space penalty: residual too small for likely next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.5 + 0.5 * progress) * 2.0;
        } else {
            score -= (pr - nx).min(30.0) * 0.3;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // Mild preference for bins with low mean residual (keeps large residuals free)
    score += (mean_residual - pr).clamp(-50.0, 50.0) * 0.1;

    // Discourage spreading across too many open bins late in stream
    score += open_bins_count as f64 * 0.05 * progress;

    // New-bin candidate handling: slightly penalize opening new bins early,
    // allow it when post_residual would be perfectly reusable
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * progress;
        score -= norm_item * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into classes of 10.
    let class = post_residual / 10;
    score += class as f64 * 4.0;

    // Perfect or near-perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            score -= 25.0;
        } else {
            // Next item won't fit here: penalize leaving large dead space.
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Prefer tighter bins: closeness of item to residual.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 3 {
        score -= 6.0;
    }

    // Penalize bins far below mean residual (wasteful big holes).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Mild early-stream preference for opening fresh bins to build variety.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 18.0 * (1.0 - progress);
    }

    // Harmonic modulo logic: residues divisible by 10 are reusable slots.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any plausible item are wasted.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Penalize leaving gaps that cannot fit the next item (lookahead).
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u32) < next_item_size {
            score += 25.0;
        } else {
            score -= 10.0; // gap remains usable for lookahead item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 0.3 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins tighter than the mean residual (better packing).
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Mild preference for high fill ratio.
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current bin would leave bad gap.
    if bin_residual == bin_capacity {
        let bad_fit = (post_residual as f64) < dead_threshold && post_residual > 0;
        if bad_fit {
            score -= 30.0; // opening fresh bin better than wasting this one
        } else {
            score += 35.0; // discourage opening new bins when fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;

    // --- 2-step lookahead: reward exact match between post_residual and next item ---
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead fit gets a strong bonus.
        if diff == 0.0 {
            score -= 60.0;
        } else {
            // Penalize mismatch scaled by how far off the next item is.
            score += diff * 0.5;
            // If next item cannot fit in post_residual, penalize proportionally.
            if next_item_size > post_residual {
                score += (next_item_size - post_residual) as f64 * 0.8;
            }
        }
    }

    // --- Dead-space penalty: very small post_residual that nothing can use ---
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // tiny unusable sliver
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fill, ideal
    }

    // --- Compare post_residual to mean residual across open bins ---
    // Prefer bins that end up tighter (below mean) -> less wasted space overall.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer it ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // --- New-bin candidate scoring ---
    if is_new_bin {
        // Opening a new bin is only attractive when current open bins are crowded
        // or the item would leave a bad fit. Base cost of a fresh bin:
        let mut new_bin_score = item_size as f64 * 0.9 + 20.0;
        // If many bins are open, discourage opening yet another.
        new_bin_score += open_bins_count as f64 * 3.0;
        // Early in stream, more willing to open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score -= (1.0 - progress) * 15.0;
        // If next item is large and would fit a fresh bin well, slight bonus.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            new_bin_score -= 5.0;
        }
        score = new_bin_score;
    }

    // Slight tie-break: prefer bins with larger original residual (more room used).
    score -= bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: perfect fit strongly favored
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize wasted space non-linearly (quadratic waste)
        let waste = post_residual as f64 / bin_capacity as f64;
        score += waste * waste * 40.0;
    }

    // Lookahead (k=2): reward bins whose post-residual can host next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize creating residual that blocks the next item
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Avoid fragmenting bins with small residuals when other options exist
    if (post_residual as u32) < 10 && post_residual > 0 {
        score -= 12.0; // small dead space is harmless, slight reward
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * mean_residual / (bin_capacity as f64 * (open_bins_count.max(1) as f64));
    score -= pressure * 10.0 * (0.5 + progress);

    // New-bin candidate handling: penalize opening a new bin, more so early on
    // and when existing bins fit well; allow it when all open residuals are poor.
    if bin_residual == bin_capacity {
        let best_possible = if post_residual == bin_capacity { 100.0 } else { 0.0 };
        let _ = best_possible;
        let open_penalty = 20.0 + 30.0 * (1.0 - progress);
        // If no other bin fits (fitting_bins_count==1 means only this new bin), make it attractive
        if fitting_bins_count <= 1 {
            score = (bin_capacity as f64) * 2.0; // effectively only option
        } else {
            score += open_penalty;
            // If mean residual is large, opening new bin wastes existing capacity
            score += mean_residual * 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    let mut score = pr;

    // Non-linear coupling: post_residual interacts with stream progress.
    // Early on, large residuals are fine (bins can absorb future items);
    // later, large residuals are wasted space.
    let pr_norm = pr / cap;
    let waste_coupling = pr_norm * pr_norm * (0.5 + 0.5 * progress);
    score += 30.0 * waste_coupling;

    // Reward tight fits (small post residual) more strongly as stream advances.
    let tightness = 1.0 - pr_norm;
    score -= 20.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual
    // of open bins; penalize proportionally, but relax if this bin is empty
    // and the current fit is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let open = open_bins_count.max(1) as f64;
        let waste = mean_residual / cap;
        score += 15.0 * waste * (1.0 - progress * 0.5);
        score += 5.0 * (open.ln() + 1.0);
    } else {
        // Prefer bins whose residual is close to item size (smooth, non-linear).
        let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
        score += 10.0 * fit_gap * fit_gap;
        // Coupling with mean residual: prefer bins below mean residual
        // (consolidate fuller bins first).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 8.0 * dev;
    }

    // Lookahead: if next item fits exactly in post residual, reward strongly.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 12.0 * (1.0 - gap / cap).max(0.0);
        // Penalize post residuals that neither fit next item nor stay small.
        if next_item_size as f64 > pr && pr > 0.0 {
            score += 6.0 * (next_item_size as f64 - pr) / cap;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // --- Harmonic class of post-residual (dead-space taxonomy) ---
    let class = pr / 10; // coarse harmonic class 0..=10
    match class {
        0 => {
            if pr == 0 {
                score -= 12.0; // perfect closure: no dead space
            } else {
                score += 18.0; // tiny unusable sliver (1..9) = worst waste
            }
        }
        1 => score += 6.0,   // 10..19: hard to reuse
        2 => score -= 2.0,   // 20..29: fits mid items
        3 => score -= 1.0,   // 30..39
        4 | 5 => score -= 3.0, // 40..59: very reusable
        _ => {}              // large residual: neutral, base term dominates
    }

    // Modulo arithmetic: residuals commensurate with common item sizes are reusable
    if pr > 0 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0) {
        score -= 4.0;
    }

    // Integer-division threshold: pr/next pairing harmony
    if next_item_size > 0 {
        if next_item_size <= pr {
            // lookahead item fits here: reward, scaled by harmony of the pair
            let harmony = (pr / next_item_size.max(1)) as f64;
            score -= 7.0 + harmony.min(3.0) * 1.5;
        } else {
            score += 5.0; // next item can't use this residual: dead end risk
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + open_bins_count as f64 * 0.6 + progress * 6.0;
        // opening a new bin is justified only if no open bin leaves a harmonic residual
        if next_item_size > 0 && next_item_size > pr {
            score -= 4.0; // fresh bin could serve the next item better
        }
    }

    // Relative waste coupling
    score += (pr as f64 / cap) * 3.0;

    // Mean-residual coupling: prefer bins whose residual tracks the fleet mean
    score += (mean_residual - pr as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the smaller the post_residual, the better (super-linear).
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Strict dead-space avoidance: residuals too small for the next item are waste.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space unless it's a near-perfect fill (post_residual tiny).
            let waste = post_residual as f64;
            let tiny_gap = waste <= 5.0;
            if tiny_gap {
                score -= 20.0; // near-perfect fill, excellent
            } else {
                score += 15.0 + 0.6 * waste;
            }
        } else {
            // Residual still usable by the lookahead item: reward proportional fit.
            let gap_util = (next_item_size as f64) / (post_residual as f64);
            score -= 8.0 * gap_util;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; acceptable only for poor fits elsewhere.
        score = cap * 0.75 + pressure * 3.0;
        // If the next item is huge and no bin will hold it later, opening early is fine.
        if next_item_size >= 70 && open_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Prefer bins whose residual deviates favorably from the mean (consolidation).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins where the item fills the residual exactly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Chain fit: this bin becomes perfectly consumed by the next item.
            score -= 600.0;
        } else if post_residual >= next_item_size {
            // Next item fits here afterwards; the tighter, the better.
            let slack = (post_residual - next_item_size) as f64;
            score -= 300.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit in the leftover; penalize large dead space relative to next item.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Compare post_residual against the mean residual across open bins:
    // leaving this bin below-average residual concentrates space elsewhere (bad fragmentation).
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when no
    // open bin offers a decent fit. Penalize the empty bin so it loses unless
    // all open-bin fits are poor (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        score += 0.9 * bin_capacity as f64; // baseline penalty ~90
        // Slightly cheaper to open new bins late in the stream when many bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * progress;
        if open_bins_count == 0 {
            score -= 1000.0; // must open a bin
        }
    }

    // Mild penalty for very large leftover gaps that few future items (10..80) can use well.
    if post_residual > 80 {
        score += 0.4 * (post_residual - 80) as f64;
    }

    // Small tie-breaker: prefer bins that are already fairly full.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness preference: quadratic penalty on wasted space.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Lookahead: reward bins whose post_residual can host the next item (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * (next_item_size as f64);
        } else {
            // Dead space that the next item cannot use: penalize proportionally.
            score += 0.10 * (post_residual as f64);
        }
        // If this bin is the only one that can fit the NEXT item too, strong reward.
        if post_residual >= next_item_size && next_item_size > item_size {
            score -= 6.0;
        }
    } else {
        // Last item overall: just minimize leftover.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 0.2 * (item_size as f64);
    }

    // Crowded regime: many open bins -> prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score -= 0.05 * crowding * (0.5 + progress);

    // New-bin candidate handling: an empty bin should only win when existing
    // residuals are so large that fits would waste a lot of space.
    if bin_residual == bin_capacity {
        let waste_if_forced = (mean_residual - item_size as f64).max(0.0);
        let scarcity_bonus = if fitting_bins_count <= 1 { 25.0 } else { 0.0 };
        score += 30.0 + 0.4 * waste_if_forced + scarcity_bonus - 20.0 * progress;
        // Early stream: opening bins is cheap and diversifies residuals.
        if progress < 0.15 {
            score -= 10.0;
        }
    }

    // Prefer placing large items into bins with proportionally large residuals.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio;

    // Small nudge toward near-exact closure.
    if post_residual < 10 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: penalize leftover space, weighted by stream progress
    let mut score = pr * (1.0 + 0.8 * progress);

    // Non-linear polynomial coupling: dead space cost grows super-linearly
    let norm_pr = pr / cap;
    score += 30.0 * norm_pr * norm_pr * (1.0 + progress);

    // Cubic interaction term: mid-range residuals penalized smoothly
    score += 10.0 * norm_pr * norm_pr * norm_pr;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward residual that can fit next item
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        score -= 15.0 * fits_next * (1.0 - progress);
        // penalize residual just below next item size (wasted space)
        if fits_next == 0.0 && post_residual > 0 {
            let gap = (next_item_size as f64 - pr).max(0.0);
            score += 5.0 * (1.0 - gap / cap);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Slight preference for bins tighter than average
    score += 0.3 * (mean_residual - pr);

    // New-bin candidate: mild penalty so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: 4 classes of capacity quarters
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..=4
    let class_bonus = match class {
        0 => 30.0, // near-perfect fit, tiny dead space
        1 => 15.0, // residual ~0-25: fits small future items
        2 => 0.0,
        3 => -10.0,
        _ => -20.0,
    };
    score -= class_bonus;

    // Integer-division threshold coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item nests perfectly: strong reward scaled by tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 25.0 - tight * 0.3;
        } else {
            // next item won't fit: penalize proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.4;
        }
    }

    // Modulo arithmetic on post_residual vs item_size harmony
    let harmony = post_residual % (item_size.max(1));
    score -= (harmony as f64) * 0.05;

    // Last-chance bin: avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count >= 1 {
            score += 35.0; // discourage new bin when one exists that fits
        }
    }

    // Prefer filling bins with large residuals early in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_residual as f64 - mean_residual) * 0.15 * (1.0 - progress);

    // Discourage many open bins with spread residuals
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: nonzero gaps below 10 are unusable for the
    // minimum item size, so they are pure waste. Penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64;
    }

    // Reward near-perfect fits (post_residual 0..=2) strongly.
    if post_residual <= 2 {
        score -= 20.0;
    }

    // Lookahead: if the next item cannot fit into the post-residual but
    // could have fit into a larger residual, penalize fragmenting this bin.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_item_size <= bin_residual {
        score += 8.0;
    }
    // Conversely, reward leaving exactly enough room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize so we only open a new bin when no open
    // bin offers a decent fit. Pressure grows with number of open bins.
    if bin_residual == bin_capacity {
        let base = 20.0 + 3.0 * open_bins_count as f64;
        // If nothing else fits, the penalty must be overcome-able:
        let escape = if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        score += base - escape;
        // Opening a new bin is more attractive late in the stream when
        // many bins are already open and mean residual is high.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * progress * mean_residual / bin_capacity as f64;
    }

    // Mild preference for filling bins with larger residual when several
    // bins fit the item (best-fit core already does this via post_residual).
    if fitting_bins_count > 2 {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next_item_size exactly.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let diff = (post_residual as f64 - nr).abs();
        if post_residual as f64 >= nr {
            // Next item can fit here afterwards: reward exact match strongly.
            score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
            if diff == 0.0 {
                score -= 40.0; // perfect 2-item packing
            }
        } else {
            // Post-residual too small for next item: penalize dead space below next size.
            score += 10.0 + 0.5 * diff;
        }
    } else {
        // Last item: just minimize leftover.
        score -= 20.0;
    }

    // Relative-to-mean coupling: bins tighter than average are more precious; prefer
    // placing into bins with residual above mean to preserve tight bins.
    if (bin_residual as f64) > mean_residual {
        score -= 8.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    } else {
        score += 8.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate handling: empty bin gets a base penalty so we prefer open bins,
    // but if the item would leave large unusable space in an open bin, allow opening.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 30.0;
        // Opening a new bin is attractive when next item is large and nothing fits well.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) < 0 {
            score -= 25.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild stream-progression pressure: tighten decisions as stream matures.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic discount as post_residual approaches 0.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Lookahead: reward if the next item also fits in the leftover space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: excellent, discount more for snug chains.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space for the known next item: penalize proportionally.
            let unusable = (next_item_size - post_residual) as f64;
            score += 0.35 * unusable;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: it should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, scaled by how much of it the item consumes.
        score = (bin_capacity - item_size) as f64 + 30.0;
        // Late in the stream, opening new bins is cheaper than leaving dead space.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        // If many bins are open with high mean residual, prefer reusing them.
        score += 0.15 * mean_residual;
    } else {
        // Reuse bonus: slightly favor existing bins, more so when many are open.
        score -= 3.0 + 0.5 * (open_bins_count as f64).ln().max(0.0);
        // Prefer bins whose residual deviates favorably from the mean (tighter than average).
        score += 0.1 * ((post_residual as f64) - mean_residual);
    }

    // Perfect fill is unbeatable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let prog_term = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += prog_term * norm_pr * 20.0;

    // Reward tight fits more strongly as stream advances (quadratic in fill ratio)
    let fill = 1.0 - norm_pr;
    score -= progress * fill * fill * 30.0;

    // Penalize small dead space quadratically (unusable slivers)
    if norm_pr < norm_item {
        score += norm_pr * norm_pr * 50.0;
    }

    // Lookahead: reward residual that can host next item smoothly
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= fits_next * (1.0 + progress) * 8.0;
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer opening new bins early when fit is poor
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress) + 5.0 * norm_item;
    }

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.3 * progress;

    // Smooth sigmoid-shaped adjustment around mean residual
    let dev = (pr - mean_residual) / cap;
    score += dev * (1.0 + (dev * 3.0).tanh()) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod capacity quarters.
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let class_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit, always reward strongly
    } else if pr < quarter {
        -8.0 + (pr as f64) * 0.5 // small dead space, mildly penalized by size
    } else if pr < half {
        // medium residual: check if it forms a harmonic pair with lookahead
        if next_item_size > 0 && next_item_size <= pr {
            -6.0
        } else {
            2.0
        }
    } else if pr < half + quarter {
        4.0
    } else {
        10.0 // large residual wasted on a big item placement
    };
    score += class_bonus;

    // Integer-division threshold: residual in units of quarter-capacity.
    let res_units = pr / quarter;
    score -= match res_units {
        0 => 4.0,
        1 => 2.0,
        2 => 0.0,
        _ => -2.0,
    };

    // Lookahead coupling: reward when next item exactly fills post_residual class.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 20.0; // chain of perfect fits
        } else if slack < quarter {
            score -= 5.0;
        } else {
            score -= 1.0;
        }
    } else if next_item_size > pr {
        score += 3.0; // next item won't fit here; keep residual flexible anyway
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer reusing bins unless fit is terrible.
    if bin_residual == bin_capacity {
        score = 60.0 + post_residual as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        } else if item_size >= half {
            score -= 25.0; // big item: fresh bin often better
        }
    }

    // Stream progression: early on be conservative (keep bins flexible),
    // later accept tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.3;
    score += (1.0 - progress) * (post_residual as f64) * 0.1;

    // Mean residual context: penalize placements far from mean residual harmony.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Many open bins: discourage spreading, reward consolidation into low-residual bins.
    if open_bins_count > 4 {
        score += (post_residual as f64) * 0.05 * ((open_bins_count as f64).ln() + 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    } else {
        // Larger leftovers are less harmful, but still scale mildly.
        score += 0.15 * post_residual as f64;
    }

    // Reward tight fits (item fills most of the residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: discourage spreading when many bins are open.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Lookahead: if next item could exactly use this post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item cannot use the leftover: penalize proportionally to waste.
            score += 0.3 * post_residual as f64;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when nothing fits well or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 40.0 + 30.0 * (1.0 - progress) + 5.0 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score += 60.0; // never prefer new bin if this is the only fitting one
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for leaving residual that cannot fit the next item (2-step lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward: next item fits perfectly here.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack * 0.3;
        } else {
            // Penalize dead space relative to the next item's size.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // favor bins that end up tighter (more filled) than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Penalize opening a new bin when an open bin fits reasonably well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_cost = 100.0 - progress * 20.0;
        // If this is the only fitting bin, opening is unavoidable; soften the cost.
        if fitting_bins_count <= 1 {
            score -= new_bin_cost * 0.5;
        }
        score += new_bin_cost;
    } else if fitting_bins_count == 1 {
        // Last-chance bin: reward using it to avoid a new bin.
        score -= 15.0;
    }

    // Non-linear coupling: small post-residuals are highly valuable (tight fits).
    let pr = post_residual as f64;
    score -= (1.0 - pr / bin_capacity as f64).powi(3) * 10.0;

    // Discard bins whose residual becomes unusable for typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 30.0;

    // Penalize dead space that can never be reused by typical items (<= 80).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 10.0; // next item won't fit here; bin likely closed
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in the stream, opening new bins is cheaper (more future to use them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
        // Many open bins with high mean residual: prefer reusing them instead.
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += mean_residual * 0.2;
        }
    }

    // Slight preference for bins with residual close to item (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.1;

    // Global balance: prefer bins below mean residual (spread load evenly).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post_residual, smoothly warped.
    let norm_pr = pr / cap; // in [0,1)
    let mut score = norm_pr * norm_pr * cap;

    // Smooth non-linear coupling: small residuals become more valuable later in stream.
    let tightness = 1.0 - norm_pr; // larger when fit is tight
    score -= tightness * tightness * (10.0 + 40.0 * progress);

    // Penalize leaving residual that matches neither current nor next item (dead space).
    if next_item_size > 0 && (next_item_size as f64) > pr {
        let gap = next_item_size as f64 - pr;
        score += 5.0 + 15.0 * progress * (gap / cap).sqrt();
    }

    // Reward exact-ish fits for lookahead item.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 12.0 * (1.0 - diff / cap).max(0.0) * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Mild penalty when bin is far below mean residual (fragmenting the pool).
    score += 0.15 * ((mean_residual - pr) / cap).abs() * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate: neutral-to-slightly-high base so it's chosen only when
    // open bins have poor fits; escalate preference for new bins late in stream
    // when residual pool is large and fragmented.
    if bin_residual == bin_capacity && item_size > 0 {
        let fragmentation = (mean_residual / cap).min(1.0);
        score = cap * 0.35
            - 30.0 * progress * fragmentation
            - (fitting_bins_count as f64) * 2.0;
        if next_item_size > 0 && (next_item_size as f64) <= pr - item_size as f64 {
            score -= 10.0; // new bin leaves room for the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "useful" size classes (multiples of common item sizes) are rewarded.
    let classes: [u32; 6] = [10, 20, 25, 30, 40, 50];
    let mut class_bonus = 0.0;
    for c in classes.iter() {
        if post_residual >= *c && post_residual % c == 0 {
            class_bonus += 8.0 + (*c as f64) * 0.15;
        }
    }
    score -= class_bonus;

    // Dead-space penalty: tiny unusable leftovers (< 10) are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward if the next item fits into the resulting residual,
    // scaled by how well it fills it.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 15.0 + 25.0 * fill;
    } else if next_item_size > post_residual {
        // leftover cannot host next item: mild penalty, worse if large gap
        score += (post_residual as f64) * 0.1;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (fresh empty bin): only attractive when current bin
    // would leave a bad fit; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && post_residual < 15;
        let base = 45.0 + 0.3 * (open_bins_count as f64);
        if bad_fit {
            score -= 70.0;
        } else {
            score += base;
        }
    }

    // Prefer tighter bins among many options: scale tightness with stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_capacity - bin_residual) as f64 * (0.2 + 0.3 * progress);

    // Mild preference to keep mean residual low (balance load).
    score += (mean_residual - post_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible future item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 && post_residual > 0 {
        score += 20.0;
    }

    // Reward perfect / near-perfect packing.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Tightness reward: fraction of the residual consumed by the item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // If the next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - next_tight / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here -> this residual becomes dead space for k+1.
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open,
    // but relieve pressure late in the stream (fewer future items to place).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (1.0 - 0.5 * progress);
    score += 0.35 * pressure;

    // Penalize bins whose residual deviates badly from the mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: make it attractive only when no decent fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by open-bin pressure.
        score = 45.0 + 0.5 * open_bins_count as f64 - 20.0 * progress;
        // If the item would leave a tiny dead gap in ANY fitting bin, prefer new bin.
        if post_residual > 0 && post_residual < 10 {
            score -= 30.0;
        }
        // If next item pairs well with a fresh bin, encourage opening.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: zero post residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits exactly-ish in the leftover space: strong reward.
            score -= 120.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 400.0; // chainable perfect fit
            }
        } else {
            // Leftover too small for the next item: penalize dead space.
            score += 60.0 + gap * 0.5;
        }
    }

    // Penalize large post_residual (wasting capacity) with a non-linear term.
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Relative to mean residual: prefer bins tighter than average.
    score += 2.0 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: keep it slightly unattractive unless current
    // bin would leave a large unusable fragment and lookahead won't fit.
    if bin_residual == bin_capacity {
        let fragment = post_residual as f64;
        let lookahead_bad = next_item_size > 0 && post_residual < next_item_size;
        if fragment < 10.0 || (lookahead_bad && fragment < 35.0) {
            score -= 80.0; // open a fresh bin rather than shatter a bin
        } else {
            score += 120.0; // prefer existing bins when fit is decent
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: opening a bin is generally bad unless forced.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Strong default penalty for opening a new bin.
        score = bin_capacity as f64 * 2.0;
        // If no open bin fits, opening is necessary (but still prefer it only then).
        if fitting_bins_count == 0 {
            score -= bin_capacity as f64;
        }
        // Early in the stream, having fresh bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
        // If many open bins have huge mean residual, a new bin is redundant.
        score += (mean_residual / bin_capacity as f64).max(0.0) * 30.0;
        return score;
    }

    // Tight fits are best: reward small post_residual nonlinearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into post_residual (chain packing),
    // penalize if post_residual is a dead zone that nothing (>=10) can use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        }
        if post_residual > 0 && post_residual < 10 {
            score -= 8.0; // unusable sliver but perfectly packed — fine
        }
    } else {
        // Last item: just pack as tightly as possible.
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Discourage wasting space in bins whose residual far exceeds the item
    // when better options exist (soft best-fit pressure).
    if bin_residual > item_size * 2 {
        score += (bin_residual - item_size * 2) as f64 * 0.3;
    }

    // Mild preference to balance load across bins when many are open.
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    // Slight time-varying exploration term (deterministic, grounded in inputs).
    let phase = ((step_index % 17) as f64 / 17.0) * 2.0 - 1.0;
    score += phase * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) matter more,
    // large dead space is penalized more aggressively.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 + progress * 3.0);
    score += poly * cap * 0.5;

    // Smooth reward for near-perfect fits, amplified by progress.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * tightness * cap * (0.3 + 0.7 * progress);

    // Penalize bins whose residual diverges from the mean residual (smoothly).
    let dev = (pr - mean_residual) / cap;
    score += dev.abs() * dev.abs() * cap * 0.4;

    // Last-chance bonus: if this is the only fitting bin, reward using it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= (1.0 - slack) * 10.0 * (0.5 + progress);
        } else {
            score += (nx - pr) / cap * 6.0;
        }
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += (open_bins_count as f64).ln().max(0.0) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 create "dead zones".
    let class = post_residual % 10;
    // Penalize awkward residues (1..9 small remainders are hard to fill).
    if post_residual > 0 {
        if class >= 1 && class <= 4 {
            score += (5 - class) as f64 * 3.0; // tiny unusable slivers
        } else if class >= 6 {
            score -= 4.0; // large-ish remainders stay usable
        }
    }

    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fills: fraction of bin consumed.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // If many bins can fit the item, mildly prefer tighter ones (handled by base),
    // but penalize spreading when open bin count is high and residuals are large.
    if fitting_bins_count > 3 {
        score += 2.0;
    }

    // Lookahead coupling: if next item would fit exactly into post_residual,
    // this placement sets up a chain — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_left = post_residual - next_item_size;
        if next_left == 0 {
            score -= 45.0;
        } else if next_left % 10 == 0 {
            score -= 12.0;
        }
    }
    // If next item cannot fit here anyway, no chain possible; slight penalty
    // if post_residual is barely below next item (wasted potential).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when current bins would waste badly or none fit well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = mean_residual / bin_capacity as f64;
        // Early stream: opening bins is cheap; late stream: consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 25.0 + progress * 40.0 + open_bins_count as f64 * 1.5;
        // If item is large, a fresh bin wastes little: reduce cost.
        score += base - fill * 30.0 - pressure * 10.0;
    }

    // Slight preference for bins below mean residual (use up laggards).
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    score = post_residual as f64 * 1.5;

    // Strict dead-space avoidance: gaps too small for the next item (or the
    // minimum item size) are "dead" — penalize them hard.
    let min_size = 1u32;
    let dead_threshold = if next_item_size > 0 { next_item_size.min(80) } else { min_size };
    if post_residual < dead_threshold {
        score += 25.0 * (dead_threshold - post_residual) as f64;
    }

    // Perfect fit is golden
    if post_residual == 0 {
        score -= 40.0;
    }

    // Small-but-alive residual is fine; large leftover waste is mild penalty
    if post_residual > 0 && post_residual < dead_threshold.max(10) {
        score -= 10.0; // gap still usable for tiny items
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few,
    // filling bins tightly is fine.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += pressure * 0.5;

    // Prefer bins whose residual is near the item (coupling with mean residual)
    score += (mean_residual - bin_residual as f64).abs() * 0.2;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 35.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // creates dead space for the known next item
        score += 15.0;
    }

    // New-bin candidate: only attractive when current bin residual is badly
    // fragmented (very small residual) or no open bin fits well.
    if bin_residual == bin_capacity {
        // neutral baseline with slight penalty so it only wins when open bins score poorly
        score += 20.0 + open_bins_count as f64 * -0.1;
        if fitting_bins_count <= 1 {
            score -= 25.0; // nothing fits elsewhere well -> new bin OK
        }
    }

    // Reward bins that can still hold a generic future item after placement
    if post_residual >= 50 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit reward: perfectly filled bins are ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item fits the post residual exactly or snugly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 40.0 * (1.0 - snug);
        if next_item_size == post_residual {
            score -= 300.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize leaving a dead-space residual that nothing small can use.
        score += 0.5 * post_residual as f64;
    }

    // Compare post residual against mean residual: prefer bins whose remaining space stays
    // close to the fleet average (keeps flexibility), penalize extreme outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin offers a good fit
    // (i.e., current item leaves a large awkward residual in every fitting bin).
    if bin_residual == bin_capacity {
        // Mild penalty so open bins with decent fits win; reduced when few bins are open.
        let base = 60.0 + 10.0 * open_bins_count as f64;
        let good_fit_exists = next_item_size > 0 && post_residual >= next_item_size;
        score = if good_fit_exists { base + 200.0 } else { base };
        // Early in stream, opening bins is cheap and useful for future flexibility.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
    }

    // Penalize large leftover residuals that are hard to fill (dead space), especially late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // tiny residual is nearly a perfect fill
    } else {
        score += progress * 0.2 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the next item: strong reward
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Dead space smaller than next item: penalize proportionally
            score += 6.0 * (post_residual as f64) / (next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins with residual below mean residual (better packing consolidation)
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Time horizon: early in stream, be conservative (favor filling existing bins);
    // late in stream, allow more aggressive new-bin usage if fit is poor
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling: only open new bin when fit is bad and progress is high
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        let poor_fit = fit_ratio < 0.45;
        if poor_fit && progress > 0.5 {
            score -= 20.0; // allow opening new bin for small items late in stream
        } else {
            score += 30.0; // default: penalize opening new bins
        }
    }

    // Discourage spreading across too many bins when many are open
    if open_bins_count > 4 {
        score += 0.5 * (open_bins_count as f64);
    }

    // Small bonus for perfectly filling a bin
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) are rewarded more strongly.
    let progress_weight = 0.5 + 1.5 * t * t;
    score *= 0.5 + 0.5 * progress_weight * (1.0 - norm_pr);

    // Reward high fill ratio with a smooth saturating term.
    score -= 8.0 * (fit_ratio * fit_ratio).tanh() * (1.0 + t);

    // Penalize large post_residual quadratically, scaled by mean residual context.
    score += 0.02 * pr * pr / cap * (1.0 + (mean_residual / cap));

    // Last-chance bin: strong reward if it fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 * (1.0 - (next_item_size as f64 / post_residual as f64));
    } else if next_item_size > post_residual {
        // dead space likely: penalize smoothly
        score += 3.0 * (1.0 + t);
    }

    // New-bin candidate: keep it competitive only when existing bins are poor fits.
    if bin_residual == bin_capacity {
        score += 4.0 + 10.0 * (1.0 - fit_ratio.abs());
        score -= 2.0 * t;
    }

    // Many open bins: slight preference for consolidating into existing bins.
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // classes (multiples of common item sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals that are multiples of small common sizes (exact fits later).
        let harmonic_bonus: f64 = if pr % 10 == 0 {
            12.0
        } else if pr % 20 == 0 {
            15.0
        } else if pr % 5 == 0 {
            6.0
        } else if pr % 25 == 0 {
            8.0
        } else {
            0.0
        };
        score -= harmonic_bonus;

        // Penalize "dead space": residuals too small for the smallest item (1..=100 range,
        // but practically penalize residuals below a small threshold more aggressively).
        if pr < 10 {
            score += 20.0 * (10.0 - pr as f64);
        }
    } else {
        // Perfect fill: strongly favored.
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            // Next item fits: reward proportional to tightness of that fit.
            let tight = 1.0 - (pr - next_item_size) as f64 / cap;
            score -= 15.0 * tight;
        } else {
            // Next item cannot fit here: mild penalty scaled by how badly it misses.
            let miss = (next_item_size - pr) as f64 / cap;
            score += 10.0 * miss;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless post_residual would be tiny dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if pr < 10 {
            score += 15.0; // still avoid creating dead space even in last chance
        }
    }

    // New-bin candidate handling: opening a new bin is penalized more when many
    // bins are open (amortization favors filling existing bins), but slightly
    // favored early in the stream when bins are few.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 + 10.0 * (1.0 - progress) - (open_bins_count as f64).min(10.0);
        // If current item is small relative to capacity, a fresh bin wastes capacity.
        let fill = item_size as f64 / cap;
        score += 20.0 * (1.0 - fill);
    }

    // Tightness of current placement: reward filling a large fraction of the bin.
    let used_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * used_frac;

    // Prefer bins whose residual deviates from the mean residual downward
    // (filling the emptiest-relative bins keeps a portfolio of tight bins).
    score -= 0.05 * (mean_residual - bin_residual as f64);

    // Mild modulo threshold on post_residual / capacity fraction: quantize reward.
    let frac = post_residual as f64 / cap;
    let quant = (frac * 4.0).floor() / 4.0; // quarter-capacity classes
    score -= 4.0 * quant;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never host typical items
    // (below the minimum plausible item size) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 25 {
        // small gaps are risky: scale penalty as gap shrinks
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (post_residual small relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins
    // and encourage filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 15.0 + 2.0 * open_bins_count as f64 + 20.0 * progress;
    } else {
        // Existing-bin bonus grows with open_bins_count to consolidate.
        score -= 1.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot follow: penalize proportional to wasted potential
        score += 8.0;
    }

    // Prefer bins whose residual is already below the mean (consolidating small residuals).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward perfect/near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how snugly
            score -= 50.0 * (1.0 - (post_residual as f64 - nxt) / cap);
        } else {
            // next item won't fit here: penalize leaving large post_residual
            score += 0.5 * (post_residual as f64 - nxt);
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: strong incentive to use it rather than open new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 250.0;
    }

    // Early in stream: slightly discourage spreading across many bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0; // lookahead item can still fit here
        } else if post_residual > 0 {
            // dead space: smaller dead space is less harmful
            score += (post_residual as f64) * 0.35;
            // extra penalty when dead space is just barely too small
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 3.0;
            }
        }
    } else {
        // last item: prefer minimal residual
        score -= 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let avg_fit_penalty = (mean_residual - item_size as f64).max(0.0);
        // open new bin if mean residual is small (existing bins are nearly full)
        score += 8.0 + avg_fit_penalty * 0.5;
        // early in the stream, opening bins is cheaper (more future items to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // many open bins: discourage opening yet another
        score += (open_bins_count as f64) * 0.6;
        // if the new bin perfectly fits a lookahead pair, reward it
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 5.0;
        }
    }

    // Mild preference for bins with residual close to item (best-fit flavor).
    score += ((bin_residual as f64) - (item_size as f64)).abs() * 0.25;

    // Slight penalty for very fragmented bin relative to mean residual.
    if (bin_residual as f64) < mean_residual {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.35 * progress * (1.0 - progress) * 4.0);

    // Non-linear penalty on awkward residual sizes (small but nonzero waste)
    let waste_curve = (pr_norm * (1.0 - pr_norm)).sqrt();
    score += 8.0 * (1.0 - waste_curve) * (1.0 - waste_curve) * cap * 0.1;

    // Reward tight fits
    score -= (item_size as f64 / cap) * (item_size as f64 / cap) * 10.0;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: penalize if next item cannot use the post-residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns > pr {
            score += 0.25 * (ns - pr);
        } else {
            score -= 0.15 * (pr - ns).min(20.0);
        }
    }

    // Mean residual coupling: prefer bins near the mean (balance)
    score += 0.2 * ((pr - mean_residual) / cap).abs() * cap;

    // New-bin candidate: mild penalty so it only wins when open bins are bad
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of small divisors) are preferred.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Fraction of capacity consumed by this placement.
    let fill_frac = (bin_residual - pr) as f64 / cap;
    score -= 40.0 * fill_frac * fill_frac; // reward tight fills superlinearly

    // Modulo-10 harmonic classes: leftover divisible by 5 or 10 is more reusable.
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        } else if pr % 2 == 0 {
            score -= 1.0;
        } else {
            score += 2.0; // odd dead space is least reusable
        }
        // Integer-division thresholds: tiny leftovers are near-wasted.
        if pr <= 3 {
            score += 12.0;
        } else if pr < 10 {
            score += 5.0;
        } else if pr >= 40 {
            score -= 4.0; // large leftover keeps future flexibility
        }
    } else {
        score -= 15.0; // perfect closure
    }

    // Coupling with lookahead item: exact future fit is gold.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 20.0;
        } else if pr > next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 8.0;
        } else if pr < next_item_size {
            score += 4.0; // leftover can't host next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening fresh bins unless stream is early
    // or open bins are crowded (mean residual small relative to item).
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 1.2;
        let early = (step_index as f64) / (total_items.max(1) as f64) < 0.1;
        if !early && !crowded {
            score += 25.0 + 3.0 * open_bins_count as f64;
        } else if crowded {
            score -= 5.0;
        }
    }

    // Mild pressure against bin sprawl.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "unusable" if it's smaller than the smallest plausible item
    // (assume min item ~ 10, but scale with stream progress as larger items may dominate).
    let min_gap = 10.0;
    if (post_residual as f64) < min_gap && post_residual > 0 {
        score += (min_gap - post_residual as f64) * 8.0;
    }
    // Perfect fit: eliminate score entirely.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Dead-space shaping: penalize post_residual that cannot fit the lookahead item
    // when the lookahead item is small enough to matter.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0; // bin remains useful for next item
        } else if post_residual > 0 {
            // gap too small for lookahead: potential dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Open-bin pressure: discourage scattering across many bins when few bins are open,
    // encourage using existing bins when many are open (avoid opening new bins unnecessarily).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 - progress);
    score += pressure * 0.3;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes (bin_capacity - item_size)
    // of potential packing; only attractive when current bins have poor fit
    // (large dead space would be created) or no bins fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // Attractive if mean residual of open bins is small (existing bins nearly full)
        // or item would leave big dead space anywhere else.
        score -= mean_residual * 0.4;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    } else {
        // Prefer bins whose residual is close to item size (best-fit flavor).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: prefer small post_residual.
    score = post_residual as f64 * 1.0;

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // 2-step lookahead: if the NEXT item fits exactly into the post_residual,
    // this placement is excellent (chains two items perfectly).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves more dead space: mild penalty proportional to leftover.
            let after_next = post_residual - next_item_size;
            score += after_next as f64 * 0.5;
            score -= 10.0;
        } else {
            // Next item cannot fit here: penalize proportional to how much dead space remains.
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(60.0) * 0.8;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" —
    // placing here is good if it tightens them further; avoid dumping into loose bins.
    let resid_f = bin_residual as f64;
    let dev = resid_f - mean_residual;
    if dev < 0.0 {
        // Tighter than average bin: reward using it (consolidates waste).
        score += dev * 0.3; // negative dev lowers score
    } else {
        // Looser than average bin: slight penalty for spreading waste.
        score += dev * 0.15;
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin, but less when the item is
    // large (better to start fresh for big items than fragment a tight bin).
    if bin_residual == bin_capacity {
        let mut new_bin_score = 60.0;
        // Large items leave large residuals in fresh bins; encourage fresh bins
        // for large items, discourage for small items.
        new_bin_score -= (item_size as f64 / 100.0) * 70.0;
        // If many bins are open and loose, avoid adding more bins.
        if open_bins_count > 3 && mean_residual > item_size as f64 * 2.0 {
            new_bin_score += 40.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 30.0;
        score += new_bin_score;
    }

    // Mild tie-break: earlier bins slightly preferred to keep bin set compact.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear penalty on wasted space)
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_frac * waste_frac;

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // next item still fits here: mild reward proportional to leftover after it
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving a gap that's too small for it
            let gap_waste = post_residual as f64 / next_item_size as f64;
            score += 8.0 * gap_waste;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = if post_residual > 0 { 1.0 } else { 0.0 };
        let poor_fits = (mean_residual - item_size as f64).abs() / bin_capacity as f64;
        score += 60.0
            - 30.0 * poor_fits
            - 10.0 * progress
            - 5.0 * fit_quality
            + (open_bins_count as f64).sqrt() * 2.0;
    } else {
        // Favor bins with residuals close to the item (best-fit refinement)
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 10.0 * tightness;

        // Prefer bins whose residual is below mean (consolidate emptier space)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Early stream: slight preference to keep few bins; late stream: pack tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fills mildly; late in stream, penalize waste more strongly.
    let progress_waste = pr * pr / cap * (0.5 + 1.5 * progress * progress);
    score += progress_waste;

    // Smooth reward for small post_residual relative to mean residual (compactness).
    let compact = 1.0 - (pr / cap).powi(2);
    score -= 8.0 * compact * (1.0 - progress);

    // Penalize bins whose residual is far from the mean (fragmentation smoothing).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Lookahead: reward post_residual that exactly accommodates the next item (smooth kernel).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 10.0 * (1.0 - gap / cap).max(0.0) * (1.0 - gap / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr / cap);
    }

    // Smooth open-bin pressure: many open bins -> discourage new-bin-like waste.
    score += (open_bins_count as f64).ln().max(0.0) * (pr / cap) * 2.0;

    // New-bin candidate: keep it neutral-to-slightly-high unless residual is perfect.
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // coarse buckets via integer division on capacity fractions.
    let class = post_residual / (bin_capacity / 4).max(1); // 0..=4 classes
    match class {
        0 => score -= 40.0,                 // near-perfect fit (dead space < 25)
        1 => score -= 12.0,                 // decent leftover
        2 => score += 6.0,                  // mediocre leftover
        3 => score += 14.0,                 // poor: large but awkward gap
        _ => score += 4.0,                  // huge leftover, still reusable
    }

    // Lookahead coupling: reward if next item can use the post residual exactly
    // or within a good class; penalize if next item cannot fit at all.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 60.0;              // perfect two-item chain
            } else if slack < bin_capacity / 4 {
                score -= 25.0;              // good chaining
            } else {
                score -= 8.0;
            }
        } else {
            score += 18.0;                  // next item won't fit here -> dead end
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize spreading across many open bins when residuals are plentiful.
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64;
    }

    // Drift correction toward mean residual: prefer bins whose leftover
    // lands near the fleet mean (keeps residuals homogeneous and usable).
    let drift = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * drift;

    // Progress modulation: early in the stream be pickier about large gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > bin_capacity / 2 && progress < 0.5 {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual < 10 {
            // Tiny unusable sliver: heavy penalty, scaled by how useless it is.
            score += (10 - post_residual) as f64 * 6.0;
        } else {
            // Larger gaps may still be usable by future items; mild penalty.
            score += post_residual as f64 * 0.05;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Tight fit reward: fraction of the bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: discourage spreading across many bins unless fit is excellent.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit in the gap: penalize leaving medium dead space.
            if post_residual > 0 && post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.3;
            }
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (concentrate filling into already-partially-used bins).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.2;
    } else {
        score += (residual_f - mean_residual) * 0.1;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin offers a decent fit (e.g. residual too small relative to item).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // But discount it when open bins are fragmented (high mean residual spread
        // implied by many open bins and low mean residual).
        if open_bins_count > 0 && mean_residual < item_size as f64 {
            score -= 15.0;
        }
        // Late in the stream, avoid leaving many near-empty bins behind.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is already favored by base,
    // but give an extra bonus for exact / near-exact closure.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fills this bin's
    // post_residual, strongly favor this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            // Next item fits into the leftover: good, scale by tightness.
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 80.0 * tightness;
        } else {
            // Next item cannot use the leftover space: penalize dead space,
            // worse when the leftover is large.
            let waste = post_residual as f64;
            score += 0.3 * waste;
        }
    } else {
        // Last item: strongly prefer closing bins completely.
        score -= 200.0;
    }

    // Penalize creating residual far below the mean residual of open bins
    // (fragmenting the fleet's usable space).
    score += 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Reward placements that reduce dispersion relative to mean residual.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: mildly penalize opening new bins while few are open,
    // but allow it when the current fit is poor (large post_residual).
    if bin_residual == bin_capacity {
        score += 60.0;
        // Opening new bins is cheaper early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
    }

    // Mild penalty for accumulating too many open bins.
    score += 1.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness).powi(3);

    // Penalize dead space that cannot fit even small future items
    if post_residual < 10 && post_residual > 0 {
        score -= 15.0; // fully packed bin is good
    } else if post_residual > 0 && post_residual < item_size {
        // residual too small for another item of similar size -> wasted space
        score += 8.0 * (1.0 - post_residual as f64 / item_size as f64);
    }

    // Lookahead: bonus if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain
        } else if post_residual >= next_item_size {
            score -= 25.0 * (post_residual as f64 / next_item_size.max(1) as f64).ln().max(0.0);
        } else {
            // next item won't fit here; penalize leaving medium gaps
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: make empty bin attractive only when fits are poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, reduced as stream progresses
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_cost = 70.0 - 20.0 * progress;
        // discourage opening new bins when many bins already open and mean residual is high
        open_cost += open_bins_count as f64 * 1.5;
        if mean_residual > item_size as f64 + 10.0 {
            open_cost += 25.0;
        }
        // if lookahead fits perfectly in a fresh bin, slightly encourage it
        if next_item_size > 0 && next_item_size >= post_residual && item_size + next_item_size <= bin_capacity {
            open_cost -= 10.0;
        }
        score += open_cost;
    }

    // Mild penalty for scattering across too many open bins
    score += 0.3 * open_bins_count as f64;

    // Prefer bins whose residual is far below mean (concentrating fill)
    let diff = bin_residual as f64 - mean_residual;
    score += 0.15 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - (pr / cap);
    let tightness2 = tightness * tightness;

    // Base: penalize large post-residual (wasted space), non-linearly.
    let mut score = pr * (1.0 + 0.8 * tightness2);

    // Smooth progress coupling: late in stream, demand tighter fits.
    let progress_pressure = t * t * (1.0 - t * 0.5);
    score += 40.0 * progress_pressure * pr / cap;

    // Reward near-perfect fits strongly (smooth cubic reward).
    let perfect = 1.0 - (pr / cap);
    score -= 25.0 * perfect * perfect * perfect;

    // Coupling with mean residual: prefer bins whose residual deviates below mean (tighter bin).
    let dev = (mean_residual - pr) / cap;
    score += 8.0 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: bonus if next item fits into post_residual.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 6.0 * (next_item_size as f64 - pr) / cap;
    }

    // Slight preference for bins among many open bins (consolidation).
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: penalize mildly unless current fit is bad.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let bad_fit = pr / cap;
        score += 15.0 - 30.0 * bad_fit * bad_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact "friendly" residuals that pair
    // with common small item sizes (capacity fractions) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let friendly = |r: u32| -> f64 {
        match r {
            0 => 200.0,               // perfect fill
            1..=5 => 60.0,            // near-perfect fill
            10 | 20 | 25 | 30 | 40 | 50 => 35.0, // classic fraction residuals
            _ => 0.0,
        }
    };
    score -= friendly(pr);

    // Penalize dead space by harmonic class: residuals that are awkward
    // (mod 10 != 0 and > 15) are likely unusable.
    if pr > 15 && pr % 10 != 0 {
        score += (pr % 10) as f64 * 1.5;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size <= pr {
            // reward proportional to tightness of the follow-up fit
            let slack = (pr - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this residual: penalize proportionally
            score += ((next_item_size - pr) as f64 / cap) * 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // attractive only when no good fit exists (large post_residual waste
    // elsewhere) or stream is early and we want spread.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of opening a bin; cheaper early, expensive late.
        let open_cost = 55.0 + 40.0 * progress;
        score = open_cost;
        // If next item is small, a fresh bin wastes potential pairing.
        if next_item_size > 0 && next_item_size <= 30 {
            score += 10.0;
        }
        // If many bins are open with fat residuals, discourage a new one.
        if mean_residual > 30.0 {
            score += (mean_residual - 30.0) * 0.8;
        }
    }

    // Mild pressure to prefer tight bins when many fit.
    if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0) * 2.0;
    }

    // Tiny tie-break toward fuller bins via mean residual context.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" zone
    // (too small for the smallest plausible item) are heavily penalized.
    let dead_zone_low: u32 = 1;
    let dead_zone_high: u32 = 12;
    if post_residual >= dead_zone_low && post_residual <= dead_zone_high {
        // Deeper penalty for smaller, more useless gaps
        score += (dead_zone_high - post_residual + 1) as f64 * 8.0;
    }
    // Moderately awkward gaps (13..25) get a milder penalty
    else if post_residual > dead_zone_high && post_residual <= 25 {
        score += 3.0;
    }

    // Reward near-perfect fits (residual almost zero)
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 3 {
        score -= 10.0;
    }

    // Tightness coupling: favor bins whose fill ratio after placement is high
    let fill_after = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_after * 15.0;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than spreading; when few are open, spreading is ok.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is truly terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if post_residual > 25 {
            score += 6.0; // still penalize wasteful placement, but less than a new bin
        }
    }

    // Lookahead: if the next item fits snugly into the post_residual, reward it;
    // if post_residual is awkwardly just below next_item_size, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (post_residual - next_item_size).min(10) as f64 * 1.5;
        } else {
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 4.0; // tantalizingly close but unusable for the next item
            }
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer it only when this bin's placement would create severe dead space
    // or when the current bin is a very poor fit.
    if bin_residual == bin_capacity {
        // Baseline neutral score for a fresh bin; slightly discouraged when
        // the item fits well somewhere else (tight fit reward above already
        // lowered those scores).
        score += 10.0;
        // But if stream is early, opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
        // If mean residual across open bins is large, opening a new bin wastes capacity
        score += (mean_residual / 10.0).min(15.0);
    }

    // Penalize placing into a bin that leaves a gap just below the smallest
    // useful item size relative to the mean residual landscape.
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.15 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits with small slack left over.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + slack);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item won't fit here afterwards: penalize proportionally.
        let gap = (next_item_size - post_residual) as f64;
        score += 10.0 + gap * 0.3;
    }

    // Reward tight fits relative to capacity (small post_residual is good).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize bins far below mean residual (poorly utilized bins) mildly.
    score += (mean_residual - post_residual as f64) * 0.2;

    // Brand-new empty bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 70.0;
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Crowd effect: many open bins -> prefer consolidation into fuller bins
    let crowd = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 0.05 * crowd * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, be pickier about waste; late, pack greedily
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress * (1.0 - tightness);

    // New-bin candidate: penalize so it only wins when no decent fit exists
    if bin_residual == bin_capacity {
        score += 45.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual
    let pr = post_residual as f64 / bin_capacity as f64;

    // Smooth non-linear coupling: quadratic dead-space penalty growing with progress
    score += (pr * pr) * (40.0 + 60.0 * progress);

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (1.0 - pr) * (1.0 - pr) * (20.0 + 30.0 * progress);

    // Penalty for leaving residual that no future item likely fits:
    // interaction of post_residual with next_item_size
    if next_item_size > 0 {
        let nis = next_item_size as f64;
        let gap = pr * bin_capacity as f64 - nis;
        if gap >= 0.0 && gap < 10.0 {
            // awkward small gap that next item barely overshoots -> strong penalty
            score += 15.0 * (1.0 - gap / 10.0) * (0.5 + progress);
        } else if gap < 0.0 {
            // next item doesn't fit; residual is dead space unless small
            score += 5.0 * pr * (0.5 + progress);
        } else {
            // next item fits comfortably: reward
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly so we only open new bins when fits are poor,
    // with smooth dependence on mean residual of open bins
    if bin_residual == bin_capacity {
        score += 10.0 + 0.05 * mean_residual;
    }

    // Mild pressure to consolidate: fewer open bins relative to progress is favored
    score += 0.02 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets
    let post_class = post_residual % 10;
    // Dead-space penalty: small post_residual classes are "unusable" pockets
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny sliver = dead space
    } else {
        // reward post_residuals that are perfect harmonic fits for common items
        let harmonics: [u32; 5] = [10, 20, 25, 50, 100];
        if harmonics.contains(&post_residual) {
            score -= 15.0;
        }
        // fractional capacity coupling
        let frac = post_residual as f64 / bin_capacity as f64;
        if frac < 0.1 {
            score += 12.0;
        } else if frac > 0.5 {
            score -= 6.0;
        }
    }

    // Integer-division threshold: can next item fit exactly?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect lookahead fit
        } else if next_item_size < post_residual {
            score -= 8.0;
        } else {
            score += 10.0; // next item won't fit here
        }
        // modulo harmony: next_item and item share harmonic class
        if next_item_size % 10 == item_size % 10 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 35.0 - 25.0 * fragmentation - 15.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference to fill fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.15;

    // Tie-break: slight noise-free deterministic jitter by residual class
    score += (post_class as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 400.0; // unusable sliver
        } else if post_residual < 25 {
            score += 150.0; // likely dead space for most distributions
        } else if post_residual < 50 {
            score += 40.0;
        }
    } else {
        score -= 300.0; // perfect fit is gold
    }

    // Reward tight fits relative to bin capacity.
    score -= 2.0 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Pressure on open bins count: when many bins are open, consolidate;
    // when few are open, opening a new bin is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins open, reward when consolidation is bad.
        score += 80.0 + 6.0 * pressure;
        // If no open bin fits well (large post_residual everywhere), allow new bin.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 60.0;
        }
    }

    // Lookahead: if next item fits into this bin's post_residual, reward placement here.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 120.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 60.0; // blocks the next item
    }

    // Mild alignment with mean residual: prefer bins whose residual is near the mean
    // (keeps bin population balanced), penalize outliers.
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits here: penalize leftover after hypothetical next placement
            let after_next = post_residual - next_item_size;
            score += after_next as f64 * 0.6;
        } else {
            // next item cannot fit here: mildly reward tight current fit
            score -= (post_residual as f64) * 0.15;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.8;

    // Last chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // Penalize opening a new bin when open bins could fit, unless residual is large
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize proportionally to item size waste
        score += (bin_capacity - item_size) as f64 * 0.9;
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Dead space penalty: small unusable residuals
    if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 120.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste minimization, super-linear).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 40.0;

    // Penalize creating dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else {
            score -= 3.0; // bin stays useful for lookahead item
        }
        // Perfect chaining: residual exactly fits next item
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is justified for large items
    // or when existing residuals are all poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Large items leave large usable residuals in fresh bins.
        let big_item_bonus = if item_size >= 50 { 12.0 } else { 0.0 };
        // Late in the stream, prefer consolidating into open bins.
        let late_penalty = 25.0 * progress;
        // If many bins fit the item, opening a new one is wasteful.
        let crowding_penalty = (fitting_bins_count as f64) * 6.0;
        // If mean residual is large, open bins have room; discourage new bin.
        let mean_room_penalty = mean_residual * 0.35;
        score += 55.0 + big_item_bonus - late_penalty + crowding_penalty + mean_room_penalty;
        // Very small items should never go to a fresh bin if anything fits.
        if item_size <= 20 {
            score += 30.0;
        }
    } else {
        // Prefer fuller bins among open bins (best-fit bias via residual).
        score += (bin_residual as f64) * 0.15;
        // Slight bonus for bins already below mean residual (well-utilized).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Early stream: be slightly exploratory, allow more bins; late: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling: post_residual shaped by stream progress
    let poly = pr_norm * (1.0 + 2.0 * progress * pr_norm + 1.5 * progress * progress * pr_norm * pr_norm);

    // Reward tight fits (low post residual) more strongly later in the stream
    let mut score = poly * (1.0 + fit_ratio);

    // Dead-space penalty: residuals too small to likely fit future items
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + progress);
        } else {
            // smooth lookahead bonus for residual that fits next item
            let slack = (pr - nxt) / cap;
            score -= 3.0 * slack * (1.0 - progress);
        }
    }

    // Last-chance bin bonus: avoid opening a new bin when only one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 - progress);
    }

    // Penalize spreading across many open bins slightly
    score += 0.15 * open_bins_count as f64 * pr_norm;

    // Mild deviation from mean residual: prefer bins near mean to keep balance
    let dev = (pr - mean_residual).abs() / cap;
    score += 1.2 * dev * dev * cap * 0.1;

    // New-bin candidate: neutral baseline with slight early-stream preference
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.3 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo small moduli
    let r = post_residual;
    let r4 = (r % 4) as f64;
    let r5 = (r % 5) as f64;
    let r10 = (r % 10) as f64;
    let r25 = (r % 25) as f64;

    // Reward residuals that form "nice" harmonic classes (multiples of 10/25)
    if r % 10 == 0 { score -= 6.0; }
    if r % 25 == 0 { score -= 4.0; }
    if r % 5 == 0 && r % 10 != 0 { score -= 2.0; }

    // Penalize awkward small residues that are hard to fill later
    if r > 0 && r < 10 { score += (10 - r) as f64 * 1.5; }

    // Integer-division threshold classes on post_residual
    let q = r / 20; // coarse class: 0..5
    score += q as f64 * 0.8; // slight preference for fuller bins (smaller q)

    // Coupling with lookahead item: if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 12.0; // perfect harmonic match
        } else if r >= next_item_size && (r - next_item_size) % 10 == 0 {
            score -= 5.0; // leaves a multiple-of-10 residue
        } else if next_item_size > r {
            score += 3.0; // next item won't fit here
        }
        // modulo coupling between next item and residual class
        if next_item_size % 10 == r % 10 && r >= next_item_size {
            score -= 1.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when no good harmonic fit exists
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let penalty = 10.0 + 8.0 * progress + 0.05 * open_bins_count as f64;
        score += penalty;
        // opening a new bin is fine if current residual classes are all bad
        if r10 > 0.0 && r25 > 0.0 && next_item_size > r {
            score -= 9.0;
        }
    }

    // Mean-residual coupling: prefer bins near the mean (balanced packing)
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 3.0;

    // Tight fit reward
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 4.0;

    // Dead-space penalty via harmonic fraction of residual
    score += (r5 * r4) / 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - pr) * 40.0; // dead space of 1..10 is nearly worthless
    } else if post_residual == 0 {
        score -= 60.0; // perfect fit is excellent
    } else if post_residual <= 20 {
        score += (21.0 - pr) * 6.0; // mildly risky small gap
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: penalize new bins, scaled by how full the stream is.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 45.0 + open_bins_count as f64 * (8.0 + 12.0 * progress);
        // Opening a new bin is acceptable if this item is large relative to look-ahead needs
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 20.0; // fresh bin still useful for the next item
        }
    } else {
        // Prefer bins whose residual is close to what's needed; waste-averse tie-break.
        score += (mean_residual - pr).abs() * 0.3;
    }

    // Lookahead coupling: leaving a gap exactly fitting the next item is great.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + 10 {
        score += 12.0; // gap just barely above next item wastes space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good (already in base score).
    // Penalize dead space that is too small for typical future items (wasted capacity).
    if post_residual > 0 {
        let dead = post_residual as f64;
        // unusable sliver penalty: residual too small to be useful later
        if dead < 10.0 {
            score += 40.0 * (10.0 - dead) / 10.0;
        }
    } else {
        // perfect fill: strong reward
        score -= 25.0;
    }

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0; // perfect chained fit
        } else if next_item_size < post_residual {
            let npost = post_residual - next_item_size;
            // reward proportional to how tight the second fit is
            score -= 20.0 * (1.0 - npost as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize slightly more if it creates stranded space
            score += 8.0;
        }
    }

    // Compare against mean residual: prefer bins whose residual is close to item size
    // (tight packing relative to fleet average).
    let res_f = bin_residual as f64;
    let tightness = (res_f - item_size as f64).abs();
    score += 0.15 * tightness;

    // Favor bins with residual below mean (they are the "fuller" bins -> consolidate)
    if res_f < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless item is large
    // or no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let base_penalty = 45.0;
        // large items pack better in fresh bins; small items should use leftovers
        let largeness = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = base_penalty - 40.0 * largeness;
        // late in stream, be more willing to open bins (avoid overstuffing early bins)
        new_bin_score -= 10.0 * progress;
        // if many bins already fit the item, opening new bin is wasteful
        if fitting_bins_count > 0 {
            new_bin_score += 15.0 * (fitting_bins_count as f64).min(5.0);
        }
        score = new_bin_score + post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness: prefer small post_residual relative to item size
        let tightness = post_residual as f64 / item_size.max(1) as f64;
        score += tightness * 10.0;

        // Lookahead: penalize if next item fits into post_residual (we'd want space saved),
        // but only mildly; penalize more if post_residual is too small to be useful
        if next_item_size > 0 {
            if (next_item_size as u32) <= post_residual {
                // space useful for the next item: reward keeping it
                score -= (next_item_size as f64) * 0.5;
            } else {
                // dead space: post_residual too small for next item
                let waste = post_residual as f64;
                let horizon = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
                score += waste * (0.3 + 0.7 * horizon);
            }
        }

        // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
        if fitting_bins_count == 1 && bin_residual >= item_size {
            score -= 500.0;
        }

        // Prefer bins with residual below half capacity being filled exactly
        if post_residual < bin_capacity / 4 {
            score -= 20.0;
        }

        // Many open bins: prefer consolidating into fuller bins
        if open_bins_count > 3 {
            let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
            score -= fullness * 30.0;
        }

        // Global mean residual coupling: if mean residual is low, avoid leaving gaps
        if mean_residual < (item_size as f64) {
            score += 15.0;
        }
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let bad_fit = fitting_bins_count == 0
            || (post_residual as f64) > (bin_capacity as f64) * 0.5 && fitting_bins_count <= 1;
        if bad_fit {
            score -= 300.0;
        } else {
            score += 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, larger residuals are mildly penalized (save space); later,
    // tight fits (small post_residual) are strongly rewarded.
    let w = 0.5 + 1.5 * progress;
    score += w * (pr / cap) * (pr / cap) * cap;

    // Reward when the leftover would exactly fit the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0 + 8.0 * progress;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // leftover too small for next item: dead space penalty grows with progress
        score += (1.0 - pr / cap) * (4.0 + 10.0 * progress);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize spreading across many open bins slightly; encourage consolidation.
    score += (open_bins_count as f64).ln() * (pr / cap) * 3.0;

    // New-bin candidate: prefer opening a new bin only when no tight fit exists.
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into a "reusable"
    // class (divisible by common item sizes) are more valuable to preserve.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -50.0 // perfect fill
    } else if pr <= 10 {
        5.0 // dead space
    } else if pr % 50 == 0 {
        -12.0
    } else if pr % 25 == 0 {
        -9.0
    } else if pr % 20 == 0 {
        -8.0
    } else if pr % 10 == 0 {
        -6.0
    } else if pr % 5 == 0 {
        -3.0
    } else {
        2.0
    };
    score += harmonic_bonus;

    // Tightness: reward small post_residual non-linearly.
    let tight = (1.0 - post_residual as f64 / cap).powi(3);
    score -= 8.0 * tight;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr && pr - next_item_size <= 10 {
            score -= 10.0;
        } else if next_item_size > pr {
            score += 4.0; // next item won't fit here; this residual likely wasted
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_ratio = item_size as f64 / cap;
        // opening new bin is cheap early or when item is large
        score += 6.0 - 10.0 * fit_ratio - 4.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 6.0; // new bin can host item + next item
        }
    }

    // Prefer bins below mean residual (keeps a spread of residual classes).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Mild pressure against bin sprawl.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item are waste.
    if post_residual > 0 {
        // Dead zone: residual below the minimum plausible item size (assume ~10, but
        // scale down gracefully if items get small); penalize heavily.
        let min_useful = (next_item_size.max(10)).min(20) as f64;
        if (post_residual as f64) < min_useful {
            score += 60.0 * (min_useful - post_residual as f64) / min_useful;
        }
    }

    // Reward near-perfect fits (post_residual close to 0 but nonzero is already low).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Lookahead coupling: if next item fits exactly in post_residual, strong bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Mild bonus proportional to how well next item fills the leftover.
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use this residual: penalize large leftovers.
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize opening/spreading when open_bins_count is high).
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., mean residual is small relative to item) or many bins are open.
    if bin_residual == bin_capacity {
        let spread_need = (item_size as f64 / mean_residual.max(1.0)).min(2.0);
        score += 30.0 - 20.0 * spread_need - 1.5 * open_bins_count as f64;
        // Penalize new bins early in the stream less (exploration allowed).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mean-residual coupling: bins far below mean residual are less attractive
    // targets (keep larger residuals for larger future items).
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

