    let mut score = (pr / cap).powi(2) * 100.0 + pr * 0.1;

    // Reward tight fits with smooth polynomial coupling to stream progress
    let tightness = 1.0 - (pr / cap);
    score -= 60.0 * tightness.powi(3) * (0.5 + progress);

    // Lookahead coupling: penalize residuals that neither fit nor waste for next item
    if next_item_size > 0 {
        let gap = pr - next_ratio * cap;
        let usable = if gap >= 0.0 { 1.0 } else { -1.0 };
        score += usable * 15.0 * (gap.abs() / cap).powi(2) * (1.0 - progress);
    }

    // Last-chance bin bonus (avoid opening new bins)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Penalize spreading across many open bins vs mean residual
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Slight preference for fuller bins late in stream
    score -= 5.0 * fit_ratio * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
