    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small residuals are "dead space" classes
    let post = post_residual;
    if post > 0 {
        // class the residual by integer division thresholds
        if post <= 10 {
            score += 25.0; // unusable sliver for most items
        } else if post <= 20 {
            score += 10.0;
        } else if post <= 30 {
            score -= 5.0;
        }
        // modulo-10 harmonic: residuals that are exact multiples of 10 align
        // with typical item granularity -> more usable
        if post % 10 == 0 {
            score -= 8.0;
        }
    }

    // Lookahead: can next item fill this bin's post_residual exactly?
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 500.0; // chain perfect fit
        } else if post >= next_item_size {
            // next item fits here too: mild reward proportional to how snugly
            score -= 3.0 + (post - next_item_size) as f64 * 0.1;
        } else {
            // next item won't fit in post_residual: penalize wasted slot
            score += (next_item_size - post) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a
    // near-perfect packing of item + lookahead
    if bin_residual == bin_capacity {
        score = cap_f - item_size as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0; // fresh bin can host current + next snugly
        }
        if fitting_bins_count > 0 {
            score += 40.0; // an existing bin could fit; prefer it mildly
        }
    }

    // Stream progression: late in the stream, consolidate harder
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0;

    // Prefer bins with below-mean residual (tighter bins) to keep slack concentrated
    let mean_gap = mean_residual - bin_residual as f64;
    score += mean_gap * 0.5;

    // Many open bins: encourage filling existing ones rather than spreading
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

