    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins rather than opening new ones.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless dead-space penalty dominates).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: attractive only when this item would leave a large,
