    // New-bin candidate handling: only attractive when open bins are crowded
    // or the item would leave a very awkward residual elsewhere.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        let late = step_index as f64 / (total_items.max(1) as f64);
        let awkward = if next_item_size > 0 && post_residual_ok_elsewhere(post_residual, next_item_size) { 0.0 } else { 20.0 };
        score += 45.0 - 15.0 * crowd - 20.0 * late - awkward;
        // Empty bin wastes nothing if item is huge relative to capacity.
        score -= 0.3 * item_size as f64;
    }

    // Mild penalty for very small post_residual that is also not a perfect
    // lookahead fit (fragmented slivers).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(15) {
        score += 8.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer
    // consolidating into existing space.
    if mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 0.1 * mean_residual;
    }

    score
}

// Helper inlined logic (kept as closure-free expression via function for clarity)
fn post_residual_ok_elsewhere(post_residual: u32, next_item_size: u32) -> bool {
    post_residual >= next_item_size
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let p2 = norm_pr * norm_pr;
    let p3 = p2 * norm_pr;
    score += 12.0 * p2 * (1.0 - progress) - 8.0 * p3 * progress;

    // Penalize residual that fails to fit the lookahead item (smooth quadratic)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 20.0 * gap * gap;
        // Reward when lookahead fits perfectly
        let fit = (pr - next_item_size as f64).abs() / cap;
        score -= 10.0 * (1.0 - fit) * (1.0 - fit) * (next_item_size as f64 / cap);
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Mean residual coupling: penalize bins far from the fleet average
    score += 0.4 * (pr - mean_residual).abs();

    // Mild preference for keeping bin count low early on
    score += 0.5 * (open_bins_count as f64) * progress;

    // Slight bonus for tight fits overall
    score -= 6.0 * (1.0 - norm_pr) * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // small classes (multiples of common item sizes) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let frac = pr as f64 / cap;

    // Reward small post_residual strongly (tight fit).
    score -= 40.0 * (1.0 - frac).powf(3.0);

    // Harmonic classes: post_residual divisible by 10, 20, 25, 50 is more reusable.
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 5.0; }
        // Dead zone: residuals in (0,10) are unusable (min item size ~1..100 unknown),
        // penalize tiny dead space.
        if pr < 10 { score += 12.0; }
    } else {
        // Perfect fill.
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // Next item fits; penalize based on resulting leftover awkwardness.
            let nn = (pr - next_item_size) % 10;
            score -= 8.0 - (nn as f64);
        } else {
            // Next item won't fit here; mild penalty for leaving large unusable gap.
            if pr > 0 && pr < next_item_size {
                score += (pr as f64) * 0.15;
            }
        }
    }

    // Last chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer filling already-open bins over opening new ones when residual is tight.
    if bin_residual < bin_capacity {
        score -= 5.0;
        // Tie-break toward bins below mean residual (more filled).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    } else {
        // New-bin candidate: penalize unless current bins would waste a lot.
        let waste_if_used = (bin_residual - item_size) as f64;
        if waste_if_used > 0.5 * cap {
            score -= 10.0;
        } else {
            score += 15.0;
        }
    }

    // Open-bin pressure: many open bins -> discourage opening another.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.0;
    }

    // Stream progression: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space penalty
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: with many bins open, prefer filling existing bins
    // over opening new ones; make the new-bin candidate less attractive.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean-residual coupling: if this bin's residual is far below mean,
    // it is a "straggler" bin — favor closing it out.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.5 * dev;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // reward leaving that gap; if not, penalize leaving medium gaps.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 12.0;
        }
    }

    // New-bin candidate handling: an empty bin has high base cost that grows
    // with open bins, but is acceptable when no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 45.0 + 1.2 * open_bins_count as f64;
        // If current item is large, opening a fresh bin is more reasonable.
        if item_size >= 50 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here: reward tight coupling
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 0.4;
        } else {
            // next item won't fit here: penalize wasted residual
            score += 25.0;
        }
    } else {
        // last item: minimize residual
        score += 10.0;
    }

    // Reward bins tighter than the mean residual (good fits)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Penalize large dead space relative to capacity
    let dead = post_residual as f64 / bin_capacity as f64;
    if dead > 0.2 {
        score += (dead - 0.2) * 80.0;
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 120.0;
        // but if no open bin fits well, allow new bin
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // late in stream, prefer consolidating
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements that nearly fill the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio * (bin_residual as f64 / bin_capacity as f64);

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 && post_residual > 0 {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // Perfect chain: item + next item exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 40.0;
        }
    } else {
        // Last item: waste minimization dominates.
        score += 15.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is attractive when open bins
    // are fragmented (high mean residual spread) and many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 35.0 - 8.0 * open_bins_count as f64 - 10.0 * (1.0 - progress);
        if next_item_size > item_size {
            score -= 10.0; // big item coming, fresh bin useful
        }
        if fragmentation > 40.0 {
            score -= 5.0;
        }
    } else {
        // Mild penalty for many open bins to encourage consolidation.
        score += 0.15 * open_bins_count as f64;
    }

    // Time horizon: early in the stream, keep bins roomy; late, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0 * post_residual as f64 / bin_capacity as f64;

    // Penalize leaving residuals just above common small-item sizes.
    for threshold in [10u32, 20, 30, 50] {
        if post_residual > threshold && post_residual <= threshold + 5 {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear sharpening
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in stream, penalize wasted space more
    let prog_coupling = 1.0 + 2.0 * progress * progress;
    score *= prog_coupling;

    // Lookahead: reward if next item fits in post_residual (smoothly)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit = if pr >= nx { 1.0 - (pr - nx) / cap } else { -1.0 + nx / cap };
        score -= 8.0 * fit;
        // exact fit lookahead bonus
        if (pr - nx).abs() < 1.0 {
            score -= 12.0 * (1.0 + progress);
        }
    } else {
        // last item: strongly prefer tightest fit
        score += 0.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalize when many bins can fit (less urgency) — smooth
    score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);

    // Compare to mean residual: penalize bins whose post_residual deviates far below mean (fragmentation)
    score += 0.5 * (mean_residual - pr).abs() / cap;

    // New-bin candidate: mild penalty so it's chosen only when clearly better
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
    }

    // Tiny tie-breaker favoring fuller bins
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (divisible by common item granularities) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // Class bonus: leftover that is a multiple of 10 is reusable.
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 2.5;
        } else {
            score += 3.0; // awkward leftover
        }
        // Integer-division threshold: small leftovers are dead space.
        let dead = pr / 12; // number of 12-sized chunks that fit
        if dead == 0 {
            score += 8.0; // leftover too small for typical items
        } else {
            score -= dead as f64 * 1.5;
        }
    } else {
        // Perfect fit is ideal.
        score -= 25.0;
    }

    // Capacity fraction coupling: reward filling bin past halfway.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 10.0;

    // Lookahead harmonic coupling: if next item exactly fits post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 8.0;
        } else if pr < next_item_size && pr < 10 {
            score += 5.0; // leftover blocks the known next item
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are tight.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 30.0 * (1.0 - pressure);
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing fits, must open
        }
        // Early in stream, keep bins open; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean
    // (keeps the pool homogeneous for future harmonic matching).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Many open bins: favor tighter packing to consolidate.
    if open_bins_count > 4 {
        score += open_bins_count as f64 * 0.3 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward when post_residual exactly matches next item (perfect 2-step chain)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64).max(0.0);

        // Perfect chain: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Post residual can fit next item too (double chain)
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Dead space penalty: leftover smaller than smallest possible item
            score += 15.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64).max(0.0);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening new bins when decent fits exist (new-bin candidate has residual == capacity)
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early stream: allow more bins; late stream: consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Slight reward for tight fits (low post_residual already does this; amplify)
    score -= 0.3 * (bin_capacity as f64 - post_residual as f64) * (item_size as f64 / bin_capacity as f64);

    // Discard tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (post_residual small).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Tightness ratio: reward small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Lookahead: if the next item exactly fits the leftover space, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use the leftover: penalize large dead space a bit more
            score += (next_item_size - post_residual).min(30) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Avoid scattering items across many bins when mean residual is large:
    // prefer bins with residual close to the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // Early in the stream, be slightly more willing to spread (keep flexibility);
    // late in the stream, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;
    score += (1.0 - progress) * 5.0;

    // If many open bins, encourage filling existing ones rather than opening new.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins exist and can absorb the item.
        if open_bins_count > 0 {
            score += 50.0 + open_bins_count as f64 * 2.0;
        }
        // Slightly favor opening a new bin late in stream if it avoids a bad fit
        // elsewhere (handled by the tightness term above).
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + t) + norm_pr * (1.0 - t) * (1.0 - t);
    score += 40.0 * poly;

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.3 + t);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (pr as u32) < next_item_size {
