            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use this residual; penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when no good fit exists elsewhere
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced open
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 15.0; // big upcoming item favors fresh bin
        }
    }

    // Progression: as stream advances, tighten packing (avoid spreading)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    // Prefer bins with residual far below mean (denser bins) slightly
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Integer division threshold on post_residual classes
    if post_residual >= 50 {
        score -= 5.0; // large residuals still useful
    } else if post_residual >= 25 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use
    // (below the minimum item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit: maximal reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward bins whose post_residual matches the lookahead item well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            score -= 25.0 / (1.0 + gap);
        } else if post_residual > 0 {
            // post_residual too small for next item: mild penalty scaled by waste
            score += 0.5 * (post_residual as f64);
        }
    }

    // Open-bins pressure: when many bins are open, prefer consolidation
    // (penalize opening new bins / spreading items).
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin is attractive only if the
    // current item is large or fits are scarce; otherwise penalize opening it.
    if bin_residual == bin_capacity {
        if item_size >= 50 || fitting_bins_count == 0 {
            score -= 15.0;
        } else {
            score += 30.0 + mean_residual * 0.3;
        }
    }

    // Prefer placing into bins with small residual relative to the mean
    // (keeps big gaps available for big items).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.8;

    // Slight preference for tighter fits overall.
    score += 0.3 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact/tight fits (small post_residual)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // 2-step lookahead: reward if next item fits into post_residual (chained packing)
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - chain_slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize leaving a gap that the next item cannot use
        let gap = post_residual as f64;
        score += 4.0 * gap / bin_capacity as f64;
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably
    score += 0.6 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 20.0 + 8.0 * (post_residual as f64 / bin_capacity as f64);
        // If lookahead chains nicely into a fresh bin, soften the penalty
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Slight preference to fill older/crowded bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (non-linear in post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item can't fit here; slight penalty proportional to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when current bins are nearly full or too fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = bin_capacity as f64 - mean_residual;
        // penalize opening new bins when open bins still have good average space
        score += 25.0 + mean_residual * 0.5 - avg_fill * 0.1 - progress * 10.0;
        // if no open bin fits well, new bin becomes more attractive
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild penalty for spreading across many open bins when residuals are large
    if open_bins_count > 4 && mean_residual > 30.0 && bin_residual < bin_capacity {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = progress;
    let coupling = norm_pr * norm_pr * (1.0 - p) + norm_pr * p * p;
    score += 40.0 * coupling;

    // Reward tight fits more strongly as stream progresses
    let tightness = (item_size as f64 / bin_residual.max(1) as f64).min(1.0);
    score -= 25.0 * tightness * tightness * (0.5 + p);

    // Penalize dead space relative to mean residual across open bins
    score += 0.15 * (pr - mean_residual).abs();

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + 15.0 * p;
    } else if next_item_size > post_residual {
        score += 5.0 * p;
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * p;

    // New-bin candidate: penalize opening a new bin unless residuals are low
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - p) + 0.3 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: multiples of 10 are "usable" classes.
    let cls = post_residual % 10;
    if cls == 0 {
        score -= 6.0; // perfectly aligned leftover -> reward
    } else if cls <= 3 {
        score += 4.0; // tiny dead space -> penalize
    } else if cls >= 7 {
        score -= 2.0; // large-ish chunk still usable by small items
    }

    // Integer-division thresholds on post_residual
    let pr = post_residual;
    if pr == 0 {
        score -= 25.0; // perfect fill
    } else if pr < 10 {
        score += 12.0; // unusable sliver
    } else if pr < 20 {
        score += 5.0;
    } else if pr < 35 {
        score += 1.0;
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic match: next item size in same decade class as pr
            let nd = next_item_size / 10;
            let pd = pr / 10;
            if nd == pd {
                score -= 10.0;
            } else {
                score -= 4.0;
            }
        } else {
            score += 6.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer opening when current fit is bad
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let bad_fit = (pr as f64) > 0.45 * bin_capacity as f64;
        if bad_fit {
            score -= 8.0;
        } else {
            score += 20.0; // existing bin fits decently -> keep using it
        }
        if open_bins_count == 0 {
            score -= 100.0; // forced open
        }
    }

    // Stream progression: late in stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !is_new_bin {
        score -= 3.0 * progress * (mean_residual - pr as f64).abs() / bin_capacity as f64;
    }

    // Prefer tighter fits relative to mean residual
    score += 0.05 * (pr as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to fit typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 30.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Pressure from number of open bins: discourage opening new bins when many
    // are already open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 8.0;
    }

    // Mild mean-residual coupling: prefer bins below mean residual (consolidate fullness).
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits into the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 60.0 + (after_next as f64) * 0.5;
        if after_next == 0 {
            score -= 150.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving large dead space.
        score += (post_residual as f64) * 0.4;
    }

    // Relative to mean residual: prefer bins already below-average residual
    // (tight bins) to concentrate waste.
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 250.0 + 150.0 * (1.0 - progress) + (open_bins_count as f64).sqrt() * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Tight fit reward: smaller post_residual relative to capacity
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 10.0 * tightness * tightness;
    }

    // Lookahead: reward leaving room for the next item (k=2 lookahead)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack_after_next / bin_capacity as f64);
    }
    // Penalize creating dead space unusable by the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Mild competition bonus scaled by scarcity
        score -= 3.0 / fitting_bins_count as f64;
    }

    // Global state: prefer filling bins when many are open (consolidation)
    if open_bins_count > 2 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }
    // Reward bins that are emptier than average when mean residual is high (spread waste)
    if (bin_residual as f64) > mean_residual {
        score -= 1.5;
    }

    // New-bin candidate handling: penalize opening a fresh bin,
    // unless the item is large (better to give big items fresh space)
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size > bin_capacity / 2 { 10.0 } else { 0.0 };
        score += 25.0 - large_item_bonus
            + 10.0 * (1.0 - item_size as f64 / bin_capacity as f64);
    }

    // Time horizon: early in stream, be more exploratory (slightly favor new bins);
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post_residual, damped by progress (late stream -> tolerate less waste)
    let mut score = pr * (1.0 + 0.5 * progress);

    // Smooth polynomial coupling: penalize small-but-nonzero post_residual quadratically
    score += 40.0 * pr_norm * (1.0 - pr_norm) * (1.0 - progress);

    // Reward tight fits: subtract proportional to fill ratio, scaled by progress
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill * fill * (0.5 + progress);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - pr_norm);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let gap = (pr as i64 - next_item_size as i64).max(0) as f64;
        score -= 8.0 * (gap / cap) * (1.0 - progress);
        if (pr as i64 - next_item_size as i64) == 0 {
            score -= 15.0;
        }
    }

    // Prefer bins below mean residual slightly (keep balanced residuals)
    score += 0.05 * (pr - mean_residual);

    // New-bin candidate: penalize mildly, more so early in the stream
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small residues are dead space
    let pr = post_residual;
    if pr <= 10 {
        score += 30.0; // tiny residue is fine actually — wait, small residue means tight fit
        score -= 60.0;
    } else if pr <= 20 {
        score -= 25.0; // still likely usable for min item
    } else if pr < 40 {
        // awkward middle zone: dead space risk
        score += 15.0 + (40 - pr) as f64 * 0.5;
    }

    // Penalize residues that no future item (>=1, up to 80) can plausibly fill
    if pr > 0 && pr < 10 {
        score -= 20.0; // effectively full
    }
    if pr >= 80 {
        score += 10.0; // large residue left behind is wasteful
    }

    // Lookahead coupling: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 40.0 + next_item_size as f64 * 0.3;
        } else if pr > 0 && next_item_size > pr {
            // next item won't fit here; leaving moderate residue is worse
            score += 8.0;
        }
        // harmonic class match: next item size class vs residue class
        let nclass = next_item_size / 20;
        let rclass = pr / 20;
        if nclass == rclass && pr >= next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 200.0 } else { 0.0 };
        score -= pressure;
        // opening a new bin wastes mean_residual spread across open bins
        score += mean_residual * 0.15;
        // early in stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
        // if item is large and would leave big residue in any bin, new bin is fine
        if item_size as f64 / cap > 0.7 {
            score -= 15.0;
        }
    }

    // Mild preference for fuller bins overall
    score -= (bin_residual - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize medium dead space less harshly; large residual is reusable.
    if post_residual >= 10 && post_residual < 30 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Open-bin pressure: many open bins -> favor filling existing bins,
    // penalize opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress);
    score += 0.05 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only open a new bin when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 25.0;
        // Strong penalty if other bins can already fit the item.
        if fitting_bins_count > 0 {
            score += 60.0;
        }
        // If this is a last-chance situation, opening a new bin is acceptable.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it.
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // If next item cannot fit in post_residual, slight penalty for wasted potential.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 3.0;
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean
    // (keeps bin population homogeneous).
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect two-item match: this bin holds item AND next item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward near-perfect two-item match.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
    }
    // Penalize leaving a dead sliver: post_residual > 0 but too small for next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }
    // Perfect single-item fit (bin becomes exactly full).
    if post_residual == 0 {
        score -= 45.0;
    }
    // Penalize wasting space relative to the mean residual of open bins.
    score += 0.15 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }
    // Opening a new bin is attractive when this fit is poor (large post_residual)
    // and the next item is small enough to use a fresh bin fully.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if next_item_size > 0 && post_residual > next_item_size {
            score -= 20.0 + 10.0 * (1.0 - progress);
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 15.0; // fresh bin would leave a worse dead space for next item
        }
        // Mild penalty for bin proliferation when many bins are already open.
        score += 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strong reward for tight fits (small post_residual relative to item).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.5 * fill_ratio * post;

    // Penalize post_residual that no typical small item could use.
    if post > 0.0 && post < 10.0 {
        score += 30.0; // dead space below min item size is wasted
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 5.0 * (1.0 - post / next_item_size as f64);
        }
    } else {
        // Last item: prefer fullest packing, reward any fill.
        score -= 5.0 * fill_ratio;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64 / cap) * (1.0 + 0.5 * open_bins_count as f64 / (1.0 + mean_residual / cap));
        score = cap - item_size as f64 - 12.0 * pressure;
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild time-dependent consolidation: prefer existing bins more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 3.0 * progress * fill_ratio;
        // Penalize bins far from mean residual (encourage uniform packing).
        score += 0.05 * (post - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: quadratic waste penalty on post_residual
    let mut score = pr * pr / cap;

    // Non-linear coupling of fill level with stream progress:
    // late in the stream, prefer tight fits more aggressively.
    let tightness = (fill * fill * (3.0 - 2.0 * fill)) - 0.5;
    score -= tightness * (0.5 + progress) * cap * 0.25;

    // Reward bins whose residual matches the lookahead item (smooth kernel).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= (1.0 - diff / cap).powi(4) * 8.0;
    }

    // Penalize when this is one of many fitting bins (spread load), reward scarcity.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0).ln() * 2.0;
    } else {
        score -= 4.0;
    }

    // Coupling with mean residual: prefer bins far from the mean (balanced spread),
    // stronger effect as stream progresses.
    let dev = (pr as f64 - mean_residual) / cap;
    score += dev * dev * (1.0 + 3.0 * progress) * cap * 0.1;

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly;
    // discount grows early when few bins are open.
    if bin_residual == bin_capacity {
        score += 6.0 - 3.0 * progress - (open_bins_count as f64).ln().max(0.0);
    }

    // Small smooth tie-breaker on exact fit.
    score -= (fill.powi(6)) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common
    // granularity classes are more reusable; penalize "ugly" residues.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -40.0 // perfect fit
    } else if pr % 10 == 0 {
        -6.0
    } else if pr % 5 == 0 {
        -3.0
    } else if pr % 2 == 0 {
        -1.0
    } else {
        2.0 // odd residual: harder to reuse
    };
    score += class_bonus;

    // Integer-division threshold: large post_residual is wasteful, but
    // only if it cannot host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // chainable: next item fits here
        } else {
            // dead space relative to lookahead: penalize proportionally
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
            // harmonic coupling: dead space that is a small multiple of
            // granularity classes is less harmful
            if pr >= 1 && (next_item_size % pr.max(1)) == 0 {
                score -= 2.0;
            }
        }
    } else {
        // last item: just minimize residual
        score -= 5.0;
    }

    // Last-chance bin: strongly reward using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many open bins: discourage spreading; prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.15 * crowding * (0.5 + progress);

    // New-bin candidate (empty bin): penalize unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let base = 15.0
            + 0.3 * open_bins_count as f64
            + 0.2 * mean_residual;
        // If the item leaves a large residual in a fresh bin and no other
        // bin is tight, opening is acceptable: reduce penalty.
        let relief = if fitting_bins_count == 0 { 20.0 } else { 0.0 };
        score += base - relief;
        // Opening is better when the lookahead item is large and would
        // need a fresh bin anyway.
        if next_item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Tight-fit reward: small post_residual relative to item size.
    if item_size > 0 {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 10.0 * fill_ratio * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Modulo harmonic class on item_size: items in "round" classes pack
    // predictably; slight reward for pairing with matching residual class.
    if pr > 0 && item_size % 10 == 0 && pr % 10 == 0 {
        score -= 2.5;
    }
    if pr > 0 && item_size % 25 == 0 && pr % 25 == 0 {
        score -= 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (size 1..100 unknown distribution -> assume
    // small items still possible) are graded non-linearly. A residual of 0
    // is perfect; small nonzero residuals are heavily penalized.
    if post_residual == 0 {
        score -= 50.0; // perfect fit reward
    } else if post_residual <= 10 {
        // unusable dead space zone
        score += (11.0 - post_residual as f64) * 8.0;
    } else if post_residual < item_size {
        // gap too small for a similar item again: mild penalty
        score += 3.0;
    }

    // Reward bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Last chance: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin
    // offers a good fit, and penalize opening bins under low pressure.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.5);
        score += 15.0 + pressure * 5.0;
        if fitting_bins_count > 1 {
            score += 40.0; // never open when several bins fit
        }
        // Lookahead: if next item could share residual left after placement,
        // opening a new bin is less attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    } else {
        // Existing-bin placement that leaves room for the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 2.0; // blocks the lookahead slightly
        }
    }

    // Open-bin pressure: mildly discourage scattering across many bins.
    score += open_bins_count as f64 * 0.5;

    // Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    } else {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: reward when next item exactly fills post_residual ---
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for next item: strong reward
        if gap < 0.5 {
            score -= 60.0;
        } else {
            // Penalize mismatch proportionally; next item must also fit somewhere
            score += gap * 0.8;
            // If next item cannot fit in this residual, mild penalty unless residual is tiny
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.3;
            }
        }
    } else {
        // Last item: just minimize waste
        score -= 5.0;
    }

    // --- Dead-space shaping: penalize residuals that are small but nonzero ---
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are bad
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    }

    // --- Relative to mean residual of open bins ---
    // Prefer bins whose post-residual lands near the mean (keeps flexibility),
    // penalize creating residuals far above the mean (fragmentation).
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();
    if dev > 0.0 {
        score += 0.25 * dev; // extra penalty for leaving more than average
    }

    // --- Last-chance bin: if this is the only bin that fits, strongly favor using it ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is acceptable early (plenty of stream left to fill it),
        // but discouraged late or when few items remain.
        let horizon = (total_items.saturating_sub(step_index)) as f64;
        score += 20.0 - 15.0 * progress;
        if horizon < 3.0 {
            score += 50.0; // don't open bins near the end
        }
        // If many open bins already have large residuals, avoid opening another
        if mean_residual > 40.0 {
            score += 10.0;
        }
    }

    // --- Mild preference for tighter existing bins (best-fit bias) ---
    score += 0.1 * (bin_capacity - bin_residual) as f64;

    // --- Slight penalty for accumulating many open bins ---
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic decay of post_residual.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize dead space that no future item (min size 1) can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny sliver is wasted space
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            score += 3.0;
        }
        // Perfect pair: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Global state: penalize opening new bins when many open bins have slack.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open-bin slack.
        score += 18.0 + 0.5 * mean_residual + 0.3 * open_bins_count as f64;
        // Early in stream, opening bins is cheaper (builds portfolio).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If item is large and no open bin is a good fit, new bin more attractive.
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    } else {
        // Prefer bins with residual close to mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
        // Prefer using fuller bins (larger item fraction consumed).
        score -= 0.4 * (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // Late-stream urgency: consolidate into fewer bins as stream ends.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (bin_residual - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap;

    // Base: waste, with non-linear penalty growth for medium dead space
    let mut score = x * cap * (1.0 + 1.5 * x * (1.0 - x));

    // Tight fits strongly rewarded (smooth coupling of item_size and post_residual)
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 8.0 * tightness * tightness;

    // Stream-progress coupling: late stream, prefer larger residual consumption
    score += 6.0 * progress * x * x;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Lookahead: reward residual that can host the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let compat = (x - nx).abs();
        score -= 4.0 * (1.0 - compat.min(1.0)) * (1.0 - compat.min(1.0));
    }

    // Mean residual alignment: prefer bins near the mean (smooth quadratic)
    score += 0.05 * (pr as f64 - mean_residual) * (pr as f64 - mean_residual);

    // Mild penalty for leaving near-zero residual (unusable slivers)
    score += 3.0 * (-x * 20.0).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity fractions (quarters) and modulo-10 bands.
    let quarter = bin_capacity / 4;
    let post_class = (post_residual / quarter) as f64;      // 0..=3
    let post_mod = (post_residual % 10) as f64;

    // Reward tight fits: post_residual near zero, or exactly matching
    // a common item-size class (10/20/25/50) so leftover is reusable.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual % 25 == 0 || post_residual % 20 == 0 {
        score -= 12.0;
    } else if post_residual < quarter {
        score -= 8.0;
    } else {
        // Larger leftovers: penalize proportional dead space.
        score += post_class * 4.0;
    }

    // Small modulo noise to break ties toward round residuals.
    score -= post_mod * 0.3;

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin; if next item is close but not exact, mild bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= (1.0 - slack / cap) * 10.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: default to being expensive, but attractive when
    // open bins have large mean residuals (bad fragmentation) or the item
    // is large relative to what open bins hold.
    if bin_residual == bin_capacity {
        let base = cap * 0.85;
        let mut nb = base;
        if mean_residual > cap * 0.5 {
            nb -= 25.0; // open bins are fragmented; fresh bin is fine
        }
        if item_size >= bin_capacity / 2 {
            nb -= 15.0;
        }
        if open_bins_count > 8 {
            nb -= 10.0;
        }
        // Early stream: prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        nb += (1.0 - progress) * 10.0;
        score += nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize "unusable" dead space: gaps too small for typical items
        // (assume minimum item size 1, but gaps < ~15 are hard to fill).
        let dead = if post_residual < 15 {
            (15 - post_residual) as f64 * 8.0
        } else {
            0.0
        };
        score += dead;

        // Lookahead coupling: if the next item fits exactly into the post-residual,
        // strongly reward this placement (chained packing).
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 600.0;
            } else if next_item_size <= post_residual {
                // next item fits but leaves another gap: mild reward proportional to fit quality
                let slack = (post_residual - next_item_size) as f64;
                score -= 200.0 - slack * 2.0;
            } else {
                // next item cannot use the gap: penalize proportionally to wasted potential
                score += (next_item_size - post_residual) as f64 * 1.5;
            }
        }

        // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 120.0;
        }

        // Open-bin pressure: discourage spreading across many bins when residuals are large.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bin_pressure = open_bins_count as f64 * (1.0 - progress) * 0.5;
        score += bin_pressure;

        // Prefer bins whose residual is close to the mean residual (balanced packing),
        // penalize outliers that would strand large residuals.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.3;
    }

    // New-bin candidate: neutral baseline; only chosen when all open bins score badly.
    if bin_residual == bin_capacity {
        score = 200.0 + open_bins_count as f64 * 2.0
            - if next_item_size > 0 { (bin_capacity.saturating_sub(next_item_size)) as f64 * 0.1 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but reward exact/near-exact fills strongly.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness * tightness;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches
    // the next item size (chained perfect fits).
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 25.0 * (-gap / 10.0).exp();
        // Penalize dead space that no plausibly-sized item (>=1) can use.
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0 * (post_residual as f64 / 20.0);
        }
    } else {
        // Last item: any placement is fine; prefer fullest fill.
        score -= 10.0 * tightness;
    }

    // Relative to mean residual: placing into a below-average-residual bin
    // (tighter bin) is good; opening residual-rich bins wastes capacity.
    score += 4.0 * (post_residual as f64 - mean_residual);

    // Last-chance bin before opening a new bin: strong bonus to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: discourage opening a new bin unless it is truly needed
    // (e.g. item is large and would leave big dead space elsewhere, or many bins
    // are already open and congested).
    if bin_residual == bin_capacity {
        let dead_elsewhere = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs()
        } else {
            0.0
        };
        let congestion = (open_bins_count as f64 / 16.0).min(1.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty so open bins are preferred; reduced when open bins are
        // scarce, item is huge, or stream is late.
        let mut penalty = 20.0 + 10.0 * congestion;
        penalty -= 12.0 * (item_size as f64 / 100.0);
        penalty -= 8.0 * progress;
        // If this fresh bin would chain perfectly with the next item, allow it.
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            penalty -= 30.0;
        }
        let _ = dead_elsewhere;
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no future typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual > 0 {
        // usable window: if next item fits into the post residual, big reward
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 14.0;
        } else if next_item_size > post_residual {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
        if post_residual <= 5 {
            score -= 10.0; // near-perfect fill, definitely use it
        }
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64;
        // Base cost of opening a new bin, higher early when bins are scarce.
        score += 30.0 + 8.0 * open_pressure.sqrt() - 10.0 * progress;
        // If item is large relative to capacity, opening fresh is more acceptable.
        score -= 0.25 * item_size as f64;
        // If mean residual across open bins is large, we should use open bins instead.
        score += 0.6 * mean_residual;
    } else {
        // Mild preference to keep residual near mean (balanced bins).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 12.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Small penalty for leaving residuals in the awkward 60-90 range that rarely fill.
    if post_residual >= 60 && post_residual <= 90 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    // Base: quadratic waste penalty (non-linear coupling with stream progress).
    let mut score = x * x * (1.0 + 2.0 * progress) * cap;

    // Smooth interaction: waste hurts more when many bins are open (fragmentation risk).
    let open_f = open_bins_count as f64;
    score += x * (1.0 - x) * open_f * 4.0;

    // Reward tight fits: small post_residual gets a subtraction, stronger early.
    score -= (1.0 - x) * (1.0 - x) * (item_size as f64 / cap) * (1.5 - progress);

    // Coupling with mean residual: prefer bins whose post residual aligns with fleet average.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 10.0 * (0.5 + progress);

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let gap = (pr - nx) / cap;
            score -= (1.0 - gap) * (1.0 - gap) * 20.0;
        } else {
            // Next item won't fit here; penalize slightly to prefer bins leaving usable room.
            score += (nx - pr) / cap * 8.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: heavy reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - x);
    }

    // New-bin candidate: neutral baseline with mild late-stream penalty so we
    // consolidate into open bins as the stream matures, unless fit is perfect.
    if bin_residual == bin_capacity {
        score = 0.5 * cap * (1.0 + progress) - (1.0 - x) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit base already: lower post_residual wins. Add harmonic-class bonuses.

    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of post_residual: small residues are "usable" dead space
    // if a future item of that size class exists. Classify residue by mod classes.
    let r = post_residual;
    // Class A: residue divisible by 10 (typical item granularity) -> less dead.
    if r % 10 == 0 {
        score -= 5.0;
    }
    // Class B: residue in a "tight" band 1..=5 is nearly dead -> penalize mildly.
    if r > 0 && r <= 5 {
        score += 8.0;
    }
    // Class C: residue that exactly matches a plausible next-item size class
    // (integer division thresholds) is valuable.
    let next_class = if next_item_size == 0 { 0 } else { next_item_size };
    if r >= next_class && next_class > 0 && (r - next_class) <= 5 {
        score -= 40.0; // residue can host the lookahead item almost perfectly
    } else if next_class > 0 && r < next_class && r > 0 {
        score += 12.0; // residue too small for lookahead -> dead-space risk
    }

    // Integer-division threshold on residual fraction of capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.05 {
        score += 3.0; // nearly full bin: fine, but tiny crumbs are dead space
    } else if frac > 0.5 {
        score -= 2.0; // keeping large residual is flexible
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    // or the lookahead pairs better with a fresh bin.
    if bin_residual == bin_capacity {
        // default new-bin cost: slightly worse than a decent fit
        score = bin_capacity as f64 + 10.0;
        if post_residual == 0 {
            score = -1000.0; // impossible here, but keep consistent
        }
        if fitting_bins_count == 0 {
            score = -500.0; // must open a bin
        }
        // If item + lookahead > capacity and no bin fits both, fresh bin is fine.
        if item_size as u64 + next_item_size as u64 > bin_capacity as u64 {
            score -= 20.0;
        }
        // Early in stream, opening bins is cheap (many items remain).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // Many open bins with high mean residual: reuse is preferable.
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 20.0;
        }
    }

    // Slight preference to consolidate when many bins are open.
    score -= 0.5 * open_bins_count as f64 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: residuals too small to ever be useful (below min item size 1..100 unknown, use conservative thresholds)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable gap
    } else if post_residual < 25 {
        score += 18.0; // risky small gap
    }

    // Reward tight fits
    score -= (bin_capacity - post_residual) as f64 * 0.35;

    // Open-bin pressure: prefer reusing bins when many are open
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.2;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // dead space relative to the known next item
    }

    // New-bin candidate: make it moderately attractive only when current fit is bad
    if bin_residual == bin_capacity {
        score += 5.0; // slight default bias toward reuse of open bins
        if post_residual > 60 { score -= 10.0; } // big residual left -> fine to open
    }

    // Mean residual coupling: avoid dumping into already-loose bins when mean is high
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.15;
    }

    // Progress: tighten packing as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.1 + 0.25 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead matching.
    // Reward when the post residual exactly (or nearly) matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_reward = (bin_capacity as f64 - gap) * 0.9;
        score -= match_reward;
        // Perfect chain: item exactly fills bin, next item exactly fills remainder.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize residuals that neither fit the next item nor are near zero.
        if post_residual > 0 && (post_residual as u64) < (next_item_size as u64) {
            score += 6.0; // dead space relative to lookahead
        }
    } else {
        // Last item: strongly prefer tightest fill.
        score -= 15.0;
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average.
    let resid_f = post_residual as f64;
    score += (resid_f - mean_residual) * 0.35;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins are open
    // or a decent fit exists; relax penalty late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 30.0 + 4.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            new_bin_penalty += 12.0;
        }
        // Perfect 2-item packing into a fresh bin (item + next == capacity) is great.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            new_bin_penalty -= 45.0;
        }
        new_bin_penalty *= 1.0 - 0.25 * progress;
        score += new_bin_penalty;
    }

    // Mild preference for tight fits overall (waste minimization).
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tight * tight;

    // Penalize dead space that cannot fit typical future items.
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.5 {
        score += 6.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 4.0;
        }
        // Perfect pair: item + next item exactly fills residual.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Many open bins: prefer consolidating into existing space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.05 * pressure * (1.0 - progress);

    // New-bin candidate: penalize opening a bin unless current fit is bad
    // or residual is nearly full (would waste this bin anyway).
    if bin_residual == bin_capacity {
        let bad_fit = (post_residual as f64) > bin_capacity as f64 * 0.6;
        let no_alternative = fitting_bins_count == 0;
        if bad_fit && !no_alternative {
            score += 15.0;
        } else {
            score -= 3.0;
        }
    }

    // Mild preference for bins with above-average residual when late in stream.
    if (bin_residual as f64) > mean_residual && progress > 0.5 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: quadratic penalty on wasted space, modulated by stream progress.
    // Late in the stream, tight fits matter more -> waste penalized harder.
    let mut score = pr * (1.0 + 1.5 * progress * progress);

    // Smooth non-linear coupling: prefer residuals that are either near-zero
    // (perfect fill) or large enough to be reusable. The function
    // sin(pi * x) peaks at x = 0.5 (worst case: half-empty bin).
    score += 12.0 * (std::f64::consts::PI * x).sin() * (0.5 + 0.5 * progress);

    // Lookahead coupling: reward residuals that can still host the next item,
    // scaled by how much of the bin that would consume (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let reuse = 1.0 - (pr - nx) / cap; // tightness of the follow-up fit
            score -= 8.0 * reuse * (1.0 - progress);
        } else {
            // next item cannot fit here: penalize proportionally to overshoot
            score += 3.0 * ((nx - pr) / cap) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin, especially early/mid stream.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate (empty bin): neutral-ish baseline, slightly penalized so
    // we only open new bins when existing fits are genuinely bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress - 0.5 * mean_residual * progress;
    } else {
        // Prefer bins whose residual is closest below the mean (balance load)
        score += 0.3 * (mean_residual - pr).abs();
    }

    // Mild tie-break: favor filling bins among many open bins.
    score += 0.1 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 buckets (capacity 100 -> classes of 10)
    let post_class = (post_residual % 10) as f64;
    score += post_class * 0.8; // dead space not aligned to decade is wasted

    // Perfect / near-perfect fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Integer-division threshold: small residual slots are only useful for tiny next items
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here: reward proportional to how snugly
            let snug = (post_residual - next_item_size) as f64;
            score -= 15.0 + 10.0 * (1.0 - snug / bin_capacity as f64);
            // harmonic coupling: next item size divisible by 10 aligns well
            if next_item_size % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // residual becomes dead space for the lookahead item
            score += 10.0 + (next_item_size as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // base penalty so we prefer open bins; relax as stream progresses
        score += 18.0 - 8.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        } else {
            // penalize more if some open bin achieves a tight fit
            let best_possible = (bin_capacity - item_size) as f64;
            if best_possible <= 10.0 {
                score += 40.0;
            }
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Coupling with mean residual: prefer bins whose residual is below mean (tighter packing)
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.25;

    // Reward filling large fraction of the bin (capacity-fraction coupling)
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 8.0;

    // Harmonic modulo logic on item size classes
    let item_class = item_size % 20;
    if item_class == 0 {
        score -= 3.0; // large aligned items pack well anywhere
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps left over are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bins pressure: discourage scattering when many bins are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if the item is large relative to
    // the bin and would leave a well-structured gap, or no good fit exists.
    if bin_residual == bin_capacity {
        score += 25.0; // default: prefer existing bins
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.6 {
            score -= 45.0 * fill_ratio; // large items start fresh bins cheaply
        }
        if next_item_size > 0 && next_item_size as f64 > post_residual as f64 {
            score += 10.0; // lookahead won't fit the fresh gap either
        }
    }

    // Lookahead synergy: reward if the next item fits the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Progress-based tightening: late in the stream, avoid leaving gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    // Deviation from mean residual: prefer bins whose residual is close to item needs.
    score += (bin_residual as f64 - item_size as f64 - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
