    if bin_residual == bin_capacity {
        score += 60.0 + 0.5 * item_size as f64;
    }

    // Slight penalty for spreading across too many open bins.
    score += 0.2 * open_bins_count as f64;

    // Early in the stream, be a bit more willing to open bins (better structure).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity && progress < 0.3 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
