    // Lookahead: penalize bins whose leftover can't host the next item,
    // reward bins whose leftover can host it (keeps a useful niche).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 0.15 * (post_residual as f64) * ((next_item_size - post_residual) as f64).sqrt();
        }
    }

    // Dead-space penalty: residuals too small for the smallest item are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Compare against global mean residual: prefer bins that are already
    // "behind" (less residual than average) to balance load.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: make opening a new bin costly unless
    // no open bin fits well (poor fit everywhere -> open fresh bin).
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0 || post_residual > 30;
        if poor_fit {
            score -= 20.0;
        } else {
            score += 30.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Time horizon: early in the stream, be frugal with new bins;
    // late in the stream, prioritize tightness over consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    } else {
        score -= 6.0 * progress * tightness;
    }

    // Mild pressure to prefer bins with high current residual (fill fuller bins first)
    // scaled by how many bins are open (consolidation matters more with many bins).
    score += 0.05 * (bin_residual as f64) * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer tight fits, with non-linear (quadratic/cubic) shaping of dead space.
    let mut score = post + 40.0 * post_norm * post_norm + 30.0 * post_norm * post_norm * post_norm;

    // Smooth coupling: as the stream progresses, waste becomes costlier.
    score *= 1.0 + 0.8 * progress * (1.0 - progress) * 0.5 + 1.2 * progress * progress;

    // Penalize bins whose residual is far from the mean (fragmentation signal).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits in post_residual (smooth soft-min style).
    if next_item_size > 0 {
        let fits_next = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        let gap = ((post_residual as i64 - next_item_size as i64).unsigned_abs()) as f64 / cap;
        score -= 18.0 * fits_next * (1.0 - gap * gap);
        // Penalize leaving a residual just barely below next item size (bad dead space).
        let near = (-gap + 0.2).max(0.0);
        score += 22.0 * (1.0 - fits_next) * (near * 5.0).min(1.0) * (1.0 - progress);
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - post_norm);

    // New-bin candidate: smooth penalty unless residual savings justify it.
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - progress) - 10.0 * (fitting_bins_count as f64).recip();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: bins whose residual falls into small
    // residue classes (dead space) are penalized quadratically.
    let pr = post_residual;
    let class = match pr {
        0 => 0.0,                    // perfect fill
        1..=10 => 1.0,               // near-perfect sliver
        11..=25 => 2.0,
        26..=50 => 3.0,
        _ => 4.0,                    // large usable residual
    };
    score += class * class * 2.5;

    // Reward exact/near-exact fits strongly.
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 10 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item can fit into the post-residual,
    // this placement chains nicely; subtract proportional to the tightness.
    if next_item_size > 0 && next_item_size <= pr {
        let tight = (pr - next_item_size) as f64;
        score -= 18.0 * (1.0 - tight / cap);
    } else if next_item_size > pr && pr > 0 {
        // next item won't fit here: leftover becomes riskier dead space
        score += 6.0 * (pr as f64 / cap);
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // many options: mildly prefer tighter fits via post_residual (already base)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only if residuals across open bins
        // are large (fragmented) or many bins already exist.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / cap).max(0.0);
        // Penalize new bin when open bins are compact and few.
        score += 30.0 - 25.0 * fragmentation - (open_bins_count as f64).min(20.0) * 0.8 - 10.0 * progress;
        // But if item is huge relative to typical residual, new bin is fine.
        if (item_size as f64) > mean_residual {
            score -= 12.0;
        }
    }

    // Small harmonic bonus for residual divisible by common item classes.
    if pr % 10 == 0 && pr > 0 {
        score -= 5.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Very tight fit reward: leaving <= small gap but zero is best.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Open-bin pressure: with many open bins, discourage spreading; favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += 4.0 * pressure;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin fits well
    // (i.e., item barely fits anywhere) or the stream is early and future items may need a fresh bin.
    if bin_residual == bin_capacity {
        // Default: discourage opening a new bin when one exists that fits.
        score += 30.0;
        // But if this bin is the only fitting option (fitting_bins_count==1 counts the new bin too),
        // and existing residuals are small, opening fresh is fine.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 25.0;
        }
        // Late in the stream with many bins, avoid proliferation.
        if progress > 0.7 {
            score += 20.0 * progress;
        }
    }

    // Lookahead: if the next item could exactly use the post-residual, reward leaving that gap.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize if post-residual is too small for the next item (dead space relative to lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Mild preference toward bins whose residual is already below mean (consolidating fragmentation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.11;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual, the better.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Penalize creating dead space that cannot fit any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: penalize if placing here blocks the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size && next_item_size <= bin_residual {
            score += 30.0; // this placement kills the only fit for next item here
        } else if post_residual >= next_item_size {
            score -= 10.0; // keeps chain-compatibility
        }
        // Reward exact chain: post_residual equals next item size
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: mildly discourage opening new bins unless
    // current fits are poor or many bins are open with large residuals.
    if bin_residual == bin_capacity {
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let dispersion = (mean_residual - post_residual as f64).abs();
        score += 45.0
            - 20.0 * poor_fits
            + 5.0 * (open_bins_count as f64).sqrt()
            - dispersion * 0.3;
        // Early in the stream, opening bins is cheaper (future flexibility).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
    }

    // Global balance: prefer bins whose residual deviates from mean toward
    // consolidation (fill below-average-residual bins first).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Late-stream pressure: near the end, prefer minimizing bin count hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - tightness);

    // Prefer filling bins that are already heavily loaded (fewer partially
    // filled bins left dangling).
    score -= 0.1 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, prefer tight fills (low post_residual). Later, tolerate slack.
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Smooth cubic interaction: penalize mid-range dead space more as stream advances.
    score += 12.0 * norm_pr * (1.0 - norm_pr) * (0.5 + progress);

    // Reward good utilization of the item relative to residual.
    score -= 6.0 * norm_item * (1.0 - progress);

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Slight penalty when bin residual is far from mean residual (imbalance).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        let nd = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 8.0 * (1.0 - nd / cap) * (1.0 - progress);
    }

    // New-bin candidate: mild penalty so it only wins when open bins are poor.
    if bin_residual == bin_capacity {
        score += 4.0 + 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity fraction band does it fall into?
    let item_class = item_size / (bin_capacity / 4); // 0: tiny, 1: small, 2: medium, 3: large
    let next_class = if next_item_size == 0 { 0 } else { next_item_size / (bin_capacity / 4) };

    // Reward tight fits: post_residual near 0 is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= bin_capacity / 10 {
        score -= 20.0;
    } else if post_residual <= bin_capacity / 4 {
        score -= 8.0;
    } else {
        // Penalize leaving large awkward gaps; dead space worse if small item caused it.
        score += (post_residual as f64) * 0.15;
        if item_class == 0 {
            score += 10.0; // tiny item in a big gap wastes the bin
        }
    }

    // Harmonic pairing: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0;
        } else if gap <= bin_capacity / 10 {
            score -= 25.0;
        } else {
            score -= 5.0;
        }
        // Complementary harmonic classes (small follows large) pair well.
        if next_class < item_class {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow here; penalize unless we're near the end.
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_residual <= bin_capacity / 4 {
            score -= 10.0;
        }
    } else if fitting_bins_count > 3 {
        // Many options: be pickier, prefer the truly best fit.
        score += post_residual as f64 * 0.1;
    }

    // Modulo threshold on post_residual: multiples of 5 leave more reusable gaps.
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // New-bin candidate logic: only open a new bin if current bins are fragmented
    // or this is a large item with poor fits available.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - (bin_residual as f64)).abs();
        // Fresh bin is attractive for large items when mean residual is small.
        if item_class >= 3 && mean_residual < (item_size as f64) {
            score -= 25.0;
        } else if mean_residual < bin_capacity as f64 * 0.15 {
            // All bins nearly full: opening fresh is fine.
            score -= 10.0;
        } else if item_class == 0 {
            // Never open a new bin for a tiny item.
            score += 60.0;
        } else {
            score += 15.0 + fragmentation * 0.3;
        }
        // Early stream: slight preference for packing into existing bins.
        if progress < 0.2 {
            score += 10.0;
        }
    }

    // Mild pressure against accumulating too many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (size 1..100 unknown, so treat < 10 as dead) are toxic.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        // Larger leftovers are fine; mildly reward keeping usable space.
        score -= 5.0;
    }

    // Reward exact/near-exact fills strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tightness reward: fraction of residual consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance pressure: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.3 * post_residual as f64;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins becomes more costly.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin is attractive only when
    // no open bin offers a decent fit, or when the fit here would create
    // dead space while the next item could use this residual better.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress
        // (late in stream, prefer reusing open bins).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 70.0 + 40.0 * progress;

        // If the current bin would leave a gap exactly matching the next
        // item, opening a fresh bin is wasteful.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 30.0;
        }
        // If this bin is the last chance and the fit is bad, allow new bin.
        if fitting_bins_count == 1 && post_residual < 10 {
            score -= 45.0;
        }
    }

    // Lookahead: if placing here leaves residual that perfectly fits the
    // next item, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        // Would leave a dead sliver after the next item lands here.
        score += 12.0;
    }

    // Slight preference for bins tighter than average (below-mean residual
    // means this is one of the fullest bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits.
    score += 0.35 * (bin_residual as f64 - item_size as f64).abs().min(40.0);

    // 2-step lookahead: reward if next item fits the post residual exactly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another residual: penalize leftover dead space
            score += 0.15 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here: penalize small unusable residuals
            let waste = post_residual as f64;
            if waste < next_item_size as f64 {
                score += 0.5 * (next_item_size as f64 - waste).min(30.0);
            }
        }
    } else {
        // last item: prefer minimal post residual
        score += 0.4 * post_residual as f64;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Early in the stream, encourage consolidation into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 {
        score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    }

    // Penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 6.0; // new bin can host the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Strong reward for exact/near-exact fill.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: penalize if next item cannot fit in post_residual (dead space for k=2),
    // reward if it fits nicely.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
            // bonus if next item almost exactly fills remainder too
            let gap2 = post_residual as f64 - next_item_size as f64;
            score -= 10.0 * (1.0 - gap2 / bin_capacity as f64);
        } else {
            score += 8.0 + 0.2 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize spreading across too many open bins when residuals are large.
    if open_bins_count > 2 {
        score += 0.5 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Reward bins whose residual is below the mean (denser bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, be conservative (prefer filling existing bins);
    // late in stream, exactness matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - waste / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual == bin_capacity means empty bin, waste = capacity).
    if bin_residual == bin_capacity {
        let poor_alternatives = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1);
        if poor_alternatives {
            score -= 20.0;
        } else {
            score += 45.0 + 0.5 * mean_residual;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: post residual, smoothly discounted by stream progress
    // (later in the stream, dead space matters relatively more per bin,
    // but the marginal value of residual decays non-linearly).
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear polynomial coupling of post_residual with progress:
    // penalize large residuals late, reward tight fits early.
    let x = pr / cap; // normalized post residual in [0,1]
    score += 30.0 * x * x * (0.5 + progress);
    score -= 20.0 * x * (1.0 - progress) * (1.0 - progress);

    // Dead-space penalty: residuals too small for the smallest items
    // (<= 10) are effectively wasted; smooth quadratic in waste.
    if pr > 0.0 && pr < 10.0 {
        let waste = 10.0 - pr;
        score += waste * waste * (1.0 + progress);
    }

    // Lookahead coupling: reward residual that still fits next item,
    // penalize when it does not (smooth polynomial in the gap).
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 8.0 * (gap / cap) * (1.0 - progress);
        } else {
            score += 6.0 * (-gap / cap) * (1.0 - progress) * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless residual is huge).
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - x) * (1.0 - progress);
    }

    // Mild preference for consolidating into bins below mean residual
    // (keeps big residuals available for large items).
    score += 0.05 * (mean_residual - bin_residual as f64).abs() * progress;

    // Slight penalty for proliferation of open bins, smoothed.
    score += 0.3 * (open_bins_count as f64).ln() * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by capacity fraction.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let quarter = (bin_capacity / 4) as f64;

    // Dead-space penalty: residuals in the "unusable sliver" classes are heavily penalized.
    // Class boundaries: (0,10], (10,25], (25,50], (50,100].
    if post > 0.0 && post <= 10.0 {
        score += 60.0; // near-perfect fit, but tiny slivers can rarely be reused
    } else if post <= quarter {
        score += 25.0; // quarter-class leftover: moderately reusable
    } else if post <= cap / 2.0 {
        score -= 10.0; // half-class leftover: good reuse potential
    } else {
        score -= 20.0; // large leftover: very reusable
    }

    // Integer-division harmonic class: how well does post_residual align with typical item classes?
    // Items 1..100 -> useful chunk sizes ~ multiples of 10/20.
    let harmonic = post_residual / 10; // integer division class 0..10
    score -= (harmonic as f64) * 2.0;  // reward coarser (larger) residual classes

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chained fit
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / cap); // tighter chained fits favored
        } else {
            score += 15.0; // next item won't fit here: bin becomes dead for lookahead
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: discourage opening a new bin when decent fits exist,
    // but encourage it when residual classes are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += 40.0 - 35.0 * fragmentation; // open new bins only when open bins are full-ish
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    }

    // Progress modulation: late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit: maximal reward.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Reward filling a large fraction of the bin's residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += 3.0 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Lookahead: reward if the next item fits exactly into the post residual,
    // penalize if post residual is too small for next item (dead space guaranteed).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size > post_residual {
            score += 25.0 * (post_residual as f64 / 100.0);
        } else {
            // next item fits, mild preference for leaving useful room
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / 100.0);
        }
    }

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps bin states balanced) unless it is a near-perfect fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev * (1.0 - fill_ratio);

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 30.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        if post_residual > 70 {
            score -= 15.0; // a fresh bin is fine for large items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 0.6 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining: bin fully consumed by next item
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover after next item, scaled by how big the dead space is
            score += 0.35 * slack;
            // extra reward if next item fits nearly perfectly
            if slack <= 10.0 {
                score -= 12.0;
            }
        } else {
            // next item cannot follow into this bin: penalize proportionally
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: prefer bins that absorb the item without
    // inflating the average residual profile too much.
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (post_f - mean_residual) / mean_residual;
        score += 3.0 * rel;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the stream is early or all existing bins are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / (bin_capacity as f64);
        // penalize new bins more as stream progresses and when fragmentation is low
        score += 8.0 + 25.0 * (1.0 - progress) + 20.0 * (1.0 - fragmentation);
        // if next item is large and no open bin chains well, allow new bin sometimes
        if next_item_size >= item_size && post_f == 0.0 {
            score -= 10.0;
        }
    }

    // Mild penalty for leaving tiny unusable slivers (< 10, smallest item size).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: prefer bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    } else {
        // Last item: just minimize waste
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when the item fits poorly anywhere
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        // Base penalty for opening a new bin, softened when item is large
        score += 20.0 - 15.0 * fit_ratio;
        // If many bins already fit the item, discourage new bin more
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64).min(4.0);
        }
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
        // If open bins are mostly full (mean residual low), new bin is fine
        score -= (mean_residual / bin_capacity as f64) * 6.0;
    } else {
        // Slight preference for fuller bins among open candidates
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 6.0 * fill;
        // Mild penalty for spreading across many open bins
        score += 0.15 * open_bins_count as f64;
    }

    // Global balance: prefer bins below mean residual slightly (even out)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: penalize wasted space, non-linearly (quadratic waste growth).
    let mut score = post * post / cap;

    // Smooth interaction: waste matters more as the stream progresses.
    score += post * (0.5 + 1.5 * progress);

    // Cubic coupling of residual with progress: late-stream tight fits strongly favored.
    let norm_post = post / cap;
    score += 40.0 * norm_post * norm_post * norm_post * (0.3 + progress);

    // Reward bins whose residual is close to the item (smooth Gaussian-like fit term).
    let fit_gap = (bin_residual as f64 - item) / cap;
    score -= 25.0 * (-(fit_gap * fit_gap) * 8.0).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward leaving useful space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = post - nxt;
        if diff >= 0.0 {
            score -= 12.0 * (-(diff / cap) * (-(diff / cap)) * 10.0).exp();
        } else {
            score += 6.0 * (-diff / cap);
        }
    }

    // New-bin candidate: penalize opening a new bin, more so mid/late stream,
    // unless residual is large relative to typical open-bin residuals.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += 15.0 + 35.0 * progress + 0.1 * open_bins_count as f64;
        // Allow new bin when it would create a very tight fit anyway (rare large items).
        score -= 20.0 * (-(norm_post * norm_post) * 6.0).exp();
    }

    // Slight penalty for bins far from mean residual (keep residuals homogeneous).
    score += 0.05 * ((post - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic class logic: partition residual space into harmonic bands
    // (capacity fractions 1/2, 1/3, 1/4) and reward leaving residuals that
    // fall on useful class boundaries for future items.
    let cap_u = bin_capacity;
    for (div, bonus) in [(2u32, 18.0), (3, 12.0), (4, 8.0)] {
        let boundary = cap_u / div;
        if post_residual == boundary {
            score -= bonus;
        } else if post_residual > boundary {
            // usable residual above a class boundary is more valuable
            score -= (post_residual - boundary) as f64 * 0.05;
        }
    }

    // Penalize dead space: residuals too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead coupling: if next item fits exactly into the post residual,
    // strongly favor this bin (perfect pair).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        score += 35.0;
        if mean_residual > cap * 0.35 {
            score -= mean_residual * 0.3;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer filling bins far below the mean residual (worst-fit avoidance)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.15;

    // Mild pressure to keep the number of open bins low
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post residual, this placement is extra valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones over new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * 1.5 * (0.5 + progress);

    // New-bin candidate: make an empty bin unattractive unless current bin fits poorly.
    if bin_residual == bin_capacity {
        score += 40.0 + mean_residual * 0.3;
    }

    // Prefer bins tighter than average.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), with mild non-linearity
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits exactly or well -> strong reward
            score -= 30.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // Next item won't fit here; penalize leaving dead space the next item can't use
            score += 0.5 * gap;
        }
    } else {
        // Last item: only the immediate fit matters
        score -= 5.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge relative to capacity
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 60.0 - 50.0 * fill_ratio;
        // Open a new bin if current bin fit would be very poor (large dead space)
        if post_residual > bin_capacity / 2 && next_item_size > post_residual {
            score -= 25.0;
        }
    }

    // Early in stream: be slightly more willing to open bins for good structure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: penalize if the next item would NOT fit the remaining space
    // (wasting this bin's potential); reward if it would chain nicely.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 6.0;
        }
        // Exact chain fit is excellent.
        if next_item_size == post_residual {
            score -= 25.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize creating dead space that no plausible item can fill.
    // Items are >= 1, but small residuals (< smallest typical item) are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Global state: when many bins are open with high mean residual,
    // discourage spreading; when mean residual is low, filling this bin is good.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.15 * (open_bins_count as f64 - 5.0).max(0.0);
    score -= 0.10 * mean_residual * (1.0 - progress);

    // New-bin candidate handling: an empty bin has post_residual == bin_capacity.
    // Make it costly unless the item fits poorly everywhere (handled by the
    // last-chance bonus on real bins) or the item is large.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 25.0 * large_item;
        // Early in the stream, opening bins is cheaper.
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Non-linear waste penalty: quadratic coupling of post-residual with stream progress
    score += 6.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post-residual) with a smooth cubic bonus
    score -= 8.0 * (1.0 - norm_pr).powi(3) * norm_item;

    // Lookahead coupling: reward residual that smoothly matches next item size
    if next_item_size > 0 {
        let gap = (norm_pr - norm_next).abs();
        score -= 5.0 * (-gap * 4.0).exp();
    }

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Penalize bins far below mean residual (smooth interaction)
    score += 2.0 * ((mean_residual - pr) / cap).max(0.0) * (1.0 + open_bins_count as f64).ln();

    // Mild pressure to reuse bins as stream progresses (favor open bins over new bin)
    score -= progress * 3.0 * (bin_residual != bin_capacity) as i32 as f64;

    // New-bin candidate: smooth penalty that decays with progress
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) + 2.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Integer-division thresholds on post_residual (harmonic classes of C/16).
    let class = post_residual / (bin_capacity / 16);
    score += class as f64 * 1.7;

    // Reward tight fits: post_residual in the "harmonic sweet spots" 0, C/4, C/2, 3C/4.
    for k in 0..=4u32 {
        let spot = bin_capacity * k / 4;
        if post_residual == spot {
            score -= 22.0;
        }
    }

    // Penalize residuals that no plausible item can fill (dead space).
    // Items are 1..=100, so a residual of exactly 0 is perfect; small odd residuals are dead.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        } else {
            // next item cannot use this residual at all: penalize proportional waste
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // Harmonic pairing: next_item shares a divisor class with post_residual
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when current residuals are fragmented.
    if bin_residual == bin_capacity {
        // Base bias so new bins are chosen only when open bins are poor.
        score = 55.0 + mean_residual * 0.3 - (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin can host next item perfectly after this one
            if next_item_size == bin_capacity - item_size {
                score -= 25.0;
            }
        }
    }

    // Progress pressure: late in the stream, avoid scattering small residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 - progress * post_residual as f64 * 0.05;

    // Mean-residual coupling: if this bin is far below mean residual, it's already fragmented.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0; // unreachable in practice, but guards the contract
    }
    // Dead space = residual too small for any plausible future item.
    let dead_threshold = 10u32.min(bin_residual);
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 8.0;
    }

    // Reward tight fits (small waste relative to item size).
    score -= (item_size as f64) * 0.35;

    // Exact fit is perfect: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: discourage proliferation of many open bins,
    // but soften when the stream is near its end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).powf(1.3) * (1.0 - 0.6 * progress) * 1.2;

    // New-bin candidate handling: only attractive when the current item
    // would leave a large gap in an existing bin, or bins are congested.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a fresh bin.
        score += 25.0 + open_bins_count as f64 * 2.0;
        // Lookahead synergy: a fresh bin is great if the next item is big.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 18.0;
        }
        // If the item barely fits an existing residual elsewhere, new bin
        // wastes capacity; make fresh bin less appealing when item is small.
        if item_size < 30 {
            score += 20.0;
        }
    } else {
        // Lookahead: penalize placing item here if next item could have
        // used this residual better (blocking penalty).
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual
            && next_item_size <= bin_residual {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // Reward bins whose residual deviates favorably from the mean
        // (prefer filling below-average-residual bins, i.e. tighter ones).
        if (bin_residual as f64) < mean_residual {
            score -= (mean_residual - bin_residual as f64) * 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is already good; amplify it.
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, strongly reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - gap / bin_capacity as f64);
    }

    // Penalize post-residuals that are too small for the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Compare residual against mean residual: prefer bins that keep the mean
    // residual balanced (avoid leaving one bin very full and others empty).
    score += 0.5 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // relative to the item or there are many bins that fit (poor fits elsewhere).
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size >= 60 {
            score -= 20.0;
        }
        if fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    // Late in the stream: consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residual dead space nonlinearly.
    let pr = post_residual as f64;
    score += 0.02 * pr * pr / bin_capacity as f64;

    // Reward tight fits.
    score -= 8.0 * (item_size as f64 / bin_residual as f64);

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        let nd = next_item_size as f64;
        if (nd as u32) == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (nd / post_residual as f64);
        } else {
            // Next item won't fit here; penalize leaving medium dead space.
            score += 5.0 * (1.0 - (post_residual as f64 / nd).min(1.0));
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins with below-average residual (fill emptier bins less).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Time horizon: early on, be more willing to open new bins (favor compacting later).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - pr / bin_capacity as f64);

    // New-bin candidate: prefer it only when post-residual is huge (fresh bin) and few bins open.
    if bin_residual == bin_capacity {
        score += 12.0 - 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) - norm_pr * (0.5 + 1.5 * progress * (1.0 - progress));
    score += 20.0 * poly;

    // Reward tight fits, stronger late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual
    let dev = pr - mean_residual;
    score += 0.3 * dev * dev / (cap * cap) * 100.0;

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: favor bins whose post_residual can host the next item
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0 * (1.0 - (next_item_size as f64 - pr) / cap);
        }
    }

    // Mild penalty for many open bins to encourage consolidation early
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize slightly unless residual is very large
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in [0,9] is nearly unusable
    // (items >= 10), so penalize it heavily; [10,19] is a "harmonic class"
    // that only fits tiny items, etc. Use integer division thresholds.
    let dead_class = post_residual / 10; // 0 => dead space < 10 (unusable)
    if post_residual > 0 {
        score += match dead_class {
            0 => 60.0,                      // unusable sliver
            1 => 25.0,                      // only fits items 10..19
            2 => 10.0,                      // fits 10..29
            3 => 3.0,
            _ => 0.0,
        };
    } else {
        // Perfect fill: strong reward
        score -= 80.0;
    }

    // Modulo-10 harmonic residue: residuals that are exact multiples of 10
    // align with the item grid; reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0;
        } else if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            score += (next_post as f64) * 0.5;
            if next_post < 10 {
                score += 15.0; // would create new dead space
            }
        } else {
            // next item won't fit here regardless; slight reward for keeping
            // residual large enough to be generally useful
            score += (post_residual as f64) * 0.1;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has post_residual = capacity - item.
    // Prefer reusing open bins when their residual stays usable; prefer a new
    // bin when the current item would leave an unusable sliver in every open bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Neutral baseline, slightly above a decent fit so reuse wins ties,
        // but below bins that create dead space.
        score += 20.0;
        // If the item is large relative to capacity, a fresh bin is efficient.
        if item_size * 2 >= bin_capacity {
            score -= 15.0;
        }
    }

    // Stream progression: late in the stream, tighten up — prefer near-exact fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Mean-residual coupling: when open bins are generally full (low mean
    // residual), reusing is more valuable; when bins are half-empty, prefer
    // consolidating into fuller bins.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.2;

    // Penalize scattering across many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum plausible item size) are heavily penalized,
    // but a PERFECT fit (post_residual == 0) is rewarded strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual < 10 {
        // Unusable dead space: gap too small for any item.
        score += 60.0;
    } else if post_residual < 20 {
        // Marginal gap: only the smallest items could ever use it.
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Superlinear pressure on leftover space: large residuals are fine,
    // mid-size residuals waste capacity potential.
    let r = post_residual as f64;
    score += 0.015 * r * r * (1.0 - r / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, reward this placement heavily (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 180.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            // Next item would create dead space here; mild penalty.
            score += 15.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading into new
    // ones; with few open bins, opening a new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score += open_pressure * (0.5 + 0.5 * progress);

    // New-bin candidate (empty bin): default is a modest penalty so it is
    // chosen only when all open bins are poor fits or dead-space creating.
    if bin_residual == bin_capacity {
        score += 90.0 - 40.0 * progress;
        // If mean residual across open bins is tiny (bins nearly full),
        // opening a fresh bin becomes attractive.
        score -= (mean_residual / 10.0).min(50.0);
    }

    // Mild bonus for filling bins tighter than the current mean residual.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer minimal post_residual (already base score).

    // 2-step lookahead: strongly reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Perfect match for the next item: big bonus
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // If next item cannot fit anywhere else after this placement, slight penalty
        if post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Penalize dead space that is too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer fuller bins relative to mean residual
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Mild pressure to consolidate when many bins are open
    score += 0.3 * open_bins_count as f64;

    // Early in stream: slightly favor opening bins to build flexibility
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless item is large relative to capacity
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 60.0;
        score += 15.0 + progress * 30.0 - large_item_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squash small post_residuals harder.
    let frac = post_residual as f64 / bin_capacity as f64;
    score -= 25.0 * (1.0 - frac).powi(3);

    // Lookahead: if the next item fits exactly in the post residual, strong bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > bin_residual && post_residual < 10 {
            // next item cannot fit anywhere here anyway; small residual is fine
            score -= 5.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's a genuinely good deal
    // (item is large relative to capacity, or current bins are very full / fragmented).
    if bin_residual == bin_capacity {
        let mut newbin_penalty = 15.0;
        // Large items start fresh bins more readily.
        let large = item_size as f64 / bin_capacity as f64;
        if large > 0.6 {
            newbin_penalty -= 10.0 * (large - 0.6) / 0.4;
        }
        // If existing bins are quite full on average, opening a new bin is less wasteful.
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        if mean_fill > 0.7 {
            newbin_penalty -= 8.0 * (mean_fill - 0.7) / 0.3;
        }
        // Early in stream: keep bins open and flexible.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        newbin_penalty += 10.0 * (1.0 - progress);
        // If no other bin fits, opening is mandatory anyway.
        if fitting_bins_count == 0 {
            newbin_penalty -= 100.0;
        }
        score += newbin_penalty;
    }

    // Slight preference for bins with residual far below mean (consolidate emptier space).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Penalize leaving awkward residuals that few item sizes can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // dead space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, but weight grows non-linearly with progress
    let mut score = pr * (1.0 + 2.0 * progress * progress);

    // Smooth polynomial coupling of normalized post residual with progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress * 3.0;
    score += 15.0 * coupling;

    // Penalize dead space that can't fit the next item (smooth ramp)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 25.0 * gap * gap;
        // Reward leaving room for the next item
        let fit_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 6.0 * fit_next * (pr / cap);
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - norm_pr);
    }

    // Mild penalty when many bins are open and this placement fragments capacity
    let frag = norm_pr * (open_bins_count as f64).ln() / (1.0 + progress);
    score += 4.0 * frag;

    // New-bin candidate: encourage opening fresh bins early, discourage late
    let is_new = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += is_new * (20.0 * (1.0 - progress) - 10.0 * progress);

    // Tight fits rewarded via smooth quadratic
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes capture which
    // "resonant" leftover sizes are easily fillable by small items.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize dead space that is too small to fit typical items but wastes capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic classes: post_residual divisible by common small item sizes
    // (e.g. multiples of 10/20/25) are more reusable -> reward.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 30 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Reward if the lookahead item fits exactly into the post residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Fits, but leaves another residual: mild reward scaled by tightness.
        let tight = (post_residual - next_item_size) as f64;
        score -= 10.0 - 0.15 * tight;
    } else if next_item_size > 0 {
        // Next item won't fit here after placement: penalize proportionally.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current bins are poorly filled.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / cap) - (item_size as f64 / cap);
        // Open a new bin only when open bins have little usable residual.
        score += 55.0 - 60.0 * pressure.max(0.0);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late in the stream, prefer tighter packing (consolidate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - pr / cap);

    // Slight preference for bins below mean residual (balance spreading).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap below 10 (min item size) is pure waste -> large penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 3.0;
    }
    // "Awkward" gap band: too small for most items, big enough to tempt.
    if post_residual >= 10 && post_residual <= 20 {
        score += 12.0;
    }
    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the resulting residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 25.0;
        } else {
            score -= slack as f64 * 0.2;
        }
    }
    // Penalize if next item would leave this residual stranded.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + item_size as f64 * 0.1;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // prefer filling existing bins over opening new ones.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: make empty bins mildly unattractive unless the
    // item fits poorly everywhere (handled via the dead-space penalties).
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
    }

    // Slight preference for bins with residual close to mean (balance).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // post_residual can still host the next item: mild reward scaled by fit tightness
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 / (1.0 + slack / 10.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to lookahead: penalize proportionally
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.6;
    }

    // Zero post_residual is perfect closure
    if post_residual == 0 {
        score -= 40.0;
    }

    // Very small unusable residual is bad (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current fits are poor (large post_residual elsewhere)
    if bin_residual == bin_capacity {
        score += 35.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // fresh bin can host both current and next item compactly
            score -= 10.0;
        }
        // late in stream, prefer reusing open bins less aggressively
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Prefer bins tighter than the mean residual (good fits)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Slight preference for fewer open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose post-residual is small relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize dead space that cannot fit the next item (lookahead).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 12.0 + 0.5 * post_residual as f64;
        } else if post_residual >= next_item_size {
            // Bonus when post-residual nicely accommodates the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (-slack / 30.0).exp();
        }
    } else {
        // Last item: just minimize leftover.
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only when
    // open bins are fragmented (high mean residual) or the fit is poor.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 30.0 - 0.3 * open_bins_count as f64 - 0.1 * fragmentation;
    }

    // Time horizon: early in the stream, be more willing to open bins (spread items);
    // late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 6.0 * (post_residual as f64 / bin_capacity as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty when many bins are open to encourage consolidation.
    score += 0.15 * open_bins_count as f64;

    // Penalize bins far below mean residual (wasteful use of a full bin).
    score += 0.05 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: reward tight fits via non-linear polynomial of normalized post residual
    let mut score = norm_pr * norm_pr * (2.0 + 3.0 * progress) + norm_pr * (1.0 - progress);

    // Smooth coupling: penalty grows quadratically as post residual deviates from usable mid sizes
    let usable = (norm_pr - 0.2) * (norm_pr - 0.2);
    score += 2.5 * usable * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * progress;
    }

    // Scarcity pressure: when few fitting bins, mildly reward using open bins
    let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
    score -= 1.5 * scarcity;

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.8 * dev * (1.0 - progress) - 0.4 * dev * progress;

    // Lookahead: reward leaving space compatible with next item (smooth kernel)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).abs() / cap;
        score += 1.2 * gap * gap - 0.6 * (1.0 - gap);
    } else {
        // Last item: maximize fill
        score -= 1.0 * (1.0 - norm_pr);
    }

    // New-bin candidate: penalize opening new bins early, less as stream progresses
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) * (1.0 - progress) + 0.5;
        // but if current bin would leave awkward residue, opening fresh is fine
        if next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
            score -= 1.5 * progress;
        }
    }

    // Open bins count pressure: many open bins -> consolidate
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 tiers
    let r = post_residual % 10;
    // Residues 1..9 are "dead" slivers (nothing in 1..100 range may fit later);
    // residue 0 is perfectly harmonic.
    if post_residual > 0 && r != 0 {
        score += 8.0 + 0.5 * (10 - r) as f64; // penalize non-zero residues
    }
    if r == 0 && post_residual > 0 {
        score -= 4.0; // reward multiples of 10 (harmonic class)
    }

    // Integer-division thresholds on post_residual
    let q = post_residual / 10;
    score -= q as f64 * 0.3; // larger usable post_residual is mildly good

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0; // chain placement possible
            // harmonic match: post_residual % next_item_size small
            let m = post_residual % next_item_size;
            score -= (10 - m) as f64 * 0.4;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 3.0; // item would strand this residual
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost
    if bin_residual == bin_capacity {
        // early in stream, opening bins is cheap; later it is expensive
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 30.0 * progress;
        // opening a new bin is attractive if current item is huge and would
        // fragment an open bin badly
        if item_size as f64 > 0.6 * bin_capacity as f64 && post_residual < 20 {
            score -= 20.0;
        }
    } else {
        // prefer bins whose residual is close to the item (tight fit)
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * 5.0;
    }

    // Mild preference for bins below mean residual (use fragmented bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    }

    // Penalize wasting a very full bin's tiny residual on tiny items
    if bin_residual < 20 && item_size <= 10 && bin_residual != bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    } else {
        // Larger residuals are usable; mild reward scaled by fit quality.
        score -= (post_residual as f64 / bin_capacity as f64) * 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose residual matches next item (lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 / (1.0 + slack / 20.0);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // This placement creates a gap that can't fit the next item: penalize.
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when few bins open, less late in stream.
        score += 35.0 + 20.0 * (1.0 - progress) - 2.0 * open_bins_count as f64;
    } else {
        // Mild penalty per open bin to prefer reusing existing bins.
        score += 0.3 * open_bins_count as f64;
    }

    // Prefer bins tighter than the mean residual (compact bins first).
    score += (mean_residual - bin_residual as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are good: reward small post_residual.
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64);

    // 2-step lookahead: if the next item fits exactly in the post-residual,
    // this placement is ideal — heavily reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item fits: residual after two placements is what matters.
            let second_residual = post_residual - next_item_size;
            score -= 15.0 - 0.3 * second_residual as f64;
            if second_residual == 0 {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here; penalize leaving awkward gaps.
            let gap = next_item_size - post_residual;
            score += 0.4 * gap as f64;
        }
    }

    // Compare residual against mean residual of open bins.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when good fits exist elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * item_size as f64;
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score quadratically as post_residual -> 0.
    score -= 30.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: penalize if post_residual cannot host the next item (dead space),
    // reward if it can exactly or usefully.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 12.0 + 0.25 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Many fitting bins: mild penalty for wasting a versatile bin.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Time horizon: early in the stream, be conservative (prefer spreading);
    // late in the stream, pack tightly into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 15.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Compare against global mean residual: bins below mean residual are
    // already tight; prefer placing into them to consolidate.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: opening a new bin wastes the residual of this bin;
    // make empty-bin attractive only when this placement is very poor.
    if bin_residual == bin_capacity {
        score = (post_residual as f64) + 20.0
            + 10.0 * (1.0 - progress)
            + (open_bins_count as f64).sqrt() * 3.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Penalize bins whose residual is far larger than needed (fragmentation).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    if waste_ratio > 0.5 {
        score += 10.0 * (waste_ratio - 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening.
    let mut score = pr * (1.0 + 2.0 * norm_post * norm_post);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, keep bins flexible (penalize tiny residuals mildly);
    // later, pack tightly (reward small post_residual more strongly).
    let tightness = 1.0 - progress;
    score += tightness * 12.0 * norm_post * (1.0 - norm_post);
    score -= progress * 10.0 * norm_post * norm_post;

    // Dead-space penalty: residuals too small to fit typical future items.
    let dead = ((20.0 - pr) / 20.0).max(0.0);
    score += 8.0 * dead * dead;

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 6.0;
    } else {
        // Mild penalty for spreading across many candidate bins.
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 + 2.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 2.0 * (1.0 - (bin_residual as f64 - next_item_size as f64).abs() / cap);
    }

    // Crowd control: many open bins -> prefer consolidating into existing ones.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling: penalize bins far from the mean residual (fragmentation).
    score += 1.5 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: make empty bins attractive only when they beat poor fits,
    // otherwise slightly discourage opening bins early.
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) + item_size as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals that are multiples of
    // common item granules (10, 20, 25, 50) are more reusable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base tightness reward: quadratic in fill fraction placed.
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= 30.0 * fill * fill;

    // Reward post_residuals in "good" harmonic classes (divisible by 10 or 25).
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 {
        score -= 4.0;
    }
    // Penalize awkward small dead space via integer-division thresholds.
    let dead_class = post_residual / 10; // 0..=9 class
    match dead_class {
        0 => score += 18.0,           // nearly full: great, keep it
        1 => score += 2.0,            // tiny dead space is bad unless bin closes
        2 | 3 => score += 5.0,
        4 | 5 => score -= 2.0,        // mid residual still useful
        _ => score -= 1.0,
    }

    // Lookahead: if next item exactly fills post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits here too: mild reward proportional to its size class
            score -= (next_item_size as f64) * 0.15;
        } else {
            // next item cannot use this residual: penalize small leftovers more
            if post_residual < next_item_size {
                score += (1.0 - post / (next_item_size as f64)) * 4.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized, but less so early in the stream or
        // when many open bins already exist with poor residuals.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = (open_bins_count as f64) * 0.4;
        score += 20.0 + open_pressure - 10.0 * (1.0 - progress);
        // If the item is large relative to mean residual, new bin is better.
        if (item_size as f64) > mean_residual {
            score -= 8.0;
        }
        // Perfect class item on fresh bin: slight discount so big items go fresh.
        if item_size % 10 == 0 {
            score -= 3.0;
        }
    }

    // Coupling with mean residual: prefer bins whose residual deviates
    // favorably (smaller than mean) to consolidate fragmentation.
    score += 0.05 * (mean_residual - (bin_residual as f64)).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            // Tiny dead space: nearly worthless leftover.
            score += 60.0 * (10.0 - post_residual as f64);
        } else if post_residual < 20 {
            // Moderately small gap: still likely unusable for typical items.
            score += 25.0 * (20.0 - post_residual as f64) / 10.0;
        } else if post_residual < 35 {
            // Borderline zone: mild penalty proportional to gap.
            score += 8.0 * (35.0 - post_residual as f64) / 15.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 80.0;
    }

    // Reward placements that leave room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual cannot fit next item: slight penalty if gap is small.
        if post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another;
    // the empty-bin candidate gets penalized progressively.
    if bin_residual == bin_capacity {
        score += 30.0 + 4.0 * open_bins_count as f64;
    } else {
        // Favor consolidating into already-open bins when many are open.
        score -= 1.5 * open_bins_count as f64;
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (i.e., tighten the tightest bins first, keep loose bins flexible).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Early in the stream, be slightly more willing to open bins (future items unknown);
    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect two-step fit: post_residual exactly matches next item.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 60.0;
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 25.0;
        }
        // Penalize residual that can't hold the next item but is large (dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Reward tight fits relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Penalize leaving residual far below mean residual (fragmentation).
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let mut penalty = 40.0;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            penalty = 0.0;
        }
        // If mean residual is low (bins nearly full), a fresh bin is attractive.
        penalty -= 0.8 * mean_residual;
        score += penalty.max(-50.0);
    }

    // Slight preference to spread load early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post residual to punish large dead space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Extra penalty for dead space too small to ever fit the smallest item (size 1..~10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 5.0;
        } else {
            // next item won't fit here; slight penalty if we leave a big unusable gap
            if post_residual < next_item_size && post_residual > 0 {
                score += (next_item_size - post_residual) as f64 * 0.2;
            }
        }
    }

    // Last chance: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows slightly with number of open bins.
        score += 20.0 + (open_bins_count as f64).sqrt() * 3.0;
        // If the current bin fits the item well (post residual small), opening new bin is bad.
        if post_residual < 15 {
            score += 60.0;
        }
        // If mean residual across open bins is large, prefer existing bins.
        score += mean_residual * 0.3;
        // Early in stream, opening bins is cheaper (exploration); later, pack tighter.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 15.0;
    } else {
        // Existing bin: slight preference for fuller bins (smaller residual).
        score += (bin_residual as f64) * 0.1;
        // Favor bins with residual below the mean (relatively full bins).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Late in stream, be more conservative: penalize creating new slack.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + progress * (1.0 - norm_pr)) - progress * norm_pr * norm_pr;

    // Reward tight fits (small post_residual), more strongly later in the stream
    let mut score = pr * (1.0 + 0.5 * progress * (1.0 - norm_pr));

    // Penalize large dead space quadratically, scaled by progress
    score += 8.0 * progress * norm_pr * norm_pr * cap * 0.01;

    // Non-linear interaction: perfect fit bonus
    if post_residual == 0 {
        score -= 15.0 + 10.0 * progress;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: penalize if next item cannot fit the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr - nxt).abs() < 1.0 {
            score -= 6.0;
        } else if nxt > pr {
            score += 3.0 * (nxt - pr) / cap * 10.0;
        } else {
            score -= 2.0 * (1.0 - (pr - nxt) / cap);
        }
    }

    // Mild preference for fuller bins relative to mean residual
    score -= (mean_residual - pr) * 0.05 * (1.0 + progress);

    // New-bin candidate: keep it neutral-to-slightly-poor unless nothing fits well
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress) + poly * 2.0;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Small smoothing term from the polynomial coupling
    score += poly * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "usable slots"
    // (multiples of common item sizes 10, 20, 25, 50).
    let post = post_residual;
    if post == 0 {
        score -= 60.0; // perfect fit, best possible
    } else {
        let harmonic_bonus: f64 = if post % 50 == 0 {
            45.0
        } else if post % 25 == 0 {
            30.0
        } else if post % 20 == 0 {
            25.0
        } else if post % 10 == 0 {
            15.0
        } else {
            0.0
        };
        score -= harmonic_bonus;
        // Penalize dead space that nothing can use (post < 10 unusable for min item 1... keep generic)
        if post < 10 {
            score += 5.0;
        }
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // next item fits: reward, scaled by how well it fills (small waste after next)
            let next_post = post - next_item_size;
            let tight = 1.0 - (next_post as f64) / (bin_capacity as f64);
            score -= 10.0 + 20.0 * tight;
            if next_post == 0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here: penalize if we're consuming a scarce bin
            score += 8.0;
        }
    } else {
        // last item: prefer filling bins as fully as possible
        score -= 20.0;
    }

    // Last-chance bin logic: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are bad fits.
    if bin_residual == bin_capacity {
        // neutral-ish base for a fresh bin: its post_residual equals capacity,
        // which is already high; add a mild penalty so decent existing fits win.
        score += 12.0;
        // but if many open bins are nearly full (low mean residual), fresh bin is fine
        if mean_residual < 15.0 {
            score -= 10.0;
        }
        // late in the stream with many bins, avoid bin proliferation
        if open_bins_count > 4 {
            score += (open_bins_count as f64).min(15.0);
        }
    }

    // Progress-aware tightening: as the stream advances, prefer tighter fits more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.25 * progress;

    // Small tie-break: prefer bins whose residual is below the mean (consolidating waste)
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
