pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared residual penalty scaled by capacity
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead: reward if next item fits into post_residual (chaining)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Penalize bins far below mean residual (fragmented outliers)
    let dev = (bin_residual as f64) - mean_residual;
    score += dev * 0.5;

    // Time horizon: late in stream, prefer consolidating into few bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.7 && post_residual <= 10 {
        score -= 30.0;
    }

    // Many open bins: discourage new-bin bias, favor filling existing ones
    if open_bins_count > 4 {
        score -= 5.0 + (open_bins_count as f64).ln() * 3.0;
    }

    // Penalize opening a fresh bin when open bins can fit
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 45.0 + item_size as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Smooth non-linear base: reward tight fits (small post_residual) with a cubic penalty.
    let mut score = pr.powf(1.5) + 12.0 * fit_norm * fit_norm * fit_norm * cap;

    // Stream-progress coupling: later in the stream, dead space becomes more costly.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Last-chance bonus: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead: reward leaving room for the next item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 8.0 * (gap / cap).sqrt() * (1.0 - progress * 0.5);
        } else {
            score += 6.0 * (-gap / cap);
        }
    }

    // Mean-residual divergence: penalize bins far from the fleet average (fragmentation).
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * cap;

    // New-bin candidate handling: opening a new bin is only attractive early or for large items.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap;
        score += 25.0 * progress * (1.0 - large_item * 0.7);
        score -= 15.0 * large_item * (1.0 - progress);
    }

    // Mild penalty for bin proliferation.
    score += (open_bins_count as f64).ln().max(0.0) * (pr / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: tight fits rewarded
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Harmonic class of post_residual: residual mod 10 classes
    let pr = post_residual;
    let class = pr % 10;
    if class == 0 {
        score -= 8.0; // perfectly aligned residual, very reusable
    } else if class <= 2 {
        score -= 3.0; // near-aligned, still useful
    } else if class >= 8 {
        score += 6.0; // awkward sliver, dead-space risk
    }

    // Integer-division thresholds on post_residual
    if pr == 0 {
        score -= 25.0; // perfect packing
    } else if pr < 10 {
        score += 12.0; // unusable for smallest items (sizes >= 1 but tiny slivers waste)
    } else if pr < 30 {
        score += 4.0;
    }

    // Lookahead coupling: does post_residual fit next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 + 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0; // this bin can't host the next item
        }
        // Harmonic class match between residual and next item
        if next_item_size % 10 == class && next_item_size <= pr {
            score -= 5.0;
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so we only open when fits are bad
    if bin_residual == bin_capacity {
        score += 30.0 + 0.15 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big next item: fresh bin attractive
        }
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Prefer bins below mean residual (keep mean balanced)
    score += 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

