        }
        if fitting_bins_count <= 1 && item_size >= 60 {
            score -= 20.0;                          // big item, few options: open new bin
        }
    }

    // Late-stream consolidation: fill existing bins harder as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.2 * progress;

    // Prefer bins with more prior content (smaller residual already)
    score += (bin_capacity - bin_residual) as f64 * (-0.1);

