    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 6.0 * (1.0 - (post_residual as f64 - 10.0) / 20.0);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // extra reward for exact chain fit
            if post_residual == next_item_size {
                score -= 8.0;
            }
        } else if post_residual > 0 {
            score += 8.0; // leaves a gap the next item cannot use
        }
        // If next item fits this bin now but not after, mild penalty for wasting chain
        if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 5.0;
        }
    } else {
        // Last item: any fit is fine; prefer fullest packing.
        score -= 10.0 * tightness;
    }

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, just close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 4.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual ->
    // prefer consolidating into existing bins rather than opening new ones.
    if bin_residual < bin_capacity {
        score -= 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when current fit is poor or nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.6 * bin_capacity as f64
            || (fitting_bins_count <= 1 && item_size <= bin_capacity);
        if poor_fit {
            score -= 20.0;
        } else {
            score += 30.0; // discourage opening new bins when a decent fit exists
        }
    }

    // Mild preference for bins with below-average residual (consolidate fullness).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = norm_pr * (1.0 + 0.8 * t + 0.6 * t * t);

    // Reward tight fits: small post_residual gets extra discount, stronger late
    let tight_bonus = -1.5 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + t);

    // Penalize dead space that cannot fit a typical next item (smooth)
    let dead_penalty = if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        2.0 * gap * gap * (1.0 + 0.5 * t)
    } else {
        0.0
    };

    // Last-chance bonus: strongly prefer using the only fitting bin
    let last_chance = if fitting_bins_count == 1 { -3.0 * (1.0 + t) } else { 0.0 };

    // Mild penalty for spreading across many open bins when residuals are large
    let spread = 0.05 * open_bins_count as f64 * mean_residual / cap * t;

    // Slight nudge to open new bins early when fit is loose
    let new_bin_pref = norm_pr * norm_pr * (1.0 - t);

    score_bin_base(pr) + poly * 0.5 + tight_bonus + dead_penalty + last_chance + spread + new_bin_pref
}

fn score_bin_base(pr: f64) -> f64 {
    pr
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the leftover: classify post_residual by integer division.
    // Class 0: post_residual < 10  -> nearly dead space, reward heavily.
    // Class 1..3: small but potentially usable.
    // Large classes: big leftover, mildly penalize beyond raw residual.
    let class = post_residual / 10;
    match class {
        0 => { score -= 12.0; }                      // perfect packing zone
        1 => { score -= 6.0; }                       // still tight
        2 | 3 => { score -= 2.0; }                   // moderate
        _ => { score += 0.05 * post; }               // wasteful big leftover
    }

    // Exact-fill bonus (post_residual == 0 is ideal).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if the NEXT item can fit into the post residual
    // (keeps bins reusable for the following arrival).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // Harmonic alignment: next item leaves another tight class.
            if (post_residual - next_item_size) < 10 {
                score -= 6.0;
            }
        } else {
            score += 4.0; // next item won't fit here; bin likely closes
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: penalize opening a fresh bin when the stream is early
    // and open bins exist; allow it when many bins are open and this residual
    // class is bad (escape hatch for fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 18.0;
        if open_bins_count == 0 {
            new_bin_score -= 30.0; // must open
        }
        if mean_residual < 10.0 && open_bins_count > 2 {
            new_bin_score -= 20.0; // fragmentation escape
        }
        new_bin_score += 10.0 * (1.0 - progress);
        score = score.max(score) + new_bin_score.min(score.max(0.0) * 0.0 + new_bin_score) - score + score; // keep base, add new-bin penalty
        score += new_bin_score;
    }

    // Mild tie-break: prefer bins whose residual deviates from the mean
    // (consume outliers first, keep uniform bins flexible).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    // A gap is "unusable" if it's smaller than the smallest plausible item (~10) or
    // smaller than the next item that could otherwise chain into this bin.
    let dead_threshold = if next_item_size > 0 { next_item_size.min(20) } else { 10 };
    if post_residual < dead_threshold {
        score += 60.0 + (dead_threshold - post_residual) as f64 * 3.0;
    } else if post_residual < 10 {
        score += 40.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Chain lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Next item cannot chain here; mild penalty proportional to wasted gap.
        score += (post_residual.min(next_item_size)) as f64 * 0.3;
    }

    // Open-bins pressure: many open bins -> prefer filling existing bins over new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // New-bin candidate handling: empty bin gets a baseline penalty so it's only
    // chosen when all open bins score badly (poor fits / heavy dead space).
    if bin_residual == bin_capacity {
        score += 45.0 + open_bins_count as f64 * 2.0;
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly prefer using it before opening a new bin.
        score -= 35.0;
    }

    // Slight preference for bins tighter than the mean residual (denser bins first).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but not perfectly zero if next item could use it.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 20.0;

    // 2-step lookahead matching: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chain: item + next item exactly fill the bin.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: good chaining.
            score -= 15.0 + 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            score += 0.2 * (next_item_size - post_residual) as f64;
        }

        // If post_residual is too small for any plausible future item (dead space), penalize.
        if post_residual < 10 && post_residual > 0 {
            score += 25.0; // unusable sliver
        }
    } else {
        // Last item: just minimize post_residual.
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Many options: slightly prefer tighter competition among candidates.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: an empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity && item_size > 0 {
        let base = 100.0
            + 30.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0))
            + 0.5 * mean_residual;
        // If item is large relative to capacity, opening fresh is safer.
        let size_factor = 0.6 * item_size as f64;
        // If next item is large too, a fresh bin allows both to chain later.
        let lookahead_factor = if next_item_size > 50 { 25.0 } else { 0.0 };
        // If this is the only fitting bin, opening new bin is discouraged (handled by bonus above).
        score += base + size_factor + lookahead_factor;
    }

    // Progress coupling: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Prefer bins with residuals near the mean (keeps a balanced pool for future items).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: penalize wasted space super-linearly.
    let waste = post_residual as f64;
    score += 0.6 * (waste / 10.0).powi(2) * 0.1;

    // Reward bins whose residual closely matches the item (best-fit flavor).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score -= 12.0 / (1.0 + fit_gap);

    // Last-chance bonus: if this is the only bin that can fit, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Mild penalty when many alternatives exist to encourage consolidation.
        score += 0.4 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / 100.0);
        } else {
            // Penalize leaving dead space the next item cannot use.
            score += 4.0 * (post_residual as f64 / 100.0);
        }
    } else {
        // End of stream: fill bins as tightly as possible.
        score -= 10.0;
    }

    // Prefer filling already-open bins over opening new ones.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Global balance: bins below mean residual are attractive targets.
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, allow late when fit is poor.
        score += 6.0 * (1.0 - progress) - 4.0 * progress;
    } else {
        score -= 3.0 * progress;
    }

    // Slight preference for larger items in emptier bins (harmonic coupling).
    score += 0.05 * (item_size as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear tightening late in stream
    let mut score = norm_pr * (1.0 + 1.5 * progress * progress);

    // Reward tight fits non-linearly (quadratic coupling of fit quality with progress)
    let fit_quality = 1.0 - norm_pr;
    score -= 0.6 * fit_quality * fit_quality * (0.5 + progress);

    // Penalize dead space: residuals too small to be useful for typical items
    let dead = if pr > 0.0 { (1.0 - pr / 20.0).max(0.0) } else { 0.0 };
    score += 0.8 * dead * dead * (1.0 - progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 1.2;
    }

    // Prefer bins below mean residual (conserving large residuals)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.25 * dev * dev.abs();

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let room = (pr - nx) / cap;
        if room >= 0.0 {
            score -= 0.5 * room;
        } else {
            score += 0.4 * (-room);
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.01 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: bias toward it when residuals are tight
    if bin_residual == bin_capacity {
        score -= 0.3 + 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity fractions
    let frac = post_residual as f64 / cap; // 0..1
    let class = (post_residual / 10).min(10); // decile class of residual

    // Reward tiny residuals (near-perfect fit), especially harmonic "good" sizes
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Modulo arithmetic: residuals that are multiples of common item sizes are reusable
    let reusable = |r: u32| -> bool {
        (r % 10 == 0) || (r % 20 == 0) || (r % 25 == 0) || (r % 50 == 0)
    };
    if reusable(post_residual) {
        score -= 15.0 + 0.1 * post_residual as f64;
    } else {
        score += 8.0; // awkward residual penalized
    }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.5 * next_item_size as f64;
            // harmonic match: next item exactly fills or leaves reusable remainder
            let rem2 = post_residual - next_item_size;
            if rem2 == 0 {
                score -= 50.0;
            } else if reusable(rem2) {
                score -= 20.0;
            }
        } else {
            score += 12.0; // next item won't fit here; bin likely closes
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: prefer existing bins with tight fits
    if bin_residual == bin_capacity {
        // neutral base for a fresh bin, scaled by stream progress and congestion
        score += 10.0 + 0.05 * (open_bins_count as f64);
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 5.0 * progress;
        // if item is large, a fresh bin is fine
        if item_size >= 50 {
            score -= 20.0;
        }
        // discourage new bin when many fitting bins exist
        if fitting_bins_count > 3 {
            score += 15.0;
        }
    }

    // Mean residual coupling: penalize adding to a bin whose residual deviates from mean
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Dead-space penalty: residual below smallest plausible item (<=10) is dead space
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Mild penalty for leaving mid-range residuals (hardest to fill)
    if post_residual >= 30 && post_residual <= 45 && !reusable(post_residual) {
        score += 10.0;
    }

    // Class-based harmonic nudge: even decile classes slightly preferred
    if class % 2 == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it's too small for the smallest plausible item (1..100 range),
    // but practically gaps below ~10 are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - (post_residual as f64) / 10.0);
    }
    // Gaps in the 10..25 range are semi-dead: most items won't fit.
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Perfect fit for the lookahead item: post_residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    // If post_residual can't fit the next item but bin_residual could have,
    // mild penalty for wasting a bin that could chain.
    if next_item_size > 0 && post_residual < next_item_size && next_item_size <= bin_capacity {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins
    // over opening new ones (penalize the new-bin candidate implicitly via residual=100).
    if bin_residual == bin_capacity {
        // New-bin candidate: base high cost, scaled by how many bins are already open.
        score += 55.0 + 2.0 * open_bins_count as f64;
        // If no existing bin fits well, opening a new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
        // Opening a fresh bin is fine early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    } else {
        // Existing bins get a mild bonus for being usable, reduced as more bins open.
        score -= 5.0;
        // Prefer bins with smaller residuals (tighter fits) among open bins.
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Penalize bins whose residual is far above the item (loose fit) when alternatives exist.
    if bin_residual > item_size + 40 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post residual
    // matches the next item's size well (chain-friendly placements).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let exact_match = (pr - nxt).abs();
        // Reward near-exact match with next item
        score -= 12.0 * (1.0 - exact_match / bin_capacity as f64).max(0.0);
        // Penalize dead space that next item cannot use at all
        if pr < nxt {
            score += 0.5 * (nxt - pr);
        }
        // Bonus if post residual leaves room for next item (chaining)
        if pr >= nxt {
            score -= 6.0;
        }
    }

    // Compare post residual relative to mean residual of open bins:
    // placing in a bin that stays near the mean keeps balance,
    // but we prefer to drain larger-than-mean residuals.
    let pr = post_residual as f64;
    let mr = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    score -= 0.6 * (pr - mr);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize very small post residuals (unusable slivers / dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 * (10 - post_residual) as f64;
    }
    // Zero residual is perfect packing
    if post_residual == 0 {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + fitting_bins_count as f64);
        let crowded = mr / bin_capacity as f64;
        score += 30.0 - 20.0 * pressure - 15.0 * crowded;
        // Late in stream, prefer reusing bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual).
    score += 0.35 * (post_residual as f64 / cap) * (post_residual as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 12.0;
    } else if post_residual < 20 {
        score -= 4.0;
    }

    // Lookahead: reward if next item fits into post residual (chained packing).
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        score -= 8.0 + 0.1 * next_item_size as f64;
    }
    // Penalize leaving a gap that is too small for typical items but nonzero.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u64) < next_item_size as u64 {
        score += 3.0 + 0.15 * post_residual as f64;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing ones.
    if open_bins_count > 3 {
        score -= 0.5 * open_bins_count as f64;
    }

    // Compare with mean residual: bins far below mean residual are good targets.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: penalize opening a new bin unless current bin would leave
    // large dead space or no bin fits well.
    if bin_residual == bin_capacity {
        let dead = if next_item_size > 0 && post_residual >= next_item_size as u64 { 0.0 } else { 20.0 };
        let scarcity = if fitting_bins_count <= 1 { 15.0 } else { 0.0 };
        score += 30.0 + dead + scarcity
            + 0.2 * (open_bins_count as f64).max(0.0).min(50.0);
        // Early in stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) - 0.5 * norm_pr * (1.0 - progress);
    score += 40.0 * poly;

    // Reward tight fits (low post residual), stronger late in stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (20.0 + 30.0 * progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            let wasted = (gap / cap).min(1.0);
            score += 25.0 * wasted * wasted;
        } else if gap.abs() < 1.0 {
            score -= 15.0; // perfect lookahead fit reward
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    // Discard new-bin candidate unless residuals elsewhere are poor
    if bin_residual == bin_capacity {
        score += 12.0 + 25.0 * (mean_residual / cap).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by 10 are
    // "harmonic" and reusable by typical item sizes; odd/prime-ish residuals
    // tend to become dead space.
    let harmonic = (post_residual % 10 == 0) as f64;
    score -= 6.0 * harmonic;

    // Penalize post_residuals that fall into awkward classes: 1..9 modulo 10
    // are hard to fill with integer item sizes >= 1... but small exact fits
    // are fine, so grade by distance to the nearest multiple of 10.
    let r = post_residual % 10;
    let dist = r.min(10 - r) as f64;
    score += 0.8 * dist;

    // Perfect fit: zero post residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Small but nonzero post residual: usable only if next item can fill it.
    if post_residual > 0 && next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0; // lookahead exact fill
        } else if next_item_size <= post_residual {
            score -= 4.0;
            // residual class after the lookahead placement
            let rr = (post_residual - next_item_size) % 10;
            if rr == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this residue: penalize awkward classes
            score += 2.0 * dist;
        }
    }

    // Integer-division thresholds on post_residual: very small residues
    // (< 10) are near-dead space unless exact fit with lookahead.
    if post_residual > 0 && post_residual < 10 {
        score += 7.0;
    }

    // Large post residual means bin is roomy: prefer filling tighter bins
    // first (best-fit flavor), scaled by capacity fraction.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 10.0 * frac * frac;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // When many bins are open, encourage consolidation into tight fits.
    if open_bins_count > 8 {
        score += 0.15 * (post_residual as f64 - mean_residual).abs();
    }

    // Late in the stream, tighten packing more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate (empty bin): neutral-ish score; open a new bin only
    // if no open bin offers a decent harmonic fit.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.5 * item_size as f64 - 20.0 * harmonic;
        if fitting_bins_count == 0 {
            score = 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: any leftover gap below the minimum item size
    // (items are 1..100, but small gaps are hardest to reuse) is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 + slack * 0.5;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: slight penalty for leaving a misleading gap.
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Pressure on number of open bins: with many open bins, prefer filling existing
    // ones over opening new ones (penalize new-bin candidate less when few bins open).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (2.0 + 4.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by open-bin pressure plus mean residual waste.
        score += 30.0 + pressure + mean_residual * 0.3;
    } else {
        // Existing bin: mild reward scaled by how full it already is.
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 15.0 * fullness;
        // Prefer bins tighter than the mean residual (better fit quality).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step fit: post_residual exactly matches next item -> strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item still fits: mild reward proportional to how much slack remains
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leftover dead space
            let dead = post_residual as f64;
            score += 0.35 * dead;
            if dead < 10.0 {
                score += 15.0; // tiny unusable fragment
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score -= 0.25 * (mean_residual - bin_residual as f64);

    // Penalize opening a new bin when good open options exist
    if bin_residual == bin_capacity {
        score += 25.0;
        // early in the stream, new bins are cheaper; later, avoid sprawl
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize wasted space relative to capacity, amplified for small leftovers.
    let waste = post_residual as f64 / bin_capacity as f64;
