    score += 0.3 * (post_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when current bin would leave awkward gap.
    if bin_residual == bin_capacity {
        let awkward = if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 12.0 - 8.0 * awkward - 3.0 * fit_ratio;
        // Late in stream, prefer reusing bins more strongly.
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) are rewarded more strongly
    let tightness = 1.0 - norm_pr; // 1.0 = perfect fit, 0.0 = empty bin
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize very small but nonzero residuals (dead space) via quartic valley
    let dead = norm_pr * (1.0 - norm_pr);
    score += 20.0 * dead * dead * 4.0 * (1.0 - progress);

    // Lookahead: reward leaving room for the next item (smooth quadratic mismatch)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let mismatch = (pr - ns) / cap;
        score -= 15.0 * (1.0 - mismatch * mismatch) * (0.3 + 0.7 * progress);
    }

    // Last-chance bin: strong smooth reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Many open bins: mild penalty to prefer consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    // Mean residual coupling: prefer bins near the mean (smooth Gaussian-like term)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: smooth penalty scaled by how well it would fit future needs
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - progress) + 10.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class logic: residual classes mod 10 and mod 25 define "usable" dead space.
    let r = post_residual;
    let class10 = r % 10;
    let class25 = r % 25;

    // Reward residuals that land in "harmonic" classes (likely to fit future items).
    if class10 == 0 {
        score -= 12.0; // residual is a multiple of 10, matches common item sizes
    } else {
        score += class10 as f64 * 0.8; // penalize off-class slack proportionally
    }

    if class25 == 0 {
        score -= 8.0;
    }

    // Integer-division thresholds: big residuals are flexible, tiny residuals are dead space.
    let big = r / 25; // 0..4 buckets
    score -= big as f64 * 3.0;

    if r < 10 && r > 0 {
        score += 20.0; // unusable dead space (min item size 1..100, but small slack is risky)
    }
    if r == 0 {
        score -= 25.0; // perfect fit: ideal
    }

    // Lookahead: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 30.0;
        } else if next_item_size <= r {
            let slack = r - next_item_size;
            score += slack as f64 * 0.5;
            if slack % 10 == 0 {
                score -= 6.0;
            }
        } else {
            score += 5.0; // next item won't fit here regardless
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so it only wins when open bins are truly bad,
    // but favor it early in the stream when few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 - 10.0 * (1.0 - progress) - (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score += 5.0; // keep new bins for pairing medium items
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter packing).
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
