        } else {
            // Penalize opening a new bin unless the item is large relative to capacity
            score += 15.0 + 0.2 * (bin_capacity - item_size) as f64;
            if item_size > bin_capacity / 2 {
                score -= 10.0;
            }
        }
    }

    // Slight preference early in the stream to keep bins open / spread
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * (1.0 - progress);

    // Mild penalty for many open bins already (encourage consolidation)
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

