    if open_bins_count > 4 && mean_residual > (item_size as f64) {
        score += 3.0;
    }

    // New-bin candidate logic: only open a new bin when the fit in open bins is bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are opened only when justified.
        score += 45.0;
        // If item is large relative to residual, a fresh bin is more attractive.
        score -= 0.4 * (item_size as f64);
        // Late in the stream, be more conservative about opening bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
        // If no open bin can fit the item, opening a new bin is necessary.
        if fitting_bins_count == 0 {
