    // Mild penalty when many bins open and this placement leaves large residual
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += 2.0 * open_pressure * norm_pr * norm_pr;

    // Smooth coupling of item size with residual: big items prefer fuller bins
    score -= 10.0 * item * (1.0 - norm_pr) * (1.0 - norm_pr);

    // New-bin candidate: penalize opening a new bin unless residuals elsewhere are tight
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score += 12.0 * (1.0 - mean_norm) * (1.0 - progress * 0.3);
        score -= 5.0 * item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: classify post_residual into coarse buckets via integer division.
    let class = post_residual / 10; // 0..10
    // Dead space penalty grows super-linearly for small unusable residuals.
    if post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    } else {
        // Reward residuals that are multiples of common item sizes (harmonic alignment).
        let r = post_residual;
        let mut harmony = 0.0;
        for d in [10u32, 20, 25, 40, 50, 80] {
            if r % d == 0 {
                harmony += 12.0;
            }
        }
        // Reward residuals exactly matching next_item_size (perfect lookahead fit).
        if next_item_size > 0 && r == next_item_size {
            harmony += 30.0;
        } else if next_item_size > 0 && r >= next_item_size {
            harmony += (next_item_size as f64) * 0.15;
        } else if next_item_size > 0 {
            harmony -= (next_item_size - r) as f64 * 0.5;
        }
        // Integer-division threshold: residuals in [50,100) are valuable halves.
        if class >= 5 {
            harmony += 8.0;
        }
        // Penalize awkward residuals like 11..19 (bad modulo classes).
        if r % 10 >= 1 && r % 10 <= 9 && r < 50 {
            harmony -= (r % 10) as f64 * 0.3;
        }
        score -= harmony;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer tight fits: reward small post_residual relative to item size.
    score -= (item_size as f64) * 0.1;

    // New-bin candidate: penalize slightly so we only open when truly needed,
    // but allow it if all open bins would leave tiny dead space.
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late in the stream, consolidate: favor existing bins more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 5.0;
    }

    // Slight pull toward bins whose residual is close to the mean (balance).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Heavy penalty for small unusable dead space after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Penalize leaving a gap that cannot hold the lookahead item if it could otherwise.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 18.0;
    }
    // Reward a residual that exactly accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64).min(30.0) * 0.4;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly so it only wins when fits are terrible,
    // but relax penalty as stream progresses and dead space accumulates.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 - 15.0 * progress;
    }

    // Mild pull toward bins near the mean residual (keeps residuals balanced).
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item fits exactly into the post residual (2-step lookahead match).
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_quality = (post_residual - next_item_size) as f64;
        score -= 40.0 + 0.6 * next_item_size as f64 - 0.3 * fit_quality;
        // Perfect 2-item fill is excellent.
        if fit_quality == 0.0 {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty scaled by how far off we are.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.4 * gap.min(50.0);
    }

    // Penalize small unusable dead space relative to the smallest possible item.
    if post_residual > 0 {
        let dead = (post_residual as f64 / bin_capacity as f64).powi(2);
        score += 25.0 * dead;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless post residual would be terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer tighter fits (low post residual).
        score += 0.2 * (post_residual as f64 - mean_residual).max(0.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin gives a good fit (post residual too small for typical items)
    // or when we are early in the stream with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = fitting_bins_count == 0
            || (fitting_bins_count == 1 && post_residual < 10);
        if poor_fit {
            score -= 15.0 + 20.0 * (1.0 - progress);
        } else {
            // Prefer reusing existing bins; penalize opening a new one.
            score += 60.0 + 5.0 * open_bins_count as f64;
        }
    }

    // Mild pressure toward bins with residual close to item size (tight packing).
    score += 0.1 * ((bin_residual - item_size) as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Tight-fit reward: quadratic penalty on wasted space, stronger near end of stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 120.0 * (1.0 + progress);

    // Penalize bins whose residual would be unusable (below typical small item size)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: reward leaving room for the next item (chain fit)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.5 * next_item_size as f64;
        } else {
            // next item won't fit here; slight penalty proportional to wasted lookahead
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New empty bin candidate: penalize opening a new bin when others can fit,
    // but relax penalty when open bins are crowded (low mean residual) or late in stream
    if bin_residual == bin_capacity {
        let crowd = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            0.0
        };
        score += 200.0 * (1.0 - crowd) * (1.0 - 0.3 * progress);
        if fitting_bins_count > 1 {
            score += 100.0;
        }
    } else {
        // Mild preference for fuller bins (best-fit style) among open bins
        score -= 0.3 * (bin_capacity as f64 - bin_residual as f64);
    }

    // Favor bins with below-average residual (they are the "tight" ones)
    score += 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer tight fits (low post_residual). Late stream:
    // tolerate slack in bins that would otherwise be wasted.
    let tight = (pr / cap).powi(2);
    let tight_term = tight * (1.0 - progress) * 40.0;
    let slack_term = (pr / cap).powi(3) * progress * 25.0;
    score += tight_term + slack_term;

    // Smooth penalty for post_residual that cannot fit the average item
    // (dead-space coupling, quadratic in the gap).
    let dead = ((pr - it) / cap).max(0.0);
    score += dead * dead * 60.0;

    // Lookahead coupling: reward residual that still fits the next item,
    // penalize if it does not (smooth quadratic in the shortfall).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 12.0 * (1.0 - ((pr - nxt) / cap));
        } else {
            let shortfall = (nxt - pr) / cap;
            score += 18.0 * shortfall * shortfall;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else {
        // Mild congestion reward: spreading load across many open bins.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Mean-residual coupling: prefer bins whose residual deviates smoothly
    // from the mean (quadratic), keeping the pool homogeneous.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse in low classes.
    let post = post_residual;
    if post > 0 {
        let class = (cap as u32 / post.max(1)).min(10) as f64; // how many items of size post would fit
        score -= 6.0 * class; // prefer residuals that can still hold generic future items
    } else {
        score -= 40.0; // perfect fit is excellent
    }

    // Penalize small awkward residuals (dead space zones)
    if post > 0 && post < 10 {
        score += 25.0;
    }
    // Harmonic modulo structure: residuals near multiples of common sizes are reusable
    for m in [10u32, 20, 25, 50] {
        if post >= m && post % m == 0 {
            score -= 8.0;
        }
    }

    // Lookahead: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0; // chain fit
        } else if next_item_size > post {
            // next item won't fit here regardless; neutral-ish
            score += 3.0;
        } else {
            let gap = post - next_item_size;
            if gap < 10 {
                score += 12.0 * (1.0 - gap as f64 / 10.0); // creates fresh dead space
            } else {
                score -= 5.0; // next item fits comfortably
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Progress: late in stream, prefer tight packing (small post_residual already in base)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate calibration: empty bin gets moderate score so it wins only
    // when open bins would waste space.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + mean_residual * 0.2 - (post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 {
        // Dead space = post_residual too small for typical items (assume min item ~1,
        // but gaps below 10 are nearly unusable given original spec; scale penalty).
        if post_residual < 10 {
            score += 40.0 * (10.0 - post_residual as f64);
        } else if post_residual < 25 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward tight fits: fraction of bin consumed by this item.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into them
    // rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: neutral-ish baseline; only attractive when open bins
    // would leave large dead space or are scarce.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 10.0
            + 0.35 * open_bins_count as f64
            - 15.0 * (item_size as f64 / bin_capacity as f64);
        // If next item is large and current bins are fragmented, new bin helps.
        if next_item_size as f64 > mean_residual {
            score -= 12.0;
        }
    } else {
        // If this bin's post-residual can host the next item, reward chain placement.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Penalize bins whose residual deviates badly from mean (fragmentation signal).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits perfectly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use this bin's leftover: penalize dead space
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare post_residual against mean residual: keep residual near mean to preserve flexibility
    let diff = post_residual as f64 - mean_residual;
    score += 0.2 * diff.abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // Penalize opening a new bin when open bins could fit (new-bin candidate is residual == capacity)
    if bin_residual == bin_capacity {
        score += 50.0 + 0.5 * open_bins_count as f64;
    }

    // Early in stream: slightly prefer compacting into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * post_residual as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: penalize large post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (bin_capacity as f64);

    // Reward near-perfect fits (post_residual small relative to capacity).
    if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 12 {
        score -= 8.0;
    }

    // Dead-space penalty: post_residual that is too small for the smallest
    // possible future item is wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 6.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to overshoot.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Prefer using bins with smaller residuals overall (fill fuller bins first).
    score += 0.4 * (bin_residual as f64 - mean_residual).max(-50.0).min(50.0) * 0.1;

    // Time-horizon modulation: early in the stream, be more conservative about
    // opening new bins (favor existing bins); later, allow more freedom.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base score high, modulated by state.
        let mut new_bin_score = 60.0
            - 15.0 * progress
            - 0.5 * open_bins_count as f64;
        // If no existing bin fits well, opening a new bin is attractive.
        if post_residual == bin_capacity {
            if fitting_bins_count == 0 {
                new_bin_score -= 25.0;
            }
            // If the next item is large, a fresh bin is good.
            if next_item_size > item_size {
                new_bin_score -= 5.0;
            }
        }
        score = score.min(new_bin_score);
        // Ensure new bin is chosen only when genuinely better: add floor.
        score += 25.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate: many open bins -> favor existing tight bins.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), with mild non-linear decay.
    let mut score = 2.0 * (pr / cap).powf(1.3);

    // Penalty for unusable dead space: residuals too small for the smallest item.
    let dead = (10.0_f64.min(cap) - pr).max(0.0);
    score += 1.5 * (dead / cap).powi(2) * (1.0 + progress);

    // Reward bins whose post_residual still fits the next item (k=2 lookahead).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.8 * (next_item_size as f64 / cap) * (1.0 - progress);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize slightly more late in the stream.
        score += 0.5 * (1.0 - progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // Penalize opening a new bin when open bins fit, more so early on.
    if bin_residual == bin_capacity {
        score += 1.2 + 0.5 * (1.0 - progress);
        // Allow new bin if mean residual is very low (all bins nearly full).
        score -= (mean_residual / cap).min(1.0);
    }

    // Smooth coupling: bins with residual far from mean get a mild normalization nudge.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.3 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by integer division
    let post_class = post_residual / 10;
    // Small post_residual classes (tight fits) are desirable -> subtract
    score -= match post_class {
        0 => 30.0,               // post_residual < 10: near-perfect fit
        1 => 22.0,               // 10..19
        2 => 14.0,               // 20..29
        3 => 7.0,                // 30..39
        _ => 0.0,
    };

    // Exact fill reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize residuals that no plausible item (1..=100) can ever use well:
    // dead space classes where post_residual is in (50, 100) but not reusable
    if post_residual > 50 && post_residual < 100 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward heavily
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 - 0.25 * slack.min(40.0);
    } else if next_item_size > 0 {
        // next item cannot follow here; slight penalty proportional to wasted opportunity
        score += 4.0;
    }

    // Modulo-10 harmonic bonus: residuals divisible by 10 align with item classes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Prefer filling already-open bins over spawning new ones, scaled by stream progress
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and many bins are open
        score += 15.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        score -= 3.0 + 2.0 * progress;
    }

    // Mean-residual coupling: bins with residual far below mean are "holes"; using them is good
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.15 * dev.min(60.0);
    } else {
        score += 0.05 * (-dev).min(60.0);
    }

    // Mild penalty for very large items landing in nearly-full bins (fragmentation risk)
    if item_size > 60 && post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are nearly useless -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    } else {
        // Larger leftover space is more reusable: mild reward.
        score -= 4.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin before opening a new one: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from many open bins: discourage opening yet another bin.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // But if lookahead item won't fit anywhere else well, keep score moderate.
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 5.0;
        }
    } else {
        // Mildly prefer tighter bins among open ones.
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Lookahead synergy: if next item exactly fits the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use this leftover: penalize proportionally to dead space.
        score += 0.15 * post_residual as f64;
    }

    // Early in stream, slightly favor consolidation into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 2 && progress < 0.5 {
        score += 2.0 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward bins whose residual after placement
    // closely matches the next item (chained packing).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as f64 >= next_item_size as f64 {
            // Next item fits here afterward: reward tight chain
            score -= (100.0 - gap).max(0.0) * 0.8;
        } else {
            // Dead space relative to next item: penalize leftover gap
            score += gap * 0.3;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // prefer bins we can reduce below the average (balancing pressure).
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the current item
    // is large and no decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 40.0
            + (post_residual as f64) * 0.5
            - (item_size as f64) * 0.3;
    }

    // Slight preference for fuller bins early vs. late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - bin_residual) as f64 * 0.1 * (1.0 + progress);

    // Penalize scattering across many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead space: penalize residuals that are too small to be useful for future items.
    // Items are 1..100, so residual below ~10 is nearly dead; residual that can't fit
    // the lookahead item is partially dead.
    let dead_zone = 10.0f64;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 3.0; // unusable sliver penalty
    }

    // Lookahead coupling: reward residuals that can still fit the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            score -= 2.0 * next / 10.0; // keeps bin useful for lookahead
        } else {
            score += 1.5 * (next - post_residual as f64) / 10.0; // lookahead dead space
        }
    }

    // Perfect fit reward: strong bonus for tight packing.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 8.0 + 10.0 * progress;
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Only let the new bin win when existing fits are poor (many fitting bins with
    // large residuals mean we can afford to open a fresh bin for future flexibility),
    // or early in the stream when spreading load is cheap.
    if bin_residual == bin_capacity {
        let poor_fit_pressure = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        let spread_bonus = (1.0 - progress) * 15.0;
        let crowding = open_bins_count as f64 * 1.2; // discourage hoarding many bins late
        score += 30.0 + crowding - spread_bonus - poor_fit_pressure;
    }

    // Prefer bins below mean residual (tighter bins) slightly, to consolidate.
    let diff = mean_residual - bin_residual as f64;
    score += 0.3 * diff;

    // Mild preference for filling fuller bins as stream progresses.
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += poly * cap * 0.5;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (1.0 + progress) * 10.0;

    // Penalize creating dead space that cannot fit a plausible next item
    if next_item_size > 0 && post_residual > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += gap * gap * 0.05;
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for spreading across many bins
    score += open_bins_count as f64 * 0.1;

    // New-bin candidate: keep it slightly unattractive unless residuals are poor
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residuals in small "dead zones"
    // are hard to reuse. Classify by integer division into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Dead-space penalty grows super-linearly for unusable slivers.
    if post > 0.0 {
        // residuals below ~10 are nearly dead (min item is small but still)
        if post < 10.0 {
            score += 60.0 * (10.0 - post) / 10.0;
        }
        // harmonic class: quarter bands of capacity
        let band = (post_residual * 4) / bin_capacity; // 0..3
        score += match band {
            0 => 25.0,  // (0,25): poor reuse
            1 => 5.0,   // (25,50): decent
            2 => 0.0,   // (50,75): good
            _ => -3.0,  // (75,100): very reusable
        };
        // modulo-class penalty: residual mod 10 == small leftover class
        let m = post_residual % 10;
        if m > 0 {
            score += 2.0 + 0.5 * m as f64;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tightness reward: item fills a large fraction of the bin
    let tight = item_size as f64 / bin_residual as f64;
    score -= 15.0 * tight * tight;

    // Last-chance bonus: only bin that fits — avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let nxt = next_item_size as f64 / post.max(1.0);
            score -= 10.0 * nxt;
        } else {
            // next item won't fit here; residual likely wasted
            score += 8.0 * (1.0 - (next_item_size as f64 - post) / cap).max(0.0);
        }
    }

    // New-bin candidate handling: fresh bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = cap * 0.55;
        // Open a new bin when existing fits are poor (large post_residual slivers)
        let best_alternative_post = if fitting_bins_count > 0 { mean_residual } else { cap };
        let _ = best_alternative_post;
        // If item is large, fresh bin is attractive early in stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size > 60 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0 * (1.0 - progress); // pair large items together fresh
        }
        // Late in stream, prefer filling existing bins
        score += 15.0 * progress;
    } else {
        // Prefer bins whose residual is close to item (minimize fragmentation)
        let waste = (bin_residual - item_size) as f64;
        score += 0.05 * waste;
        // Slight preference for bins below mean residual (use emptier-of-usable bins)
        score += 0.02 * (bin_residual as f64 - mean_residual);
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1..=100 unknown distribution) are likely wasted; penalize heavily.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= item_size {
        // Residual could still hold an item of similar size: mildly good.
        score -= 15.0;
    } else if post_residual < next_item_size.max(1) as u32 && next_item_size > 0 {
        // This bin cannot host the lookahead item: penalty scaled by lookahead size.
        score += 8.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size as u32 {
        // Bin remains useful for the next item: reward.
        score -= 10.0;
    }

    // Tightness: fraction of the bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when few are open,
    // encourage consolidation when many are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.5 * (open_bins_count as f64 - 5.0) * (0.5 + 0.5 * progress);

    // Mean residual coupling: prefer bins below the mean residual (tighter bins),
    // penalize dumping into already-loose bins.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: default mild penalty; only attractive when the item
    // fits poorly everywhere (large item, loose existing bins).
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        let baseline = 45.0 - 0.4 * poor_fit + 0.6 * mean_residual;
        score = score.max(baseline);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if next item fits the post residual exactly or well
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            let waste_after_two = post_residual - next_item_size;
            score -= 100.0 * (1.0 - waste_after_two as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leftover dead space
            score += 0.5 * (post_residual as f64 - next_f).abs();
        }
    }

    // Compare residual to mean residual: prefer bins with less residual (tighter bins)
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin bonus: if only this bin fits, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin unless current bin would leave large unusable space
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = (bin_residual - item_size) as f64 > 20.0;
        if bad_fit && fitting_bins_count >= 1 {
            score += 60.0 + 40.0 * progress;
        } else {
            score += 25.0;
        }
    }

    // Mild preference for filling bins that are already quite full
    score += 0.2 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 12.0;

    // Penalize dead space: post_residual too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        } else {
            // Next item won't fit here; slight penalty proportional to wasted gap.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in the stream, be conservative (prefer filling existing bins);
    // late in the stream, allow more flexible choices.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Global state: many open bins with high mean residual -> prefer reusing existing bins.
    if bin_residual < bin_capacity {
        score -= (mean_residual - post_residual as f64).abs() * 0.1;
        score += open_bins_count as f64 * 0.05;
    } else {
        // New-bin candidate: penalize unless existing bins are fragmented.
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 15.0 - fragmentation * 25.0;
    }

    // Mild penalty for very large leftover chunks that may trap small items.
    if post_residual > 50 && post_residual < bin_capacity {
        score += (post_residual as f64 - 50.0) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more; early, waste is cheaper
    let tightness = (1.0 - norm_pr).powi(2);
    score += progress * tightness * 12.0;
    score -= (1.0 - progress) * norm_pr * 4.0;

    // Penalize dead space relative to mean residual (smooth cubic coupling)
    let dead = (pr - mean_residual) / cap;
    score += dead * dead.abs().powf(1.5) * 10.0;

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * tightness * progress;
    }

    // Lookahead coupling: reward leaving space for the next item (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_kernel = (gap / cap).powi(2);
        score -= (1.0 - fit_kernel) * 8.0;
    } else {
        score += pr * 0.5; // end of stream: just minimize residual
    }

    // Mild pressure against opening many bins when residuals are large
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 2.0;

    // New-bin candidate: neutral-ish baseline so it only wins on genuinely bad fits
    if bin_residual == bin_capacity {
        score = 55.0 + 20.0 * progress - 8.0 * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near zero (tight fits) are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction remaining

    // Exact-fit / near-zero residue reward
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    }

    // Modulo harmonic classes on post_residual: residues in [0,10) are "consonant"
    // dead-space classes (small leftovers often reusable by small items).
    let res_class = post_residual % 25;
    if res_class == 0 && post_residual > 0 {
        score -= 40.0; // residual aligns with quarter-capacity: reusable slot
    } else if res_class > 20 {
        score += 25.0; // awkward large-but-unusable class
    }

    // Integer-division threshold: post_residual buckets by /10
    let bucket = post_residual / 10;
    score += bucket as f64 * 3.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let next_left = post_residual - next_item_size;
            // reward smooth chaining, penalize tiny leftovers after chaining
            if next_left <= 10 {
                score -= 60.0;
            }
            score -= (next_left as f64).ln().max(0.0) * 8.0;
        } else {
            // next item cannot follow: post_residual becomes dead space
            score += 45.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when current fit is terrible
    // or no open bins exist.
    if bin_residual == bin_capacity {
        let base = 0.5 * cap;
        if post_residual as f64 > 0.6 * cap {
            score -= 90.0; // fresh bin fine when item is large
        } else {
            score += 0.45 * (base - pr).abs() + 70.0; // discourage wasting open space
        }
        if open_bins_count == 0 {
            score -= 400.0;
        }
    }

    // Mean-residual coupling: if this bin is far below mean residual, it is a
    // "straggler" bin; using it consolidates open bins.
    let dev = mean_residual - pr;
    if dev > 0.0 {
        score -= dev.min(50.0) * 1.5;
    }

    // Stream progression: late in the stream, tighten up (prefer tight fits more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // Slight preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 10 {
        // Dead space zone: gap too small for the smallest plausible item.
        score += (11.0 - pr) * 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    } else if post_residual <= 20 {
        // Moderately risky residual: mild penalty.
        score += (20.0 - pr) * 2.5;
    } else {
        // Large residuals remain usable; slight reward scaled by size.
        score -= pr * 0.05;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 20.0 - slack; // near-perfect chaining fit
        } else {
            score -= 3.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item cannot use this gap: penalize if gap is small.
        if post_residual <= 15 {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open bins pressure: discourage spreading when many bins are already open.
    score += open_bins_count as f64 * 0.8;

    // Deviation from mean residual: prefer bins whose residual is closest to
    // the item (tight packing relative to fleet state).
    let dev = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate handling: only attractive late in the stream or when
    // item is large; otherwise make it costly so existing bins get used.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size >= 60;
        if large_item || progress > 0.7 {
            score -= 5.0 + progress * 5.0;
        } else {
            score += 20.0;
        }
    }

    // Mild preference to fill fuller bins first (small residual before placement).
    score += (bin_capacity - bin_residual) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: small post_residual is good (already baseline).

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, this is a perfect pairing -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves more waste: partial reward proportional
            // to how snug the pairing is.
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.5 * pair_waste;
        } else {
            // Next item cannot follow into this bin: penalize proportionally
            // to the unusable gap it would leave behind.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Compare residual against mean residual across open bins:
    // filling bins that are below-average residual (already tight) is good,
    // dumping into bins with large residual wastes flexibility.
    if post_residual as f64 > mean_residual {
        score += 0.4 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless the item
    // is large and no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 55.0 - 35.0 * large_item;
    }

    // Late in the stream, closing bins tightly matters more (less future
    // opportunity to reuse residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Mild penalty for spreading across many open bins when item is small.
    if item_size < 30 {
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Reward perfect fit strongly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (next_item_size as f64) * 0.2;
    }
    // If next item would leave another near-perfect leftover, small extra reward.
    if next_item_size > 0 && post_residual >= next_item_size
        && (post_residual - next_item_size) <= 10 {
        score -= 8.0;
    }

    // Penalize bins far from mean residual (encourage balanced usage),
    // but more strongly when many bins are open (consolidation pressure).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * (1.0 + open_bins_count as f64 * 0.05);

    // New-bin candidate handling: only attractive when the item is huge
    // relative to capacity or open bins are all poor fits.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Big items deserve a fresh bin; small items should use existing space.
        score += 60.0 * (1.0 - fill_ratio);
        // Late in the stream, opening new bins is more costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If many bins are open and one fits, discourage spreading.
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Mild bonus for filling large bins down to small leftovers.
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer tight fills (low post_residual) strongly.
    // Late stream: tolerate residual, favor keeping bins usable.
    let pr = post_residual as f64 / bin_capacity as f64;
    let w_early = (1.0 - progress).powi(2);
    let w_late = progress.powi(2);
    score += w_early * (pr * pr) * 40.0;
    score -= w_late * (pr * (1.0 - pr)) * 30.0;

    // Reward near-perfect fits smoothly (cubic in post_residual).
    let perfect = 1.0 - (post_residual as f64 / bin_capacity as f64).powf(3.0);
    score -= perfect * 15.0;

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Lookahead: penalize if next item cannot use the post residual.
    if next_item_size > 0 {
        if (next_item_size as f64) > post_residual as f64 {
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate: smooth bias depending on mean residual of open bins.
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        score += 12.0 + open * 0.5 - mean_residual * 0.2;
    }

    // Penalize creating small dead space relative to typical item sizes.
    if post_residual > 0 && post_residual < item_size {
        score += 8.0 * (1.0 - post_residual as f64 / item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity split into 4 equal classes.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..4

    // Reward small post-residuals (tight fits) with a class-based bonus.
    match class {
        0 => score -= 40.0,                       // nearly full: excellent
        1 => score -= 18.0,                       // decent
        2 => score -= 4.0,                        // mediocre
        _ => {}                                   // large dead space: no bonus
    }

    // Exact modulo structure: post_residual divisible by 4 or 5 pairs well
    // with integer item sizes drawn from 1..=100.
    if post_residual > 0 && (post_residual % 4 == 0 || post_residual % 5 == 0) {
        score -= 6.0;
    }
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 6.0; // extra harmony with decade-sized items
    }

    // Lookahead coupling: if the next item exactly fills post_residual,
    // this bin becomes perfect after two placements.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize leftover that is a bad class
            let nxt_left = post_residual - next_item_size;
            if nxt_left > quarter * 2 {
                score += 10.0;
            } else if nxt_left <= 5 {
                score -= 12.0;
            }
        } else {
            // next item will NOT fit here: leaving big residual is wasteful
            if post_residual > quarter {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: it has full residual. Make it attractive
    // only when the current fit is poor (large post_residual).
    if bin_residual == bin_capacity {
        // Neutral baseline slightly above a good fit's score.
        score = 55.0 + (post_residual as f64);
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 30.0; // current bins too full; open fresh bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 && item_size <= bin_capacity / 4 {
            score -= 15.0; // big item coming: fresh bin useful
        }
    }

    // Mild stream-progression pressure: consolidate more as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Spread pressure: many open bins -> prefer filling existing ones.
    if open_bins_count > 4 {
        score -= 0.5 * (open_bins_count.min(20) as f64);
    }

    // Slight preference to deviate from mean residual toward fuller bins.
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (1..100 stream => treat ~<10 as dead) are toxic.
    if post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 25.0; // barely usable dead space
    } else if post_residual >= 40 && post_residual <= 90 {
        score -= 15.0; // generous, reusable gap
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or the
    // fit here is poor. Penalize default new bins when open bins exist.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 35.0 + 3.0 * open_bins_count as f64;
            // If the next item is large, a fresh bin is more valuable.
            if next_item_size >= 60 {
                score -= 20.0;
            }
        } else {
            score -= 100.0; // must open the first bin
        }
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    score += 1.5 * open_bins_count as f64;

    // Prefer bins whose residual is already below the mean (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // Lookahead: if post_residual can host the next item, bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 12.0; // would strand a tiny gap before next item
    }

    // Late in stream: consolidate harder.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward near-perfect match with next item (2-step lookahead).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 12.0 * (1.0 - gap / cap).max(0.0);
        // Perfect chain: post_residual exactly equals next item.
        if post == nxt {
            score -= 25.0;
        }
        // Pairing leaves a residual that fits next item leaving tiny waste.
        if post >= nxt && (post - nxt) <= 10.0 {
            score -= 8.0;
        }
    }

    // Penalize dead space that no realistic item (1..100) can use.
    if post > 0.0 && post < 10.0 {
        score += 30.0 * (1.0 - post / 10.0);
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score = post + 20.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin
        } else if next_item_size > 0 && (post - next_item_size as f64).abs() < 5.0 {
            score -= 10.0; // fresh bin chains nicely with next item
        }
    }

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 40.0;

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + (next_item_size as f64) * 0.3;
    } else if next_item_size > 0 {
        // Penalize leaving dead space that the next item cannot use.
        score += (next_item_size as f64 - post_residual as f64).max(0.0) * 0.5;
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize bins far below mean residual (badly unbalanced usage) mildly.
    score += (mean_residual - bin_residual as f64).abs() * 0.15;

    // Time horizon: early in the stream, be more conservative with tight fits;
    // late in the stream, prioritize closing bins out (favor small post_residual more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (1.0 - fit_ratio);

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; competes with poor fits.
        score = (item_size as f64) * 0.9 + 10.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // no open bin fits anyway
        }
        // Late in stream, prefer filling existing bins.
        score += progress * 15.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin will hold future items too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let nxt = next_item_size as f64;

    // Smooth non-linear base: convex growth of post-residual waste,
    // slightly steeper as the stream progresses (packing tightens late).
    let mut score = pr.powf(1.35 + 0.35 * t) / cap.powf(0.35 + 0.35 * t);

    // Dead-space coupling: residual that cannot host the lookahead item
    // is penalized more heavily later in the stream (smooth ramp).
    if nxt > 0.0 && pr < nxt {
        let dead = nxt - pr;
        score += dead * (1.2 + 1.3 * t) * (1.0 - pr / cap);
    }

    // Smooth interaction with mean residual: prefer bins whose remaining
    // space deviates below the fleet average (tighten the tightest first).
    score += 0.06 * (pr - mean_residual) * (1.0 - t) + 0.10 * (pr - mean_residual).abs() * t;

    // Last-chance bonus: if this is the only bin that fits, reward strongly
    // but modulated by how wasteful the placement would be.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= (10.0 + 10.0 * t) * (1.0 - pr / (2.0 * cap));
    }

    // New-bin candidate: mild default penalty that decays over the stream;
    // opening fresh bins becomes relatively more acceptable early on.
    if bin_residual == bin_capacity {
        score += 6.0 + 14.0 * (1.0 - t) * (1.0 - t);
    }

    // Slight congestion term: with many open bins, prefer consolidation.
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, with a non-linear penalty on large residuals.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Harmonic class of the post-residual: residual mod 10 classes.
    // Residuals that are "friendly" (divisible into common small item sizes)
    // are rewarded; awkward classes are penalized.
    let pr = post_residual as i64;
    let class = pr % 10;
    match class {
        0 => score -= 6.0,                     // perfectly reusable residual
        5 => score -= 3.0,                     // half-decade residual, still good
        2 | 4 | 6 | 8 => score -= 1.5,         // even residuals pair with even items
        1 | 3 | 7 | 9 => score += 2.0,         // awkward odd residuals
        _ => {}
    }

    // Reward small post-residual buckets via integer-division thresholds.
    let bucket = post_residual / 10;
    score -= match bucket {
        0 => 10.0,
        1 => 6.0,
        2 => 3.0,
        3 => 1.0,
        _ => 0.0,
    };

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            // next item fits: small leftover after chaining is good
            let chain_left = post_residual - next_item_size;
            score -= 4.0 * (1.0 - chain_left as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize large post-residuals more
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    // or mean residual is small (nothing good to place into).
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let scarcity = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 55.0 - 20.0 * congestion - 15.0 * scarcity;
        // Don't open a new bin when the current item is tiny and bins are roomy.
        if item_size <= 20 && mean_residual > 40.0 {
            score += 25.0;
        }
    }

    // Mild stream-progression pressure: later in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Small nudge toward bins tighter than the mean residual (compactness).
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 12.0; // risky zone: only huge items fit later
    } else if post_residual <= 35 {
        score += 3.0;
    } else {
        // Reward large, versatile residuals (mildly sub-linear).
        score -= (post_residual as f64).sqrt() * 1.5;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: discourage proliferating bins slightly,
    // scaled by how full the average bin already is.
    let mean_fill = bin_capacity as f64 - mean_residual;
    score += open_bins_count as f64 * (0.4 + 0.02 * mean_fill);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward this placement; if it barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size > post_residual && next_item_size <= post_residual + 10 {
            score += 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when this item would leave a tight, useful residual in a new bin
    // (i.e., item is large) AND existing fits are poor.
    if bin_residual == bin_capacity {
        let tight_new_fit = (bin_capacity - item_size) <= 25;
        if tight_new_fit && (fitting_bins_count == 0 || post_residual <= 12) {
            score -= 55.0;
        } else {
            score += 30.0; // default: prefer reusing open bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fits are ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves further residual — mild reward
            score -= 50.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item does not fit in this bin's remainder — penalize
            // larger leftover relative to next item size = worse dead space
            score += 30.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        }
    }

    // Compare post_residual against mean residual across open bins
    // Leaving a residual far above mean wastes capacity potential
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
    // Reward bins tighter than the mean
    score -= 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize selecting a brand-new bin when open bins could fit
    if bin_residual == bin_capacity {
        score += 150.0;
        // But if nothing else fits well (this is the only fitting candidate),
        // the new-bin penalty is offset by the last-chance reward above.
    }

    // Late in the stream, prefer consolidation into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (open_bins_count as f64 / 10.0).min(3.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - t);
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 / (1.0 + slack);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count <= 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when fits are poor or many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mean_fit = if bin_capacity as f64 > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        let poor_fits = (fitting_bins_count == 0) || (fit_ratio < 0.5 && mean_fit > 0.6);
        if poor_fits {
            score -= 18.0;
        } else {
            score += 40.0 + 3.0 * open_bins_count as f64;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins below mean residual slightly (balance load).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Normalize post-residual and apply non-linear polynomial shaping
    let x = pr / cap; // in [0,1]
    // Reward tight fits strongly (low post_residual), non-linearly
    score -= (1.0 - x) * (1.0 - x) * 12.0;
    // Penalize mid-range dead space (unusable gaps) via smooth bump
    score += 4.0 * x * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Coupling with stream progress: early on, keep bins flexible (prefer larger residual);
    // late, exploit tight fits more aggressively
    let prog_coupling = 6.0 * progress * (1.0 - x) * (1.0 - x) - 3.0 * (1.0 - progress) * x * (1.0 - x);
    score += prog_coupling;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress + 0.2);
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 * (1.0 - progress);
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        score += 2.0 * (next_item_size as f64 - pr) / cap;
    }

    // Mild penalty when bin residual is far from mean residual (diversity of gap sizes)
    score += 0.5 * ((pr - mean_residual) / cap).abs();

    // Slight preference to fill existing bins vs opening new ones as stream progresses
    score += 1.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction slot it lands in.
    let cap = bin_capacity as f64;
    let quarter = (bin_capacity / 4) as u32;
    let post = post_residual;
    let class: u32 = if post == 0 { 0 }
        else if post <= quarter { 1 }
        else if post <= 2 * quarter { 2 }
        else if post <= 3 * quarter { 3 }
        else { 4 };
    score += match class {
        0 => -40.0,                       // perfect closure: strongly reward
        1 => post as f64 * 0.5,           // tiny dead space: penalize proportionally
        2 => -5.0,                        // half-ish residual: still reusable
        3 => 3.0,                         // large residual: mild penalty
        _ => 0.0,
    };

    // Modulo arithmetic on post_residual: divisibility classes hint at future fit.
    let m3 = post % 3;
    let m5 = post % 5;
    if m3 == 0 { score -= 4.0; }
    if m5 == 0 { score -= 3.0; }
    if m3 == 1 && m5 == 2 { score += 5.0; } // awkward class

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            score -= 12.0; // chain placement possible
            // exact chain closure
            if next_item_size == post { score -= 15.0; }
            // harmonic class of what remains after the chain
            let chain_post = post - next_item_size;
            if chain_post == 0 { score -= 10.0; }
            else if chain_post <= quarter { score += chain_post as f64 * 0.3; }
        } else {
            score += 6.0; // next item won't fit here: dead-end risk
        }
    } else {
        // last item: prefer closing bins tightly
        score -= 8.0;
        if post == 0 { score -= 20.0; }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin gets a neutral-ish score so it is
    // chosen only when all open bins have bad (large) residuals.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + mean_residual * 0.2 - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score += 5.0; // slightly discourage new bin when next item is small
        }
    }

    // Progress bias: late in the stream, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (mean_residual - post as f64) * 0.25;

    // Pull toward bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below 10 are nearly useless dead space.
    if post_residual < 10 {
        score -= 25.0; // perfect/near-perfect fill is highly desirable
    } else if post_residual <= 20 {
        // Small gaps are only usable by tiny items; penalize mildly-to-strongly.
        score += (20 - post_residual) as f64 * 0.8;
    } else if post_residual <= 40 {
        score += (40 - post_residual) as f64 * 0.25;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, favor compacting into existing bins.
    let pressure = (open_bins_count as f64 / 10.0).min(3.0);
    score -= pressure * (item_size as f64 / bin_capacity as f64) * 5.0;

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0; // next item can still use leftover space
    } else if next_item_size > post_residual && post_residual > 0 {
        // Leftover space cannot host the next item; penalize proportional dead space.
        score += (post_residual as f64) * 0.3;
    }

    // New-bin candidate: opening a new bin is only attractive when existing bins
    // are crowded (few fitting bins) and current bins are already fairly full.
    if bin_residual == bin_capacity {
        let crowded = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let fullness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 - 20.0 * crowded - 15.0 * fullness - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual closely
    // matches the next item size (chain-packing).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64).max(0.0);

        // Perfect chain: next item fills bin exactly.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item cannot fit here afterwards -> dead space penalty if gap large.
        if post_residual < next_item_size {
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter (smaller residual) than average.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Penalize leaving tiny unusable fragments (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer it only when item is large and no good open fit.
    if bin_residual == bin_capacity {
        score += 5.0 - 0.1 * item_size as f64;
    }

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small to plausibly hold future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: check if the next item can co-fit in this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Great: next item also fits here; reward proportionally.
            let combo = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - combo / bin_capacity as f64);
        } else {
            // Next item won't fit; penalize leaving awkward remainder.
            let slack = (post_residual as f64) - (next_item_size as f64 - post_residual as f64).max(0.0);
            if post_residual < next_item_size {
                score += 6.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
            } else {
                score += 2.0;
            }
            let _ = slack;
        }
    } else {
        // Last item in stream: just minimize post_residual (already base).
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins are underutilized.
        let underuse = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 20.0 + 45.0 * underuse + 15.0 * progress;
        // But if no existing bin fits and item is large, allow opening.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late in stream with crowded bins, opening may fragment; extra penalty.
        if open_bins_count > 3 {
            score += 5.0 * (open_bins_count as f64).ln();
        }
    } else {
        // Slight preference for bins whose residual is near the mean (balance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Early stream: be conservative, keep bins flexible (mild penalty on very tight fits).
    if progress < 0.2 && post_residual < 15 && bin_residual != bin_capacity {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = (1.0 - x) * (1.0 - x) * (1.0 + 2.0 * progress) - x * x * (1.0 - progress);
    score -= 30.0 * poly;

    // Penalize dead space relative to next item's fit
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let waste = (pr - n).max(0.0) / cap;
        score += 25.0 * waste * waste;
        if pr >= n {
            score -= 12.0 * (1.0 - (n / cap));
        }
    }

    // Last-chance bonus for tight fits
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - x) * (1.0 + progress);
    }

    // Mild penalty when many bins are open and residual is large (fragmentation)
    let openness = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 10.0 * openness * x * x;

    // Smooth new-bin discouragement: empty bin gets a progress-dependent offset
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * (1.0 - progress) - 10.0 * x;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: bins whose leftover lies in a
    // "reusable" residue class (multiples of 10, and small residues that
    // future small items can still fill) are favored.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Dead-space penalty: leftover too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Modulo-10 harmonic class: residual divisible by 10 is "clean" space.
    if post_residual % 10 == 0 {
        score -= 25.0;
    }

    // Integer-division thresholds on post_residual: classify leftover size.
    let class = post_residual / 25; // 0: tiny, 1: small, 2: medium, 3: large
    score -= match class {
        0 => 10.0,   // tiny leftover: nearly full bin, good
        1 => 5.0,    // small leftover
        2 => 0.0,    // medium leftover
        _ => -8.0,   // large leftover still usable
    };

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 30.0;
        } else {
            // Next item won't fit here; leftover becomes dead unless small.
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: only open a new bin when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin; stronger when many bins are open
        // or when the mean residual suggests space exists elsewhere.
        score += 350.0 + 8.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 40.0; // large item coming: fresh bin may be useful
        }
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 50.0 * (1.0 - progress); // prefer reusing bins early on
    } else {
        // Prefer filling bins that are already relatively full.
        score += 20.0 * (1.0 - (bin_residual as f64 / cap));
    }

    // Coupling with mean residual: avoid wasting bins whose residual is
    // far below average (they are the "odd ones out").
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.1 * dev;
    }

    // Small harmonic tie-breaker on item_size classes.
    score += (item_size % 7) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit: strongly reward
    }

    // Reward tight fits relative to bin capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bin: avoid opening a new bin when this is the only option.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: penalize spreading across many bins slightly,
    // but allow new bin when existing residuals are large and fit is poor.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.8 * (1.0 - progress);

    // New-bin candidate: only attractive if this bin's fit wastes a lot
    // (large post_residual) or residual space can't serve the next item.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        let next_fits_here = next_item_size > 0 && post_residual >= next_item_size;
        let next_fits_current = next_item_size > 0 && post_residual >= next_item_size;
        let bad_fit = waste > 25.0 || (next_item_size > 0 && !next_fits_here && next_fits_current && false);
        if bad_fit {
            score -= 30.0 + waste * 0.3;
        } else {
            score += 20.0; // prefer filling existing bins on decent fits
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.2;
    }

    // Mean residual context: penalize bins far below mean residual (already packed),
    // favor bins whose residual is close to mean for balanced packing.
    score += (mean_residual - bin_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
