    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when the item fits reasonably in an existing bin.
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        score += 15.0 + 30.0 * (1.0 - fit_quality);
        // New bin is acceptable if the item is large and nothing else fits well.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Slight preference early in the stream to keep bins tight (more bins will follow).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that can never fit a typical future item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: bonus if next item exactly fits post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit_penalty = if fitting_bins_count > 0 {
            (post_residual as f64 - (bin_capacity - item_size) as f64).abs()
        } else {
            -50.0
        };
        score = 30.0 + poor_fit_penalty - 20.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Global pressure: many open bins with high mean residual -> consolidate
    if mean_residual > 40.0 && !is_new_bin {
        score -= (mean_residual - 40.0) * 0.3;
    }
    if open_bins_count > 8 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Prefer filling bins that are already partially committed
    let used_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * used_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of residual waste with stream progress:
    // early on, larger residuals are fine; late, penalize them harder.
    let coupling = norm_pr * (1.0 - norm_pr); // peaks mid-range residual
    score += 40.0 * coupling * progress * progress;

    // Penalize dead space that next item can't use (smooth interaction)
    if next_item_size > 0 {
        let nx = (next_item_size as f64).min(cap);
        let gap = (pr - nx).max(0.0) / cap;
        score += 25.0 * gap * gap * (1.0 + progress);
        // Reward if next item fits exactly-ish
        let fit_quality = 1.0 - ((pr - nx) / cap).abs();
        if fit_quality > 0.0 {
            score -= 15.0 * fit_quality * fit_quality * fit_quality;
        }
    }

    // Last-chance bonus: only one fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - progress);
        score -= 30.0 * progress;
    }

    // Mild reward for consolidating into bins below mean residual
    let mr = mean_residual / cap;
    score -= 10.0 * (norm_pr - mr) * (norm_pr - mr) * (1.0 - progress);

    // Smooth pressure against opening new bins when many are open
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 6.0 * progress);

    // Slight preference for tight fits overall
    score -= (item_size as f64 / cap) * (item_size as f64 / cap) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is a small residue modulo
    // common item classes (e.g. multiples of 10, 25, 50) is nearly unusable.
    let pr = post_residual as i64;
    let mut dead = 0.0f64;
    for m in [10i64, 20, 25, 50] {
        let r = pr % m;
        if r > 0 && r < 10 {
            dead += (10 - r) as f64 * (m as f64 / 50.0);
        }
    }
    score += dead;

    // Perfect fit reward: post_residual in a "harmonic" class (0 mod 10 or 0 mod 25)
    if pr == 0 {
        score -= 40.0;
    } else if pr % 10 == 0 {
        score -= 12.0;
    } else if pr % 25 == 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 35.0;
        } else if gap <= 10 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use the leftover: penalize proportionally
        score += (next_item_size.min(post_residual.max(1)) as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer tight bins: scale relative to mean residual
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.3;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.1;
    }

    // New-bin candidate penalty: opening a bin wastes capacity; only attractive
    // when open bins are few or item is large relative to residuals.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        score += 15.0 + pressure * 1.5;
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Late-stream consolidation: mild bonus for filling existing bins near the end
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_useful = 10; // smallest possible item footprint
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0; // tiny gap = pure waste
    } else if post_residual >= min_useful && post_residual <= 20 {
        score += 15.0; // narrow gap, likely unusable soon
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 25.0 / (1.0 + tightness);

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // gap blocks the known next item
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when existing bins would leave bad dead space.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    }

    // Mild pull toward bins with larger residuals among open bins.
    score += 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: bin closes exactly after next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect match: next item fits with small slack afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: penalize relative to how close we were.
        let miss = (next_item_size - post_residual) as f64;
        score += 3.0 * miss;
    }

    // Penalize dead space that no plausible item (min size 1..100) can ever use.
    if post_residual > 0 {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 50.0 * waste * waste;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Early in the stream, encourage consolidation; late, be more permissive with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize it, more so early on.
        score += 120.0 * (1.0 - 0.5 * progress);
    }

    // Slight preference for bins with less residual overall (best-fit flavor).
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that can never fit the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: only one bin can fit this item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }
    // Many alternatives: slight penalty to encourage diversity of choices
    if fitting_bins_count > 3 {
        score += 5.0;
    }

    // Lookahead: reward if next item fits perfectly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 12.0 * (post_residual as f64 - next_item_size as f64).min(30.0) / 30.0;
        } else {
            // next item won't fit here; penalize proportionally to wasted space
            score += 8.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
        }
    }

    // Global state: prefer filling bins when mean residual is high (many scattered gaps)
    if mean_residual > 40.0 {
        score -= 6.0 * (mean_residual - 40.0).min(40.0) / 40.0;
    }

    // Time horizon: early in stream, be more willing to open new bins (explore);
    // late in stream, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bias = 15.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: neutral base plus exploration bias, penalized
        // if open bins are few (avoid bin proliferation) or many (encourage consolidation)
        score += new_bin_bias;
        if open_bins_count > 2 {
            score += 10.0 * (open_bins_count.min(20) as f64) / 20.0;
        }
        // Opening a new bin is attractive if item is large and fits nowhere well
        if item_size > 60 && fitting_bins_count <= 2 {
            score -= 20.0;
        }
    }

    // Mild penalty for placing small items into large residuals (waste)
    if item_size < 25 && bin_residual > 70 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits (small post residual), non-linearly shaped by progress.
    let mut score = pr as f64;

    // Smooth polynomial coupling: dead space penalized more later in the stream.
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep-like in [0,1]
    score += 30.0 * poly * (0.5 + progress);

    // Reward filling bins nearly exactly, scaled by stream progress.
    let exactness = 1.0 - x;
    score -= 20.0 * exactness * exactness * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    }

    // Lookahead: penalize if post residual can't fit the next item (creates stranded space),
    // reward if it can.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (pr as u32) >= next_item_size {
            score -= 8.0 * (1.0 - progress);
        } else {
            score += 6.0 + 10.0 * progress;
        }
        // Slight reward if post residual is "close" to next item size (good chain fit).
        let gap = (pr - nx).abs();
        score -= 5.0 * (1.0 - gap / cap).max(0.0);
    }

    // Mild penalty for spreading across too many open bins relative to mean residual.
    let mr = mean_residual / cap;
    score += 10.0 * (x - mr) * (x - mr) * progress;

    // New-bin candidate: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 15.0 * (fitting_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // coarse buckets via integer division (classes of width 10).
    let class = post_residual / 10;
    let class_center = class as f64 * 10.0 + 5.0;
    score += 0.5 * (post_residual as f64 - class_center); // mild within-class shaping

    // Reward tiny dead space (near-perfect fits) nonlinearly.
    if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 6.0;
    }

    // Penalize leftovers that no plausible future item can use:
    // dead zones where residual is smaller than the smallest item (1).
    // Since items >= 1, any residual is usable, but tiny residuals (< 10)
    // are much less flexible than mid-range ones.
    if post_residual > 10 && post_residual < 20 {
        score += 4.0; // awkward class: too small for most items
    }

    // Lookahead coupling: reward if the next item fits exactly/nicely
    // into the post_residual (modulo-style harmonic match).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 8.0;
            } else {
                score -= 4.0 / (1.0 + slack as f64 / 20.0);
            }
        } else {
            // next item won't fit here; leftover becomes a waiting class
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin gets opened.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin has large residual;
    // make it attractive only when current bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, discounted when many items remain
        // and open bins are already crowded.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 25.0;
        if fitting_bins_count == 0 {
            new_bin_cost = 0.0; // forced
        }
        // If mean residual across open bins is low, prefer new bin.
        new_bin_cost -= (cap - mean_residual).max(0.0) * 0.05;
        new_bin_cost -= progress * 5.0;
        score += new_bin_cost.max(0.0);
        // An empty bin gives full flexibility: slight bonus for large items.
        score -= item_size as f64 * 0.05;
    } else {
        // Prefer filling bins that are already relatively full
        // (small residual before placement = tight fit).
        score += (bin_residual as f64) * 0.10;
        // Mild pressure to keep number of open bins small.
        score += open_bins_count as f64 * 0.02;
    }

    // Harmonic modulo bonus: if post_residual shares a residue class
    // structure with next_item_size (both multiples of 10), future packing
    // is easier.
    if next_item_size > 0 && post_residual % 10 == 0 && next_item_size % 10 == 0 && next_item_size <= post_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    } else {
        // Larger leftover space is flexible; reward it mildly.
        score -= 4.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space relative to next item: leftover that next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.5 * (next_item_size - post_residual) as f64;
    }
    // If next item fits exactly into the post residual, favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Pressure from number of open bins: prefer tighter bins when many open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * (bin_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless all open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 40.0 + 5.0 * open_bins_count as f64 * progress;
        // But if item is large, opening fresh is fine.
        if item_size > bin_capacity / 2 {
            score -= 35.0;
        }
    }

    // Prefer bins whose residual is closest to the item (tight packing).
    score += (bin_residual - item_size) as f64 * 0.1;

    // Slight preference toward bins below mean residual (tightly packed bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward residuals that exactly fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr == nxt {
            score -= 500.0;
        } else if pr >= nxt {
            // residual can host next item: mild reward proportional to leftover after next
            score -= 0.5 * (pr - nxt);
        } else {
            // residual cannot host next item: penalize dead space, worse when gap is small
            let gap = nxt - pr;
            score += 0.3 * gap;
        }
    }

    // Prefer bins tighter than mean residual
    let pr = post_residual as f64;
    score += 0.2 * (pr - mean_residual);

    // Last chance bin: strong push to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Slight preference to fill earlier bins as stream progresses
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 0.1 * progress * (open_bins_count as f64);

    // Discard tiny unusable residuals (< 10, smallest item)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

