            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Global state coupling: prefer filling bins when many are open (contain bin proliferation).
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 20.0);
    score -= 4.0 * open_pressure * tightness;

    // Mean residual coupling: if this bin's residual is far below mean, filling it
    // harmonizes residuals (reduces fragmentation); if above mean, slight penalty.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev;

    // Time horizon: early in stream, be more willing to open new bins (explore);
    // late in stream, consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: cheaper early, expensive late.
        score += 20.0 * (1.0 - progress) - 20.0 * progress;
        // But if no open bin fits well (this is the only fitting option), allow it.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    } else {
        score -= 10.0 * progress * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Smooth non-linear coupling of post_residual with stream progress.
    let t = post_residual as f64 / bin_capacity as f64;
    let poly = t * t * (1.0 - t) * (1.0 - t); // peaks mid-range, small at extremes
    score -= 30.0 * poly * (0.5 + progress);

    // Penalize large post-residuals more strongly as stream matures.
    score += (post_residual as f64).powi(2) / bin_capacity as f64 * (0.4 + 0.8 * progress);

    // Reward tight fits (small post_residual) with a smooth saturating term.
    score -= 12.0 * (1.0 - (-post_residual as f64 / 20.0).exp());

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: reward residual that can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // New-bin candidate: mild penalty so it loses to good fits, wins over bad ones.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0;
    }

    // Mild coupling with mean residual and bin count.
    score += 0.05 * (mean_residual - post_residual as f64).abs();
    score += open_bins_count as f64 * 0.01 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how well the leftover aligns with
    // typical small-item sizes (1..=100 unknown distribution). Residuals that
    // are near multiples of common size classes (10, 20, 25, 50) are reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize dead space: tiny leftovers (< 10) are almost unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward residuals in "harmonic" classes: divisible by 10 or 25.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 {
        score -= 4.0;
    }
    if post_residual % 50 == 0 {
        score -= 3.0;
    }

    // Perfect fit: strongly reward zero residual.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits the post residual exactly or well,
    // reward this bin; if next item nearly fits (within 2), small bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 2 {
                score -= 12.0;
            } else if slack <= 10 {
                score -= 5.0;
            }
        } else {
            // Next item cannot follow here; slight penalty proportional to gap.
            score += ((next_item_size - post_residual) as f64).min(15.0) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless residual waste would be huge).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Prefer tighter bins: deviation from mean residual.
    score += (pr - mean_residual).abs() * 0.05;

    // Prefer bins whose fill fraction is high (harmonic fraction thresholds).
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    if fill_frac > 0.75 {
        score -= 5.0;
    } else if fill_frac > 0.5 {
        score -= 2.0;
    }

    // Early stream: be more willing to spread out (penalize new-bin use less
    // implicitly by not over-rewarding old bins); late stream: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    // Mild penalty for opening a brand-new bin when decent fits exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0;
        // But if no open bin fits well (post residual would be tiny), allow it.
        if item_size > 60 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small nonzero gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residual that can still fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Pressure from many open bins: discourage spreading items.
    score += open_bins_count as f64 * 0.8;

    // Mild preference for bins tighter than the mean residual.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: attractive early, penalized once many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 40.0 + open_bins_count as f64 * 2.5 - progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: make empty bins moderately attractive
    // unless an existing bin offers a tight fit.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Late in the stream, opening new bins is cheap (few leftover items)
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 30.0 * progress;
        }
        // If next item is huge, a fresh bin is valuable
        if next_item_size >= 60 {
            score -= 20.0;
        }
        return score;
    }

    // --- 2-step lookahead core ---
    if next_item_size > 0 {
        // Perfect match: post_residual exactly fits the next item
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 40.0 / (1.0 + diff);

        // Penalize dead space that cannot hold the next item at all
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }

        // Bonus if post_residual could still fit a mid-size item later
        if post_residual >= 10 && post_residual >= next_item_size {
            score -= 5.0;
        }
    } else {
        // Last item: just minimize waste
        score -= 10.0;
    }

    // Relative to mean residual: prefer using bins with more space than average
    // (keeps tight bins free for small items)
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize very small post_residual (unusable dead space < 10)
    if post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space: post residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead coupling: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Crowding: when many bins are open, prefer consolidation; when few, opening is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = (open_bins_count as f64).ln() + 1.0;
    score += 2.0 * crowding * (1.0 - tightness);

    // Mean residual alignment: prefer bins near the mean residual (balanced usage).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: opening a fresh bin should only win when fits are poor
    // or the item nearly fills a bin alone.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        score = 60.0 + 40.0 * poor_fit - 20.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 50.0; // never open when a last-chance bin exists
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let x = post / cap; // normalized dead space
    let poly = x * x * (3.0 - 2.0 * progress) + x * (1.0 + 2.0 * progress * (1.0 - progress));
    score += 40.0 * poly * (0.5 + progress);

    // Reward tight fits more strongly as the stream progresses.
    let tightness = 1.0 - x;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: penalize if post_residual cannot host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            let slack = (post - nx) / cap;
            score -= 15.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 12.0 * (nx - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Mild penalty when many bins are open and this placement creates large dead space.
    score += 0.05 * open_bins_count as f64 * x * x;

    // Slight preference toward bins with below-average residual (consolidation).
    score += 0.1 * (post - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in (0,10) is nearly unusable
    // since items are >= 1; small residues are penalized super-linearly.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fit: strongly reward
    } else if post_residual <= 5 {
        score += 45.0; // tiny dead space: very bad
    } else if post_residual <= 15 {
        score += 18.0;
    } else if post_residual <= 30 {
        score += 4.0;
    } else if post_residual <= 50 {
        score -= 3.0;
    } else {
        score -= 8.0; // large residue keeps future options open
    }

    // Integer-division classes on post_residual (harmonic bands of C/4)
    let quarter = bin_capacity / 4;
    let band = post_residual / quarter.max(1);
    score -= band as f64 * 2.5;

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // next item fits: good, but partial fit leaves a new residue
            score -= (next_item_size as f64) * 0.35;
            let r2 = post_residual - next_item_size;
            if r2 <= 10 {
                score += 12.0; // resulting residue nearly dead
            }
        } else {
            // next item cannot use this bin's residue: mild penalty scaled by waste
            score += ((next_item_size - post_residual) as f64).min(40.0) * 0.4;
        }
    } else {
        // last item: prefer closing bins out completely
        if post_residual > 0 {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        if post_residual <= 10 && post_residual > 0 {
            score += 20.0; // ...but not if it creates near-dead space
        }
    }

    // New-bin candidate: neutral residual = capacity. Encourage opening a new
    // bin only when no open bin fits well; make the empty bin moderately
    // attractive so it wins exactly when fits are poor.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.55 + (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // room for the lookahead too
        }
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Slight pull toward bins with residuals near the mean (balanced packing).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space strongly (gaps < 10 are worthless)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits the post-residual exactly, reward heavily
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: penalize opening new bins when few bins are open,
    // encourage consolidation when many are open
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if nothing fits well elsewhere
        score += 30.0 + 20.0 * (1.0 - progress);
    } else {
        score -= 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins tighter than the mean residual (consolidation)
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Penalize post_residual that cannot fit next item but is small (dead space)
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // dead space for lookahead; worse when post_residual is tiny
            let dead = post_residual as f64;
            score += 12.0 * (1.0 - dead / bin_capacity as f64);
            // extra penalty if the dead space is below the minimum item size
            if post_residual < 10 {
                score += 15.0;
            }
        } else {
            // next item fits: mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Reward tight fits overall
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize spreading across many open bins slightly; encourage filling existing bins
    score += 0.5 * open_bins_count as f64;

    // Coupling with mean residual: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: penalize opening a new bin unless current fit is very poor
    if bin_residual == bin_capacity {
        score += 25.0;
        // but if next item is large and this item fits perfectly in fresh bin, soften
        if post_residual == bin_capacity - item_size && next_item_size > 0
            && (bin_capacity - item_size) >= next_item_size {
            score -= 15.0;
        }
    }

    // Slight stream progression adaptation: later in stream, be greedier about tight fits
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let residual_f = bin_residual as f64;
    let fill_ratio = 1.0 - (post_residual as f64) / residual_f.max(1.0);
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that likely becomes unusable (items >= 10 traditionally,
    // but sizes unknown: penalize residuals below typical small-item scale).
    if post_residual > 0 {
        let dead = (post_residual as f64) / (bin_capacity as f64);
        if dead < 0.15 {
            score += 25.0 * (0.15 - dead);
        } else {
            score -= 4.0 * dead; // larger leftover may still be useful
        }
    }

    // Perfect fit gets a huge bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits the post-residual exactly or well, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        let next_fit = (next_item_size as f64) / (post_residual as f64).max(1.0) as f64;
        score -= 18.0 * next_fit;
        if next_item_size as u32 == post_residual {
            score -= 40.0; // chain of perfect fits
        }
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // Next item won't fit here anyway; mild penalty for leaving awkward gap.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Global state: many open bins with high mean residual -> prefer reusing existing bins
    // (reduce fragmentation) rather than opening new ones.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if open_bins_count > 2 {
        score -= 8.0 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual spread.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly
        // (large post_residual relative to item) or late in stream with few bins.
        let waste = (post_residual as f64) / (bin_capacity as f64);
        score += 20.0; // base reluctance to open new bin
        score -= 60.0 * waste; // but a fresh bin keeps a big usable residual
        score += 10.0 * progress; // late in stream, avoid opening bins
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: new bin is fine
        }
    }

    // Mild preference for fuller bins overall (best-fit flavor).
    score -= 5.0 * (1.0 - (bin_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping.
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling: residual quality matters more as stream progresses.
    score += 12.0 * progress * norm_pr * (1.0 - norm_pr);

    // Penalize large dead space quadratically relative to mean residual.
    let dead = (pr - mean_residual).max(0.0);
    score += 0.05 * dead * dead / cap;

    // Reward tight fits (post_residual near zero) with a smooth bonus.
    score -= 15.0 * (-2.0 * norm_pr).exp();

    // Last-chance bin: strongly favor using it to avoid opening new bins.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - (next_item_size as f64) / cap);
    }

    // Mild penalty for spreading across many open bins early on.
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues near 0 are good, mid-range are dead space.
    let r = post_residual % 10;
    let residue_penalty = match r {
        0 => -6.0,
        1 | 9 => 2.0,
        2 | 8 => 4.0,
        3 | 7 => 6.0,
        4 | 6 => 8.0,
        _ => 10.0, // r == 5: worst dead space class
    };
    score += residue_penalty;

    // Integer division thresholds on post_residual: small leftovers are excellent,
    // mid leftovers (25..60) are dangerous dead zones.
    if post_residual <= 10 {
        score -= 8.0;
    } else if post_residual <= 25 {
        score -= 3.0;
    } else if post_residual > 40 && post_residual <= 60 {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // Harmonic class match: next item leaves a small residue again.
            let nr = (post_residual - next_item_size) % 10;
            if nr <= 2 {
                score -= 7.0;
            }
            score -= (post_residual - next_item_size) as f64 * 0.08;
        } else {
            // Next item cannot use this bin's leftover: penalize large leftovers more.
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bins early or when mean residual is fragmented.
        score -= 4.0 + 10.0 * (1.0 - progress) + (mean_residual / bin_capacity as f64) * 6.0;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Coupling with mean residual: avoid bins far below the mean when many bins are open.
    score += (mean_residual - bin_residual as f64).abs() * 0.03
        + (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Exact fill is always best.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Tight fits (small waste relative to item) get a moderate reward.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // If next item could exactly fill this bin's post-residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit in the leftover: penalize dead space creation.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, opening new is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 / (1.0 + progress);
    score += bin_pressure * 0.05;

    // New-bin candidate: only attractive when it enables a good future fit or all fits are poor.
    if bin_residual == bin_capacity {
        // Base mild penalty so we prefer existing bins with good fits.
        score += 15.0;
        // If no open bin fits tightly (item barely fits anywhere), opening new is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Reserve new bin if next item is large and current item is small.
        if next_item_size >= 60 && item_size <= 30 {
            score -= 20.0;
        }
        // Late in stream with many bins, avoid opening more.
        if progress > 0.7 && open_bins_count > 5 {
            score += 20.0 * progress;
        }
    }

    // Mild preference for bins tighter than the mean residual (better packing).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.94;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item (1..100, use 10 as soft floor).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            // wasting space the next item could have used
            score += 10.0;
        }
    }

    // Prefer bins with below-mean residual (consolidate emptier bins? no: fill tighter bins first).
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 12.0 * dev;

    // Discourage spreading across many open bins; encourage filling existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.5 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // New-bin candidate handling: empty bin should only win when the fit elsewhere is poor.
    if bin_residual == bin_capacity {
        // base penalty so a new bin only wins via strong lookahead/exact-fit signals
        score += 55.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 35.0;
        }
        // late in the stream, opening new bins is fine since leftovers are wasted anyway
        score -= 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let next = next_item_size as f64;

    let mut score = pr as f64;

    // Non-linear polynomial coupling: waste weight grows with stream progress
    let waste_weight = 1.0 + 2.0 * progress * progress + 1.5 * progress;
    score += waste_weight * norm_pr * norm_pr * cap * 0.5;

    // Reward tight fits (small post residual) more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Penalize dead space unusable by lookahead item
    if next > 0.0 && pr < next {
        let gap = (next - pr) / cap;
        score += gap * (30.0 + 40.0 * progress) * (1.0 + 0.5 * norm_pr);
    }

    // Reward leaving room for the next item
    if next > 0.0 && pr >= next {
        let fit_quality = 1.0 - ((pr - next) / cap);
        score -= fit_quality * 8.0 * (0.5 + progress);
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Mild preference for bins below mean residual (balance load)
    score += 0.1 * (mean_residual - pr) * (1.0 - progress);

    // Penalize very low occupancy bins early (avoid scattering)
    let occ = item / cap;
    score -= occ * occ * 5.0 * (1.0 - progress);

    // Slight penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 5.0 + 0.05 * open_bins_count as f64 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals near "nice" capacity fractions
    // (multiples of 10, quarters of capacity) are reusable dead space.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual divisible by 10 -> highly reusable residual.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    // Class B: divisible by 5 only.
    else if post_residual % 5 == 0 {
        score -= 3.0;
    }
    // Class C: near a multiple of 10 (within 2) -> slightly penalize.
    else {
        let dist10 = ((post_residual as i32 % 10).abs() as f64).min((10 - post_residual % 10) as f64);
        score += dist10 * 0.8;
    }

    // Exact fit is always superb.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Integer-division threshold classes on post_residual relative to capacity quarters.
    let quarter = bin_capacity / 4;
    if post_residual <= quarter {
        // Very small residual: dead space risk unless exact or tiny next item fits.
        score += 8.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    } else if post_residual <= 2 * quarter {
        score += 1.0;
    } else if post_residual <= 3 * quarter {
        score -= 2.0;
    } else {
        score -= 4.0;
    }

    // Lookahead harmonic class: does next item land in a "complementary" residue class?
    if next_item_size > 0 {
        let sum = item_size + next_item_size;
        if sum == bin_capacity {
            score -= 20.0;
        } else if sum % 10 == 0 && sum <= bin_capacity {
            score -= 8.0;
        }
        // Next item fits exactly into resulting residual: strong reward.
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size > post_residual {
            // Next item won't fit here: penalize if this bin is a last chance.
            if fitting_bins_count == 1 {
                score += 6.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early stream: allow opening bins more freely.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // Many open bins with high mean residual: discourage another bin.
        score += (open_bins_count as f64) * 1.5;
        if mean_residual > cap * 0.35 {
            score += 10.0;
        }
        // Small current item: keep new-bin option cheap (better long-term packing).
        if item_size <= cap / 4 {
            score -= 8.0;
        }
    }

    // Mild preference for tighter bins overall.
    score += (mean_residual - post).clamp(-20.0, 20.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (>=1, but realistically >=10)
    // can use are wasted. Penalize "awkward" residuals heavily.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // A residual is dead if smaller than the smallest plausible item.
    let min_item = 10.0f64.min(cap);
    if post > 0.0 && post < min_item {
        score += 60.0; // unusable sliver
    } else if post > 0.0 && post < 20.0 {
        score += 15.0; // near-dead gap: only tiny items could fit
    }

    // Reward near-perfect fits super-linearly.
    if post == 0 {
        score -= 40.0;
    } else if post <= 5 {
        score -= 25.0;
    } else if post <= 10 {
        score -= 12.0;
    }

    // Fractional tightness bonus: prefer bins where the item fills a large share
    // of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Last-chance pressure: if this is the only fitting bin, using it avoids
    // opening a new bin — reward, scaled by how much dead space would be created elsewhere.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 0.1 * mean_residual;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer tight packing
    // into existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // New-bin candidate: make it attractive only when the current bin would leave
    // a large awkward gap or the fit is poor. A fresh bin has full residual; its
    // post_residual equals capacity - item_size, which is naturally large, so
    // penalize it unless existing bins would waste a lot.
    if bin_residual == bin_capacity {
        let fresh_penalty = 25.0 + 0.35 * post;
        // If no existing bin fits well (post_residual small), opening fresh is fine.
        let poor_existing = post > 30.0;
        if poor_existing {
            score -= fresh_penalty - 0.35 * post; // net small penalty; fresh bin competitive
        } else {
            score += fresh_penalty; // keep item in an existing bin
        }
        // Late in the stream, be more willing to open bins (avoid stranding).
        score -= 15.0 * progress;
    }

    // Mild preference for bins with residuals close to the mean (balanced packing).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        score -= 200.0 - gap * 0.5; // exact match strongly favored
    } else if next_item_size > 0 {
        // next item can't use this bin's leftover: penalize dead space
        score += next_item_size as f64 * 0.1;
    }

    // Compare leftover to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin bonus: only one bin fits, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize opening a new bin when open bins exist with reasonable residual
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 80.0 + mean_residual * 0.2;
    }

    // Late in stream: be more conservative with new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 1.6 * tightness * tightness * (item_size as f64);

    // Penalize dead space: very small post_residual that is hard to reuse
    // (below typical small item size) is waste unless it is exactly tight.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.25 * (next_item_size as f64);
        } else {
            score += 2.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or their residuals are poor fits.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        score -= 4.0;
        if mean_residual > 40.0 {
            score -= 6.0; // open bins are fragmented; fresh bin is fine
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score += 3.0; // fresh bin still good for next item anyway
        }
        if fitting_bins_count > 0 {
            score += 9.0 + crowded * 0.5; // discourage skipping usable bins
        }
    }

    // Time horizon: late in the stream, avoid leaving many scattered residuals;
    // consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (mean_residual - post_residual as f64) * 0.35;

    // Mild preference to fill bins with larger residual spread consistency.
    if (bin_residual as f64 - mean_residual).abs() < 5.0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual (dead space fraction)
    let pr = post_residual as f64 / cap;

    // Non-linear polynomial coupling: dead space penalized more as stream progresses
    let dead_space_penalty = pr * pr * (1.0 + 3.0 * progress);
    score += dead_space_penalty * cap;

    // Reward tight fits with smooth quadratic term
    let tightness = 1.0 - pr;
    score -= 2.0 * tightness * tightness * (1.0 + progress);

    // Last-chance bonus: strongly prefer the only bin that fits (smooth scaling)
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Penalize opening a new bin when open bins already fit (new-bin candidate detection)
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).sqrt();
        // But if next item is large and this item is small, slight discount for fresh bin
        if next_item_size > 0 {
            let nxt = next_item_size as f64 / cap;
            score -= 6.0 * nxt * nxt;
        }
    }

    // Lookahead: reward bins whose post-residual matches the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        let match_factor = 1.0 - (diff / cap).min(1.0);
        score -= 3.0 * match_factor * match_factor;
    }

    // Mild penalty when this bin's residual is far above mean residual (outlier bin)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev * dev;

    // Encourage consolidation as bins accumulate
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity split into eighths.
    // Residuals in the lowest class (tiny dead space) are rewarded strongly.
    let eighth = bin_capacity as f64 / 8.0;
    let pr = post_residual as f64;
    let class = (pr / eighth).floor().min(7.0);

    // Reward small post-residuals super-linearly within their class.
    score -= (7.0 - class) * 6.0;

    // Exact fits (post_residual in {0, 1}) are gold.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual == 1 {
        score -= 25.0;
    }

    // Harmonic modulo logic on post_residual: residues that pair well with
    // common item sizes (multiples of 5 and 10) are more reusable.
    let res_mod = post_residual % 10;
    if res_mod == 0 {
        score -= 8.0;
    } else if res_mod == 5 {
        score -= 4.0;
    } else {
        score += res_mod as f64 * 0.3;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let nxt_left = post_residual - next_item_size;
            score -= 10.0 * (1.0 - nxt_left as f64 / bin_capacity as f64);
        } else {
            // Next item would not fit here: penalize wasting a good residual.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Penalize leaving a residual that is too small for the minimum item size.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Fresh empty bin: only attractive when no open bin fits well
    // (i.e., mean residual is small relative to item) — otherwise discourage.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / mean_residual.max(1.0);
        if pressure > 1.0 {
            score -= 10.0 * (pressure - 1.0).min(2.0);
        } else {
            score += 14.0;
        }
    }

    // Mild stream-phase modulation: early on, be more willing to open bins
    // (keep flexibility); late, consolidate tightly.
    let phase = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= phase * 5.0;
    } else {
        score += (1.0 - phase) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (gaps too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (post residual near zero relative to item).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 20.0;
        } else if gap < 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: dead space penalty scaled by gap.
        score += 5.0;
    }

    // New-bin candidate handling: neutral baseline, slightly penalized so only
    // genuinely poor fits among open bins trigger opening a new bin.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear penalty
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward post_residual matching next item exactly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        // Perfect chain fit: strongly reward
        if diff == 0.0 {
            score -= 40.0;
        } else if pr >= nxt {
            // next item can still fit here: mild reward proportional to closeness
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // dead space relative to next item: penalize
            score += 8.0 * (diff / bin_capacity as f64);
        }
        // reward post_residual that leaves space usable for typical items (>= min size 1)
        if pr > 0.0 && pr < 10.0 {
            score += 12.0; // tiny unusable sliver penalty
        }
    } else {
        // last item: just minimize waste
        score += (post_residual as f64).powi(2) / (bin_capacity as f64);
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious tight bins
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 5.0 * (pr - mean_residual) / (bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless current fit is terrible
    if bin_residual == bin_capacity {
        // new empty bin: post_residual = capacity - item_size
        // penalize unless item is huge and no tight option exists
        score += 15.0;
        if item_size >= 60 {
            score -= 10.0;
        }
        if next_item_size > 0 && (bin_capacity - item_size) as f64 >= next_item_size as f64 {
            score -= 5.0;
        }
    }

    // Stream progression: early on, be more willing to open bins (explore)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Too many open bins: discourage fragmentation
    if open_bins_count > 8 {
        score += 2.0 * ((open_bins_count as f64 - 8.0).min(10.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core fit quality: reward tight fits (low post residual) non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Lookahead: reward bins whose post-residual can host the next item (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 12.0 + 6.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // Penalize creating dead space the next item cannot use.
            let dead = post_residual as f64;
            score += dead * 0.25 * (dead / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when the item is large relative
    // to residuals or no good fit exists. Base penalty to discourage bin sprawl.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let pressure = (open_bins_count as f64).ln().max(1.0);
        let mut new_bin_score = 55.0 + 30.0 * (1.0 - fill_ratio) + 4.0 * pressure;

        // Late in the stream, avoid opening new bins (waste at the tail).
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += 20.0 * progress;

        // If next item would fit in a fresh bin alongside this one, mild discount.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 10.0;
        }
        // If many bins already fit the item, opening a new one is clearly worse.
        new_bin_score += 15.0 * fitting_bins_count as f64;

        score = new_bin_score;
    } else {
        // Reward bins that are already partially filled and below mean residual
        // (consolidate emptier bins, keep fuller ones for small items).
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;

        // Slight bonus for filling bins near exhaustion (close them out).
        if post_residual < 10 {
            score -= 15.0;
        } else if post_residual < 20 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling of post-residual with stream progress
    let poly = 1.0 + 0.8 * progress - 1.6 * progress * progress + 0.8 * progress * progress * progress;
    score *= poly;

    // Penalize large post-residual more strongly late in the stream
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth quadratic bonus
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: reward bins whose post-residual can fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 8.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 6.0 * (post_residual as f64 - next_item_size as f64).abs() / cap;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 18.0 * (0.5 + 0.5 * progress);
    }

    // Slight preference for bins below mean residual (consolidating fullness)
    score += 5.0 * ((bin_residual as f64 - mean_residual) / cap);

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity split into 4 quartile classes.
    let q = post_residual / (bin_capacity / 4);
    match q {
        0 => score -= 12.0, // near-perfect fill: post_residual < 25
        1 => score += 0.0,
        2 => score += 6.0,
        _ => score += 14.0, // wasteful large residual
    }

    // Exact-fit bonus via harmonic residue classes.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual % 10 == 0 {
        score -= 6.0; // residual divisible by 10 is re-usable by common sizes
    } else if post_residual < 10 {
        score -= 10.0; // dead space below min item size
    } else {
        score += 4.0; // awkward non-harmonic residual
    }

    // Lookahead: does next item fit harmonically into post_residual?
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 18.0; // perfect chain
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 8.0;
            }
            score += (gap as f64) * 0.15;
        } else {
            score -= 2.0; // next item won't fit here anyway; mild bonus for keeping room
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // unless current bin would leave a badly fragmented residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = bin_capacity as f64 * 0.55 + progress * 10.0;
        if open_bins_count == 0 {
            new_bin_score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= 50 {
            new_bin_score -= 5.0; // big next item: fresh bin useful
        }
        return new_bin_score;
    }

    // Slight preference for tighter bins overall.
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual that is still usable).
    score -= (bin_capacity - post_residual.min(bin_capacity)) as f64 * 0.05;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins.
    score += open_bins_count as f64 * 0.8;

    // Mean residual coupling: if open bins already have large average residual,
    // discourage spreading; prefer the bin that reduces fragmentation.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.3;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.5;
        // If nothing else fits well, allow new bin: soften when fitting bins are scarce.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins whose residual is exactly consumed.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the new residual
    // (chain of perfect fits), penalize dead space the next item cannot use.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits but leaves further slack; mild penalty proportional to slack
            score += 0.25 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot fit into this residual: dead space penalty
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare residual against mean residual across open bins.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin (new bin would have residual = capacity - item_size).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and would leave a highly usable residual (post_residual >= next_item_size).
    if bin_residual == bin_capacity {
        score += 400.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 350.0;
        }
        if item_size >= 50 {
            score -= 100.0;
        }
    }

    // Late in the stream: consolidate, avoid spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * open_bins_count as f64 * progress;

    // Small residual is generally good (tight packing), scaled slightly.
    score += 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else {
            score += 10.0;
        }
        // Perfect chain: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // New-bin candidate logic: only attractive when open bins are crowded
    // or the fit here is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.5;
        let mut new_bin_score = 45.0 - 10.0 * progress + crowd;
        if poor_fit { new_bin_score -= 15.0; }
        if next_item_size > 0 && next_item_size >= item_size && bin_capacity >= next_item_size {
            new_bin_score -= 8.0; // fresh bin can chain large items
        }
        score = new_bin_score;
    } else {
        // Prefer fuller bins among open bins (best-fit bias).
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 12.0 * fill;
    }

    // Mild penalty for opening many bins with slack.
    if open_bins_count > 3 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score += 0.05 * (mean_residual - 30.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    // Non-linear interaction: waste penalty grows super-linearly as stream progresses
    let waste = (1.0 - x).powi(3);
    score += 40.0 * progress * waste;

    // Reward tight fits with a smooth quadratic bonus
    score -= 25.0 * (1.0 - x) * (1.0 - x) * (0.5 + 0.5 * progress);

    // Penalize leaving residuals that are likely unusable for future items
    let next_fits = if next_item_size > 0 && next_item_size as f64 <= pr { 1.0 } else { 0.0 };
    score -= 12.0 * next_fits * (1.0 - progress);

    // Smooth coupling with mean residual: prefer bins near the mean state
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Last-chance bonus (smooth, no hard constant branching)
    let last_chance = 1.0 / fitting_bins_count as f64;
    score -= 15.0 * last_chance * (1.0 - x);

    // Penalize opening new bins when open bins exist late in the stream
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * progress + (open_bins_count as f64).sqrt() * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover lies in small
    // dead-space classes (1..=9) are nearly wasted, penalize them.
    let dead = post_residual < 10;
    if dead {
        score += 25.0;
    } else {
        // Reward post-residuals that are "harmonic" multiples of common size
        // classes (divisible by 10 or 20), since future items may tile them.
        if post_residual % 10 == 0 {
            score -= 8.0;
            if post_residual % 20 == 0 {
                score -= 4.0;
            }
        }
    }

    // Integer-division threshold on post_residual: leftovers below the
    // smallest plausible item class (<=10) are pure loss.
    let dead_class = post_residual / 10; // 0 => dead space
    score += (10 - dead_class.min(10)) as f64 * 0.8;

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post % 10 == 0 {
                score -= 10.0;
            }
            score += (nxt_post as f64) * 0.3;
        } else {
            // next item cannot follow here; slight penalty proportional to gap
            score += ((next_item_size - post_residual) as f64) * 0.2;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: empty bin should only win when existing bins are bad.
    if bin_residual == bin_capacity {
        // Penalize new bins mildly; escalate when many bins are already open
        // and mean residual is healthy (we should keep filling them).
        score += 20.0 + 2.0 * (open_bins_count as f64).sqrt();
        if mean_residual > 30.0 {
            score += 15.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    } else {
        // Reward filling bins with high residual relative to mean (tightening).
        if (bin_residual as f64) > mean_residual {
            score -= 3.0;
        }
    }

    // Modulo harmonic bonus: item size classes that divide the residual evenly.
    if item_size > 0 && bin_residual % item_size == 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space more harshly than large residuals.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny dead gap: worst outcome
        } else if post_residual < 20 {
            score += 18.0;
        } else if post_residual < 30 {
            score += 8.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Dead space is only truly wasted if the next item cannot use it.
    if next_item_size > 0 {
        if post_residual > 0 && (next_item_size as f64) > post_residual as f64 {
            score += 12.0; // residual too small for lookahead item
        } else if (next_item_size as f64) <= post_residual as f64 {
            score -= 10.0; // residual is usable by next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage proliferation when many open.
    score += (open_bins_count as f64) * 0.5;

    // Prefer bins tighter than the current mean residual (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight preference for keeping new-bin option open early in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * progress; // new bin penalized, less so late in stream
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - diff / bin_capacity as f64).max(0.0);

        // Perfect 2-chain bonus: item + next item exactly fill the bin
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item fits leaving small unusable gap -> penalize lightly
        else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 8.0;
        }
        // Next item won't fit here anyway
        if next_item_size > post_residual {
            score += 3.0;
        }
    }

    // Penalize dead space relative to mean residual (creating unusable gaps)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize slightly so we prefer good fits into open bins,
    // but allow opening when post_residual would be large (fresh space useful)
    if bin_residual == bin_capacity {
        score += 20.0 - 0.2 * post_residual as f64;
    }

    // Early stream: be more conservative with open bins, favor packing density
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized post-residual waste, with nonlinear squashing.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize bins whose residual becomes awkwardly small (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting a good residual.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals flexible); late in the stream, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins already open or late in stream,
        // but allow early when mean residual is high (fragmentation).
        score += 20.0 + 30.0 * progress;
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
        if mean_residual > 30.0 && progress < 0.5 {
            score -= 10.0;
        }
    }

    // Prefer bins with below-mean residual (consolidate fullness).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Slight preference for more-open-bin environments to consolidate.
    score -= 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with smooth polynomial coupling to stream progress.
    // Early on, prefer tight fits less aggressively; later, dead space matters more.
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Non-linear penalty for very small residuals (dead space), smooth in norm_pr.
    let dead = (1.0 - norm_pr).powi(3) * (norm_pr * norm_pr);
    score -= 18.0 * dead;

    // Reward exact-ish fits: smooth gaussian-like term around small post_residual.
    score -= 12.0 * (-(norm_pr * norm_pr) / 0.02).exp();

    // Last-chance bonus: strongly favor using this bin if it's the only fitting one.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let smooth_fit = 1.0 / (1.0 + (pr - next_item_size as f64).abs());
        score -= 6.0 * fits_next * smooth_fit;
        // Penalize leaving residual just barely below next item (wasted near-fit).
        let near_miss = ((next_item_size as f64 - pr) / cap).powi(2);
        score += 10.0 * near_miss * (1.0 - fits_next);
    }

    // Mild pressure to consolidate: fewer open bins relative to residual mass.
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Prefer bins with residual above the mean (balance across bins).
    score += 0.15 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space uselessness
    // Small residuals (< smallest plausible item) are dead space
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Modulo classes on post_residual (capacity = 100): residual in {50, 60, 70, 80, 90}
    // pairs well with common item sizes -> reward "recyclable" residuals
    let pr = post_residual as i64;
    let recyclable = (pr % 10 == 0) && pr >= 20;
    if recyclable {
        score -= 6.0;
    }

    // Coupling with lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            // penalize leaving awkward slack for the next item
            score += slack as f64 * 0.5;
            if slack < 10 {
                score += 15.0;
            }
        } else {
            // next item won't fit here anyway; residual quality matters more
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 20.0 * progress;
    }

    // New-bin candidate: make opening a new bin costly unless current bins are crowded
    if bin_residual == bin_capacity {
        let crowded = mean_residual < (item_size as f64) * 1.2;
        if crowded {
            score -= 30.0;
        } else {
            score += 45.0;
        }
    }

    // Prefer fuller bins (small residual) mildly
    score += (bin_residual as f64) * 0.05;

    // Many open bins: discourage spreading
    if open_bins_count > 4 {
        score += 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no realistic item (>=1) can use
    // are pure waste; gaps below a typical small item are near-waste.
    if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 25.0; // unusable sliver => heavy penalty
    } else if post_residual < 20 {
        score += 10.0; // poor gap
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0; // next item won't fit here either way
    }

    // New-bin candidate: penalize opening a fresh bin unless current fits are bad.
    if bin_residual == bin_capacity {
        let baseline = (bin_capacity - item_size) as f64;
        let mut alt = baseline + 0.6 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            alt -= 30.0;
        }
        if post_residual < 10 && post_residual > 0 {
            alt += 25.0;
        }
        score += 12.0 + 0.15 * (bin_capacity as f64 - baseline);
        let _ = alt;
    }

    // Slight late-stream conservatism: consolidate as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: mildly penalized by default so we prefer existing bins,
    // but the penalty shrinks late in the stream or when few bins fit.
    if bin_residual == bin_capacity {
        let openness = (step_index as f64) / (total_items.max(1) as f64);
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 18.0 - 12.0 * openness + 20.0 * scarcity;
        return score;
    }

    // 2-step lookahead coupling: reward post_residual that matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            // Next item can fit here: reward tight matching.
            let match_quality = 1.0 - ((post_residual as f64 - nxt) / bin_capacity as f64);
            score -= 14.0 * match_quality;
        } else {
            // Dead space: next item cannot use the leftover; penalize proportionally.
            let waste = (nxt - post_residual as f64) / bin_capacity as f64;
            score += 22.0 * waste;
        }
    }

    // Penalize leaving residual far below mean residual (fragmenting small bins).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.06 * dev;

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Slight preference for tighter fits overall.
    score -= 0.05 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
