            score += 30.0;
        }
        // If next item exactly matches post residual, big bonus.
        if next_item_size == post_residual {
            score -= 250.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; let tight fits in existing bins win.
        score += 50.0 + open_bins_count as f64 * 2.0;
        // But if many bins already open and mean residual is low, opening fresh is fine.
        if mean_residual < 20.0 {
            score -= 60.0;
        }
    }

    // Prefer bins with residual below mean (consolidate emptier space usage).
    if (bin_residual as f64) < mean_residual {
        score -= 20.0;
    } else {
        score += 10.0;
    }

    // Time horizon: late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 80.0 * progress;
    } else {
        score -= 30.0 * progress;
    }

    // Prefer bins with larger residual among comparable fits (waste big spaces first).
    score += 0.15 * bin_residual as f64;

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
