    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Stream-progress coupling: tighten preference as stream advances.
    score *= 1.0 + 0.35 * progress * (1.0 - progress) * 4.0 * 0.25;

    // Reward filling bins deeply relative to current mean residual state.
    let fill = (item_size as f64) / cap;
