        } else {
            score -= 3.0 * (1.0 - (nxt - pr).abs() / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 + progress);
    }

    // New-bin candidate: mildly penalize early, allow late in stream or when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 6.0 * (1.0 - progress) * (1.0 - crowd) + 2.0;
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 4.0; // fresh bin can serve the lookahead item
        }
    }

    // Mean-residual coupling: penalize diverging from the fleet's residual state.
    score += 0.05 * (pr - mean_residual).abs();

    score
}

