pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer bins with small post residual (tight fit), scaled by fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score += (post_residual as f64 / bin_capacity as f64) * 40.0 * (1.0 - fill);

    // Reward tight fits: quadratic penalty on wasted space.
    let waste = post_residual as f64;
    score += 0.02 * waste * waste / bin_capacity as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for leaving a large unusable hole.
            score += 0.05 * (next_item_size as f64 - post_residual as f64).min(50.0);
        }
    }

    // Penalize opening a new bin when open bins already have plenty of room,
    // but allow it when existing residuals are small (fragmented state).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 12.0;
        if mean_residual > (item_size as f64) * 1.2 {
            score += 20.0; // existing bins comfortably fit; don't open new
        } else if fitting_bins_count == 0 {
            score -= 30.0; // nothing fits; new bin required
        }
        // Early in the stream, be more willing to open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    } else {
        // Favor bins whose residual deviates from mean (consolidate similar holes).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Prefer filling bins that are already heavily loaded (fewer partially-filled bins remain).
    let load = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * load;

    // Slight preference to keep the number of open bins from exploding late in stream.
    score += 0.3 * open_bins_count as f64 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual (tight fit).
    let mut score = pr;

    // Smooth polynomial penalty on dead space: small-but-nonzero residuals are
    // least useful; large residuals remain reusable. Penalize the "dead zone"
    // via a smooth bump centered around a fraction of capacity that tightens
    // as the stream progresses.
    let dead_center = 0.15 + 0.10 * t;
    let bump = ((norm_pr - dead_center) / 0.12).powi(2);
    let dead_penalty = 12.0 * (-bump).exp() * (1.0 + 0.5 * t);
    score += dead_penalty;

    // Reward very tight fits (post residual near zero) with smooth coupling.
    let tight = (-norm_pr * 8.0).exp();
    score -= 8.0 * tight * (1.0 + 0.6 * t);

    // Lookahead coupling: if next item fits into post_residual, this is a
    // valuable bin; smooth polynomial interaction between norm_pr and next size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if pr >= nx { 1.0 } else { 0.0 };
        let slack = (pr - nx) / cap;
        let lookahead_bonus = fits_next * (1.0 - slack).max(0.0) * 6.0 * (1.0 - t);
        score -= lookahead_bonus;
        // If next item cannot fit here, mildly penalize wasting space now.
        score += (1.0 - fits_next) * 1.5 * (1.0 - t);
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (smooth reward scaled by scarcity).
    if fitting_bins_count <= 1 {
        score -= 15.0 * (1.0 + 0.5 * (1.0 - t));
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Its post_residual is large; add a mild exploration cost that decays as
    // more bins are open, so a new bin is chosen only when open bins fit poorly
    // (their dead-space penalties will dominate instead).
    if bin_residual == bin_capacity {
        score += 4.0 + 0.5 * open_bins_count as f64;
    } else {
        // Slight preference for bins already below mean residual (balancing).
        score += 0.05 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement (integer division buckets of 10)
    let post_class = post_residual / 10;
    let next_class = if next_item_size > 0 { next_item_size / 10 } else { 0 };

    // Reward when the next item's class matches the post-residual class (perfect harmonic fit)
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        // tight packing: reward small gap after placing next item
        score -= (10.0 - (gap % 10) as f64) * 0.5;
        if gap == 0 {
            score -= 30.0; // exact fit with lookahead
        }
    }

    // Penalize dead space: residuals in awkward classes (1..=9 units) are hard to fill
    let rem = post_residual % 10;
    if post_residual > 0 && rem != 0 {
        score += (10 - rem) as f64 * 0.8;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bin would leave tiny unusable residual
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin useful for a stream of similar items
        }
        if fitting_bins_count > 0 && post_residual < 20 {
            score -= 30.0; // allow new bin when existing fit would be poor anyway
        }
    }

    // Progress-based modulation: late in stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64).abs() * 0.1 * progress;

    // Modulo coupling between post_residual and capacity fraction
    let quarter = bin_capacity / 4;
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A leftover gap is "unusable" if smaller than the minimum item size (1..100 unknown,
    // so treat gaps < 10 as risky, gaps < 20 as mildly risky).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 4.0 * (10 - post_residual) as f64;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when this bin's fit is poor
    // (large post_residual waste relative to capacity) or no tight option exists.
    if bin_residual == bin_capacity {
        // Base new-bin cost; slightly cheaper when many bins are open and residuals are high.
        score += 150.0;
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score -= 8.0 * pressure;
        if mean_residual > 40.0 {
            score -= 20.0;
        }
    }

    // Lookahead: if next item would fit the post-residual exactly, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 25.0; // would create dead space after next item
    }

    // Mild open-bins pressure: discourage spreading across many bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Prefer tighter fits overall (small relative waste).
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching:
    // Reward bins whose post-residual exactly matches the next item size.
    if next_item_size > 0 && next_item_size <= post_residual {
        let exact = (post_residual as f64 - next_item_size as f64).abs();
        score -= 60.0 / (1.0 + exact);
        // Strong bonus for a perfect 2-chain (post_residual == next_item_size).
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize leaving dead space relative to mean residual.
        let dead = post_residual as f64 - next_item_size as f64;
        score += 0.5 * dead.max(0.0);
    }

    // Compare post_residual against mean residual: prefer tightening loose bins.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin candidate unless it enables a perfect lookahead chain.
    if bin_residual == bin_capacity {
        let perfect_chain = next_item_size > 0 && post_residual == next_item_size;
        if perfect_chain {
            score -= 55.0;
        } else {
            score += 20.0 + 0.2 * open_bins_count as f64;
        }
    }

    // Mild pressure to pack tightly as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.1 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) more than linearly.
    let fit_ratio = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual that can't fit a typical small item.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Lookahead: bonus if the next item fits in the post residual (good chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: prefer filling existing ones rather than spreading.
    let open_pressure = (open_bins_count as f64) / ((total_items as f64).max(1.0) * 0.1 + 1.0);
    score += 4.0 * open_pressure;

    // Global residual balance: if this bin's residual is far below mean, packing here
    // consolidates large residuals elsewhere; slight reward for consolidating.
    let dev = (bin_residual as f64) - mean_residual;
    if dev < 0.0 {
        score += 0.05 * dev; // bins below mean residual get slightly lower score
    } else {
        score += 0.03 * dev;
    }

    // Time horizon: early in stream, be more selective (penalize mediocre fits);
    // late in stream, prioritize closing out bins.
    let progress = (step_index as f64) / (total_items as f64).max(1.0);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate: make empty bins moderately attractive only when the fit
    // into open bins is poor (large post_residual waste) — handled implicitly, but
    // add a mild penalty so we don't proliferate bins unnecessarily.
    if bin_residual == bin_capacity {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fits mildly; late in stream, reward tight fits strongly.
    let tightness = 1.0 - (pr / cap);
    score -= 18.0 * tightness * tightness * (0.5 + progress);

    // Penalize large dead space super-linearly.
    score += 0.35 * (pr / cap) * (pr / cap) * cap * (0.4 + 0.6 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward if next item could fill the post residual well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fill = nxt / pr.max(1.0);
            score -= 10.0 * fill * fill;
        } else {
            score += 4.0;
        }
    }

    // Mild penalty when bin residual deviates from mean residual (balance spread).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    // Slight preference to keep few open bins early, more freedom late.
    score += (open_bins_count as f64) * (0.3 - 0.2 * progress);

    // New-bin candidate: penalize slightly unless residuals of open bins are poor.
    if bin_residual == bin_capacity {
        score += 3.0 - 6.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: quarter-decile classes via integer division
    let item_class = item_size / 13;
    let next_class = next_item_size / 13;

    // Reward bins whose post-residual lands in a "harmonic" class
    // that a future item could plausibly fill exactly (small dead space).
    let post = post_residual;
    if post > 0 {
        // dead-space penalty grows superlinearly with unusable gap
        let gap = post as f64;
        score += 0.08 * gap * gap / bin_capacity as f64;
        // harmonic match: post_residual modulo classes
        if next_item_size > 0 && next_item_size <= post {
            // next item fits exactly or near-exactly into the gap
            let slack = post - next_item_size;
            score -= 6.0 * (1.0 - slack as f64 / 13.0).max(0.0);
            if slack == 0 {
                score -= 10.0;
            }
        }
        // penalize residuals in awkward classes (11..=19 dead zone)
        if post >= 11 && post <= 19 {
            score += 8.0;
        }
        // reward residuals that are multiples of common item classes
        if post % 13 == 0 || post % 17 == 0 {
            score -= 3.0;
        }
    } else {
        // perfect fill
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Many open bins: discourage fragmentation, prefer tighter bins
    let t = step_index as f64 / (total_items.max(1) as f64);
    let openness = open_bins_count as f64 / (total_items.max(1) as f64 * 0.5 + 1.0);
    score += openness * (bin_residual as f64 - item_size as f64) * 0.05;

    // Mean-residual coupling: prefer bins below mean residual (tighter fill)
    score -= (mean_residual - post as f64) * 0.15;

    // Class-affinity bonus: placing item next to a same-class neighbor region
    if item_class == next_class && next_item_size > 0 && next_item_size <= post {
        score -= 4.0;
    }

    // New-bin candidate handling: only attractive early or when current bin
    // would leave a large awkward gap.
    if bin_residual == bin_capacity {
        let early = 1.0 - t;
        let gap_penalty = if post > 0 { (post as f64).powf(1.3) * 0.4 } else { -20.0 };
        let new_bin_score = 30.0 * (1.0 - early) + gap_penalty - (fitting_bins_count as f64) * 8.0;
        score = new_bin_score + 40.0; // baseline offset so open bins usually win
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // keep new bin for a big lookahead item
            if next_item_size >= item_size + post.min(0) {
                score -= 5.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are worthless.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver penalty
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Penalize large post_residual less if a known next item can use it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 {
        score += (next_item_size as f64 - post_residual as f64).min(40.0);
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, allow it.
    let pressure = (open_bins_count as f64).ln() * 4.0;
    score += pressure;

    // New-bin candidate: make it attractive only when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // New bin is good for large items or when few fitting bins exist.
        score = 30.0 - 20.0 * tightness - 35.0 * (fitting_bins_count == 1) as i32 as f64;
        if post_residual == bin_capacity {
            // empty bin baseline: compare against mean residual of open bins
            score += mean_residual * 0.2;
        }
    }

    // Mild phase adjustment: later in stream, prefer consolidating (lower post_residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // 2-step lookahead: if the next item exactly matches post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item can still fit here after this placement — mild reward,
        // scaled by how well it fills the remaining space.
        let chain_fill = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * chain_fill;
    } else if next_item_size > 0 {
        // Next item won't fit in the leftover — penalize dead space creation.
        let waste = next_item_size as f64 - post_residual as f64;
        score += 0.3 * waste.min(40.0);
    }

    // Relative to mean residual: bins tighter than average are better to fill.
    score += 0.2 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    // Penalize leaving large residuals relative to capacity (dead space).
    score += 0.1 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If lookahead chain is perfect, a fresh bin is fine.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Late in the stream, prefer consolidation into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (open_bins_count as f64).recip().min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Penalize creating dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can still host the next item
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize dead space relative to gap size
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 + gap * 0.15;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let late = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins mildly so existing bins are preferred unless desperate
        score += 15.0 - 10.0 * pressure - 5.0 * late;
        // A new bin is good if it can host both this item and the next one
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 12.0;
        }
    }

    // Encourage balancing residuals toward the mean (avoid many tiny leftovers)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Slight preference for fuller bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.03;

    // Mild penalty for very small unusable leftovers
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post-residual (waste), modulated by stream progress.
    let mut score = pr * (1.0 + 1.5 * norm_pr * (0.5 + progress));

    // Reward tight fits: strong bonus when post_residual is small relative to capacity.
    score -= cap * 2.0 * (1.0 - norm_pr).powi(6);

    // Dead-space penalty: residuals too small for typical items are costly.
    let dead = (norm_pr - 0.15).max(0.0) * (norm_pr - 0.35).max(0.0);
    score += cap * 3.0 * dead * (1.0 - progress);

    // Lookahead coupling: if next item fits the post-residual, reward heavily.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 + 10.0 * progress;
    } else if next_item_size > 0 {
        // Penalize if post-residual leaves next item stranded near fit boundary.
        let gap = (next_item_size as f64 - pr) / cap;
        score += 8.0 * (-gap * 20.0).exp() * gap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize relative to how many bins are already open,
    // unless current open bins are nearly full (mean residual small).
    if bin_residual == bin_capacity {
        let mean_r_norm = mean_residual / cap;
        score += 20.0 + 10.0 * (open_bins_count as f64).ln();
        score -= 25.0 * (1.0 - mean_r_norm).powi(2) * (1.0 - progress);
    } else {
        // Mild bonus for bins below mean residual (less-full bins absorb waste better).
        score -= 3.0 * ((mean_residual - pr) / cap).max(0.0);
    }

    // Smooth progress interaction: later in stream, prefer consolidating into tight fits.
    score *= 1.0 + 0.3 * progress * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space quality classes
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: reward strongly
        score -= 40.0;
    } else if pr <= 10 {
        // Nearly perfect: small residual likely fillable by small items
        score -= 15.0;
    } else if pr <= 25 {
        // Usable zone for medium-small items
        score -= 5.0;
    } else if pr <= 50 {
        // Mid zone: neutral
        score += 0.0;
    } else {
        // Large residual wasted on a big item: penalize lightly
        score += 5.0;
    }

    // Modulo class: residuals divisible by common item sizes (10s, 5s) are reusable
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    } else if pr % 5 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0;
            // exact or near-exact lookahead match
            if pr - next_item_size <= 5 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here: slight penalty proportional to overflow
            score += ((next_item_size - pr) as f64) * 0.1;
        }
    } else {
        // Last item: prefer tightest packing, no future value in residual
        score -= 10.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening unless current bins have poor fit
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin
        score += 55.0;
        // If many bins already open and mean residual is high, discourage new bin
        score += mean_residual * 0.15;
        // Early stream: slightly cheaper to open bins (build diversity)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // Big items early benefit from a fresh bin
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    } else {
        // Existing bin: reward filling it more completely
        let fill_frac = (item_size as f64) / (bin_residual as f64);
        score -= 10.0 * fill_frac;
        // Crowding control: too many open bins -> prefer consolidation
        if open_bins_count > 8 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item are dead.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 25.0; // perfect closure is excellent
    }

    // Reward tight fits (post_residual close to 0 but still usable).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Last chance bin: strongly prefer it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0 * (post_residual as f64 / next_item_size as f64);
    }

    // Mean residual coupling: penalize bins far below mean residual (wasteful).
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate: neutral-ish baseline; only chosen when open bins look bad.
    if bin_residual == bin_capacity {
        score += 55.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets strongly preferred.
    score -= 2.0 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // 2-step lookahead: if the next item exactly fills post_residual, big reward.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            let slack_after_next = post - next;
            // Reward if next item fits with small leftover (chain fit).
            score -= 6.0 * (1.0 - slack_after_next / bin_capacity as f64);
            // Extra reward for perfect chain (post_residual == next_item_size).
            if slack_after_next == 0.0 {
                score -= 15.0;
            }
        } else {
            // Penalize leaving residual the next item cannot use.
            score += 4.0 * (next - post) / bin_capacity as f64;
        }
    }

    // Relative to mean residual: prefer bins that are tighter than average.
    score += 1.5 * (post_residual as f64 - mean_residual) / bin_capacity as f64;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Penalize opening a new bin when good open bins exist.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64;
        // But if next item is large and no open bin chains well, new bin is okay.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 8.0;
        }
    }

    // Late in stream: favor closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small but nonzero post_residual).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
        // Perfect chain: this item + next item exactly fill the bin.
        if item_size + next_item_size == bin_residual {
            score -= 25.0;
        }
    }

    // New-bin candidate: make it attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + 40.0 * progress;
        // Cheap new bin if the item is large and few bins fit it.
        if item_size > 60 && fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // If mean residual across open bins is large, reusing is better: penalize new bin.
        score += (mean_residual - item_size as f64).max(0.0) * 0.5;
        // Many open bins: prefer consolidation.
        score += open_bins_count as f64 * 1.5;
    } else {
        // Slight penalty scaled by fragmentation of this bin relative to mean.
        if (bin_residual as f64) < mean_residual * 0.5 {
            score += 5.0;
        }
        // Late in the stream, consolidate more aggressively.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress * fit_ratio;
    }

    // Reward filling bins nearly completely (post_residual near zero).
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling: post_residual interacts with stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    score += (pr_norm * pr_norm) * (1.0 + progress) * 30.0;
    score -= (pr_norm * pr_norm * pr_norm) * 20.0;

    // Tight fits rewarded, scaled smoothly by progress.
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Penalize dead space that no plausible next item can use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.5 + 2.0 * progress);
        } else {
            score -= (pr - nxt).min(30.0) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    }

    // Mild pressure toward consolidating into fewer bins.
    score += (open_bins_count as f64).ln().max(0.0) * pr_norm * 3.0;

    // Slight preference for bins with residuals above the mean (keeps spread balanced).
    score += (mean_residual - pr) * 0.05;

    // New-bin candidate: penalize mildly early, allow late in stream only for large items.
    if bin_residual == bin_capacity {
        let base = 40.0 - 25.0 * progress;
        score += base + (item_size as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a "usable"
    // class (large enough for typical future items) are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: leftover too small to host a mid-size item (<= 10)
    if post_residual < 10 {
        score += 60.0;
    }

    // Harmonic class reward via integer division thresholds on post_residual.
    // Class 0: post in [25,50) -> sweet spot for typical next items.
    // Class 1: post in [50,75) -> still flexible.
    // Class 2: post in [10,25) -> narrow.
    let class = post_residual / 25;
    match class {
        1 => score -= 18.0,          // 25..49
        2 => score -= 30.0,          // 50..74
        3 => score -= 22.0,          // 75..99 (big residual, near-empty bin)
        0 if post_residual > 0 => score += 12.0, // 1..24 tight leftover
        _ => {}
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: does the leftover accommodate the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain fit reward, scaled by how snugly next item fits
            let snug = (post_residual - next_item_size as u32) as f64;
            score -= 25.0 - snug * 0.15;
        } else {
            score += 8.0;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (fill emptier bins first)
    score += (post - mean_residual) * 0.25;

    // Stream progression: early on, keep bins open and flexible (favor big residual);
    // late in stream, prioritize tight packing (favor small post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post * 0.20 - progress * post * 0.10;

    // New-bin candidate handling: only attractive late in the stream or when
    // opening a fresh bin preserves a large clean residual for future big items.
    if bin_residual == bin_capacity {
        let fresh_bonus = 30.0 + progress * 40.0
            - (open_bins_count as f64) * 2.0
            + (next_item_size as f64) * 0.1;
        score += fresh_bonus;
    }

    // Modulo harmonic: post_residual divisible by 10 aligns with item granularity
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are "dead space" — penalize them heavily.
    // Treat residual <= 15 as unusable (min item is 1, but small gaps rarely match).
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 18.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Perfect fit of the residual (item exactly fills bin) is ideal.
    if item_size == bin_residual {
        score -= 80.0;
    }

    // Open-bin pressure: penalize bins when many bins are already open,
    // favoring consolidation into existing bins over spreading out.
    score += (open_bins_count as f64) * 0.8;

    // Reward bins whose residual is close to the mean residual (balanced usage),
    // slightly favoring tighter-than-average bins.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Lookahead coupling: if the next item fits the post-residual,
    // reward this placement (chains two items into one bin).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item cannot fit post-residual, penalize creating a stranded gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it moderately expensive so we only open a new bin
    // when existing bins are truly poor fits (large dead-space risk).
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in the stream, opening bins is cheaper; later, avoid it.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 400.0;
        } else if (post_residual as f64 - nxt).abs() <= 5.0 {
            score -= 200.0;
        }
        // penalize post_residual that next item can't use but is small (dead space)
        if post_residual > 0 && (post_residual as u32) < next_item_size && post_residual < 10 {
            score += 60.0;
        }
        // if next item could still fit comfortably, slight bonus
        if post_residual as u32 >= next_item_size && post_residual < 30 {
            score -= 30.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate penalty: only open new bin if no decent fit exists
    if bin_residual == bin_capacity {
        score += 150.0;
        // early stream: more willing to open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 100.0 * (1.0 - progress);
        // if next item is large, a fresh bin is more attractive
        if next_item_size >= 50 {
            score -= 40.0;
        }
    }

    // penalize very small dead space creation (unusable slivers)
    if post_residual > 0 && post_residual < 5 {
        score += 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    }

    // Penalize dead space relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Lookahead: if next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }
    // Lookahead conflict: next item would fit better elsewhere; slight penalty if it nearly fits post-residual but not quite.
    if next_item_size > post_residual && next_item_size > 0 && next_item_size - post_residual <= 15 {
        score += 15.0;
    }

    // Tightness of current fit: favor bins where the item fills a large fraction of residual.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 25.0;
    }

    // Time horizon: early in the stream, be more conservative (prefer existing bins);
    // later, allow more freedom since fewer items remain.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 3 && mean_residual > item_size as f64 {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only when existing fits are poor.
        score += 60.0;
        // If few bins fit the item, opening a new bin is more acceptable.
        if fitting_bins_count <= 1 {
            score -= 70.0;
        }
        // Late in the stream with many open bins, avoid proliferation.
        if progress > 0.5 && open_bins_count > 5 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth non-linear penalty on tiny residuals (dead space)
    let mut score = pr
        + 40.0 * (1.0 - norm_pr).powi(6) * norm_pr.max(0.0)
        - 30.0 * (1.0 - norm_pr).powi(3);

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, chase tight fits harder.
    let coupling = (norm_pr - 0.5) * (norm_pr - 0.5) * (0.5 + progress) * 60.0;
    score += coupling * (1.0 - progress);

    // Lookahead: reward if next item fits the post residual, penalize otherwise
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 25.0 * (1.0 - nxt / cap);
        } else {
            score += 15.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 - progress);
    }

    // Many open bins: discourage spreading; prefer filling existing bins
    score += (open_bins_count as f64).ln().max(0.0) * 4.0 * norm_pr;

    // Prefer bins whose residual is below mean (tighter bins)
    score += (mean_residual - pr) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that are "harmonious"
    // divisors of capacity (0, 25, 50, 75, 100 classes) -> low dead space.
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Reward perfect fit strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Harmonic class reward: residual divisible by quarter classes is reusable.
        if post_residual % quarter == 0 {
            score -= 20.0;
        } else if post_residual % (bin_capacity / 10) == 0 {
            score -= 10.0;
        } else {
            // Penalize awkward residuals (dead space risk)
            score += 8.0;
        }

        // Integer-division threshold: how many mid-size items (>=10) fit in the post residual
        let slots = post_residual / 10;
        score -= (slots as f64) * 6.0;

        // If post residual is too small for the smallest possible item, heavy penalty
        if post_residual < 10 {
            score += 60.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= 40.0;
            // harmonic bonus: next item leaves another harmonic residual
            let nr = post_residual - next_item_size;
            if nr % quarter == 0 || nr == 0 {
                score -= 25.0;
            }
        } else {
            // next item won't fit here; mild penalty scaled by how far off
            score += ((next_item_size - post_residual) as f64) * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: empty bin gets a baseline so it only wins
    // when open bins have poor fits.
    if bin_residual == bin_capacity {
        score = cap * 0.9 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 30.0;
        }
    }

    // Tight-fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.8 {
        score -= 30.0 * fill_ratio;
    }

    // Early stream: be slightly greedy on tight fits; late stream: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;
    score += progress * (post_residual as f64) * 0.05;

    // Prefer bins below mean residual (keeps residual distribution balanced)
    score += ((mean_residual - post_residual as f64).abs()) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (small leftovers that few future items can fill) are heavily penalized.
    let dead_zone: f64 = if post_residual > 0 && post_residual < 10 {
        60.0 // tiny sliver: worst dead space
    } else if post_residual < 20 {
        25.0
    } else if post_residual < 35 {
        8.0
    } else {
        0.0
    };
    score += dead_zone;

    // Reward near-exact fits (post_residual close to zero but usable).
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when it enables a good pairing
    // with the lookahead item, otherwise discourage spreading.
    if bin_residual == bin_capacity {
        let pair_fit = if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            (bin_capacity - item_size - next_item_size) as f64
        } else {
            100.0
        };
        score = 55.0 + pair_fit * 0.5 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && next_item_size == bin_capacity - item_size {
            score -= 30.0; // new bin guarantees a perfect pair
        }
    } else {
        // Open-bin pressure: mildly discourage proliferating bins.
        score += open_bins_count as f64 * 0.15;
    }

    // Lookahead synergy: favor bins whose post_residual accommodates next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (post_residual - next_item_size) as f64 * 0.1;
    } else if next_item_size > 0 {
        score += 6.0; // next item won't fit here either
    }

    // Prefer tighter bins relative to the mean residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Late in the stream, prioritize closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(40.0); // perfect match => -40, decaying for slack
    }

    // Penalize leaving a residual too small for the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += 0.5 * dead;
    }

    // Relative-to-mean coupling: prefer bins whose post-residual tracks mean residual.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if next item is large, a fresh bin is attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Slight preference to fill tighter bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * progress * (bin_residual as f64 - item_size as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: tiny post_residual is ideal.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Dead-space penalty: non-linear waste for awkward leftovers
    // that few future items (>=10) could still use.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: reward bins whose post_residual can also host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 80.0 + 0.5 * (next_item_size as f64);
    }
    // Penalize leaving a gap just below the next item size (near-miss waste).
    if next_item_size > 0 && post_residual >= (next_item_size as f64 * 0.6) as u32 && post_residual < next_item_size {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate logic: only attractive when the item is large relative
    // to the mean residual of open bins (poor fits elsewhere) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = (fitting_bins_count == 0) as i32 as f64;
        let desperation = ((item_size as f64) - mean_residual).max(0.0);
        score -= 40.0 * desperation / 50.0
            + 60.0 * (1.0 - progress)
            + 150.0 * scarcity
            + (open_bins_count as f64 * 2.0);
        // Discard new-bin option if a decent fit already exists.
        if mean_residual >= item_size as f64 + 15.0 {
            score += 120.0;
        }
    }

    // Mild preference for fuller bins among equals (fragmentation control).
    score += 0.15 * (bin_capacity as f64 - bin_residual as f64).max(0.0) * -1.0;

    // Prefer spreading across many open bins when mean residual is high.
    if mean_residual > item_size as f64 * 1.5 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr
        + 40.0 * norm_pr * norm_pr
        + 25.0 * norm_pr * norm_pr * norm_pr;

    // Smooth stream-progress coupling: penalize large residuals more later in stream
    let late = progress * progress;
    score += 60.0 * late * norm_pr;

    // Reward tight fits smoothly (post_residual near zero)
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Lookahead coupling: if next item fits the post residual, reward this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (pr - nxt).max(0.0) / cap;
        let usable = (nxt / cap) * (1.0 - fits * fits);
        score -= 35.0 * usable * (1.0 + progress);
    } else {
        // Last item: strongly prefer tightest fit
        score += 20.0 * norm_pr;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 - norm_pr);
    }

    // Mild penalty proportional to open bins to discourage fragmentation
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Deviation from mean residual: prefer bins deviating smoothly
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;

    // Perfect fill is ideal
    if pr == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: tiny unusable slivers
    if pr > 0 && pr < 10 {
        score += 18.0;
    }

    // Harmonic class of residual: prefer residuals in "useful" classes
    // (multiples of 10 align well with typical item sizes)
    score += (pr % 10) as f64 * 0.25;

    // Lookahead coupling (k=2): reward residuals that fit the next item well
    if next_item_size > 0 {
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            score -= 15.0;
            score += gap as f64 * 0.4; // prefer tight fit for next item
            if gap == 0 {
                score -= 35.0; // exact chain fit
            }
        } else {
            score += 6.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: only one open bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 28.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 200.0; // forced open
        } else {
            // Only open a new bin if all fits are terrible (huge leftover waste)
            let worst_open = mean_residual.max(0.0);
            if (post_residual as f64) > worst_open + 25.0 {
                score -= 30.0;
            } else {
                score += 45.0; // prefer existing bins
            }
        }
    }

    // Mild pressure against bin proliferation as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.05 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are pure waste.
    let min_item = 1u32;
    if post_residual < min_item.max(next_item_size) && post_residual > 0 {
        // Dead space below next item size: heavy penalty proportional to tightness.
        score += 60.0 + (post_residual as f64) * 0.5;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits: small relative slack.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: mild penalty to discourage spreading across many bins,
    // but relax late in the stream when consolidation matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (1.5 - progress);

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    // Prefer bins whose residual deviates favorably from the mean (consolidate slack).
    score -= (mean_residual - post_residual as f64) * 0.1;

    // Lookahead: if next item fits the post-residual exactly, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 40.0; // exact fill for the next item
        }
    } else {
        // Last item: reward tightest fit
        score -= 10.0;
    }

    // Penalize creating tiny unusable dead space (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's a great fit for lookahead
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor placements leaving tiny residuals,
    // with a superlinear penalty for medium dead space.
    let pr = post_residual as f64;
    if pr <= 10.0 {
        score -= 25.0 * (1.0 - pr / 10.0);
    } else if pr <= 30.0 {
        score += 0.15 * (pr - 10.0);
    } else {
        score += 3.0 + 0.25 * (pr - 30.0);
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item exactly fits the post residual, big reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 == nx {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            // Next item fits: mild reward scaled by how much slack remains.
            score -= 8.0 * (1.0 - (post_residual as f64 - nx) / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize wasting a good bin on this item
            // if post residual becomes hard-to-use dead space.
            score += 0.1 * (nx - pr).min(40.0);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the fit elsewhere would be poor (large post residual) or bins are scarce.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, modulated by stream progress
        // (later in the stream, avoid proliferation of open bins).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 15.0 * progress;

        // If many open bins with plenty of mean residual, discourage new bin.
        score += 0.05 * open_bins_count as f64;
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0;
        }
        // But if a big item would leave a terrible fit in existing bins,
        // the new-bin baseline above already competes fairly.
    } else {
        // Existing bin: slight preference for bins with less residual overall
        // (best-fit flavor), scaled by global mean residual context.
        score += 0.05 * (bin_residual as f64 - mean_residual).max(-20.0).min(20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: penalize wasted space quadratically (dead space grows costly)
    let mut score = pr * pr / cap;

    // Smooth coupling: normalized post-residual interacting with stream progress.
    // Early on (progress ~ 0), keep residuals flexible; late, prefer tight fits strongly.
    let prn = pr / cap;
    score += prn * (0.5 + progress) * (1.0 - prn) * cap * 0.1;

    // Lookahead: reward if next item fits into post_residual (smooth soft-max style term)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (nx - pr).abs();
        score -= (1.0 - fit_gap / cap).max(0.0) * (1.0 - progress) * 5.0;
        // penalize if next item won't fit
        score += (nx > pr) as i32 as f64 * (2.0 + 3.0 * progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Many open bins: encourage consolidation into existing bins
    score += (open_bins_count as f64).ln().max(0.0) * (0.5 + prn);

    // Deviation from mean residual: prefer bins with residuals near mean (balanced packing)
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * dev * cap * 0.05;

    // Brand-new bin candidate: mild penalty so it only wins when open bins are truly bad
    if (bin_residual as f64 - cap).abs() < 1e-6 {
        score += 3.0 + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Perfect fit: strongest reward ---
    if post_residual == 0 {
        score -= 1000.0;
    }

    // --- Harmonic class of the post-residual (mod arithmetic on capacity) ---
    let c = bin_capacity;
    let class = post_residual % (c / 10); // classes of 10 units
    // Residuals that form "harmonic" slots: 0, 10, 20, 25, 50 pair well with common sizes
    let harmonic = matches!(post_residual, 0 | 10 | 20 | 25 | 30 | 40 | 50);
    if harmonic {
        score -= 15.0;
    } else if class == 0 {
        score -= 5.0;
    }

    // Dead-space penalty: tiny unusable residual that few items can fill
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // --- Lookahead coupling: does next_item_size fit the post-residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: the next item can land here too; reward proportionally
            score -= 10.0 + (next_item_size as f64 / c as f64) * 20.0;
            if post_residual == next_item_size {
                score -= 50.0; // chained perfect fit
            }
        } else if post_residual > 0 {
            // Next item cannot use this bin's remainder: penalize proportionally to waste
            let waste = (post_residual as f64) / c as f64;
            score += waste * 25.0;
        }
    } else {
        // Last item of stream: prefer tightest fit, dead space is pure loss
        score += (post_residual as f64) * 0.5;
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is good only when: perfect fit possible, or item is
        // huge (leaves a harmonic residual), or existing bins are congested.
        let mut new_bin_score = 30.0 + open_bins_count as f64 * 2.0;
        if item_size >= 50 {
            let rem = c - item_size;
            if rem == 0 || rem % 10 == 0 {
                new_bin_score -= 45.0;
            }
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;
        }
        // If many open bins are near-empty, spreading out is cheap
        if mean_residual > (c as f64) * 0.6 {
            new_bin_score -= 10.0;
        }
        score = score.max(new_bin_score) - 0.0;
        score = new_bin_score + (post_residual as f64) * 0.1;
    } else {
        // Slight preference for fuller bins (best-fit flavor) beyond raw post_residual
        let fullness = 1.0 - (bin_residual as f64 / c as f64);
        score -= fullness * 8.0;
    }

    // --- Stream progression: late in the stream, avoid opening bins / close bins out ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    } else {
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gaps below 10 cannot hold any item (min size 1 assumed, but tiny gaps waste capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Exact-fit for the lookahead item: reserve this bin if next item fits the gap.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Penalize gaps that cannot fit the next item (dead space w.r.t. lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += open_pressure * (post_residual as f64 / bin_capacity as f64) * 5.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it moderately attractive only when no tight fit exists.
    if bin_residual == bin_capacity {
        score += 5.0 + mean_residual * 0.05;
    }

    // Mild stream-progress modulation: later in the stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (post_residual close to 0)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly matches post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 800.0; // chain fit: next item fills this bin exactly
        } else if diff <= 5 {
            score -= 250.0;
        } else if diff <= 10 {
            score -= 90.0;
        } else {
            // penalize leaving residuals that no typical item can use
            score += diff as f64 * 0.5;
        }
        // If post_residual is too small for the next item, mild penalty for wasted space
        if post_residual < next_item_size && post_residual < 10 {
            score += 60.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 400.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Allow new bin only when nothing else fits, or item is huge and fit is bad elsewhere
        score = 500.0 - pressure * 1200.0;
        if next_item_size > 0 && next_item_size >= item_size && fitting_bins_count <= 1 {
            score -= 200.0; // pairing big items into fresh bins
        }
    }

    // Prefer filling bins with low residual relative to mean (tighter bins first)
    let bin_residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (bin_residual_f - mean_residual) * 0.3;
    }

    // Slight preference for denser packing late in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on leftover space.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Dead-space penalty: leftover that no plausible item can use.
    if post_residual > 0 && (post_residual as f64) < 0.12 * bin_capacity as f64 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 18.0;
        } else {
            score += 8.0;
        }
        // If next item fits exactly into post_residual, strong chain bonus.
        if post_residual as u32 == next_item_size {
            score -= 22.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Time horizon: early in stream, be conservative (favor new bins less);
    // late in stream, consolidate aggressively into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress;

    // Global state coupling: many open bins with high mean residual
    // suggests fragmentation; favor filling existing bins.
    let open_f = open_bins_count as f64;
    score += 0.05 * open_f * (mean_residual / bin_capacity as f64);

    // New-bin candidate adjustment: only attractive when existing fit is poor
    // or the item is large relative to typical residual.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.5 * bin_capacity as f64;
        if poor_fit || fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            score += 45.0 + 3.0 * open_f;
        }
        // Late in stream, discourage opening new bins harder.
        score += 30.0 * progress;
    }

    // Item size coupling: large items should prefer roomier bins.
    let item_frac = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * item_frac * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Core: minimize post residual, with non-linear polynomial shaping.
    let mut score = post / cap;
    score += 0.6 * (post / cap) * (post / cap);
    score -= 0.25 * (post / cap) * (post / cap) * (post / cap);

    // Reward tight fits more as the stream progresses (smooth coupling).
    score -= 0.35 * (1.0 - post / cap) * progress;

    // Lookahead: bonus if next item fits the post residual (smooth falloff).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            let fit_ratio = 1.0 - (post - next) / cap;
            score -= 0.4 * fit_ratio * fit_ratio;
        } else {
            score += 0.15 * ((next - post) / cap);
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 0.5 + 0.3 * progress;
    }

    // Mild penalty proportional to number of open bins (encourage consolidation).
    score += 0.02 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Penalize bins whose residual deviates from the mean (keeps residuals uniform).
    score += 0.1 * ((post - mean_residual) / cap).abs();

    // New-bin candidate: keep it competitive only when open bins are quite full.
    if bin_residual == bin_capacity {
        score = 0.35 + 0.5 * progress - 0.002 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "reusable" the leftover space is.
    // Class 0: post_residual divisible by 10 -> clean slot for future items.
    let pr = post_residual;
    let class = (pr % 10) as f64;
    score += class * 0.8; // penalize ragged leftovers

    // Integer-division thresholds: leftover in coarse capacity fractions
    let frac = pr as f64 / bin_capacity as f64;
    if frac < 0.05 {
        score -= 15.0; // near-perfect packing, reward strongly
    } else if frac < 0.10 {
        score -= 8.0;
    } else if frac > 0.5 {
        score += 6.0 * (frac - 0.5); // wasteful half-empty bin
    }

    // Lookahead coupling: does the leftover fit the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
            // harmonic bonus if next item leaves a divisible-by-10 remainder too
            if (pr - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            score += 4.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        let bad_fit = (bin_residual - item_size) as f64;
        score += 25.0 - 0.2 * bad_fit; // base penalty to prefer existing bins
        if open_bins_count == 0 {
            score -= 30.0; // no alternative
        }
        // early stream: opening bins cheap; late stream: consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mean residual deviation: prefer bins close to the average leftover
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    let dead = post_residual > 0 && post_residual < 10;
    if dead {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing a bin.
        score -= 100.0;
    } else {
        // Reward tight fits quadratically.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 30.0 * tightness * tightness;
    }

    // Penalize leaving a gap that no plausible item (10..80) can use,
    // i.e. gap in (10..20) range beyond the hard-dead case.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening a new one.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and stream progress.
        score += 25.0 + 3.0 * open_bins_count as f64 + 20.0 * progress;
        // But if mean residual across open bins is large, opening fresh is fine.
        score -= (mean_residual / 20.0).min(15.0);
    } else {
        // Using an existing bin is mildly favored when many bins are open.
        score -= 0.5 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 || slack == 0 {
            score -= 25.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for next item: mild penalty unless it's dead space anyway.
        score += 8.0;
    }

    // Mean-residual coupling: prefer bins with residual below mean (tighten small leftovers).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits: square the post residual (dead space punished superlinearly).
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Two-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: subtract reward proportional to how snugly the next item fits afterward.
            let after_next = post_residual - next_item_size;
            score -= 40.0 - (after_next as f64) * 0.3;
        } else {
            // Next item won't chain here: penalize proportionally to wasted chain opportunity.
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Relative to mean residual: prefer bins with residual below mean (denser bins).
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Mild penalty for opening a brand-new bin when other bins fit.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 25.0;
    }

    // Early in the stream, be more willing to open bins to build diversity of residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    // Penalize leaving residuals in the awkward 1..10 dead zone.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powf(1.7) * 40.0;

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 - slack / bin_capacity as f64) * 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize leaving mid-range dead space.
        if post_residual > 0 && post_residual < 20 {
            score += 8.0;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Discourage opening new bins when plenty of aggregate space exists.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 45.0 * (1.0 - pressure);
        score += open_bins_count as f64 * 1.5;
        // Late in the stream, opening new bins is even worse.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // But if the item is huge relative to mean residual, new bin is fine.
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
    }

    // Slight preference for bins already tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.12;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "reusable" the leftover space is.
    // Class 0: post_residual == 0 (perfect fit) — best possible.
    // Small post_residuals that still admit common item sizes are good;
    // dead space below the minimum item size (1..10) is worthless.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0;
    } else if pr < 10 {
        // Dead space: unusable for any future item.
        score += 25.0;
    } else {
        // Harmonic divisibility classes: leftover divisible by common sizes
        // (10, 20, 25, 50) is more likely to be filled later.
        if pr % 50 == 0 { score -= 12.0; }
        else if pr % 25 == 0 { score -= 8.0; }
        else if pr % 20 == 0 { score -= 6.0; }
        else if pr % 10 == 0 { score -= 4.0; }

        // Fraction-of-capacity classes for the leftover.
        let frac = pr as f64 / bin_capacity as f64;
        if frac > 0.5 {
            score -= 10.0; // roomy bin: plenty of future flexibility
        } else if frac < 0.05 {
            score += 8.0; // nearly full: little value left
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            score -= 5.0 + (pr - next_item_size) as f64 * 0.05;
        } else {
            // Next item cannot use this bin's leftover: mild penalty,
            // stronger when leftover is tiny dead space.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless it would create large dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual < 10 && post_residual > 0 {
            score -= 10.0; // still fine: dead space is small
        }
    }

    // New-bin candidate handling: opening a new bin is attractive early in
    // the stream or when few bins are open; penalize it otherwise so we
    // consolidate into existing bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress + 1.5 * open_bins_count as f64;
        // But if the item would leave this new bin in a bad harmonic class
        // (small dead leftover), make new bin less attractive.
        if post_residual > 0 && post_residual < 10 {
            score += 30.0;
        }
        // If no existing bin fits at all, opening is mandatory: neutralize penalty.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fits).
    score -= (bin_residual - item_size) as f64 * 0.1;

    // Slight preference for bins below mean residual (consolidating fuller bins).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual exactly accommodates the next item (lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize leaving a gap that neither the next item nor small items can use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, favor consolidating into existing space.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 2.0;
    if bin_residual < bin_capacity {
        score -= open_pressure;
    } else {
        // New-bin candidate: penalize more when many bins are open, less when few.
        score += 8.0 + open_pressure;
        // Early in the stream a fresh bin is cheap; later it is costly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    // Slight preference for bins below mean residual (tighter bins first).
    if bin_residual < bin_capacity {
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 500.0; // next item fits perfectly after this placement
        } else if post_residual >= next_item_size {
            score -= 50.0;  // next item still fits
        } else {
            score += 30.0;  // next item won't fit here: dead-ish space
        }
        // Penalize large leftover relative to next item (wasted gap)
        let gap = post_residual as f64 - nxt;
        if gap > 0.0 {
            score += gap * 0.5;
        }
    }

    // Compare post residual against mean residual: prefer tighter-than-average bins
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Prefer opening new bins only when fits are poor elsewhere
    if bin_residual == bin_capacity {
        // new bin: neutral residual, penalize slightly so good fits in open bins win
        score += 40.0;
        // but if next item is large and current fits poorly, new bin attractive
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 60.0;
        }
    }

    // Slight preference for filling bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Reward filling a bin to near-exact capacity (post_residual very small).
    if post_residual <= 2 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        // Extra reward for an almost perfect two-item packing.
        if post_residual - next_item_size <= 2 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post residual useless for the next item: mild penalty.
        score += 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
        if post_residual < 15 {
            score -= 10.0;
        }
    }

    // Many open bins: encourage consolidation into existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score -= 4.0 * open_pressure.min(3.0);

    // Mean residual coupling: prefer bins whose residual deviates below the mean
    // (i.e., this bin is more filled than average).
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64 - mean_residual) / mean_residual;
        score -= 5.0 * rel.clamp(-1.0, 1.0);
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it is only
    // chosen when no existing bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, opening bins is cheaper (spread items).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If the item is large, a fresh bin is more attractive.
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
        // If no open bin fits at all (fitting_bins_count accounts only open bins),
        // the new bin must win; reduce its penalty.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild time-horizon term: later in the stream, prioritize closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: post-residual, with a non-linear penalty on wasted space.
    let mut score = post;

    // Polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap; late, residual dead space is heavily penalized.
    let waste_weight = 0.5 + 1.5 * progress * progress;
    score += waste_weight * (post / cap) * (post / cap) * 20.0;

    // Smooth fill reward: near-perfect fits get a non-linear bonus.
    let fill = item / cap;
    score -= 30.0 * fill * fill * fill;

    // Interaction: tight fit with lookahead compatibility (smooth, no hard constants).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let compat = (nxt - post).abs() / cap;
        score += 10.0 * compat * compat;
    }

    // Last-chance bonus: when this is the only fitting bin, reward using it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - post / cap);
    }

    // Mild penalty for spreading across many bins vs. mean residual deviation.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev * (0.5 + progress);

    // New-bin candidate: smooth preference to reuse bins early, open later.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" is the leftover space.
    // Residuals that are multiples of common small item sizes (10, 20, 25, 50) are valuable.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -40.0 // perfect fit, strongly reward
    } else if pr % 50 == 0 {
        -12.0
    } else if pr % 25 == 0 {
        -8.0
    } else if pr % 10 == 0 {
        -6.0
    } else if pr % 5 == 0 {
        -3.0
    } else {
        4.0 // awkward leftover, penalize
    };
    score += harmonic_bonus;

    // Integer-division threshold: residual classes by decade.
    let decade = pr / 10;
    score -= (decade as f64) * 1.5; // larger usable residual is better

    // Dead-space penalty: residual too small for the smallest plausible item (<= 5).
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            // harmonic check on the double-leftover
            if (pr - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
            score -= (10.0 - slack / 10.0).max(0.0);
        } else {
            // next item cannot use this residual: mildly penalize wasting tight space
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded
    // or the fit elsewhere would be bad.
    if bin_residual == bin_capacity {
        // baseline attractiveness of fresh bin, scaled by stream progress and open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.55 + (open_bins_count as f64) * 2.0 - progress * 10.0;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item makes a fresh bin more attractive
        }
    }

    // Mean residual coupling: when mean residual across open bins is large,
    // discourage adding more fragmentation to already-loose bins.
    if bin_residual != bin_capacity {
        let dev = mean_residual - (post_residual as f64);
        score += dev * 0.15;
    }

    // Slight preference for filling bins more tightly as stream progresses.
    let fill_ratio = item_size as f64 / cap;
    score -= fill_ratio * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a future item (below the minimum plausible item size) are toxic.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Penalize gaps that cannot fit the known next item (lookahead-aware).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward near-perfect fits (small but still-usable gaps are fine).
    score -= 25.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins over spawning more (penalize the fresh-bin candidate).
    score += 0.35 * open_bins_count as f64;

    // New empty bin candidate: make it expensive unless the current bin
    // would leave a really bad residual or the fit is poor.
    if bin_residual == bin_capacity {
        score += 55.0 + 0.5 * open_bins_count as f64;
        // But if the item fits very snugly in a fresh bin (large item),
        // soften the penalty a bit.
        if item_size > bin_capacity * 7 / 10 {
            score -= 25.0;
        }
    }

    // Slight tie-break: prefer bins with lower residual overall early on.
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual, strongly favor
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let left2 = post_residual - next_item_size;
            score -= 150.0 - (left2 as f64) * 2.0;
        } else {
            // next item won't fit here; penalize wasted lookahead potential
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Penalize creating dead space relative to smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Relative-to-mean residual coupling: prefer bins tighter than the mean
    let pr = post_residual as f64;
    score += (pr - mean_residual) * 0.8;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Late in the stream, be more conservative about wasting space
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * progress * 0.5;

    // Mild pressure against spreading across many open bins
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 60.0 + mean_residual * 0.3;
        if fitting_bins_count <= 1 {
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize large dead space: residual after placement that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // nearly perfect fit bonus
    } else if post_residual > 60 {
        score += 0.15 * (post_residual as f64 - 60.0); // large gap penalty
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let best_possible = if post_residual == bin_capacity { 0.0 } else { score };
        let _ = best_possible;
        // Base penalty for opening a new bin; relaxed when open bins are fragmented.
        score += 18.0;
        let fragmentation = if open_bins_count > 0 { mean_residual / (bin_capacity as f64) } else { 0.0 };
        // If open bins are very full on average, a new bin is reasonable.
        score -= 20.0 * fragmentation * fragmentation;
        // Lookahead: if next item is large, a fresh bin is valuable.
        if next_item_size > 0 {
            let slack = bin_capacity as f64 - next_item_size as f64;
            if item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
                // both fit together in a fresh bin -> attractive
                score -= 10.0;
            } else if (next_item_size as f64) > slack {
                score += 5.0;
            }
        }
        // Early in the stream, opening bins is cheap; late, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    } else {
        // Existing bin with lookahead synergy: leaving room for next item.
        if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
            score -= 8.0;
        } else if next_item_size > 0 && (post_residual as i64) > 0 && (post_residual as i64) < (next_item_size as i64) {
            score += 3.0; // would strand space relative to lookahead
        }
    }

    // Mild preference for filling bins with larger residuals when many bins open.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer filling bins tightly (penalize large post_residual quadratically).
    // Late: residual waste matters even more, so scale curvature upward.
    let curvature = 1.0 + 3.0 * progress * progress;
    score += curvature * (pr * pr) / cap;

    // Reward near-perfect fits smoothly via a Gaussian-like term on post_residual.
    let tightness = (pr / cap - 0.1).powi(2);
    score -= 8.0 * (-tightness * 40.0).exp();

    // Penalize opening a new bin when it fits elsewhere, smoothly weighted by progress.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        score += 6.0 * (1.0 - progress) * (1.0 + 4.0 * scarcity);
    }

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 + progress);
    }

    // Lookahead coupling: reward if next item fits smoothly in post_residual.
    if next_item_size > 0 {
        let fits_next = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        let gap = ((post_residual as f64 - next_item_size as f64) / cap).abs();
        score -= 3.0 * fits_next * (-gap * gap * 30.0).exp();
        score += 2.0 * (1.0 - fits_next) * progress;
    }

    // Mild penalty for deviating from mean residual, damped by openness.
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev * (1.0 - 1.0 / (open_bins_count as f64 + 1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual, with non-linear penalty on mid-size waste.
    score = score * (1.0 + 0.5 * (post_residual as f64 / bin_capacity as f64));

    // Harmonic class logic: classify post_residual by integer division into capacity fractions.
    let class = post_residual / 10; // classes 0..10 of residual size
    let class_bonus: f64 = match class {
        0 => -8.0, // perfect fit
        1 => -4.0, // residual 10-19: still usable for typical small items
        2 | 3 => -1.5,
        4 | 5 => 1.0, // mid-range dead space risk
        6 | 7 => 0.5,
        _ => -2.0, // large residual: bin barely used, fine
    };
    score += class_bonus;

    // Modulo coupling: residuals divisible by 10 align well with item sizes drawn from decadal grids.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    // Parity harmonic: even residuals pair better with even next items.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Lookahead: reward bins that can also fit the next item (chaining).
        let leftover_after_next = post_residual - next_item_size;
        score -= 2.0 + 0.05 * (leftover_after_next as f64);
        if leftover_after_next % 10 == 0 {
            score -= 2.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Bin cannot host the next item: penalize proportionally, but less if it's a tight fit now.
        score += 1.5 + 0.03 * (next_item_size as f64);
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Progress-based adaptation: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // Mean-residual coupling: if this bin's residual deviates favorably from the mean, reward it.
    let dev = post_residual as f64 - mean_residual;
    score -= 0.05 * dev;

    // New-bin candidate handling: opening a new bin is only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Empty bin: neutral baseline; discourage unless stream is early or fits are poor.
        score = 100.0 - 2.0 * (post_residual as f64);
        if step_index < total_items / 10 {
            score -= 15.0; // early: spreading out is fine
        }
        if fitting_bins_count > 0 && mean_residual < 30.0 {
            score += 20.0; // existing bins are already tight-ish, prefer them
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals below 10 are unusable (min item size ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Reward tight fits relative to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits but leaves more waste: mild reward
        score -= 6.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space relative to lookahead
        score += 4.0;
    }

    // Last-chance bin pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 1.5;
        // But if existing bins would leave bad dead space, new bin is fine:
        if post_residual >= 20 && post_residual < 35 {
            score -= 8.0;
        }
    }

    // Mild pressure toward consolidating residuals near mean.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Late-stream: prefer keeping future flexibility less (items nearly done).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 {
        // penalize dead space that can't host the next item
        score += 0.3 * (post_residual as f64).min(next_item_size as f64 - post_residual as f64);
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: avoid opening a new bin when only this one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals everywhere are hopeless
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // pairing potential in a fresh bin: soften the penalty
            score -= 60.0;
        }
        if mean_residual > 2.0 * item_size as f64 {
            score -= 40.0; // open bins are wasteful anyway
        }
    }

    // Mild preference for using more-open-bins states efficiently
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post residual relative to capacity, the better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 18.0 * tightness * tightness;

    // Penalize creating small unusable dead space (< 10, minimum item size analog).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // reward; if post residual is large but useless for the next item,
    // penalize mildly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
        // If next item is huge, prefer conserving large-residual bins.
        if next_item_size > 50 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (long future justifies fresh capacity); later, squeeze existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus openness penalty that shrinks over time.
        score += 30.0 + 45.0 * (1.0 - progress);
        // Avoid opening new bins when many bins already have slack.
        score += 0.8 * open_bins_count as f64;
    } else {
        // Late stream: reward using existing bins more aggressively.
        score -= 10.0 * progress;
    }

    // Global slack awareness: if mean residual is high, prefer bins that
    // reduce dispersion (move residual toward mean after placement).
    let dev_before = (bin_residual as f64 - mean_residual).abs();
    let dev_after = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * (dev_after - dev_before);

    // Mild preference for filling bins that are already half-empty or less.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // smooth polynomial coupling of post_residual with stream progress
    score += 8.0 * norm_pr * norm_pr * (progress - 0.5) * (progress - 0.5) * 4.0;
    // reward tight fits more strongly as stream progresses
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;
    // penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx && pr > 0.0 {
            score += 6.0 * (nx - pr) / cap * (0.5 + progress);
        }
        // reward reserving room for next item
        if pr >= nx {
            score -= 4.0 * (nx / cap) * (1.0 - progress);
        }
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - norm_pr);
    }
    // new-bin candidate: penalize mildly so it only wins when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress * (1.0 - norm_pr);
        if fitting_bins_count > 0 {
            score += 4.0;
        }
    }
    // mean residual coupling: prefer bins near mean residual (balance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;
    // many open bins: encourage consolidation
    score += 0.15 * open_bins_count as f64 * norm_pr;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into "useful"
    // coarse classes (multiples of 10 / 25), penalize awkward remainders.
    let post = post_residual;
    let cap = bin_capacity as f64;
    if post > 0 {
        let class = post % 10;
        match class {
            0 => score -= 12.0,
            1 | 9 => score += 8.0,
            2 | 8 => score += 5.0,
            3 | 7 => score += 2.0,
            5 => score -= 3.0, // half-tens are moderately reusable
            _ => {}
        }
        // Quarter classes: post_residual divisible by 25 is a great landing zone
        if post % 25 == 0 {
            score -= 10.0;
        }
        // Dead space penalty: residual too small for the smallest plausible item
        if post < 10 {
            score += 30.0 * (10 - post) as f64 / 10.0;
        }
    }

    // Perfect fit is gold
    if post == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does post_residual still fit the next item?
    if next_item_size > 0 && post >= next_item_size {
        score -= 6.0;
        // harmonic class match: next item leaves a clean class again
        if (post - next_item_size) % 10 == 0 {
            score -= 4.0;
        }
    } else if next_item_size > 0 && post > 0 && post < next_item_size {
        // next item cannot use this bin; residual likely wasted
        score += 5.0;
    }

    // Last-chance bin before opening a new one: strong incentive to use it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Fraction-of-capacity thresholds on residual
    let frac = bin_residual as f64 / cap;
    if frac > 0.5 {
        score -= 2.0; // prefer filling roomier bins first (best-fit-ish)
    } else if frac < 0.2 && post > 0 {
        score += 3.0; // avoid leaving slivers in nearly-full bins when alternatives exist
    }

    // Mean residual coupling: if this bin is far below average residual,
    // filling it consolidates space (good); if it's the roomiest, mild penalty
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Stream progression: early on, be picky (open bins cheaply); late, squeeze hard
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (post as f64 / cap);

    // New-bin candidate should only win when open bins would be badly fragmented
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: its post_residual is cap - item_size
        // penalize slightly so only genuinely bad fits open new bins
        score += 14.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open when nothing is open
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0; // fresh bin has clean lookahead room
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable gaps (dead space) after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }
    // Medium dead space: mildly penalized, since next items (>=1) may still fit.
    if post_residual >= 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Reward tight fits (low post_residual relative to bin_residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // If this is the only bin that can fit the item, strongly favor it
    // (avoid opening a new bin when the item would otherwise be stranded).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here; penalize leaving a gap smaller than next item.
            score += 5.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.8 * (1.0 - progress);

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Only attractive if no open bin fits well or too many bins are open.
        let mean_gap = (mean_residual - item_size as f64).abs();
        score += 35.0;               // base cost of opening a new bin
        score -= mean_gap * 0.6;     // discount if existing bins fit poorly
        if fitting_bins_count == 0 {
            score -= 100.0;          // must open a new bin
        }
    } else {
        // Prefer bins whose residual is close to the mean (balanced usage),
        // but only mildly, so tight fits dominate.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: minimize score for near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: strongly favor bins whose post_residual
    // matches the next item exactly (chained perfect fit).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            if gap == 0.0 {
                score -= 800.0; // next item also fits perfectly -> excellent chain
            } else if gap <= 5.0 {
                score -= 300.0;
            } else {
                score -= 150.0 / (1.0 + gap / 20.0);
            }
        } else {
            // next item cannot use this bin's leftover; penalize dead space
            // proportionally to how much is wasted relative to next item.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.5;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average
    // (small residuals) to preserve roomier bins for larger items.
    if mean_residual > 0.0 {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to remaining capacity elsewhere. Make the
    // empty-bin candidate moderately costly so tight fits in existing bins win.
    if bin_residual == bin_capacity {
        score += 50.0;
        // but if item is huge and next item is also huge, new bin is fine
        if item_size >= 80 && next_item_size >= 70 {
            score -= 60.0;
        }
    }

    // Late-stream pressure: as the stream progresses, waste matters more;
    // squeeze harder into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.2;

    // Penalize leaving residuals that no typical item can use (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0; // small unusable slivers are wasted capacity
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Fraction of stream processed (time horizon)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit reward: strongly favor bins that end exactly full
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Penalize small dead space that nothing (min size 1..100) can reuse well:
    // dead space below next_item_size is wasted unless it's tiny
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) > 0.0 && (post_residual as f64) < nxt {
            score += 0.6 * nxt; // unusable for the known next item
        }
        // Reward if next item fits exactly into the post-residual
        if post_residual as u32 == next_item_size {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Fragmentation pressure: if mean residual across open bins is low,
    // packing tightly matters more; if residuals are plentiful, tolerate slack
    let frag = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
    score += frag * (post_residual as f64) * 0.5;

    // Early in the stream: keep bins balanced / open new bins cheaply to
    // preserve flexibility; late: squeeze into existing bins aggressively
    let early = (1.0 - t).clamp(0.0, 1.0);
    score += early * 0.3 * (post_residual as f64);

    // New-bin candidate handling: empty bin gets a base handicap so we only
    // open a new bin when the fit elsewhere is poor, with a lookahead escape:
    // if the next item is large, opening a fresh bin now is attractive.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size >= 60 && post_residual >= 40 {
            score -= 30.0; // fresh bin will serve the big next item well
        }
        if post_residual == 0 {
            score -= 60.0; // opening a bin for a perfect fit is great
        }
    }

    // Mild penalty for many open bins already (consolidation pressure)
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let item = item_size as f64;
    let norm_post = post / cap;
    let norm_item = item / cap;

    // Base: normalized post residual (waste indicator)
    let mut score = norm_post;

    // Smooth non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins tightly (low post_residual); later, tolerate slack
    let p2 = norm_post * norm_post;
    let p3 = p2 * norm_post;
    let coupling = p2 * (1.0 - progress) - 0.5 * p3 * progress;
    score += 2.0 * coupling;

    // Reward tight fits: post residual near zero is good if bin was almost full
    let tightness = 1.0 - norm_post;
    score -= 1.5 * tightness * tightness * (1.0 - progress);

    // Penalize leaving just-below-next-item gaps (dead space for lookahead)
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        let gap_deficit = (next_item_size as f64 - post) / cap;
        score += 0.8 * gap_deficit * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // reward leaving room exactly for next item
        let gap_match = 1.0 - ((post - next_item_size as f64) / cap).abs();
        score -= 0.6 * gap_match.max(0.0);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // New-bin candidate: prefer it when open bins are congested or late in stream
    if bin_residual == bin_capacity {
        score = 1.0 + 0.5 * progress + 0.3 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        if next_item_size > 0 && item >= next_item_size as u32 {
            score -= 0.3;
        }
    }

    // Mild penalty for bins much emptier than average (avoid scattering)
    score += 0.2 * ((mean_residual - post) / cap).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space that is a multiple of
    // small divisors (2,4,5,10) is more reusable; odd/prime residuals are worse.
    let post = post_residual;
    if post > 0 {
        let mut harmonicity = 0.0;
        if post % 10 == 0 { harmonicity -= 12.0; }
        else if post % 5 == 0 { harmonicity -= 6.0; }
        else if post % 4 == 0 { harmonicity -= 4.0; }
        else if post % 2 == 0 { harmonicity -= 2.0; }
        else { harmonicity += 8.0; } // odd residual: poor reuse potential
        score += harmonicity;

        // Penalize small awkward leftovers (classic dead space) super-linearly.
        if post < 10 {
            score += (10 - post) as f64 * 3.5;
        }
        // Reward perfect fits
        if post == 0 {
            score -= 25.0;
        }
    }

    // Fraction-of-capacity classes for the item itself.
    let frac = item_size as f64 / bin_capacity as f64;
    if frac > 0.8 { score -= 15.0; }        // big item: place eagerly anywhere it fits
    else if frac > 0.5 { score -= 5.0; }
    else { score += 4.0; }                  // tiny item: prefer bins with matching small residual

    // Coupling with next item (lookahead k=2): reward residuals that can host next item too.
    if next_item_size > 0 {
        if post >= next_item_size {
            score -= 10.0;                  // this bin stays useful for the next item
            if post % next_item_size.max(1) == 0 {
                score -= 6.0;               // harmonic divisibility: exact multi-fit
            }
        } else if post > 0 {
            score += 5.0;                   // creates stranded space relative to lookahead
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only when
    // the current fit is poor or many bins are open with high mean residual.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let poor_fit = post > 0 && post < 10;
        let crowded = mean_residual > 40.0 && open_bins_count > 4;
        if poor_fit || (crowded && frac > 0.6) {
            score -= 20.0 * (0.5 + progress);
        } else {
            score += 35.0;                  // discourage opening bins when a decent fit exists
        }
    }

    // Prefer tighter-than-average bins (below-mean residual => better packing).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Slight early-stream exploration: keep several bins openable early.
    if progress < 0.2 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in [1, 9] is nearly unusable
    // (min item size 10 in classic streams; small items 1..9 still exist).
    if post_residual > 0 && post_residual <= 9 {
        score += 25.0; // heavy penalty for creating tiny dead gaps
    } else if post_residual == 0 {
        score -= 40.0; // perfect closure is the best outcome
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chain placements).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 30.0;
        } else if gap <= 9 {
            score += 10.0; // chain would create dead space afterwards
        } else {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0; // next item cannot use this bin anyway
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    score += (open_bins_count as f64).powf(1.3);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Mean residual context: prefer bins below the mean residual
    // (tighter bins first, keep loose bins flexible).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: neutral-ish baseline with slight pressure so that
    // opening a new bin is chosen only when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * (open_bins_count as f64);
    }

    // Late-stream tightening: as the stream progresses, avoid fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: low post_residual.
    score += (post_residual as f64) * 0.5;

    // Two-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            // partial credit, closer fit is better
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack.min(30.0);
        } else {
            // next item won't fit here; penalize leaving awkward gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(20.0);
        }
    }

    // Penalize large dead space relative to mean residual across open bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits
    // (high mean residual relative to item) or many bins already open.
    if bin_residual == bin_capacity {
        score += 40.0; // base penalty for opening a new bin
        if mean_residual > item_size as f64 * 1.5 {
            score -= 45.0; // open bins are fragmented; new bin is better
        }
        if open_bins_count > 20 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual), with non-linear shaping.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Lookahead: reward bins whose post residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Extra reward if next item fills the bin completely afterwards.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Dead space for the lookahead item: penalize proportionally to wasted capacity.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 14.0 * waste * waste;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, scaled by how much it would be filled.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fill = item_size as f64 / bin_residual as f64;
        score -= 30.0 * fill;
    }

    // Penalize opening a new bin when good open bins exist and mean residual is large.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowded = (open_bins_count as f64 / (1.0 + mean_residual / 20.0)).sqrt();
        score += 10.0 + 22.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64).min(1.0)
            + 4.0 * crowded;
        // Allow new bin late in the stream when open bins are nearly full anyway.
        if mean_residual < item_size as f64 + 10.0 {
            score -= 20.0;
        }
    } else {
        // Mild penalty for leaving very small unusable slivers.
        if post_residual > 0 && post_residual < 10 {
            score += 12.0;
        }
        // Prefer using bins with lower residual among equals (consolidate fragmentation).
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    // Time-horizon coupling: early in stream, be pickier (higher score baseline),
    // late in stream, accept more aggressively to close bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: waste after placement, normalized
    let mut score = post / cap;

    // Quadratic waste penalty: dead space grows quadratically bad
    score += 0.9 * (post / cap).powi(2);

    // Smooth progress coupling: early on, tolerate slack (bins reusable later);
    // late in stream, waste is irrecoverable so penalize more.
    let progress_coupling = 0.6 + 1.4 * progress * progress;
    score *= progress_coupling;

    // Tight fit reward: smooth bell around post_residual == 0
    let tightness = 1.0 - (post / cap);
    score -= 0.35 * tightness * tightness * tightness;

    // Lookahead: if next item fits exactly in post_residual, reward strongly (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt) / cap;
        if gap >= 0.0 {
            // next item fits: reward closeness to perfect chain fit
            score -= 0.5 * (-6.0 * gap).exp();
        } else {
            // next item won't fit here: mild penalty proportional to overshoot
            score += 0.25 * (-gap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 1.2;
    }

    // New-bin candidate: make empty bin attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Cost of opening a new bin decreases as stream progresses (fewer future chances to amortize)
        let open_cost = 1.0 - 0.3 * progress;
        // Extra cost if many bins already open (fragmentation pressure)
        let frag = 0.02 * open_bins_count as f64;
        // If mean residual across open bins is large, opening new bin is wasteful
        let slack_pressure = (mean_residual / cap).powi(2);
        score = open_cost + frag + 0.8 * slack_pressure;
        // If the item is huge relative to capacity, new bin is a fine home
        score -= 0.2 * (item_size as f64 / cap);
    }

    // Slight preference for bins with smaller residual before placement (compact packing)
    score += 0.1 * (residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo small integers
    // capture "which well-known gap classes" the leftover space falls into.
    let r = post_residual;
    let r_mod_10 = (r % 10) as f64;
    let r_mod_20 = (r % 20) as f64;
    let r_div_10 = (r / 10) as f64;

    // Penalize post-residuals whose harmonic class is "dead" (small nonzero gaps).
    if r > 0 && r < 10 {
        score += 30.0 - 2.0 * r as f64; // tiny unusable slivers are bad
    }
    // Reward post-residuals in "good classes": multiples of 10 or 20
    if r_mod_10 == 0.0 && r > 0 {
        score -= 8.0 + 0.5 * r_div_10;
    }
    if r_mod_20 == 0.0 && r > 0 {
        score -= 6.0;
    }
    // Penalize awkward residues (3..7 mod 10) that rarely fit future items
    if r_mod_10 >= 3.0 && r_mod_10 <= 7.0 && r >= 10 {
        score += 4.0;
    }

    // Capacity fraction coupling: how full the bin becomes
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill; // reward high fill ratio

    // Lookahead harmonic coupling: does next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            score -= 10.0 + 0.1 * next_item_size as f64;
            // exact harmonic match: next item leaves another multiple-of-10 class
            if (r % next_item_size.max(1)) == 0 {
                score -= 5.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive early or when open bins are crowded
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 15.0 + 40.0 * progress; // opening new bins gets worse later in the stream
        if open_bins_count < 3 {
            score -= 20.0;
        }
    }

    // Mean residual coupling: if open bins are generally full, conserve tight bins
    if (mean_residual - post_residual as f64).abs() < 5.0 {
        score -= 3.0;
    }
    if post_residual as f64 > mean_residual + 20.0 {
        score += 5.0; // don't hoard loose bins when tighter fits exist
    }

    // Mild tie-break by residue class of item itself
    score += ((item_size % 7) as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable gaps (dead space): residuals that are
    // too small for typical future items are almost wasted capacity.
    if post_residual > 0 {
        let dead_zone = 30.0; // gaps below this are unlikely to fit future items
        let unusability = ((dead_zone - post_residual as f64) / dead_zone).max(0.0);
        score += 12.0 * unusability * unusability;
    } else {
        // Perfect fit: reward heavily.
        score -= 40.0;
    }

    // Reward filling the bin tightly: fraction of capacity consumed.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // the empty-bin candidate (bin_residual == bin_capacity) gets this penalty
    // naturally, and we add extra pressure proportional to open bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // If no existing bin fits well (large post_residual elsewhere), opening
        // a new bin becomes relatively attractive.
        if post_residual as f64 > 0.0 {
            score -= 5.0;
        }
    }

    // Prefer bins whose residual is close to the current mean residual
    // (keeps residuals uniform, leaving larger gaps consolidated).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * deviation;

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_fit = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 15.0 * lookahead_fit;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize if post residual is a small gap the next item cannot use.
        score += 8.0;
    }

    // Early in the stream, be slightly more willing to open bins (diversity);
    // late in the stream, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward if the next item can fit exactly into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.35 * slack;
    }
    // Penalize dead space that the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Compare against mean residual across open bins: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Discourage opening a new bin when decent existing fits exist.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * open_bins_count as f64;
    }

    // Progression: tighten packing slightly as stream advances.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.1 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer placements that leave small dead space.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize awkward residuals that are hard to refill (small but nonzero gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward if the next item fits the resulting residual well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer fuller bins: compare residual to mean residual across open bins.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Mild penalty for opening new bins when several bins exist and fit is loose.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 15.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // Allow new bin if item is large relative to capacity (poor fit anywhere).
        if (item_size as f64 / bin_capacity as f64) > 0.6 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * x * x);

    // Smooth polynomial coupling with stream progress: early on tolerate
    // larger residuals, later penalize dead space more aggressively.
    score += 12.0 * progress * (x - 0.3) * (x - 0.3) * cap;
    score -= 6.0 * (1.0 - progress) * x * (1.0 - x) * cap;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits into post residual (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit = ((x - nx).max(0.0)) / cap;
        score -= 8.0 * (1.0 - fit * fit);
    } else {
        score -= 5.0 * x; // last item: just fill bins
    }

    // Mild pressure toward consolidating open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - x);

    // New-bin candidate handling: make empty bin mildly attractive only
    // when residuals are poor
    if bin_residual == bin_capacity {
        score = pr + 4.0 - 10.0 * (1.0 - x) * (1.0 - (mean_residual / cap).min(1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (divisible by small harmonics) are better final states.
    let pr = post_residual;
    if pr > 0 {
        // Reward (subtract) if post residual is divisible by common item harmonics.
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        else if pr % 2 == 0 { score -= 1.5; }
        // Penalize awkward residue classes (dead-space prone).
        if pr % 7 == 3 || pr % 7 == 5 { score += 2.0; }
    } else {
        // Perfect fill is ideal.
        score -= 25.0;
    }

    // Integer-division thresholds: leftover big enough to host a mid-size item.
    let tier = pr / 20; // 0..5
    score -= tier as f64 * 4.0;

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= pr {
        if pr - next_item_size == 0 { score -= 20.0; }
        else if (pr - next_item_size) % 10 == 0 { score -= 8.0; }
        else { score -= 3.0; }
    } else if next_item_size > pr {
        // Next item cannot use this bin's leftover: penalize proportionally.
        score += (next_item_size - pr) as f64 * 0.15;
    }

    // Last-chance bin: avoid stranding it, but also avoid wasting it on tiny items.
    if fitting_bins_count == 1 {
        if item_size >= bin_residual / 2 { score -= 10.0; } else { score += 5.0; }
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / bin_capacity as f64).powi(2);
        score = 55.0 - 40.0 * tightness;
        if next_item_size > 0 && (bin_capacity - next_item_size) <= 5 && next_item_size >= 50 {
            score -= 12.0; // reserve fresh bin for a big follower
        }
        if fitting_bins_count > 0 && post_residual as f64 > mean_residual {
            score += 8.0;
        }
    }

    // Late-stream consolidation: prefer tighter fills as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // Prefer bins below mean residual (already tight bins stay tight).
    if (bin_residual as f64) < mean_residual { score -= 2.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (exact fill strongly favored).
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Fit ratio: smaller waste relative to item is better.
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 40.0 * fit_ratio;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins and
    // encourage consolidation into existing space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual deviates below the mean (denser bins get priority).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead: if the next item fits exactly into the post-residual, bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // decent fit exists; make the empty bin moderately expensive by default.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        } else if post_residual < 20 {
            score -= 40.0; // current best fit would leave dead space anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize leaving dead space below the minimum plausible item size.
    if post_residual > 0 && post_residual < 10 {
        score += 100.0;
    }

    // 2-step lookahead: strongly reward when the next item fits exactly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // perfect two-item fill
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty for large post residual
            // that invites fragmentation relative to the fleet mean residual.
            score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Deter opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 40.0 + 10.0 * open_bins_count as f64;
        // Allow new bin if current item is huge and would leave tiny residue anyway
        if item_size >= 80 {
            score -= 30.0;
        }
    }

    // Prefer tighter bins: small relative residual bonus.
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (-tightness * 12.0).exp();

    // Penalize leaving dead space that no future item (>=10) could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_waste = post_residual - next_item_size;
            score -= 15.0 * (-(next_waste as f64) / 20.0).exp();
        } else {
            // This bin can't host next item; mild penalty if gap is small (awkward leftover).
            let gap = next_item_size - post_residual;
            if gap < 10 {
                score += 5.0;
            }
        }
    }

    // New-bin candidate handling: empty bin gets a base cost so we only open when
    // existing fits are poor, but discount early in the stream and when many bins open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 - 10.0 * progress;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += 0.15 * mean_residual;
        // If few bins fit the item, new bin is more acceptable.
        score -= 8.0 * (fitting_bins_count as f64).min(3.0);
        // Next item exactly fits a fresh bin's residual after this item? encourage.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Prefer filling bins with large residuals (consolidation) to reduce bin sprawl.
    score -= 0.05 * bin_residual as f64;

    // Mild penalty for excessive open bins (encourage closing out bins).
    score += 0.3 * open_bins_count as f64;

    // Reward placing into bins whose residual is close to item size in general.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post-residual with smooth non-linear penalty for awkward dead space.
    // Penalize residuals that are neither ~0 (perfect fit) nor large enough to be useful.
    let mut score = pr;
    score += 30.0 * (x * (1.0 - x)) * (1.0 - progress); // mid-sized dead space penalized more early
    score -= 25.0 * (1.0 - x) * (1.0 - x) * progress;   // reward near-full bins late in stream

    // Coupling with mean residual: prefer bins whose residual deviates below the mean (tighter bin).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 12.0 * dev * dev - 8.0 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward if the next item fits into the post-residual (smooth kernel).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = (pr - nx).max(0.0);
        let kernel = (1.0 - (pr - nx / 2.0 - fits / 2.0) / cap).min(1.0);
        score -= 10.0 * kernel * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins early on.
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by modulo classes
    let post = post_residual as i64;
    let class = post % 10; // harmonic residue class

    // Dead space penalties by harmonic class: small residues (0..=5) are "usable" slots
    let class_penalty = match class {
        0 => -8.0,          // perfectly divisible residual is ideal
        1 | 2 => -4.0,      // near-perfect classes
        3 | 4 | 5 => 0.0,   // neutral mid classes
        6 | 7 => 6.0,       // awkward classes
        _ => 12.0,          // 8 | 9 : worst dead-space classes
    };
    score += class_penalty;

    // Integer-division thresholds on post_residual: reward tight fits
    let quot = post_residual / 10;
    score -= (quot as f64) * 0.5;

    // Harmonic coupling with next item: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = post_residual - next_item_size;
        if diff == 0 {
            score -= 15.0; // perfect chaining
        } else if diff <= 5 {
            score -= 8.0;
        } else if diff <= 15 {
            score -= 3.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot use this bin's leftover: penalize proportional to waste
        score += (next_item_size as f64 - post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).abs();
        // penalize new bin mildly; reduce penalty when many fragmented bins exist
        let mut nb = 6.0;
        if fitting_bins_count > 0 {
            nb += 4.0 * (1.0 - (fitting_bins_count as f64 / (fitting_bins_count + open_bins_count) as f64).sqrt());
        }
        if fragmentation < 0.3 {
            nb += 5.0; // bins mostly full -> new bin acceptable sooner
        }
        score += nb;
    }

    // Stream progression: late in stream, tighten up and avoid opening bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Mean residual coupling: prefer bins close to mean (balanced packing)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    // Slight preference for fuller bins overall
    score -= (item_size as f64 / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small nonzero post_residual is worst.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward fits that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when open bins are underutilized.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
        if mean_residual >= item_size as f64 {
            score += 20.0;
        }
    }

    // Mild pressure on number of open bins overall.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual
    // with next item size (perfect two-item packing).
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 1000.0; // perfect chain: bin becomes exactly reusable
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 300.0; // near-perfect chain
        } else if post_residual >= next_item_size {
            score -= 50.0; // next item still fits afterwards
        } else {
            score += 30.0; // next item won't fit here; dead space likely
        }

        // Penalize leaving residuals that no small item can ever fill.
        if post_residual < 10 && post_residual > 0 {
            score += 40.0;
        }
    } else {
        // Last item: just minimize post residual.
        score += 0.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates
    // favorably from the mean (tighter-than-average bins get priority).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: empty bin gets a mild default score so that
    // it only wins when no open bin offers a decent fit (post_residual small
    // in good open bins keeps them below the empty-bin score).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - item_size as f64 + 25.0;
        // Encourage opening a new bin early in the stream when many bins open.
        if open_bins_count > 0 && item_size >= 60 {
            score -= 10.0;
        }
    }

    // Slight progression term: late in the stream, be more conservative
    // about wasting space (dead space matters more as stream ends).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Penalize waste relative to what the item consumed.
    score += 0.35 * (post_residual as f64 / item_size.max(1) as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // big reward; if next item would be stranded by this placement, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            let slack = post_residual as f64 - nxt;
            if slack == 0.0 {
                score -= 30.0; // perfect chain fit
            } else {
                score -= 10.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else if (next_item_size as u32) <= bin_residual && bin_residual != bin_capacity {
            // Next item fits current bin but not after this placement -> mild penalty
            score += 6.0;
        }
    }

    // Global state: when many bins are open with slack, discourage spreading;
    // prefer consolidating into existing residual when mean residual is high.
    let mr = mean_residual / bin_capacity as f64;
    score += 8.0 * mr * (open_bins_count as f64).ln();

    // Time horizon: early in stream, opening bins is cheap (favor tight fits less
    // aggressively); late in stream, squeeze everything.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * t * (1.0 - fit_ratio);

    // New-bin candidate handling: empty bin gets a base cost so it only wins
    // when existing bins fit poorly, scaling with how bad existing fits are.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.5 * (open_bins_count as f64);
        // But if no open bin can fit at all, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Late in stream with large item, new bin can be better than wrecking a bin
        // that could serve the next item.
        if next_item_size > 0 && (next_item_size as u32) > post_residual && (next_item_size as u32) <= bin_residual {
            score -= 15.0;
        }
    }

    // Mild penalty for leaving residuals below smallest plausible item (dead space),
    // but only mid/late stream.
    if post_residual > 0 && post_residual < 10 && t > 0.3 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    // Base: raw dead space
    let mut score = pr as f64;

    // Smooth non-linear coupling of dead space with stream progress:
    // late in the stream, small residuals become more valuable (tight packing),
    // large residuals less penalized relative to opening new bins.
    let w = 0.5 + 0.5 * progress;
    score += w * 30.0 * x * x * (1.0 - x); // penalizes mid-size dead space peaks smoothly

    // Reward tight fits more strongly as the stream progresses
    score -= (1.0 - x).powi(3) * 15.0 * (0.4 + 0.6 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Penalize bins whose residual is far below the mean residual
    // (keeps a spread of usable residuals across open bins)
    let dev = (mean_residual - pr) / cap;
    score += 8.0 * dev * dev * dev.abs();

    // Lookahead: reward leaving space that fits the next item, smoothly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit_next = if pr >= n { 1.0 } else { 0.0 };
        let closeness = 1.0 - ((pr - n).abs() / cap);
        score -= fit_next * 12.0 * closeness * closeness;
        score += (1.0 - fit_next) * 6.0 * (1.0 - closeness);
    }

    // Slight preference for existing bins over opening new ones, stronger early
    if bin_residual == bin_capacity {
        score += 10.0 * (1.2 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (dead space minimization).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Harmonic class logic: classify post_residual by modulo buckets.
    // Residuals that pair well with common small items (residual % 10 in {0,1,2})
    // are more "usable"; penalize awkward residue classes.
    let residue = post_residual % 10;
    score += match residue {
        0 => -6.0,
        1 | 2 => -3.0,
        8 | 9 => 4.0,
        3 | 4 => 1.0,
        _ => 2.5,
    };

    // Integer-division thresholds: bins whose remaining capacity still allows
    // at least one more "half-item" chunk are preferred.
    let half_chunks = post_residual / (bin_capacity / 2);
    if half_chunks == 0 && post_residual > 0 {
        score += 5.0; // dead bin: too small for anything big
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward; if next item cannot fit any fitting bin besides this one,
    // keep this bin viable.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: brand-new empty bin (residual == capacity).
    // Penalize opening a new bin when decent fits exist elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base_penalty = 18.0 + 10.0 * (1.0 - progress);
        // If the current item would leave a large awkward residual in any bin,
        // a fresh bin may be better; reduce penalty when item is large.
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 12.0;
        score += base_penalty - large_item_bonus;
        // If next item is huge and current item is small, opening fresh bin
        // preserves ordering flexibility.
        if next_item_size > 60 && item_size < 30 {
            score -= 8.0;
        }
    }

    // Mild pressure to consolidate into fewer bins.
    if open_bins_count > 2 {
        score -= 1.5;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first),
    // leaving roomier bins for future large items.
    score -= (mean_residual - bin_residual as f64) * 0.08;

    // Small tie-breaker on tightness ratio.
    score += (bin_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: reward tight packing (low post residual)
    score += post_residual as f64;

    // Dead-space penalty: small gaps (< 10, minimum item size) are unusable
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Medium dead-space: gaps below 20 are hard to fill
    else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward exact fit for next item lookahead
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open bins pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize relative to how full existing bins are
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.3;
        // Opening a new bin is fine late in stream when residuals are fragmented
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // Prefer bins whose residual is close to item size (tight relative fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 10.0;

    // Penalize if this bin's residual deviates far from mean residual (keeps balance)
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    // If next item fits exactly in post_residual, big bonus already; also penalize
    // leaving post_residual that cannot fit next item but is large
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = (next_item_size as f64 / post_residual as f64).min(1.0);
        score -= 80.0 * tightness;
    } else if next_item_size > 0 {
        // penalize dead space that next item cannot use, scaled by how unusable it is
        let dead = post_residual as f64;
        score += 0.5 * dead * (1.0 - (next_item_size as f64 / bin_capacity as f64));
    }

    // Relative to mean residual: prefer filling bins that are already below-average residual (denser bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when decent fits exist, more so early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let waste = bin_capacity as f64 - item_size as f64;
        score += 40.0 + 30.0 * (1.0 - progress) + 0.4 * waste;
    }

    // Slight preference to use bins with small residual relative to capacity
    score += 0.1 * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

