        }
        // Few open bins and high mean residual: keep using open bins.
        if mean_residual > item_size as f64 * 1.5 && open_bins_count > 0 {
            score += 20.0;
        }
    }

    // Mild preference for bins with residual close to the item (avoid fragmenting big gaps).
    let gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * gap;

    // Slight time-horizon coupling: early in stream, consolidate; late, be flexible.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), with smooth non-linear penalty
    let mut score = pr * (1.0 + 0.8 * pr / cap);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap; late, waste is costly (superlinear in progress)
    let waste_coupling = (pr / cap).powi(2) * (0.5 + 2.5 * progress * progress);
    score += waste_coupling * cap;

    // Reward nearly-full bins with a smooth saturating term
    let fill = 1.0 - pr / cap;
    score -= 12.0 * fill * fill * fill;

    // Penalize dead space that cannot plausibly fit the next item (smooth softplus-like)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (n - pr).max(0.0);
        score += 3.0 * (gap / cap) * (1.0 - progress);
        // Bonus if post_residual still fits next item (smooth)
        let fit_next = (pr / n).min(1.0);
        score -= 6.0 * fit_next * fit_next;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Slight preference for bins below mean residual (balance avoidance of fragmentation)
    score += 0.05 * (mean_residual - bin_residual as f64).abs() * progress;

    // Mild penalty for proliferating open bins early
    score += 0.3 * open_bins_count as f64 * (1.0 - progress) * (pr / cap);

    // New-bin candidate (bin_residual == bin_capacity) gets smooth extra penalty
    if (bin_residual as f64 - cap).abs() < 0.5 {
        score += 15.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual).
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic class logic: dead space is worse when it falls in "useless"
    // residue classes that few item sizes can match (items are integers 1..100).
    let dead = post_residual;
    let class = dead % 10;
    match class {
        0 => score -= 12.0,          // round residual: many future items fit
        1 | 2 | 3 => score += 6.0,   // tiny slivers: nearly unusable
        4 | 6 | 8 => score += 2.0,   // even classes: moderately reusable
        5 => score -= 4.0,           // half-decade residual: decent reuse
        _ => score += 1.0,
    }

    // Integer-division threshold: residual blocks divisible by common item
    // granularities are more reusable.
    if dead > 0 && (dead % 5 == 0 || dead % 20 == 0) {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits exactly in the post-residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == dead {
            score -= 30.0;
        } else if next_item_size <= dead {
            let slack_after_next = dead - next_item_size;
            if slack_after_next <= 5 {
                score -= 15.0;
            }
            // harmonic match between next item and residual class
            if dead % 10 == next_item_size % 10 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here: residual becomes final dead space
            score += dead as f64 * 0.3;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual <= 20 {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    }

    // New-bin candidate: penalize opening a fresh bin when open bins exist
