    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item fits poorly elsewhere.
    if bin_residual == bin_capacity {
        let tight = (bin_capacity - item_size) as f64 / bin_capacity as f64;
        // Base mild penalty so existing bins are preferred.
        score += 15.0;
        // If item leaves large residual in a fresh bin (small item), new bin is cheap.
        score -= 20.0 * tight;
        // Late in the stream, consolidate instead of opening bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Prefer filling bins tighter than the current mean residual (reduces fragmentation).
    score -= 3.0 * (mean_residual - post_residual as f64).max(0.0) / bin_capacity as f64;

    // Many open bins: encourage closing them out (fill small residuals).
    if open_bins_count > 4 {
        score -= 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: penalize wasted space, quadratically so tiny dead space is heavily punished.
    let mut score = post * post / cap;

    // Smooth coupling of waste with stream progress: later in the stream,
    // dead space is more costly (fewer chances to fill it).
    score *= 1.0 + 0.8 * progress * progress;

    // Reward tight fits: subtract a smooth function of utilization.
    let util = item_size as f64 / cap;
    score -= 6.0 * util * util * (1.0 - progress * 0.5);

    // New-bin candidate: penalize opening a bin unless existing bins are poor fits.
    if is_new_bin {
        let crowding = (fitting_bins_count as f64).max(1.0);
        let avg_fit = mean_residual / cap;
        // Penalty shrinks when few bins fit or mean residuals are small (tight bins).
        let penalty = 12.0 / crowding * (1.0 - avg_fit.clamp(0.0, 1.0));
        score += 10.0 + penalty;
    } else {
        // Last-chance bonus: if this is the only fitting bin, strongly favor it.
        if fitting_bins_count == 1 {
            score -= 8.0;
        }
        // Reward using bins that deviate favorably from the mean residual.
        score -= (mean_residual - bin_residual as f64) * 0.05;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 4.0 * (-gap / 20.0) * (1.0 - progress * 0.3);
        // Penalize leaving a gap the next item barely misses (dead space trap).
        if (post_residual as i64 - next_item_size as i64) < 0 {
            score += 2.0 * progress;
        }
    }

    // Mild penalty for proliferating bins late in the stream.
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that fall into
    // "usable" classes (multiples of common small item sizes / divisors of capacity).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit is divine.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Modulo classes on post_residual: residuals divisible by 10 (or 5) are
    // more likely to be filled by future items drawn from a broad distribution.
    let m10 = post_residual % 10;
    let m5 = post_residual % 5;
    if m10 == 0 {
        score -= 12.0;
    } else if m5 == 0 {
        score -= 6.0;
    } else {
        score += (m5 as f64) * 1.5; // penalize awkward off-class residuals
    }

    // Integer-division threshold: classify residual into harmonic bands
    // (cap/4, cap/2, 3cap/4). Mid-band residuals are the most reusable.
    let quarter = bin_capacity / 4;
    if post_residual >= quarter && post_residual <= 3 * quarter {
        score -= 8.0;
    } else if post_residual < quarter && post_residual > 0 {
        score += 10.0; // tiny dead-space slivers
    }

    // Lookahead coupling: reward residuals that can exactly host the next item,
    // penalize residuals just barely too small for it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or the
    // fit here would be terrible (large post_residual relative to capacity).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowding = mean_residual / cap;
        score += 30.0 - 25.0 * crowding;
        // If the item is huge, opening fresh is often better.
        if (item_size as f64) > 0.6 * cap {
            score -= 15.0;
        }
    }

    // Waste ratio penalty: fraction of capacity thrown away.
    score += (pr / cap) * (pr / cap) * 20.0;

    // Late in the stream, consolidation matters more: favor tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - pr / cap);

    // Mild pressure to prefer fuller bins when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * (pr / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (<= 10) are pure waste; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Small but potentially usable gaps: moderate penalty scaled by gap.
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward very tight fits (post_residual near zero but not dead).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Perfect-fit lookahead: if the next item exactly fills the post_residual,
    // this is an ideal placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits here: mild reward for keeping chains alive.
        score -= (post_residual as f64 - next_item_size as f64).min(10.0);
    }

    // Last-chance bin: strongly prefer using the only bin that fits the item
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bins pressure: penalize placements that leave bins scattered when
    // many bins are already open; encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual is below the mean (fill the emptier-relative
    // bins less; favor filling fuller bins tightly).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; offset by tight-fill potential.
        score += 25.0 + open_bins_count as f64 * 1.0;
        // If the item fills a fresh bin well, opening is cheap.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= fill_ratio * 30.0;
    }

    // Early stream: be slightly more willing to open bins (future items
    // benefit from diversity of residual sizes).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact / near-exact fits.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            score -= 40.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 1.5 * waste;
        }
    }

    // Tightness relative to mean residual: prefer bins tighter than average.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 250.0 + 150.0 * (1.0 - progress) + 10.0 * open_bins_count as f64;
        // But if the next item is large and nothing fits well, new bin is safer:
        if next_item_size > 0 && next_item_size > post_residual.min(bin_residual) && next_item_size >= 50 {
            score -= 100.0;
        }
    }

    // Small preference for compacting into already-open bins as stream progresses.
    score += 0.05 * (post_residual as f64) * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Penalize large dead space, scaled by how unusable it is:
    // dead space smaller than the smallest plausible item is worse.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 60.0 * (10.0 - dead);
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // next item still fits here; mild reward proportional to leftover after chain
            score -= 30.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize more if this bin's leftover is tiny
            score += 10.0 * (next_item_size as f64 - post_residual as f64).min(50.0);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits; add small dispersion penalty.
        score += (fitting_bins_count as f64).ln() * 3.0;
    }

    // Global state: if mean residual across open bins is high (lots of slack),
    // prefer filling existing bins rather than opening new ones.
    let slack_ratio = mean_residual / bin_capacity as f64;
    score -= 25.0 * slack_ratio;

    // New-bin candidate handling: only attractive early in the stream or when
    // the current bin would leave a very awkward residual.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new bin: base cost, discounted early in the stream
        score += 120.0 * (1.0 - 0.5 * (1.0 - progress));
        // attractive if item is large (uses a fresh bin efficiently)
        score -= 40.0 * (item_size as f64 / bin_capacity as f64);
        // less attractive if plenty of open bins with slack exist
        score += 30.0 * slack_ratio;
    } else {
        // existing bin: mild preference as stream progresses to consolidate
        score -= 10.0 * progress;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // unless it is a near-exact fit which is already rewarded.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Tiny tie-breaker favoring fuller bins.
    score += 0.01 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: reward tight fits with smooth polynomial decay.
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * norm_pr);

    // Tight-fit bonus amplified later in the stream.
    let tightness = 1.0 - norm_pr;
    score -= 3.0 * tightness * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual across open bins.
    let mr = mean_residual / cap;
    score += 1.5 * (norm_pr - mr) * (norm_pr - mr);

    // Penalty for leaving a hole that no future small item can use:
    // coupling post_residual with next item size (lookahead k=2).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste_gap = (pr - nx).max(0.0);
        score += 0.8 * (waste_gap / cap) * (1.0 + progress);
        // Reward bins whose post_residual exactly accommodates the next item.
        let match_bonus = 1.0 - ((pr - nx).abs() / cap);
        score -= 1.2 * match_bonus * match_bonus * (0.3 + progress);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 4.0 * (1.0 - norm_pr);
    } else {
        // Mild preference for fuller bins when many alternatives exist.
        score += 0.5 * norm_pr * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        let bad_alternatives = (norm_pr - mr).abs().min(1.0);
        score += 2.5 * crowded * (1.0 - progress) + 1.0 - bad_alternatives;
    }

    // Mild congestion pressure: encourage consolidating items into fewer bins early.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * norm_pr * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fraction.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Class boundaries: dead space below smallest useful chunk is bad.
    if post_residual == 0 {
        score -= 50.0; // perfect fit: strongly reward
    } else if post_residual < 10 {
        score += 40.0; // unusable sliver: penalize
    } else if post_residual <= 20 {
        score += 12.0; // small leftover
    } else if frac >= 0.5 {
        score -= 8.0; // half-capacity residual still very usable
    }

    // Modulo arithmetic on residual classes: residuals near multiples of common item sizes
    // pair well with future items (sizes 10..80 often multiples of 5/10).
    let r = post_residual as i64;
    let mod10 = r % 10;
    if mod10 == 0 {
        score -= 6.0;
    } else if mod10 <= 2 || mod10 >= 8 {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // how tightly the next item would pack here
            let nxt = next_item_size as f64;
            let tight = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 10.0 * tight;
        } else {
            // next item cannot use this residual: mild penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / cap).min(1.0) * 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin has high nominal score; push it up so it
    // only wins when all fits are poor, but reward opening when open bins are crowded.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If many open bins are nearly full, opening fresh is reasonable.
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual deviates from mean in a useful (smaller) direction:
    // filling tighter-than-average bins first consolidates space.
    let dev = (post - mean_residual) / cap;
    score += dev * 10.0;

    // Mild late-stream consolidation: as stream progresses, prefer tighter fits more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (post_residual as f64) * progress * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 12 {
