        score -= 80.0;
    } else if post_residual >= 13 && post_residual <= 20 {
        // Mild penalty: residual small enough to be mostly wasted later.
        score += 8.0;
    }

    // Reward leaving room that matches the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
