    // Last-chance bin before opening a new one: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: fewer open bins -> prefer existing bins; many open -> allow consolidation.
    score += (open_bins_count as f64) * 0.6;

    // Prefer bins tighter than the mean residual (better packing).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate: penalize opening a bin unless current bin fit is really bad.
    if bin_residual == bin_capacity {
        score += 25.0;
        // but if item is large and nothing fits well, new bin is fine
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Early stream: be slightly more permissive with opening bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score -= 15.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
