    if post_residual as f64 > mean_residual {
        score += 0.8 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        score += 30.0 - 10.0 * pressure;
        score += open_bins_count as f64;
    }

    // Late in the stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
