    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        // Penalize opening a new bin; the penalty shrinks for large items.
        score += 30.0 * (1.0 - fill_frac) + 10.0;
        // Early in the stream, be more willing to open bins (diversify residuals).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 12.0 * (1.0 - progress);
        // If many bins are open and mean residual is low, prefer reusing.
        score += (mean_residual / 10.0).min(10.0);
    } else {
        // Reuse bonus scaled by how full the bin already is (compact existing bins).
        let used_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 8.0 * used_frac;
        // Mild penalty for spreading across many open bins.
        score += (open_bins_count as f64).ln().max(0.0) * 1.5;
    }

    // Global pressure: when open bins are nearly full on average, tighten selection.
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: prefer tight fits (low post_residual). Later: tolerate
    // larger post_residual slightly less harshly since bins are more committed.
    let poly = pr * pr / (cap * cap);
    score += poly * (1.0 + 2.0 * progress) * 10.0;

    // Penalize dead space relative to next item: if next item fits in post_residual,
    // reward this bin; otherwise penalize proportional to gap.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 5.0 * (1.0 - nxt / cap);
        } else {
            score += 3.0 * (pr / cap) * (nxt / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr / cap);
    }

    // Mild preference for bins below mean residual (consolidation of slack).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Slight openness penalty: with many open bins, avoid fragmenting further.
    score += 0.01 * (open_bins_count as f64) * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: quantize post_residual into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = (post / cap * 8.0).floor(); // 8 harmonic classes of capacity fraction

    // Penalize dead space: residuals too small for typical items (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Harmonic bonus: residual exactly divisible into useful chunks.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 10.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.5 * (next_item_size as f64);
            // Integer-division threshold: next item leaves a class-0 residual too.
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // Next item cannot follow: penalize proportional to overshoot class.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 5.0 + overshoot / 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins usually win, modulated by stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = cap * 0.75 - 10.0 * progress;
        // If current bin's fit is terrible (large dead space class), new bin competes.
        if post_residual > 0 && post_residual < 15 {
            score -= 20.0;
        }
        // If next item is large, fresh bin is safer.
        if next_item_size > 50 {
            score -= 15.0;
        }
    }

    // Slight preference for tighter bins overall (waste minimization).
    score += (bin_residual as f64 - post) * 0.05;

    // Mean-residual coupling: if this bin is far below mean residual, it is
    // "harmonically distant" — mildly discourage abandoning it empty-ish.
    let dev = mean_residual - post;
    if dev > 20.0 {
        score += (dev - 20.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    } else if post_residual < 20 {
        score += 20.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins when
    // alternatives exist; encourage closing bins (post_residual small but usable).
    score += 0.8 * open_bins_count as f64;

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Next item won't fit here: remaining space is dead unless large.
            if post_residual < 10 {
                score += 40.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current placements
    // would create heavy fragmentation (mean residual very low).
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Mild stream-progression coupling: later in stream, avoid creating tiny gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual is good).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual,
    // this is a perfect chain -> reward heavily.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if nx <= pr {
            let diff = pr - nx;
            score -= 12.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item won't fit here after placing; penalize wasted residual
            // proportionally to how much of next item is "unplaceable" here.
            score += 0.15 * (nx - pr).min(nx);
        }
    } else {
        // Last item: prefer leaving minimal residual.
        score -= 3.0 * tightness;
    }

    // Penalize bins with residual far above the mean (avoid hoarding space
    // in already-large bins when tighter bins exist).
    let res = bin_residual as f64;
    if res > mean_residual {
        score += 0.10 * (res - mean_residual);
    } else {
        score -= 0.05 * (mean_residual - res);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 6.0;
        if post_residual < 10 {
            score -= 4.0; // near-perfect fill in the only candidate
        }
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // the current item is large relative to capacity or no good fits exist.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        if large_item > 0.7 {
            score -= 10.0 * (large_item - 0.7) / 0.3; // large items deserve fresh bins
        } else {
            score += 5.0 + 8.0 * (1.0 - large_item); // discourage wasting fresh bins
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 4.0 * progress;
    }

    // Mild preference to fill bins when many are open (reduce bin count).
    score -= 0.02 * open_bins_count as f64 * tightness;

    // Small dead-space penalty for very small residuals that are unlikely
    // to be usable (below typical minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: small post_residual is good, but avoid tiny unusable slivers.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // dead-space penalty that grows super-linearly as residual becomes small but nonzero
        let unusable = (post_residual < 10) as i32 as f64;
        score += 25.0 * unusable * (1.0 - pr / bin_capacity as f64);
    } else {
        // perfect fit: big reward
        score -= 60.0;
    }

    // Exact-fill ratio shaping: reward bins whose residual is well used
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill;

    // Lookahead: penalize if post_residual can't host the next item but is close-ish,
    // reward if post_residual can host next item snugly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 12.0 * snug;
        } else {
            // bin becomes dead for the next item; penalize proportionally to wasted space
            score += 8.0 * (1.0 - pr / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer opening a new bin when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // penalize new bin when existing bins are roomy
        score += 15.0 + 40.0 * pressure;
        // early in stream, opening new bins is cheaper (spreads items)
        let t = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - t);
        // if next item is huge, an empty bin is valuable
        if next_item_size >= 70 {
            score -= 18.0;
        }
    }

    // Mild preference to fill bins with larger residuals when many bins are open (bin count control)
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (pr / bin_capacity as f64);

    // Global fragmentation penalty: if this bin's residual is far below mean, it's a straggler — prefer using it
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= 0.15 * diff.min(50.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual, with smooth cubic saturation of tight fits.
    let x = (pr / cap).clamp(0.0, 1.0);
    let mut score = pr as f64 * (1.0 + 2.5 * x * x);

    // Penalize dead space that cannot serve the lookahead item: smooth coupling.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let waste = (ns - pr).max(0.0) / cap;
        score += 30.0 * waste * waste * (1.0 - progress);
        // Reward bins whose post-residual still fits the next item (chaining).
        let chain = (pr - ns).max(0.0) / cap;
        score -= 15.0 * chain * (1.0 - chain);
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 10.0 + 20.0 * (1.0 - progress);
    }

    // Mild penalty for spreading load thin across many open bins (smooth in count).
    let density = open_bins_count as f64 / (1.0 + mean_residual.max(0.1) / 10.0);
    score += 0.05 * density.sqrt();

    // Early-stream: slightly prefer filling existing bins; late-stream: allow new bins.
    score += 5.0 * progress * (pr / cap);

    // Perfect fit reward (smooth Gaussian-like term around zero residual).
    score -= 25.0 * (-pr as f64 * pr as f64 / 50.0).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo capacity fractions.
    // Post-residuals that are "usable" (>= next item or divisible into common
    // class sizes) get rewards; tiny dead-space residues get penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as i64;
    let nis = next_item_size as i64;

    // Class 1: post_residual divisible by 10 (harmonic with typical item sizes)
    if pr % 10 == 0 {
        score -= 6.0;
    }
    if pr % 20 == 0 {
        score -= 4.0;
    }
    if pr % 25 == 0 {
        score -= 3.0;
    }
    if pr % 50 == 0 {
        score -= 5.0;
    }

    // Dead-space penalty: small odd residues that no item (>=1) pairs with well
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 2.5;
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual
    if nis > 0 {
        if nis == pr {
            score -= 20.0;
        } else if nis <= pr {
            let rem = pr - nis;
            // harmonic class of the double-fit remainder
            if rem % 10 == 0 {
                score -= 8.0;
            } else if rem < 10 {
                score += 3.0;
            }
        } else {
            // next item won't fit here: slight penalty scaled by overflow
            score += ((nis - pr).min(40)) as f64 * 0.3;
        }
    }

    // Last-chance bonus: only this bin fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bin
    // would leave a badly-classified residue or the fit is poor.
    if bin_residual == bin_capacity {
        let base = cap * 0.55;
        score += base; // default cost of a new bin
        // If placing here leaves a harmonic residue, open bins are better;
        // a new bin keeps full capacity, so reduce its cost when the item is large.
        let frac = item_size as f64 / cap;
        if frac > 0.6 {
            score -= 0.35 * cap;
        }
        // If many open bins and mean residual is large, discourage new bin
        score -= (mean_residual / cap).min(1.0) * 5.0;
    }

    // Tightness reward: filling a bin densely is good
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= tightness * 4.0;

    // Late-stream consolidation: prefer existing bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= progress * 3.0;
    }

    // Mild preference for bins below mean residual (balance workload)
    if bin_residual as f64 > mean_residual {
        score += 1.5;
    } else {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    if post_residual == 0 {
        score -= 12.0; // perfect fit reward
    }

    // Penalize large post-residuals that waste capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Open bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: favor bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 7.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Mean residual coupling: prefer bins close to mean residual (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.12;

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 18.0 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: reward heavily.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead space is good; penalize super-linearly for larger waste.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += waste * waste * 50.0;

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this is a perfect chain placement — reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            // Next item fits: leftover after both items determines quality.
            let two_step_left = post_residual - next_item_size;
            score -= 200.0 - two_step_left as f64 * 2.0;
        } else {
            // Next item won't fit here: penalize proportional to mismatch,
            // unless post_residual is tiny (unusable anyway).
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
            if post_residual < 10 {
                score -= 100.0; // tiny residual is nearly dead space anyway
            }
        }
    }

    // Relative to mean residual: bins with less residual than average are
    // "tighter" — prefer filling tight bins to consolidate waste.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Late in the stream, closing out bins matters more; prefer tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.2;

    // Mild penalty for opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Tight fit reward: squared post-residual pressure (dead space is quadratic waste)
    score += 0.35 * (post * post) / cap;

    // Exact / near-exact fill bonus
    if post == 0 { score -= 60.0; }
    else if post <= 5 { score -= 25.0; }
    else if post <= 10 { score -= 10.0; }

    // Lookahead: if the next item fits into the post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 8.0 + 12.0 * (nxt / post);
        } else {
            // post-residual too small for next item: penalize wasted sliver
            score += 6.0 * (1.0 - post / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 3 {
        // many alternatives: prefer the tightest anyway (post dominates), small tie-break
        score += 1.5;
    }

    // Prefer bins below mean residual when item fits snugly (keeps spread balanced)
    score += 0.10 * (residual - mean_residual);

    // Time horizon: late in the stream, avoid opening new bins and consolidate
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it only wins when open bins are bad fits
        score += 15.0 + 20.0 * (1.0 - progress);
        // Opening a new bin is fine if item is large relative to capacity or no tight alternative
        score -= 10.0 * (item / cap);
        if fitting_bins_count == 0 { score -= 50.0; }
        if post >= 70.0 { score += 10.0; } // large fresh bin keeps flexibility
    } else {
        // Early stream: mild bonus to fill existing bins, keeping bins few
        score -= 5.0 * (1.0 - progress);
    }

    // Penalize opening many bins early (bin count pressure)
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping over stream progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Smooth interaction: penalize mid-range dead space more as stream progresses
    let dead = norm_pr * (1.0 - norm_pr);
    score += 12.0 * dead * dead * (0.3 + progress);

    // Reward tight fits (small post residual) with a non-linear bonus
    score -= 8.0 * (-pr / 10.0).exp() * (1.0 + progress);

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = if pr >= nxt { 1.0 } else { 0.0 };
        let slack = (pr - nxt).max(0.0) / cap;
        score -= 10.0 * fits * (1.0 - slack * slack) * (0.5 + 0.5 * progress);
        // Penalize if next item nearly fits but doesn't (tempting dead space)
        let near = (-((pr - nxt).abs()) / 15.0).exp();
        score += 5.0 * near * (1.0 - fits) * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Prefer bins below mean residual (more roomy bins used first for big fills)
    score += 0.15 * (pr - mean_residual) * (0.5 + progress);

    // Mild penalty for opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) + 0.5 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Penalize tiny dead space classes: residuals in (0,10) are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Reward "perfect" residuals that are multiples of small harmonic steps.
    let class = post_residual % 10;
    if class == 0 {
        score -= 12.0;
    } else if class <= 3 {
        score += 6.0;
    }

    // Reward tight fits: low post_residual relative to item size.
    let tightness = item_size as f64 / (item_size.max(1) + post_residual) as f64;
    score -= 30.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        // Harmonic bonus if next item exactly exhausts a class boundary.
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 8.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize leaving medium dead space.
        if post_residual >= 10 {
            score += 5.0;
        }
    }

    // New-bin candidate logic: only prefer fresh bin when existing residuals are poor.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fit win.
        score += 15.0;
        // But if mean residual is small (open bins nearly full), new bin is attractive.
        score -= (mean_residual / cap) * 30.0;
        // Early stream: opening bins early builds flexibility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Mild penalty for too many open bins relative to progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count as f64 > 4.0 + progress * 10.0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 20.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins exist,
    // but allow it when few bins are open or the fit is poor.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize slightly, but less when few open bins.
        score += 12.0 + 3.0 * open_bins_count as f64;
        // Allow new bin if item is large relative to mean residual (poor fits elsewhere).
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
        // Allow new bin early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    } else {
        // Prefer filling already-open bins when open_bins_count is high.
        score -= (open_bins_count as f64).ln().max(0.0) * 4.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // Penalize if post_residual is dead space for the next item.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild preference for bins below mean residual (balance residuals).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: strongly reward a residual that exactly
    // matches the next item, and penalize residuals the next item cannot use.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post == next {
            score -= 900.0;
        } else if post >= next {
            let slack = post - next;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // Dead space for the next item: penalize proportionally.
            score += 0.5 * (next - post);
        }
    }

    // Compare against mean residual: prefer bins whose remaining space stays
    // close to (or below) the average, avoiding fragmentation outliers.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev.abs();

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin — strong reward unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is
    // large and existing residuals are small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let load_pressure = mean_residual / bin_capacity as f64;
        let penalty = 120.0 - 80.0 * (item_size as f64 / bin_capacity as f64) - 60.0 * load_pressure;
        score += penalty.max(0.0) * (1.0 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches zero.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    // Lookahead coupling: perfect fit for the next item is very valuable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // bonus proportional to how well the leftover accommodates the next item
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item won't fit here; leftover likely dead space
        score += 0.35 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Brand-new bin candidate: prefer it only when current residual is small
    // or the item is large relative to residual.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is attractive when item is big and few bins fit it.
        score = 30.0 + fit_ratio * 20.0;
        if fitting_bins_count <= 1 {
            score -= 25.0; // nothing else fits well; open new bin
        }
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
    } else {
        // Compare against mean residual: bins tighter than average are precious.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Time horizon: early on, allow more exploration (soften penalties);
    // late in the stream, be greedy and avoid waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.25 * progress; // late-stage scores compressed toward tight fits
    if progress > 0.8 && post_residual > 40 {
        score += 6.0 * progress; // discourage large leftovers at the end
    }

    // Many open bins: discourage spreading; few open bins: consolidation is fine.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly (quadratic/cubic growth)
    let progress_weight = 0.5 + 1.5 * t;
    score += progress_weight * (x * x) * cap * 0.5;
    score += t * (x * x * x) * cap * 0.5;

    // Reward filling bins nearly exactly (post_residual near 0) more strongly over time
    score -= (1.0 - x) * (1.0 - x) * (2.0 + 4.0 * t);

    // Penalize the brand-new empty bin candidate smoothly: opening a new bin
    // wastes the accumulated residual of open bins; cost grows with open_bins_count
    // and with mean residual available elsewhere.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(1.0);
        score += 8.0 + openness * 3.0 + mean_residual * 0.08;
        // Late in the stream, prefer closing out existing bins rather than opening new ones
        score += 10.0 * t * t;
        // But if the item is huge relative to capacity, a new bin is natural: soften penalty
        score -= (item_size as f64 / cap) * 6.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 10.0 * t;
    }

    // Lookahead: if the next item would fit in the post residual, reward leaving that space
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        // smooth coupling: exact match for next item is highly desirable
        score -= (1.0 - gap / cap).max(0.0) * (3.0 + 5.0 * t);
        // penalize post residual that is too small to ever be useful again
        if pr < nx && pr > 0.0 {
            score += (1.0 - pr / nx) * (4.0 + 6.0 * t);
        }
    }

    // Mild preference for consolidating into fewer bins
    score += open_bins_count as f64 * 0.05 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, with a harmonic (integer-division) tiering
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic class of post_residual: how "coarse" is the leftover space
    // Leftovers that are multiples of common small sizes (5,10,20,25) are more reusable.
    let harmonic_bonus: f64 = if post_residual == 0 {
        -30.0 // perfect fit
    } else if post_residual % 25 == 0 {
        -12.0
    } else if post_residual % 20 == 0 {
        -10.0
    } else if post_residual % 10 == 0 {
        -8.0
    } else if post_residual % 5 == 0 {
        -5.0
    } else {
        4.0 // awkward remainder
    };
    score += harmonic_bonus;

    // Integer-division threshold: dead space below the smallest plausible item is useless.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Fraction of capacity left as residual: nonlinear penalty for mid-range waste
    let frac = pr / cap;
    if frac > 0.0 && frac < 0.15 {
        score += 15.0; // sliver
    } else if frac >= 0.15 && frac < 0.4 {
        score += 3.0;
    }

    // Lookahead coupling: if the next item fits the post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // extra reward for tight chaining
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 8.0;
            }
        } else {
            score += 6.0; // next item won't chain here
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is terrible
    if fitting_bins_count == 1 {
        score -= 14.0;
        if post_residual > 40 {
            score += 10.0; // but a very poor fit justifies a new bin
        }
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when all fits are bad
    if bin_residual == bin_capacity {
        // neutral base for fresh bin; make it competitive only against bad fits
        score = 45.0;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big item coming: fresh bin useful
        }
        if open_bins_count == 0 {
            score = 0.0; // must open
        }
    }

    // Mild load balancing across many open bins: prefer bins below mean residual
    if (bin_residual as f64) > mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    // Stream progression: early on, be more willing to open bins; late, pack tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward residual that can still host a typical future item.
    if post_residual >= next_item_size && next_item_size > 0 {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < (next_item_size as f64) {
        score += 15.0; // dead space relative to lookahead
    }

    // Open-bin pressure: prefer using existing bins over spawning new ones.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor filling it to avoid waste.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: neutralize its naturally large residual so it only
    // wins when existing fits are truly poor.
    if bin_residual == bin_capacity {
        score += 55.0 + 0.5 * open_bins_count as f64;
    }

    // Prefer bins tighter than the mean (better consolidation).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // next item fits too: mild bonus proportional to tightness
            let tight = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * tight;
        } else {
            // next item won't fit here: penalize wasted potential
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare post_residual against mean residual: prefer bins that become
    // tighter than average (good consolidation) or that were already tight
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 50.0 * (1.0 - rel);
        } else {
            score += 30.0 * (rel - 1.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // relative to capacity (poor fit elsewhere) or few bins open
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        score += 300.0 - 250.0 * large;
        if open_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Late in stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 100.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (typical item >= 1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < 20 {
        score += 8.0; // hard-to-fill gap
    }

    // Lookahead: if next item fits perfectly in the post_residual, big reward.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 1.0 {
            score -= 30.0; // perfect chain
        } else if post_residual as u32 >= next_item_size {
            score -= 6.0; // next item still fits here
        } else {
            score += 4.0; // next item will need another bin
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make opening a new bin costly unless the item
    // is large relative to capacity and no open bin fits well.
    if bin_residual == bin_capacity {
        let base_penalty = 20.0 + 0.15 * open_bins_count as f64;
        // If item is huge (>= 60), a fresh bin is more acceptable.
        let relief = if item_size >= 60 { 18.0 } else { 0.0 };
        score += base_penalty - relief;
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    // Global state coupling: if mean residual is low (bins nearly full),
    // prefer spreading items into emptier bins (higher residual than mean).
    let diff = bin_residual as f64 - mean_residual;
    score -= 0.05 * diff;

    // Mild preference for keeping few open bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: quadratic in post_residual (dead space penalized super-linearly)
    let mut score = pr * pr / cap + pr;

    // Smooth coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) are rewarded more strongly.
    let tightness = 1.0 - pr / cap;
    score -= tightness * tightness * (1.0 + 3.0 * progress) * cap * 0.5;

    // Reward high fill ratio with a smooth saturating polynomial
    score -= (fit_ratio * fit_ratio * (3.0 - 2.0 * fit_ratio)) * cap * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Scarcity pressure: fewer fitting bins -> prefer placing here
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0).ln() * (1.0 + 4.0 * progress);
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus;
    // smooth reward proportional to how well next item matches post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let match_deg = 1.0 - (nx - pr).abs() / cap;
        score -= match_deg * match_deg * (10.0 + 20.0 * progress);
        // Penalize leaving post_residual that neither fits next item well nor is near zero
        if nx > pr {
            score += (nx - pr) * 0.05;
        }
    }

    // Slight penalty when bin residual deviates from mean residual (balance open bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 2.0;

    // New-bin candidate: make it attractive only when nothing fits well
    if bin_residual == bin_capacity {
        score = pr * pr / cap + pr + 25.0 - 15.0 * progress
            - (fitting_bins_count as f64).ln().max(0.0) * 0.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 (capacity fractions)
    let res_class = post_residual % 10;
    let dead_penalty = match res_class {
        0 => -12.0,                       // perfect fill class
        1 | 2 => -4.0,                    // near-perfect
        3 | 4 | 5 | 6 | 7 => 6.0,         // awkward mid-class dead space
        8 | 9 => 2.0,                     // small sliver, mostly unusable
        _ => 0.0,
    };
    score += dead_penalty;

    // Integer division thresholds on post_residual
    let q = post_residual / 10;
    if q <= 1 { score -= 8.0; }           // residual <= 19: nearly sealed bin
    else if q >= 6 { score += 4.0; }      // leaving bin mostly empty is wasteful

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;                // perfect two-item chain
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 10.0 - (slack as f64).min(10.0); // tighter lookahead fit better
            // harmonic match: next item complements residual to a multiple of 10
            if (post_residual - next_item_size) % 10 == 0 { score -= 5.0; }
        } else {
            score += 3.0;                 // next item won't reuse this bin
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: keep it mid-ranked, only chosen when fits are bad
    if bin_residual == bin_capacity {
        score = 55.0 - (mean_residual / bin_capacity as f64) * 10.0
                    - (open_bins_count as f64).min(20.0);
        if next_item_size > 0 && next_item_size >= 90 { score -= 20.0; }
    }

    // Slight pressure to close bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    // Mild preference for bins below mean residual (consolidating emptier space)
    if bin_residual as f64 > mean_residual { score += 2.5; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable dead space
    // (min item size is 1 in the interface regime, but very small gaps waste capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 120.0;
    }

    // Non-linear penalty for large wasted residuals relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_frac * waste_frac;

    // Open-bin pressure: discourage spreading across many open bins.
    score += 4.0 * (open_bins_count as f64).sqrt();

    // Deviation from mean residual: prefer bins whose residual is tight (small).
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead coupling: if the next item fits in the post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: mild dead-space penalty.
        score += 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless all open bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; scale with how many bins already fit the item.
        score = 100.0 + 30.0 * fitting_bins_count as f64
            + 2.0 * open_bins_count as f64;
        // If nothing else fits well, allow the new bin.
        if fitting_bins_count == 0 {
            score -= 90.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can host the next item (chained packing), especially near-exact matches.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain_waste = post_residual as f64 - next_item_size as f64;
            score -= 20.0;
            score -= 10.0 * (1.0 - chain_waste / cap);
        } else {
            // Next item cannot follow: penalize proportional to how close it missed.
            let miss = (next_item_size - post_residual) as f64;
            score += 6.0 * (miss / cap);
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving less than average keeps the bin pool balanced (good), leaving
    // far more than average wastes a bin slot.
    if post_residual as f64 > mean_residual {
        score += 0.35 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // or the stream is early and bins are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / cap;
        score += 30.0 - 25.0 * item_frac - 10.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0; // fresh bin can chain the next item
        }
    }

    // Slight preference to fill bins among many open ones (reduce bin count).
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post-residual.
    let tight = (post_residual as f64 / bin_capacity as f64).powi(2);
    score -= 30.0 * tight;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: penalize if post-residual blocks the next item but residual
    // of a fresh bin (or larger gap) would fit it.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0 + 0.3 * next_item_size as f64;
        }
        // Reward leaving a gap that exactly fits the next item (chain packing).
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize wasting a near-full bin on a small item when next item is large.
        if next_item_size > post_residual && post_residual == 0 {
            score += 0.0; // fresh bin case handled below
        }
    }

    // New-bin candidate handling: opening a new bin is costly, but becomes
    // attractive when existing bins fit poorly (large dead space) or when
    // many bins are already open and fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Cheaper to open new bin early in stream (more future items to fill it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If current item leaves huge dead space in any existing bin, opening
        // a fresh bin becomes more attractive.
        let dead = post_residual as f64 / bin_capacity as f64;
        score -= 30.0 * dead;
        // If no open bin fits well, new bin is preferred.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Lookahead synergy: fresh bin can host next item too.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
        }
    } else {
        // Penalize fragmenting existing bins that are already mostly full
        // (their residual is precious).
        let scarcity = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
        score += 8.0 * scarcity * (post_residual as f64 / bin_capacity as f64);
    }

    // Global fragmentation pressure: when mean residual is low, preserve
    // remaining capacity; when mean residual is high, consolidate.
    if mean_residual > 0.0 {
        let gap = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 6.0 * gap;
    }

    // Mild penalty when many bins are open: encourage closing bins out.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Small time-dependent drift to break ties differently over the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + 0.8 * t - 0.6 * t * t + 0.4 * t * t * t;
    score += 0.5 * (pr / cap) * (pr / cap) * poly * cap;

    // Reward tight fits (small post residual), stronger late in stream
    let tightness = 1.0 - pr / cap;
    score -= tightness * tightness * (10.0 + 20.0 * t);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 8.0 + 12.0 * t;
    }
    // Reward residual that exactly accommodates the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Mild penalty when bin residual deviates far from mean residual across bins
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: penalize opening a new bin when good fits exist, less so early
    if bin_residual == bin_capacity {
        score += 25.0 - 15.0 * t;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing similar items in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: quantize post_residual into capacity-fraction bands.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward near-tight fits: post_residual in the lowest eighth band.
    if post_residual <= eighth {
        score -= 30.0 + (eighth as f64 - pr) * 0.8;
    } else if post_residual <= quarter {
        score -= 12.0 - pr * 0.05;
    } else {
        // Penalize large leftover space proportionally with a non-linear kick.
        score += (pr - quarter as f64) * 0.25 + (pr / cap).powi(3) * 20.0;
    }

    // Perfect-fill harmonic class: post_residual divisible by common class sizes.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 3.0;
    }

    // Lookahead coupling: reward if next item can use the post_residual exactly or nearly.
    if next_item_size > 0 {
        let nd = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item won't fit here: penalize wasted capacity if residual is small.
            if post_residual < next_item_size && post_residual < quarter as u32 {
                score += 10.0;
            }
        }
        // Favor bins whose residual stays in a reusable band for typical item classes.
        if next_item_size <= post_residual && post_residual - next_item_size <= eighth {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; subtract more when no good fit exists elsewhere.
        score = cap * 0.55;
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else {
            // Encourage new bin when all existing fits leave large dead space.
            if pr > cap * 0.6 {
                score -= 20.0;
            }
            score += open_bins_count as f64 * 0.5;
        }
    }

    // Mild stream-progression damping: early on, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    // Slight preference for bins below mean residual (consolidating fuller bins).
    score -= (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it is smaller than the smallest plausible item (1),
    // but practically, gaps below ~10 are hard to fill; scale penalty sharply.
    if post_residual > 0 {
        let dead = (20u32.saturating_sub(post_residual)) as f64;
        score += 2.5 * dead * dead / 20.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness * tightness;

    // Penalize leaving a gap that exactly blocks the next item, reward if next item fits.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 8.0; // next item can't use this bin -> wasted capacity
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: prefer spreading across existing bins when many are open.
    score += (open_bins_count as f64) * 0.4;

    // Prefer bins with residual below mean (consolidate fullness).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New empty bin candidate: make it unattractive unless residual pressure is high.
    if bin_residual == bin_capacity {
        score += bin_capacity as f64 * 0.8 + (open_bins_count as f64) * 2.0;
        // Allow new bin late in stream if it would be nearly perfect for item + next
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 60.0;
        }
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // perfect 2-step match
        } else if next_item_size as f64 <= post_residual as f64 {
            // next item can also fit here: mild reward scaled by tightness
            score -= 15.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item would not fit: penalize leftover dead space
            score += 8.0 + 0.2 * diff;
        }
    }

    // Reward tight fits relative to current residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness * tightness;

    // Penalize placements leaving residual far below mean residual (fragmenting small slots).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is poor (large post_residual).
    if bin_residual == bin_capacity {
        score -= 5.0;
        if post_residual as f64 > 40.0 {
            score -= 10.0;
        }
    }

    // Slight preference for consolidating into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 6.0 * fit_ratio;

    // Penalize dead space: post_residual too small to ever be useful later
    // (items are >= 1, but small slivers under ~10 are likely wasted).
    if post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    }

    // Lookahead: if next item fits in post_residual, big reward;
    // if next item does NOT fit, penalize proportionally.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain = 1.0 - (next_item_size as f64 / post_residual as f64).abs();
            score -= 18.0 * (1.0 - (next_item_size as f64 - post_residual as f64).abs() / bin_capacity as f64);
            let _ = chain;
            score -= 8.0;
        } else {
            score += 6.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last chance: only bin that fits -> strong reward to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let spread = mean_residual - post_residual as f64;
        let pressure = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Early stream: opening bins is cheap; late stream: prefer filling.
        score += 30.0 * (1.0 - pressure) - 0.5 * open_bins_count as f64;
        // If mean residual across open bins is large, opening new bin is wasteful.
        score += 0.3 * mean_residual.max(0.0);
        let _ = spread;
    } else {
        // Slight preference for bins whose residual is above average (keep big holes flexible).
        if (bin_residual as f64) < mean_residual {
            score += 3.0;
        } else {
            score -= 2.0;
        }
    }

    // Mild reward for using more of the bin overall.
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual)
    let mut score = pr as f64;

    // Smooth polynomial coupling: dead-space penalty grows non-linearly with progress
    let dead = norm_pr * norm_pr * (0.5 + 3.0 * progress);
    score += 30.0 * dead;

    // Reward filling bins well, scaled by stream progress
    score -= 15.0 * norm_item * (0.3 + 0.7 * progress);

    // Penalize bins whose residual diverges from mean residual (fragmentation)
    let dev = (pr as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving residual that can host the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 10.0 * snug * (0.4 + 0.6 * progress);
    } else if next_item_size > 0 {
        // Next item cannot use this residual: mild penalty if residual is tiny
        score += 5.0 * (1.0 - norm_pr) * progress;
    }

    // New-bin candidate: make empty bins attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64 / (1.0 + open_bins_count as f64)) * (0.5 + 0.5 * progress);
        score += 20.0 * (1.0 - crowd) - 10.0 * crowd;
        // penalize opening new bins early in the stream
        score += 25.0 * (1.0 - progress) * (1.0 - norm_item);
    }

    // Mild preference for fewer open bins when many are open
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + 2.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "reusable" classes
    // (small residuals that many future items can still pair with).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill is always best
    } else {
        // class = pr / 10 bucket: low buckets are more reusable
        let bucket = pr / 10;
        score -= (10 - bucket.min(10)) as f64 * 2.0;

        // modulo arithmetic: residuals divisible by common item granularities
        // (items often arrive in multiples of 5 or 10)
        if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 5 == 0 {
            score -= 4.0;
        } else {
            score += 3.0; // awkward residual
        }

        // If lookahead item fits exactly into post_residual, strong reward
        if next_item_size > 0 && next_item_size <= pr {
            let gap = pr - next_item_size;
            if gap == 0 {
                score -= 45.0;
            } else if gap <= 10 {
                score -= 20.0;
            } else {
                score -= 5.0;
            }
        }
        // If next item would NOT fit here but fits nothing else either,
        // leaving a large residual is fine (it stays usable later)
        if next_item_size > pr && pr >= 10 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins have plenty of room
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus pressure terms
        score = 100.0
            + 30.0 * (mean_residual / bin_capacity as f64)
            + 20.0 * progress
            - (fitting_bins_count as f64) * 5.0;
        // early stream: new bins cheap; late stream: expensive
        score -= (1.0 - progress) * 15.0;
    }

    // Prefer bins whose residual is close to mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Many open bins: encourage tightening existing ones
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever fit the
    // minimum item (size 1) are already counted; instead punish gaps that
    // cannot fit the *lookahead* item, making them effectively dead space.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Dead gap relative to the next item's demand: the smaller the gap
        // compared to what is coming, the worse this placement is.
        let dead_ratio = (next_item_size - post_residual) as f64 / next_item_size as f64;
        score += 40.0 * dead_ratio * dead_ratio;
    }

    // Reward near-perfect packing strongly (tight fits first).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Penalty for opening a new bin when existing bins can fit the item,
    // scaled by how many alternatives exist (open-bin pressure).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 30.0 + 5.0 * fitting_bins_count as f64;
        }
        // Mild bonus for new bins late in the stream (consolidation).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    } else {
        // Prefer bins whose residual is close to the mean (balance load),
        // slightly weighted by number of open bins to avoid sprawl.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev * (1.0 + open_bins_count as f64 / 20.0);
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (aggressive tightness bonus).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    } else if post_residual <= 20 {
        score -= 30.0;
    }

    // 2-step lookahead: reward if next item fits the post-residual exactly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // perfect chain fit
        } else if next_item_size < post_residual {
            let waste = (post_residual - next_item_size) as f64;
            // penalize the leftover after a hypothetical next placement
            score += waste * 0.6;
            if waste <= 10.0 {
                score -= 40.0; // near chain fit
            }
        } else {
            // next item won't fit here: post residual becomes dead space
            score += (post_residual as f64) * 0.35;
        }
    }

    // Compare post_residual against mean residual: prefer bins whose
    // residual stays near/below the mean (keeps other bins usable).
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        if pr > mean_residual {
            score += (pr - mean_residual) * 0.25;
        } else {
            score -= (mean_residual - pr) * 0.10;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 25.0;
        // opening a new bin is fine if next item is large and residuals are small
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 20.0;
        }
    }

    // Late in stream: prefer tighter packing, less opening of bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: post_residual small relative to capacity
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 15.0 * tight * tight;

    // Penalize dead space that no plausible future item can use
    let min_item = 1.0;
    if (post_residual as f64) > 0.0 && (post_residual as f64) < min_item * 2.0 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly or tightly
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= ni {
            let gap = pr - ni;
            score -= 20.0 * (1.0 - gap / cap);
            if gap == 0.0 { score -= 30.0; }
        } else {
            // next item cannot go here; mild penalty scaled by how close
            score += 5.0 * (ni - pr) / cap;
        }
    } else {
        // Last item: strongly prefer tightest fit
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: opening a new bin is expensive when many bins
    // are already open with usable residual; cheap early in the stream.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 25.0 * (1.0 - progress);
        if fitting_bins_count == 0 { score -= 50.0; } // no alternative
        if open_bins_count > 3 && mean_residual > item_size as f64 {
            score += 15.0; // plenty of room elsewhere; avoid proliferation
        }
    } else {
        // Prefer bins with residual close to item (minimize fragmentation)
        let diff = (bin_residual as f64 - item_size as f64) / cap;
        score += 10.0 * diff * diff;
        // Favor bins below mean residual (filling emptier bins balances state)
        score += 5.0 * ((bin_residual as f64 - mean_residual) / cap);
    }

    // Time horizon: late in stream, be more aggressive about closing gaps tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits (low post_residual). Late: penalize dead space more strongly.
    let base = pr * (1.0 + 0.6 * progress * fit_norm);

    // Smooth interaction: quadratic term in normalized residual, modulated by progress.
    let quad = 40.0 * fit_norm * fit_norm * (0.3 + 0.7 * progress);

    // Cubic coupling: strong penalty for large residuals late in the stream.
    let cubic = 25.0 * fit_norm.powi(3) * progress;

    // Reward near-perfect fits smoothly (gaussian-like bump around post_residual ~ 0).
    let perfect = -30.0 * (-(fit_norm * fit_norm) / 0.02).exp();

    // Lookahead coupling: reward if next item fits into post_residual (smooth, soft).
    let lookahead = if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = (pr - nx).max(0.0);
        -8.0 * (1.0 - fits / cap) * (1.0 - (pr - nx).abs() as f64 / cap)
    } else {
        0.0
    };

    // Last-chance bonus: strongly favor using the only fitting bin.
    let last_chance = if fitting_bins_count == 1 { -20.0 } else { 0.0 };

    // New-bin candidate: neutral-to-slightly-high baseline, cheaper only when
    // no open bin offers a decent fit (smooth via mean_residual).
    let new_bin_penalty = if bin_residual == bin_capacity {
        let mean_fit = (mean_residual - item_size as f64).max(0.0) / cap;
        15.0 + 60.0 * mean_fit * (1.0 + progress)
    } else {
        0.0
    };

    // Mild pressure to consolidate: fewer open bins is better.
    let consolidation = 0.15 * open_bins_count as f64 * (0.5 + fit_norm);

    base + quad + cubic + perfect + lookahead + last_chance + new_bin_penalty + consolidation
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: harmonic ladder on post_residual
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Penalize dead space that no plausible item (1..=100) can use
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Harmonic class of post_residual: multiples of 10 are "friendly" residuals
    let friendly = post_residual % 10 == 0;
    if friendly {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (post_residual - next_item_size) as f64 * 1.5 + 25.0;
    } else if next_item_size > 0 && next_item_size > bin_residual {
        // next item can't fit anywhere near this size; prefer filling this bin anyway
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: make it attractive only when open bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        // open a new bin when existing residuals are small (poor fits) or many bins open
        score = 40.0 - pressure * 30.0 - (open_bins_count as f64).min(20.0);
        if item_size > 50 {
            score -= 10.0; // big items like fresh bins
        }
    }

    // Mild time regularization
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10 or below next item) are heavily penalized.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 40.0 }
                   else if next_item_size > 0 && (post_residual as u32) < next_item_size { 25.0 }
                   else { 0.0 };
        score += dead;

        // Non-linear penalty: quadratic growth of waste for tiny residuals.
        if post_residual < 20 {
            score += (20 - post_residual) as f64 * 1.5;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Pressure from many open bins: discourage spreading when bins are plentiful,
    // but allow opening a new bin when open bins are few and fit is poor.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when few bins open or fit is bad.
        let poor_fit = if post_residual > 0 && post_residual < 10 { 30.0 } else { 0.0 };
        score -= 10.0 + 2.0 * open_pressure * (1.0 - fill_ratio.min(1.0)) - poor_fit;
        // Late in stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    } else {
        // Existing bin: mild bonus to keep bins consolidated.
        score -= 3.0;
    }

    // Prefer bins whose residual is close to mean (balance), slight effect.
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: strongly reward exact fit for the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize post_residual that is too small to ever fit a typical item.
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Compare residual against mean residual: bins with more free space than average
    // are better targets; nearly-empty bins are less valuable to consume.
    if post_residual as f64 >= mean_residual {
        score -= 8.0;
    } else {
        score += 8.0;
    }

    // Penalize wasting a fresh bin on small items when many bins are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.2 * open_bins_count as f64;
        if item_size > 70 {
            score -= 10.0;
        }
    }

    // Late in the stream, tighten packing (favor fuller bins).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a non-linear boost.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 20.0;

    // Penalize dead space: post residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; slight penalty for awkward leftover.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Time horizon: early in the stream, be conservative (prefer filling open bins);
    // late in the stream, allow more aggressive bin opening if fits are poor.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to mean residual availability
        // and number of open bins; discount late in the stream.
        score += mean_residual * 0.5 + open_bins_count as f64 * 2.0 - progress * 10.0;
        // A new bin is attractive only if the item is large relative to capacity.
        score -= (item_size as f64 / bin_capacity as f64) * 15.0;
    } else {
        // Favor bins whose residual is close to mean residual (balanced packing),
        // slightly, to keep residuals homogeneous and combinable.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Slight preference for bins with larger residual when item is small
    // (preserve tight bins for small items that need them).
    if item_size <= 20 && bin_residual > item_size {
        score += (bin_residual as f64) * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: quadratic waste penalty, smoothed by stream progress
    let mut score = post * (1.0 + 0.8 * post_norm) + 12.0 * post_norm * post_norm;

    // Reward tight fits more strongly as the stream progresses
    let tightness = (bin_residual as f64 - item_size as f64).abs() / cap;
    score += 25.0 * tightness * (0.5 + progress);

    // Lookahead: bonus if the next item fits exactly into the post-residual
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let gap = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 30.0 * (1.0 - gap);
    } else if next_item_size > 0 && next_item_size as f64 > post {
        // next item cannot use this residual: penalize large leftover slightly
        score += 8.0 * post_norm * (1.0 - progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: keep it attractive only when residuals of open bins are poor
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score += 35.0 * (1.0 - mean_norm) * (1.0 - 0.5 * progress);
        score += 0.5 * open_bins_count as f64;
    } else {
        // Prefer reusing bins with residual below the mean (consolidation)
        let res_norm = bin_residual as f64 / cap;
        score += 10.0 * (res_norm - mean_residual / cap).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands in
    // "small residue" classes are more valuable to preserve.
    let post = post_residual as u32;
    let class = post % 10; // residue class mod 10
    // Reward (subtract) when post_residual is in a "composable" class,
    // i.e. likely to be filled by future small items (1..=100 unknown dist).
    let composable_bonus = match class {
        0 => 8.0,
        1 => 6.0,
        2 => 4.0,
        3 => 2.0,
        5 => 1.0,
        _ => 0.0,
    };
    score -= composable_bonus;

    // Integer-division thresholds: post_residual bucketed by capacity fraction.
    let quarter = (cap / 4.0) as u32;
    let half = (cap / 2.0) as u32;
    if post == 0 {
        score -= 15.0; // perfect fit, always great
    } else if post < quarter / 2 {
        score -= 6.0; // tiny dead space, nearly perfect
    } else if post < quarter {
        score -= 2.0;
    } else if post < half {
        score += 0.0;
    } else if post <= bin_residual {
        score += (post as f64) * 0.25; // very empty bin used wastefully
    }

    // Penalize pairing with next item poorly: if next item exactly fills
    // this bin's post_residual, big reward; if it can't fit anywhere else
    // consideration, mild coupling.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 12.0;
        } else if next_item_size < post && post - next_item_size <= 5 {
            score -= 7.0;
        } else if next_item_size > post {
            score += 3.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral baseline; open a new bin only when all
    // existing fits are poor (high post_residual relative to capacity).
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative, must open
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.max(1) {
            score -= 10.0; // next item pairs well with fresh full bin
        }
    }

    // Mild stream progression coupling: prefer tight packing early,
    // allow slight sprawl later when many bins already open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += mean_residual * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 9.0; // gaps below typical min item size are pure dead space
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 40.0;
    }
    // Penalize mid-range residuals that likely fit few future items
    if post_residual > 0 && post_residual < item_size {
        score += 6.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight fit bonus: item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins,
    // but for the new-bin candidate (residual == capacity) add pressure instead.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits the post-residual exactly or well, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 8.0 * next_fit;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Progress-based mild tightening: later in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual.
    let tight = (post_residual as f64) / bin_capacity as f64;
    score -= 40.0 * (-8.0 * tight).exp();

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (-0.15 * gap).exp();
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize wasting residual that could hold it.
        let waste = next_item_size as f64 - post_residual as f64;
        score += 12.0 * (-0.2 * waste).exp();
    }

    // Relative to mean residual: bins with residual far above mean are "loose"; prefer them.
    score -= 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // and the next item is large relative to this fit.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 30.0;
        let lookahead_bad = next_item_size > 0 && post_residual < next_item_size;
        let mut penalty = 20.0;
        if poor_fit { penalty += post_residual as f64 * 0.5; }
        if lookahead_bad { penalty -= 15.0; }
        // Early in stream, opening bins is cheaper (more room to consolidate later).
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty += 10.0 * progress;
        // Many open bins: discourage adding more.
        penalty += 2.0 * open_bins_count as f64;
        score += penalty;
    }

    // Mild penalty scaled by how much of the bin is left unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // dead space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * tightness * tightness;

    // Reward perfect fills aggressively.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize large dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        // small slivers are nearly useless
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow here; slight penalty for wasting capacity
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): penalize moderately so we prefer reusing open bins,
    // but less when many items remain and open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // open new bins more readily early on or when existing residuals are tiny
        score = 5.0 + 40.0 * fragmentation - 15.0 * (1.0 - progress);
        if item_size > 70 {
            // very large items: a fresh bin is often fine
            score -= 10.0;
        }
    }

    // Mild preference for bins with residual close to item (best-fit flavor).
    let gap = (bin_residual as i64 - item_size as i64) as f64;
    score += 0.05 * gap.abs();

    // Prefer bins below mean residual slightly (keep a spread of sizes).
    score += 0.02 * (bin_residual as f64 - mean_residual);

    // Time-dependent exploration: slight bias toward fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling: penalize mid-range wasted space more
    let x = pr / cap; // normalized post residual
    score += 40.0 * x * (1.0 - x) * (1.0 + progress);

    // Reward tight fits (small post residual) increasingly over time
    score -= 25.0 * (1.0 - x) * (1.0 - x) * (0.5 + progress);

    // Lookahead: reward if next item fits exactly into post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_gap = (pr - nx) / cap;
            score -= 20.0 * (1.0 - fit_gap) * (1.0 - progress * 0.5);
        } else {
            score += 10.0 * progress;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize so we only open when fit is bad
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * (1.0 - progress) + 0.2 * open_bins_count as f64;
        // but allow opening if all existing fits would leave terrible dead space
        let dead = (pr / cap - 0.5).max(0.0);
        score -= 60.0 * dead * dead;
    }

    // Mean residual coupling: prefer bins whose residual is near the mean (balance)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space penalty grows for
    // residuals that are "awkward" (large but not matching common item sizes).
    let pr = post_residual;
    let awkward = if pr == 0 {
        0.0
    } else if pr < 10 {
        -2.0 // tiny leftover is excellent
    } else {
        // penalize residuals that are not close to a multiple of 10
        let m = pr % 10;
        let m_pen = if m == 0 { 0.0 } else { m as f64 * 0.15 };
        let size_pen = (pr as f64 / cap_f).powi(2) * 12.0;
        m_pen + size_pen
    };
    score += awkward;

    // Perfect fits and near-perfect fits get strong rewards.
    if pr == 0 {
        score -= 15.0;
    } else if pr <= 5 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // this placement is harmonic — reward it.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 10.0;
        } else if next_item_size < pr {
            let nxt_res = pr - next_item_size;
            // reward smooth chaining, penalize leaving awkward next gap
            if nxt_res % 10 == 0 {
                score -= 4.0;
            }
            score -= (next_item_size as f64 / cap_f) * 3.0;
        } else {
            // next item cannot follow here: mild penalty, worse if pr large
            score += (pr as f64 / cap_f) * 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current bin would leave a large, awkward residual.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = cap_f * 0.9;
        // cheaper to open a new bin early in the stream when many bins open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
        // if existing fit would be terrible, new bin wins
        if (bin_residual - item_size) < 15 {
            score -= 5.0;
        }
        // avoid proliferating bins
        score += open_bins_count as f64 * 0.8;
        // if mean residual is small, existing bins are well packed; prefer them
        score += (mean_residual / cap_f) * 20.0;
    }

    // Slight preference for tighter bins among comparable fits.
    score -= (bin_residual as f64 / cap_f) * 1.5;

    // Harmonic modulo bonus: residual after placement divisible by common
    // item classes (10, 20, 25) is more reusable.
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for tiny unusable gaps (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving a gap that the next item can fill
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 25.0; // next item seals the bin
        } else {
            score -= 8.0;
        }
    }
    // Penalize if next item cannot use the leftover gap
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: prefer existing bins when many are open
    score += open_bins_count as f64 * 1.5;

    // Prefer bins with below-mean residual (tighter bins first)
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: baseline slightly above good fits, but beats bad fits
    if bin_residual == bin_capacity {
        score = 55.0 + open_bins_count as f64 * 0.5;
        // Late in the stream, closing out bins is cheaper
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score -= 10.0;
        }
        // If next item is small, a fresh bin is attractive
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual, the better.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - 2.0 * fit_ratio).abs() * (1.0 - fit_ratio);

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item can also fit here: excellent chaining.
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Post residual is dead space relative to the next item; penalize
            // proportionally to how wasted it is.
            score += 25.0 * (post_residual as f64 / bin_capacity as f64);
        }
        // Exact match with next item is ideal.
        if post_residual == next_item_size {
            score -= 50.0;
        }
    }

    // Penalize bins that deviate strongly from mean residual (prefer balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Slight penalty when many bins are open (encourage consolidation).
    score += 0.5 * open_bins_count as f64;

    // Late in the stream, be more conservative about waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * fit_ratio;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 60.0 + 20.0 * (1.0 - fit_ratio);
        if fitting_bins_count == 0 {
            score -= 120.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Non-linear tightness reward: strongly favor small post residuals.
    score += 0.35 * (post / cap).powi(2) * cap;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead-space penalty: residuals too small for typical future items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item can use this bin's post_residual, reward it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        } else {
            // Post residual cannot host next item: mild penalty proportional to waste.
            score += 3.0 * (post / cap);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a bin when decent fits exist,
    // unless current bins would create large dead space.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let waste_if_forced = (bin_residual - item_size) as f64;
        // Opening a new bin is attractive only if all existing fits are terrible
        // (i.e., would leave big unusable residuals) or no bins fit.
        let pressure = if fitting_bins_count == 0 {
            -30.0
        } else {
            (mean_residual - item) - 15.0
        };
        score = 55.0 + waste_if_forced * 0.25 + scarcity * 5.0 - pressure.max(0.0);
        // Early in the stream, opening bins is cheap and builds flexibility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // Many open bins: discourage spreading further.
        score += open_bins_count as f64 * 1.5;
    } else {
        // Mild reward for using already-open bins, scaled by congestion.
        score -= 2.0;
        score += open_bins_count as f64 * 0.2;
        // Prefer bins whose residual deviates favorably from the mean (consolidation).
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    // Time horizon: late in the stream, be conservative—minimize residual strictly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;
    let fill = 1.0 - pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Reward high fill non-linearly
    score -= 30.0 * fill * fill * fill;

    // Penalize large dead space quadratically, amplified late in stream
    score += 0.15 * pr * pr * (0.5 + progress);

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if pr >= nx { 1.0 } else { 0.0 };
        let slack = ((pr - nx).abs()) / cap;
        score -= 12.0 * fits_next * (1.0 - slack * slack);
        score += 6.0 * slack * (1.0 - fits_next);
    }

    // Last-chance bin bonus (smoothly weighted by scarcity of fitting bins)
    if fitting_bins_count <= 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin when others fit, decay with stream progress
    if bin_residual == bin_capacity {
        let others_fit = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += 40.0 * others_fit * (1.2 - progress);
        score -= 10.0 * fit_ratio;
    }

    // Mild preference for bins below mean residual (consolidate emptier bins)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: exact-fit bucket gets strong reward
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always best
    } else {
        // small dead space classes via integer division thresholds
        if post_residual <= 10 { score -= 40.0; }
        else if post_residual <= 20 { score -= 20.0; }
        else if post_residual <= 30 { score -= 8.0; }
        else { score += (post_residual as f64 - 30.0) * 0.5; }
    }

    // Modulo-class coupling: does post_residual pair with next item?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            // next item fits exactly or near-exactly here -> reward
            let gap = pr - nx;
            score -= 60.0 - gap * 1.2;
        } else {
            // next item cannot use this bin's leftover: penalize proportional dead space
            score += 10.0 + (nx - pr) * 0.15;
        }
        // harmonic pair check: (item + next) close to capacity
        let pair = (item_size + next_item_size) as f64;
        if pair <= cap {
            let slack = cap - pair;
            if slack <= pr as f64 {
                score -= 25.0 - slack * 0.5;
            }
        }
    } else {
        // last item: prefer tightest bin
        score -= 5.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: neutral-ish, penalize slightly unless current
    // alternatives are poor; opening early is fine when mean residual is high
    if bin_residual == bin_capacity {
        let waste = (mean_residual * open_bins_count as f64) / cap;
        score = cap * 0.5 + waste * 10.0;
        if fitting_bins_count == 0 { score -= 50.0; }
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 15.0; // next item needs fresh space anyway
        }
    }

    // Fractional capacity coupling: reward bins whose residual fraction
    // complements common item classes (mod-10 harmonics)
    let frac = pr / cap;
    let harm = (frac * 10.0).round() / 10.0;
    if harm >= 0.1 && harm <= 0.3 {
        score += 6.0; // awkward leftover band
    } else if harm == 0.0 {
        score -= 30.0;
    }

    // Late-stream consolidation: fewer bins favored as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64) * 0.05;

    // Mean-residual alignment: prefer bins near the mean residual
    score += ((pr - mean_residual) / cap).abs() * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small non-zero post_residuals are "dead space": unusable for typical future
    // items, so penalize them extra (wasting 1-15 units is worse than leaving 40).
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 15 {
        score += (16.0 - pr) * 3.0; // up to +45 for nearly-perfect-but-wasted fits
    } else if post_residual == 0 {
        score -= 20.0; // perfect fit: strongly reward closing the bin
    }

    // --- Lookahead coupling: if the next item fits exactly in post_residual,
    // this placement is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // next item would have fit if we hadn't placed here
            score += 10.0;
        } else if n < pr {
            score -= (n / pr).min(1.0) * 8.0;
        }
    }

    // --- Tightness reward: fraction of bin used by this placement ---
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 12.0;

    // --- Open-bin pressure: discourage scattering across many open bins,
    // but relax late in the stream when consolidation matters less.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 - 0.5 * progress);
    score += pressure * 0.8;

    // --- Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (penalize new-bin alternative implicitly).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // --- Mean residual context: if this bin's residual is far below the mean,
    // it's a poorly-utilized outlier; using it consolidates waste.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.3;
    }

    // --- New-bin candidate handling: brand-new empty bin.
    // Base it on what would remain after placement; only attractive when the
    // item is huge (little waste) or no existing bin fits well.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        let mut new_bin_score = waste;
        // penalize opening new bins when good alternatives exist
        new_bin_score += open_bins_count as f64 * 2.0;
        if fitting_bins_count > 0 {
            new_bin_score += 18.0; // existing bins fit: new bin must lose unless they're bad
        }
        // huge items almost fill a bin: new bin is fine
        if item_size >= 85 {
            new_bin_score -= 25.0;
        }
        // late in stream, avoid spawning bins for small leftovers
        if progress > 0.8 && item_size < 40 {
            new_bin_score += 20.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact / tight fits (low dead space).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            // The next item fits; the smaller the leftover slack after that, the better.
            let slack_after_next = post_residual - next_item_size;
            score -= 40.0 - (slack_after_next as f64).min(40.0);
        } else {
            // Next item would NOT fit here: penalize proportionally to the gap,
            // so we prefer bins that don't strand the lookahead item.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter (smaller residual) than average.
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make it mildly unattractive so we consolidate into open
    // bins unless they are all bad fits; scale with stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 + 30.0 * progress;
        // But if the next item is large and won't fit anywhere else, opening a
        // fresh bin with room for both is good: soften the penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 35.0;
        }
    }

    // Slight preference for consolidating when many bins are open.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual to strongly prefer near-perfect packing.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Lookahead: if the next item can fit into the post-residual, this bin remains useful.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64) * 0.15;
    } else if next_item_size > 0 {
        // Dead space relative to the next item's need is penalized.
        let waste = (post_residual as f64).min(next_item_size as f64);
        score += waste * 0.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins are crowded or fit poorly.
    if bin_residual == bin_capacity {
        let crowding = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0;
        score -= crowding * 35.0 + progress * 8.0 + (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // big pair coming: fresh bin is fine
        }
    } else {
        // Slight preference for bins below mean residual (consolidate emptier bins).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Time-horizon modulation: late in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with progress.
    // Early in the stream, prefer tight fits strongly; later, tolerate slack
    // slightly more but still punish dead space super-linearly.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let tightness = 1.0 - pr / cap; // 1.0 = perfectly tight fit

    // Smooth non-linear interaction: progress-modulated cubic in tightness
    score -= 12.0 * (1.0 - progress) * tightness * tightness * tightness;
    score -= 6.0 * progress * tightness * tightness;

    // Penalize residuals that are too small to ever fit a plausible item
    // (dead space), with a smooth saturating term.
    if post_residual < 10 {
        score += 30.0 * (1.0 - pr / 10.0);
    }

    // Lookahead coupling: penalize if post_residual cannot host the next item,
    // reward if it exactly leaves room for the next item (smooth hinge).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap < 0.0 {
            score += 8.0 * (-gap / cap);
        } else {
            // smooth reward for residual close to next item size
            let closeness = (gap / cap).min(1.0);
            score -= 5.0 * (1.0 - closeness) * (1.0 - closeness);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
        score -= 8.0;
    }

    // Mild penalty for spreading across many open bins vs consolidating.
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    // New-bin candidate handling: an empty bin has pr == cap, so tightness = 0;
    // add a smooth penalty so it loses to decent fits but wins over bad ones.
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: coarse capacity fractions.
    let class = post_residual / (bin_capacity / 5); // classes 0..=4 (0,1-19,20-39,...)
    match class {
        0 => score -= 25.0,               // near-perfect fit, tiny dead space
        1 => score -= 10.0,               // small leftover, still usable for small items
        2 => score -= 3.0,
        3 => score -= 0.0,
        _ => score += 5.0,                // very loose fit, wasteful
    }

    // Dead-space trap: leftover too small for the smallest plausible item (<=9)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Coupling with lookahead: leftover exactly fitting next item is golden
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0; // chains perfectly with next item
        } else {
            score -= (10.0 - slack.min(10) as f64) * 0.5;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0; // next item cannot use this leftover
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when fits are poor or bins are fragmented
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fits = (post_residual as f64) / bin_capacity as f64; // = 1.0 for empty bin
        let pressure = mean_residual / bin_capacity as f64;
        // Penalize new bins mildly; reward when open bins are highly fragmented late in stream
        score += 20.0 - 15.0 * pressure - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Mild preference to fill bins when many are open (consolidation)
    score += open_bins_count as f64 * 0.05;

    // Slight tilt: prefer bins below mean residual (keep balance of usable space)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are worthless.
    let min_item = 10.0f64.min(bin_capacity as f64); // guard for 1..100 interface
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        // gap can never be used by any item -> heavy penalty
        score += 60.0 * (10.0 - pr) / 10.0 + 25.0;
    } else if pr < min_item {
        // near-dead zone for larger items: moderate penalty
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to item)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let avg_waste = (mean_residual - item_size as f64).max(0.0);
        // penalize opening new bins when existing bins have decent room
        score += 45.0 + open_pressure * 2.0;
        if avg_waste < 15.0 {
            score += 20.0; // open bins are nearly full anyway -> new bin ok
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: nothing fits
        }
    }

    // Lookahead: if next item fits exactly in the post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 10.0; // leads to dead space after next item
        }
    }

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.8;

    // Slight preference for fuller bins as stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) with a non-linear penalty.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).sqrt() * 10.0;

    // 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        if diff < 1.0 {
            score -= 25.0; // perfect chain: next item exactly fills this bin
        } else if nxt <= pr {
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to wasted gap
            score += 0.25 * diff;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious tight bins.
    if pr < mean_residual {
        score += 0.5 * (mean_residual - pr);
    } else {
        score -= 0.15 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 55.0;
        // allow new bin early in stream or when many bins open and fit is loose
        let progress = step_index as f64 / total_items.max(1) as f64;
        if pr > 40.0 && (progress < 0.2 || open_bins_count > 8) {
            score -= 45.0;
        }
    }

    // Late-stream: consolidate harder, avoid spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * (1.0 - tightness);

    // Reward bins whose residual is close to the item (good fill)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: penalize leaving a residual that cannot hold next item
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }
    // Reward residual that exactly accommodates the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global pressure: many open bins with low mean residual -> consolidate
    if open_bins_count > 2 {
        score += 0.5 * (open_bins_count as f64).ln() * (1.0 - mean_residual / bin_capacity as f64);
    }

    // Penalize creating large unusable dead space as stream matures
    if post_residual > 0 && post_residual < 10 {
        score += 5.0 * (0.5 + progress);
    }

    // New-bin candidate handling: discourage opening a new bin when existing bins fit well
    if bin_residual == bin_capacity {
        let escape = if fitting_bins_count == 0 { 0.0 } else { 40.0 + 10.0 * (fitting_bins_count as f64) };
        // Allow new bin for very large items that would leave awkward slivers
        let sliver = if item_size >= 60 { 15.0 } else { 0.0 };
        score += escape - sliver;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tighter fits (small post_residual), with a non-linear
    // polynomial coupling to stream progress. Early on, leave room for
    // future items (mildly favor larger residuals); late, pack tightly.
    let mut score = pr * (1.0 + 0.8 * progress * progress) - 12.0 * norm_pr * (1.0 - progress);

    // Dead-space penalty: post_residual that is too small to matter
    // (smooth quadratic ramp around the smallest item size).
    let dead = ((pr - 1.0).max(0.0) / cap).powi(2);
    score += 30.0 * (1.0 - dead) * (1.0 - progress);

    // Lookahead coupling: reward residuals that can fit the next item,
    // penalize those that nearly-but-don't fit (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = (pr >= nx) as i32 as f64;
        let gap = (nx - pr).abs() / cap;
        score += 8.0 * gap * gap * (1.0 - fits) - 6.0 * fits * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mild penalty for scattering across many open bins vs mean residual.
    score += 0.5 * (open_bins_count as f64).ln() * (1.0 - progress);

    // New-bin candidate: penalize opening a fresh bin unless existing
    // residuals are all tight (smooth sigmoid of mean residual).
    if bin_residual == bin_capacity {
        let tight = 1.0 / (1.0 + (mean_residual / cap * 4.0).exp());
        score += 20.0 * (1.0 - tight) + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on a
    // "reusable" class (divisible by small common item sizes) are rewarded.
    let reusable = [1u32, 2, 4, 5, 10, 20, 25, 50];
    let mut class_bonus = 0.0;
    for &r in reusable.iter() {
        if post_residual % r == 0 {
            class_bonus += 6.0;
        }
    }
    // Exact-fit harmonic: post_residual zero is the ideal class.
    if post_residual == 0 {
        class_bonus += 60.0;
    }
    // Dead-space penalty for awkward tiny leftovers that nothing (min size 1..)
    // can pair with next: leftover smaller than next_item_size but nonzero.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    score -= class_bonus;

    // Integer-division threshold: leftover bucket by tenths of capacity.
    let tenths = (post_residual * 10) / bin_capacity;
    score -= match tenths {
        0 => 20.0,
        1 => 10.0,
        2 | 3 => 4.0,
        4 | 5 => 0.0,
        6 | 7 => -3.0,
        _ => -6.0,
    };

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current bins are
    // nearly full (their residuals are small relative to item needs).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowded = mean_residual < item_size as f64 * 0.5;
        score = 90.0 - 15.0 * progress;
        if crowded {
            score -= 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Lookahead coupling: if the next item exactly matches post_residual class,
    // reward leaving that amount.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 5 {
        score -= 15.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (1..=100) are wasted space. Penalize tiny
    // non-zero residuals heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 3.0;
    }

    // Perfect fit reward: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to bin residual (small post_residual as
    // fraction of what was available).
    let fit_ratio = post_residual as f64 / (bin_residual as f64).max(1.0);
    score += fit_ratio * 30.0;

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Penalize if post_residual is large enough to tempt but next item
    // would leave another awkward gap.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer
    // using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; favor
    // filling existing bins and discourage opening new ones.
    let open_pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score = bin_capacity as f64 + open_pressure;
        // Late in the stream, opening new bins is more acceptable only
        // if few bins are open; otherwise penalize more.
        if open_bins_count > 3 {
            score += 15.0;
        }
        // If next item is large and current residuals are small, new bin
        // may be attractive: mild discount.
        if next_item_size > 60 && mean_residual < next_item_size as f64 {
            score -= 25.0;
        }
    } else {
        // Filling an existing bin: reward proportional to how much of
        // the bin's mean residual we consume.
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
        // Prefer bins with below-mean residual (consolidate emptier bins).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // Early stream: keep options open, mildly discourage using
        // nearly-empty bins for tiny items.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.2 && item_size < 20 && bin_residual == bin_capacity - item_size {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small dead space is exponentially good).
    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // 2-step lookahead: strongly reward leaving exactly the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item can fit here afterwards: reward closeness of match.
            score -= 25.0 / (1.0 + gap);
        } else {
            // Next item would not fit in the leftover: penalize proportional to gap.
            score += gap * 0.5;
        }
        // Mild reward if next item fits the current residual too (flexibility).
        if next_item_size <= bin_residual {
            score -= 2.0;
        }
    }

    // Compare against mean residual: bins with unusually low residual are precious,
    // avoid wasting them on this item unless the fit is tight.
    if (bin_residual as f64) < mean_residual && post_residual > 10 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win if the item
    // fits poorly everywhere else (large post_residual in every open bin).
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is only chosen when open-bin fits are bad.
        score += 12.0;
        // Early in the stream, opening bins is cheap-ish; later it is costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If many bins already open, discourage spreading further.
        score += open_bins_count as f64 * 0.5;
    } else {
        // Reward using existing bins, more so when many are open.
        score -= (open_bins_count as f64).min(5.0) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized post-residual penalty (quadratic).
    let fit_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_frac * fit_frac;

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Small post-residuals that are still useful (can host small items later):
    // penalize residuals that are too small to be useful (dead space), e.g. < 10.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoiding bin proliferation).
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With multiple fitting bins, prefer less crowded global state mildly.
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if the next item fits in the post-residual, reward this bin
    // (chaining placements); if it would fit better elsewhere, mild penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // extra reward if next item nearly fills the bin after this one
            let chain_post = post_residual - next_item_size;
            if chain_post < 10 {
                score -= 8.0;
            }
        } else if next_item_size <= bin_residual {
            // next item fits this bin now but not after current item: slight penalty
            score += 6.0;
        }
    }

    // Prefer bins with above-average residual when mean residual is high
    // (spread load evenly early), but prefer below-average when mean is low
    // (consolidate late). Time horizon coupling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let diff = bin_residual as f64 - mean_residual;
    if progress < 0.5 {
        score += 0.05 * diff;
    } else {
        score -= 0.05 * diff;
    }

    // Late in the stream, consolidate aggressively: penalize leaving many open bins.
    if progress > 0.7 {
        score += 0.3 * open_bins_count as f64;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is only attractive when current item fits poorly
    // everywhere else (large post_residual in existing bins) or few bins fit.
    if bin_residual == bin_capacity {
        // Base bias against opening new bins.
        score += 45.0;
        // But relax the bias when many bins are open and mean residual is small
        // (existing bins are nearly full anyway) or few bins can fit the item.
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 / fitting_bins_count as f64 };
        score -= 30.0 * scarcity;
        score -= 0.1 * open_bins_count as f64;
        // If next item is large, a fresh bin can host it later: slight discount.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Smooth non-linear coupling: waste pressure grows as the stream progresses
    let waste_pressure = (post_residual as f64 / cap).powi(2) * (0.5 + 1.5 * progress * progress);
    score += waste_pressure * 20.0;

    // Reward tight fits: quadratic bonus shrinking as post_residual approaches 0
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 15.0 * tightness * tightness * tightness;

    // Penalize dead space that cannot fit the next item (smooth interaction)
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = (next - post_residual as f64).max(0.0) / cap;
        score += 25.0 * gap * gap;
        // Reward leaving exactly enough room for the next item
        let room_match = 1.0 - ((post_residual as f64 - next) / cap).abs();
        if room_match > 0.0 {
            score -= 10.0 * room_match * room_match;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty when many bins are open and residual is far above mean (imbalance)
    let imbalance = (post_residual as f64 - mean_residual) / cap;
    score += 5.0 * imbalance * imbalance;

    // Slight preference for filling bins deeper as stream nears its end
    score -= progress * (item_size as f64 / cap) * 4.0;

    // New-bin candidate: keep it neutral-to-slightly-high so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual modulo capacity fractions
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Class-1 residues: small dead space (0..10) is ideal
    if post_residual < 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    } else if post_residual <= 40 {
        score += 6.0;
    } else {
        score += 15.0;
    }

    // Modulo classes: residuals that are multiples of 10 align with item granularity
    if post_residual % 10 == 0 {
        score -= 5.0;
    }
    if post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Exact fill reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this residual; penalize large wasted space
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a base offset that scales
    // with how badly existing bins would fragment
    if bin_residual == bin_capacity {
        score = cap - item_size as f64 + 8.0;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // early stream: opening bins is cheap; late stream: prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer bins below mean residual (tighter packing)
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small to hold even the smallest plausible item are toxic.
    // With sizes 1..100 unknown, treat gaps below ~25% of capacity as "at risk".
    let dead_threshold = bin_capacity as f64 * 0.25;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        // quadratic penalty on unusable slivers
        let ratio = 1.0 - (post_residual as f64) / dead_threshold;
        score += 40.0 * ratio * ratio;
    }

    // Perfect fit is heavily rewarded
    if post_residual == 0 {
        score -= 60.0;
    } else if next_item_size > 0 {
        // Lookahead: reward if the next item fits exactly-ish in the post residual
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this gap -> penalize proportional to gap size
            score += 0.3 * (post_residual as f64);
        }
    }

    // --- Open-bin pressure: discourage spreading across many bins ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).powf(0.7) * (0.5 + 0.5 * progress);

    // Penalize bins whose residual is far above the mean (wasteful hoarding of space)
    score += 0.2 * ((bin_residual as f64 - mean_residual).abs());

    // --- Last-chance bonus: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin: high, but tunable so that a very poor
        // fit in existing bins (large dead-space penalty) can still justify opening.
        score = bin_capacity as f64 + 20.0 + (open_bins_count as f64) * 2.0;
        // Early in the stream, opening bins is cheaper (build a diverse portfolio)
        score -= 40.0 * (1.0 - progress);
        // If next item is large and current residuals are tight, new bin is attractive
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 25.0;
        }
        // Perfect fit elsewhere (post_residual==0 gives -60) will beat this.
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact match with the next item (2-step lookahead).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 20.0 / (1.0 + diff);
        // Bonus if post_residual exactly fits the next item.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize post_residuals that are too small to ever be useful later
        // (dead space), but only mildly if they match the next item.
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0;
        }
    }

    // Compare against mean residual across open bins: prefer bins whose
    // post_residual deviates from the mean toward small usable values.
    let mean_dev = post_residual as f64 - mean_residual;
    score += 0.15 * mean_dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent fits exist, unless residuals
    // across open bins are very fragmented (high mean residual).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 15.0 - 20.0 * fragmentation;
        // If next item is large, a fresh bin is attractive.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Slight preference early in the stream to consolidate into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * (1.0 - progress) * (open_bins_count as f64 / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit preference with non-linear penalty on mid-range waste.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste * (1.0 - waste); // penalize half-full leftovers most

    // Reward tight fits (small post_residual) super-linearly.
    if post_residual <= 5 {
        score -= 8.0;
    } else if post_residual <= 15 {
        score -= 3.0;
    }

    // Lookahead (k=2): reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (next_item_size as f64 / post_residual as f64);
    }
    // Penalize leaving exactly a gap that no typical item (>=10) can use,
    // generalized: dead space smaller than the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Global pressure: many open bins -> consolidate into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += pressure * 2.0 * waste;

    // Time horizon: late in the stream, avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 3.0;

    // New-bin candidate handling: empty bin gets a moderate baseline score.
    if bin_residual == bin_capacity {
        // Prefer new bin only when the current item is large and would leave
        // a poor fit elsewhere, or when few bins fit the item.
        let poor_fit_elsewhere = (post_residual as f64) > 0.55 * bin_capacity as f64;
        if poor_fit_elsewhere || fitting_bins_count <= 2 {
            score -= 4.0;
        } else {
            score += 6.0;
        }
        // Late stream: opening new bins is costly.
        score += progress * 5.0;
    } else {
        // Existing bins: reward being closer to full than the average bin.
        score -= (mean_residual - post_residual as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: waste after placement, non-linearly scaled.
    let mut score = post * post / cap;

    // Smooth interaction: waste becomes more costly as stream progresses.
    score += post * (0.5 + 1.5 * progress * progress);

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / cap;
    score -= tightness * (cap - post) * 0.5;

    // Penalize new-bin opening, more so when many bins are open or fitting bins exist.
    if is_new_bin {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // But relax penalty late in stream if mean residual is high (fragmentation).
        score -= 10.0 * progress * (mean_residual / cap);
    } else {
        // Reward using an existing bin, especially when it's the only fit.
        if fitting_bins_count == 1 {
            score -= 25.0;
        } else {
            score -= 5.0 + 3.0 * progress;
        }
    }

    // Lookahead coupling: penalize leaving residual that barely fails next item,
    // reward residuals that can host next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post >= ni {
            score -= 8.0 * (1.0 - progress);
        } else if post > 0.0 && post > ni * 0.5 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Mild penalty for residual that is unusably small but nonzero (dead space).
    if post > 0.0 && post < 10.0 {
        score += 12.0 * (1.0 - post / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo small divisors
    // captures "usable leftover" structure (e.g. residuals divisible by
    // common item sizes are easier to fill later).
    let pr = post_residual;
    let class_score = ((pr % 10) as f64) * 1.5
        + ((pr % 20) as f64) * 0.8
        + ((pr % 25) as f64) * 0.6;
    score += class_score * 0.35;

    // Perfect fit or near-perfect fit: strong reward.
    if pr == 0 {
        score -= 500.0;
    } else if pr <= 3 {
        score -= 200.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly
    // or very well (chained packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score += slack * 0.9;
            // harmonic class of chained leftover
            score += (((pr - next_item_size) % 10) as f64) * 0.5;
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += (next_item_size - pr).min(40) as f64 * 0.4;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only open a new bin if existing bins are
    // badly fragmented (mean residual low relative to item needs) or item
    // is large relative to mean residual.
    if bin_residual == bin_capacity {
        // base attractiveness of fresh bin: its post_residual is large,
        // so offset the natural advantage with a penalty.
        score += 55.0 + open_bins_count as f64 * 1.2;
        // if many bins can fit the item, prefer reusing one
        if fitting_bins_count > 0 {
            score += 25.0;
        }
        // early in stream, slightly prefer consolidating
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += (1.0 - progress) * 20.0;
    } else {
        // reward filling bins whose residual is close to item size (tight fit)
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= (1.0 - tightness) * 15.0;
        // reward reducing deviation of this bin's residual from the mean
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= (30.0 - dev.min(30.0)) * 0.3;
    }

    // Dead-space penalty: leftover that no plausible item (>=1) can use
    // is already captured by post_residual; extra penalty for tiny leftovers
    // that block future medium items.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // minimum item are pure waste -> hard penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        // gap cannot host the lookahead item -> likely dead space
        score += 25.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Reward tight fits (small post_residual relative to capacity).
    score -= 18.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling.
    score += 0.8 * open_bins_count as f64;

    // New-bin candidate handling: only attractive when no open bin fits well,
    // i.e. penalize the empty bin so existing bins win unless forced.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 + 10.0 * progress;
        // If the current item leaves a large gap and the next item is big,
        // a fresh bin is more acceptable.
        if post_residual > 0 && next_item_size > post_residual {
            score -= 20.0;
        }
        // If no open bin can fit, this call is effectively the only option.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild alignment with mean residual state: prefer bins below mean residual
    // (they are emptier than average -> keep big gaps available for big items).
    score += 0.15 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but only if it remains "usable".
    // Usability threshold: residual >= smallest plausible item (1..100 unknown, use small floor).
    let usable_floor = 1.0f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if (post_residual as f64) < usable_floor {
        score -= 1000.0; // perfect fit, extremely desirable
    }

    // Aggressive 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Coupling: reward scaled by how snugly the next item fits.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 12.0 + 20.0 * snug;
        } else {
            // Dead space penalty: post_residual too small for the lookahead item.
            // Penalize more strongly when post_residual is nonzero but useless.
            let waste = (post_residual as f64) / bin_capacity as f64;
            score += 8.0 + 25.0 * waste;
        }
    } else {
        // Last item: just minimize residual directly (already base score).
        score -= 5.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight";
    // filling them is good (consolidates waste). Bins far above mean are roomy;
    // placing small items there is wasteful unless lookahead fits.
    let rel = (bin_residual as f64) - mean_residual;
    score -= 0.08 * rel;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has maximal residual. Make it
    // attractive only when no open bin offers a good 2-step fit, i.e. when the
    // current item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        // Empty bin gets a moderate baseline; large items should prefer it.
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 30.0;
        score -= 10.0 + large_item_bonus;
        // Late in the stream, opening new bins is cheap since stream ends soon.
        score -= 10.0 * progress;
        // If many bins are open and residuals are high, spreading is fine.
        score -= 0.02 * open_bins_count as f64;
    }

    // Slight early-stream preference for keeping bins balanced (avoid many tiny opens).
    score += 0.01 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residuals non-linearly (dead space is super-linearly bad).
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).powi(3) * bin_capacity as f64;

    // Reward tight fits: small post_residual relative to bin_capacity.
    score -= 12.0 * (1.0 - pr / bin_capacity as f64);

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // partial reward proportional to how well next item fills remainder
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot fit: mild penalty for stranding space
            score += 4.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, heavily favor using it.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Prefer bins with residual close to the item (best-fit style).
    score += 0.5 * ((bin_residual as f64 - item_size as f64).abs() / bin_capacity as f64) * 10.0;

    // Global state: when many bins are open and mean residual is high,
    // discourage opening/using extra space; encourage consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins open or late in stream,
        // but allow it if existing bins are nearly full (mean residual low).
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        score += 20.0 + 30.0 * crowding + 15.0 * progress
            - 10.0 * (mean_residual / bin_capacity as f64);
    } else {
        // Reward using existing bins more strongly as stream progresses.
        score -= 6.0 * progress;
        // If mean residual is small, existing bins are precious; use them well.
        if (mean_residual - item_size as f64).abs() < 5.0 {
            score -= 5.0;
        }
    }

    // Mild stochastic-free tie-breaker: prefer lower-indexed-equivalent (denser) bins
    // via mean residual comparison.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;
    let mut score = pr as f64;
    // Smooth non-linear coupling of post_residual with stream progress
    score -= 18.0 * x * (1.0 - x) * (1.0 + 2.0 * progress);
    score -= 10.0 * x * x * progress;
    // Penalize large dead space as stream progresses
    score += 6.0 * x * x * x;
    // Reward tight fits when few bins can fit the item
    if fitting_bins_count <= 1 {
        score -= 25.0;
    } else {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }
    // Lookahead: reward residual matching next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let diff = (pr - n) / cap;
        score -= 12.0 * (-8.0 * diff * diff).exp();
    }
    // Slight preference for bins with below-average residual (consolidate waste)
    score += 2.0 * ((bin_residual as f64 - mean_residual) / cap);
    // New-bin candidate: penalize mildly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well does leftover space align
    // with typical future item sizes (1..100)? Classify by integer division.
    let pr = post_residual;
    let class = pr / 10; // coarse decile class of dead space

    // Perfect fit: zero dead space is ideal.
    if pr == 0 {
        score -= 1000.0;
    }

    // Tiny residuals (<10) are nearly unusable dead space -> penalize.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Residuals in 10..=30 are "re-usable" only for small items; mildly penalize.
    if pr >= 10 && pr <= 30 {
        score += 5.0;
    }

    // Harmonic coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0; // perfect harmonic pair
        } else if next_item_size < pr {
            // next item fits: reward proportional to how snugly it fits
            let slack = pr - next_item_size;
            if slack < 10 {
                score -= 80.0;
            } else {
                score -= (pr as f64 - slack as f64) * 0.3;
            }
        } else {
            // next item does NOT fit here: leftover must hold until later;
            // penalize more if residual is in a "useless" class
            if class <= 2 {
                score += 15.0;
            }
        }
        // modulo harmony: post_residual % next_item_size small means future
        // items of that size tile the leftover nicely
        if next_item_size > 0 && pr >= next_item_size {
            let m = pr % next_item_size;
            if m == 0 {
                score -= 60.0;
            } else if m < 10 {
                score -= 20.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 40.0;
        // opening a new bin is fine if this bin's fit would leave bad dead space
        if pr > 0 && pr < 20 {
            score -= 60.0;
        }
        // if only one bin fits and it's tight, new bin is attractive
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // early in stream, keep bins open; late, consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * (1.0 - progress);
    }

    // Prefer fuller bins: compare residual to mean residual across open bins.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Many open bins: encourage filling existing ones rather than spreading.
    if open_bins_count > 4 {
        score -= 2.0 * open_bins_count as f64 * 0.1;
    }

    // Exact-fill harmony with capacity fractions: residual that is a clean
    // fraction of capacity is more predictable/usable.
    if pr > 0 && (bin_capacity % pr == 0) {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for tiny unusable gaps (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits
    if post_residual == 0 {
        score -= 40.0;
    }

    // Prefer bins whose residual closely matches item size
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 25.0 * tightness * tightness;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate: make it attractive only when item is large and fits poorly elsewhere
    if bin_residual == bin_capacity {
        score -= 5.0;
        if item_size > 70 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for fuller bins as stream progresses
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if next_item_size > 0 {
        // Perfect 2-step chain: post_residual exactly matches next item
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits, reward closeness of the chain fit
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 * (-gap / 25.0).exp();
        } else {
            // Next item won't fit; penalize wasted post-residual relative to next size
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste.min(60.0);
        }
    }

    // Penalize post_residual too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer bins whose residual is tight relative to the mean (compact packing)
    score += 0.25 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize mildly so we only open when fits are poor,
    // but relax the penalty as the stream progresses
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 100.0;
        }
    }

    // Slight preference for fewer open bins when item is large
    score += 0.02 * open_bins_count as f64 * (item_size as f64 / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual (tight fits).
    let mut score = post;

    // Strong reward for near-perfect fits.
    if post == 0.0 {
        score -= 60.0;
    } else if post <= 10.0 {
        score -= 35.0;
    } else if post <= 20.0 {
        score -= 15.0;
    }

    // Penalize dead space relative to capacity (quadratic waste).
    score += (post / cap) * (post / cap) * 40.0;

    // Lookahead: reward leaving a residual that the next item can use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = post - nxt;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here: penalize more if residual is awkwardly small.
            score += 6.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Many fitting bins: mild penalty to encourage consolidation diversity.
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state coupling: if mean residual is low, treasure tight fits more.
    score -= (mean_residual / cap) * 8.0 * (1.0 - post / cap);

    // Time horizon: early in the stream, be more conservative (penalize small residuals
    // that fragment future capacity); late in the stream, pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 10.0 * (post / cap);

    // Open-bin pressure: many open bins -> prefer filling existing ones over new bins.
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate handling: opening a new bin is only attractive when no good fit
    // exists elsewhere. Make it mediocre by default but allow it when the current bin
    // would leave a very awkward residual and many bins already fit the item poorly.
    if bin_residual == bin_capacity {
        // Empty bin: residual after placement is cap - item; it competes normally,
        // but add a mild opening cost so existing decent fits win.
        score += 8.0;
        // If the item is large relative to capacity, a fresh bin is actually good.
        score -= (item / cap) * 10.0;
        // If few bins can fit the item, opening a bin is safer.
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);

    let mut score = pr - 12.0 * poly;

    // Reward tight fits more strongly later in the stream.
    let tight = 1.0 - (pr / cap).powf(2.0);
    score -= tight * (1.0 + 2.0 * progress) * 8.0;

    // Penalize opening new bins when existing bins fit, scaled by open bin count.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + 3.0 * (open_bins_count as f64).ln();
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: penalize if next item cannot use the resulting residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next > pr {
            score += 6.0 * progress * (next - pr) / cap;
        } else {
            score -= 4.0 * (1.0 - progress) * (pr - next) / cap;
        }
    }

    // Mean residual coupling: prefer bins near the mean (balance residuals).
    let dev = (pr - mean_residual).abs();
    score += 3.0 * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: exact division classes of capacity.
    // Residuals that are multiples of 25 or 50 are "harmonic" and reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: close the bin, excellent
    } else if pr % 50 == 0 {
        score -= 25.0;
    } else if pr % 25 == 0 {
        score -= 15.0;
    } else if pr % 10 == 0 {
        score -= 8.0;
    } else if pr < 10 {
        score += 40.0; // dead space below minimum item size
    }

    // Fractional capacity tier of post-residual
    let frac = pr as f64 / cap;
    if frac > 0.5 {
        score -= 10.0;
    } else if frac < 0.2 {
        score += 12.0;
    }

    // Lookahead coupling: reward if next item fits harmonically into post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0; // next item exactly fills this bin
        } else if next_item_size <= pr && next_item_size % 10 == 0 && pr % 10 == 0 {
            score -= 12.0; // compatible decimal classes
        }
        if next_item_size > pr && next_item_size > 0 && pr < 10 {
            score += 20.0; // dead space that even the next item can't use
        }
        // lookahead residual chain: pr - next_item_size class
        if next_item_size < pr {
            let pr2 = pr - next_item_size;
            if pr2 % 25 == 0 || pr2 == 0 {
                score -= 10.0;
            }
        }
    }

    // Last chance: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let base_penalty = 55.0 + 0.15 * open_bins_count as f64;
        // If current fit is bad (large post residual waste relative to item), allow opening
        let waste_ratio = post_residual as f64 / cap;
        score = base_penalty + 30.0 * waste_ratio;
        if fitting_bins_count == 0 {
            score = -100.0; // must open a new bin
        }
    }

    // Mild preference to consolidate into fewer bins early on
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins whose residual is near the mean (balanced packing)
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space avoidance: residuals too small to hold the smallest
    // possible item are pure waste. Penalize them heavily (non-linearly).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 8.0 * (10 - post_residual) as f64;
    }
    // Gaps too small for the next item are likely waste too (soft lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + 0.15 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits: perfect fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Fraction of the bin wasted by this placement; penalize quadratic waste.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 30.0 * waste_frac * waste_frac;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current fit is bad (large post_residual) or this is a last-chance situation
    // that would create dead space. Base new-bin score slightly above a good fit.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.5 * open_bins_count as f64;
        if item_size >= 90 {
            score -= 10.0; // huge items: a fresh bin is fine
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // lookahead may pair well with a fresh bin
        }
    }

    // Mild stream-progression adaptation: later in the stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect fits (zero waste).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead coupling: reward when next item fits the post-residual exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0; // chain fit: item then next item perfectly fills bin
        } else if post_residual >= next_item_size {
            // next item still fits: mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item does NOT fit: post_residual becomes a dead pocket.
            // Penalize more if the dead pocket is small-but-unusable (worst case).
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                let severity = 1.0 - dead / next_item_size as f64; // near-miss is worst
                score += 40.0 + 80.0 * severity;
            }
        }
    }

    // Relative-to-mean-residual term: prefer bins whose residual is below average
    // (i.e., already well-filled bins) to keep many high-residual bins available.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: empty bin is a fallback. Prefer it only when
    // no good fit exists; make it mildly attractive early, expensive late.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = bin_capacity as f64 + 80.0 + 120.0 * progress;
        if next_item_size > 0 && item_size as f64 >= 0.5 * bin_capacity as f64 {
            score -= 40.0; // big items justify fresh bins
        }
        // If no open bin fits at all, new bin must be competitive
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Slight preference for fewer open bins being consolidated when many are open.
    if open_bins_count > 4 {
        score -= (post_residual as f64 / bin_capacity as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let residual = bin_residual as f64;
    if residual > 0.0 {
        let fill = item_size as f64 / residual;
        score -= 60.0 * fill * fill; // quadratic tightness bonus
    }

    // Penalize large dead space relative to capacity.
    let cap = bin_capacity as f64;
    score += 0.6 * (post_residual as f64 / cap) * (post_residual as f64 / cap) * cap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            let nxt_fit = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - nxt_fit / cap);
        } else {
            // Next item won't fit here; penalize leaving awkward residual.
            score += 10.0 * (1.0 - nxt / cap);
        }
    }

    // New-bin candidate logic: only attractive when open bins have poor fit potential.
    if bin_residual == bin_capacity {
        // Opening new bin costs; make it expensive unless many bins are open with
        // scattered residuals or current fit is terrible.
        let poor_fits = if residual > 0.0 { 1.0 - (item_size as f64 / residual).min(1.0) } else { 1.0 };
        let scatter = (mean_residual - post_residual as f64).abs() / cap;
        let openness = (open_bins_count as f64).ln().max(0.5);
        let mut new_bin_score = 45.0 + 12.0 * openness;
        // Discount the new bin when item is large relative to mean residual (bad fits everywhere)
        let mean_fit = item_size as f64 / mean_residual.max(1.0);
        if mean_fit > 0.9 {
            new_bin_score -= 55.0;
        }
        new_bin_score -= 30.0 * scatter * poor_fits;
        // Time horizon: later in stream, less future to amortize a new bin.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += 20.0 * progress;
        score = new_bin_score;
    } else {
        // Slight bonus for placing into bins with residual below mean (consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    // Mild preference to keep few bins open early.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: penalize wasted residual, quadratically (dead space is doubly bad).
    let mut score = pr + 1.75 * (pr * pr) / cap;

    // Smooth interaction: tight fits matter more as the stream progresses.
    let tightness = 1.0 - pr / cap; // in (0,1]
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Reward bins whose residual closely matches the item (smooth kernel).
    let diff = (bin_residual as f64 - it) / cap;
    score -= 20.0 * (-40.0 * diff * diff).exp();

    // Lookahead coupling: if the next item fits the post-residual, reward heavily.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs() / cap;
        score -= 15.0 * (-30.0 * gap * gap).exp();
        // Penalize leaving residual that is awkwardly larger than next item.
        if pr > nx {
            score += 4.0 * (pr - nx) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral baseline, adjusted by how bad existing fits are.
    if bin_residual == bin_capacity {
        // Prefer a fresh bin only if this item would leave a large, useless residual
        // in existing bins; otherwise a fresh empty bin should lose.
        score = pr + 1.0 * pr * pr / cap + 30.0 - 6.0 * (pr / cap) * (pr / cap);
        // Late in the stream, closing out bins is better than opening new ones.
        score += 10.0 * progress;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 8.0 * (fitting_bins_count as f64).ln();
        }
    }

    // Mild pressure to consolidate into fewer bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post_class = post_residual / eighth;
    let next_class = if next_item_size > 0 { next_item_size / eighth } else { 0 };

    // Reward near-tight fits (post_residual in low harmonic classes)
    score -= 22.0 * (1.0 - pr / cap) * (1.0 - pr / cap);

    // Class match: if next item fits exactly into the post_residual class, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        if slack_after_next < eighth {
            score -= 30.0;
        } else if next_item_size > post_residual - quarter {
            score -= 12.0;
        } else {
            score += 4.0;
        }
    } else if next_item_size > 0 {
        // next item cannot reuse this bin's remainder -> penalize dead space
        score += 8.0 + 0.25 * pr;
    }

    // Integer-division thresholds on post_residual
    match post_class {
        0 => score -= 25.0,          // almost full: excellent
        1 => score -= 10.0,          // good
        2 => score -= 3.0,           // moderate
        3 => score += 6.0,           // large hole left
        _ => score += 14.0,          // nearly empty placement
    }

    // Last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Penalize new-bin candidate unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 35.0 - 6.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin good for upcoming large item
        }
    }

    // Spread pressure: prefer bins with residual far below mean (consolidate)
    score += 0.15 * (mean_residual - pr).abs().signum() * (mean_residual - pr);

    // Late-stream tightening
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=9)
    // are unusable; penalize them heavily so tight fits are preferred.
    if !is_new_bin && post_residual > 0 && post_residual < 10 {
        score += 25.0 + 2.0 * (10 - post_residual) as f64;
    }

    // Reward very tight fits (waste <= 5) even more strongly.
    if !is_new_bin && post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item can use the leftover space, reward;
    // if it cannot, penalize the creation of a stranded gap.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else if post_residual > 0 {
            score += 3.0;
        }
    }

    if is_new_bin {
        // Opening a new bin costs: pressure from already-open bins
        // (discourage bin proliferation) plus a base opening cost so that
        // a new bin only wins when existing fits are truly bad.
        score += 18.0 + 1.5 * open_bins_count as f64;
        // Mild progress-based relaxation: late in the stream, tolerate
        // new bins slightly more (avoid stranding items early).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * progress;
        // If the new bin's leftover is unusable dead space, penalize it too.
        if post_residual > 0 && post_residual < 10 {
            score += 20.0;
        }
    } else {
        // Last-chance bonus: if this is the only bin that fits, strongly
        // prefer placing here over opening a new bin.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Prefer bins whose residual is close to being exhausted
        // (consolidate waste into few bins).
        score += 0.05 * (mean_residual - bin_residual as f64).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack * 0.5;
        // Bonus if the next item fills the bin completely after this placement.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: penalize dead space proportionally.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Penalize wasted residual relative to mean residual of open bins.
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs()
        } else {
            post_residual as f64
        };
        score += 15.0 + poor_fit * 0.4 + (open_bins_count as f64 * 0.2);
        if fitting_bins_count == 1 {
            score += 40.0; // discourage abandoning the last fitting open bin
        }
    }

    // Slight preference to fill earlier-opened bins as the stream progresses.
    score -= (step_index as f64 / (total_items.max(1) as f64)) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items (unusable sliver).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chaining
        } else if next_item_size < post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Next item cannot follow here; slight penalty proportional to leftover size.
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: minimize waste absolutely.
        score -= 20.0 * fit_ratio;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Global fragmentation pressure: when mean residual across open bins is low,
    // conserve space in existing bins; when mean residual is high, prefer filling.
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if (mean_residual - item_size as f64).abs() < 5.0 {
        score -= 20.0; // near-exact global fit
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - prog);

    // New-bin candidate handling: an empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin; decreases late in the stream.
        score = bin_capacity as f64 - 15.0 * prog;
        // Opening a new bin is attractive if no existing bin fits well.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // If the item perfectly fills a fresh bin, new bin is great.
        if item_size == bin_capacity {
            score -= 100.0;
        }
        return score;
    }

    // Mild reward for using bins with larger residuals (clean up loose bins first).
    score -= 3.0 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted space, quadratically for small dead space
    let mut score = post * (1.0 + 0.9 * (1.0 - post / cap));

    // Reward tight fits (high fill ratio)
    score -= 22.0 * fit_ratio * fit_ratio;

    // Smooth non-linear coupling of waste with stream progress:
    // later in the stream, dead space hurts more
    let waste_weight = 1.0 + 1.6 * progress * progress;
    score *= waste_weight;

    // Last-chance bin: strong reward to use it, avoiding a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: bonus if post_residual can host the next item exactly-ish
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        if post >= next_item_size as f64 {
            score -= 14.0 * (1.0 - gap / cap);
        } else {
