            score += 5.0 * (1.0 - post / cap) * (next_item_size as f64 / cap);
        }
    }

    // New-bin candidate: prefer it only when open bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (1.0 + fitting_bins_count as f64) };
        score = cap + 10.0 * pressure - 8.0 * progress;
        // early in stream, opening bins is cheap
        score -= 20.0 * (1.0 - progress) * (1.0 - progress);
    }

    // Mild penalty for proliferating bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap; // 0..1 fraction of capacity left

    // Dead-space penalty: residuals that cannot plausibly host future items.
    // Quantize post_residual into classes of size 10 (harmonic bins).
    let class = post_residual / 10;
    let class_center = (class * 10 + 5) as f64;
    // Residuals in [1..9] are nearly dead; penalize strongly via non-linear coupling.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Reward small residuals generally (tight packing), scaled by class.
    score -= 40.0 / (1.0 + post_f);

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Bonus proportional to how snugly the next item fills the leftover.
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / cap);
            score -= 30.0 * snug;
        } else {
            // Next item won't fit here: penalize leaving mid-sized leftovers.
            score += 15.0 * frac;
        }
    }

    // Last-chance bin: strongly prefer using the final fitting bin over opening new.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only good if all existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap * 0.85;
        // Cheaper to open new bins early in the stream (more future items to fill it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        // More open bins -> opening yet another is more costly.
        score += 3.0 * open_bins_count as f64;
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    } else {
        // Prefer bins whose residual is far from mean residual (diversity of classes).
        let dev = (post_f - mean_residual).abs();
        score -= 5.0 * (dev / cap);
    }

    // Modulo-based harmonic penalty: residuals congruent to small values mod 25 are awkward.
    let m = post_residual % 25;
    if m > 0 && m < 8 {
        score += 8.0;
    } else if m >= 17 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be
    // useful (unusable gaps) but not zero. Perfect fits get a big reward.
    if post_residual == 0 {
        score -= 50.0; // perfect fit: excellent
    } else if post_residual < 10 {
        score += 30.0; // tiny dead gap, nearly unusable
    } else if post_residual <= 20 {
        score += 12.0; // small dead space
    } else if post_residual <= 40 {
        score -= 5.0; // still usable for small items
    }

    // Reward leaving room that can host the lookahead item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 25.0; // next item fits perfectly afterwards
        } else if slack <= 15 {
