        }
    }
    // Penalize if the next item cannot fit in the leftover.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 6.0;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    // Slight preference to keep residuals aligned with the mean (balance).
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    // New-bin candidate: only attractive when existing bins would leave bad gaps.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are open
        // and current fits are poor.
        score = 45.0 + (open_bins_count as f64) * 2.0 - pressure * 3.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin guarantees room for the next item.
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

