        if rel < 1.0 {
            score -= 10.0 * (1.0 - rel); // tighter than average: good
        } else {
            score += 5.0 * (rel - 1.0).min(2.0); // looser than average: mild penalty
        }
    }

    // ---- Last-chance bin ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Only this bin can take the item; avoid opening a new bin wastefully.
        score -= 60.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly:
