}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize very small post-residuals that become dead space (unusable slivers),
    // unless the residual is fully consumed (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect fit bonus
    }

    // Lookahead coupling: reward leaving a residual that can host the next item,
    // penalize residuals that are "almost but not quite" big enough for it.
    if next_item_size > 0 {
        if post_residual as u32 >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            if gap < 15.0 {
                score += 4.0 * (1.0 - gap / 15.0);
            }
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate logic: opening a fresh bin is only attractive when no open bin
    // fits well, or when the stream is early and we can afford spreading load.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let best_possible_waste = post_residual as f64; // = 100 - item_size for empty bin
        score = best_possible_waste + 15.0 * progress + 2.0 * open_bins_count as f64;
        // Discourage hoarding many open bins when mean residual is already large.
        if mean_residual > item_size as f64 + 10.0 {
            score += 10.0;
        }
        // But encourage a new bin early in the stream (cheap future flexibility).
        if progress < 0.25 {
            score -= 8.0;
        }
    }

    // Mild global pressure: prefer bins whose residual is below the mean residual
    // (use up the emptier bins first, keep roomy bins for future large items).
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 1.5;
    }

    // Late-stream consolidation: near the end, pack tighter into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: penalize wasted residual, with non-linear (quadratic) waste growth
    let mut score = r + cap * rn * rn * (1.0 + t);

    // Smooth coupling: residual quality vs. stream progress
    score += 8.0 * t * rn * rn * cap;

    // Perfect fit bonus (non-linear in item size)
    let perfect = 1.0 - (r - item_size as f64).abs() / cap;
    score -= 15.0 * perfect * perfect * perfect;

    // Lookahead coupling: reward leaving space compatible with next item
    if next_item_size > 0 {
        let gap = (r - next_item_size as f64).abs();
        score += 0.05 * gap * (1.0 - t);
        if next_item_size as f64 <= r {
            score -= 6.0 * (1.0 - rn);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly early, allow late when open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0));
        score += 10.0 - 6.0 * t - 0.5 * crowd.min(10.0);
    }

    // Slight preference for fuller bins relative to mean residual
    score -= 0.03 * (mean_residual - r);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Reward small post_residual classes (tight fits).
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= eighth {
        score -= 35.0; // near-perfect fill
    } else if post_residual <= quarter {
        score -= 12.0; // usable leftover
    } else if post_residual <= cap / 2.0 {
        score += 6.0;  // medium dead space
    } else {
        score += 18.0; // large dead space
    }

    // Integer-division thresholds on post_residual: which item classes could still fit?
    let fits_next = next_item_size > 0 && next_item_size <= post_residual;
    if fits_next {
        // Harmonic coupling: exact modulo match means next item fills bin perfectly.
        if next_item_size == post_residual {
            score -= 45.0;
        } else {
            // reward if post_residual is in a "friendly" class for the lookahead
            let combo = post_residual + next_item_size;
            if combo == bin_capacity {
                score -= 40.0;
            } else {
                score -= 8.0 + (post_residual - next_item_size) as f64 * 0.05;
            }
        }
    } else if next_item_size > 0 {
        // Lookahead cannot use leftover: penalize proportionally to waste.
        score += 10.0 + (next_item_size as f64 - post_f).min(50.0) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins are badly fragmented
    // (high mean residual spread) or nothing fits well.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_f).abs();
        let pressure = open_bins_count as f64 / (step_index as f64 / total_items.max(1) as f64).max(0.1);
        // Prefer new bin when mean residual is small (bins nearly full) or item is large.
        score = 20.0 + item_size as f64 * 0.1 - fragmentation * 0.15 - pressure.min(20.0) * 0.3;
        if item_size > bin_capacity * 3 / 4 {
            score -= 10.0; // big items like fresh bins
        }
    } else {
        // Mild preference to spread load across open bins when many are open.
        score += open_bins_count as f64 * 0.05;
    }

    // Progress-based drift: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - post_f) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (too small for the smallest plausible item) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Near-perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Favor bins whose residual is close to the item (tight packing),
    // scaled by how "full" the bin already is.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 25.0 * tightness;

    // Pressure from open bin count: with many open bins, prefer filling
    // existing bins rather than spreading out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 1.5 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual < 10 && post_residual > 0 {
            score += 25.0; // undo reward if it creates dead space anyway
        }
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement (chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 12.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 8.0; // next item can't use this bin's remainder
        }
    }

    // New-bin candidate (empty bin): make it attractive only when current
    // bins would leave bad dead space or there are no open bins.
    if bin_residual == bin_capacity {
        score = 45.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score = -100.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            // opening new bin only if the sole fit creates dead space
            if post_residual >= 10 || post_residual == 0 {
                score = 80.0;
            } else {
                score = 5.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio;

    // 2-step lookahead: reward if next item fits perfectly in post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1e-9 {
            score -= 60.0; // perfect 2-step match
        } else if post_residual >= next_item_size {
            let chain_fit = nxt / post_residual as f64;
            score -= 25.0 * chain_fit;
        } else {
            // next item won't fit: penalize wasted residual relative to next item size
            score += 0.3 * (post_residual as f64 - nxt);
        }
    }

    // Penalize deviation of resulting residual from mean residual (keeps bins homogeneous)
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large relative to capacity
    if bin_residual == bin_capacity {
        let load_frac = item_size as f64 / bin_capacity as f64;
        score += 55.0 - 40.0 * load_frac;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 10.0; // pair could go together, keep flexibility cost
        }
    }

    // Late-stream: prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact fit jackpot
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize dead space that cannot serve a typical future item
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else if next_item_size > bin_residual {
            // next item won't fit here anyway; residual size matters less
            score += 5.0;
        } else {
            // blocking the next item: penalize proportionally to waste
            score += 15.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing fits are poor
    if bin_residual == bin_capacity {
        // baseline reluctance to open new bins, decaying as stream progresses
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 55.0 + 45.0 * progress;
        // open new bins more readily when many bins are open with low mean residual
        if mean_residual < 20.0 && open_bins_count > 2 {
            score -= 20.0;
        }
        // never open a new bin if an open bin would be an exact fit
        if post_residual == 0 {
            score += 1e6;
        }
        // opening a new bin leaves full capacity for large future items
        if item_size > 60 {
            score -= 10.0;
        }
    } else {
        // mild penalty for spreading across many bins when residuals are large
        if mean_residual > 50.0 && post_residual > 40 {
            score += 10.0;
        }
    }

    // Encourage consolidating into bins with low residual early (fill nearly-full bins first)
    let residual_gap = (bin_residual as f64) - mean_residual;
    score += 0.15 * residual_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr as f64;
    score += 20.0 * norm_pr * norm_pr;

    // Smooth coupling: post_residual vs stream progress
    // Early on, keep bins flexible (penalize low residual less); late, pack tightly
    let flex = (1.0 - progress) * (1.0 - progress);
    score -= 15.0 * flex * norm_pr;
    score += 10.0 * progress * norm_pr * norm_pr * norm_pr;

    // Reward near-perfect fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * progress * tightness * tightness;

    // Lookahead: if next item fits into post_residual, reward this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack) * (0.5 + progress);
        } else {
            let gap = (nxt - pr) / cap;
            score += 6.0 * gap * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Penalize scattering residual across many open bins
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // Mean residual coupling: prefer bins deviating below mean residual (tighter bins)
    let dev = (pr as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev - 3.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "usable" classes (multiples of small denominators) are more valuable.
    let pr = post_residual;
    if pr > 0 {
        // Class penalty: residuals not divisible by 5/10 create dead space
        // for typical item sizes.
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Small unusable residuals are dead space -> heavy penalty.
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 10.0;
        }
        // Perfect fit reward.
        if pr == 0 {
            score -= 40.0;
        }
    }

    // Coupling with lookahead: reward residuals that can host next_item_size.
    if next_item_size > 0 && pr >= next_item_size {
        score -= 8.0;
        // Harmonic match: residual exactly a multiple of next item size class.
        if pr % next_item_size.max(1) == 0 {
            score -= 4.0;
        }
    } else if next_item_size > 0 && pr > 0 && pr < next_item_size {
        // Residual too small for lookahead item: partial dead space penalty.
        score += (next_item_size - pr) as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin should only win when no
    // open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        let mut new_bin_score = bin_capacity as f64 * 0.35;
        // If few fitting bins exist, opening new is more acceptable.
        if fitting_bins_count <= 1 {
            new_bin_score -= 20.0;
        } else {
            new_bin_score += (fitting_bins_count as f64) * 3.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score += progress * 10.0;
        // Large items waste less of a new bin.
        new_bin_score -= item_size as f64 * 0.2;
        return new_bin_score;
    }

    // Prefer tighter fits generally.
    score -= (bin_residual - item_size) as f64 * 0.05;

    // Bin congestion: if many bins open, favor filling existing ones.
    score += open_bins_count as f64 * 0.3;

    // Deviation from mean residual: prefer bins near/below mean residual
    // (close-to-full bins first).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Strict dead-space avoidance: unusable small gaps are the enemy.
    let dead = post_residual as f64;
    let dead_threshold = 9.0; // smallest plausible future item
    if dead > 0.0 && dead < dead_threshold {
        score += 500.0 * (dead_threshold - dead) / dead_threshold;
    }

    // Base tightness preference: lower post_residual is better, mildly.
    score += dead * 0.5;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward fills that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0;
        } else if post_residual > 0 {
            // Gap too small for next item: penalize proportionally to wasted gap.
            score += 30.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 2.0;

    // Prefer bins with residual below mean (consolidate into fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.8;

    // New-bin candidate: neutral-ish baseline; only chosen if no open bin scores better.
    if bin_residual == bin_capacity {
        score = 250.0 + pressure * 3.0;
        // Late in the stream, opening a new bin is cheap since bins rarely fill again.
        score -= 200.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fits post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 60.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space relative to next item
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: penalize bins far below mean residual (tight bins)
    score += 0.15 * (mean_residual - post_residual as f64).max(0.0);
    score -= 0.05 * (post_residual as f64 - mean_residual).max(0.0);

    // Last chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: mildly penalize opening a new bin unless fit is poor
    if bin_residual == bin_capacity {
        score += 30.0 - 0.4 * item_size as f64;
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 20.0;
        }
    }

    // Late stream: prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that no future item (min size 1..10) can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // nearly unusable sliver
    }
    if post_residual >= 10 && post_residual < 20 {
        score -= 8.0; // still useful for small items
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 6.0 + 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
        // Perfect chaining: next item exactly fills the bin.
        if post_residual == next_item_size {
