        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current item leaves a very clean residual or no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early on, opening bins is cheap; later, prefer squeezing into open bins.
        let open_penalty = 20.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        score += open_penalty;
        // But if the item is large and leaves little residual, a fresh bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 35.0;
        }
        // If mean residual across open bins is small (all bins are full-ish),
        // a new bin is the natural choice.
        if mean_residual < item_size as f64 {
            score -= 50.0;
        }
    } else {
        // Placing into an existing bin reduces open-bin pressure slightly.
        score -= 3.0 * (1.0 - (bin_residual as f64 / bin_capacity as f64));
    }

    // Mild preference for filling fuller bins (best-fit flavor) among open bins.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: late in the stream, avoid opening bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, mildly non-linear (wasted space matters super-linearly)
    let mut score = pr + 40.0 * pr_norm * pr_norm;

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate large residuals; late, penalize them more.
    let coupling = 1.0 + 2.0 * progress * progress + 1.5 * progress;
    score *= coupling;

    // Reward tight fits (small post_residual relative to item), smoothly
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * tightness * (1.0 - progress);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Penalize scattering across many open bins
    score += 0.4 * open_bins_count as f64 * (0.5 + progress);

    // Lookahead: reward leaving space usable by the next item
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as f64;
        score -= 12.0 * fits_next * (1.0 - progress * 0.5);
        // penalize leaving almost-but-not-quite space for next item
        let gap = (next_item_size as f64 - pr).abs();
        score += 0.15 * gap * (pr < next_item_size as f64) as f64;
    }

    // New-bin candidate: baseline slightly above good fits, drops late in stream
    if bin_residual == bin_capacity {
        score = cap * (0.85 + 0.3 * progress) + 0.3 * open_bins_count as f64;
    }

    // Mean residual alignment: prefer bins near the mean residual (balanced filling)
    score += 0.1 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "useful" sizes
    // (small residuals are good; residuals that are multiples of common item sizes are good).
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else if pr <= 10 {
        score -= 15.0;
    } else if pr <= 20 {
        score -= 5.0;
    } else if pr <= 35 {
        score += 3.0;
    }

    // Harmonic bonus: post_residual divisible by common size classes (10, 20, 25, 50)
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 5.0;
    }

    // Lookahead: strongly reward exact fit for the next item
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if pr >= next_item_size && pr - next_item_size <= 10 {
            score -= 12.0;
        } else if pr < next_item_size && pr > 0 {
            // residual too small for next item: dead space penalty scaled by dead amount
            score += (next_item_size - pr) as f64 * 0.6;
        }
    }

    // Last chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when many open bins exist with room
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64) * 0.15 + mean_residual * 0.05;
        score += 45.0 + pressure - progress * 10.0;
        // new bin is fine if item is huge and mean residual is small
        if item_size >= 70 && mean_residual < 20.0 {
            score -= 35.0;
        }
    }

    // Mild preference for tighter bins overall (waste-aware)
    score += (bin_residual as f64 - mean_residual) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10) are nearly useless -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Perfect or near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Reward fitting into a tight bin (waste little of the residual).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another one.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above a good fit, scaled by pressure.
        score = bin_capacity as f64 * 0.55 + pressure * 3.0;
        // If the next item could pair with the residual created here, soften slightly.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    } else {
        // Slight penalty for leaving a gap exactly matching the next item's complement poorly.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
        // Prefer bins whose residual deviates from the mean (consolidate slack).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to zero is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Aggressive 2-step lookahead: strongly reward if next item fits exactly
    // into the post residual; penalize if it nearly fits (dead-space trap).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chain: next item seals this bin completely.
            score -= 60.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // Prefer leaving a useful residual for the next item.
            let chain_quality = 1.0 - (next_post as f64) / (bin_capacity as f64);
            score -= 15.0 * chain_quality;
            // Penalize leaving large awkward gaps the next item won't fill.
            if next_post > 40 {
                score += 0.15 * (next_post as f64);
            }
        } else {
            // Next item cannot follow into this bin: mild penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.05 * gap;
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving less than average keeps the bin pool balanced and compact.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when no open bin offers a good fit (few fitting bins, large item).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 10.0;
        } else {
            // Discourage wasteful new bins when decent fits exist.
            let waste = (bin_capacity as f64) - (item_size as f64);
            score += 0.4 * waste + 15.0 * (fitting_bins_count as f64);
        }
    }

    // Early in the stream, allow more bins for flexibility; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 2.0;

    // Slight penalty for accumulating many open bins with large residuals.
    score += 0.02 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post_residual.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * (1.0 - tight) * (1.0 - tight);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 6.0 * (next_item_size as f64 / 100.0);
    }

    // Perfect-fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor
    // and many open bins exist (fragmentation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) / (bin_capacity as f64); // = 1.0 for empty item? post = C - item
        let fit_penalty = (item_size as f64 / bin_capacity as f64) * 60.0;
        score += 45.0 + 30.0 * (1.0 - progress) - fit_penalty;
        if fitting_bins_count <= 1 {
            score -= 70.0; // no real alternative; new bin is fine
        }
        if mean_residual < 15.0 {
            score -= 20.0; // existing bins are nearly full anyway
        }
        let _ = poor_fit;
    }

    // Mild preference for fuller bins among alternatives.
    score -= 10.0 * (bin_residual as f64 / bin_capacity as f64);

    // Spread control: penalize bins far from mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial base: penalize residual, with curvature growing over the stream.
    let mut score = norm_pr + 0.35 * norm_pr * norm_pr + 0.15 * progress * norm_pr * norm_pr * norm_pr;

    // Reward tight fits (small post_residual) more strongly as stream advances.
    score -= 0.5 * (1.0 - norm_pr) * (1.0 - progress);

    // Lookahead coupling: smooth interaction between post_residual and next item size.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let diff = norm_pr - nx;
        // Perfect follow-up fit (post_residual == next size) gets strong reward.
        score -= 0.6 * (-diff * diff / 0.02).exp() * (1.0 - progress);
        // Penalize leaving residual just below the next item (wasted sliver).
        score += 0.3 * (diff / (nx + 0.01)) * (diff > 0.0) as i32 as f64 * 0.1;
    }

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 2.0 * (1.0 + progress);
    }

    // Mild penalty for scattering across many bins when mean residual is high.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap - norm_pr).abs();

    // New-bin candidate: neutral-ish score so it wins only when fits are poor.
    if bin_residual == bin_capacity {
        score += 0.4 + 0.6 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" class (small or near-half capacity) are favored.
    let pr = post_residual as u32;
    let class = match pr {
        0 => -12.0,                                  // perfect fit
        x if x <= 10 => -6.0,                        // tiny dead space
        x if x <= 20 => -2.0,
        x if (x as i64 - 50).abs() as u32 <= 5 => -3.0, // near half-capacity, reusable
        x if x % 20 == 0 => -1.5,                    // harmonic residue class
        x if x % 10 == 0 => -1.0,
        _ => 0.0,
    };
    score += class;

    // Tightness bonus: reward filling most of the bin (fraction of capacity used).
    let fill = item_size as f64 / cap;
    score -= 8.0 * fill * fill;

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size < pr {
            // next item fits: mild reward scaled by how well it uses leftover
            score -= 4.0 * (next_item_size as f64 / pr.max(1) as f64);
        } else {
            // next item cannot use leftover: penalize large stranded residuals
            score += 0.05 * pr as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals
    // are all badly fragmented (mean residual small relative to item).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        score += 10.0 - 25.0 * fragmentation;
        // late in the stream, prefer consolidation into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress;
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.02 * open_bins_count as f64;

    // Penalize residuals that no plausible item (1..100) can use well:
    // stranded space just above common small-item sizes.
    if pr > 20 && pr < 30 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // possible item (1..=100 interface, use a conservative small-gap threshold)
    // are nearly worthless -> heavy penalty.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }

    // Reward tight fits (post_residual near zero relative to bin_residual).
    let fit_ratio = post_residual as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * (1.0 - fit_ratio);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is excellent.
    score += 2.0 * open_bins_count as f64 * fit_ratio;

    // Lookahead: if next item fits in post_residual, bonus for this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space that blocks the lookahead item: mild penalty.
        score += 5.0;
    }

    // Mean residual coupling: bins far below mean residual are "valuable" to fill.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate (empty bin): make it attractive only when the current
    // bin's post fit is bad (large leftover) or no real bin is a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0 + 1.5 * open_bins_count as f64;
        // If the item perfectly fills a fresh bin, allow it.
        if item_size == bin_capacity {
            score -= 200.0;
        }
        // If this bin would leave a large unusable gap anyway, prefer new bin.
        if post_residual < dead_threshold {
            score -= 50.0;
        }
    }

    // Progression: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward exact/near-exact match of next item into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        if slack == 0.0 {
            score -= 60.0; // perfect 2-step pairing
        }
    } else if next_item_size > post_residual {
        // Next item cannot follow here; penalize small dead space that blocks it.
        let dead = post_residual as f64;
        if dead < next_item_size as f64 {
            score += 0.5 * (next_item_size as f64 - dead);
        }
    }

    // Tightness reward: small post_residual relative to capacity is good.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * tightness * tightness;

    // Compare against mean residual: prefer bins that get tighter than average.
    score += 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count > 0 && (post_residual as f64) >= 0.35 * bin_capacity as f64 {
            score += 25.0; // keep using open bins when a decent fit exists
        }
    }

    // Late-stream consolidation: fewer open bins preferred near the end.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * 3.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements that leave small post_residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    // (residual below ~10 is wasted; residual just above a common size is valuable).
    if post_residual > 0 {
        let r = post_residual as f64;
        if r < 10.0 {
            score += 12.0 * (10.0 - r);
        } else {
            // reward residuals that can host a future item (lookahead or typical sizes)
            let usable = if next_item_size > 0 && r >= next_item_size as f64 {
                1.0
            } else {
                0.4
            };
            score -= 5.0 * usable * (r / 100.0);
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0; // next item won't fit here; this bin may become dead
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; penalize it
    // unless existing bins are nearly full / poor fits.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        // Penalty grows with how "healthy" the open bins are; shrinks late in stream.
        score += 25.0 * avg_fill + 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: must open new bin
        }
    } else {
        // Favor bins whose residual deviates from mean in a "complementary" way:
        // placing into bins with residual close to item_size balances global state.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 1.5 * dev / bin_capacity as f64;
    }

    // Mild preference for fewer open bins early (keeps packing compact),
    // relaxes as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * 0.3 * (1.0 - progress);

    // Waste-pressure: if mean residual is high, encourage using bins aggressively.
    score -= 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear coupling: normalized post residual polynomial in progress
    let x = pr / cap;
    let t = progress;
    let coupling = x * x * (1.0 - t) + x * t * t;
    score += 30.0 * coupling;

    // Reward tight fits, stronger later in the stream
    score -= (1.0 - x) * (1.0 + t) * 10.0;

    // Penalize waste relative to mean residual of open bins
    score += 0.5 * (pr as f64 - mean_residual).abs() * (1.0 - t);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + t);
    }

    // Lookahead: favor bins whose post residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // New-bin candidate: penalize mildly so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space is bad if unusable
    let dead = post_residual as f64 / bin_capacity as f64;
    score += dead * dead * 40.0;

    // Penalize post_residual in "awkward" classes (small unusable slivers)
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 25.0; // sliver
    }
    // Modulo-10 class coupling: residual divisible by 10 is more reusable
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            score -= 15.0;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin bonus: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Encourage tight packing when many bins are open
    score += (open_bins_count as f64) * 0.5;

    // New-bin candidate handling: opening a new bin is expensive unless
    // current residuals are all poor fits
    if bin_residual == bin_capacity {
        // fresh bin baseline: slight penalty so it's chosen only when better
        score += 5.0;
        if mean_residual < item_size as f64 {
            // no open bin can usefully absorb -> new bin is good
            score -= 80.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - 10 {
            score -= 30.0; // large next item benefits from fresh bin
        }
    }

    // Progress-aware tightening: later in stream, be more conservative
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit: maximal reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual >= 10 {
        // Larger usable leftovers are mildly attractive.
        score -= 0.15 * post_residual as f64;
    }

    // Reward bins whose residual can still host the lookahead item after placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 5.0; // dead space relative to lookahead
        }
    }

    // Last-chance pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and progress.
        score += 30.0 + 2.0 * open_bins_count as f64 + 20.0 * progress;
        // But allow new bin if all existing fits would create dead space.
        if post_residual >= item_size {
            score -= 10.0;
        }
    } else {
        score -= 1.0 * open_bins_count.min(10) as f64;
    }

    // Prefer bins below mean residual (tighter bins first).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 400.0;
        } else {
            score -= 150.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space relative to next item: penalize small leftover that next item cannot use
        score += 60.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current options are bad
    if bin_residual == bin_capacity {
        score += 180.0;
        // but if next item is large and no good fit exists, new bin is attractive
        if next_item_size > 0 && next_item_size > post_residual.max(1) {
            score -= 100.0;
        }
    }

    // Prefer bins tighter than the mean residual (good packing)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Early in stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * (1.0 - progress) * (open_bins_count as f64 / (total_items.max(1) as f64)).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving dead space that no plausible future item can use.
    // Dead space: post_residual smaller than the smallest plausible item (1..100 unknown,
    // assume >= 10-ish risk) — but sizes 1..100, so only fully dead if very small.
    if post_residual > 0 && post_residual < 5 {
        score += 8.0; // nearly-dead sliver
    }

    // Lookahead coupling: if next item fits the post-residual exactly, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item won't fit here after this placement; mild penalty grows with waste
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is expensive; penalize it,
    // but relax the penalty late in the stream or when many bins are already open
    // and mean residual is low (existing bins are fragmented).
    if is_new_bin {
        let mut open_penalty = 18.0;
        // If current bin cannot even be judged among fitting bins (fitting_bins_count==0
        // implies no open bin fits), opening is justified.
        if fitting_bins_count == 0 {
            open_penalty -= 18.0;
        } else if fitting_bins_count == 1 {
            open_penalty += 20.0; // keep using the lone fitting bin
        }
        // Fragmented state: mean residual low relative to item => open anyway.
        if mean_residual < item_size as f64 {
            open_penalty -= 8.0;
        }
        // Late stream: consolidation matters more, discourage new bins.
        open_penalty += 10.0 * progress;
        // Many open bins with low mean residual => fragmentation; allow opening.
        if open_bins_count > 4 && mean_residual < 0.25 * bin_capacity as f64 {
            open_penalty -= 6.0;
        }
        score += open_penalty;
    }

    // Mild preference for bins with residual close to mean (balanced packing).
    score += 0.03 * (bin_residual as f64 - mean_residual).abs();

    // Prefer using fuller bins overall.
    score += 0.05 * bin_residual as f64 * 0.01 * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_pr = pr / cap;

    // Base: penalize leftover space, but with non-linear (quadratic) cost
    let mut score = norm_pr + 0.8 * norm_pr * norm_pr;

    // Smooth stream-progress coupling: later in the stream, dead space matters more
    let progress_coupling = 1.0 + 0.9 * t * t;
    score *= progress_coupling;

    // Reward tight fits: cubic decay of penalty as post_residual -> 0
    score -= 0.6 * (1.0 - norm_pr).powi(3);

    // Penalize bins far from mean residual (fragmentation pressure), smoothly
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.25 * dev * dev;

    // Last-chance bin: strong smooth reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 1.5 + 0.5 * t;
    }

    // Lookahead coupling: if next item fits well in post-residual, reward this placement
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let next_fit = 1.0 - (pr - nx) / cap;
            score -= 0.5 * next_fit * next_fit;
        } else {
            // next item won't fit here; mildly penalize leaving large unusable gaps
            score += 0.3 * norm_pr;
        }
    }

    // Mild penalty when many bins are open (encourage consolidation early)
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic class of post_residual: classify dead space by capacity fraction.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (post_residual / 25) as f64; // integer division: 0..4 harmonic class
    let mod10 = (post_residual % 10) as f64;

    // Reward large post_residual classes (more usable space), i.e. subtract for classes 3-4.
    score -= 8.0 * quarter;

    // Penalize awkward small-but-nonzero residuals (dead space): class 0 with pr > 0.
    if post_residual > 0 && quarter == 0.0 {
        score += 6.0 + mod10 * 0.5;
    }

    // Perfect fit: zero residual is excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item slots exactly or leaves good class.
            let nxt_mod = (next_item_size as f64) * 0.05;
            score -= 10.0 - nxt_mod;
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0; // exact divisor: harmonic tiling
            }
        } else {
            // Next item won't fit here: residual risks becoming dead space.
            score += 4.0 + (next_item_size as f64 - pr).min(30.0) * 0.2;
        }
    } else {
        // Last item: prefer closing bins tightly.
        score -= 5.0;
    }

    // Last-chance bonus: only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 * 0.4 + mean_residual * 0.05;
        let poor_fit = if post_residual as f64 > cap - item_size as f64 { 0.0 } else { 0.0 };
        let _ = poor_fit;
        // New bin starts with residual == capacity, so quarter == 4 gives base reward.
        // Penalize it unless few bins fit the item or mean residual is low.
        score += 14.0 - crowded - if fitting_bins_count <= 1 { 20.0 } else { 0.0 }
                 - (cap - mean_residual).max(0.0) * 0.1 - progress * 3.0;
    }

    // Mild preference for filling fuller bins (low mean residual pressure).
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // Gaps below the minimum item size (1) are impossible, but very small gaps
    // relative to typical item sizes are wasteful. Penalize gaps < 20 heavily.
    if post_residual < 20 {
        score += 60.0;
    } else if post_residual < 35 {
        score += 25.0;
    } else if post_residual < 50 {
        score += 8.0;
    }

    // Perfect fit reward: zero post residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Exact match with lookahead item: reserve room for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size as f64 {
            score -= 30.0;
        } else if (post_residual as f64) < next_item_size as f64 && post_residual > 0 {
            // post residual too small for next item: mild penalty unless tiny gap
            score += 6.0;
        } else if (post_residual as f64) >= next_item_size as f64
            && (post_residual as f64 - next_item_size as f64) < 20.0
        {
            // placing next item here would leave a small dead gap again
            score += 10.0;
        }
    }

    // Open bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New bin candidate: penalize opening a new bin unless current bin is bad.
    if bin_residual == bin_capacity {
        score += 35.0 + open_bins_count as f64 * 0.5;
        // but if all open bins would leave tiny dead gaps, new bin is attractive
        if fitting_bins_count > 0 && post_residual == bin_capacity as f64 {
            // neutralize: allow new bin when needed
        }
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Progression: early in stream, be slightly more willing to open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins where the next item also fits snugly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_post = post_residual - next_item_size;
            // Reward tight two-item packing
            let tightness = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - tightness / bin_capacity as f64);
            if next_post == 0 {
                score -= 500.0;
            }
        } else {
            // Next item cannot follow here; penalize proportionally to leftover dead space
            score += 50.0 * (1.0 - (next_item_size as f64 - post_residual as f64) / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Relative-to-mean residual coupling: prefer bins with residual below mean
    // (compact bins), unless it's the empty new-bin candidate.
    if bin_residual != bin_capacity {
        score += 0.5 * (bin_residual as f64 - mean_residual);
    } else {
        // New bin candidate: only attractive when current fit is bad / many bins open
        score += 20.0 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0;
        }
    }

    // Late in stream: be more conservative, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 30.0;

    // Penalize dead space: post_residual too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits exactly in post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 10.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: penalize opening a new bin, but less when
    // item is large and existing residuals are poor / fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mut new_penalty = 45.0;
        // If item is huge, few alternatives, or mean residual is small, relax penalty.
        if item_size >= 70 {
            new_penalty -= 20.0;
        }
        if mean_residual < item_size as f64 {
            new_penalty -= 15.0;
        }
        if fitting_bins_count == 0 {
            new_penalty -= 30.0;
        }
        // Early in stream, opening bins is cheaper (more future items to fill).
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_penalty *= 1.0 + progress * 0.5;
        score += new_penalty;
    }

    // Slight preference for bins with residual close to item (best-fit flavor)
    score += (bin_residual as f64 - item_size as f64).abs() * 0.2;

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins above mean residual (keeps a balanced spread of gaps).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let base = post * (1.0 + 0.8 * norm_post * norm_post);
    let drift = post * (0.35 * progress * progress + 0.15 * progress);

    let mut score = base + drift;

    // Reward tight fits via smooth cubic term in (1 - norm_post).
    let tightness = (1.0 - norm_post).clamp(0.0, 1.0);
    score -= 12.0 * tightness * tightness * tightness;

    // Lookahead coupling: smooth quadratic interaction between post_residual
    // and next item size; reward if next item fits, penalize otherwise.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = post - nx;
        let fit_next = (gap / cap).clamp(-1.0, 1.0);
        score -= 10.0 * fit_next * fit_next * fit_next.abs();
        score += 0.25 * gap.abs();
    }

    // Last-chance bonus: smooth ramp when this bin is the only fitting bin.
    if fitting_bins_count <= 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Penalize opening a new bin when decent open bins exist (smooth sigmoidal gate).
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        let openness = 1.0 / (1.0 + (-0.35 * open_bins_count as f64).exp());
        let waste = (cap - item_size as f64) / cap;
        score += 30.0 * openness * (0.5 + waste) * (1.0 - progress * 0.3);
    }

    // Mild dispersion penalty relative to mean residual (smooth quadratic).
    let dev = post - mean_residual;
    score += 0.02 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // classes (multiples of common small item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let class_bonus = if pr % 10 == 0 {
            -6.0
        } else if pr % 5 == 0 {
            -3.0
        } else if pr >= 10 && pr % 2 == 0 {
            -1.5
        } else {
            2.0 // odd, tiny residual: dead space
        };
        score += class_bonus;

        // Integer-division thresholds: residual big enough for another
        // standard-size item is valuable.
        if pr / 10 >= 3 {
            score -= 2.0;
        } else if pr / 10 == 0 {
            score += 4.0; // residual < 10 is nearly unusable
        }
    } else {
        score -= 10.0; // perfect fill
    }

    // Lookahead coupling: harmonic class match between post_residual and next item.
    if next_item_size > 0 && pr >= next_item_size {
        let fits_next = (pr - next_item_size) % 10 == 0;
        if fits_next {
            score -= 4.0;
        } else {
            score -= 1.0;
        }
    } else if next_item_size > 0 && pr < next_item_size && pr > 0 {
        score += 3.0; // next item can't use this residual
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        if crowding < 0.15 || open_bins_count == 0 {
            score -= 5.0;
        } else {
            score += 6.0 + crowding * 4.0;
        }
    } else {
        // Prefer fuller bins (small residual) among open bins.
        let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= fullness * 3.0;
    }

    // Late in the stream, tighten packing to avoid leftover fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits strongly.
    score -= 15.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space blocking the next item.
        score += 6.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: penalize using bins when many are open,
    // unless the fit is very tight (encourage consolidation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 {
        score += (open_bins_count as f64) * 0.8 * (1.0 - item_size as f64 / bin_residual.max(1) as f64);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter than average).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate handling: make empty bin moderately attractive only
    // when item is large and would leave big dead space elsewhere, or when
    // few bins are open early in the stream.
    if bin_residual == bin_capacity {
        let waste_if_forced = (bin_capacity - item_size) as f64;
        if waste_if_forced > 60.0 || (fitting_bins_count == 0 && open_bins_count == 0) {
            score -= 20.0 + 0.2 * waste_if_forced;
        } else {
            score += 10.0 + 0.1 * open_bins_count as f64 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: exact 2-step lookahead match — if the next item fits the post residual,
    // reward this bin strongly (chain two items into one bin).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0 + next_item_size as f64 * 0.5;
    }

    // Penalize large dead space relative to mean residual across open bins.
    let mean_r = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    if (post_residual as f64) > mean_r {
        score += (post_residual as f64 - mean_r) * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item is large
    // and would leave a useful residual for the next item.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && (bin_capacity as u32 - item_size) >= next_item_size && item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        // Late in the stream, opening fresh bins is less attractive (fewer chances to fill).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Prefer tight fits: small post_residual is good (already the base), but add
    // a mild non-linear penalty for residuals that are too small to ever be useful.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Mild congestion penalty: many open bins means we should consolidate.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Core: penalize dead space nonlinearly (small post-residuals are valuable).
    let pr = post_residual as f64;
    score += 0.35 * (pr / cap) * (1.0 - pr / cap) * cap;

    // Lookahead: reward if the next item fits exactly in the post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - pr).abs() < 1.0 {
            score -= 25.0;
        } else if nxt <= pr {
            // next item fits: mild reward proportional to leftover after both
            score -= 12.0 * (1.0 - ((pr - nxt) / cap).abs());
        } else {
            // next item won't fit here: penalize tight fits slightly
            score += 6.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (score new-bin candidate better); later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty that shrinks with progress.
        score += 8.0 + 25.0 * (1.0 - progress);
        // Discourage opening a new bin when many open bins already exist late.
        score += (open_bins_count as f64) * (1.0 - progress) * 1.5;
    } else {
        // Prefer bins with residuals below the mean (tighter bins first).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 10.0 * dev;
    }

    // Perfect-fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Base: penalize wasted post-residual, with non-linear (quadratic) coupling
    let mut score = pr + 30.0 * prn * prn;

    // Smooth interaction of post-residual with stream progress
    score += 40.0 * prn * progress * (1.0 - progress) * 4.0;

    // Reward tight fits (small post_residual) more as stream progresses
    let tightness = 1.0 - prn;
    score -= 20.0 * tightness * tightness * (0.5 + progress);

    // Penalty if post-residual is too small to be useful (dead space), smooth ramp
    let deadness = (1.0 - pr / (0.15 * cap)).max(0.0).min(1.0);
    score += 15.0 * deadness * deadness;

    // Lookahead: reward bins whose post-residual fits the next item (smooth)
    if next_item_size > 0 {
        let fits_next = (pr - next_item_size as f64).max(0.0);
        let next_fit_quality = 1.0 - (fits_next / cap);
        score -= 10.0 * next_fit_quality * (pr >= next_item_size as f64) as i32 as f64;
    }

    // Last-chance bin: strong smooth reward to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * (1.0 - progress);
    }

    // Mild penalty when many bins are open relative to progress (encourage consolidation)
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins near the mean (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality via modulo arithmetic
    let pr = post_residual;
    if pr > 0 {
        // Residuals that are multiples of small "harmonic" sizes are more reusable.
        let harmonic_bonus = if pr % 10 == 0 { 6.0 }
            else if pr % 5 == 0 { 3.0 }
            else if pr % 4 == 0 { 2.0 }
            else if pr % 3 == 0 { 1.0 }
            else { 0.0 };
        score -= harmonic_bonus;

        // Very small dead space (< 10) is nearly useless: penalize.
        if pr < 10 { score += 8.0; }
        // Perfect fit is ideal.
        if pr == 0 { score -= 25.0; }
    } else {
        score -= 25.0;
    }

    // Fraction-of-capacity classes for post_residual
    let frac = post_residual as f64 / cap;
    if frac > 0.0 && frac <= 0.1 { score += 6.0; }        // sliver
    else if frac <= 0.25 { score += 2.0; }                // small but usable
    else if frac <= 0.5 { score -= 2.0; }                 // good leftover
    else { score -= 4.0; }                                // large leftover

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Harmonic class match between next item and post residual
            let class_match = (pr % next_item_size.max(1) == 0) as f64;
            score -= 5.0 + 3.0 * class_match;
        } else {
            // Next item won't fit here: slight penalty for tight coupling
            score += 1.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it moderately unattractive unless open bins are bad fits
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (post_residual as f64 / cap);

    // Prefer bins tighter than the mean residual (good fill)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are nearly unusable.
    if post_residual > 0 {
        let dead_zone = 12.0; // gaps smaller than ~12 are hard to fill
        if (post_residual as f64) < dead_zone {
            score += (dead_zone - post_residual as f64) * 8.0;
        }
        // Perfect fit: eliminate score entirely to strongly prefer exact fills.
        if post_residual == 0 {
            score -= 200.0;
        }
    }

    // Tightness reward: relative fill of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
        if post_residual as f64 <= 10.0 {
            score += 60.0; // but not if it creates dead space
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins;
    // a new empty bin candidate gets penalized when many bins are already open.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 10.0;
        // Late in the stream, opening new bins is even less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 25.0;
        // But allow a new bin if the item would leave a large awkward gap
        // in every existing bin (mean residual much larger than item).
        if mean_residual > (item_size as f64 + 30.0) {
            score -= 35.0;
        }
    } else {
        // Reward packing into bins whose residual is close to the item size.
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score -= (bin_capacity as f64 - gap) * 0.5;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // reward this placement strongly (chaining placements).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 10.0; // next item will need another bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match between post_residual and next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits perfectly after this placement -> strong reward.
            score -= 12.0 * (1.0 - gap / bin_capacity as f64).powi(3);
            if gap == 0.0 {
                score -= 20.0;
            }
        } else {
            // Next item would NOT fit in the leftover space: penalize dead space,
            // scaled by how much of the leftover is wasted.
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.15 * waste.min(50.0);
        }
    } else {
        // Last item: only care about current fit tightness.
        score -= 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Tight fit reward: smaller post_residual relative to capacity is better.
    score -= 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(2);

    // Compare against mean residual: prefer bins whose residual deviates usefully.
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        // Bin tighter than average: good, keep filling it.
        score -= 0.08 * (-dev);
    } else {
        // Looser than average: slight penalty to avoid fragmenting loose bins.
        score += 0.05 * dev;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity equal to item_size
    // worth of residual elsewhere; only attractive if all open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: its full residual.
        score += 5.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // Fresh bin still guarantees the next item fits: mild discount.
            score -= 4.0;
        }
        if fitting_bins_count == 0 {
            // No open bin can fit; new bin is mandatory anyway.
            score -= 30.0;
        } else if post_residual as f64 > mean_residual + 0.5 * item_size as f64 {
            // Existing bins are quite loose; discourage opening another.
            score += 10.0;
        }
    }

    // Slight late-stream consolidation pressure: fewer open bins preferred as stream grows.
    score += 0.02 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Reward bins whose post-fit residual can still host the lookahead item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0;
        // Extra reward if the lookahead item fits snugly afterwards.
        let second_residual = post_residual - next_item_size;
        score -= 2.0 * (1.0 - second_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: this is the only bin that can take the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 + 5.0 * progress;
    }

    // Penalize creating dead space relative to the current mean residual.
    let dead = post_residual as f64 - mean_residual;
    if dead > 0.0 {
        score += 0.05 * dead;
    }

    // Mildly penalize wasting large-capacity bins on small items.
    score += 0.03 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: discourage opening a new bin unless the best available
    // fit is poor (the low post_residual of a good fit will still win).
    if bin_residual == bin_capacity {
        score += 6.0 + 0.08 * item_size as f64;
        // If the current item is large, a fresh bin is more acceptable.
        if item_size >= bin_capacity / 2 {
            score -= 4.0;
        }
        // Late in the stream, avoid opening new bins for tiny leftovers.
        if item_size < 20 && progress > 0.5 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Normalize residual as fraction of capacity
    let post_frac = post_residual as f64 / bin_capacity as f64;

    // Non-linear penalty on dead space: small post_residuals are either perfect fits
    // (good) or unusable slivers (bad). Use smooth polynomial shaping.
    let dead_space_penalty = (post_frac * (1.0 - post_frac)).sqrt(); // peaks at 0.5
    score -= 12.0 * dead_space_penalty;

    // Reward tight fits with a smooth quadratic decay from zero post_residual
    score -= 20.0 * (-3.0 * post_frac).exp();

    // Stream progress coupling: early on, prefer keeping residuals flexible (larger
    // post_residual is fine); late in the stream, reward compacting bins aggressively.
    let progress_coupling = post_frac * post_frac * (0.5 + 2.0 * progress);
    score += 15.0 * progress_coupling;

    // Lookahead: if the next item fits into the post_residual, reward; otherwise penalize.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        let next_fit_frac = next_item_size as f64 / bin_capacity as f64;
        score -= 8.0 * next_fit_frac * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for spreading across many open bins relative to mean residual.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * (post_frac - mean_residual / bin_capacity as f64).abs();

    // New-bin candidate: penalize opening a new bin unless the item is large and
    // existing residuals are poor. Smooth interaction instead of hard cutoff.
    if bin_residual == bin_capacity {
        let waste_factor = (mean_residual / bin_capacity as f64).powi(2);
        let new_bin_cost = 30.0 - 25.0 * waste_factor - 10.0 * (item_size as f64 / bin_capacity as f64);
        score += new_bin_cost.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in low classes is more painful
    let pr = post_residual;
    let class = pr / 10; // integer division thresholds (0..=9)
    score += match class {
        0 => -30.0,                    // perfect fit: strongly reward
        1 => -18.0,
        2 => -10.0,
        3 => -4.0,
        4 => 0.0,
        5 => 4.0,
        6 => 9.0,
        7 => 15.0,
        8 => 22.0,
        _ => 30.0,                     // large leftover: penalize
    };

    // Modulo-10 coupling: post_residuals divisible by 10 align with future items
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }

    // Lookahead: if next item exactly fits post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / 100.0);
        } else {
            // next item cannot use this residual at all: mild penalty
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Crowding: when many bins are open, prefer tighter packing (lower residual)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);
    score -= 2.0 * progress;

    // Mean residual coupling: penalize bins far above mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: only open a new bin if the fit is truly poor
    if bin_residual == bin_capacity {
        score += 45.0 - 20.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 50.0; // no real alternative: allow new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item are pure waste — penalize them heavily.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 50.0; // perfect fit, no waste at all
    } else if post_residual < 10 {
        score += 60.0; // tiny unusable gap
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0; // gap can't host the lookahead item
    } else {
        // Reward leaving a gap that exactly accommodates the next item
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 15.0;
        }
        // Mild reward for larger usable leftovers
        score -= (post_residual as f64 / bin_capacity as f64) * 8.0;
    }

    // Perfect-fit bonus relative to capacity
    if post_residual == 0 {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += (open_bins_count as f64) * 1.5;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's a tighter bin — slightly favor consolidating there.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless it creates dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual >= 10 {
            score -= 20.0;
        }
    }

    // New-bin candidate: make opening a fresh bin only attractive when the
    // item is large and no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 35.0;
        // A fresh bin is more attractive early in the stream
        score -= (1.0 - step_index as f64 / total_items.max(1) as f64) * 10.0;
        // Attractive if the item is large (would leave small gap elsewhere)
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // Unattractive if many bins already fit the item
        score += (fitting_bins_count as f64) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            // reward closeness of chained fit, penalize leftover after next item
            let next_left = post_residual - next_item_size;
            score -= 25.0 - (next_left as f64).min(25.0);
            score += next_left as f64 * 0.4;
        } else {
            // next item cannot chain here; dead space risk
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Penalize residual far below mean residual (wasting space relative to fleet)
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score += 40.0 - fill_frac * 40.0; // large items justify new bins
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 15.0; // new bin can host the pair
        }
    }

    // Mild preference for tighter fits overall
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Early stream: encourage keeping bins flexible (avoid tiny residuals early)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 && progress < 0.5 {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize leaving dead space that few future items can use
    if post_residual > 0 && post_residual < 10 {
        // small residual is nearly unusable given min size 1..100 unknown; mild penalty
        score += 2.0;
    }
    if post_residual > 50 && post_residual < 70 {
        // awkward mid-range residual
        score += 5.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here after placement; slight penalty
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Encourage spreading across many open bins when they are numerous
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);

    // Prefer bins whose residual is far from the mean residual (diversity of sizes)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.05;

    // New-bin candidate handling: penalize opening a new bin unless it's genuinely useful
    if bin_residual == bin_capacity {
        // Base threshold: opening a new bin should lose to any decent existing fit
        score += 55.0;
        // But if no existing bin fits well (post_residual would be large relative), allow it:
        // when called for new bin, post_residual == capacity - item_size; large post_residual = big item
        let fill = item_size as f64 / bin_capacity as f64;
        score -= fill * 45.0; // big items justify new bins
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // new bin can host the next item too
        }
        // Late in stream, slightly discourage proliferation
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (low post residual), non-linearly scaled.
    let mut score = pr / cap;

    // Polynomial coupling: waste matters more as the stream progresses.
    let pr_norm = pr / cap;
    score += 2.5 * pr_norm * pr_norm * (0.5 + progress);

    // Dead-space penalty: residuals too small for the smallest plausible item are worthless.
    let dead = (pr / 10.0).floor() / 10.0;
    score += 1.8 * dead * dead * (0.3 + 0.7 * progress);

    // Lookahead: if the next item fits the post-residual, reward; otherwise penalize.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 1.2 * (ni / cap) * (1.0 - pr_norm);
        } else {
            score += 0.9 * ((ni - pr) / cap) * (0.5 + progress);
        }
    }

    // Last chance: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 3.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins below mean residual (more crowded bins keep open-bin count low).
    score += 0.4 * ((pr - mean_residual) / cap);

    // New-bin candidate: penalize opening a new bin mildly, more so early on;
    // but if current bin would leave a large residual, new bin becomes attractive.
    if bin_residual == bin_capacity {
        score = 1.0 + 0.5 * (1.0 - progress) - 0.6 * pr_norm * pr_norm;
        if fitting_bins_count == 0 {
            score -= 5.0; // no open bin fits, must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands on
    // "nice" residue classes (multiples of small divisors of capacity) are
    // more likely to host future items, so reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    if pr > 0 {
        let class_bonus: f64 = if pr % 50 == 0 {
            -12.0
        } else if pr % 25 == 0 {
            -8.0
        } else if pr % 10 == 0 {
            -5.0
        } else if pr % 5 == 0 {
            -2.5
        } else {
            0.0
        };
        score += class_bonus;

        // Dead-space penalty: tiny leftovers that few item sizes can use.
        if pr < 10 {
            score += 15.0;
        } else if pr < 20 {
            score += 6.0;
        }
    } else {
        // Perfect closure is excellent.
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let nxt = next_item_size as f64;
            // Prefer residuals in the same "decade class" as next item.
            let frac = nxt / pr.max(1) as f64;
            score -= 10.0 * (1.0 - (frac - 0.5).abs());
            if pr % nxt.max(1) == 0 {
                score -= 6.0; // divisible residual: reusable chunks
            }
        } else {
            // Next item cannot use this bin's leftover at all.
            score += 3.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid wasting it
    // on a huge item that leaves nothing useful — but prefer using it over
    // opening a new bin when the fit is decent.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
        if post_residual < 10 {
            score += 10.0; // don't burn the last fitting bin for near-zero leftover value
        }
    }

    // New-bin candidate handling: an empty bin should only win when open
    // bins fit poorly. Penalize it proportionally to how well existing
    // bins could do (approximated via mean residual), with a mild decay as
    // the stream progresses (less room to consolidate late).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.55 + 8.0 * (1.0 - progress) - 0.15 * mean_residual;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 4.0; // new bin can chain large items
        }
        if fitting_bins_count == 0 {
            score -= cap; // no alternative: new bin is mandatory
        }
    } else {
        // Tightness reward: prefer bins where the item fills a large share
        // of the residual (classic best-fit sharpened by fraction classes).
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        score -= 10.0 * fill;
        // Slight preference for bins below mean residual (consolidate slack).
        score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Mild pressure to reuse bins when many are open.
    score -= 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold even the
    // smallest plausible item (<= 10) are wasted forever.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: post_residual small relative to item size.
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 30.0 / (1.0 + tightness);
    }

    // Penalize bins whose residual is already small (fragmented bins).
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when few are open,
    // encourage consolidation when many are open.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer filling existing bins unless existing fits are terrible.
        score += 15.0;
        // If next item is large, opening a fresh bin early can be good.
        if next_item_size > 60 {
            score -= 20.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item would be blocked by the post residual, mild penalty.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 10.0;
    }

    // Stream progression: later in stream, be slightly more conservative
    // about leaving dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.1;

    // Mean residual coupling: if this bin is far below mean residual,
    // it is relatively full; favor it.
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nr).abs();
        if post_residual >= next_item_size {
            // next item can also fit here: strong reward, sharper for exact match
            score -= (30.0 - diff) * 1.5;
        } else {
            // dead space that blocks the next item: penalize proportionally
            score += (nr - pr) * 1.2;
        }
    }

    // Compare residual against mean residual: avoid leaving below-average space
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is huge relative to capacity
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score -= tightness * 20.0;
        if next_item_size > item_size {
            score -= 10.0; // bigger item coming: keep fresh capacity
        }
    }

    // Late in the stream, prefer tighter packing (waste matters more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual), scaled.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Strongly reward near-perfect fills.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: bonus if next item fits into post_residual (good chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // Extra reward if next item fills remaining space well.
            let gap = post_residual - next_item_size;
            if gap < 10 { score -= 5.0; }
        } else {
            // Post-residual too small for next item: penalize dead space.
            score += (post_residual as f64 - (next_item_size as f64).min(post_residual as f64)) * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 12.0;
        if post_residual < 20 { score -= 6.0; }
    }

    // Many open bins: encourage consolidation into existing bins.
    let open_f = open_bins_count as f64;
    score += open_f * 0.4 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below mean (tighter),
    // prefer it when mean residual is large.
    let residual_f = bin_residual as f64;
    if mean_residual > residual_f {
        score -= (mean_residual - residual_f) * 0.15;
    } else {
        score += (residual_f - mean_residual) * 0.05;
    }

    // Time horizon: late in the stream, be more conservative — prefer using
    // existing bins and avoid leaving large residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.1;

    // New-bin candidate handling: empty bin should only win when existing fits
    // are poor or the item is large.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Penalize new bin; relief if item is large or few fitting bins.
        let mut new_bin_penalty = 15.0;
        new_bin_penalty -= large_item * 10.0;
        if fitting_bins_count == 0 { new_bin_penalty -= 20.0; }
        if fitting_bins_count <= 2 { new_bin_penalty -= 4.0; }
        // Late stream: opening new bins is fine (many items remain to fill them).
        new_bin_penalty -= progress * 5.0;
        score += new_bin_penalty.max(-5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Base: prefer tight fits (small post_residual), non-linearly.
    let norm_post = post / cap;
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Polynomial coupling with stream progress: early on, tolerate imperfect fits
    // to build flexible residual mass; late, demand tight packing.
    let tightness = 1.0 - progress;
    score += 25.0 * tightness * norm_post * (1.0 - norm_post) * (1.0 - norm_post);

    // Penalize dead space relative to the smallest future item (10) —
    // residual below 10 is nearly unusable.
    if post < 10.0 && post > 0.0 {
        score += 15.0 * (10.0 - post) / 10.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item (k=2).
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 8.0 + 4.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
    }

    // Last-chance bin: strong reward to avoid opening a needless bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0;
    }

    // New-bin candidate: penalize so we only open when open bins are truly poor fits.
    if is_new_bin {
        score += 20.0 + 10.0 * progress;
        // But if all open bins would leave bad dead space, allow opening.
        let mean_fit_gap = (mean_residual - item_size as f64).abs();
        if mean_fit_gap > 0.35 * cap {
            score -= 18.0;
        }
    }

    // Slight dispersion penalty: prefer bins far from the mean residual
    // (keeps a spread of residual sizes for future items).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score -= 4.0 * dev * (1.0 - dev);

    // Mild pressure against bin proliferation early in the stream.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fits / small residues are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Zero residual = perfect fit: massive reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Small dead-space classes (1..=10) are nearly perfect fits.
    if post_residual > 0 && post_residual <= 10 {
        score -= 80.0 - (post_residual as f64) * 4.0;
    }

    // Harmonic threshold classes: residues that cannot fit any future item
    // (residual < 10 is dead space; but items can be as small as 1 here).
    // Penalize residues that are unusable for typical items but reward
    // residues that match the lookahead item exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            // Perfect chain: this bin's residue exactly fits next item.
            score -= 300.0;
        } else if post_residual > next_item_size {
            // Residue can host the next item: mild reward scaled by tightness.
            score -= 60.0 * (nxt / (pr + 1.0));
        } else {
            // Residue too small for next item: penalize proportional waste.
            score += 30.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when current bin fit is terrible
    // (large post_residual relative to capacity) or bin is empty anyway.
    if bin_residual == bin_capacity {
        // Fresh bin: baseline penalty so it is chosen only when clearly better.
        score += 40.0;
        if next_item_size > 0 && (next_item_size as f64) > pr {
            score -= 20.0;
        }
    }

    // Modulo-classes of post_residual: residues near half capacity are
    // versatile (fit many items), residues just above small item sizes waste.
    let half = bin_capacity / 2;
    if post_residual >= half && post_residual <= half + 10 {
        score -= 25.0;
    }

    // Coupling with mean residual: placing into a bin far above the mean
    // residual balances the open-bin pool.
    score += 0.5 * (pr - mean_residual);

    // Early in stream, be slightly conservative (keep bins flexible);
    // late in stream, prioritize tight fits more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 30.0 * (1.0 - pr / cap);

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 3 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are tiny (unusable for most items)
    // are heavily penalized. Treat gaps < 10 as pure dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect fit: zero waste is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose residual was already small (compaction of loose space).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive if this bin's fit is poor (large post residual)
    // or the bin is essentially empty. Penalize opening new bins otherwise.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // If next item could then pair well, slightly soften.
        if next_item_size > 0 && next_item_size <= 50 {
            score -= 5.0;
        }
    }

    // If placing here leaves a gap exactly matching the next item, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap the next item cannot use but that is close to usable.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Mild penalty if this bin is much looser than the average residual (waste concentration).
    if bin_residual as f64 > mean_residual + 20.0 && bin_residual < bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual matches next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        if slack == 0.0 {
            score -= 300.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here; penalize dead space
        score += 20.0 + (post_residual as f64).min(60.0);
    }

    // Prefer tighter bins relative to mean residual
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin boost
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let good_fit_exists = post_residual == 0
            || (next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10);
        if good_fit_exists {
            score += 500.0; // discourage new bin when an open bin fits well
        } else {
            score -= 30.0; // allow opening a new bin on poor fits
        }
    }

    // Late-stream consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual non-linearly.
    let pr = post_residual as f64;
    score += 0.35 * (pr / 100.0).powi(3) * 100.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // small unusable sliver is fine (dead space anyway)
        score -= 8.0;
    } else {
        // dead space that could have held a small item is bad
        score += 5.0;
    }

    // Lookahead: reward if next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 0.3 * (next_item_size as f64 / post_residual as f64) * 20.0;
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += 0.15 * ((next_item_size - post_residual) as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin when open bins could fit, more so early in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 70.0 * (1.0 - 0.5 * progress);
        // but if mean residual of open bins is small relative to item, new bin is attractive
        score -= (mean_residual / item_size.max(1) as f64) * 10.0;
    }

    // Prefer filling bins that are already mostly full (low residual).
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Slight preference for fewer open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    let mut score = post;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post_residual); later, tolerate slack.
    let progress_weight = 0.6 * progress * progress + 0.4 * progress;
    score += progress_weight * 30.0 * norm_post * (1.0 - norm_post);

    // Penalize large dead space quadratically when few bins are open.
    let openness = 1.0 / (1.0 + open_bins_count as f64);
    score += openness * norm_post * norm_post * 40.0;

    // Reward exact/near-perfect fits smoothly.
    let fit_quality = 1.0 - norm_post;
    score -= fit_quality * fit_quality * fit_quality * 25.0;

    // Last-chance bonus: strongly favor this bin if it's the only fitting one.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else {
        score -= 6.0 / fitting_bins_count as f64;
    }

    // Lookahead coupling: bonus if next item fits the post residual smoothly.
    if next_item_size > 0 {
        let next_fit = (post - next_item_size as f64) / cap;
        if next_fit >= 0.0 {
            score -= 15.0 * (1.0 - next_fit) * (1.0 - progress);
        } else {
            score += 8.0 * (-next_fit);
        }
    }

    // Mild alignment with mean residual across open bins.
    score += 0.15 * (post - mean_residual);

    // New-bin candidate: penalize opening a new bin, more so later in stream,
    // unless residual waste of existing options is severe (smooth tradeoff).
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - progress);
        score -= 10.0 * norm_post; // always ~0 here, keeps smoothness
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let k = post_residual / 10; // integer division threshold class (0..10)

    // Reward tight fits: exact and near-exact placements get strong bonuses.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Modulo arithmetic on post_residual: residuals that are "nice" multiples
    // (divisible by 5 or 10) are more likely to be filled by future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    } else if post_residual % 5 == 0 {
        score -= 7.0;
    } else {
        score += 5.0; // odd/awkward class penalty
    }

    // Harmonic class thresholds: mid-range dead space is worst.
    if post_residual > 30 && post_residual < 60 {
        score += 12.0 * (1.0 - frac);
    }

    // Lookahead coupling: reward if next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.8;
        } else {
            // next item won't fit here; penalize proportionally to overshoot class
            score += ((next_item_size - post_residual) as f64).min(50.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it when it's the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: prefer new empty bin only when no good fit exists.
    if bin_residual == bin_capacity {
        // Opening a new bin is a last resort; make it costly unless nothing fits well.
        score += 250.0;
        if post_residual > 0 && post_residual <= 10 {
            score -= 250.0; // fresh bin with tiny item still fine
        }
    }

    // Mean residual coupling: if this bin is below-average residual (tighter),
    // prefer filling it to consolidate space.
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // Late-stream pressure: near the end, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 200.0 * progress;
    }

    // Open-bin count pressure: many open bins -> prefer consolidation.
    if open_bins_count > 3 && bin_residual != bin_capacity {
        score -= (open_bins_count as f64).min(20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 11.0);
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln() * 6.0 * (0.5 + progress);

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score = 110.0 + (open_bins_count as f64) * 2.0 - progress * 20.0;
        if fitting_bins_count <= 1 {
            score -= 90.0; // forced new bin anyway
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        return score;
    }

    // Prefer bins with tighter residuals among viable candidates.
    score -= (bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next_item_size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item fill
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
            // penalize leaving dead space that next item can't use
            score += 0.6 * slack;
        } else {
            // next item can't fit in leftover: dead space penalty scaled by leftover size
            let dead = post_residual as f64;
            score += 0.9 * dead;
            // small residual (<10) is effectively dead; extra penalty
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Tight fit reward
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Last-chance bonus: only bin that fits -> avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would leave large unusable gap
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 12.0; // default: prefer existing bins
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score -= 40.0; // existing placements would create tiny dead space -> open new bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // late in stream, consolidate less
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Prefer filling bins with below-average residual (balance-aware)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Mild pressure to close nearly-full bins
    if post_residual <= 5 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: prefer minimal post-residual, with mild non-linear pressure
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 30.0;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Lookahead: reward if next item fits the post-residual exactly or well
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = post_residual as f64 - next_item_size as f64;
        score -= 12.0 * (1.0 - next_fit / bin_capacity as f64);
        if next_fit == 0.0 {
            score -= 30.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space that next item cannot use: penalize proportionally
        score += 6.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Many open bins: discourage fragmenting further, encourage filling existing ones
    let pressure = open_bins_count as f64 / (1.0 + step_index.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing bins are crowded or poor fits
        let mean_tightness = 1.0 - mean_residual / bin_capacity as f64;
        let mut new_bin_score = 55.0
            - mean_tightness * 45.0
            - pressure * 10.0;
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;
        }
        // Late in stream, prefer closing out bins rather than spawning
        new_bin_score += (step_index as f64 / total_items.max(1) as f64) * 15.0;
        score = new_bin_score;
    } else {
        // Filling a nearly-full bin is good; leaving tiny unusable slivers is bad
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 20.0;
        if post_residual > 0 && post_residual < 10 {
            // small sliver: mildly bad unless next item is tiny
            if next_item_size == 0 || next_item_size > post_residual {
                score += 4.0;
            }
        }
        // Reward bins below mean residual (target the emptiest useful bins)
        if (bin_residual as f64) > mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let p = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 40.0 * tightness * tightness * tightness;

    // Penalize dead space that is too small for the smallest plausible item (1..100 range).
    let dead = post_residual as f64;
    if dead > 0.0 {
        let unusable = (dead / cap) * (1.0 - dead / cap) * 4.0; // peaks mid-range
        score += 10.0 * unusable;
    }

    // Non-linear coupling of post_residual with stream progress: later in the
    // stream, prefer bins that leave residuals matching the lookahead item.
    let prog_weight = p * p * (3.0 - 2.0 * p); // smoothstep
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let match_q = 1.0 - ((post_residual as f64 - nr).abs() / cap).min(1.0);
        score -= 25.0 * prog_weight * match_q * match_q;
        // Penalize if post_residual is slightly below next item (near-miss dead space)
        if (post_residual as f64) < nr && (post_residual as f64) > 0.0 {
            score += 15.0 * prog_weight * (nr - post_residual as f64) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Prefer bins with residuals below the mean (consolidate emptier space),
    // with smooth quadratic coupling to stream progress.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 20.0 * prog_weight * dev * dev.abs();

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.5 };
        score += 35.0 * scarcity * (1.0 - prog_weight * 0.5);
        // A fresh bin is more attractive late in the stream when mean residual is low.
        score += 20.0 * (1.0 - (mean_residual / cap).min(1.0)) * prog_weight;
    }

    // Mild penalty for opening many bins relative to progress.
    score += (open_bins_count as f64) * 0.05 * prog_weight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: dead space quantization ---
    // Residuals in (0..10] are nearly dead; small-but-nonzero classes are the worst.
    let pr = post_residual;
    if pr > 0 {
        // Class index: floor(pr / 10) -> harmonic bins of size 10
        let class = pr / 10;
        // Penalize residuals in the "dead zone" classes: 1..9 (i.e. 10..90 usable only for tiny items)
        let dead_penalty = match class {
            0 => -12.0,           // near-perfect fill (0..=9 leftover): strongly reward
            1 => 6.0,             // 10..19: only tiny items fit -> mild dead space
            2 => 2.0,             // 20..29
            3 => 1.0,             // 30..39
            4 => 0.5,
            5 => 0.0,
            _ => 0.0,
        };
        score += dead_penalty;
    } else {
        // Perfect closure of the bin: big reward
        score -= 15.0;
    }

    // --- Lookahead coupling: does next_item_size fit into the post residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Chain bonus scaled by how tightly the next item nests
            let tightness = 1.0 - (pr as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 8.0 + 4.0 * tightness;
        } else {
            // Next item cannot use this residual: penalize proportionally to wasted potential
            let waste = (next_item_size - pr) as f64 / bin_capacity as f64;
            score += 5.0 * waste;
        }
    }

    // --- Last-chance logic: if this is the only bin that fits, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // --- New-bin candidate handling (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if no open bin fits well.
        // Penalize new bins when others can fit; the base post_residual (= capacity - item)
        // already reflects how much fresh space we would create.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Late in the stream, prefer closing existing bins -> penalize new bins more
        score += 14.0 + 10.0 * progress;
        if fitting_bins_count > 1 {
            score += 8.0;
        }
        // If the mean residual of open bins is large, opening yet another bin is wasteful
        score += 0.15 * mean_residual;
    } else {
        // Reward using an already-open bin, more so when many bins are open
        score -= 2.0 * (open_bins_count.min(20) as f64).sqrt();
    }

    // --- Fine best-fit tiebreak: prefer minimal post residual with a nonlinear curve ---
    score += (pr as f64).powf(1.15) * 0.02;

    // --- Modulo harmonic: residuals congruent to small values mod 10 are slightly worse ---
    score += ((pr % 10) as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small for the next item are semi-dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.5 * (next_item_size - post_residual) as f64;
    }
    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward placements that leave room for the lookahead item (chained fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // (penalize the new-bin candidate, which has full residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 12.0 + 3.0 * open_bins_count as f64 + 10.0 * progress;
    } else {
        // Favor fuller bins: the less residual left relative to mean, the better.
        score -= 0.05 * (mean_residual - post_residual as f64);
        score -= 1.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to the item (tight fit) nonlinearly.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tightest fit (small post_residual), scaled by residual fraction.
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // 2-step lookahead: perfect chain match (post_residual == next_item_size) is ideal.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr == nxt {
            score -= 60.0;
        } else if pr >= nxt {
            // next item fits: reward proportionally to how well it chains
            let chain_waste = pr - nxt;
            score -= 45.0 - (chain_waste / bin_capacity as f64) * 60.0;
        } else {
            // next item won't fit in this residual: penalize dead space
            score += (nxt - pr) * 0.5;
        }
    }

    // Relative to mean residual: bins below mean residual are already tight,
    // using them is good; bins above mean have slack, discourage wasting them.
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish score so it only wins when open fits are bad.
    if bin_residual == bin_capacity {
        score = 70.0;
        // Early in stream, opening new bins is cheaper; late, prefer filling.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    // Many open bins: prefer consolidation into existing bins.
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 25.0 * tightness * tightness;
    }

    // Penalize dead space that no plausible item (>=1) can use well:
    // small residuals (<10) are unusable; large residuals are flexible.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // dead space penalty
    }

    // Lookahead: reward residuals that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / (bin_capacity as f64)); // snug for next item
        } else {
            // residual too small for next item: mild penalty scaled by gap
            score += 6.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0)).max(0.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
        // but if fit is very poor, soften the reward
        if post_residual as f64 > 0.7 * bin_capacity as f64 {
            score += 35.0;
        }
    }

    // New-bin candidate handling: make an empty bin attractive only when
    // open bins are crowded or the fit elsewhere would be bad.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score += 45.0;
        // cheaper to open new bins early in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        // if many open bins exist with slack, opening new bins is less attractive
        score += 2.0 * (open_bins_count as f64).min(20.0);
        // if mean residual is small (bins nearly full), new bin is good
        score -= (100.0 - mean_residual).max(0.0) * 0.4;
        // if next item is large, having a fresh bin is valuable
        if next_item_size >= 50 {
            score -= 15.0;
        }
    } else {
        // Existing bins: slight preference for fuller bins (best-fit style)
        let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 10.0 * fill;
    }

    // Prefer distributing load when few bins are open (avoid fragmentation early)
    if open_bins_count <= 2 && bin_residual != bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // As the stream progresses, waste (post_residual) becomes more costly: super-linear penalty
    score += (pr * pr) / cap * (0.5 + 1.5 * progress);

    // Reward tight fits (small post_residual) more strongly late in the stream
    let tightness = 1.0 - (pr / cap);
    score -= tightness * tightness * 20.0 * (0.3 + 0.7 * progress);

    // Penalize residual that cannot fit the lookahead item (dead space), smoothly scaled
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * (0.4 + 0.8 * progress);
        } else {
            // Smooth reward if lookahead fits into the post-residual
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        }
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild pressure to consolidate when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * (pr / cap) * 4.0;

    // Deviation from mean residual: prefer bins whose residual is near the mean (balanced packing)
    score += ((pr - mean_residual) / cap).abs() * 8.0;

    // New-bin candidate: make it moderately attractive only when item fits poorly anywhere
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize capacity into eighths.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as i32;

    // Dead-space penalty: residuals too small for the smallest item (<= 8)
    // are pure waste; penalize quadratically as frac approaches 0.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 * (1.0 - frac * 8.0) * (1.0 - frac * 8.0);
    }

    // Perfect fit reward: strong subtraction when residual nearly vanishes.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Harmonic pairing: if the NEXT item fits exactly into the post-residual
    // (modulo-friendly coupling), reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 60.0;
        } else if gap <= 5 {
            score -= 20.0;
        } else {
            score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use this residual: mild penalty scaled by waste.
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Integer-division threshold: residuals in the "half-full" band
    // (post_residual in [40, 60]) are highly reusable; reward them.
    if post_residual >= 40 && post_residual <= 60 {
        score -= 12.0;
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // open bins are tightly packed (low mean residual => poor fits available).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual / bin_capacity as f64;
        score = 100.0 + 20.0 * progress - 40.0 * (1.0 - tight);
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 15.0; // big item coming, fresh bin useful
        }
    }

    // Mild tie-breaker: prefer bins with below-mean residual (denser bins).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small for the minimum
    // item (1..10) are permanently wasted -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Reward bins whose leftover can host the lookahead item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0; // leftover still usable for next item
    } else if next_item_size > 0 && post_residual > 0 {
        score += 15.0; // leftover too small for lookahead
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // and discourage new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 1.5;

    // New-bin candidate: bias by mean residual of open bins; if open bins
    // are mostly full, opening a new bin is less harmful.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.4;
        if fitting_bins_count > 2 {
            score += 30.0; // plenty of alternatives; new bin rarely needed
        }
    }

    // Slight preference for bins tighter than the current average.
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: strongly reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize proportionally to wasted potential
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow * 0.3;
        }
    }

    // Compare against mean residual across open bins: bins below mean are more precious
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 10.0 * (1.0 - rel);
        } else {
            score += 5.0 * (rel - 1.0);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: default neutral-ish score; only chosen when fits are terrible
    if bin_residual == bin_capacity {
        score = 70.0 + post_residual as f64 * 0.1;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        // late in stream, prefer using open bins
        score += 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space relative to capacity, non-linearly
        let dead_ratio = post_residual as f64 / bin_capacity as f64;
        score += dead_ratio * dead_ratio * 40.0;

        // Lookahead: reward if next item fits into post_residual
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                score -= 15.0 + (next_item_size as f64 / 10.0);
            } else {
                // penalize leaving space just below next item size (wasted gap)
                let gap = post_residual as f64 - next_item_size as f64;
                if gap < 10.0 {
                    score += (10.0 - gap) * 2.0;
                }
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Many open bins: prefer filling existing ones rather than opening more
    let open_pressure = open_bins_count as f64;
    if bin_residual != bin_capacity {
        score -= open_pressure * 0.5;
    } else {
        // New-bin candidate: penalize more when many bins already open or residuals are large
        score += open_pressure * 3.0 + mean_residual * 0.3;
    }

    // Time horizon: early in stream, be more conservative about new bins (bins get reused later)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 20.0;
    }

    // Prefer bins with tighter residuals (best-fit flavor)
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Base: prefer tight fits via non-linear post-residual shaping
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Smooth cubic coupling: small residuals penalized progressively (dead space)
    score += 18.0 * norm_pr * norm_pr * norm_pr;

    // Interaction with stream progress: later in stream, tighter packing matters more
    score -= 30.0 * (1.0 - norm_pr) * progress * progress;

    // Lookahead coupling: reward residual that still fits next item (smooth kernel)
    if next_item_size > 0 {
        let gap = (norm_pr - norm_next).abs();
        score -= 20.0 * (1.0 - gap) * (1.0 - gap) * norm_item;
    }

    // Last-chance bonus: smooth reward when few fitting bins
    let fit_frac = if open_bins_count > 0 { fitting_bins_count as f64 / open_bins_count as f64 } else { 1.0 };
    score -= 15.0 * (1.0 - fit_frac) * (1.0 - fit_frac);

    // Mean residual alignment: prefer bins near mean to preserve diversity
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: penalize opening new bins mildly, more early in stream
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 buckets capture "dead space quality".
    let class = post_residual % 10;
    match class {
        0 => score -= 6.0,          // perfectly divisible residual, highly reusable
        5 => score -= 3.0,          // half-class residual, decent reuse
        1 | 9 => score += 4.0,      // near-full/edge residuals are dead space
        2 | 8 => score += 1.0,
        _ => {}
    }

    // Integer-division thresholds: residual divisible by common item sizes (10, 20, 25, 50)
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 2.5; }
        if post_residual % 20 == 0 { score -= 1.5; }
        if post_residual % 25 == 0 { score -= 1.0; }
        if post_residual % 50 == 0 { score -= 1.0; }
    }

    // Perfect fit is supreme
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does post_residual harmonically fit the next item?
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_class = (post_residual - next_item_size) % 10;
        if next_class == 0 { score -= 5.0; }
        else if next_class <= 2 { score += 2.0; }
        // bonus when next item exactly fills this bin afterwards
        if post_residual == next_item_size { score -= 8.0; }
    } else if next_item_size > 0 {
        // next item cannot use leftover: penalize proportionally to leftover size
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer filling bins that are already relatively full (tight packing)
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 4.0;

    // New-bin candidate: penalize opening a new bin unless current fit is very poor
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if no open bin fits well and item is large, opening is fine
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Late in stream: consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Spread of residuals: if this bin's residual is far from mean, mild penalty
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
