    // Tight fits should be strongly preferred over loose fits.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the post residual (perfect chaining), penalize when it cannot fit at all.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect two-item chain
        } else if next_item_size <= post_residual {
            // next item fits: better when it leaves little further slack
            let second_post = post_residual - next_item_size;
            score -= 12.0 * (1.0 - second_post as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: dead space risk grows with gap size
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap;
        }
    } else {
        // Last item: finishing a bin completely is ideal.
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Relative to mean residual: placing into a bin with residual above the
    // mean concentrates slack and keeps other bins tight.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using the only bin that fits the item,
    // avoiding the cost of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize opening a new bin when good fits exist among open bins,
    // scaled by how full the stream already is (late streams should pack tightly).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress;
        // New bin is acceptable if it enables a perfect chain with next item
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 6.0;
        }
    }

    // Many open bins: encourage consolidating into existing bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
