    // Penalize dead space: residuals that cannot fit typical small items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 15.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for fragmenting this bin.
            score += 8.0;
        }
    }

    // New-bin candidate handling: make empty bins attractive only when fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, discounted when many items remain.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 50.0 * progress;
        // If existing fitting bins are scarce, opening a new bin is more acceptable.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // If mean residual across open bins is low (bins are full), new bin is natural.
        score += (mean_residual / 10.0).min(10.0);
    } else {
        // Reward using existing bins when they are relatively full already.
        let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 12.0 * fill;
        // Penalize scattering across many open bins when mean residual is high.
        if mean_residual > (bin_capacity as f64) * 0.5 {
            score += 10.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.15 * open_bins_count as f64;

    // Time-horizon term: early in the stream, be conservative with new bins;
    // late in the stream, prioritize closing bins tightly.
    if step_index + 1 >= total_items.saturating_sub(5) && !is_new_bin {
        score -= 20.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with non-linear (quadratic) shaping
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) are valued more,
    // large leftovers penalized more aggressively.
    let tight = 1.0 - norm_pr;
    score -= 30.0 * progress * tight * tight * tight;

    // Penalize dead space that cannot fit the lookahead item (smooth ramp)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = ((ns - pr).max(0.0)) / cap;
        score += 25.0 * gap * gap * cap * (0.5 + 0.5 * progress);
        // Reward if lookahead fits in post_residual
        let fits = (pr / ns).min(1.0);
        score -= 15.0 * fits * fits * (1.0 - progress);
    }

    // Last-chance bonus: only fitting bin -> strong reward, stronger early
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins, scaled by deviation
    // from mean residual (encourage consolidation toward the mean)
    let dev = (pr - mean_residual).abs() / cap;
    score += 10.0 * dev * dev * (open_bins_count as f64).sqrt();

    // Reward near-perfect fills smoothly
    score -= 20.0 * (1.0 - norm_pr).powi(6);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are multiples of small divisors
    let pr = post_residual;
    let mut harmony = 0.0f64;
    if pr == 0 {
        harmony -= 60.0; // perfect fill
    } else {
        if pr % 10 == 0 { harmony -= 12.0; }
        if pr % 25 == 0 { harmony -= 10.0; }
        if pr % 20 == 0 { harmony -= 8.0; }
        if pr % 50 == 0 { harmony -= 8.0; }
        // penalize dead space classes (hard-to-fill residuals)
        if pr < 10 { harmony += 30.0; }
        if pr > 0 && pr < next_item_size.max(1) && next_item_size > 0 { harmony += 15.0; }
    }
    score += harmony;

    // Fractional capacity coupling: reward tight fits relative to capacity
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 10.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.55 * cap;
        if poor_fit {
            score -= 20.0; // allow new bin when this would leave big usable space anyway
        } else {
            score += 40.0; // discourage wasteful new bins
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        if pr - next_item_size < 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        score += 8.0; // next item won't fit here
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - tightness);

    // Mean residual deviation: prefer bins near mean to keep balance
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Modulo class threshold on item_size: large items prefer emptier bins
    if item_size >= 50 {
        score += 0.1 * (bin_residual as f64 - post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    // A gap is "dead" if it is nonzero and smaller than the smallest plausible item.
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < 10.0 {
        score += (12.0 - post_residual as f64) * 2.5;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Reward leaving gaps that can still fit the next item (lookahead k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Open-bins pressure: prefer tighter bins when many bins are open.
    let pressure = (open_bins_count as f64) / ((open_bins_count as f64) + 5.0);
    score += pressure * (bin_residual as f64 - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive if all open bins would leave bad gaps.
    if bin_residual == bin_capacity {
        let best_gap_penalty = if fitting_bins_count == 0 { 0.0 } else {
            // penalize opening a new bin when decent fits exist
            10.0
        };
        score += best_gap_penalty + (open_bins_count as f64) * 0.5;
        // allow new bin early in stream when few bins exist
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 3.0;
    }

    // Slight tie-break: prefer bins whose residual deviates below the mean (tighter).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly or closely.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64); // tight but feasible
        } else {
            score += 10.0; // next item won't fit here afterward
        }
    }

    // Compare post_residual against the mean residual: prefer bins driven below average (tight fits).
    let mean_post = mean_residual - item_size as f64;
    score -= 2.0 * (mean_post - post_residual as f64);

    // Penalize tiny dead space that can never host the smallest item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Slight preference for opening new bins early when stream is young and bins are many.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    } else {
        score += 0.5 * open_bins_count as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: reward tight fits.
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Lookahead: if the next item fits exactly into post_residual, heavily reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 25.0 - (gap as f64).min(25.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to lookahead item: penalize small unusable leftovers.
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bonus: only fitting bin; avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize spreading across many open bins when mean residual is high.
    score += open_bins_count as f64 * 0.3 * (mean_residual / bin_capacity as f64);

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = mean_residual < item_size as f64 * 1.2;
        if poor_fit {
            score -= 10.0;
        } else {
            score += 20.0;
        }
    }

    // Early stream: be more conservative (keep bins open); late stream: pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let mut score = post * post / bin_capacity as f64 + 0.5 * post;

    // Smooth non-linear coupling: tight fits are rewarded more as the stream progresses.
    let tightness = 1.0 - post / bin_capacity as f64;
    score -= 40.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space unusable by the lookahead item (smooth quadratic penalty).
    if next_item_size > 0 && post_residual > 0 {
        let gap = next_item_size as f64 - post;
        if gap > 0.0 {
            let g = gap / bin_capacity as f64;
            score += 60.0 * g * g * (1.0 + progress);
        } else {
            // Bonus when the next item exactly fits the leftover space.
            score -= 15.0 * (-gap / bin_capacity as f64);
        }
    }

    // Last-chance bonus: this is the only open bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize spreading into many half-empty bins.
    score += 0.3 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // New-bin candidate handling: baseline penalty that shrinks as stream progresses,
    // so late in the stream we tolerate opening bins for poor fits.
    if bin_residual == bin_capacity {
        score += bin_capacity as f64 * (1.2 - 0.5 * progress);
        if fitting_bins_count == 0 {
            score -= bin_capacity as f64 * 1.5; // no open bin fits: opening is right
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space classes
    // Residuals in (0, 10] are nearly unusable dead space -> heavy penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 8.0;
    } else if post_residual <= 30 {
        score += 2.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small residual classes that can host the smallest items (1..=10)
    if post_residual >= 1 && post_residual <= 15 {
        score -= 10.0; // still reusable for small items
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 45.0;
        } else if slack <= 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot use this bin's leftover: penalize leaving big unusable gap
        score += (post_residual as f64) * 0.3;
    }

    // Last chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin wastes capacity unless item is large
    if bin_residual == bin_capacity {
        // base cost of a new bin ~ half capacity; large items justify it
        score = 50.0 - 0.4 * (item_size as f64);
        if next_item_size > 0 && next_item_size >= 60 {
            score += 10.0; // big next item will need fresh space anyway
        }
        if open_bins_count > 0 && item_size <= 30 {
            score += 15.0; // avoid new bins for small items
        }
    }

    // Prefer filling bins with low residual relative to fleet mean (balance waste)
    score += (mean_residual - post_residual as f64) * 0.15;

    // Late in stream: consolidate, prefer tight fits more aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size (1..100 stream, but small gaps are hard to fill)
    // are heavily penalized as unusable dead space.
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }
    if post_residual == 0 {
        // Perfect fit: strongly rewarded.
        score -= 60.0;
    }

    // Lookahead coupling: reward bins where the next item also fits snugly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
        score -= 10.0 + 15.0 * snug;
    } else if next_item_size > post_residual {
        // Next item won't fit here; slightly penalize leaving a stranded gap.
        score += 5.0;
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., many fitting bins means reuse is clearly better).
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64 * 0.9;
        let pressure = (fitting_bins_count as f64).max(1.0);
        score = base + 30.0 / pressure;
        if fitting_bins_count == 0 {
            score = 5.0; // no alternative: new bin is fine
        }
    }

    // Mild progression coupling: later in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Mean-residual coupling: when open bins are generally full (low mean
    // residual), be more willing to open a new bin; penalize this bin less.
    score -= (mean_residual / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual can
    // exactly (or nearly) host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 20.0; // perfect 2-step pairing
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize proportionally to the
        // unusable gap this creates.
        let gap = (next_item_size - post_residual) as f64;
        score += 6.0 * (gap / bin_capacity as f64);
    }

    // Penalize dead space far below mean residual (fragmentation risk).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 2.0 * dev / bin_capacity as f64;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild preference for keeping fewer open bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Small tie-break favoring tighter fits.
    score += 0.05 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the item into the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill * fill;

    // Penalize very small dead space ONLY mildly; but heavily penalize
    // dead space that no plausibly arriving item can use (below min item 1 is fine,
    // so instead penalize dead space far from typical item sizes).
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 6.0; // tiny unusable slivers are acceptable waste
    } else if dead >= 10.0 && dead <= 50.0 {
        score -= 4.0; // mid-range residual is reusable
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item would fit in post_residual,
    // reward this placement (creates a good chain).
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            let chain_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 12.0 * chain_fit;
        } else if (next_item_size as i64) > (post_residual as i64)
            && (bin_residual as i64) >= (item_size as i64 + next_item_size as i64)
        {
            // Packing both current and next item here is ideal.
            score -= 15.0;
        } else {
            // Next item won't fit here; slight penalty for fragmenting.
            score += 3.0;
        }
    }

    // Global state: many open bins with slack -> prefer consolidating into
    // bins with above-mean residual (close out nearly-empty bins).
    if open_bins_count > 1 {
        let rel = bin_residual as f64 - mean_residual;
        score -= 0.08 * rel;
        // Pressure to consolidate grows with number of open bins.
        score -= 0.5 * (open_bins_count as f64).ln();
    }

    // New-bin candidate logic: opening a fresh bin is only attractive when
    // the item is large relative to capacity and no tight option exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Base cost of a new bin, discounted when item is big or stream is early.
        score += 30.0 - 20.0 * item_frac - 8.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative; must open
        }
    }

    // Time horizon: late in the stream, avoid opening bins (waste locks in).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && !is_new_bin {
        score -= 5.0 * progress;
    }

    // Mild preference for bins whose residual is close to a multiple band
    // of common item sizes (keeps residuals "composable").
    let r = post_residual % 20;
    if r == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr_norm = pr / cap;
    let t = progress;
    // Smooth interaction: dead space becomes more costly as stream progresses.
    let coupling = pr_norm * pr_norm * (0.5 + 1.5 * t) * cap;
    score += coupling;

    // Reward tight fits (small post_residual relative to item) with smooth term.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * (1.0 + t);

    // Penalize wasted space that next item cannot use (smooth quadratic).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.6 * gap * gap / cap;
        // Reward if next item fits exactly into post residual.
        let fits_next = ((pr - next_item_size as f64).abs()) / cap;
        score -= 4.0 * (1.0 - fits_next.min(1.0)) * (pr >= next_item_size as f64) as i32 as f64;
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - pr_norm);
    }

    // Mild penalty when bin is far below mean residual (fragmentation risk).
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * cap;

    // Slight preference to keep many open bins consolidated late in stream.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (0.5 + t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "usable slots"
    // (multiples of common item sizes 10..=25), penalize dead-space classes.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else {
        let mut class_bonus = 0.0;
        for m in 10..=25 {
            if pr % m == 0 {
                class_bonus += 4.0;
            }
        }
        score -= class_bonus;
        // Integer division threshold: small residuals (< 10) are dead space
        if pr < 10 {
            score += 12.0;
        } else if pr <= 20 {
            score += 2.0;
        }
        // Harmonic fraction: residual as fraction of capacity
        let frac = pr as f64 / cap;
        if frac > 0.5 {
            score -= 6.0; // large leftover still very usable
        } else if frac < 0.1 {
            score += 8.0; // tiny unusable sliver
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0;
        score -= 20.0 / (1.0 + gap); // exact lookahead fit heavily rewarded
        if gap == 0.0 {
            score -= 15.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item cannot use this residual: mild penalty scaled by waste
        let waste = (next_item_size - post_residual) as f64;
        score += (waste / 20.0).min(10.0);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current fit is poor
    // and many bins are open (diversification when fragmented).
    if bin_residual == bin_capacity {
        score += 25.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing fits anywhere: must open
        } else {
            // open new bins more readily late in stream when fragmentation is high
            if mean_residual < 25.0 && open_bins_count > 4 {
                score -= 10.0 * progress;
            }
        }
    }

    // Prefer tighter bins generally: closeness of item to residual (good fit)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio;

    // Mean-residual coupling: placing into bins below mean residual keeps spread even
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the bin.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness * (item_size as f64);

    // Dead-space penalty: small unusable gaps (post_residual < 10) are wasted space
    // under the original 10..80 regime; penalize them nonlinearly.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only open bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize the new-bin candidate more when many bins are already open).
    if bin_residual == bin_capacity {
        score += 6.0 + 1.5 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // reward this placement strongly (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 / (1.0 + slack);
    }

    // Mean-residual alignment: prefer bins whose residual is close to the mean
    // (balanced packing), mildly.
    let resid = bin_residual as f64;
    score += 0.05 * (resid - mean_residual).abs();

    // Early stream: slightly prefer new bins early (build diversity), later consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.5 * diff;
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-step chain
        } else if post_residual >= next_item_size {
            score -= 5.0; // next item still fits here
        } else {
            score += 10.0; // dead space relative to lookahead
        }
    }

    // Prefer bins that are already fairly full (small residual relative to mean)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Tight fit reward: penalize large post_residual (wasted space)
    score += 0.2 * post_residual as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current bin would leave unusable residue
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if no open bin fits well, allow new bin
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 40.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to item size.
    let item = item_size as f64;
    if item > 0.0 {
        score -= (bin_capacity as f64 - post_residual as f64) * (1.0 - post_residual as f64 / bin_capacity as f64) * 0.5;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Dead-space penalty: small post_residual that likely can't fit future items (min size 1 unknown; use 10 as typical floor).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            score -= 25.0;
        } else if post_residual as f64 >= nxt {
            score -= 6.0;
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += (nxt - post_residual as f64) * 0.2;
        }
    }

    // Time horizon: late in stream, prefer consolidating into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (bin_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage filling existing ones rather than opening new.
    score += open_bins_count as f64 * 0.5 * (bin_residual >= bin_capacity) as i32 as f64;

    // Mean residual coupling: if this bin's residual is far below mean, it's a laggard bin — prefer filling it.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // New-bin candidate: add a fixed opening cost so it's chosen only when no open bin is decent.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But late in stream with tight lookahead, opening may still win; soften slightly.
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr as f64 * (1.0 + 0.5 * progress * progress);

    // Reward tight fits: quadratic bonus as post_residual shrinks
    score -= (1.0 - fit_norm) * (1.0 - fit_norm) * 20.0;

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score += (gap * gap) / cap * 0.3 * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05 * fit_norm;

    // Mean residual drift: prefer bins below mean residual (tighter bins first)
    score += (mean_residual - pr) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible into
    // "clean" classes (0, small, or large-but-pairable) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Perfect fit is heavily rewarded.
    if pr == 0 {
        score -= 1000.0;
    }

    // Modulo-10 harmonic class: dead space that is a multiple of 10
    // is more likely reusable by future items.
    let class = pr % 10;
    if class == 0 {
        score -= 15.0;
    } else if class <= 2 {
        score += 10.0; // sliver waste
    }

    // Integer-division thresholds on post_residual: medium residuals
    // (25..=50) are prime targets for next items; penalize extremes.
    if pr >= 25 && pr <= 50 {
        score -= 20.0;
    } else if pr > 60 && pr < 90 {
        score += 8.0; // awkward large-but-not-reusable zone
    }

    // Coupling with lookahead item: reward residuals that fit next item.
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            score += 12.0; // next item cannot reuse this bin's leftover
        }
    }

    // Last-chance bin: if only this bin fits, strongly favor it to
    // avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has high post_residual.
    // Only prefer it when no open bin offers a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let best_open = mean_residual.max(0.0);
        if best_open > item_size as f64 + 20.0 {
            score += 60.0; // open bins still roomy; don't open new
        } else {
            score -= 10.0; // open bins are tight; new bin is fine
        }
    }

    // Progress-based mild pressure to consolidate late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Normalize by capacity fraction.
    score * (cap / 100.0)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Define "dead zone" as residual space smaller than the smallest plausible item.
    let dead_threshold = 10.0_f64; // items can be as small as 1..100; treat tiny gaps as waste
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * 8.0; // dead space is worse than wasted space in a fresh bin
    }
    // Non-linear: quadratic penalty on small leftover space (0 < pr < 30)
    if pr > 0.0 && pr < 30.0 {
        score += (30.0 - pr).powi(2) / 30.0;
    }

    // Reward tight fits (post_residual near zero but not dead space)
    let fill_ratio = 1.0 - pr / cap;
    score -= fill_ratio * 40.0;

    // Penalize bins whose residual is already small (they are scarce resources)
    let res_ratio = bin_residual as f64 / cap;
    score += (1.0 - res_ratio) * 15.0;

    // Open-bins pressure: prefer reusing existing bins over opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or when this bin fits.
        if fitting_bins_count > 0 {
            score += 25.0 + 3.0 * open_bins_count as f64;
        } else {
            score += 5.0; // only option anyway; mild baseline
        }
    } else {
        // Reusing an open bin is good; extra reward if it's the last fitting bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        score -= 10.0;
    }

    // Lookahead: if next item can use the post_residual, reward leaving exactly that gap.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr - nxt).abs() < 1.0 {
            score -= 30.0; // perfect two-item packing
        } else if pr >= nxt && pr - nxt < dead_threshold {
            score += (dead_threshold - (pr - nxt)) * 6.0; // next item would create dead space
        }
    }

    // Stream progression: late in the stream, tighten up and avoid new bins even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    } else {
        score -= progress * 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (use up tighter bins first).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
