    // Relative to mean residual: prefer bins with residual near/below mean (drier bins first)
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize creating very small unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New empty bin candidate: penalize mildly so it's only chosen when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if next item is huge and current fit is bad, new bin becomes attractive
        if next_item_size > 0 && post_residual + item_size as f64 as u32 as f64 as f64 > 0.0 {
            // no-op placeholder coupling
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Slight penalty for scattering across many open bins
    score += 0.3 * open_bins_count as f64;

