}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize progress through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fits are good: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for the smallest plausible future item.
    if post_residual < 10 {
        score += 30.0;
    } else if post_residual < item_size.min(80) {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Next item won't fit here; penalize proportionally to wasted space.
            score += 0.15 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin is a fallback; make it attractive only
    // when existing bins would leave large unusable residue, and early in the stream
    // or when many bins are open (diversification of residual sizes).
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.6 * bin_capacity as f64;
        let fallback_bonus = if poor_fit { 10.0 } else { 0.0 };
        // Early stream: opening bins builds diversity; late stream: prefer filling.
        let time_bonus = 15.0 * (1.0 - progress);
        let crowd_penalty = 1.5 * open_bins_count as f64;
        score += 45.0 - fallback_bonus - time_bonus + crowd_penalty;
        // If the next item is large, an empty bin is valuable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is below the mean residual (filling the emptier side
    // keeps a spread of residual sizes available).
    let diff = mean_residual - bin_residual as f64;
    score += 0.08 * diff;

    // Mild pressure to keep the number of open bins from exploding.
    score += 0.05 * open_bins_count as f64;

    // Late-stream urgency: consolidate aggressively.
    if progress > 0.8 {
        score -= 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: minimize post residual, with non-linear polynomial shaping.
    let mut score = post * (1.0 + 0.5 * norm_post * norm_post);

    // Stream-progress coupling: early on tolerate larger residuals, later penalize them more.
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Penalize residuals that cannot plausibly fit the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += (nxt - post) * (0.5 + progress);
        } else {
            // Reward residuals that still accommodate the next item smoothly.
            score -= 2.0 * (post / (nxt + 1.0)).ln().abs().min(2.0);
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_post);
    } else {
        score += 1.0 * (fitting_bins_count as f64).ln();
    }

    // Dead-space penalty: residuals too small for the minimum item size (1) are unusable.
    if post == 0 {
        score -= 5.0; // perfect fit is ideal
    } else if post < 1.0 {
        score += 20.0;
    }

    // Mean-residual coupling: prefer bins close to the mean residual (balance).
    let dev = (post - mean_residual) / cap;
    score += 4.0 * dev * dev * cap * 0.01;

    // Mild penalty for opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress) - (open_bins_count as f64).ln() * 2.0;
        // But encourage new bins when post residual of this empty bin is best for tight items.
        if item_size as f64 > 0.8 * cap {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
