    } else if post_residual < 25 {
        score += 8.0 * (25.0 - post_residual as f64) / 15.0;
    }

    // Harmonic class: post_residual divisible by common item sizes is reusable
    let reusable = [10u32, 20, 25, 50];
    if reusable.iter().any(|&r| post_residual % r == 0) && post_residual > 0 {
        score -= 12.0;
    }
    // Integer-division class: leftover supports a next-size chunk
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 {
        score += 10.0;
    }

    // Last-chance bin bonus: avoid wasting the only fitting bin? Actually prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when current bin would be badly fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = fit_ratio > 0.5 && post_residual < 60;
        if bad_fit || open_bins_count == 0 {
            score -= 35.0 + 15.0 * progress;
        } else {
            score += 40.0; // prefer existing bins with decent fits
        }
    }

    // Mild pressure to consolidate: prefer bins tighter than average
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Tightness reward: fraction of bin filled by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Last-chance bonus: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // and existing residuals are too small to be useful.
    if bin_residual == bin_capacity {
        score += 35.0;
        if item_size as f64 > mean_residual {
            score -= 45.0; // existing gaps too small, new bin justified
        }
        // Late in stream, opening bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // creates dead space relative to next item
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.4 * open_bins_count as f64;

    // Slight pull toward bins with below-average residual (fill emptier-first
    // keeps large gaps available for large future items).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain: post_residual == next_item_size -> strong reward.
        if diff == 0.0 {
            score -= 40.0;
        } else {
            // Penalize mismatch, scaled by how tight the bin is.
            score += diff * 0.5;
        }
        // If next item cannot fit after this placement, penalize mildly.
        if post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.3;

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize creating tiny unusable dead space (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large and
    // no good fit exists (large item benefits from a fresh bin).
    if bin_residual == bin_capacity {
        let base_penalty = 20.0;
        // Large items waste less in fresh bins; small items should use existing space.
        let size_bonus = (item_size as f64 / 100.0) * 25.0;
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += base_penalty - size_bonus + progress * 10.0;
    }

    // Slight preference for filling tighter bins overall.
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space relative to next item: penalize small leftovers that can't fit next item
        score += 5.0 * (next_item_size as f64 - post_residual as f64).min(30.0) / 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current fit is poor
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // base penalty for opening a new bin
        score += 60.0;
        // but reward new bin if item is large and would leave a nearly-full bin anyway
        if item_size >= 70 {
            score -= 50.0;
        }
        // penalize more when many bins already open (avoid bin proliferation)
        score += 2.0 * open_bins_count as f64;
        // time horizon: early in stream, cheaper to open bins for future flexibility
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        let _ = tightness;
    }

    // Prefer bins with small residual relative to mean (tight packing)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Slight preference for more-filled bins overall
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling: post_residual weighted by stream progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Penalize large dead space quadratically, more so late in the stream
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: small post_residual relative to item size
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness * (1.0 - progress * 0.5);

    // Lookahead coupling: if next item fits into post_residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 15.0 * (1.0 - (pr - nxt) / cap) * (1.0 - progress);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress);
    }

    // Mild preference toward consolidating into bins below mean residual
    score += 5.0 * (pr - mean_residual) / cap;

    // New-bin candidate: discourage opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - tightness) * (1.0 - progress * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose residual falls into
    // "small" classes (<= 10) are nearly perfectly packed -> reward strongly.
    let pr = post_residual;
    let class = pr / 10; // integer division threshold class (0..10)
    score -= (10 - class.min(10)) as f64 * 6.0;

    // Perfect fit: zero waste is ideal.
    if pr == 0 {
        score -= 100.0;
    } else {
        // Dead-space penalty grows quadratically for tiny unusable remainders
        // that likely cannot host any future item (min item size unknown, use 1..100 band).
        if pr < 20 {
            score += (20 - pr) as f64 * (20 - pr) as f64 * 0.15;
        }
        // Harmonic modulo logic: residuals divisible by common item granularities
        // (5, 10, 25) are more reusable.
        if pr % 5 == 0 { score -= 4.0; }
        if pr % 10 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            // next item fits: leftover after that also matters (harmonic chaining)
            let pr2 = pr - next_item_size;
            score -= 15.0 - (pr2 as f64) * 0.2;
        } else {
            // next item won't fit here: mildly penalize wasting a big residual
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: an empty bin has residual == capacity. Its raw
    // score is `capacity`; keep it high unless the current fit is very poor.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: new bin slightly penalized so tight fits win,
        // but rewarded when open bins are crowded.
        score = cap * 0.9 + mean_residual * 0.1 - (open_bins_count as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host the next item too
        }
    }

    // Progress-based mild pressure: later in the stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Prefer bins below mean residual (tighter bins) slightly.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to ever hold the
    // minimum item are heavily penalized (quadratically).
    if post_residual > 0 && post_residual < 10 {
        score += 120.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Gaps below the typical small-item threshold are risky too.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Pressure from number of open bins: discourage spreading when many
    // bins are open, encourage consolidation.
    score += open_bins_count as f64 * 1.5;

    // If the next item could exactly use the post_residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 50.0;
    }
    // If next item fits in the resulting gap, mild reward.
    if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when no decent fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // If other fitting bins are tight (good fits), make new bin worse.
        if fitting_bins_count >= 1 {
            let best_possible = bin_residual.min(bin_capacity);
            let _ = best_possible;
            score += fitting_bins_count as f64 * 20.0;
        }
        // If current bin would leave a dead gap, opening a fresh bin
        // becomes relatively more attractive.
        if post_residual > 0 && post_residual < 10 {
            score -= 90.0;
        }
        // Early in the stream, prefer opening bins more freely.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 15.0;
        }
    }

    // Mean residual coupling: if the fleet average residual is high,
    // prefer placements that consume from fuller bins less; i.e. prefer
    // bins below mean residual (they are emptier, absorb the item well).
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match lookahead: strongly reward post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 60.0;
        } else if diff <= 5 {
            score -= 30.0 / diff as f64;
        } else {
            // penalize leftover that next item can't use (dead space)
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.5;
            }
        }
        // small lookahead bonus if next item still fits in residual
        if post_residual >= next_item_size && diff > 5 {
            score -= 5.0;
        }
    } else {
        // last item: prefer tightest fit
        score -= 10.0;
    }

    // Reward tight fits relative to capacity
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 8.0;

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent alternatives exist
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            let best_possible = (mean_residual - item_size as f64).abs();
            if best_possible < 20.0 {
                score += 25.0;
            } else {
                score += 5.0;
            }
        } else {
            score -= 20.0; // no alternative: new bin is correct
        }
        // early stream: slightly favor consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 3.0;
    }

    // Prefer bins with residual close to mean (balance)
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post / cap);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that can never be used by typical items (min size 10).
    if post_residual < 10 {
        score += 12.0; // perfect fill, actually good -> invert: reward instead
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only bin that can fit, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead synergy: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let next_waste = post_residual - next_item_size;
            score -= 10.0 * (1.0 - (next_waste as f64) / cap);
        } else {
            // next item cannot use the leftover: mild penalty for large leftovers
            score += 0.15 * post;
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (future flexibility matters); late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_penalty = 15.0 + 25.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // Opening a new bin is more attractive when many bins are open and fragmented.
        score -= 0.3 * open_bins_count as f64;
        // If mean residual across bins is small, current bins are nearly full -> new bin ok.
        score -= 0.2 * mean_residual;
    }

    // Prefer bins below mean residual (less-full bins) slightly to balance load,
    // but only when the fit is not tight.
    if post / cap > 0.3 {
        score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = pr;

    // Smooth polynomial coupling: penalize large residuals early, reward tight fits late
    let x = pr / cap;
    score += 12.0 * x * x * (1.0 - progress) - 8.0 * x * x * progress;

    // Reward filling bins well relative to mean residual
    if mean_residual > 0.0 {
        score -= 4.0 * (pr - mean_residual) / cap;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (next_item_size as f64 / cap);
    }

    // Penalize opening new bins when many bins already fit the item
    if bin_residual == bin_capacity {
        score += 5.0 * (fitting_bins_count as f64) + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: class 0 (perfect fill) heavily rewarded.
    let post = post_residual;
    if post == 0 {
        score -= 1000.0;
    } else if post <= 10 {
        score -= 60.0;
    } else {
        // Modulo-class dead-space penalty: residuals that few item sizes can use are bad.
        // Items are 1..=100; count how many item sizes (1..=post) could still fit later,
        // approximated by harmonic classes via integer division thresholds.
        let usable = (post * (post + 1)) / 2; // triangular weight: larger residuals more usable
        score -= (usable as f64).sqrt() * 2.0;

        // Penalize residuals in "awkward" modulo classes w.r.t. capacity fractions.
        let class = post % 25; // capacity quarter classes
        score += match class {
            0 => -20.0,      // quarter-aligned leftover: likely reusable
            1..=5 => 8.0,    // near-aligned: slightly awkward
            _ => 0.0,
        };
        // Half-capacity aligned leftovers are prime targets for mid-size items.
        if post == 50 {
            score -= 35.0;
        }
        if post % 10 == 0 {
            score -= 10.0; // decade-aligned residuals pair with common item sizes
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, mild preference toward tighter fits (already via post_residual).
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 200.0;
        } else if next_item_size < post {
            // Reward proportional to how well next item fills the leftover.
            let fill = next_item_size as f64 / post as f64;
            score -= 40.0 * fill;
        } else {
            // Next item won't fit here; penalize leaving large dead space.
            score += (post as f64) * 0.15;
        }
    }

    // New-bin candidate handling: an empty bin has huge post_residual; only prefer it
    // when no open bin offers a decent fit (large item, few fitting bins).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Baseline cost of opening a new bin; reduced late in stream or when item is large.
        let mut new_bin_cost = 120.0 - 40.0 * progress;
        if item_size > bin_capacity / 2 {
            new_bin_cost -= 25.0;
        }
        if fitting_bins_count == 0 {
            new_bin_cost = -500.0; // no open bin fits: must open
        }
        score += new_bin_cost;
    }

    // Mild tie-break: prefer bins whose residual is below the mean (consolidate fullness).
    score += (post as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) more aggressively.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins when fit is loose.
    if post_residual > 0 {
        score += 0.05 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item won't fit here; penalize leaving a gap it can't use.
            score += 10.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: neutral-ish baseline, opened only when no open bin scores lower.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong lookahead matching: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_quality = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
        score -= 35.0 * match_quality;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space penalty: post_residual too small for the next item
        score += 0.6 * (post_residual as f64);
    }

    // Penalize creating very small unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it over a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins have poor residuals
    if bin_residual == bin_capacity {
        // Slight penalty so we prefer reusing bins with good fits; relax late in stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 - 8.0 * progress;
    }

    // Prefer bins tighter than the mean residual (better packing)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Mild preference for fuller bins overall
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively.
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Penalize dead space that cannot fit the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits into post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else if bin_residual >= next_item_size {
            score += 6.0; // this bin would be better saved for the next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Encourage consolidation when many bins are open.
    score += open_bins_count as f64 * 0.8;

    // Prefer bins with residual below mean residual (denser bins).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Early in stream: slightly prefer filling existing bins; late: be picky.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    // New-bin candidate: make it moderately attractive only for large items
    // or when current bin would leave very awkward space.
    if bin_residual == bin_capacity {
        let awkward = post_residual > 0 && post_residual < 20;
        if item_size > 60 || awkward || open_bins_count == 0 {
            score -= 12.0;
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: prefer tight fits (low post_residual). Late: tolerate residual
    // since bins may close anyway; smooth polynomial interaction.
    let tightness = norm_pr * norm_pr; // quadratic in residual
    let progress_coupling = tightness * (1.0 - progress) * (1.0 - progress);
    score += 30.0 * progress_coupling;

    // Cubic coupling: large residuals late in stream become less penalizing
    let cubic = norm_pr * norm_pr * norm_pr;
    score -= 20.0 * cubic * progress;

    // Dead-space penalty: residual that cannot fit even the next item is waste.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 + 0.25 * (next_item_size - post_residual) as f64 * (1.0 - progress);
    }

    // Lookahead synergy: residual that exactly accommodates next item is valuable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 6.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate: penalize opening a new bin when open bins exist,
    // scaled by how many bins could otherwise fit the item.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 + 3.0 * open_bins_count as f64;
    }

    // Mean residual coupling: placing into a bin far from mean residual
    // balances load; smooth quadratic term.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: reward residuals that are "friendly" modulo small divisors,
    // since common item sizes (multiples of 5/10) pair well with them.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Perfect fit is best possible.
    if pr == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic bonus: residual divisible by 10 or 5 is likely reusable.
    if pr % 10 == 0 {
        score -= 12.0;
    } else if pr % 5 == 0 {
        score -= 6.0;
    }

    // Small dead space is bad: penalize residuals in awkward ranges.
    if pr < 10 {
        score += 30.0; // unusable sliver (min item 1..100, but tiny waste)
    } else if pr <= 20 {
        score += 10.0;
    }

    // Fraction-of-capacity classes: residuals near half or full capacity are flexible.
    let frac = pr as f64 / cap;
    if (frac - 0.5).abs() < 0.1 {
        score -= 8.0;
    }
    if frac > 0.7 {
        score -= 5.0; // large residual remains useful
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack % 10 == 0 {
                score -= 15.0;
            } else if slack % 5 == 0 {
                score -= 8.0;
            }
            if slack < 10 {
                score += 8.0; // leaves a sliver after next item too
            }
        } else {
            // next item won't fit here anyway; slight penalty for tight fills
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin if current bins are crowded
    // and this placement would create bad dead space.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: its residual is capacity, already high score.
        // Penalize opening new bins unless there are many open bins with low mean residual.
        score += 15.0;
        if mean_residual < 25.0 && open_bins_count > 0 {
            score -= 20.0; // existing bins are crowded; a new bin is reasonable
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.05;

    // Slight progression awareness: later in stream, be a bit more greedy about fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for dead space that is too small to fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / item_size.max(1) as f64;
    score -= 20.0 / (1.0 + fit_ratio);

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 0.8;

    // If lookahead item can use the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Prefer bins with below-mean residual (concentrate free space).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Early in the stream, be slightly more willing to open new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    // New-bin candidate: penalize mildly so it is chosen only when open bins have bad fits.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.01;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: squared post-residual penalty.
    score += (post_residual as f64).powi(2) * 0.02;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: heavily favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty spread when many bins compete, keeps preference tight.
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // New empty bin candidate: penalize opening a new bin generally,
    // but relax penalty when the item leaves large dead space in existing bins
    // or when open bins are already fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        let base_penalty = 45.0;
        // If the item is large relative to capacity, opening fresh is less bad.
        let size_relief = (item_size as f64 / bin_capacity as f64) * 30.0;
        // If existing bins are mostly full (low mean residual), opening is worse.
        let scarcity_penalty = (mean_residual / bin_capacity as f64) * 20.0;
        score += base_penalty + scarcity_penalty - size_relief;
        // Late in stream, avoid proliferation of nearly-empty bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Lookahead: if the post-residual can exactly fit the next item, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Reward leaving room for the next item, scaled by how snug it is.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Leaving dead space the next item can't use: mild penalty.
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Prefer bins with residual below mean (use the tightest bins first),
    // keeping looser bins available for larger future items.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild global pressure: with many open bins, consolidate into existing ones.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = pr_norm * (1.0 + 2.0 * progress + 3.0 * p2 + 1.5 * p3);
    score += 20.0 * coupling;

    // Penalize tiny dead space (waste) with smooth quartic-ish term
    if pr > 0.0 {
        let tiny = (cap - pr.min(cap)) / cap; // fill fraction
        let dead = (1.0 - tiny) * (1.0 - tiny);
        score += 5.0 * dead * pr_norm * pr_norm;
    }

    // Reward tight fits: small post_residual relative to item size
    let item = item_size as f64;
    let tightness = item / (item + pr + 1.0);
    score -= 10.0 * tightness;

    // Last-chance bin bonus (smooth)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = if pr >= nxt { 1.0 } else { 0.0 };
        let gap = ((pr - nxt).abs()) / cap;
        score -= 8.0 * fit_next * (1.0 - gap) * (1.0 - 0.5 * progress);
        score += 6.0 * (1.0 - fit_next) * (pr / cap) * (0.5 + 0.5 * progress);
    }

    // Discourage spreading across many bins early
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    // Deviation from mean residual: prefer bins near mean for balance
    let dev = (pr - mean_residual).abs() / cap;
    score += 3.0 * dev * (1.0 - p2);

    // New-bin candidate: penalize mildly so it's chosen only for poor fits
    if bin_residual == bin_capacity {
        score += 12.0 + 18.0 * (1.0 - progress);
        if next_item_size as f64 > pr * 0.9 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: penalize residuals in "dead zones"
    // where few item sizes (1..=100) can still fit.
    let class = post_residual % 25;
    match class {
        0 => score -= 30.0,            // perfectly divisible residual, very reusable
        1..=9 => score += 12.0,        // awkward sliver
        10..=19 => score -= 5.0,       // decent mid-range residual
        _ => score += 2.0,             // 20..24 near-quarter residual
    }

    // Integer-division thresholds: small post_residual is dead space unless
    // it exactly matches a plausible small item class.
    if post_residual > 0 && post_residual <= 10 {
        // dead space penalty, softened if next item could use it
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 15.0;
        }
    }

    // Perfect fit reward (residual becomes zero).
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor
    // (large mean residual spread) or item is huge relative to residual.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 20.0;
        // more attractive when open bins are fragmented (high mean residual
        // means poor packing so far)
        score -= (mean_residual / bin_capacity as f64) * 10.0;
        // less attractive late in the stream when many bins are open
        score += open_bins_count as f64 * 0.5;
        // if item barely fits nowhere else, new bin is fine
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // lookahead: if next item is small, a fresh bin wastes capacity
        if next_item_size > 0 && next_item_size < 20 {
            score += 10.0;
        }
    } else {
        // reward tight fits in existing bins: post_residual close to 0
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * 20.0;

        // lookahead synergy: if next item fits the post_residual exactly-ish,
        // reward this placement
        if next_item_size > 0 && next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 18.0;
            } else {
                score -= (gap as f64).recip() * 10.0;
            }
        } else if next_item_size > post_residual {
            // next item cannot use leftover; penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Stream progression: early on, be conservative about fragmenting bins;
    // later, prioritize closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * tightness_proxy(post_residual, bin_capacity);

    score
}

fn tightness_proxy(post_residual: u32, bin_capacity: u32) -> f64 {
    1.0 - (post_residual as f64 / bin_capacity as f64)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        // Dead space below minimum item size: heavily penalized.
        score += 60.0 - pr * 4.0;
    } else if pr == 0.0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Usable residual: mild reward for tightness.
        score += pr * 0.15;
    }

    // Reward leaving space exactly matching the next item (lookahead coupling).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        if diff < 5.0 {
            score -= 12.0 * (1.0 - diff / 5.0);
        } else if pr < next_item_size as f64 {
            // Next item won't fit here; slight penalty for stranding.
            score += 4.0;
        }
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferation of open bins unless it's a new bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin is attractive only when existing bins are crowded or fit is bad.
        let crowd = (mean_residual / bin_capacity as f64).min(1.0);
        score += 30.0 * crowd + pr * 0.3;
        if fitting_bins_count <= 2 {
            score += 15.0;
        }
    } else {
        score += open_bins_count as f64 * 0.6;
        // Prefer the emptiest bins to consolidate load.
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    // Late-stream: prefer closing bins tightly as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward leaving enough room for the next item, scaled by tightness.
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit: dead space penalty grows with gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Penalize tiny unusable residuals relative to item scale.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer tight fits: fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current bin would leave a bad residual.
    if bin_residual == bin_capacity {
        score += 45.0;
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
    }

    // Late in stream: prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill;

    // Slight bias toward bins below mean residual (consolidating emptier bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that likely cannot be reused by the next item.
    if next_item_size > 0 && post_residual > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score += 0.35 * gap;
        // Bonus if next item fits exactly in the post residual.
        if next_item_size as u32 == post_residual {
            score -= 18.0;
        } else if next_item_size as u32 <= post_residual {
            score -= 6.0;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Small residual penalty scaled by how unusable it is for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Time-horizon coupling: early in the stream, be conservative and favor
    // spreading load (higher residual); later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0 * tightness;
    score += (1.0 - progress) * 0.05 * (bin_residual as f64 - mean_residual);

    // Many open bins: discourage leaving large residuals idle; favor filling.
    let openness = open_bins_count as f64;
    score += 0.03 * openness * (post_residual as f64 / cap);

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, softened when current bin fit is bad
        // or when the item leaves awkward space in existing bins.
        let awkward = (post_residual as f64 / cap) > 0.5 && post_residual > 0;
        score += 40.0;
        if awkward { score -= 15.0; }
        if fitting_bins_count == 0 { score -= 60.0; }
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 { score -= 5.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Smooth non-linear coupling: quadratic & cubic polynomial in normalized post-residual modulated by stream progress
    let poly = norm_pr * norm_pr * (1.0 + norm_pr);
    score -= 40.0 * poly * progress;
    score += 25.0 * (1.0 - progress) * norm_pr * norm_pr;
    // Penalize dead space that cannot fit the next item (smooth interaction)
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = (next - pr).max(0.0) / cap;
        score += 30.0 * gap * gap * (1.0 - progress);
        // Reward when next item fits tightly (smooth falloff)
        let tight = 1.0 - (pr - next).abs() / cap;
        if pr >= next {
            score -= 20.0 * tight * tight * progress;
        }
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }
    // Mild penalty for spreading across many bins early
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;
    // New-bin candidate: discourage unless current bin fit is poor
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress) - 8.0 * (1.0 - norm_pr);
    }
    // Coupling with mean residual: prefer bins deviating from mean to balance residuals
    let dev = (mean_residual - pr).abs() / cap;
    score += 5.0 * dev * dev;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify post_residual into capacity fractions
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of bin left over

    // Penalize dead space that is small (unusable): residues in (0,10] are worst
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 25.0;
    } else if post_residual <= 30 {
        score += 8.0;
    }

    // Modulo classes on post_residual relative to capacity quarters
    let quarter = bin_capacity / 4;
    let class = (post_residual / quarter) as f64;
    score += class * 3.0;

    // Reward when next item fits into post_residual (good chaining)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0 + (next_item_size as f64) * 0.2;
        // extra bonus if next item nearly fills remaining space
        let nr = post_residual - next_item_size;
        if nr <= 5 {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use the leftover: penalize proportionally
        score += (next_item_size as f64 - post_residual as f64).min(40.0) * 0.5;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: keep it attractive only when fits are poor
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score = 70.0;
        // cheaper to open a new bin when many bins are already open and mean residual is high
        score -= (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(next_item_size) {
            score -= 10.0;
        }
        // if current fits would leave tiny dead space, opening a new bin is competitive
        if post_residual > 0 && post_residual <= 10 {
            score -= 55.0;
        }
    }

    // Mild penalty for spreading across many bins when mean residual is low
    score += (mean_residual - frac * 50.0) * 0.05;

    // Slight preference to fill bins earlier in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst.
    let dead_zone = 15.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        // Small unusable gap: heavy penalty that grows as gap shrinks.
        score += (dead_zone - post_residual as f64) * 8.0;
    }
    // Perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Reward tight fits relative to bin capacity.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * 12.0;
    }

    // Post residual must be able to host next item, else penalize.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 10.0;
        } else {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many bins open, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 30.0 + 4.0 * open_bins_count as f64;
    } else {
        score += 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins far from the mean residual
    // (consume the outliers, keep the pack balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.3;

    // Early in stream: be slightly more willing to open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if new_bin {
        score -= (1.0 - progress) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward residuals that will accommodate the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as u32) >= next_item_size {
            let gap = (post_residual as f64 - nx).abs();
            // Perfect two-step match: post_residual == next_item_size is ideal.
            score -= 18.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // Post-residual too small for next item: penalize dead space proportionally.
            score += 6.0 + 0.10 * (post_residual as f64);
        }
    }

    // Penalize post_residual that is unusably small relative to typical item sizes (min 1).
    if post_residual > 0 {
        score += 4.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave a bad fit.
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 5.0; // fresh bin still pairs well with next item
        }
    }

    // Contextual scaling: later in the stream, be slightly more conservative with new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    // Relative-to-mean adjustment: prefer bins with residual near the mean (typical fit).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can never be used by typical items (<= 80).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // unusable sliver
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_tight = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 10.0 * (1.0 - next_tight);
        } else {
            // Next item won't fit here; slight penalty for wasting the gap.
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when existing fits are poor
    // (post residual would be large) and many bins are already open.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
        // But if the current item is large, a fresh bin is attractive.
        score -= 0.15 * item_size as f64;
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    // Mild pressure to fill bins close to the current mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual, mildly discounted as stream progresses
    let mut score = pr * (1.0 + 0.5 * progress);

    // Reward tight fits (small post_residual relative to capacity) with smooth quadratic term
    let tightness = 1.0 - pr / cap;
    score -= 8.0 * tightness * tightness * tightness * (item_size as f64) / cap;

    // Penalize dead space: post_residual too small for typical future items
    if pr > 0.0 {
        let min_item = 1.0;
        let unusable = ((min_item - pr).max(0.0)) * 4.0;
        score += unusable;
        // Smooth penalty for residuals that can't fit the lookahead item
        if next_item_size > 0 {
            let gap = next_item_size as f64 - pr;
            if gap > 0.0 {
                score += gap * (0.3 + 0.7 * progress);
            } else {
                // Lookahead fits: reward synergy
                score -= 3.0 * (1.0 - pr / cap) * (1.0 - progress);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 6.0 * progress;
    }

    // Prefer bins with residuals below the mean (consolidating space)
    score += 0.15 * (pr - mean_residual);

    // New-bin candidate: make it attractive only when existing fits are poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when many items remain
        score = cap * (0.9 - 0.3 * progress);
        if next_item_size > 0 {
            // New bin is good if lookahead also fits nicely afterwards
            let after = cap - (item_size as f64) - (next_item_size as f64);
            if after >= 0.0 {
                score -= 2.0 * (after / cap);
            }
        }
        // Discourage opening when a last-chance bin exists
        if fitting_bins_count == 1 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity-fraction band does it fall in?
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;

    // Class A: post_residual in (0, quarter] -> small dead space, reward.
    if post > 0 && post <= quarter {
        score -= 18.0;
        // Perfect harmonic fit: post_residual divides capacity (mod classes)
        if bin_capacity % post == 0 {
            score -= 10.0;
        }
    }
    // Class B: (quarter, half] -> moderate, mild reward.
    else if post > quarter && post <= half {
        score -= 6.0;
    }
    // Class C: (half, 3*half) -> large residual, neutral-to-slight penalty
    else if post > half {
        score += 2.0;
    }

    // Dead space: post_residual too small for any plausible future item (items >= 1,
    // but small items are rare in packing streams); penalize tiny nonzero leftovers.
    if post > 0 && post < 5 {
        score += 25.0;
    }

    // Exact fit is ideal.
    if post == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // Next item fits: strong reward, scaled by how snugly it fits.
            let snug = (post - next_item_size) as f64 / cap;
            score -= 14.0 * (1.0 - snug);
        } else {
            // Next item won't fit here: penalize more if this bin was "wasted" on a big item.
            let gap = (next_item_size - post) as f64;
            score += 0.05 * gap;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post <= quarter {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive; discourage unless current fit is bad
        // or many bins already open (spread load).
        score = cap * 0.55;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Late in stream, prefer consolidating into open bins.
        score += 10.0 * (1.0 - progress);
        // If item nearly fills a fresh bin, opening is reasonable.
        if item_size as f64 / cap > 0.8 {
            score -= 12.0;
        }
        // If no open bin gives a decent fit (post_residual large elsewhere), allow new bin.
        if post_residual > half && fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Many open bins with high mean residual: reuse them instead.
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 8.0;
        }
    }

    // Modulo harmonic classes on item_size: items in "nice" classes (multiples of 10/25)
    // pair predictably; reward bins whose residual matches item's complement class.
    let complement = bin_capacity.saturating_sub(item_size);
    if bin_residual == complement {
        score -= 15.0;
    }

    // Tie-breaker: prefer tighter existing bins (small residual) mildly.
    score += 0.02 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space below minimum item size is pure waste
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Prefer bins whose residual is closest to item size (tight fit).
    score += 0.15 * (bin_residual as f64 - item_size as f64);

    // Lookahead: if next item fits in post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // likely dead space for the lookahead item
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage proliferation of bins.
    score += 0.5 * open_bins_count as f64;

    // Align with mean residual: bins far from mean treated mildly.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (fitting_bins_count == 1 && bin_residual - item_size < 10);
        if poor_fit {
            score -= 15.0;
        } else {
            score += 40.0 + 2.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact/near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 60.0 + 0.5 * chain_fit;
    } else if next_item_size > 0 {
        // Penalize leaving residual that is too small for the next item (dead space).
        score += 0.6 * (next_item_size as f64 - post_residual as f64).min(40.0);
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize the brand-new empty bin candidate unless the item is huge relative to
    // typical residuals or the fit elsewhere would be very poor.
    if bin_residual == bin_capacity {
        score += 80.0;
        if item_size > 60 {
            score -= 60.0; // big items deserve fresh bins
        }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 20.0;
        }
    }

    // Mild late-stream conservatism: reuse bins more aggressively as stream progresses.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: the smaller the post residual relative to capacity, the better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 20.0;

    // Penalize dead space: post residuals too small for the smallest plausible item (<=10)
    // are wasted; strongly discourage leaving fragments below the minimum item size.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 15 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post residual can still host the next item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here: reward proportionally to how well it would nest.
            let next_waste = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - next_waste / bin_capacity as f64);
        } else {
            // Next item cannot follow here: mild penalty scaled by how close it was.
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(40.0) * 0.3;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when existing
    // residuals are large (poor fits elsewhere) or many bins are already open and fragmented.
    if bin_residual == bin_capacity {
        let avg_poor = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins mildly by default...
        let mut new_bin_penalty = 15.0;
        // ...but reduce penalty when existing bins are fragmented (high mean residual)
        // or late in the stream where consolidation matters less.
        new_bin_penalty -= avg_poor * 20.0;
        new_bin_penalty -= progress * 10.0;
        // If the current item is huge, a fresh bin is often the cleanest choice.
        if item_size > 60 {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty.max(-5.0);
    }

    // Slight preference for filling bins that are already relatively full
    // (best-fit flavor reinforced via residual vs mean residual comparison).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual

    // Smooth polynomial coupling of post residual with stream progress.
    // Early on, prefer tight fits (low post residual) but keep some slack
    // for future items; late in the stream, drive post residual to zero hard.
    let mut score = post
        * (1.0 + 0.8 * progress * progress)      // tighten late
        - 6.0 * (1.0 - x) * x * (1.0 - progress); // reward mid-range slack early

    // Perfect fit bonus (smooth quadratic dip).
    score -= 12.0 * (1.0 - x) * (1.0 - x) * (0.5 + 0.5 * progress);

    // Lookahead: if the next item fits the post residual, reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = (nx <= post) as i32 as f64;
        let slack = ((post - nx) / cap).max(0.0);
        score -= 8.0 * fits * (1.0 - slack) * (1.0 - progress);
        // Penalize post residual that is too small for any plausible item.
        score += 5.0 * (x * (1.0 - x)) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty relative to mean residual: avoid creating outliers
    // that are much tighter than the average open bin.
    score += 0.15 * (post - mean_residual).max(0.0);

    // New-bin candidate: make it mildly unattractive unless open bins are bad.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition residual space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as i64; // 0..7 harmonic class of leftover space

    // Reward tight fits: post_residual near 0 is excellent.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    } else if post_residual <= 20 {
        score -= 30.0;
    }

    // Penalize dead space that no plausible item (1..=100) can reuse well.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    }

    // Lookahead coupling: reward if next item fits the post residual exactly / well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_gap = post_residual - next_item_size;
        score -= 40.0 + (next_gap as f64).min(30.0);
        if next_gap == 0 {
            score -= 150.0; // chain completion
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item cannot use leftover: leftover is likely dead
        score += 25.0;
    }

    // Harmonic class bonus: prefer bins whose post_residual lands on "nice" classes
    // (fractions like 1/4, 1/2 of capacity are reusable by mid-size items).
    score += match class {
        0 => -20.0,
        1 => -10.0,
        2 => -15.0,
        3 => 5.0,
        4 => -8.0,
        _ => 0.0,
    };

    // Modulo arithmetic: residuals divisible by common item sizes (5,10) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins when good fits exist,
    // but allow it when all open residuals are small relative to item.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 30.0; // big next item: fresh bin is fine
        }
    }

    // Stream progression: late in stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // Tie-break toward bins below mean residual (filling emptier bins first keeps spread even).
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // dead space too small for the smallest item
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        } else {
            score -= 15.0; // large usable residual is good
        }
    } else {
        score -= 50.0; // perfect fit is highly rewarded
    }

    // Prefer bins whose residual tightly matches the item (snug fit).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow.
        score += 30.0 + 4.0 * open_bins_count as f64;
        // But if no open bin fits well, new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item could use the post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // residual becomes dead space for next item
    }

    // Mean residual coupling: prefer bins near the mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 10.0;

    // Early stream: be slightly more conservative about filling bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits, but with leftover slack
            score -= 50.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item does not fit: dead space penalty grows with gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 200.0;
    }

    // Relative to mean residual: prefer bins that are more filled than average
    score += 0.3 * (mean_residual - bin_residual as f64).abs().signum() * (mean_residual - bin_residual as f64).abs();

    // Last chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large and no good fit exists
    if bin_residual == bin_capacity {
        score += 250.0;
        if item_size >= 60 {
            score -= 100.0;
        }
        // discourage new bin if an existing bin would leave small post_residual
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 40 {
            score -= 100.0;
        }
    }

    // slight preference for using existing bins as stream progresses
    score += 0.05 * (step_index as f64 / (total_items.max(1) as f64)) * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual strongly preferred.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 12.0;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 4.0; // usable pocket
    }

    // Lookahead: reward if the next item can fit into the post residual.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 8.0 + 0.05 * next_item_size as f64;
        } else {
            // penalize blocking the next item when alternatives exist
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 10.0 + 0.1 * item_size as f64;
    }

    // Compare against global mean residual: bins with residual far below mean
    // are "nearly full"; using them consolidates state.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // New-bin candidate handling: empty bin gets a moderate baseline so it wins
    // only when fits into open bins are poor.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.15 * open_bins_count as f64;
        // late in the stream, prefer consolidating rather than spreading
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Time horizon: early on, be more willing to open bins (spread); late,
    // squeeze into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Many open bins with slack: discourage adding yet another bin.
    if open_bins_count > 4 {
        score += 0.3 * open_bins_count as f64 * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    // Non-linear coupling: squared residual term, weighted by stream progress
    score += 2.0 * pr_norm * pr_norm * (0.5 + progress);
    // Reward tight fits (small post residual) with a smooth superlinear bonus
    score -= 4.0 * (1.0 - pr_norm).powi(3);
    // Penalize residuals that are too small to be useful later (dead space)
    score += 3.0 * pr_norm * (1.0 - pr_norm) * (1.0 - progress);
    // Lookahead coupling: smooth reward when next item fits the post residual
    if next_item_size > 0 {
        let fits = (pr >= next_item_size as f64) as f64;
        let tight = 1.0 - ((pr - next_item_size as f64).abs() / cap);
        score -= 2.5 * fits * tight * (0.3 + 0.7 * progress);
    }
    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - pr_norm);
    }
    // Crowd penalty: many open bins -> prefer filling existing ones
    score += 0.05 * open_bins_count as f64 * pr_norm;
    // Mean residual alignment: prefer bins near the mean residual
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: perfect fits and residuals that
    // match common item sizes (modulo classes) are valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward residuals that are "usable" — divisible into plausible item sizes.
    if post_residual >= 10 {
        let div10 = post_residual % 10 == 0;
        let div20 = post_residual % 20 == 0;
        if div10 { score -= 12.0; }
        if div20 { score -= 8.0; }
        // Harmonic fraction: residual as fraction of capacity; small usable fractions good.
        let frac = pr / cap;
        if frac < 0.2 {
            score -= 10.0 * (0.2 - frac);
        } else {
            score += 5.0 * (frac - 0.2);
        }
    } else if post_residual > 0 {
        // Dead space penalty for tiny unusable remainders (1..9).
        score += 25.0;
    }

    // Coupling with lookahead item: if next item fits exactly in post_residual,
    // strongly favor this bin (chained perfect packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 200.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
        // Harmonic pairing: next item leaves a multiple-of-10 remainder too.
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        // Next item cannot use this residual: penalize proportionally.
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate (fresh empty bin): penalize unless current bins are crowded
    // or the item is large and fits alone nicely.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 15.0 || open_bins_count == 0;
        let big_item = (item_size as f64) > 0.6 * cap;
        if crowded || big_item {
            score -= 60.0;
        } else {
            // Prefer filling existing bins; new bin only if residual waste is high.
            score += 30.0 + 0.5 * mean_residual;
        }
    }

    // Progress term: early in stream, tolerate more open bins; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (post_residual as f64 / cap);

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it's smaller than the minimum plausible item size.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) * 10 {
        // Gap too small for almost anything: severe penalty.
        score += 40.0 * (1.0 - (post_residual as f64) / 10.0);
    }

    // Reward tight fits: the smaller the post_residual relative to capacity, the better,
    // but only when the fit is "useful" (post_residual >= 10 or exactly 0).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.8 {
        score -= 15.0 * (fit_ratio - 0.8) / 0.2;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_gap = post_residual - next_item_size;
        if lookahead_gap < 10 {
            score -= 20.0;
        } else {
            score -= 8.0 * (1.0 - lookahead_gap as f64 / 100.0);
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins
    // and encourage consolidating into existing ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins already open.
        score += 10.0 + 6.0 * open_pressure;
        // But if the current item would leave a tiny gap in every existing bin anyway,
        // a fresh bin is fine — soften penalty when item is large relative to capacity.
        let large_item_bonus = item_size as f64 / bin_capacity as f64;
        score -= 12.0 * large_item_bonus;
    } else {
        // Existing bin: slight reward for using it when many bins are open.
        score -= 2.0 * open_pressure;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (fill the emptier-relative bins first, keeping large gaps available).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Progression: late in the stream, be more conservative about dead space
    // (fewer future items to fill gaps), so penalize large post_residuals more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        if post_residual == next_item_size {
            score -= 200.0;
        }
        // Penalize leaving a residual that is awkwardly smaller than next item
        if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 15.0;
        }
    }

    // Tightness reward: prefer small post_residual relative to bin
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * tightness;

    // Relative to mean residual: prefer bins already below-average residual (well-filled)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 80.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // As stream progresses, slightly discourage hoarding new bins
        score += 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fits (smaller post_residual) already favored.

    // Penalize dead space: residuals too small for the smallest plausible item
    let dead = if post_residual > 0 && post_residual < 10 { 60.0 } else { 0.0 };
    score += dead;

    // Strong reward for perfect fill
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // extra reward for near-exact two-item packing
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= 6.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        } else {
            // next item won't chain here; slight penalty proportional to slack
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes mean_residual across open bins.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 15.0;
        // opening a bin is worse when many open bins already have plenty of room
        score += mean_residual * 0.05;
        // but if only one bin fits and its fit is terrible, opening is acceptable
        if fitting_bins_count <= 1 && post_residual > 0 && (post_residual as f64) < item_size as f64 * 0.25 {
            score -= 20.0;
        }
        // early in stream, cheaper to open bins (build diversity)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    } else {
        // mild penalty for over-fragmenting: many open bins with small mean residual
        score += (open_bins_count as f64).ln().max(0.0) * 1.5;
    }

    // Penalize placing large items into nearly-full bins when a better option likely exists elsewhere
    if item_size >= 60 && bin_residual < 100 && bin_residual - item_size > 30 {
        score += 5.0;
    }

    // Coupling with global mean residual: bins deviating far below mean residual are "outliers";
    // placing here balances the pool.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.03;

    // Slight time-decay on lookahead effectiveness (later items benefit more from tight packing)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling: post_residual polynomial shaped by stream progress.
    // Early in stream: prefer tight fits mildly. Late: penalize wasted space strongly.
    let norm_pr = pr / cap;
    score += 20.0 * norm_pr * norm_pr * (1.0 + progress * 2.0);
    score -= 12.0 * norm_pr * (1.0 - progress) * (1.0 - progress);

    // Perfect fit reward (smooth, non-linear).
    if post_residual == 0 {
        score -= 25.0 * (1.0 + progress);
    }

    // Dead-space penalty: residual too small for likely future items.
    let dead = (1.0 - norm_pr).powi(2);
    score += 8.0 * dead * (1.0 - progress);

    // Last-chance bonus: only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize slightly so open bins are preferred unless very poor fit;
    // but early in stream, opening new bins is cheap.
    if bin_residual == bin_capacity {
        score += 5.0 + 30.0 * progress - 3.0 * (open_bins_count as f64).sqrt();
    }

    // Lookahead: if next item fits post_residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // Mean-residual coupling: prefer bins whose residual differs from mean (diversify sizes).
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are golden
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 25.0;
    } else {
        // modulo classes: residuals divisible by common item sizes are reusable
        for m in [10u32, 20, 25, 50] {
            if pr % m == 0 {
                score -= 8.0 + (pr as f64) * 0.05;
            }
        }
        // dead space penalty: tiny unusable slivers
        if pr < 10 {
            score += 30.0;
        }
    }

    // Coupling with lookahead: does post_residual fit next_item_size?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0 + (pr - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - pr) as f64 * 0.2;
        }
        // harmonic pair: item + next exactly fills bin
        if item_size + next_item_size == bin_residual {
            score -= 40.0;
        }
    }

    // Fraction-of-capacity classes
    let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill_frac * 15.0; // prefer fuller bins

    // Last-chance bin: strongly favor to avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening unless current bins are crowded
    if bin_residual == bin_capacity {
        score = 55.0 - (mean_residual / cap) * 40.0 - (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    // Late-stream pressure: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical items are wasted.
    // Treat gaps below a "dead zone" threshold as heavily penalized waste.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        // Dead space penalty grows as the gap shrinks toward zero.
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= tightness * 15.0;

    // Perfect fill is highly desirable.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize creating more bins when many are already open,
    // but reward consolidating into existing bins.
    if bin_residual != bin_capacity {
        score -= 8.0 + (open_bins_count as f64).sqrt() * 2.0;
    } else {
        // New-bin candidate: penalize opening a bin unless current bins are crowded.
        score += 25.0 + (open_bins_count as f64) * 3.0;
        // If mean residual across open bins is large, opening new bin is wasteful.
        score += mean_residual * 0.5;
    }

    // Lookahead: if the next item fits exactly in the resulting gap, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Gap can't host the next item: mild dead-space penalty scaled by gap.
        score += (post_residual as f64) * 0.3;
    }

    // Early in the stream, allow slightly more freedom to open bins (exploration).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score -= (1.0 - progress) * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits in the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain potential: subtract proportional to how well next item fits
            let chain_fit = (next_item_size as f64) / (post_residual as f64);
            score -= 60.0 * chain_fit;
            let second_residual = post_residual - next_item_size;
            if second_residual == 0 {
                score -= 400.0;
            }
        } else {
            // Next item doesn't fit: penalize dead space relative to next item
            let gap = (next_item_size - post_residual) as f64;
            score += 0.8 * gap;
        }
    }

    // Penalize unusable small residuals (< min item size 1..100 => keep threshold modest)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Relative to mean residual: prefer bins that are already more filled (smaller residual)
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless all fits are bad
    if bin_residual == bin_capacity {
        score += 90.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
    }

    // Late in stream: consolidate into open bins more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 40.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: minimize wasted space quadratically.
    let tight = (bin_residual - item_size) as f64;
    score += 0.35 * tight * tight / bin_capacity as f64;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).recip();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bins are more acceptable early or when few alternatives exist.
        score += 20.0 * scarcity * (1.0 - 0.5 * progress) - 5.0 * (1.0 - progress);
        // If item is large, new bin is natural; soften penalty.
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    // Lookahead: favor bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * (next_item_size as f64);
    }
    // Penalize leaving a residual that is too small for the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let dead = (next_item_size - post_residual) as f64;
        score += 0.15 * dead;
    }

    // Prefer filling bins with larger residuals (consolidate waste) relative to mean.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild pressure to reduce number of open bins as stream progresses.
    score += 0.01 * open_bins_count as f64 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, small residuals matter less; late in the stream, punish them harder.
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (1.0 + 2.0 * progress) + pr_norm * progress * progress;
    score += 25.0 * coupling;

    // Reward tight fits (small post_residual) with a smooth inverse-ish term.
    let tight = 1.0 - pr_norm;
    score -= 15.0 * tight * tight;

    // Lookahead: if the next item fits into the post_residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - gap) * (1.0 + progress);
        } else {
            // penalize leaving a residual that is useless for the next item,
            // scaled by how far off it is (smoothly).
            let miss = (nxt - pr) / cap;
            score += 8.0 * miss * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using the final fitting bin to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + 0.5 * progress);
    } else if fitting_bins_count > 1 {
        // mild preference among multiple fits toward better fill ratio.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Penalize opening a brand-new bin, more so as the stream progresses.
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        // slight preference for bins that are already well loaded (below mean residual).
        score += 3.0 * (mean_residual - pr) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Perfect / near-perfect fit: big reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Dead-space penalty: residuals that nothing (min size 1..100) can reuse well.
    // Class residuals into harmonic bands via integer division thresholds.
    let band = post_residual / 10; // 0..10 bands
    match band {
        0 => { score -= 30.0; }        // 1..9: nearly full, excellent
        1 => { score -= 10.0; }        // 10..19: good small-item slot
        2 | 3 => { score += 5.0; }     // 20..39: mediocre
        4 | 5 => { score += 15.0; }    // 40..59: half-empty bin
        _ => { score += 25.0; }        // 60+: wasteful placement
    }

    // Lookahead coupling: reward if next item fits harmonically in post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size <= post_residual {
            // exact or tight reuse of the leftover
            let leftover = post_residual - next_item_size;
            if leftover == 0 {
                score -= 150.0;
            } else if leftover <= 10 {
                score -= 40.0;
            } else {
                score -= 10.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += 0.3 * (pr - nx).max(0.0);
        }
    }

    // Fractional coupling: penalize residuals in awkward fractions of capacity
    // (e.g., ~1/3 or ~1/2 full leftovers are hard to fill exactly).
    let thirds = (frac * 3.0).round() / 3.0;
    if (frac - thirds).abs() < 0.02 && frac > 0.05 && frac < 0.95 {
        score += 20.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: keep neutral-ish baseline so it's chosen only
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = cap * 0.5 + 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 40.0; // big next item favors fresh bin
        }
    }

    // Mild pressure toward consolidating bins when many are open.
    score += open_bins_count as f64 * 0.05 * frac;

    // Slight drift over the stream: later items favor tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (pr * 0.1);

    // Mean-residual alignment: prefer bins whose residual is near the mean
    // (keeps a balanced pool of reusable space).
    score -= 0.2 * (mean_residual - pr).abs().min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item if it fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap that can't host next item: penalize proportionally.
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Prefer bins with small residual relative to mean (tighter bins first).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        // Base cost of a new bin grows with congestion.
        score = 100.0 + (open_bins_count as f64) * 8.0;
        // But if no existing bin fits well, opening may be fine:
        if fitting_bins_count == 0 {
            score -= 90.0;
        }
        // Late in stream, avoid proliferation less aggressively.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 20.0;
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 30.0;
        }
    }

    // Mild pressure to keep open_bins_count low overall.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
