}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward bins that are well-utilized by this placement (tight fit bonus).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Lookahead coupling: strongly favor bins where the NEXT item also fits
    // in the resulting residual (chained packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + next_item_size as f64 * 0.1;
        } else {
            // Slight penalty if this placement strands the next item.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; penalize
    // it more when other bins already fit, less when fits are scarce.
    if bin_residual == bin_capacity {
        score += 25.0 - 5.0 * fitting_bins_count as f64;
    }

    // Global state coupling: penalize leaving residual above the mean
    // residual across open bins (creates outlier dead space).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Dynamic time horizon: as the stream progresses, waste matters more,
    // so scale the score slightly upward over time.
    let t = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) - 0.5 * norm_pr * progress;
    score += 6.0 * poly;
    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 * (1.0 - (next_item_size as f64 / cap)) * (1.0 - progress);
    }
    // Penalize small dead space unless perfectly tight
    if post_residual > 0 {
        score += 2.0 * (1.0 - pr / (pr + item_size as f64)) * (0.5 + progress);
    } else {
        score -= 4.0;
    }
    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - progress);
    }
    // New-bin candidate: mild penalty, stronger late in the stream
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 2.0;
    }
    // Coupling with mean residual across open bins
    score += 0.3 * (pr - mean_residual) * (0.5 + 0.5 * progress);
    // Slight penalty for many open bins to discourage spreading
    score += 0.05 * open_bins_count as f64 * progress;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exponential bonus for small post-residual
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Harmonic class of post_residual modulo 10: dead space that only
    // tiny items (1..10) can fill is worse than space divisible into
    // common size chunks.
    let dead_class = post_residual % 10;
    if dead_class != 0 {
        score += dead_class as f64 * 0.8;
    }

    // Capacity fraction coupling: post_residual as fraction of capacity
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize leaving a large-but-awkward residual (> half capacity wasted)
    if frac > 0.5 {
        score += (frac - 0.5) * 40.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, prefer tighter fits more aggressively
        score += post_residual as f64 * 0.15;
    }

    // New-bin candidate handling: empty bin gets baseline cost so it's
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 55.0 + open_bins_count as f64 * 2.0;
    } else {
        // Prefer already-open bins slightly to avoid bin proliferation
        score -= 8.0;
    }

    // Mean residual coupling: if this bin is much tighter than average,
    // reward filling it (reduce fragmentation).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Stream progression: late in stream, waste less (fewer chances to fix)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (11.0 - post_residual as f64);
    } else if post_residual > 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: penalize if leftover gap can't fit the next item,
    // reward if it can exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
