    }

    // Last-chance bin pressure: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += (open_bins_count as f64) * 0.5;

    // New-bin candidate: residual == capacity. Make it attractive only when
    // item is large or existing fits are poor.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64;
        if item_size >= 50 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        score += (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Next item fits snugly into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        score -= 12.0 * fit_ratio;
    } else if next_item_size > post_residual {
        // Dead space relative to lookahead item
        score += 5.0 + 0.1 * (next_item_size - post_residual) as f64;
    }

    // Compare residual against mean residual across open bins
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize tiny unusable residuals
    if post_residual < 10 {
        score += 8.0;
    }

    // Slight preference to fill existing bins over opening new ones as stream grows
    if bin_residual == bin_capacity {
        score += 10.0 + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tight_bonus = (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;
    score += tight_bonus;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize creating dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward;
    // otherwise penalize wasting space the next item could have used.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else if (bin_residual as f64) >= next_item_size as f64 && (post_residual as f64) < next_item_size as f64 {
            score += 6.0;
        }
    }

    // Mean residual coupling: placing into a bin far below mean residual
    // helps balance open bins; discourage using bins already tight when
    // other bins have slack.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual - 5.0 {
        score += 4.0;
    } else if residual_f > mean_residual + 5.0 {
        score -= 3.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity equal
    // to (capacity - item). Make it attractive only for large items or
    // when no other bin fits well / it's the last chance.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Large items: opening a fresh bin is fine (they leave big residual anyway).
        // Small items: heavily penalize unless it's the only fitting option.
        let waste_penalty = (bin_capacity - item_size) as f64 * 1.2;
        let large_item_relief = item_frac.powi(2) * 120.0;
        let last_chance_relief = if fitting_bins_count == 1 { 30.0 } else { 0.0 };
        let early_stream_relief = (1.0 - progress) * 10.0;
        score += waste_penalty - large_item_relief - last_chance_relief - early_stream_relief;
    }

    // Mild penalty for many open bins: encourage consolidation early,
    // relax later in the stream.
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    // Slight preference for filling fuller bins as stream progresses.
    score -= (residual_f / bin_capacity as f64) * progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual, with smooth polynomial coupling to stream progress.
    let mut score = post * (1.0 + 0.6 * progress * progress);

    // Quadratic dead-space penalty: small residuals are increasingly wasteful.
    score += 12.0 * norm_post * norm_post * (1.0 - norm_post);

    // Tightness reward: subtract for near-perfect fits, smoothly scaled.
    let tightness = 1.0 - norm_post;
    score -= 8.0 * tightness * tightness * tightness;

    // Lookahead coupling: reward if next item fits smoothly into post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 6.0 * (1.0 - gap / cap).max(0.0) * (1.0 - progress);
        if nxt > post {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Penalize opening new bins when many bins have slack (smooth pressure term).
    let mean_norm = mean_residual / cap;
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * mean_norm * (1.0 + progress);
    } else {
        score -= 5.0 * mean_norm;
    }

    // Mild penalty for bin proliferation.
    score += 0.3 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction buckets (integer division thresholds).
    let frac = post_residual as f64 / bin_capacity as f64;

    // Dead-space penalty: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        // Reward roomy residuals, with diminishing (harmonic) returns.
        score -= 40.0 / (post_residual as f64).sqrt();
    }

    // Harmonic class via integer division: post_residual bucketed by
    // multiples of 25 (quarter-capacity classes).
    let class = post_residual / 25;
    score -= 6.0 * class as f64;

    // Modulo arithmetic on post_residual: residuals divisible by 5 or 10
    // are "cleaner" fits for typical item granularities.
    if post_residual % 10 == 0 {
        score -= 4.0;
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    } else {
        score += 1.5;
    }

    // Lookahead coupling: if the next item fits exactly or nearly into the
    // post-residual, this bin is doubly valuable.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 12.0 / (1.0 + gap as f64);
        } else {
            // Next item cannot use this residual: mild penalty proportional
            // to wasted harmonic class.
            score += 3.0 * ((next_item_size - post_residual) / 25) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bins are penalized unless the
    // current bin fit is genuinely poor (large post-residual mismatch).
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
        // But allow new bins early in the stream or when mean residual is low.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        if mean_residual < 15.0 {
            score -= 8.0;
        }
    }

    // Prefer filling bins that are already relatively full (small residual
    // relative to mean): tight-packing pressure.
    if (bin_residual as f64) < mean_residual {
        score -= 0.3 * (mean_residual - bin_residual as f64);
    }

    // Late-stream pressure: as the stream nears its end, avoid opening
    // bins that will waste space; prefer tight fits even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Reward bins whose residual matches next item size (lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bonus: only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Pressure from many open bins: favor filling existing bins over opening new ones.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: penalize opening a new bin unless existing bins are crowded.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * -0.4;
    }

    // Slight progress pressure: later in stream, prefer consolidation.
    score += (step_index as f64 / total_items.max(1) as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * (1.0 + 0.5 * (post_residual as f64 / bin_capacity as f64));

    // 2-step lookahead: reward bins whose post_residual can fit the next item exactly well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward: post_residual leaves room for next item; better if slack is small.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize dead space that the next item cannot use,
            // scaled by how much space is wasted.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.8 * dead;
        }
    } else {
        // Last item: just prefer tightest fit.
        score -= 5.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" already;
    // placing here keeps loose bins available for future awkward items.
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; the lookahead/dead-space terms
        // of existing bins will dominate when fits are bad.
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But if the next item is huge, a fresh bin is fine.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Slight stream-progression term: early on, be more willing to open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 55.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // tiny unusable slivers are wasted capacity
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere else or residual space is very tight.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit_pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let fragmented = (mean_residual - post_residual as f64).abs() / (bin_capacity as f64);
        // Cost of a fresh bin grows with how many bins are already open and how early we are.
        score += 70.0 + 0.6 * open_bins_count as f64 + 50.0 * (1.0 - progress);
        // But discount the penalty when other bins fit badly or are highly fragmented.
        score -= 65.0 * poor_fit_pressure + 30.0 * fragmented;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item cannot follow here; mild penalty scaled by how close it was.
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 * (1.0 - (gap / (bin_capacity as f64)).min(1.0));
        }
    }

    // Prefer placing into bins whose residual deviates from the mean
    // (consolidate fragmentation toward a common residual shape).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slight preference for using fuller bins early (best-fit-like pressure over time).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let prog = t * t * (3.0 - 2.0 * t); // smoothstep-like progression
    score += 6.0 * norm_pr * norm_pr * (0.5 + prog) * cap * 0.05;

    // Reward tight fits, more so as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.4 + 0.6 * t);

    // Penalize dead space that can't fit a lookahead item
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 8.0 * (1.0 - t) * (next_item_size as f64 - pr) / cap * 10.0;
    } else if next_item_size > 0 {
        score -= 5.0 * t;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild pressure against spreading across many open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Pull toward mean residual to keep bins balanced
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: prefer opening early, discourage late unless very tight fit exists
    if bin_residual == bin_capacity {
        score += 10.0 * t + 4.0 * (1.0 - t);
        if next_item_size as f64 >= 0.9 * cap {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: maximal reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit classes: post_residual in small harmonic bands are valuable
    let pr = post_residual;
    if pr <= 10 {
        score -= 60.0;
    } else if pr <= 20 {
        score -= 30.0;
    } else if pr <= 30 {
        score -= 10.0;
    }

    // Harmonic class of item size (mod 10): items leaving residuals that other
    // common size classes can fill are preferable. Reward when post_residual
    // is congruent to a plausible item size (multiple of 10 or small).
    let harmonic = pr % 10;
    if harmonic == 0 {
        score -= 15.0;
    } else if harmonic >= 5 {
        score += 5.0;
    }

    // Dead-space penalty: residual too small for any item (min size 1, but
    // practically below ~10 is nearly dead given typical distributions).
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here anyway; mild penalty for wasting large residual
            score += (next_item_size - pr) as f64 * 0.1;
        }
    }

    // Prefer filling bins with large residual when many bins are open
    // (reduce bin count pressure), but keep mean-residual balance.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 {
        score -= (bin_residual as f64 - mean_residual) * 0.3 * (1.0 - progress);
    }

    // New-bin candidate (empty bin): penalize unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 120.0;
        // but if no open bin gives a tight fit, opening fresh is attractive:
        if pr >= 0 && item_size as f64 / cap < 0.2 && fitting_bins_count <= 1 {
            score -= 100.0;
        }
        // early in stream, opening bins is cheaper
        score -= 40.0 * (1.0 - progress);
    }

    // Fractional capacity coupling: reward placing large items into low-fill bins
    let fill = 1.0 - bin_residual as f64 / cap;
    score += fill * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0 + (dead_threshold - post_residual as f64) * 3.0;
    }
    if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to item size.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * item_size as f64 * 0.8;

    // Penalize bins whose residual deviates badly from the mean (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + next_item_size as f64 * 0.3;
    } else if next_item_size > 0 {
        // Next item won't fit here: slight penalty for leaving an awkward gap.
        score += (next_item_size as f64 - post_residual as f64) * 0.1;
    }

    // New-bin candidate: attractive early in the stream or when no good fit exists,
    // but discouraged as open-bin count grows.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_bonus = 40.0 - open_bins_count as f64 * 2.0 + progress * 10.0;
        // A new bin leaves full residual; only attractive if the fit elsewhere is poor.
        score -= new_bin_bonus;
        if item_size as f64 > bin_residual as f64 * 0.8 {
            score -= 10.0; // large item: fresh bin is natural
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Exact-fit rewards
    if post_residual == 0 {
        score -= 1000.0;
    }
    // 2-step lookahead: perfect match with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // next item fits comfortably; mild bonus scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // dead space relative to next item: penalize proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += 1.5 * waste;
        }
    }

    // Penalize small unusable residuals (below typical minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    } else if post_residual > 0 {
        // favor tight fits: smaller post_residual relative to bin_residual
        let tightness = 1.0 - post / (bin_residual as f64).max(1.0);
        score -= 40.0 * tightness;
    }

    // Relative to mean residual: prefer bins whose leftover deviates favorably
    score += 0.5 * (post - mean_residual);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize moderately, but allow opening when the
    // current item would leave a very poor residual in any open bin
    if bin_residual == bin_capacity {
        let mut penalty = 120.0;
        if post_residual < 10 && next_item_size > post_residual {
            penalty -= 200.0; // opening fresh is better than creating dead space
        }
        penalty += 2.0 * open_bins_count as f64 * (0.3 + step_index as f64 / total_items.max(1) as f64);
        score += penalty;
    }

    // Mild late-stream preference to consolidate into existing bins
    score += 0.05 * (post_residual as f64) * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize bins whose residual becomes too small to be useful
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: prefer keeping it closed unless open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        score += 15.0 + 2.0 * crowd;
        // but allow opening when mean residual is high (bins are full)
        score -= (mean_residual / bin_capacity as f64) * 20.0;
    }

    // Time horizon: early in the stream, be conservative (penalize spreading);
    // late in the stream, pack aggressively into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins with residual close to item_size (minimize waste)
    let waste = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * waste;

    // Penalize placing large items into nearly-full bins if other options exist
    if item_size > 50 && bin_residual < 60 && fitting_bins_count > 1 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear polynomial shaping.
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling with stream progress: later in stream, tighten fit preference.
    score += progress * 10.0 * norm_pr * (1.0 - progress);

    // Penalize bins whose residual deviates from mean residual (fragmentation signal).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // Reward near-perfect fits smoothly (quadratic decay of waste).
    score -= 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (bin_residual as f64 / cap);

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 / cap) * norm_pr;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.5 * (open_bins_count as f64).ln() * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common item sizes (1..100 unknown
    // distribution, but classic "nice" sizes cluster around multiples of 10 and halves of 100).
    // Reward residuals that are 0 (perfect fit) or that pair with the lookahead item.
    if post_residual == 0 {
        score -= 1000.0; // perfect closure
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // lookahead fits exactly: strong reward, scaled by exactness of the pair
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 - gap.min(60.0);
        if gap == 0.0 {
            score -= 200.0; // item + next item closes bin perfectly
        }
    } else if next_item_size > post_residual {
        // next item cannot use this residual; penalize dead space more harshly
        // when residual falls in "awkward" harmonic classes (small odd remainders)
        let r = post_residual % 10;
        score += match r {
            0 => 0.0,
            5 => 4.0,
            _ => 10.0 + (r as f64),
        };
    }

    // Integer-division thresholds: classify residual into usable capacity fractions
    let quarter = bin_capacity / 4;
    if post_residual >= quarter && post_residual <= bin_capacity / 2 {
        score -= 8.0; // sweet spot: still useful for medium items
    } else if post_residual < 10 && post_residual > 0 {
        score += 25.0; // sliver, nearly dead
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a fresh bin when existing residuals are
    // badly fragmented (mean residual low relative to item) and many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // reward opening new bin when open bins are crowded and stream is early/mid
        let openness = (open_bins_count as f64).ln_1p();
        score = 30.0 + openness * 10.0 - fragmentation * 20.0 - progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative, must open
        }
    } else {
        // mild penalty for spreading across too many bins when mean residual is high
        if mean_residual > 40.0 && post_residual > 0 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A gap is "dead" if it's too small for the smallest plausible item (1..100 range,
    // assume min item ~10 from classic streams, but scale with observed mean residual).
    let min_item = 10.0f64;
    if (post_residual as f64) < min_item && post_residual > 0 {
        score += 40.0; // dead space created -> strong penalty
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight fit reward: penalize proportionally to wasted fraction of residual
    let tightness = post_residual as f64 / bin_residual as f64; // 0 = perfect, 1 = loose
    score += 25.0 * tightness;

    // Open bins pressure: discourage spreading when many bins are open
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave dead space
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // but allow new bin if placing here would create dead space
        if post_residual > 0 && (post_residual as f64) < min_item {
            score -= 60.0;
        }
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // If next item cannot fit post-residual but could fit elsewhere, mild penalty
    if next_item_size > post_residual && post_residual > 0 && (post_residual as f64) < min_item {
        score += 10.0;
    }

    // Mean residual coupling: if this bin is far below mean residual, it's a good filler
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Slight progression bias: early on, prefer consolidating (lower post residual)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item fill
        } else if post_residual < next_item_size {
            // next item cannot follow here: post_residual is dead space unless tiny
            score += 0.8 * diff;
        } else {
            // next item fits afterward: mild reward proportional to closeness
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        }
    } else {
        // last item: prefer tightest fit only
        score += 0.0;
    }

    // Reward tight fits relative to bin capacity (small post_residual is good,
    // but avoid unusable slivers: penalize post_residual in [1, 9]).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 15.0; // sliver penalty
    }

    // Compare against mean residual of open bins: placing into a bin whose
    // residual is below mean (already partially filled) is preferable.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no good existing option exists. Penalize empty-bin choice mildly, but
    // cancel the penalty when the new bin enables a perfect 2-item fill.
    if bin_residual == bin_capacity {
        let mut new_bin_bonus = -5.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let pair_leftover = bin_capacity - item_size - next_item_size;
            if pair_leftover == 0 {
                new_bin_bonus = -55.0; // fresh bin fits item + next item exactly
            }
        }
        score += new_bin_bonus;
        // With many open bins, discourage proliferation unless lookahead is perfect
        if open_bins_count > 3 && new_bin_bonus > -50.0 {
            score += 10.0;
        }
    }

    // Slight stream-position adaptation: early on, be conservative about
    // spreading items (keep bins tight); late, accept looser fits to close bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tight = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tight).powi(3);

    // Penalize creating dead space that likely cannot fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.15 * (post_residual as f64);
    }
    // Reward when the leftover can still accommodate the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins
    // can already fit the item or mean residual is large.
    if bin_residual == bin_capacity {
        score += 20.0;
        score += 3.0 * fitting_bins_count as f64;
        score += 0.5 * open_bins_count as f64;
        score += 0.05 * mean_residual;
    }

    // Prefer filling bins with large residuals as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.1 * (bin_residual as f64 - mean_residual) * (1.0 - progress);

    // Slight bonus for packing into already-open bins vs spreading.
    if bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = item_size as f64 / cap;
    let norm_post = post_residual as f64 / cap;
    let norm_res = bin_residual as f64 / cap;

    // Tight-fit reward: quadratic in fill fraction, scaled by stream progress
    let tight = (fill * fill) * (1.0 + progress);
    score -= 18.0 * tight;

    // Penalize large post-residual non-linearly (dead space grows quadratically)
    score += 4.0 * norm_post * norm_post * cap;

    // Smooth interaction: post_residual vs mean residual deviation
    let dev = norm_post - mean_residual / cap;
    score += 6.0 * dev * dev;

    // Lookahead coupling: reward residual that can host the next item, smooth decay
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        let ratio = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * ratio * (1.0 - ratio) * (1.0 + progress);
    } else if next_item_size > 0 {
        // residual too small for next item: mild penalty growing with progress
        score += 3.0 * progress * norm_post;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + progress);
    } else if fitting_bins_count > 1 {
        // competition among fitting bins: mild crowding penalty
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Smooth open-bin pressure: discourage spreading when many bins are open
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += 8.0 * pressure * norm_post;

    // New-bin candidate handling: empty bin gets base cost, softened late in stream
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.25 * progress) + 12.0 * (1.0 - fill);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible into large chunks are valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize residuals in awkward "dead zone" classes: 1..=9 or 21..=29 style gaps.
    let class = post_residual % 10;
    if post_residual > 0 {
        if class != 0 && class > 5 {
            score += 6.0 - class as f64; // awkward small tail
        } else if class != 0 {
            score -= class as f64 * 0.5; // somewhat usable tail
        }
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Fraction-of-capacity coupling: prefer residual well below half capacity.
    let frac = pr / cap;
    if frac < 0.5 {
        score -= 5.0 * (0.5 - frac);
    } else {
        score += 4.0 * (frac - 0.5);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            score -= 8.0 - (leftover as f64).min(8.0);
        } else {
            score += 3.0; // next item can't follow here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(4.0);
    }

    // New-bin candidate: make it moderately attractive only when open bins are crowded
    // or the fit here is terrible.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        score = 30.0 + 25.0 * (1.0 - crowding) - 10.0 * (1.0 - frac);
        if fitting_bins_count <= 1 {
            score -= 20.0; // no real alternative
        }
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 10.0; // fresh bin fits next item too
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the smallest plausible
    // item are wasted forever. Penalize them super-linearly.
    let dead_threshold: f64 = 9.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * 6.0;
    }

    // Reward tight fits strongly (near-zero post residual).
    if pr == 0 {
        score -= 25.0;
    } else if pr <= 4.0 {
        score -= 12.0;
    }

    // Fit quality relative to bin: prefer bins where item fills a large
    // fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open
    // and the fit is acceptable.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = 18.0 + 12.0 * (1.0 - progress) + (open_bins_count as f64).sqrt() * 2.0;
    if bin_residual == bin_capacity {
        // Candidate new bin: high base cost, reduced if the current fit
        // options are poor (large post residual on all bins).
        score += new_bin_penalty;
        // If the item would leave a huge gap in any existing bin, opening a
        // fresh bin becomes more attractive.
        if post_residual > 0 && post_residual < 40 && fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Lookahead: if next item is large, a fresh bin is useful.
        if next_item_size >= 60 {
            score -= 6.0;
        }
    } else {
        // Existing bin: mild bonus for keeping residual near the next item
        // size so the lookahead can also fit.
        if next_item_size > 0 && post_residual >= next_item_size as u32 {
            let slack = (post_residual - next_item_size as u32) as f64;
            score -= 4.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        }
        // Penalize leaving residual slightly below the next item size
        // (unusable for lookahead but above dead threshold).
        if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 5.0;
        }
        // Slight preference for bins with below-mean residual (consolidate).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Global pressure: as open bin count grows, tighten selection.
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact-ish match with the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.6; // penalize mismatch between leftover and next item
        // Perfect chaining bonus: next item exactly fills the bin
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            // next item fits with small leftover -> good
            let rem_after_next = post_residual - next_item_size;
            if rem_after_next <= 10 {
                score -= 12.0;
            }
        }
    }

    // Tight fit reward: small post residual is good (already base score), extra bonus
    if post_residual < 10 {
        score -= 8.0;
    } else if post_residual > 50 {
        // large leftover: wasteful unless it matches next item (handled above)
        score += 6.0;
    }

    // Compare against mean residual: prefer bins with less residual than average (denser bins)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when existing bins fit well
    if bin_residual == bin_capacity {
        // new-bin candidate: base score is capacity; adjust
        score -= 10.0; // slight preference for fresh bin early on
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0; // later in stream, prefer filling open bins
        if fitting_bins_count > 0 {
            score += 15.0; // discourage new bin when alternatives exist
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big next item: keep space free
        }
    }

    // Many open bins: consolidate into fewer bins
    if open_bins_count > 3 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit pressure: reward tight fits.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize dead space that no future item (1..=100) can use.
    if post_residual > 0 {
        let max_usable = post_residual.min(100) as f64;
        let waste = post_residual as f64 - max_usable;
        score += waste * 8.0;
        // Small residuals (<10) are near-useless if items are 10..80; mildly penalize.
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + 0.3 * next_item_size as f64;
        } else {
            // Next item won't chain here; penalize leaving awkward gaps.
            score += 10.0;
            // Bonus if post_residual pairs with typical small items.
            if post_residual >= 10 && post_residual <= 40 {
                score -= 5.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly (large post_residual) or many bins are open
    // with high mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let early = (step_index as f64) / (total_items.max(1) as f64);
        let fragmentation = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // Base cost of a new bin; discount early in the stream and when fragmented.
        score += 60.0 - 40.0 * (1.0 - early) - 30.0 * fragmentation;
        // If item is large relative to capacity, new bin keeps flexibility.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        // Don't open new bins when a decent fit exists elsewhere.
        if fitting_bins_count > 0 && post_residual <= 20 {
            score += 80.0;
        }
    }

    // Prefer filling bins that are already small-residual (consolidation).
    if bin_residual != bin_capacity {
        score -= 0.1 * (bin_capacity as f64 - bin_residual as f64);
    }

    // Late-stream urgency: close out bins rather than spreading.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    if progress > 0.7 && bin_residual != bin_capacity {
        score -= 20.0 * progress;
    }

    // Mild penalty for accumulating too many open bins.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: waste after placement
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits (low post_residual) strongly; later, relax slightly
    let progress_weight = 1.0 + 0.5 * progress * progress;
    score += 40.0 * norm_pr * norm_pr * progress_weight;

    // Penalize leaving residual that is small but unusable (dead space),
    // scaled smoothly by next item size
    let next_fit = (next_item_size as f64 / cap).min(1.0);
    let dead_space = norm_pr * (1.0 - norm_pr).max(0.0);
    score -= 30.0 * dead_space * next_fit * (1.0 - progress);

    // Reward filling bins nearly full (smooth bell around full utilization)
    let fullness = 1.0 - norm_pr;
    score -= 25.0 * fullness * fullness * fullness;

    // Last-chance bin: strongly favor using it to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild penalty for many open bins relative to progress (encourage consolidation)
    score += 0.5 * open_bins_count as f64 * (0.3 + progress);

    // Mean residual coupling: prefer bins whose residual is below mean (tighter than average)
    score += 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod capacity fraction classes
    let post = post_residual;
    let class = match post {
        0 => 0.0,                 // perfect fit
        1..=5 => -6.0,            // near-perfect: dead space tiny
        6..=15 => 2.0,            // awkward small gap
        16..=30 => 0.0,           // usable medium gap
        31..=50 => -1.5,          // half-ish bin: good for medium items
        51..=70 => -1.0,
        _ => -0.5,
    };
    score += class;

    // Integer-division thresholds: how well next_item_size fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post {
            // lookahead fits perfectly or tightly
            if post - next_item_size <= 5 {
                score -= 8.0;
            } else if post - next_item_size <= 15 {
                score -= 3.0;
            } else {
                score -= 1.0;
            }
        } else {
            // lookahead won't fit here; penalize more if gap is just below next item
            let gap = (next_item_size - post) as f64;
            score += 1.0 + (gap / cap) * 6.0;
        }
    } else {
        // last item: prefer minimal residual, strongly
        score -= 5.0 * (1.0 - post as f64 / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current fit is bad or bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / cap * 4.0);
        // base penalty so open bins win unless fit is poor
        score += 12.0;
        // discount new bin when many open bins with small residuals (fragmented state)
        score -= crowding * 0.5;
        // late in stream, small residual targets matter less; slightly prefer fresh bins
        score -= progress * 2.0;
        // if item is huge, fresh bin gives max post space anyway
        score -= (item_size as f64 / cap) * 3.0;
    } else {
        // prefer bins with lower residual (tighter packing) mildly
        score += (bin_residual as f64 / cap) * 2.0;
        // reward filling bins close to full to close them out
        if post <= 10 {
            score -= 4.0;
        }
    }

    // modulo harmonic bonus: post_residual divisible classes
    if post % 10 == 0 && post > 0 {
        score -= 1.0; // round residual classes are reusable
    }
    if post % 2 == 1 && item_size % 2 == 1 {
        score += 0.5; // odd+odd leaves odd gap, slightly worse
    }

    // mean residual coupling: when mean residual is high, prefer tight fits less aggressively
    score += (mean_residual / cap) * (bin_residual as f64 / cap) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item are worthless — penalize them heavily.
    let dead_threshold: u32 = 10; // smallest possible item size
    if post_residual < dead_threshold && post_residual > 0 {
        score += 40.0; // dead space: unusable forever
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit: bin fully closed
    } else {
        // Usable residual: reward proportionally to tightness of fit.
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 15.0 * tightness;
    }

    // Penalize residuals that can't fit the lookahead item but could have.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0; // leaves room for the next item
    }

    // Open-bin pressure: discourage spreading items across many bins when
    // a decent fit exists; encourage using existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += 0.4 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when all open bins fit poorly
    // (large dead space would be created) or few bins are open early on.
    if bin_residual == bin_capacity {
        let worst_gap = mean_residual.min(post_residual as f64);
        let poor_fits = (mean_residual - item_size as f64).abs() < 12.0;
        if poor_fits && open_bins_count > 2 {
            score -= 12.0; // opening fresh bin beats forcing a bad fit
        } else {
            score += 10.0 + 3.0 * open_bins_count as f64;
        }
        let _ = worst_gap;
    }

    // Slight preference for bins whose residual is close to mean (balance).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when post_residual exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post-residual can still host the next item: mild reward, tighter is better.
        score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space relative to next item: penalize proportionally.
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Prefer bins whose residual is tight relative to the mean residual.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Slight penalty for opening a new bin when many bins are already open.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (waste minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Penalize large dead space relative to capacity, non-linearly.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 50.0 * waste_ratio * waste_ratio;

    // Lookahead coupling: bonus if the next item fits into this bin's post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space unusable by the next item is worse if the dead space is large.
        score += 0.3 * (post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when global
    // residuals are fragmented (mean residual low relative to item) or too many bins
    // barely fit the item (risk of bad fits).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with how many bins already exist.
        let mut new_bin_score = 250.0 + 2.0 * open_bins_count as f64;
        // If many bins fit, prefer reusing one of them.
        if fitting_bins_count > 0 {
            new_bin_score += 150.0 * (fitting_bins_count as f64).ln().max(1.0);
        }
        // If mean residual is large, reusing is likely fine; penalize new bin more.
        new_bin_score += 0.5 * mean_residual;
        // Late in the stream, avoid opening bins with tiny items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size < 40 {
            new_bin_score += 100.0 * progress;
        }
        score = new_bin_score;
    } else {
        // Prefer bins whose residual is close to the item (tight fit) via residual distance term.
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 20.0 * tightness;
        // Slight preference for bins below mean residual (consolidating emptier bins).
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // Time-horizon modulation: early on, be greedy about compactness; late, be conservative
    // about leaving unusable slivers.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Tight fits (small post_residual) are increasingly valuable as the stream progresses.
    let pr_norm = pr / cap; // in [0,1)
    let tightness = 1.0 - pr_norm;
    let poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep in [0,1]
    score -= 30.0 * poly * tightness * tightness;

    // Penalize post_residual that is too small to ever be useful (dead space),
    // scaled non-linearly by progress: late dead space is worse.
    let dead = if pr > 0 && pr < 10 { (10.0 - pr as f64) / 10.0 } else { 0.0 };
    score += 25.0 * (0.5 + 0.5 * poly) * dead * dead;

    // Lookahead: reward leaving room for the next item (perfect follow-up fit),
    // penalize post_residual that almost-but-not-quite fits it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = (pr - nxt) as f64;
            score -= 15.0 * poly * (-gap / 20.0).exp();
        } else {
            let miss = (nxt - pr) / cap;
            score += 12.0 * poly * miss * (1.0 - miss);
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits
    // for the current item (large relative waste) or bins are congested.
    if bin_residual == bin_capacity {
        let waste = (bin_residual - item_size) as f64 / cap;
        let min_waste_elsewhere = if fitting_bins_count > 0 {
            (post_residual as f64 / cap).min(1.0)
        } else {
            waste
        };
        let congestion = (open_bins_count as f64 / 8.0).tanh();
        score += 35.0 + 20.0 * congestion - 30.0 * (1.0 - min_waste_elsewhere) * (1.0 - min_waste_elsewhere);
    }

    // Mild penalty when this bin's residual deviates far from the mean residual,
    // encouraging balanced residual distribution across open bins.
    score += 0.15 * (pr - mean_residual).abs() * (0.5 + 0.5 * poly);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Exact-fill reward: perfect packing gets strongest discount.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic-class penalty: dead space in "awkward" classes is penalized more.
        // Classes: (0,10], (10,20], (20,30], (30,50], (50,100)
        let class_penalty = if post_residual <= 10 {
            5.0
        } else if post_residual <= 20 {
            12.0
        } else if post_residual <= 30 {
            20.0
        } else if post_residual <= 50 {
            35.0
        } else {
            0.0 // large residual is still usable, mild
        };
        score += class_penalty;

        // Modulo arithmetic: if next item can exactly fill the post residual, big reward.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 500.0;
            } else if next_item_size <= post_residual {
                // Reward when post_residual is a "harmonic" multiple-ish of next item size
                let k = post_residual / next_item_size.max(1);
                if k >= 1 && post_residual % next_item_size.max(1) == 0 {
                    score -= 60.0 * k as f64;
                } else {
                    // partial fit reward proportional to how much of next item fits
                    score -= 25.0;
                }
            } else {
                // next item cannot fit here: penalize leaving dead space that blocks it
                score += 15.0;
            }
        }

        // Integer-division threshold coupling: pair small residuals with small items.
        let pair_class = (post_residual / 10) + (next_item_size / 10);
        score -= (pair_class as f64) * 1.5;

        // Last-chance bin: strongly favor using the only fitting bin.
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 120.0;
        }

        // New-bin candidate: penalize opening a new bin unless current bins are quite full.
        if bin_residual == bin_capacity {
            let mean_frac = mean_residual / bin_capacity as f64;
            // Open new bin only if mean residual across open bins is low (bins nearly full)
            // or there are no open bins.
            if open_bins_count == 0 {
                score -= 200.0;
            } else if mean_frac < 0.15 {
                score -= 50.0;
            } else {
                score += 80.0 * mean_frac + (open_bins_count as f64) * 5.0;
            }
        }

        // Progress-scaled tightening: later in the stream, be greedier about tight fits.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (bin_capacity - post_residual) as f64 * 0.3 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize residuals that cannot fit even the smallest plausible item.
    if post_residual > 0 && (post_residual as f64) < 0.15 * bin_capacity as f64 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Open-bins pressure: prefer using existing bins over opening new ones.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: make the empty bin moderately attractive only when
    // the current fit is poor; otherwise keep it slightly penalized.
    if bin_residual == bin_capacity {
        score -= 5.0;
        // If nothing fits well, a fresh bin avoids creating dead space.
        if post_residual < 10 && bin_residual != bin_capacity {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: reward leaving space that can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Mild normalization toward stream progression.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    // Slight preference for bins with residual near the mean (balanced usage).
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual), normalized.
    score += 0.5 * (post_residual as f64 / cap);

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff < 1.0 {
            score -= 40.0; // perfect pairing
        } else if post_residual as f64 >= nxt {
            score -= 10.0 * (1.0 - diff / cap);
        } else {
            // next item cannot fit here; penalize wasted small residuals
            score += 0.3 * (post_residual as f64 / cap) * (nxt / cap);
        }
    }

    // Relative to mean residual: prefer bins with less-than-average residual (tighter bins).
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it moderately attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score = cap * 0.6 + post_residual as f64;
        if next_item_size as f64 >= cap * 0.5 {
            score -= 5.0;
        }
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Late-stream consolidation: push toward filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness * (item_size as f64);

    // Penalize dead space that is too small to hold any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Prefer bins whose residual is close to item_size relative to the mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits very poorly everywhere.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Early in the stream, opening bins is cheaper (future items can fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 12.0 * (1.0 - progress);
        // If many bins are open already, discourage spreading.
        score += 1.5 * (open_bins_count as f64).sqrt();
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
            // Next item won't fit in leftover; mild penalty for wasting space.
            score += 0.2 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Prefer using fuller bins slightly more as stream progresses (consolidation).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * fill_ratio * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer small post residual, with non-linear sharpening over stream progress.
    let mut score = post * (1.0 + 0.8 * progress * norm_post);

    // Quadratic dead-space penalty: small residuals (<~half bin) are hard to reuse.
    let dead = if norm_post < 0.5 { (0.5 - norm_post).powi(2) } else { 0.0 };
    score += 30.0 * dead * (1.0 + progress);

    // Cubic coupling: reward tight fits (small post) more strongly later in the stream.
    score -= 12.0 * (1.0 - norm_post).powi(3) * progress;

    // Lookahead: penalize if next item cannot use the post residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > post {
            score += 6.0 * ((nx - post) / cap) * (1.0 + progress);
        } else {
            score -= 4.0 * (post - nx) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count <= 1 {
        score -= 25.0;
    }

    // New-bin candidate: smooth penalty growing with number of open bins and mean residual,
    // so a new bin is only chosen when existing fits are truly poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 18.0 + 2.5 * open_bins_count as f64 + 8.0 * (mean_residual / cap).max(0.0);
    } else {
        // Mild reward for consolidating into existing bins as they fill.
        score -= 2.0 * (1.0 - (bin_residual as f64) / cap);
    }

    // Mean-residual coupling: bins deviating far below mean residual are less attractive
    // (keeps a diverse residual pool for future items).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it partitions the capacity
    let pr = post_residual;
    let class = pr % 10; // decade class of dead space
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;

    // Penalize dead space in "unusable" classes: residuals in (0,10) are nearly dead
    if pr > 0 && pr < 10 {
        score += 25.0;
    }
    // Reward residuals that form harmonic complements of common item sizes (multiples of 5/10)
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    } else if pr % 5 == 0 {
        score -= 4.0;
    } else {
        score += class as f64 * 0.6; // odd classes leave awkward gaps
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 40.0;
    }

    // Fraction-of-capacity coupling: prefer filling past half/quarter thresholds
    let fill_frac = item_size as f64 / cap;
    if fill_frac > 0.5 {
        score -= 6.0 * (fill_frac - 0.5);
    }
    if bin_residual > half && pr <= half {
        score -= 3.0; // crossing the halfway threshold is efficient
    }
    if bin_residual > quarter && pr <= quarter {
        score -= 2.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score += slack * 0.15;
            if (pr - next_item_size) % 10 == 0 {
                score -= 5.0; // harmonic complement for next item
            }
        } else {
            // next item won't fit here; mild penalty for wasting the slot
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer opening a new bin when current fit is terrible
    if bin_residual == bin_capacity {
        // fresh bin: baseline score equals item_size left over; discourage unless nothing fits well
        score += 15.0 + mean_residual * 0.1;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        }
    } else if pr < 10 && fitting_bins_count > 1 {
        // avoid creating tiny dead space if better options exist
        score += 10.0;
    }

    // Stream progression: later in the stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - fill_frac);

    // Many open bins with high mean residual: prefer consolidating into emptier bins
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical future items are waste.
    let dead_threshold = 20.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if (post_residual as f64) <= 5.0 {
        score -= 20.0;
    }

    // Reward bins whose residual tightly matches the item (tight fit ratio).
    let fit_tightness = item_size as f64 / bin_residual as f64;
    score -= fit_tightness * 15.0;

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (0.5 + progress);

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // offers a decent fit, or the item is large relative to a fresh bin.
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0
            && (mean_residual - item_size as f64).abs() < cap * 0.5;
        if decent_fit_exists {
            score += 40.0; // penalize opening a new bin when a reasonable fit exists
        } else {
            score -= 10.0; // fresh bin is a fine home for poor fits elsewhere
        }
        // Large items pack efficiently into fresh bins early.
        if item_size as f64 > cap * 0.7 {
            score -= 15.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, this placement is golden.
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 30.0;
    }
    // Penalize leaving a residual that is awkwardly just below the next item.
    if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual && (next_item_size as u32) - post_residual <= 10 {
        score += 10.0;
    }

    // Slight preference for bins with below-mean residual (concentrate filling).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    score -= (1.0 - (post_residual as f64) / cap) * 30.0;

    // Aggressive 2-step lookahead: if the next item exactly fills post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next - post_residual as f64).abs() < 1.0 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item can also land here: reward proportional fit.
            score -= (next / post_residual as f64) * 25.0;
        } else {
            // Next item won't fit here: penalize wasted residual.
            score += (next / cap) * 20.0;
        }
        // Perfect pairing: post_residual + next fills bin exactly.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // Compare against mean residual across open bins: prefer bins tighter than average.
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64) / mean_residual;
        score += (rel - 1.0) * 15.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Penalize opening a brand-new bin when decent open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 20.0 + (open_bins_count as f64) * 2.0;
        // But allow opening a new bin if the item is huge and fits poorly anywhere.
        if item_size as f64 > 0.7 * cap && post_residual < 10 {
            score -= 25.0;
        }
    }

    // Late in the stream: consolidation matters more; penalize spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / cap) * 25.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Reward near-perfect packing (post_residual very small).
    if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Penalize dead space: residual too small to be useful for future items
    // (assume items >= 1, but typical mid-size items dominate; keep generic).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // stranded sliver
    }

    // Lookahead coupling: if the next item fits in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.2 * (next_item_size as f64);
        } else {
            // next item won't fit here; slight penalty proportional to waste gap
            score += 0.1 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin; reduced when existing fits are poor.
        let mut penalty = 30.0;
        if fitting_bins_count == 0 {
            penalty = -5.0; // nothing fits: opening a new bin is necessary
        } else if fitting_bins_count == 1 {
            penalty = 10.0; // only one fit: mildly discourage
        }
        // Early in stream, opening bins is cheaper; late, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty += 20.0 * progress;
        // If mean residual across open bins is high, open bins are underused:
        // discourage new bins.
        penalty += (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 15.0;
        score += penalty;
    }

    // Global fragmentation pressure: many open bins with low mean residual
    // suggests fragmentation; favor placements that consolidate (low post_residual).
    if open_bins_count > 1 {
        let frag = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 5.0 * frag;
    }

    // Mild tie-break: prefer bins with more residual used already (smaller residual).
    score += 0.05 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
