pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into residue classes mod 10
    let r = post_residual;
    let class = r % 10;
    // Rewards: residuals that form "harmonic" complements with typical item sizes (multiples of 10)
    if r == 0 {
        score -= 60.0; // perfect fit is golden
    } else if class == 0 {
        score -= 12.0; // residual is a multiple of 10: likely re-usable by future items
    } else if class >= 1 && class <= 3 {
        score += 18.0; // tiny unusable sliver: dead space penalty
    } else if class >= 8 {
        score += 6.0; // nearly a full class slot but wasteful
    }

    // Integer-division thresholds on post_residual
    let q = r / 20; // how many "20-slots" remain
    score -= q as f64 * 5.0; // more usable slots => better bin
    if r > 0 && r < 10 {
        score += 25.0; // sub-minimum residual is pure waste
    }

    // Lookahead coupling: can next item fit into post residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            // harmonic bonus scaled by how tightly next item fits
            let tight = (r - next_item_size) as f64;
            score -= 20.0 - tight * 0.3;
        } else {
            score += 8.0; // next item cannot follow here
        }
    } else {
        // last item: only care about current fit
        score -= 5.0;
    }

    // Last-chance bin logic
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0; // strongly prefer using the only bin that fits
    }

    // New-bin candidate handling: opening a new bin wastes mean residual
    if bin_residual == bin_capacity {
        let waste = mean_residual * open_bins_count as f64;
        score += 15.0 + waste * 0.2;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score += 10.0; // next item won't fit in fresh bin either
        }
    }

    // Prefer fuller bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - bin_residual) as f64 * 0.1 * (0.5 + progress);

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= 10) are pure waste; penalize heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small gaps are only usable by tiny items; scale penalty.
        score += 25.0 + (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // If this bin can also fit the lookahead item exactly after placement,
    // strongly favor it (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }
    // If the lookahead item would be blocked by the resulting residual,
    // mild penalty unless residual becomes near-useless anyway.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 6.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, opening a new bin is less costly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.8 + 0.4 * progress);

    // New-bin candidate handling: an empty bin has perfect flexibility but
    // should only win when the fit into existing bins is poor. Base its
    // score on the mean residual landscape.
    if bin_residual == bin_capacity {
        score = 30.0 + mean_residual * 0.5;
        // Late in the stream, prefer closing out existing bins.
        score += 15.0 * progress;
        // If several bins already fit, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 10.0 + 5.0 * fitting_bins_count as f64;
        }
        // But if the only fitting bin would leave a large dead gap, allow
        // the new bin to win.
        if fitting_bins_count == 1 && post_residual >= 10 && post_residual < 30 {
            score -= 20.0;
        }
    }

    // Mild bonus for keeping residuals aligned with common item sizes
    // (multiples of 10 are most reusable).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual large enough for next item: mild reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 - slack * 0.05;
    }

    // Post-residual too small for next item: dead space penalty, stronger when close to fitting
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap.min(20.0) * 1.5;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize opening a new bin when a decent fit exists among open bins
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 && post_residual >= next_item_size {
            score += 25.0;
        }
        score += 5.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.1;

    // Late in stream: prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared waste penalty (dead space is superlinear bad)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness;

    // Perfect / near-perfect fill bonus
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Penalize creating residual too small for typical future items (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: reward if next item fits into post_residual (chaining)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.1 * next_item_size as f64;
        } else if post_residual > 0 && next_item_size > post_residual {
            // next item won't fit here; slight penalty for leaving awkward gap
            score += 3.0;
        }
        // If next item is large, prefer conserving big residual bins
        if next_item_size >= 70 && post_residual < next_item_size as u32 {
            score += 4.0;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize opening new bins mildly, more when many bins open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 + 1.5 * open_bins_count as f64 * (1.0 - 0.5 * progress);
        // but if the item is large and mean residual across bins is small, opening is fine
        if item_size as f64 > mean_residual {
            score -= 14.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (use emptier bins for big items)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev * (item_size as f64 / 100.0);

    // Mild time-horizon adaptation: early stream, be choosier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * tightness * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with a smooth non-linear (quartic) reward
    let mut score = pr - 18.0 * (1.0 - norm_pr).powi(4) * cap * 0.1;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight packing matters more; early on, slack is okay.
    let tightness = 1.0 - norm_pr;
    score += 25.0 * norm_pr * norm_pr * (0.4 + 0.6 * progress);
    score -= 12.0 * tightness * tightness * (0.3 + 0.7 * (1.0 - progress));

    // Lookahead: reward leaving room for the next item, penalize near-misses smoothly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n) / cap;
        if gap >= 0.0 {
            // next item fits: reward, strongest when the fit is exact-ish
            score -= 10.0 * (1.0 - gap).powi(2);
        } else {
            // next item just misses: smooth penalty proportional to overshoot
            score += 8.0 * (-gap).powi(2);
        }
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * tightness;
    }

    // New-bin candidate: penalize mildly early, more when decent fits exist
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress) + 4.0 * (fitting_bins_count as f64).ln();
    }

    // Mild diversity bonus: keep residuals near the mean residual to balance bins
    score += 0.05 * (pr - mean_residual).abs();

    // Slight penalty for many open bins, encouraging consolidation
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Class boundaries at multiples of common item-size harmonics.
    let pr = post_residual;
    let class = if pr == 0 { 0 }
        else if pr <= 10 { 1 }
        else if pr <= 20 { 2 }
        else if pr <= 30 { 3 }
        else if pr <= 40 { 4 }
        else if pr <= 50 { 5 }
        else { 6 };
    // Reward tight fits (small classes), penalize awkward mid leftovers.
    score -= (6 - class) as f64 * 4.0;
    if class == 3 || class == 4 {
        // leftover in 21..40 is a "dead zone": too small for many items, too big to ignore
        score += 6.0;
    }

    // Modulo-10 coupling: leftovers that are multiples of 10 pair well with
    // the typical item-size lattice (sizes 1..100 often cluster on multiples of 5/10).
    if pr % 10 == 0 && pr > 0 {
        score -= 3.0;
    }
    if pr % 5 == 0 && pr > 0 {
        score -= 1.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let npr = post_residual - next_item_size;
            score -= 8.0;
            if npr == 0 { score -= 6.0; }
            if npr % 10 == 0 { score -= 2.0; }
        } else {
            score += 4.0;
        }
        // Harmonic check: next item is "large" relative to capacity
        let next_frac = next_item_size as f64 / cap;
        if next_frac > 0.5 && post_residual < next_item_size {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are bad.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 30.0;
        // if this is the only fitting option, opening is necessary
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // large items prefer fresh bins
        let frac = item_size as f64 / cap;
        if frac > 0.7 {
            score -= 10.0;
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 8.0;
        // many open bins with high mean residual -> prefer consolidation
        score += (open_bins_count as f64).ln().max(0.0) * 2.0 + mean_residual / 20.0;
    } else {
        // mild consolidation pressure: prefer bins with low residual (best-fit flavor)
        score += (bin_residual as f64) * 0.05;
        // reward filling bins that are already mostly full
        if bin_residual as f64 / cap < 0.3 {
            score -= 2.0;
        }
    }

    // Perfect fit is always excellent.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(20)) {
        score += 60.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Small residuals are likely dead space; penalize superlinearly.
    if post_residual < 15 {
        score += (15.0 - post_residual as f64) * 3.0;
    }

    // Reward tightening the residual distribution (fit close to mean residual).
    let gap = (bin_residual as f64 - mean_residual).abs();
    score += gap * 0.3;

    // Open-bins pressure: discourage spreading into many bins unless it helps.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin leaves a bad gap
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        score = 100.0 - (post_residual as f64) * 0.5;
        if fitting_bins_count == 1 {
            score += 50.0; // don't open new bin when a last-chance bin exists
        }
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
    }

    // Lookahead: favor leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Slight stream-progression pressure to consolidate late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: bin becomes exactly full next step
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // mild reward proportional to how close next item gets to filling
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use leftover: penalize dead space
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer tight fits relative to mean residual
    score += 0.25 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin unless the current item nearly fills it
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score += 40.0 * (1.0 - fill_frac);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // new bin set up for a good chain
        }
    }

    // Late in stream, consolidate into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !is_new_bin {
        score -= 10.0 * progress;
    }

    // Small penalty for many open bins to encourage consolidation
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 30.0;

    // Penalize wasted residual relative to mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.25;
    }

    // Lookahead: if next item fits into the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Perfect chain: next item exactly fills remainder.
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // Dead space for the known next item; penalize proportionally.
            let gap = (post_residual - next_item_size.min(post_residual)) as f64;
            score += gap * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let base = 20.0 + 0.1 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin anyway
        } else if fitting_bins_count == 1 {
            score += base - 10.0 * progress; // borderline: keep last-chance bin competitive
        } else {
            score += base + 10.0; // many alternatives: deprioritize new bin
        }
    }

    // Mild time-horizon scaling: early stream, be slightly more selective about fill quality.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear waste penalty: squared normalized post-residual
    let post_norm = post / cap;
    score += 12.0 * post_norm * post_norm * cap * 0.5;

    // Tight fits rewarded more as stream progresses
    let tightness = 1.0 - post_norm;
    score -= 20.0 * tightness * tightness * (0.5 + progress);

    // Penalize residual that can't fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 8.0 * (nxt - post) / cap * (1.0 + progress);
        } else {
            score -= 4.0 * (post - nxt).min(cap) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Crowding pressure: many open bins -> favor filling existing ones
    let crowd = (open_bins_count as f64).ln_1p();
    score -= 3.0 * crowd * tightness;

    // Mean residual coupling: prefer bins deviating below mean residual (denser bins)
    let dev = (mean_residual - post) / cap;
    score -= 5.0 * dev * dev.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residuals divisible by common item sizes are reusable
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else {
        // divisibility bonus: residual exactly reusable by a plausible next item
        for d in [10u32, 20, 25, 30, 40, 50] {
            if pr % d == 0 && pr >= d {
                score -= 8.0 + (d as f64) * 0.15;
            }
        }
        // dead-space class: small unusable fragments
        if pr < 10 {
            score += 45.0; // fragment below minimum item size is pure waste
        } else if pr < 20 {
            score += 18.0;
        }
        // quantize residual into capacity-fraction classes; prefer coarse fill
        let frac = (pr as f64) / (bin_capacity as f64);
        score += 12.0 * (frac * std::f64::consts::PI).sin().abs();
    }

    // Lookahead coupling: does post_residual accommodate next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0; // chain placement possible
            // harmonic match: exact modulo fit for the lookahead
            if pr % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
        } else {
            score += 6.0; // this bin dies for the next item anyway
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless item is large and no good fit exists
    if bin_residual == bin_capacity {
        score += 55.0;
        if item_size >= 60 && post_residual < 40 {
            score -= 40.0; // large item starting a fresh bin is fine
        }
        if fitting_bins_count > 0 {
            score += 15.0 * (fitting_bins_count as f64).min(3.0);
        }
    }

    // Tightness reward: prefer bins where item fills a large fraction of residual
    if bin_residual > 0 {
        let fill = (item_size as f64) / (bin_residual as f64);
        score -= 20.0 * fill * fill;
    }

    // Mean-residual alignment: bins deviating from mean residual are less flexible
    score += 0.08 * ((post_residual as f64) - mean_residual).abs();

    // Late-stream consolidation: as stream ends, prefer packing into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    // Modulo threshold on post_residual vs capacity half
    if pr == bin_capacity / 2 {
        score -= 5.0; // half-full residual is a versatile class
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Prefer bins whose residual closely matches the item (tight coupling).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.05;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // New empty bin candidate: make it unattractive unless it beats everything.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near matches with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect fit for next item: strong reward
        if post_residual == next_item_size {
            score -= 40.0;
        } else {
            score += diff * 0.35;
        }
        // Penalize leaving residual too small for next item (dead space)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: reward tight packing strongly
        score -= 20.0;
    }

    // Relative to mean residual: prefer bins whose post-residual deviates favorably
    let mean_dev = post_residual as f64 - mean_residual;
    score += mean_dev * 0.15;

    // Reward filling bins tightly relative to capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate penalty: prefer existing bins unless this is a big item
    if bin_residual == bin_capacity {
        score += 15.0 - fill_ratio * 20.0;
    }

    // Late in stream: prioritize closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Lookahead: if post_residual can't fit the next item, it's likely dead space.
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.8;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can still host the next item.
        score -= 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins could fit reasonably well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_pressure = (mean_residual - item_size as f64).max(0.0);
        score += 55.0 - fit_pressure * 0.5 - progress * 10.0;
        // Fewer open bins => less consolidation pressure, discourage new bin slightly less.
        score -= open_bins_count.min(10) as f64 * 1.5;
    } else {
        // Prefer bins with smaller residual before placement (best-fit flavor).
        score += (bin_residual as f64) * 0.15;
        // Prefer bins already below mean residual (more filled than average).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Early stream: be more exploratory, favor consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let fit = fitting_bins_count as f64;
    let open = open_bins_count as f64;

    let mut score = post;

    // Non-linear coupling: residual squared scaled by progress
    score += 18.0 * norm_post * norm_post * (0.5 + progress);

    // Cubic term penalizing awkward mid-range residuals
    let x = norm_post - 0.5;
    score += 30.0 * x * x * x * x;

    // Tight fit reward, stronger early
    score -= (1.0 - norm_post) * (1.0 - norm_post) * 22.0 * (1.2 - progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_post);
    }

    // More fitting bins -> less urgency; smooth divisor coupling
    score += 10.0 * norm_post / (1.0 + fit);

    // Lookahead: if next item fits into post_residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 12.0 * (nxt / cap) * (1.0 - progress);
        } else {
            score += 6.0 * (1.0 - nxt / cap) * norm_post;
        }
    }

    // Mean residual deviation coupling
    score += 4.0 * (post - mean_residual).abs() / cap;

    // Open bin pressure: prefer consolidating when many bins open
    score += 2.0 * open * norm_post * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that are
    // "clean" fractions of capacity (perfect fits, halves, thirds, quarters).
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -60.0 // perfect closure
    } else if pr == bin_capacity / 2 {
        -25.0
    } else if bin_capacity % pr == 0 && pr <= bin_capacity / 2 {
        -18.0 // residual divides capacity: likely reusable exactly
    } else if pr % 10 == 0 {
        -8.0 // round residual class
    } else {
        4.0 // ragged residual: dead-space risk
    };
    score += harmonic_bonus;

    // Lookahead coupling: penalize leaving a residual that neither fits
    // the next item nor is large enough to be generally useful.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward snug fit for the next item
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item cannot follow here: penalize proportionally to how
            // close we came (wasted opportunity) scaled by stream progress
            let progress = step_index as f64 / total_items.max(1) as f64;
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 + 8.0 * progress * (gap / cap);
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: discourage scattering; prefer tighter (smaller residual) bins.
    score += 0.15 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins below mean (tighter packing).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Early stream: slightly favor consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    // New-bin candidate baseline: an empty bin should only win when the
    // fit here is terrible; give it a moderate standing cost.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold any
    // future item are pure waste. Penalize them super-linearly.
    let dead_threshold = 10.0f64; // smallest plausible item footprint
    if (post_residual as f64) < dead_threshold {
        score += 25.0 * (dead_threshold - post_residual as f64);
    }

    // Reward tight fits: post_residual close to zero is excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Coupling with residual landscape: prefer bins whose residual is
    // already tight relative to the mean (filling cramped bins first
    // keeps large residuals available for future large items).
    let tightness = (bin_residual as f64) - mean_residual;
    score += 0.35 * tightness;

    // Penalize leaving a gap that exactly (or nearly) matches nothing:
    // mid-sized leftovers in the 20..40 range are hard to reuse.
    let pr = post_residual as f64;
    if pr > 15.0 && pr < 40.0 {
        score += 8.0 * (1.0 - (pr - 27.5).abs() / 12.5).max(0.0);
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        let nd = post_residual as i64 - next_item_size as i64;
        if nd == 0 {
            score -= 45.0;
        } else if nd > 0 && nd <= 10 {
            score -= 12.0;
        } else if nd < 0 && nd >= -(10) {
            // next item won't fit here; mild penalty for blocking it
            score += 4.0;
        }
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few are open, tolerate looser fits to keep options alive.
    let pressure = open_bins_count as f64;
    score += 0.8 * pressure * (pr / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 70.0;
    }

    // New-bin candidate evaluation: an empty bin is only attractive when
    // the item is large or no open bin fits well. Otherwise penalize it
    // to avoid bin proliferation.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count > 0 {
            score += 30.0 + 40.0 * (1.0 - frac);
        } else {
            score += 5.0 - 20.0 * frac;
        }
    }

    // Mild stream-progression term: late in the stream, be greedier
    // about filling existing bins tightly.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 6.0 * progress * (1.0 - pr / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residuals that exactly fit the next item,
    // penalize residuals too small for the next item (dead space risk).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 50.0;
        } else {
            // Dead space: residual unusable by next item.
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
    }

    // Compare post_residual to mean residual across open bins:
    // prefer leaving residuals near the mean (balanced packing).
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        let open_pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 0.0 };
        score += 250.0 - open_pressure * 30.0;
        // Early in the stream, opening bins is cheap; later, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 100.0;
    }

    // Slight preference for tighter fits overall.
    score += (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already low; amplify the fit quality.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize tiny dead space that is hard to reuse (waste pockets).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 4.0;
    }

    // Lookahead: if the next item can fit into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 - 0.25 * gap.min(40.0);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item can't use leftover; penalize proportionally.
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: late in the stream, avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as the stream progresses.
        score += 15.0 + 30.0 * progress;
        // Opening a bin is more attractive if open bins are mostly full on average.
        score -= 10.0 * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
    } else {
        // Using existing bins is good; slight extra reward when bins are many.
        score -= 2.0 + 0.1 * open_bins_count as f64;
    }

    // Global balance: prefer bins whose residual is above the mean (keeps variety).
    if bin_residual as f64 > mean_residual {
        score -= 2.5;
    } else {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post residual (tight fit).
    let mut score = post;

    // Smooth non-linear reward for tight fits: post_residual^2 scaled by capacity.
    score -= (post * post) / (2.0 * cap);

    // Cubic dead-space penalty: strongly punish residuals that are too small to be useful.
    let dead = (post / cap).powi(3);
    score += 40.0 * dead * (1.0 + progress);

    // Fill-ratio coupling: reward bins that end up well-filled, modulated by stream progress.
    let fill = item / cap;
    score -= 15.0 * fill * fill * (0.5 + progress);

    // Lookahead: if next item fits in post_residual, reward; else penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 8.0 * (1.0 - post_residual as f64 / cap) * (1.0 - progress * 0.5);
        } else {
            score += 5.0 + 10.0 * progress;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when open bins would leave large waste,
    // or when many bins are open and residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).max(0.0);
        let pressure = (open_bins_count as f64).ln().max(0.0);
        // New bin is cheap early; penalize later unless fragmentation is high.
        score = 30.0 + 60.0 * progress - 25.0 * fragmentation * pressure;
        // But if no open bin fits at all, opening is inevitable and good.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference to balance load across open bins.
    score += 0.02 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals that are "nice" fractions
    // of capacity (multiples of 10/20) are reusable, odd remainders are dead space.
    let pr = post_residual;
    if pr > 0 {
        let class_penalty = match pr % 10 {
            0 => -6.0,
            5 => -2.0,
            _ => 3.0 + (pr % 10) as f64 * 0.5,
        };
        score += class_penalty;
    }

    // Perfect fit is heavily rewarded.
    if pr == 0 {
        score -= 40.0;
    }

    // Tiny dead space (unusable for min item) is penalized quadratically.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * (10 - pr) as f64 * 0.4;
    }

    // Harmonic pairing: reward if the next item can exactly fill the post-residual
    // or land in the same modulo-10 class, leaving a multiple of 10 again.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 25.0; // chainable perfect fit
        } else if gap > 0 {
            let g = gap as u32;
            if g % 10 == 0 {
                score -= 8.0;
            } else if g % 10 == 5 {
                score -= 3.0;
            } else {
                score += 2.0;
            }
        } else {
            // next item won't fit here: mild penalty scaled by overflow
            score += (-gap) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    // (post_residual would be very small relative to next item) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs() < 3.0
        } else { false };
        if poor_fit || post_residual < 10 {
            score -= 20.0 - 10.0 * progress;
        } else {
            score += 12.0 + 8.0 * (1.0 - progress);
        }
    }

    // Prefer tighter bins overall: compare against mean residual.
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.3;

    // Slight preference for filling fuller bins as the stream progresses.
    score -= (1.0 - bin_residual as f64 / cap) * 5.0 * (step_index as f64 / total_items.max(1) as f64 + 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are heavily penalized (non-linear quadratic ramp).
    let dead_threshold: f64 = 30.0;
    if (post_residual as f64) < dead_threshold {
        let gap = dead_threshold - post_residual as f64;
        score += 4.0 * gap * gap;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Perfect-fill lookahead: if the next item exactly fills the post-residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits comfortably: mild bonus proportional to leftover slack.
        score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residual: penalize proportionally to wasted space.
        score += 8.0 * post_residual as f64 / dead_threshold;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let openness = open_bins_count as f64 / (1.0 + total_items as f64);
    score += 10.0 * openness * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is already low
    // (i.e., consolidate into nearly-full bins).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 6.0 * dev;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let urgency = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 20.0 * urgency + 0.5 * open_bins_count as f64;
        if post_residual as f64 >= dead_threshold {
            score -= 10.0;
        }
    }

    // Stream progression: late in the stream, be more conservative about waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect two-step match: post_residual exactly fits next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        // Slight bonus when post residual is smaller than next item (dead space bounded)
        if post_residual < next_item_size {
            score -= 3.0;
        }
    } else {
        // Last item: prefer tightest fit strongly.
        score -= 50.0;
    }

    // Penalize large leftover relative to mean residual (wasteful fit).
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Penalize tiny unusable slivers less than medium dead space: slivers < 10 are dead.
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New empty bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if next item is large and this item leaves a good complement, allow it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Early in stream, new bins are cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Mild preference to balance across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize progress through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: post_residual near 0 is best. Add a bonus (score reduction)
    // when post_residual is small relative to the smallest conceivable future item.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item exactly fills the post_residual, this is a perfect
    // chain fit -> strong reward. If next item fits in post_residual, mild reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; a very small post_residual is still fine,
            // but a mid-range dead zone is wasted.
            let dead = post_residual as f64;
            if dead > 0.0 && dead < next_item_size as f64 {
                score += 0.15 * dead;
            }
        }
    }

    // Penalize creating dead space that no future item (min size 1, typical >=10)
    // could ever use, but only when it's a genuine gap (not near-full).
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // near-perfect seal, reward
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Multiple options: prefer the bin whose residual was already small
        // (best-fit behavior), scaled by how crowded the bin population is.
        let crowding = (open_bins_count as f64).ln().max(1.0);
        score += 0.5 * crowding * (bin_residual as f64 / bin_capacity as f64);
    }

    // Global state: if mean residual across open bins is high, we have plenty of
    // slack overall -> discourage dumping into already-large-residual bins and
    // encourage consolidation into tight ones.
    let resid_ratio = bin_residual as f64 / bin_capacity as f64;
    score += 0.6 * (resid_ratio * bin_capacity as f64 - mean_residual);

    // New-bin candidate: an empty bin should only win when no open bin fits well.
    // Penalize opening a new bin, more so early in the stream (amortization) and
    // less so late (when leftover tails are cheap).
    if bin_residual == bin_capacity {
        let new_bin_penalty = 45.0 * (1.0 - 0.5 * progress);
        // If nothing else fits, the penalty must be effectively void.
        let escape = if fitting_bins_count == 0 { new_bin_penalty } else { 0.0 };
        score += new_bin_penalty - escape;
        // But if the item is huge relative to capacity, opening fresh is natural.
        score -= 0.1 * item_size as f64;
    }

    // Mild time-horizon shaping: late in the stream, prioritize sealing bins
    // completely (minimize residual), early on keep flexibility.
    score -= 6.0 * progress * tightness;

    // Tiny tie-breaker favoring bins with residual just above item size
    // (classic best-fit signal, smoothed).
    score += 0.05 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space, modulated by stream progress
    let mut score = pr * (1.0 + 0.8 * norm_pr * (0.5 + progress));

    // Smooth non-linear coupling: waste hurts more as stream progresses
    score += (pr * pr / cap) * progress * (1.0 - progress) * 2.0;

    // Reward tight fits (small post residual) with a smooth saturating bonus
    let tightness = (-norm_pr * 6.0).exp();
    score -= tightness * (4.0 + 6.0 * progress);

    // Penalize residuals too small for the lookahead item (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = nxt - pr;
        if gap > 0.0 {
            let dead = gap / cap;
            score += dead * (30.0 + 40.0 * progress) * (1.0 - (-dead * 8.0).exp());
        } else {
            // lookahead fits exactly: smooth reward
            score -= (-gap / cap) * 8.0;
        }
    }

    // Last-chance bonus: only this bin can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild penalty when many bins are open and residual is near mean (fragmentation)
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * open_bins_count as f64 * 0.3;

    // New-bin candidate: smooth cost that grows with progress and openness
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.6 * progress) + open_bins_count as f64 * 2.0;
        // but allow new bin if all fits are terrible
        let worst = pr.min(cap);
        let _ = worst;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how well it decomposes into
    // capacity fractions (quarters, thirds, halves). Residuals that are
    // multiples of common divisors are more reusable by future items.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction-of-capacity class of post_residual
    let frac = pr / cap;
    if frac < 0.05 {
        // Perfect or near-perfect fill: strongly reward.
        score -= 60.0;
    } else if frac < 0.15 {
        score -= 25.0;
    } else if frac < 0.35 {
        // Awkward mid-range dead space: penalize.
        score += 20.0;
    } else if frac < 0.55 {
        score += 5.0;
    }

    // Modulo arithmetic: residuals divisible by 4, 3, or 2 align with
    // common item sizes (multiples of small integers).
    let r = post_residual;
    if r > 0 {
        if r % 10 == 0 {
            score -= 12.0; // aligns with decade-quantized items
        } else if r % 5 == 0 {
            score -= 6.0;
        }
        if r % 4 == 0 {
            score -= 3.0;
        }
        if r % 3 == 0 {
            score -= 2.0;
        }
    }

    // Integer-division threshold: can next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain potential: reward, scaled by how tight the next fit is.
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 15.0 + 20.0 * tightness;
            // Harmonic pairing: item + next item near capacity multiples
            let pair = (item_size + next_item_size) as f64;
            if (pair % 50.0).abs() < 1.0 || (pair % 100.0).abs() < 1.0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot follow into this bin: mild penalty.
            score += 8.0;
        }
    } else {
        // Last item: prefer tightest fill aggressively.
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    // or the item is huge relative to residuals of open bins.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 0.45 * cap;
        let many_open = open_bins_count as f64 > 6.0;
        if bad_fit || many_open {
            score -= 10.0; // allow opening a fresh bin
        } else {
            score += 25.0; // discourage wasting open capacity
        }
    }

    // Prefer bins with residual below the mean (consolidate emptier bins).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Late in the stream: tighten up, reduce slack.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual that no plausible future item (>= 1..~30) can use is waste.
    if post_residual > 0 {
        // Non-linear penalty: small residuals are exponentially worse.
        if post_residual < 30 {
            score += 45.0 * (1.0 - post_residual as f64 / 30.0).powi(3);
        }
        // Perfect fit is heavily rewarded.
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Coupling with lookahead: if next item fits exactly in post_residual,
    // this placement is excellent; if post_residual is just barely too small
    // for the next item, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 10 {
            score += 15.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // fit exists; encourage using existing bins when many are already open.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 20.0);
    score += 0.8 * pressure;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make opening a new bin moderately unattractive
    // unless the fit into existing bins would be terrible.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
    }

    // Slight preference for tighter bins generally.
    score -= 0.15 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match between post_residual and next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (bin_capacity as f64 - diff) * 0.9;
        // bonus for leaving exactly enough room for the next item
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // penalize leaving small unusable slivers that neither fit next item nor are useful
        if post_residual < next_item_size && post_residual < 10 {
            score += 40.0;
        }
    } else {
        // last item: prefer tightest fit
        score -= 10.0;
    }

    // relative to mean residual: bins with residual below mean are tighter, prefer them slightly
    score -= (mean_residual - post_residual as f64) * 0.3;

    // last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // new-bin candidate: only attractive when current fit is terrible (huge dead space)
    if bin_residual == bin_capacity {
        let waste = bin_residual as f64 - item_size as f64 - next_item_size as f64;
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 20.0; // opening fresh bin lets next item fit too
        }
        if waste < 0.0 {
            score -= 30.0;
        } else {
            score += waste * 0.5;
        }
    }

    // late in stream, consolidate: penalize spreading across many bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64));
        }
        // If next item exactly fills remaining space, big bonus.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Discount new bins slightly more as stream progresses (commit early structure).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If many open bins already, prefer reusing them.
        score += 2.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual is far below mean residual (they are "odd" bins;
    // filling them normalizes global state).
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Mild pressure to keep the number of open bins low.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: non-linear quadratic shaping of post_residual.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Penalize creating dead space relative to the mean residual across open bins.
    let dead = pr - mean_residual;
    score += 0.15 * dead * dead.abs();

    // Lookahead coupling: favor bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.5 * gap;
        // Bonus if the next item fits exactly after this placement.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 40.0 * progress;
    }

    // New-bin candidate handling: early on, opening fresh bins is cheap;
    // late in the stream, prefer reusing existing bins.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        score += 25.0 * (1.0 - progress) * (1.0 - progress);
        // Penalize new bins when many open bins can fit the item.
        score += 3.0 * fitting_bins_count as f64;
    } else {
        // Mild reward for keeping the number of open bins from exploding.
        score += 0.5 * open_bins_count as f64 * progress;
    }

    // Smooth stream-progress coupling: as stream advances, tighten tolerance
    // for leftover space (favor near-full bins more aggressively).
    score -= 10.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: class 0 (perfect fit) strongly rewarded
    let pr = post_residual;
    let class = pr % 10;
    if pr == 0 {
        score -= 60.0;
    } else if class == 0 {
        score -= 12.0; // multiple of 10 -> likely reusable by 10..80 items
    } else if class <= 3 {
        score += 8.0;  // tiny dead space, unusable
    }

    // Dead-space penalty: residual too small for the smallest plausible next item
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Reward if next item fits exactly into post_residual (harmonic pairing)
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap).max(0.0);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer tight fits: relative waste
    score += (post_residual as f64 / cap) * 20.0;

    // Fractional capacity coupling: item size classes
    let item_frac = item_size as f64 / cap;
    if item_frac > 0.5 && post_residual < item_size {
        score -= 10.0; // big item placed tightly
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins open or late stream
        score += 20.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 / 2 {
            score -= 15.0; // big next item may justify fresh bin
        }
    } else {
        score -= 3.0 * (open_bins_count as f64 / (open_bins_count as f64 + 1.0));
    }

    // Mean residual alignment: prefer bins near mean residual (balanced packing)
    score += ((post_residual as f64 - mean_residual).abs()) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful later
    // (below the minimum plausible item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - post_residual as f64 * 3.0;
    }

    // Reward tight fits strongly (wasted-space relative measure).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 40.0;

    // Reward leaving a residual that could still fit a typical item.
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this is a perfect pairing — reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when few are open,
    // encourage consolidation when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to how many bins exist.
        score += 25.0 + open_bins_count as f64 * 3.0;
        // But if the current bin would leave a terrible dead space and no
        // good alternative exists, opening a new bin becomes attractive.
        if post_residual > 0 && post_residual < 10 {
            score -= 45.0;
        }
    } else {
        // Placing into an existing bin reduces bin count pressure slightly
        // as the stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 + progress * 5.0;
    }

    // Slight preference for bins below mean residual (balance spreading),
    // keeping residuals even for future flexibility.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: zero post residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills the post residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 900.0;
    }

    // Penalize small dead space that next item cannot use (wasted capacity).
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 150.0 * waste;
    }

    // Reward bins whose residual is already below average (tight bins).
    score -= (bin_residual as f64 - mean_residual) * 2.0;

    // Last-fitting-bin urgency: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 400.0;
    }

    // New-bin candidate: penalize opening a new bin when it would leave a large
    // residual compared to existing mean residual, unless stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = open_bins_count as f64 / (step_index as f64 + 1.0);
        score += 120.0 * (1.0 - progress) * openness;
        // If next item is huge relative to residual, a fresh bin is attractive.
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) < mean_residual {
            score -= 60.0;
        }
    }

    // Slight penalty for very small post residual that nothing (min size ~1) may fit
    // but is not zero — dead space trap.
    if post_residual > 0 && post_residual < 5 {
        score += 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 60.0 - chain_waste * 0.5;
        } else {
            // next item won't fit here; penalize leaving awkward gaps
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(40.0) * 0.8;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let pressure = (open_bins_count as f64).ln().max(1.0);
        // base penalty for opening a new bin
        score += 120.0;
        // but if existing residuals are small (poor fits), new bin becomes better
        score -= (1.0 - crowding) * 200.0;
        // early in stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 30.0;
        // large item that barely fits anywhere: new bin is clean
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 50.0;
        }
        let _ = pressure;
    }

    // Prefer filling bins with larger mean residual less aggressively
    score -= (mean_residual - post_residual as f64) * 0.1;

    // Mild preference to keep number of open bins stable
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post residual, with non-linear polynomial coupling
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in the stream, tighten packing harder
    let tight = 1.0 + 1.5 * progress * progress;
    score *= tight;

    // Reward filling bins tightly relative to mean residual (smooth interaction)
    let mean_gap = mean_residual - pr;
    score += 0.35 * mean_gap * (0.5 + progress);

    // Penalize leaving dead space that the next item cannot use (smooth quadratic)
    if next_item_size > 0 {
        let waste = (pr - next_item_size as f64).max(0.0);
        score += 0.25 * waste * waste / cap;
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Perfect fit reward (smooth exponential-like)
    if pr == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // "dead" (very small) vs "usable" bands using integer division thresholds.
    let dead_zone = post_residual < 10; // unusable sliver given min item size 1..100
    let tiny_zone = post_residual < 20;

    if dead_zone {
        // Perfect or near-perfect fit: strongly reward.
        score -= 60.0 + (cap - post_residual as f64) * 0.3;
    } else if tiny_zone {
        score -= 25.0;
    } else {
        // Usable leftover: reward proportional tightness but keep it reusable.
        let tightness = 1.0 - (post_residual as f64 / cap);
        score -= 20.0 * tightness;
    }

    // Modulo arithmetic on post_residual: leftovers divisible by common item
    // sizes (10, 20, 25, 50) are more likely to be filled later.
    let post = post_residual;
    if post > 0 && (post % 10 == 0 || post % 25 == 0 || post % 50 == 0) {
        score -= 12.0;
    }
    // Odd awkward remainders get penalized.
    if post % 10 != 0 && post < 40 && post >= 10 {
        score += 8.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // Next item can slot in: big reward, scaled by how well it fits.
            let waste_after_next = post - next_item_size;
            if waste_after_next < 10 {
                score -= 45.0; // chain of near-perfect fits
            } else {
                score -= 15.0;
            }
        } else {
            // Next item cannot use this bin's leftover; penalize if we also
            // leave a moderate gap (dead space risk).
            if post >= 10 && post < next_item_size {
                score += 10.0;
            }
            // Harmonic class check: leftover in next item's complement class?
            if post > 0 && (next_item_size % 10 == 0) && (post % 10 == 0) {
                score -= 5.0; // same residue class, likely combinable later
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin should only win when current
    // bins would create bad leftovers. Give the empty bin a moderate baseline
    // score (its post_residual == capacity is large, already penalizing it),
    // plus a mild bonus that grows with mean residual fragmentation.
    if bin_residual == bin_capacity {
        score -= (open_bins_count as f64) * 2.0
               + (mean_residual - post_residual as f64).abs() * 0.05;
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / cap);

    // Prefer bins tighter than the mean (best-fit flavor with harmonic twist).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the space.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 60.0;

    // Dead space penalty: small unusable gaps (< min item size 1..10) are pure waste.
    if post_residual < 10 {
        score -= 40.0; // effectively full bin, great
    } else if post_residual < 20 {
        score += 25.0; // risky small gap
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Coupling with lookahead: a gap exactly fitting the next item is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 30.0; // next item fills this bin perfectly
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap unusable for the known next item: penalize proportionally
        score += (next_item_size as f64) * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Open-bin pressure: when many bins are open, consolidate (favor existing bins).
    score += (open_bins_count as f64) * 1.5;

    // Mean residual coupling: placing into a bin far below mean residual spreads waste;
    // favor bins near the mean to keep residuals balanced.
    score += ((post_residual as f64 - mean_residual).abs()) * 0.3;

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = -100.0;
        } else {
            // prefer a new bin over a very poor fit (large dead space or fragmentation)
            let poor_fit = (post_residual as f64 > 45.0) as f64 * 20.0
                + (fitting_bins_count == 1 && post_residual > 0 && post_residual < 20) as i32 as f64 * 60.0;
            score = post_residual as f64 + 55.0 - poor_fit;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit bonus: minimize residual aggressively.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward placements whose post_residual matches next item size.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let diff = (post_residual as f64 - nr).abs();
        score -= 120.0 / (1.0 + diff);
        // Perfect lookahead fit: chain placement.
        if post_residual as u32 == next_item_size {
            score -= 150.0;
        }
        // Penalize post_residual that is too small to fit next item (dead space).
        if (post_residual as u32) < next_item_size {
            score += 0.5 * (nr - post_residual as f64);
        }
    } else {
        // Last item: pure tightness.
        score -= 100.0;
    }

    // Relative tightness vs mean residual across open bins.
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs()
        } else {
            post_residual as f64
        };
        let desperation = if fitting_bins_count == 0 { 300.0 } else if fitting_bins_count == 1 { 0.0 } else { 60.0 * fitting_bins_count as f64 };
        score += 40.0 + desperation - 0.3 * poor_fit;
        // Early in stream, slightly favor consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins (encourage consolidation).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness * tightness;

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small dead space is fine, nearly perfect fit
    } else if post_residual >= 10 {
        // dead space worse if it's just above the smallest item size
        let waste = post_residual as f64;
        score += 0.35 * (waste - 10.0).min(40.0);
    }

    // Lookahead: if next item fits in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 22.0 * chain;
    } else if next_item_size > 0 {
        // next item won't fit here; mild penalty proportional to gap
        let gap = (next_item_size - post_residual) as f64;
        score += 0.15 * gap.min(30.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins that are emptier relative to mean residual
        let rel = (bin_residual as f64 - mean_residual) / cap;
        score += 4.0 * rel;
    }

    // New-bin candidate handling: only open a new bin when the item fits
    // nowhere well (large item, poor fits elsewhere).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let item_frac = item_size as f64 / cap;
        // base penalty for opening a new bin
        let mut new_bin_score = 45.0;
        // large items justify new bins more
        new_bin_score -= 25.0 * item_frac;
        // early in stream, opening bins is cheaper
        new_bin_score -= 15.0 * (1.0 - progress);
        // many open bins with slack: discourage new bin
        new_bin_score += 0.4 * open_bins_count as f64;
        // if this is the only fitting option, opening is fine
        if fitting_bins_count == 0 {
            new_bin_score -= 60.0;
        }
        score = new_bin_score;
    }

    // Slight time-dependent tightening: late in stream, conserve bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Smooth polynomial coupling: residual value decays non-linearly with progress
    let decay = 1.0 - progress * progress; // late stream: residuals matter less
    score -= decay * (norm_pr - norm_pr * norm_pr) * cap * 0.5;

    // Penalize large dead space quadratically (wasted capacity)
    score += norm_pr * norm_pr * cap * 0.6;

    // Reward tight fits: small post_residual gets extra bonus
    score -= (1.0 - norm_pr).powi(3) * cap * 0.35;

    // Lookahead: favor bins whose post_residual can hold the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - ((pr - norm_next * cap) / cap).abs();
        score -= 6.0 + 8.0 * snug;
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * (1.0 - progress);
    }

    // Many open bins: encourage consolidation into emptier bins
    let openness = open_bins_count as f64;
    score += (openness / (openness + 10.0)) * (pr - mean_residual).abs() * 0.4;

    // New-bin candidate: penalize opening a new bin, more so early on
    if bin_residual == bin_capacity {
        score += 4.0 + 8.0 * (1.0 - progress) + openness * 0.3;
        // but if current item is huge relative to mean residual, new bin is fine
        score -= (norm_item - mean_residual / cap).max(0.0) * cap * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quantization.
    // Residuals that are multiples of small item sizes (10..=20) are reusable;
    // odd, prime-ish gaps are dead space -> penalize.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -40.0 // perfect fit is always best
    } else if pr <= 10 {
        25.0 // tiny gap, nearly unusable
    } else if pr % 10 == 0 {
        -12.0 // perfectly divisible gap, reusable by standard classes
    } else if pr % 5 == 0 {
        -5.0
    } else {
        8.0 // awkward gap
    };
    score += harmonic_bonus;

    // Next-item lookahead: if the next item fits exactly in post_residual,
    // strongly reward (chained packing). If next item cannot fit afterward,
    // penalize proportionally.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.4;
        } else {
            // next item won't fit here after placement; leftover risk
            let overflow = next_item_size - pr;
            score += (overflow as f64).min(40.0) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // mean residual across open bins is small (all bins nearly full)
    // or the current item leaves an awkward residual in any existing bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // new bin score: base cost + discount if open bins are congested
        let congestion = (mean_residual / bin_capacity as f64) * open_bins_count as f64;
        score = 45.0 - congestion * 6.0 - progress * 5.0;
        if next_item_size > item_size {
            score -= 8.0; // big item coming, fresh bin may help
        }
    }

    // Prefer tighter bins generally: reward small bin_residual (best-fit bias)
    score += (bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item are unusable dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Penalize residual gaps that cannot fit the lookahead item (k=2),
    // but only if that item actually needs to land somewhere.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward a residual that still accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // yet another bin unless the fit is tight.
    let pressure = open_bins_count as f64 * 1.5;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a fresh bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild trend with stream progression: tighten later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 5.0;

    // Deviation from mean residual: prefer bins whose post_residual stays
    // near the mean (balanced packing).
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // New-bin candidate calibration: an empty bin has large post_residual,
    // which is naturally high score; give it a fixed offset so it only wins
    // when open bins would create truly bad dead space.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more strongly than linear.
    score += (post_residual as f64 / cap) * 20.0;

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            score -= 50.0;
        } else if post_residual as u32 >= next_item_size {
            // next item fits: reward proportionally to how well it uses leftover
            score -= 15.0 * (nxt / post_residual as f64);
        } else {
            // next item won't fit here: penalize wasted residual
            score += 8.0 * (1.0 - nxt / cap);
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 5.0 * (mean_residual - bin_residual as f64) / cap;

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0;
        if post_residual as f64 > (item_size as f64) * 0.5 {
            score += 10.0;
        }
    }

    // Late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Lookahead coupling: reward residuals that can host the next item ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            // Post-residual can also fit the next item: strong reward,
            // scaled by how "snugly" the next item fits.
            let snug = 1.0 - ((post_residual as f64 - nxt) / bin_capacity as f64);
            score -= 8.0 * snug;
        } else {
            // Next item won't fit here: penalize leaving awkward gaps,
            // worse when the gap is small (near-miss dead space).
            let gap = nxt - post_residual as f64;
            if gap < 15.0 {
                score += 6.0 * (1.0 - gap / 15.0);
            }
        }
    } else {
        // Last item: pure best-fit, no future to plan for.
        score -= 5.0;
    }

    // --- Exact fit bonus ---
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // --- Last-chance bin: strongly prefer using the only fitting bin ---
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // --- Penalize spreading across too many open bins when residuals are high ---
    let mean_res_norm = mean_residual / bin_capacity as f64;
    if mean_res_norm > 0.5 && open_bins_count > 2 {
        score += 3.0 * mean_res_norm;
    }

    // --- New-bin candidate logic: bin_residual == bin_capacity means empty bin ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive early (plenty of stream left to fill it)
        // or when the item fits poorly everywhere (large post_residual elsewhere).
        let early_bonus = 30.0 * (1.0 - progress);
        score += 20.0 - early_bonus;
        // Discourage opening bins late in the stream.
        score += 40.0 * progress * progress;
    }

    // --- Mild reward for filling existing bins densely as stream progresses ---
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 4.0 * fill_ratio * (0.5 + progress);

    // --- Tiny tie-break noise-free deterministic jitter ---
    score += ((step_index % 7) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear penalty on wasted space (quadratic coupling)
    let waste_norm = pr / cap;
    score += 6.0 * waste_norm * waste_norm * cap;

    // Tight-fit reward: strong discount as post_residual approaches 0
    score -= 10.0 * (-pr / 12.0).exp();

    // Stream-progress coupling: later in stream, waste matters more
    score += (0.5 + 2.0 * progress) * waste_norm * waste_norm * cap;

    // Lookahead coupling: if next item exactly fills post_residual, big reward
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 8.0 * (-diff / 10.0).exp();
        // penalize leaving space slightly larger than next item (dead space)
        if pr > next_item_size as f64 {
            score += 0.15 * (pr - next_item_size as f64);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild preference toward bins below mean residual (balance spreading)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize slightly so we only open when fits are poor
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect / near-perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Harmonic classes of post_residual: dead space that few item sizes (1..100)
    // can reuse is penalized more. Residuals that are multiples of common small
    // sizes (10, 20, 25, 50) are "harmonic" and reusable.
    let harmonic = post_residual % 10 == 0 || post_residual % 25 == 0 || post_residual == 50;
    if harmonic {
        score -= 40.0;
    } else {
        // Non-harmonic dead space penalty grows with residual size.
        score += 0.5 * post_residual as f64;
    }

    // Lookahead: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            score -= 20.0;
        } else {
            // Next item cannot use this bin's leftover: penalize large leftovers.
            score += 0.3 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would leave very bad (non-harmonic, large) residuals.
    if bin_residual == bin_capacity {
        // Baseline competitiveness: a new bin has residual = capacity.
        score = 60.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Slight bonus if next item is large (hard to pack later).
            if next_item_size >= 70 {
                score -= 15.0;
            }
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins already below mean residual (consolidating space).
    score -= 0.2 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that can never host the smallest plausible
    // future item are pure waste; penalize them super-linearly.
    if post_residual < 10 && post_residual > 0 {
        score += 200.0 * (1.0 + (10 - post_residual) as f64);
    }

    // Sweet spots: residuals that exactly match common item sizes are valuable.
    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Penalize leaving a gap that is just barely too small for the next item
    // (lookahead mismatch creates dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 30.0 + 0.5 * (next_item_size - post_residual) as f64;
    }
    // Reward leaving a gap that exactly (or nearly) fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 60.0;
        } else if slack <= 5 {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, prefer compacting into existing
    // bins rather than spreading; with few open bins, opening new bins is cheap.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline near capacity, adjusted by pressure and
        // how poorly the item would fit elsewhere (large mean residual means
        // open bins have room, so opening is less attractive).
        score = bin_capacity as f64 - 40.0 + pressure * 4.0 + (mean_residual - item_size as f64).max(0.0) * 1.5;
        // Early in the stream, opening bins is more acceptable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
    } else {
        // Existing bin: mild reward scaled by how full it already is.
        let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 25.0 * fullness;
        // Prefer bins whose residual is close to the item (tight fit).
        score -= 10.0 * (1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64);
    }

    // Global pull toward the mean residual: avoid creating outliers of tiny
    // residual that fragment the pool of usable space.
    if bin_residual != bin_capacity {
        score += 0.3 * (post_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward leaving a residual that exactly
    // accommodates the next item (chained perfect packing).
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64 - nr).abs() < 0.5 {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // Good: next item still fits; scale reward by tightness of match.
            let slack = post_residual as f64 - nr;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Bad: dead space the next item cannot use; penalize the gap.
            score += 2.0 * (nr - post_residual as f64);
        }
    }

    // Penalize residuals that are small but unusable (below minimum item size 1
    // is impossible here, but tiny residuals are still waste relative to mean).
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.5 {
            score += 0.5 * (mean_residual - pr);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
        if post_residual <= 10 {
            score -= 60.0; // near-perfect last-chance fit
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are poor. Make the empty-bin call (residual == capacity)
    // moderately expensive so it is chosen only when open-bin fits are bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if the next item is large and this item is small, a fresh bin
        // preserves large contiguous space — slightly cheaper to open.
        if next_item_size > 0 && next_item_size > post_residual + 10 {
            score -= 20.0;
        }
    }

    // Slight late-stream pressure: prefer consolidating into fewer bins as
    // the stream progresses to avoid bin-count blowup.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize creating small unusable dead space (post_residual too small to matter later).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward leaving exactly the space the next item needs.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (post_residual as f64 / (next_item_size as f64 + 1.0)).ln().max(0.0);
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless the current
    // fit is terrible or many bins are already open with high mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = fill_ratio < 0.35;
        let pressure = open_bins_count as f64 * mean_residual / bin_capacity as f64;
        if poor_fit || (pressure > 6.0 && progress < 0.7) {
            score -= 20.0;
        } else {
            score += 45.0 + 10.0 * (1.0 - progress);
        }
    }

    // Mild preference to balance residuals toward the mean (avoid extreme skew).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let is_new_bin = (bin_residual as u64 == bin_capacity as u64) && post_residual > 0;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: tight fits matter less; late: minimize dead space aggressively.
    let tightness = pr / cap;
    let poly = tightness * tightness * (1.0 + 2.5 * progress) + tightness * (0.5 + 1.5 * progress * progress);

    let mut score = pr * (0.6 + 1.2 * progress) + 40.0 * poly;

    // Reward using last-chance bins (avoid opening a new bin).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0 + 40.0 * progress;
    }

    // Penalize opening new bins more when many bins are open and mean residual is high.
    if is_new_bin {
        score += 55.0 + 0.8 * open_bins_count as f64 + 0.15 * mean_residual;
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - (pr - nx) / cap) * (1.0 - 0.5 * progress);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Perfect fit bonus (smooth, non-piecewise).
    let perfect = (post_residual == 0) as i32 as f64;
    score -= 25.0 * perfect * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor minimal waste.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Harmonic class logic: dead space in low residue classes is nearly unusable.
    let dead_class = match post_residual {
        0 => 0.0,
        r if r < 10 => 0.9,   // tiny residue rarely reusable
        r if r < 20 => 0.6,
        r if r < 30 => 0.35,
        r if r < 50 => 0.15,
        _ => 0.0,
    };
    score += dead_class * 40.0;

    // Lookahead coupling: penalize residues that cannot host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward proportionally to how snugly the next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 20.0; // next item can't use this residue
            // harmonic bonus: residue modulo 10 classes that pair with common sizes
            if post_residual % 10 <= 2 && next_item_size % 10 >= 8 {
                score += 10.0; // awkward pairing, extra penalty
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // mild preference for bins with less residual among many candidates
        score += (mean_residual - post_residual as f64) * 0.3;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { fitting_bins_count as f64 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 120.0 * pressure;
        // penalize opening bins early / when many bins already open
        score = base + open_bins_count as f64 * 8.0 + (1.0 - progress) * 15.0;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 10.0; // new bin will nicely hold next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Strict dead-space avoidance: a nonzero gap that cannot hold the next
    // lookahead item is wasted capacity -> penalize it.
    if !is_new_bin && post_residual > 0 {
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            // Chain fit: this placement enables the next item to slot in.
            score -= 8.0;
        } else {
            // Dead space: gap too small for the upcoming item.
            score += 5.0 + 0.05 * post_residual as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, use it rather
    // than opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 6.0;
    }

    // New-bin candidate: make it unattractive by default, with pressure that
    // grows with the number of already open bins (consolidate first).
    if is_new_bin {
        score += 12.0 + 0.6 * open_bins_count as f64 * (1.0 + 0.5 * progress);
        // If the fresh bin would end up tighter than the current average
        // residual, opening it is somewhat more tolerable.
        if (post_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Mild global pressure toward reusing open bins early in the stream.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: penalize wasted space relative to mean residual across open bins.
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Strong reward for exact 2-step lookahead match: next item fills bin perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement; mild reward scaled by tightness.
            let tight = (post_residual - next_item_size) as f64;
            score -= 20.0 - 0.2 * tight;
        } else {
            // Next item won't fit here: penalize proportionally to leftover dead space.
            score += 10.0 + 0.1 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when several open bins can fit the item.
    if fitting_bins_count > 1 && bin_residual == bin_capacity {
        score += 40.0;
    }

    // Late in the stream, consolidate: prefer bins with small residual overall.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // Slight reward for high fill ratio of this bin.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);

    // Prefer filling bins that are already mostly full (low residual).
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Lookahead: penalize leaving a residual that awkwardly fits the next item
    // (next item leaves a large unusable remainder), reward perfect chaining.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_left = post_residual - next_item_size;
        if chain_left == 0 {
            score -= 30.0; // perfect pair placement
        } else {
            score += 0.15 * chain_left as f64;
        }
    } else if next_item_size > 0 {
        // Next item cannot use leftover; leftover is dead space risk.
        score += 0.08 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Many open bins: consolidate; few open bins: tolerate spreading.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    // Global pressure: when mean residual is low, waste hurts more.
    score += (post_residual as f64) * (mean_residual / bin_capacity as f64).powi(2);

    // Time horizon: early stream, keep bins flexible; late stream, pack tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.1 * post_residual as f64;
    score -= progress * 20.0 * fill_ratio;

    // New-bin candidate: open a new bin only when item is large relative to
    // typical residuals or all fits are poor.
    if bin_residual == bin_capacity {
        let poor_fits = fitting_bins_count == 0
            || (post_residual as f64 > 0.45 * bin_capacity as f64 && item_size > 50);
        score = if poor_fits { 5.0 } else { 250.0 + item_size as f64 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_norm = pr / cap;

    // Base: post-residual (tighter fit preferred), shaped non-linearly
    let mut score = pr - 2.0 * (fit_norm * (1.0 - fit_norm)) * cap;

    // Polynomial coupling of post_residual with stream progress:
    // early on, prefer leaving usable space; later, chase tight fits.
    let progress_coupling = (1.0 - 2.0 * progress) * (fit_norm - 0.5).powi(2) * cap;
    score += progress_coupling;

    // Smooth quadratic penalty for small dead space relative to mean residual
    let dead = if pr < 10.0 { (10.0 - pr) * (10.0 - pr) * 0.5 } else { 0.0 };
    score += dead;

    // Reward last-chance bins (avoid opening a new bin)
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Lookahead: bonus if next item fits snugly into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let snug = 1.0 - (pr - nxt) / cap;
            score -= 4.0 * snug * snug;
        } else {
            score += 2.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln() * 0.5;

    // New-bin candidate: keep it slightly unattractive unless residuals are large
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress - 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo 10 classes
    let pr = post_residual;
    let class = pr % 10;

    // Perfect fits are extremely desirable
    if pr == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals that can never fit the smallest item (1..=10)
    // Harmonic classes 1..9 (below 10) are dead unless exactly 0.
    if pr > 0 && pr < 10 {
        score += 300.0;
    }

    // Class-based desirability: residuals that are multiples of 10 are "harmonic"
    // and can be exactly filled by items of complementary decile sizes.
    if class == 0 && pr > 0 {
        score -= 40.0;
    } else if class == 5 && pr > 0 {
        // half-class residuals pair well with x5 items
        score -= 15.0;
    } else if pr > 0 {
        score += class as f64 * 2.0;
    }

    // Lookahead: if next item fits the post residual exactly, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            // next item fits but not perfectly: mild reward scaled by fit tightness
            let tight = 1.0 - ((pr - next_item_size) as f64) / cap;
            score -= 60.0 * tight;
        } else {
            // next item cannot use this residual: penalize large leftovers slightly
            score += (pr as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: empty bin gets baseline score near capacity,
    // adjusted so we only open new bins when existing fits are poor.
    if bin_residual == bin_capacity {
        score = cap * 0.75 + (open_bins_count as f64) * 2.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: must open new bin
        }
    }

    // Prefer filling tighter bins overall: closeness to mean residual
    let tightness = 1.0 - (bin_residual as f64) / cap;
    score += tightness * 30.0;

    // Early stream: be more conservative about opening bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity && progress < 0.2 {
        score += 50.0 * (0.2 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps smaller than the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 1000.0;
    }

    // Tight fits are rewarded
    score -= (bin_residual as f64 - item_size as f64).abs().min(50.0) * 0.5;

    // Pressure from number of open bins: prefer reusing bins when many are open
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 30.0;
    }

    // Slight bias toward mean residual alignment (avoid leaving bins far from pack norm)
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // New bin candidate: make it unattractive unless post_residual is large
    if bin_residual == bin_capacity {
        score += 50.0 + open_bins_count as f64 * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: exact match with next item is ideal.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 60.0; // perfect chain: item + next item fills bin
        } else {
            score += diff as f64 * 0.8; // penalize mismatch with lookahead
        }
        // Bonus when post_residual can still host next item comfortably
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // Last item: just minimize waste
        score -= 5.0;
    }

    // Tight fits are good: reward small post_residual relative to item size
    let fit_ratio = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 20.0 / (1.0 + fit_ratio);

    // Penalize leaving large dead space (< 10 unusable)
    if post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it unattractive unless no open bin fits well
    if bin_residual == bin_capacity {
        score += 45.0 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Compare against mean residual: bins tighter than average are preferred targets
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Late in stream: consolidate, avoid spreading across many bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small is already favored by base term,
    // but amplify the preference for near-perfect packing.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Lookahead: if the next item can fit into the post residual, reward this bin
    // (keeps a "slot" for the upcoming item); otherwise penalize wasted space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64) / (bin_capacity as f64);
        } else {
            // Post residual too small for next item: dead-space penalty scaled
            // by how close we are to the end of the stream (less worry early).
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 4.0 * (post_residual as f64 / bin_capacity as f64) * (0.5 + 0.5 * progress);
        }
    } else {
        // Last item: strongly prefer the fullest possible packing.
        score -= 10.0 * tightness;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Many open bins: discourage spreading items across too many bins;
    // prefer consolidating into existing bins when there are lots of them.
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score += 1.5 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Compare bin residual against the mean residual across open bins:
    // bins with below-mean residual (fuller bins) are preferred targets.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // New-bin candidate (empty bin): make it expensive unless current bins
    // are essentially full or cannot host future items well.
    if bin_residual == bin_capacity {
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        // Opening a new bin is penalized; the penalty shrinks if existing bins
        // are very full (mean residual low), allowing fresh bins when needed.
        score += 15.0 * (0.4 + 0.6 * mean_tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) matter more,
    // so amplify the quadratic reward for small residuals.
    let tightness = 1.0 - post / cap;
    score -= (1.0 + 2.0 * progress) * tightness * tightness * cap * 0.5;

    // Reward residuals that exactly accommodate the lookahead item (k=2).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        let norm_gap = gap / cap;
        score += norm_gap * norm_gap * cap * (0.3 + 0.7 * progress);
        // Bonus if post_residual leaves room for the next item.
        if post_residual >= next_item_size {
            score -= 8.0 + 10.0 * progress;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // Penalize bins far from the mean residual (prefer balanced fills),
    // with smooth coupling to progress.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * dev * cap * (0.2 + 0.5 * (1.0 - progress));

    // Mild penalty proportional to number of open bins: encourage consolidation.
    score += open_bins_count as f64 * (0.5 + 1.5 * (1.0 - progress));

    // New-bin candidate: baseline so it is chosen only when open bins score badly.
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of 10, or >= next common item size) are rewarded.
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Exact fit: perfect placement.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness reward: reward small post_residual non-linearly.
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 60.0 * tight * tight * tight;

    // Harmonic class penalty: post_residual in "dead zone" classes
    // (odd leftovers, tiny unusable slivers 1..10) are penalized.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 25.0; // unusable sliver
    } else if pr % 10 != 0 {
        score += 8.0;  // off-class leftover
    } else {
        score -= 5.0;  // on-class leftover (multiple of 10)
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size < pr {
            let npr = pr - next_item_size;
            // Harmonic class match between chained leftovers
            if npr % 10 == 0 { score -= 40.0; }
            if npr < 10 { score += 15.0; }
            score -= 20.0 * (1.0 - npr as f64 / cap);
        } else {
            // next item cannot use this leftover: penalize proportional to waste
            score += 10.0 + 0.1 * pr as f64;
        }
    }

    // Last chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no
    // open bin fits well. Penalize the fresh empty bin (residual == capacity)
    // unless the stream is early or many bins are open with poor mean residual.
    if bin_residual == bin_capacity {
        let base_penalty = 80.0;
        let relief = if fitting_bins_count == 0 { 500.0 } else { 0.0 };
        let mean_pressure = (mean_residual / cap - 0.5).max(0.0) * 60.0;
        score += base_penalty + mean_pressure - relief - 50.0 * (1.0 - progress);
    }

    // Mild diversity: avoid leaving many bins with near-identical large residuals
    // when mean residual is high (fragmentation guard).
    if post_residual as f64 > mean_residual + 0.35 * cap {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (min item size 1..100, but typical items are
    // chunky) are pure waste. Penalize a "dead zone" band harshly.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold {
        // Quadratic penalty inside the dead zone: smaller gap => worse.
        score += (dead_threshold - post_residual as f64).powi(2) * 0.8;
    }

    // Reward tight fits (small post_residual) super-linearly.
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    score -= fit_ratio * fit_ratio * 15.0;

    // Perfect/near-perfect closure gets a strong bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 3 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // Even better: next item leaves its own small residual too.
        let next_left = post_residual - next_item_size;
        if next_left <= 5 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; leftover is likely dead space.
        if post_residual > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than spreading; penalize this bin less
    // if open_bins_count is high (favor using existing bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score -= pressure * 2.0;

    // Mean residual coupling: if this bin's residual is far below the
    // mean, it's already "fragmented" relative to the fleet; using it
    // up is good. If it's near the mean and post_residual is large,
    // keep it for future items.
    let res_diff = mean_residual - bin_residual as f64;
    score += res_diff * 0.3;

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin has full residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no existing bin fits
        // well; make it moderately expensive so tight fits win.
        score += 12.0;
        // But if the item is large, a fresh bin is actually ideal.
        if item_size >= 60 {
            score -= 20.0;
        }
        // Early in the stream, opening bins is cheap and useful.
        if progress < 0.2 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual large enough for next item: proportional reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.4 * (post_residual as f64 - next_item_size as f64);
    } else if next_item_size > 0 {
        // Dead space relative to next item: penalize unusable gap.
        score += 0.6 * (next_item_size as f64 - post_residual as f64);
    }

    // Compare post_residual against mean residual of open bins:
    // leaving more than average is good (bin stays useful).
    score -= 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize very small post-residuals (wasted slivers), scaled by progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual < 10 {
        score += 20.0 + 10.0 * progress;
    }

    // Mild penalty for opening a new bin when many bins are already open.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: squared residual penalizes large leftover space superlinearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer filling the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Lookahead: if next item can fit into this bin's post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * (next_item_size as f64);
        // Bonus if the pair exactly fills the bin.
        if post_residual == next_item_size {
            score -= 150.0;
        }
    }
    // Penalize leaving post-residual that is too small for the lookahead item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 40.0 + 0.3 * (post_residual as f64);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current open bins are crowded (high mean fill) or many items remain.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mean_fill = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        // Prefer new bin when existing bins are quite full or few fit.
        let new_bin_attraction = 60.0 * mean_fill + 40.0 * progress + 10.0 * (open_bins_count as f64).min(20.0) / 20.0;
        score -= new_bin_attraction;
        // Slight caution: never make new bin free.
        score += 25.0;
    } else {
        // Penalize placing into bins whose residual deviates from mean (fragmentation).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Late in the stream, prefer closing bins tightly (waste matters more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64);

    // Small tie-break noise-free nudge toward fewer open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Core waste term: post_residual is the primary driver, but couple it
    // non-linearly with stream progress so late in the stream we push
    // harder toward tight fits (small post_residual).
    let pr = post_residual as f64;
    let waste = pr * pr / bin_capacity as f64;
    score += waste * (0.5 + 1.5 * progress);

    // Reward tight fits: the smaller the post_residual relative to item size,
    // the better the packing density.
    let tightness = 1.0 - pr / bin_capacity as f64;
    score -= 30.0 * tightness * tightness;

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly reward this placement; if it nearly fits, mild reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, heavily penalize
    // rejecting it (which would force a new bin).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // New-bin candidate: prefer it only when open bins have poor average fit.
    // Score it relative to mean residual so it competes fairly.
    if is_new_bin {
        // A fresh bin has residual == capacity, so its raw score is high;
        // discount it by the mean residual of open bins to reflect that
        // spreading waste across many open bins is bad.
        score -= 20.0 + 0.5 * mean_residual;
        // Early in the stream, opening bins is cheap and useful.
        score -= 30.0 * (1.0 - progress);
    }

    // Penalize excessive bin proliferation late in the stream.
    score += (open_bins_count as f64).sqrt() * 2.0 * progress;

    // Smooth non-linear coupling of post_residual with mean residual:
    // placing into a bin whose residual is far below average wastes less.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.1 * dev * dev / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of 10 are "clean"
    let pr = post_residual;
    let harmonic = (pr % 10) as f64;
    let harmonic_penalty = if harmonic == 0.0 {
        -6.0
    } else if harmonic <= 2.0 || harmonic >= 8.0 {
        -2.0
    } else {
        harmonic // mid residues leave awkward slivers
    };
    score += harmonic_penalty;

    // Integer-division thresholds: reward post_residual that fits a whole next item
    if next_item_size > 0 && next_item_size <= pr {
        let fits_chain = pr / next_item_size;
        score -= 8.0 + 3.0 * fits_chain as f64;
    } else if next_item_size > 0 {
        // next item cannot use this residual: dead space penalty scaled by waste
        score += (pr as f64) * 0.05 + 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer tighter fits among many candidates
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Perfect fill bonus
    if pr == 0 {
        score -= 15.0;
    }

    // Small residual but not zero: penalize unusable sliver
    if pr > 0 && pr < 10 {
        score += 4.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        let stream_progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // opening a new bin is bad early / when open bins still have room
        score += 20.0 - 15.0 * fragmentation - 10.0 * stream_progress;
        if open_bins_count == 0 {
            score -= 25.0; // must open
        }
    }

    // Mild preference for bins with residual close to item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1) are
    // impossible, but small unusable gaps are penalized super-linearly.
    // Treat gaps < 20 as "likely dead" since typical item sizes are >= 10.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 3.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are crowded
    if bin_residual == bin_capacity {
        score += 25.0;
        score += mean_residual.min(100.0) * 0.2;
    }

    // Lookahead: favor leaving room for the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Mild progression-based tightening: later in stream, prefer tighter fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching: reward bins whose post_residual
    // matches the next item size well.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match (next item exactly fills post residual) -> strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits after this placement: reward proportional to tightness.
            score -= 25.0 * (1.0 - lookahead_gap / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize wasted potential.
            score += 8.0 + 0.1 * lookahead_gap;
        }
    }

    // Tightness reward: smaller post_residual relative to capacity is better.
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins that deviate positively
    // (larger residual bins absorb items, keeping tight bins tight).
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual as i64 != next_item_size as i64 { 1.0 } else { 0.0 };
        score += 15.0 - 10.0 * poor_fit;
        // Early in stream, opening bins is cheaper; later, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * (1.0 - progress);
        // Many open bins with slack -> discourage new bins.
        score += 2.0 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Penalize creating tiny unusable slivers (< 10% capacity) unless exact match.
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // If the leftover space exactly fits the next item, strongly reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // If leftover space could fit the next item (partial lookahead), mild reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
    }
    // Penalize leaving dead space that is too small for the typical next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Compare against mean residual: bins with residual far below mean are "almost full",
    // prefer filling them; bins with large residual relative to mean stay flexible.
    score -= 10.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Time-horizon coupling: early in stream, keep bins flexible (penalize low post_residual
    // spread); late in stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage consolidation into emptier bins.
    if open_bins_count > 4 {
        score += 0.5 * (open_bins_count as f64).ln() * (bin_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: a fresh empty bin should only win when no open bin is decent.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted as the stream progresses.
        score = 55.0 + 20.0 * (1.0 - progress);
        // If many open bins with large mean residual, opening new bins is less attractive.
        score += 0.3 * open_bins_count as f64;
        // If the item fits well in an existing bin (post_residual small), penalize new bin more.
        if bin_residual >= item_size {
            let fit_quality = item_size as f64 / bin_capacity as f64;
            score += 25.0 * fit_quality;
        }
        // Last-chance override: never open a new bin if it is the only fitting option elsewhere.
        if fitting_bins_count == 1 {
            score += 60.0;
        }
        // If next item is large and current item leaves awkward residue, new bin gains appeal.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: minimize post residual, smoothly warped
    let mut score = 100.0 * (x * x);

    // Non-linear coupling of post residual with stream progress:
    // late in the stream, tight fills matter more
    let prog_coupling = (1.0 + progress) * (x - x * x) * 30.0;
    score += prog_coupling;

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_gap = (ns - pr).max(0.0) / cap;
        score += 40.0 * fit_gap * fit_gap * (1.0 + progress);
        // Reward when next item exactly fills remaining space
        let snug = 1.0 - ((ns - pr).abs() / cap).min(1.0);
        score -= 25.0 * snug * snug * x;
    } else {
        // last item: strongly prefer zero residual
        score += 60.0 * x * x;
    }

    // Last-chance bin bonus (smooth in fitting_bins_count)
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Mild penalty for scattering across many open bins
    let ob = open_bins_count as f64;
    score += 0.5 * (ob.ln() + 1.0) * (x * (1.0 - x)) * 4.0;

    // Reward closeness to mean residual (balance preservation), smooth quadratic
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: neutral-ish baseline; opening new bin only when residuals are large
    if bin_residual == bin_capacity {
        score = 55.0 + 40.0 * (1.0 - progress) - 0.0
            + if fitting_bins_count > 0 { 10.0 + 30.0 * (1.0 - x) } else { 0.0 };
        // discourage new bin if a snug fit exists elsewhere
        if next_item_size > 0 {
            let ns = next_item_size as f64;
            score += 20.0 * (1.0 - ((ns / cap) - (ns / cap) * (ns / cap)).abs());
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits and small dead space get rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;

    // Reward near-perfect fits (dead space in low harmonic classes).
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 10 {
        score -= 10.0;
    }

    // Modulo arithmetic on post_residual: residuals that are "harmonic" divisors
    // of common item sizes are more reusable.
    if pr > 0 {
        let mut reuse_bonus = 0.0;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                reuse_bonus += 8.0;
            }
        }
        if pr % 100 == 0 {
            reuse_bonus += 5.0; // empty bin (new-bin candidate)
        }
        score -= reuse_bonus;
    }

    // Penalize residuals that no plausible item (1..=80) can use efficiently.
    if pr > 0 && pr < 10 {
        score += 15.0; // dead space zone
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack <= 10 {
                score -= 20.0;
            } else {
                score -= 10.0 * (1.0 - slack as f64 / cap);
            }
        } else {
            // next item cannot follow here: mild penalty proportional to overshoot
            score += 5.0 + (next_item_size - pr) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no open
    // bin offers a good harmonic fit.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 + pressure * 0.5 - progress * 5.0;
        // discourage opening when a decent fit exists elsewhere
        if mean_residual >= item_size as f64 {
            score += 8.0;
        }
    }

    // Mild preference for bins tighter than the mean (best-fit flavor).
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Integer-division threshold: bins whose residual is in "useful band"
    // [20, 60] are more valuable to preserve than to waste.
    if pr >= 20 && pr <= 60 {
        score -= 5.0;
    } else if pr > 80 {
        score += 3.0; // wasteful large leftover
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are the worst outcome.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 60.0 * (1.0 - pr / 10.0); // tiny leftover = heavily penalized
    } else if pr == 0.0 {
        score -= 25.0; // perfect fit reward
    }

    // Prefer filling bins with the smallest residual (best-fit coupling).
    score += (bin_residual as f64 - item_size as f64) * 0.15;
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.05; // reward fuller bins

    // Lookahead: if next item fits the post residual, this placement is great.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            score -= 12.0 + 0.2 * n;
        } else {
            // post residual too small for next item -> dead space likely
            score += 8.0 * (1.0 - pr / bin_capacity as f64);
        }
    }

    // Open-bin pressure: discourage proliferation of bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly
    // (residual barely above item size means tight fits elsewhere).
    if bin_residual == bin_capacity {
        let spread = (mean_residual - item_size as f64).abs();
        score += 30.0 + 0.3 * open_bins_count as f64;
        if mean_residual < item_size as f64 + 5.0 {
            score -= 25.0; // open bins nearly full -> new bin reasonable
        }
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) < item_size as f64 {
            score -= 10.0;
        }
        let _ = spread;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual, but non-linearly.
    score = (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Exact fit bonus: zero post residual is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills the
    // remaining space; penalize when the leftover is unusable for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // leftover can host the next item: mild reward proportional to closeness
            let diff = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // leftover is dead space relative to the next item
            let waste = (next_item_size - post_residual) as f64;
            score += 15.0 * (waste / (bin_capacity as f64));
        }
    }

    // Compare against mean residual: bins with residual far below mean are
    // already "tight"; using them for a poor fit wastes their scarce space.
    if post_residual as f64 > mean_residual {
        score += 5.0 * (post_residual as f64 - mean_residual) / (bin_capacity as f64);
    } else {
        score -= 3.0 * (mean_residual - post_residual as f64) / (bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good fit (i.e. item barely fits anywhere) or the
    // stream is early and we want to keep large residual buffers alive.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins generally; relax penalty when open bins are all tight.
        score += 25.0;
        let avg_tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 20.0 * avg_tightness;
        // Early in the stream, keeping flexibility is valuable: extra penalty.
        score += 15.0 * (1.0 - progress);
        // If the item is large, a fresh bin may be the cleanest home.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
        // Lookahead: a fresh bin can host both this and the next item.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize very small dead space that nothing (min size 1) can use later anyway,
    // but reward leaving residuals that match typical upcoming needs.
    if post_residual > 0 {
        let usable = if post_residual >= next_item_size.max(1) { 1.0 } else { 0.0 };
        score += 8.0 * (1.0 - usable);
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 5.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidation.
    if open_bins_count > 2 {
        let spread = bin_residual as f64 - mean_residual;
        score += 0.05 * spread; // prefer below-average-residual bins (fuller bins)
        score += 0.3 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.5;
        let no_lookahead_room = next_item_size > 0 && post_residual < next_item_size;
        if poor_fit || no_lookahead_room || fitting_bins_count <= 1 {
            score -= 20.0; // open a fresh bin rather than fragmenting
        } else {
            score += 60.0; // keep using existing bins when fit is decent
        }
    }

    // Mild time-based exploration: early on, be greedy for tight fits; later, be conservative.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;
    let norm_next = next_item_size as f64 / bin_capacity as f64;

    // Non-linear coupling: squared post-residual, scaled by stream progress
    score += norm_post * norm_post * (1.0 + 2.0 * progress) * bin_capacity as f64;

    // Perfect-fit reward (smooth polynomial dip near zero residual)
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * tightness * 10.0;

    // Lookahead coupling: penalize residuals that neither fit nor nearly fit next item
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        let fit_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        score -= fit_next * (1.0 - gap / bin_capacity as f64) * 8.0 * (1.0 - progress);
        score += (gap / bin_capacity as f64) * (gap / bin_capacity as f64) * 5.0;
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early and when good fits exist
    if bin_residual == bin_capacity {
        let waste_penalty = norm_item * norm_item * 30.0;
        score += 20.0 + open_bins_count as f64 * 1.5 + waste_penalty * (1.0 - progress);
        // Allow new bin when residuals are fragmented (high mean residual spread)
        if mean_residual > 0.0 && mean_residual < norm_item * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Mild preference to fill bins below mean residual (compactness)
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.05;

    // Smooth progress-based consolidation: late in stream, prefer tightest bins extra
    score += progress * norm_post * norm_item * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "reusable" classes (large enough for common future items).
    let pr = post_residual;
    if pr > 0 {
        // modulo-10 class: residuals divisible by 10 are "clean"
        let cls = pr % 10;
        if cls == 0 {
            score -= 6.0;
        } else if cls <= 2 {
            score += 4.0; // nearly clean but awkward sliver
        }
        // integer-division thresholds: can it hold a mid-size item?
        let tier = pr / 20; // 0..5
        score -= tier as f64 * 2.5;
        if pr < 10 {
            score += 15.0; // dead space penalty
        }
    } else {
        score -= 20.0; // perfect fit
    }

    // Perfect-fit harmonic: item divides capacity evenly
    if bin_capacity % item_size.max(1) == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // harmonic match: next item divides residual cleanly
        if next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size > bin_residual {
        // next item needs a new bin anyway; prefer filling this bin fully
        score -= 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // penalize opening new bins early / when mean residual is generous
        score += 30.0
            + mean_residual * 0.3
            + (1.0 - progress) * 10.0
            - (open_bins_count as f64) * 0.5;
        if post_residual >= next_item_size {
            score -= 10.0; // fresh bin keeps room for lookahead
        }
    }

    // Mild preference for bins whose residual is below mean (tighter packing)
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly subtract when the item nearly fills the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Dead space penalty: residuals too small to hold the smallest plausible item (1..10)
    // are unusable; penalize them harshly, especially if next item can't use them.
    if post_residual < 10 {
        score += 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space relative to the lookahead item: gap is wasted for k=2.
        score += 12.0;
    } else if next_item_size > 0 {
        // Reward gaps that exactly or nearly fit the next item.
        let gap_diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 8.0 * (1.0 - gap_diff / bin_capacity as f64);
    }

    // Prefer bins whose residual is already small (consolidate large items into tight bins).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Open-bin pressure: with many open bins, discourage opening new bins;
    // make the new-bin candidate (residual == capacity) less attractive.
    if bin_residual == bin_capacity {
        score += 25.0 + 5.0 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Mild stream-progression term: late in the stream, be more conservative
    // about leaving medium gaps (less time to fill them later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact/near-exact fits (low post_residual)
    let fit_quality = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_quality * fit_quality;

    // 2-step lookahead: if next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let next_left = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - next_left / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to wasted post_residual
            score += 0.15 * post_residual as f64;
        }
    } else {
        // last item: minimize post_residual aggressively
        score += 0.5 * post_residual as f64;
    }

    // Relative to mean residual: bins with residual close to mean are "normal" targets;
    // penalize placing into bins with unusually large residual (save them) or tiny residual
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: only bin that fits the item -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 55.0;
        // but if next item is large and this item would leave a big awkward gap elsewhere,
        // opening new bin becomes relatively better
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 20.0;
        }
    }

    // Slight preference to fill older/more crowded bin sets
    score += 0.01 * open_bins_count as f64;

    // Mild stream-progress term: be greedier early, tighter late
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * fit_quality;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit bonus: reward placements that nearly fill the bin.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Exact fit is golden.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Penalize dead space that no future item (10..80 range, but unknown dist 1..100) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // sliver unusable under original range
    }

    // Lookahead coupling: reward bins whose residual after placement can host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 * (next_item_size as f64 / 100.0);
            // chain bonus if next item then leaves little slack
            let chain_left = post_residual - next_item_size;
            if chain_left < 15 {
                score -= 12.0;
            }
        } else {
            // next item won't fit here; penalize moderately
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer better fits (already via tightness)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate arbitration: opening a new bin is expensive;
    // only attractive when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 30.0;
        // cheaper to open when open bins are fragmented (high mean residual spread)
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 10.0 * (fragmentation / bin_capacity as f64);
        // late in stream, prefer filling existing bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
        // if many bins already open, discourage another
        score += 3.0 * (open_bins_count as f64);
        // if item is large relative to capacity, new bin is fine (avoids stranding)
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    // Global pressure: when few bins fit the item anywhere, keep good residuals.
    let pressure = 1.0 - (fitting_bins_count as f64 / (open_bins_count.max(1) as f64 + 1.0));
    score += 10.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Mild preference to balance residuals across bins mid-stream.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = item_size as f64 / cap;

    // Core: prefer small post-residual, with smooth polynomial coupling to progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Penalize residuals that no plausible future item can use (dead space), smoothly
    let dead = (pr / cap).powi(3);
    score += 40.0 * dead * (0.5 + progress);

    // Reward tight fits (high tightness) smoothly
    score -= 10.0 * tightness * tightness * (1.0 - progress * 0.5);

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 15.0 * (1.0 - gap / cap).max(0.0);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight penalty when many bins open (encourage consolidation), smooth in count
    score += 0.5 * (open_bins_count as f64).ln() * (1.0 - progress);

    // Prefer bins near mean residual (balanced packing)
    score += 0.2 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of post_residual (mod-10 buckets, capacity fractions) ----
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = post_residual / 10; // harmonic bucket id
    // Dead-space penalty: residuals that no plausible item (1..=100) can use well
    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Residuals that are "harmonic" (multiples of 10, small) are more reusable.
        let harmonic = if post_residual % 10 == 0 { 0.0 } else { 8.0 + (post_residual % 10) as f64 };
        score += harmonic;

        // Fractional-capacity coupling: small residuals relative to capacity are risky.
        let frac = pr / cap;
        if frac < 0.10 {
            score += 12.0 * (0.10 - frac) * 10.0; // nearly full bin: fine, but tiny residue
        }
        // Awkward middle zone (30..60) is the worst dead space for unknown distributions.
        if pr >= 30 && pr < 60 {
            score += 10.0;
        }
        // Very large residual after placement means we barely used the bin: penalize
        // mildly so dense packing is preferred over spreading.
        if pr > 70 {
            score += (pr - 70.0) * 0.5;
        }
    }

    // ---- Lookahead coupling with next_item_size ----
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // next item exactly fills this bin: reserve it!
        } else if next_item_size <= post_residual {
            // Next item fits here too: reward proportional to how well it couples.
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 - gap.min(40.0);
        } else {
            // Next item cannot use this bin's residue: penalize if residue is small-ish.
            if post_residual < next_item_size {
                score += 3.0;
            }
        }
        // Harmonic bucket match: residue class of bin matches next item class.
        if post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 {
            score -= 15.0;
        }
    }

    // ---- Last-chance bin: if this is the only fitting bin, strongly prefer using it ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is generally bad while open bins fit well,
        // but attractive when item is huge relative to mean residual (poor fits ahead).
        let tight_fit = (bin_capacity - item_size) as f64;
        score = tight_fit + 25.0; // base disadvantage for new bin
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 20.0; // future items are big: fresh bin useful
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // no open bin fits: must open
        }
        if open_bins_count > 0 && item_size >= 70 {
            score += 10.0; // large items prefer squeezing into existing space
        }
    }

    // ---- Stream progression: pack tighter as stream advances ----
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    // ---- Open-bin pressure: many open bins -> consolidate ----
    if open_bins_count > 3 {
        score += (open_bins_count as f64 - 3.0) * (post_residual as f64 / cap) * 2.0;
    }

    // Mean residual coupling: prefer bins deviating favorably from mean.
    score += 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible future item are pure waste. Penalize hard.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold {
        // Perfect or near-perfect fill -> strong reward.
        score -= 60.0 + 2.0 * (dead_threshold - post_residual as f64);
    } else if post_residual == 0 {
        score -= 100.0;
    }

    // Non-linear penalty on mid-size wasted gaps (waste grows super-linearly).
    if post_residual > 0 {
        let r = post_residual as f64;
        score += 0.02 * r * r / bin_capacity as f64;
    }

    // If a future item could still fit in the post-residual, reward keeping it usable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If the lookahead item no longer fits here, the gap risks becoming dead space.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items into
    // yet another bin; prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is below the mean (consolidating fuller bins),
    // penalize dipping into the emptiest bins for small items.
    if (bin_residual as f64) > mean_residual * 1.3 && item_size < 40 {
        score += 8.0;
    }

    // New-bin candidate (empty bin): only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0; // forced new bin
        } else {
            // Opening a new bin while others fit is wasteful unless this item
            // would leave a terrible gap elsewhere.
            let gap_elsewhere = (bin_residual - item_size) as f64;
            if gap_elsewhere < dead_threshold {
                score -= 30.0; // tight fit exists -> still prefer it over new bin slightly less
            } else {
                score += 20.0 + open_bins_count as f64 * 2.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward if the next item fits exactly into the post residual (2-step lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Reward proportional to how much of the next item can be absorbed,
            // but penalize leftover slack beyond it.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.15 * slack;
        } else {
            // Next item won't fit here after placement: penalize dead space.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    }

    // Penalize very small post residuals (unusable dead space), unless zero (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 30.0;
    }

    // Prefer bins whose residual is close to the item (tight fits).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Prefer bins with residuals below the mean residual (denser bins first).
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Mild penalty for opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 20.0; // fresh bin great for chaining large items
        }
    }

    // Slight preference for consolidating into fewer bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor placements that nearly fill the bin.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize creating dead space too small for typical items (1..=10 useless gap).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Favor bins whose residual is already small relative to the mean
    // (consolidate waste into few bins).
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        score += 4.0 * (rel - 1.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward heavily; if post-residual can't fit next item but could fit
    // something useful, mild preference.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            // Next item won't fit here; slightly penalize wasting large residual.
            score += 2.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: opening a new bin is expensive early on
    // (bins stay open) but acceptable when open bins are crowded or the fit
    // among existing bins is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / 8.0;
        let poor_fits = if fitting_bins_count == 0 { 20.0 } else { 0.0 };
        // Base penalty for opening a new bin, softened by crowding/progress.
        let base = 30.0 - 10.0 * progress - 2.0 * crowding.min(3.0) + poor_fits;
        // If the item is large, a fresh bin is more attractive.
        let large_item = (item_size as f64 / bin_capacity as f64) * 10.0;
        score += base - large_item;
        // If next item is large and won't fit anywhere else anyway, new bin ok.
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Mild penalty for accumulating many open bins (encourage closing bins out).
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post residual
    let pr = post_residual as f64 / cap;
    let fill = 1.0 - pr;

    // Non-linear polynomial coupling: reward high fill with progress-dependent weight
    let fill_coupling = fill * fill * (0.5 + 1.5 * progress);
    score -= fill_coupling * cap;

    // Penalize small dead space that is hard to reuse (non-linear valley)
    let dead = pr * pr * (1.0 - pr);
    score += dead * cap * (1.0 - 0.5 * progress);

    // Lookahead: bonus if next item fits the post residual smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post_residual as f64 {
            let tight = 1.0 - (post_residual as f64 - nx) / cap;
            score -= 4.0 * tight * tight;
        } else {
            score += 3.0 * (nx / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: penalize slightly so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score += 5.0 + 4.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.5 * ((bin_residual as f64 - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic class of post_residual: dead space in low classes (0..=5) is very costly.
    let class = (post_residual / 10).min(8) as f64;
    score += (8.0 - class) * 2.5;

    // Reward near-perfect fits superlinearly.
    if post_residual <= 3 {
        score -= 30.0;
    } else if post_residual <= 8 {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let nxt_class = ((post_residual - next_item_size) / 10).min(8) as f64;
            score -= 10.0 - nxt_class;
        }
    }

    // New-bin candidate: penalize unless no open bin fits or this is a last-chance situation.
    if is_new_bin {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 18.0 + 10.0 * (1.0 - progress) };
        score += scarcity;
        // Opening a bin is more attractive when mean residual across open bins is high (fragmented).
        score -= (mean_residual / bin_capacity as f64) * 8.0;
    } else {
        // Reward using bins with low residual (tight packing) mildly.
        score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;
        // Last chance bin: strongly favor using it.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Mild preference to consolidate into fewer bins early on.
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never be filled again
    // (smaller than the smallest plausible item) are pure waste.
    let min_item = 1u32;
    if post_residual < 10 {
        // tiny unusable gap -> heavy penalty, scaled by how close to wasted
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    } else if post_residual == 0 {
        // perfect fit: strong reward
        score -= 80.0;
    } else {
        // reward leaving residuals that are still usable for typical items
        let usable = post_residual >= min_item;
        if usable {
            // mildly reward mid-range residuals that many item sizes can use
            score -= 10.0 * ((post_residual as f64) / bin_capacity as f64).min(0.5);
        }
    }

    // Tight-fit reward: prefer bins where the item occupies a large fraction.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new bin is cheap.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): penalize slightly so we only open new
    // bins when the fit into existing bins is poor (large post_residual there).
    if bin_residual == bin_capacity {
        score += 25.0 + 0.1 * open_bins_count as f64;
    } else {
        // existing bin that fits well relative to mean residual gets a bonus
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_tightness = next_item_size as f64 / post_residual as f64;
        score -= 15.0 * lookahead_tightness;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use the leftover: penalize creating stranded space
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio).powi(6);

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item could chain into this bin: reward tight chaining.
            score -= 25.0 * (1.0 - gap / bin_capacity as f64).powi(3);
        } else {
            // Dead space the next item cannot use: penalize.
            score += 8.0 * (1.0 - gap / bin_capacity as f64);
        }
    }

    // Compare against mean residual: bins already tighter than average are precious.
    score += 0.35 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: only bin that fits, avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize the brand-new empty bin candidate unless the fit elsewhere is terrible.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * item_size as f64;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: square the post-residual penalty.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Penalize opening a new bin when existing bins fit, unless fit is very tight.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Opening new bin is good only if item is huge (leaves small residual)
        score += 25.0 * (1.0 - tightness).powi(2);
        // Discourage new bins when many open bins can already fit the item
        score += 6.0 * fitting_bins_count as f64;
        // Early in stream, opening bins is cheaper (spread items out)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    } else {
        // Last-chance bonus: if this is the only fitting bin, strongly favor it.
        if fitting_bins_count == 1 {
            score -= 18.0;
        }
        // Reward using bins whose residual is close to the mean (balance load)
        score += (bin_residual as f64 - mean_residual).abs() * 0.15;
        // Slight preference for fuller bins (smaller residual) to consolidate
        score += (bin_residual as f64 / bin_capacity as f64) * 4.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 30.0;
        } else {
            score -= 12.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize leaving dead space next item can't use
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Late in stream, be conservative: avoid opening bins / spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && !is_new_bin {
        score -= 3.0;
    }

    // Mild penalty proportional to number of open bins to encourage consolidation
    score += open_bins_count as f64 * 0.05 * if is_new_bin { 1.0 } else { -1.0 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), with non-linear sharpening.
    let mut score = post * (1.0 + 0.8 * post / cap);

    // Dead-space penalty grows super-linearly for unusable gaps.
    let dead = post / cap;
    score += 12.0 * dead * dead;

    // Tightness reward: near-perfect fills subtract.
    let tightness = 1.0 - (post / cap);
    score -= 8.0 * tightness * tightness * tightness;

    // Stream-progress coupling: early on, keep bins flexible (favor moderate residuals);
    // late in stream, strongly prefer minimal post_residual.
    let flex = (1.0 - progress) * (1.0 - progress);
    score += 6.0 * flex * (post / cap) * (1.0 - post / cap);
    score -= 10.0 * progress * progress * (1.0 - post / cap);

    // Lookahead: reward if next item fits the post residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_ratio = nxt / post.max(1.0);
            score -= 6.0 * fit_ratio * (1.0 - fit_ratio);
            // perfect chain: next item exactly fills
            score -= 4.0 * (1.0 - (post - nxt).abs() / cap);
        } else {
            // next item won't fit here; penalize leaving a gap that wastes capacity
            let gap = (post - (nxt - post).min(post)) / cap;
            score += 5.0 * gap * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's an outlier; consolidating there is good.
    let dev = resid - mean_residual;
    score -= 0.05 * dev;

    // New-bin candidate handling: empty bin gets a mild opening cost that
    // decays as the stream progresses, so late items prefer existing bins
    // unless the fit is terrible elsewhere.
    if bin_residual == bin_capacity {
        let open_cost = 20.0 * (1.0 - 0.5 * progress);
        score += open_cost;
        // but opening is attractive if item is large (would leave big gap elsewhere)
        score -= 0.15 * item;
    }

    // Small jitter-free tie-break on residual to break exact ties deterministically.
    score += 0.001 * (cap - resid);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits strongly (harmonic-style in post_residual)
    if post_residual > 0 {
        score -= 60.0 / post_residual as f64;
    } else {
        score -= 80.0; // perfect fill
    }

    // Harmonic class: post_residual in low classes is dead space
    let cls = post_residual % 10;
    if cls != 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= 15.0 / (post_residual - next_item_size) as f64;
        } else {
            // next item can't use leftover; penalize proportional waste
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; higher when many bins already open
        score = cap * 0.9 + 2.0 * open_bins_count as f64;
        // If few bins can fit, opening new bin is more acceptable
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If an open bin would end with tiny residual, opening new bin is fine
        if post_residual < 5 {
            score -= 10.0;
        }
    }

    // Prefer bins below mean residual (less-filled bins get used first)
    score -= 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item (>=1) can use well.
    // Post-residuals in [1, 9] are "dead space" -> heavy penalty.
    let dead_zone = (1..=9).contains(&post_residual);
    if dead_zone {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Reward near-perfect packing (post_residual == 0 is ideal).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 15 {
        // Usable small gap: mild reward proportional to tightness.
        score -= 10.0 * (1.0 - post_residual as f64 / 15.0);
    }

    // Penalize large leftover gaps that could have been filled by the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Next item could still fit here; slight penalty for wasted opportunity structure.
        score -= 2.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap is too small for the lookahead item -> likely dead space; penalize.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight fit exists.
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    if bin_residual != bin_capacity {
        score -= 5.0 / (1.0 + bin_pressure);
    }

    // New-bin candidate: baseline score = full capacity; only win if all open bins score worse.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.85 + open_bins_count as f64 * 0.5;
        // Late in the stream, be more willing to open bins (fewer future consolidation chances).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
    }

    // Mild reward for matching mean residual (keeps bins homogeneous).
    score -= 0.05 * (mean_residual - post_residual as f64).abs().recip().min(5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (best fit style)
    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual,
    // reward strongly (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how well next item fits, but penalize leftover
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            score += 0.5 * slack;
        } else {
            // next item does not fit in the residual -> dead space risk
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.35 * overshoot;
        }
    }

    // Compare post_residual relative to mean residual across open bins:
    // leaving less than average residual is good (tight packing).
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last chance bin: if this is the ONLY bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when the fit is poor.
    if bin_residual == bin_capacity {
        // penalize opening a new bin unless the item leaves a bad residual
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += 30.0; // base cost of opening a new bin
        if post_residual <= 20 {
            score -= 35.0; // very tight fit elsewhere is unlikely; new bin is fine
        }
        if tightness > 0.5 {
            score += 10.0 * (tightness - 0.5); // wasteful large residual in fresh bin
        }
    }

    // Slight preference to fill bins that are already mostly full (low residual)
    score += 0.1 * (bin_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // Early in the stream, be a bit more willing to open bins (future flexibility)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            score += 4.0;
        }
        // Chain fit: leftover fits next item with room to spare after.
        if post_residual >= next_item_size && post_residual.saturating_sub(next_item_size) >= item_size.min(20) {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening new bins when good alternatives exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64) / (1.0 + mean_residual / bin_capacity as f64);
        score += 18.0 + 10.0 * progress + 0.5 * pressure;
        // But allow new bin if item is huge relative to mean residual (poor fits everywhere).
        if (item_size as f64) > mean_residual + 15.0 && fitting_bins_count <= 1 {
            score -= 22.0;
        }
    }

    // Prefer fuller bins among open ones (residual close to item size).
    let slack = (bin_residual - item_size) as f64;
    score += 0.02 * slack;

    // Mild bonus for consolidating into bins with low mean residual state.
    score -= 0.01 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear penalty on wasted fraction (quartic coupling of fill ratio)
    let fill = 1.0 - pr / cap;
    score -= 12.0 * fill * fill * fill * fill * cap;

    // Tight fit reward: smooth gaussian-like coupling of post_residual to item size
    let tight = (pr - it * 0.5) / (it.max(1.0));
    score -= 6.0 * (-tight * tight).exp() * (1.0 + progress);

    // Penalize post_residual that no plausible future item can use (smooth valley around small residuals)
    let dead = pr / cap;
    score += 8.0 * dead * dead * (1.0 - dead) * cap * (0.5 + progress);

    // Last-chance bin: strongly favor using it rather than opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize smoothly unless current fit is poor
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let fit_quality = pr / cap; // = 1 - item/cap for empty bin
        score += 10.0 + 20.0 * progress - 25.0 * (1.0 - fit_quality) * (1.0 - fit_quality);
        if next_item_size > 0 {
            // lookahead: opening a new bin is good if next item pairs with this one
            let pair = (it + next_item_size as f64) / cap;
            if pair <= 1.0 {
                score -= 12.0 * (1.0 - pair);
            } else {
                score += 10.0 * (pair - 1.0);
            }
        }
    } else {
        // Favor bins whose residual is close to mean residual (balanced packing), smooth coupling
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 4.0 * dev * dev;
    }

    // Slight preference for fewer open bins as stream progresses
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post_residual is small.
    let tight = if post_residual == 0 {
        -60.0
    } else {
        -40.0 * (1.0 - post_residual as f64 / bin_capacity as f64)
    };
    score += tight;

    // Harmonic class logic: classify post_residual into modulo classes of the
    // capacity; classes with small residue (near-perfect packing) get rewarded.
    let half_cap = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    let class_bonus = match post_residual {
        0 => -50.0,
        r if r <= quarter => -25.0,
        r if r > quarter && r <= half_cap => 0.0,
        _ => 10.0,
    };
    score += class_bonus;

    // Integer-division threshold: post_residual bucket via division by 10.
    let bucket = post_residual / 10;
    score += bucket as f64 * 1.5;

    // Lookahead coupling: reward if next item can use the post_residual exactly
    // or nearly; penalize if next item would leave another big hole.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let nxt_waste = post_residual - next_item_size;
            score -= 20.0 * (1.0 - nxt_waste as f64 / bin_capacity as f64);
        } else {
            // Next item cannot fit here anyway; slight penalty for medium holes.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or when open bins are nearly full (low mean residual).
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count > 0 {
            (bin_capacity as f64 - mean_residual) / bin_capacity as f64
        } else {
            0.0
        };
        // New bin starts with full residual; penalize opening unless pressure high.
        score += 35.0 * (1.0 - pressure);
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Slight preference to fill older bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress;

    // Mild penalty when bin residual deviates far from mean residual (balance).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item can use are pure waste.
    // Any gap smaller than the smallest possible item (1) is impossible, but gaps that
    // cannot fit the lookahead item are strongly penalized (wasted relative to lookahead).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space with respect to the next item: penalize proportionally,
            // extra harsh when the gap is tiny (unusable for most sizes).
            score += (next_item_size - post_residual) as f64 * 1.5;
            if post_residual < 10 {
                score += 20.0;
            }
        } else {
            // Reward bins whose leftover can still host the next item.
            score -= 5.0;
        }
    }

    // Non-linear penalty on very small post_residuals (classic "best-fit trap"):
    // a residual of exactly 0 is perfect; residuals of 1..=5 are near-dead.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score += (6 - post_residual) as f64 * 4.0;
    }

    // Open-bin pressure: discourage scattering items across many open bins
    // unless the fit is excellent. Scales with fraction of stream completed.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild preference toward bins tighter than average (good consolidation).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: neutral-ish baseline; only chosen when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 10.0 + post_residual as f64 * 0.5;
        // Opening a new bin is more acceptable early when few bins are open.
        score -= open_bins_count as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect/near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, huge reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 150.0;
        }
        // Penalize leaving residual that neither fits next item nor is tiny.
        if post_residual < next_item_size && post_residual > 15 {
            score += 40.0;
        }
    }

    // Relative to mean residual: prefer bins with less residual than average (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.8;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if next item is large and this new bin would be clean, slightly soften.
        if next_item_size >= 50 {
            score -= 20.0;
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Many open bins: prefer filling existing ones.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tight = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 6.0 * tight * tight;

    // Penalize leaving dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are wasted capacity
    }

    // Lookahead: bonus if next item fits exactly in the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // next item won't fit here; slight penalty for poor chaining
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: discourage opening new bins unless
    // the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress:
        // early in the stream, opening bins is cheaper (more future use);
        // late in the stream, prefer packing into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 40.0 * progress;

        // If many bins can fit, opening a new bin is almost always bad.
        if fitting_bins_count > 1 {
            score += 25.0;
        }
        // If the item would leave a very large residual in an open bin anyway,
        // a fresh bin is more tolerable.
        let best_alt = if fitting_bins_count > 0 { mean_residual } else { bin_capacity as f64 };
        if best_alt < item_size as f64 + 5.0 {
            score -= 15.0;
        }
    } else {
        // Reward reusing bins that are already partially filled,
        // scaled by how full they are relative to the mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Mild pressure to consolidate when too many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * (1.0 - progress) * 12.0;
    score -= coupling;

    // Reward tight fits, stronger later in the stream
    let tight = (1.0 - norm_pr) * (1.0 - norm_pr) * progress * 8.0;
    score -= tight;

    // Penalize residual that cannot fit the lookahead item (dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - pr) * (0.5 + progress) * 2.0;
    }

    // Reward when lookahead item exactly fits the post residual
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 6.0 + 4.0 * progress;
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Mild penalty for opening new bins when many bins already open
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * (1.0 - progress);
    }

    // Mean residual interaction: prefer bins below mean residual (tighter)
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common item
    // sizes are more likely to be filled by future items.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Residue classes modulo small integers (harmonic classes of capacity).
    let mut bonus = 0.0;
    for m in [2u32, 5, 10, 20, 25, 50] {
        if post_residual % m == 0 && post_residual > 0 {
            bonus += 6.0 * (m as f64).sqrt();
        }
    }
    score -= bonus;

    // Penalize tiny dead space that no item (min size 1..10) can use well:
    // post_residual in awkward bands (1..10 or 11..19 non-harmonic) is dead.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Lookahead coupling: if next item fits exactly or well into post_residual,
    // reward strongly (harmonic match between residual and next item).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let new_res = post_residual - next_item_size;
            score -= 12.0;
            if new_res % 10 == 0 {
                score -= 8.0;
            }
        }
        // next item near-miss: penalize if next item just barely doesn't fit
        if next_item_size > post_residual && next_item_size - post_residual <= 10 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    // Many fitting bins: prefer the tightest fit (score already grows with
    // post_residual), but add mild penalty for spreading across many bins.
    if fitting_bins_count > 3 {
        score += 2.0;
    }

    // New-bin candidate: default attractive when open bins have small mean
    // residual relative to item size (poor fits everywhere).
    if bin_residual == bin_capacity {
        let poor_fits = mean_residual < item_size as f64 * 0.6;
        if poor_fits || fitting_bins_count == 0 {
            score -= 20.0 + 10.0 * (1.0 - progress);
        } else {
            score += 15.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Tight fit reward: residual close to item size.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 15.0 * (1.0 - tightness * tightness);

    // Late in stream, consolidate: penalize leaving many open bins loose.
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero residuals are worst.
    let dead_zone = 15.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 4.0;
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fills relative to capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    score += open_bins_count as f64 * 0.8;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count >= 1 {
            score += 25.0;
        }
        // More attractive early when few bins exist.
        score -= 15.0 / (1.0 + open_bins_count as f64);
    }

    // Lookahead: if next item can use the post residual, reward leaving that gap.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 5.0;
        }
    }

    // Slight preference for bins below mean residual (evening out load).
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize exact-zero waste
    // only mildly (perfect fits are great).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: reward when next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward proportional to how snugly the next item will fit.
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 12.0 + 10.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // Post-residual cannot host next item: penalize dead space that is
            // smaller than next_item_size (unusable for the lookahead).
            let dead = post_residual as f64;
            if dead > 0.0 && dead < next_item_size as f64 {
                score += 6.0 + 0.25 * dead;
            }
        }
        // Bonus if post_residual matches next item size exactly.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: just minimize waste.
        score -= 5.0;
    }

    // Coupling with mean residual: bins far below mean residual are "fresher";
    // prefer packing into bins whose residual is above mean (older, emptier bins),
    // keep low-residual bins for small future slack.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.08 * diff;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, tighten preference for smallest post_residual.
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Opening a new bin is attractive when the item fits poorly everywhere else
    // (large post_residual would be wasted) or late in the stream when many
    // bins are already open and fragmented.
    if bin_residual == bin_capacity {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        // Cost of a new bin decreases as stream progresses (amortized over
        // remaining items) but a fresh bin should only win when current fits
        // are bad. Base new-bin score is its post_residual plus a fixed overhead.
        score = post_residual as f64 + 18.0 - 10.0 * progress;
        // If post_residual is large (item is small relative to capacity), a new
        // bin preserves lots of usable space: discount.
        score -= 8.0 * waste_ratio;
        // If no other bin fits well, new bin becomes relatively better.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Mild late-stream consolidation: favor existing bins over proliferation.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: smaller post_residual already favored, amplify it
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize creating dead space that the lookahead item cannot use.
    // If next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect pairing
        } else if next_item_size <= post_residual {
            // leftover after the pair would be post_residual - next_item_size
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - pair_waste / bin_capacity as f64);
        } else {
            // next item cannot use the residual: penalize proportionally
            score += 0.08 * (post_residual as f64 - mean_residual).max(0.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity when
    // existing bins fit reasonably well. Base penalty for the empty bin.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 6.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them)
        new_bin_penalty *= 1.0 - 0.5 * progress;
        // If many bins are open with large mean residual, spreading is fine
        if mean_residual > item_size as f64 + 20.0 {
            new_bin_penalty -= 3.0;
        }
        // If the item is large relative to capacity, poor fits are likely elsewhere
        if item_size > bin_capacity / 2 {
            new_bin_penalty -= 2.0;
        }
        // If very few bins fit and mean residual is small, new bin is attractive
        if fitting_bins_count <= 1 {
            new_bin_penalty -= 15.0;
        }
        score += new_bin_penalty;
    }

    // Mild preference to consolidate into bins with below-average residual
    // (keeps a pool of large-residual bins alive for big items).
    if bin_residual != bin_capacity {
        score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Late-stream consolidation: near the end, avoid opening new bins
    if progress > 0.9 && bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer small post-residual, with mild non-linear convexity.
    let mut score = pr.powf(1.15);

    // Smooth stream-progress coupling: later in the stream, waste matters more.
    let progress_weight = 0.5 + 1.5 * t * t;
    score *= progress_weight;

    // Tight-fit reward (smooth, quadratic in fill fraction).
    let fill = 1.0 - pr / cap;
    score -= 12.0 * fill * fill * cap * 0.01;

    // Last-resort bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * t;
    }

    // Lookahead coupling: penalize post-residual that cannot host next item
    // (dead space), reward post-residual that can.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            let gap = (nx - pr) / cap;
            score += 30.0 * gap * gap * cap * 0.05;
        } else {
            let slack = (pr - nx) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 - slack);
        }
    }

    // Penalize bins deviating from mean residual mildly (keeps residual spread balanced).
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * cap * 0.02;

    // New-bin candidate: bin_residual == bin_capacity implies pr = cap - item_size;
    // add a fixed opening cost so a new bin only wins when fits elsewhere are poor.
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "usable slots"
    // for common small item sizes (mod classes), penalize dead space.
    let pr = post_residual;
    if pr > 0 {
        let usable = if pr % 10 == 0 {
            1.0
        } else if pr % 5 == 0 {
            0.7
        } else if pr >= 10 {
            0.4
        } else {
            0.0
        };
        score -= 12.0 * usable;
    } else {
        // Perfect fit: heavily reward closing a bin exactly.
        score -= 60.0;
    }

    // Dead-space penalty: residuals too small for the minimum item size.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            // how well the next item's leftover again lands in a good class
            let nxt_left = pr - next_item_size;
            if nxt_left % 10 == 0 {
                score -= 15.0;
            } else if nxt_left < 10 {
                score += 10.0;
            }
            score -= 5.0;
        } else {
            // next item cannot use this bin's remainder: mild penalty
            score += 8.0;
        }
    }

    // Tightness reward: prefer bins where the item fills a large fraction.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: neutral baseline, penalized slightly so we
    // prefer reusing open bins unless the fit is clearly bad; but if existing
    // bins would leave large dead space, the new bin becomes attractive.
    if bin_residual == bin_capacity {
        score = cap - (item_size as f64);
        score += 5.0; // mild preference for existing bins by default
        if fitting_bins_count >= 1 {
            let best_possible = mean_residual;
            if best_possible - (item_size as f64) > 30.0 {
                score -= 20.0; // existing fits are wasteful; open new bin
            }
        }
        // early stream: keep fewer bins open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Spread pressure: many open bins -> favor consolidating into fuller bins.
    score += (open_bins_count as f64) * 0.5;

    // Mean residual alignment: prefer bins whose residual is near the mean
    // (keeps bin states uniform, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1) are impossible,
    // but residuals just above typical small items are "unusable" if next item can't use them.
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 500.0;
    } else if post_residual < 10 {
        // Tiny dead gap: heavily penalize (waste with near-zero reuse chance).
        score += 200.0 + 20.0 * (10.0 - post_residual as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Lookahead: next item cannot fit into this residual -> dead space for k=2 horizon.
        score += 60.0 + 0.5 * post_residual as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Residual is reusable by the lookahead item: reward.
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - 0.3 * slack;
    }

    // Tight fit bonus: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 100.0 * fill;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize new-bin / spreading behavior).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: brand-new empty bin gets a fixed opening cost,
    // only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 120.0 + 3.0 * open_bins_count as f64;
        // If the item fits very well in a fresh bin (large item), soften the cost.
        if fill > 0.7 {
            score -= 60.0 * fill;
        }
    } else {
        // Existing bin: reward being close to mean residual (balanced packing),
        // penalize bins far below mean (fragmenting behavior).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.5 * dev;
    }

    // Mild recency: late in the stream, prefer filling bins nearly full.
    if bin_residual != bin_capacity {
        score -= 30.0 * progress * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (small post_residual is already favored by base score).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Bonus decays with leftover slack after hypothetically placing next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.3 * slack;
        } else {
            // Penalize residuals too small for the next item (dead space risk),
            // scaled by how far short the residual falls.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare against mean residual of open bins: prefer bins with residual
    // below mean (tighter bins get filled first, keeping large residuals open).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.4 * (mean_residual - res);
    } else {
        score += 0.6 * (res - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad
    // or the item would leave a large awkward residual. Scaled by stream progress
    // (early on, opening bins is cheaper; late, consolidation matters more).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 40.0 * progress;
        // If next item is small enough to chain into a fresh bin, soften penalty.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
        }
        // If no existing bin fits well, opening a new bin is reasonable.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild preference to spread load when many bins are open with high residuals.
    if open_bins_count > 3 && mean_residual > 50.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) super-linearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tight * tight * tight;

    // Penalize leaving residuals that are awkward (small but nonzero, hard to fill).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; slight penalty for creating fragmented space
            score += (next_item_size as f64 - post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // many alternatives: be picky, penalize loose fits more
        score += (post_residual as f64) * 0.1;
    }

    // New-bin candidate: only attractive when current fits are poor.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / (bin_capacity as f64);
        let bad_fits = if post_residual == bin_capacity {
            // evaluating new bin for this item: post_residual == capacity means item placed alone
            (bin_capacity - item_size) as f64
        } else {
            0.0
        };
        // base cost of opening a bin, discounted when open bins are nearly full
        score = bad_fits + 20.0 * (1.0 - pressure) + (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 1 {
            score += 40.0; // never open when a last-chance bin exists
        }
        // late in stream, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Mild preference for fuller bins globally.
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 30.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    let tight = 1.0 - norm_pr;
    score -= tight * tight * (10.0 + 20.0 * progress);

    // Penalize creating dead space unusable by the lookahead item
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild penalty when many bins are open and residual is wasteful
    score += (open_bins_count as f64).ln() * norm_pr * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Harmonic class of post_residual: integer division into capacity-fraction buckets.
    // Buckets of width 10 (C/10): 0 = perfect fill, higher = more waste.
    let bucket = post_residual / 10;
    score += (bucket as f64) * 4.0;

    // Perfect-fit reward: post_residual exactly 0.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item (<=10 unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Next-item coupling: if next_item_size fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // harmonic class: does post_residual % next_item_size leave a clean split?
            let rem = post_residual % next_item_size;
            score -= (next_item_size as f64) * 0.5;
            if rem == 0 {
                score -= 20.0; // next item tiles the residual perfectly
            } else {
                score += (rem as f64) * 0.3; // messy leftover
            }
        } else {
            // next item cannot fit here; penalize large residual that invites fragmentation
            score += ((next_item_size - post_residual) as f64) * 0.2;
        }
    }

    // Capacity fraction coupling: item size relative to capacity (eighths).
    let item_class = (item_size * 8 + bin_capacity - 1) / bin_capacity; // ceil(item/C*8)
    match item_class {
        1 => score -= 5.0,   // tiny item: cheap to place anywhere, prefer small residuals anyway
        5..=6 => score += 3.0, // big item: be pickier
        7..=8 => score -= 8.0, // huge item: place it, avoid opening new bins for it
        _ => {}
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default so it wins only
    // when all open bins would create bad fits.
    if bin_residual == bin_capacity {
        score = 55.0 + pr * 0.1;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
        // late in stream, avoid proliferating bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
    }

    // Mean-residual context: if this bin is far below mean residual, it's already
    // the "worst" bin - placing here consolidates fragmentation.
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.1;
    }

    // Many open bins: discourage keeping too many alive with sloppy placements.
    if open_bins_count > 8 {
        score += (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 12] are nearly unusable gaps.
    let pr = post_residual as f64;
    if post_residual >= 1 && post_residual <= 12 {
        score += 60.0 - pr * 3.0; // small gaps are heavily penalized
    }

    // Reward tight fits (best-fit core with sharpened slope for low post_residual).
    score -= (bin_capacity as f64 - pr) * 0.05;

    // Dead-space coupling with lookahead: if next item cannot use the leftover, penalize more.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 && post_residual <= 30 {
        score += (30.0 - pr) * 1.5;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
        // Reward bins whose leftover can host the next item (chaining).
        score -= (post_residual as f64 - next_item_size as f64).abs().min(20.0) * 0.8;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 0.3;

    // Mean-residual coupling: penalize bins far above mean residual (wasteful picks).
    score += ((bin_residual as f64 - mean_residual) * 0.4).max(0.0);

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when no open bin
    // offers a decent fit (i.e., item leaves large dead space in every open bin).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty: prefer reusing open bins by default.
        score += 45.0 + open_bins_count as f64 * 2.0;
        // If the item would leave a tiny unusable gap in any open bin, opening new is fine.
        if next_item_size > 0 && next_item_size > post_residual && post_residual <= 12 {
            score -= 70.0;
        }
        // Late in the stream, avoid spawning extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        // Reward using a bin whose post_residual equals a likely-future-fit state.
        if post_residual == 0 {
            score -= 15.0; // perfect fill
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer small post_residual (tight fit).

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            let slack = pr - next;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize wasted residual relative to next size
            score += 5.0 + (next - pr) * 0.3;
        }
    }

    // Penalize dead space that is too small for any plausible item (min size 1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when existing residuals fit poorly.
    if bin_residual == bin_capacity {
        // neutral baseline slightly above a decent fit, below a bad fit
        score += 30.0;
        // early in stream, prefer filling existing bins less aggressively? keep mild
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        // if many bins are open and mean residual is small, opening new bin is fine
        if mean_residual < item_size as f64 {
            score -= 5.0;
        }
        // if no open bin can fit (this is the only candidate), it must be chosen anyway
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Prefer bins with residual below mean (concentrate filling).
        score += 0.2 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 18.0 * fit_ratio;
    } else if fit_ratio > 0.6 {
        score -= 8.0 * fit_ratio;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly-ish.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            let slack = post_residual as f64 - nx;
            if slack <= 5.0 {
                score -= 10.0; // next item nests perfectly here
            } else {
                score -= 4.0 * (1.0 - slack / cap);
            }
        } else if post_residual as f64 >= nx * 0.5 {
            score += 3.0; // next item would strand half here
        }
        // Penalize leaving residual just below the next item size (dead space).
        if post_residual > 0 && (next_item_size as u32) > post_residual {
            score += 2.0 * (1.0 - post_residual as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item is large relative to capacity (better to start fresh) or the
    // stream is early (long horizon to exploit a fresh bin).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let size_pull = item_size as f64 / cap; // 0..1
        score = cap * 0.45 + 10.0 * (1.0 - progress) - 14.0 * size_pull;
        // Discourage hoarding many open bins late in the stream.
        score += 0.6 * open_bins_count as f64 * (0.5 + progress);
    }

    // Global pressure: when mean residual across open bins is small, tighten
    // selection (prefer minimal waste even more).
    let mr = mean_residual.max(0.0);
    if mr < 25.0 {
        score += post_residual as f64 * 0.35;
    } else if mr > 60.0 {
        // Plenty of slack around: mildly reward compact placements.
        score -= post_residual as f64 * 0.15;
    }

    // Prefer bins whose residual is close to item size (classic best-fit sharpening).
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.08 * residual_gap;

    // Slight preference for older bins to encourage closing them out.
    score -= 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    // non-linear coupling of post_residual with stream progress
    score += (pr / cap).powi(2) * 30.0 * (1.0 - t);
    score -= (pr / cap).powi(3) * 25.0 * t;
    // reward tight fits more strongly as stream progresses
    let tight = 1.0 - pr / cap;
    score -= tight.powi(2) * 40.0 * (0.5 + 0.5 * t);
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * t;
    }
    // penalize bins far from mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * 8.0;
    // lookahead: reward leaving space for next item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= (gap / cap) * 12.0;
        } else {
            score += (-gap / cap) * 10.0;
        }
    }
    // slight penalty for opening many bins
    score += open_bins_count as f64 * 0.05;
    // new-bin candidate: penalize mildly so we prefer reusing decent bins
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - t) + 5.0;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "complementary"
    // to common item sizes (multiples of 10 and small remainders).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else {
        let class = pr % 10;
        match class {
            0 => score -= 25.0,                 // divisible residual stays usable
            1..=3 => score += 18.0,             // tiny slivers are near-dead space
            4..=6 => score += 6.0,              // mildly awkward
            _ => score -= 8.0,                  // 7..9 leaves room for min item
        }
    }

    // Fractional capacity coupling: prefer bins whose fill ratio crosses
    // harmonic thresholds (1/2, 2/3, 3/4) with this placement.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    if (fill - 0.5).abs() < 0.001 { score -= 15.0; }
    if (fill - 2.0/3.0).abs() < 0.001 { score -= 12.0; }
    if (fill - 0.75).abs() < 0.001 { score -= 10.0; }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap).max(0.0);
        } else {
            score += 10.0; // next item won't fit here; penalize slightly
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would leave very awkward residuals or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_fit = mean_residual - item_size as f64;
        if mean_fit >= 0.0 && mean_fit < 8.0 {
            score += 5.0; // open bins would leave slivers -> new bin ok
        } else {
            score += 70.0 + 60.0 * (1.0 - progress); // discourage early opening
        }
        if open_bins_count == 0 { score -= 100.0; }
    }

    // Tight-fit bonus: item nearly fills the bin.
    if item_size as f64 / bin_residual as f64 > 0.9 {
        score -= 20.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the smallest plausible item) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits: post_residual close to zero relative to capacity.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.3;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when no open bin
    // offers a good fit; otherwise discourage fragmentation.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 1.5;
        // If the next item would fit nicely in a fresh bin's leftover, boost it.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 6.0;
        }
    }

    // Open-bin pressure: penalize placements that leave residuals unlikely to
    // host the lookahead item, favoring bins that keep useful space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += 5.0;
        }
    }

    // Mild pressure to consolidate into fewer bins as stream progresses.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but scale waste penalty by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.15 * progress * post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins where the NEXT item
    // also fits into the post_residual (perfect 2-chain), penalize near-misses.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 + 4.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize wasted residual that exceeds
            // what the next item could use, worse for large dead zones.
            let dead = (post_residual as f64 - (next_item_size as f64).min(post_residual as f64)).max(0.0);
            score += 2.0 + dead * 0.08;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are scarce
    // capacity; filling them is good, so reward using below-mean bins.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = res_f / mean_residual;
        if rel < 1.0 {
            // tight bin being consumed: reward proportionally
            score -= 3.0 * (1.0 - rel);
        } else {
            // above-average residual bin: slight penalty to prefer tight bins
            score += 1.5 * (rel - 1.0).min(2.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.5 {
            score -= 10.0;
        } else {
            score -= 2.0;
        }
    }

    // New-bin candidate handling: an empty bin is a fallback. Make it
    // attractive only when the item is large relative to capacity or when
    // open bins are already congested (high mean residual means poor fits).
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity as f64;
        let congestion = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // Penalize new bins mildly by default...
        score += 4.0;
        // ...but discount the penalty when item is big or bins are congested.
        score -= 6.0 * item_ratio + 5.0 * congestion;
        // Late in the stream, avoid proliferating bins.
        score += 3.0 * progress;
    }

    // Small stabilizer to break ties toward earlier (tighter) bins.
    score += 0.001 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's leftover; penalize large dead space more.
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin, more so when many bins are already open or few fitting bins exist.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 8.0;
        }
        // Early in the stream, opening bins is cheaper; later it is costly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    } else {
        // Reward using existing bins, especially when mean residual is high (bins are fragmented).
        score -= 0.02 * mean_residual;
        score -= 1.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mild penalty when the item barely fits, leaving awkward residual (avoid residual 1..=9 style gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear polynomial shaping of post residual.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream progress coupling: as stream advances, penalize large residuals more (dead space matters later).
    let progress_coupling = progress * (norm_pr * cap) * (0.5 + 1.5 * norm_pr);
    score += progress_coupling;

    // Smooth interaction: penalize post_residual relative to next item fit.
    let n = next_item_size as f64;
    if n > 0.0 {
        let gap = (pr - n).abs();
        let norm_gap = gap / cap;
        score += 12.0 * norm_gap * norm_gap * (1.0 - progress);
        // Reward when next item fits smoothly into post residual (quadratic bonus).
        if pr >= n {
            score -= 6.0 * (1.0 - norm_gap) * (1.0 - norm_gap);
        }
    }

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    if fitting_bins_count <= 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Mild penalty for scattering across many bins, coupled with mean residual.
    score += 0.05 * open_bins_count as f64 * (1.0 - norm_pr) + 0.1 * (mean_residual - pr).abs() / cap;

    // New-bin candidate: penalize opening a new bin smoothly, unless item is large and post residual tiny.
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * (item_size as f64 / cap) * (1.0 - norm_pr * 4.0).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and mod 20 quantify "dead space quality".
    let post = post_residual as i64;
    let cap = bin_capacity as f64;

    // Reward small post_residuals that fall into "usable" harmonic classes.
    // Residue 0 mod 10 is ideal (leaves round slots); odd residues are penalized.
    let residue10 = post % 10;
    let residue20 = post % 20;
    let class_bonus: f64 = match residue10 {
        0 => -12.0,
        5 => -6.0,
        _ if residue20 == 0 => -9.0,
        _ => (residue10 as f64) * 0.8,
    };
    score += class_bonus;

    // Integer-division thresholds on post_residual: classify leftover into slots.
    let slot = post / 10; // how many 10-sized items could still fit stacked conceptually
    if slot >= 2 {
        score -= 4.0 + slot as f64;
    } else if slot == 0 && post > 0 {
        // tiny dead space: penalize proportionally
        score += (10 - residue10 as i64) as f64 * 1.2;
    }

    // Perfect fit reward
    if post == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: does the next item fit harmonically into post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as i64;
        if nxt <= post {
            let next_post = post - nxt;
            let nres = next_post % 10;
            let harmony: f64 = if nres == 0 {
                -10.0
            } else if nres == 5 {
                -5.0
            } else {
                0.0
            };
            score += harmony - 3.0;
        } else {
            // next item won't fit here: mild penalty unless post_residual is tiny anyway
            score += 2.0 + (nxt - post) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default so it wins
    // only when existing fits are poor.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (open_bins_count as f64) * 0.3;
        if next_item_size > 0 && (next_item_size as i64) > post {
            score += 5.0;
        }
    }

    // Fractional capacity pressure: penalize placements wasting a large fraction.
    let waste_frac = post as f64 / cap;
    if waste_frac > 0.0 && waste_frac < 0.1 {
        score += 6.0; // awkward sliver
    }

    // Stream progression: early on, be more conservative about filling bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Mean residual alignment: prefer bins near the mean residual (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    // A gap is "dead" if it is smaller than the smallest plausible item (<= ~10)
    // or if it cannot fit the lookahead item.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // unusable sliver -> strong penalty
        } else if post_residual < item_size {
            // gap smaller than current item class: partially dead
            score += 8.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 6.0; // cannot host the next item either
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0; // lookahead-friendly residual is valuable
        }
    } else {
        // Perfect fill: reward strongly.
        score -= 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin, especially as the stream progresses.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Open-bin pressure: discourage spreading across many bins; but if the
    // mean residual is large (open bins are roomy), reusing them is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);
    score -= 0.15 * mean_residual;

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Make the empty bin slightly unattractive so
    // that any reasonable-fit open bin beats it.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Early in the stream, opening bins is cheaper (more future use).
        score -= 10.0 * (1.0 - progress);
        // If the current bin would leave a big dead gap, opening fresh is fine.
        if post_residual > 0 && post_residual < 10 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }

    // Post-residual that is close to the next item size is also attractive
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 80.0 / (1.0 + slack * 0.15);
    }

    // Penalize leaving residual too small for any future item (dead space),
    // unless the residual is exactly consumed by the lookahead item.
    if next_item_size == 0 || post_residual < next_item_size {
        if post_residual > 0 && post_residual < 10 {
            score += 60.0;
        }
    }

    // Compare against mean residual: bins tighter than average are preferred targets
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when item is huge or stream is early;
    // otherwise penalize so existing bins get used.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.7 * bin_capacity as f64;
        if big_item || open_bins_count == 0 {
            score -= 50.0;
        } else {
            score += 150.0 * (1.0 - progress * 0.3);
        }
    }

    // Slight preference for tighter bins overall
    score += (bin_capacity as f64 - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize leaving awkward gaps.
            score += 3.0;
        }
        // Bonus if post-residual matches next item exactly (perfect chaining).
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin, less so when
    // alternatives are poor (few fitting bins) or item is large.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 20.0 * scarcity - 10.0 * item_frac;
        // Late in the stream, be more conservative about new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Global state coupling: many open bins with high mean residual suggests
    // spreading; prefer bins whose residual is below the mean (tighter bins).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.05 * diff;
    }

    // Mild penalty for very large item into nearly-full bin (fragmentation risk
    // for the remainder), unless remainder is zero.
    if post_residual > 0 && item_size > 60 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress;
    score += 40.0 * poly;

    // Penalize large dead space more as stream progresses (less time to fill it)
    score += 10.0 * pr_norm * pr_norm * progress;

    // Reward tight fits
    score -= 15.0 * (1.0 - pr_norm);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post residual exactly-ish, reward
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.2 * gap;
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into classes of 10
    let class = post_residual / 10;
    let phase = post_residual % 10;

    // Reward small post_residual (tight fits), stronger for low classes
    score -= 12.0 * (1.0 - class as f64 / 10.0).max(0.0);

    // Penalize "awkward" residual phases that rarely recombine (dead space)
    if phase > 0 && phase < 5 {
        score += 6.0 - 2.0 * phase as f64;
    }

    // Exact fit: huge reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Perfect harmonic pair: post_residual exactly matches next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Post residual can host next item with leftover class alignment
    if next_item_size > 0 && post_residual >= next_item_size {
        let nxt_class = (post_residual - next_item_size) / 10;
        score -= 2.0 * nxt_class as f64;
    } else if next_item_size > post_residual {
        // next item won't fit here: slight penalty unless residual tiny
        score += 4.0;
    }

    // Last-chance bin: strong reward to use it rather than open new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if item is large, new bin is attractive (avoid fragmenting)
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Prefer filling bins with high residual relative to mean (balance avoidance)
    if bin_residual as f64 > mean_residual {
        score -= 3.0;
    }

    // Late in stream: prioritize closing bins (tight fits)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for the smallest
    // conceivable item are pure waste. Penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing a bin exactly.
        score -= 25.0;
    }

    // Reward tight fits relative to current residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 20.0;
        } else if gap < 10 {
            score += 15.0; // leaves a tiny dead gap for the next item
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight bonus for using this bin now.
        score -= 3.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones,
    // and encourage consolidating into existing bins.
    let open_pressure = open_bins_count as f64 / 10.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and
        // mean residual availability across open bins.
        score += 20.0 + 10.0 * open_pressure + 0.2 * mean_residual;
        // But if no open bin fits well (large mean residual mismatch),
        // opening a fresh bin becomes relatively more attractive.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    } else {
        // Existing bin: mild reward that grows with open-bin pressure.
        score -= 2.0 * open_pressure;
    }

    // Late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter post-fit is better, but avoid tiny dead space.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 25.0; // penalize unusable slivers
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        if nxt <= pr {
            // next item fits here: strongly reward exact/near-exact chaining
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
            if diff < 0.5 {
                score -= 20.0; // perfect chain bonus
            }
        } else {
            // next item won't fit here: mild penalty proportional to overflow
            score += 5.0 + (nxt - pr) * 0.15;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual is near/below mean
    // (packing into emptier bins wastes tight space elsewhere).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin when stream is early/mid
    // and decent open bins exist; allow it late or when item is large.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 60.0 - 30.0 * progress;
        if item_size >= 70 {
            score -= 20.0; // big items are hard to place later; new bin ok
        }
        if next_item_size > 0 && (next_item_size as f64 + item_size as f64) <= bin_capacity as f64 {
            score -= 25.0; // allows pairing with lookahead item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for wasted dead space (nonzero post_residual)
    if post_residual > 0 {
        score += (post_residual as f64) * 0.35;
    } else {
        score -= 25.0; // perfect fit reward
    }

    // Reward tight fits relative to capacity
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Lookahead: if the next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64 / post_residual.max(1) as f64) * 10.0;
        } else {
            // next item won't fit here; penalize leaving awkward small residual
            if post_residual > 0 && post_residual < next_item_size {
                score += (post_residual as f64) * 0.15;
            }
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into existing bins
    score += (open_bins_count as f64) * 0.5;

    // Mean residual coupling: if this bin is above average residual, it's roomier -> mild penalty
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    // Time horizon: late in the stream, be more conservative with new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // New-bin candidate: make opening a new bin unattractive unless item is large / no good fit
    if bin_residual == bin_capacity {
        score += 18.0;
        if item_size > bin_capacity * 3 / 4 {
            score -= 10.0; // large items start fresh bins more willingly
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: quadratic penalty on wasted space, softened by stream progress
    let mut score = rn * rn * (1.0 + 2.0 * progress) * cap;

    // Cubic coupling: large residuals late in stream are acceptable (keep bins flexible)
    let cube = rn * rn * rn;
    score -= 8.0 * cube * cap * (1.0 - progress);

    // Reward tight fits (small post residual), stronger early
    score -= (1.0 - rn) * (1.0 - rn) * 6.0 * (1.0 - 0.5 * progress);

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * (1.0 - rn);
    }

    // Lookahead coupling: if next item fits in post residual, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= r {
            score -= 4.0 * (1.0 - nx / cap);
        } else {
            score += 3.0 * (nx - r) / cap;
        }
    }

    // Spread penalty: bin far from mean residual is less attractive
    score += 0.15 * (r - mean_residual).abs();

    // Many open bins: mild preference for filling existing ones
    score += 0.05 * open_bins_count as f64 * rn;

    // New-bin candidate: penalize unless residual advantage is real
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues in [0..10] are "golden" dead space
    let class = post_residual % 10;
    if class == 0 && post_residual > 0 {
        score -= 8.0; // exact harmonic alignment, tiny residue reusable by small items
    } else if class <= 3 {
        score -= 3.0;
    } else if class >= 7 {
        score += 4.0; // large awkward residue class
    }

    // Big residual chunks are valuable: reward leaving large usable space
    if post_residual >= 50 {
        score -= 6.0;
    } else if post_residual >= 30 {
        score -= 2.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 5.0; // near-dead space penalty
    } else if post_residual == 0 {
        score -= 12.0; // perfect closure
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) % 10;
            score -= 5.0 - slack as f64 * 0.3;
        } else {
            score += 3.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New empty bin candidate: penalize mildly unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = (open_bins_count as f64) / (mean_residual / bin_capacity as f64 + 1.0);
        score += 14.0 - 6.0 * progress - crowding.min(8.0);
        if item_size >= bin_capacity / 2 {
            score -= 6.0; // big items start fresh bins happily
        }
    }

    // Prefer filling bins far below the mean residual (compress variance)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1..100 range,
    // but tiny gaps are hard to fill) are heavily penalized.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize bins whose residual is far below the mean (already tight bins are precious)
    if (bin_residual as f64) < mean_residual {
        score += (mean_residual - bin_residual as f64) * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation;
    // also make the brand-new empty bin less attractive when bins are already open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    if bin_residual == bin_capacity {
        score += 15.0 + pressure * 2.0;
    } else {
        score -= pressure * 0.3;
    }

    // Lookahead: if the next item would fit exactly in the post-residual, reward this placement
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // If next item fits in post residual, mild reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect / near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 100.0 + (5 - post_residual) as f64 * 10.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = post_residual as f64 - nxt;
            // Exact match for next item is excellent.
            if gap == 0.0 {
                score -= 500.0;
            } else {
                // Smaller leftover gap after next item is better.
                score -= 50.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // Next item cannot fit here; penalize proportionally to how
            // much dead space the lookahead leaves behind.
            score += 0.5 * (nxt - post_residual as f64);
        }
    }

    // Compare post_residual against mean residual: avoid creating
    // residuals far below the mean (fragmentation) unless it's a great fit.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Slight preference for reusing existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 0.1;
    } else {
        score -= 5.0;
    }

    // Mild time decay: later in the stream, tighten up (avoid waste).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * (post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: heavily favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing (min size 1) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: bonus if next item fits the post-residual exactly-ish.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space the known next item cannot use.
        score += 0.3 * post_residual as f64;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Crowding pressure: with many open bins, prefer reusing existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / bin_capacity as f64);
    score -= 0.05 * open_pressure;

    // Mean-residual alignment: prefer bins near the mean residual (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    // Time horizon: early in stream, be slightly more willing to consolidate;
    // late in stream, avoid leaving large residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 0.05 * post_residual as f64;

    // New-bin candidate: only attractive when no open bin fits well
    // (large item, tight fits unavailable) or residuals are all poor.
    if bin_residual == bin_capacity {
        let poor_alternatives = (fitting_bins_count == 0)
            || (item_size as f64 / bin_capacity as f64 > 0.6 && fitting_bins_count <= 1);
        if poor_alternatives {
            score -= 20.0;
        } else {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 12.0 * coupling * (1.0 + mean_residual / (cap * open_bins_count.max(1) as f64 + 1.0));

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 20.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that is too small for likely future items
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr > 0.0 && pr < ni {
            score += 15.0 * (ni - pr) / cap * (1.0 + progress);
        }
        // Reward leaving space exactly usable by next item
        if pr >= ni && pr < ni * 1.5 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New empty bin candidate: penalize unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of small common sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        let class_bonus: f64 = if pr % 10 == 0 {
            -6.0
        } else if pr % 5 == 0 {
            -3.0
        } else if pr % 20 == 0 {
            -7.0
        } else if pr < 10 {
            4.0 // tiny dead space is nearly unusable
        } else {
            0.0
        };
        score += class_bonus;

        // Dead-space penalty: quadratic growth for small leftovers.
        if pr < 15 {
            score += ((15 - pr) * (15 - pr)) as f64 * 0.15;
        }
    } else {
        score -= 10.0; // perfect fit
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual
    // (harmonic pairing), penalize if it clearly cannot.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 8.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.1;
        } else {
            score += 1.5;
        }
        // modulo harmony: next item shares divisor class with post residual
        if pr > 0 && next_item_size % 10 == 0 && pr % 10 == 0 {
            score -= 1.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large relative to capacity or many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        let crowded = (open_bins_count as f64) > 4.0 + 8.0 * progress;
        if large_item || crowded {
            score -= 2.0;
        } else {
            score += 3.0; // prefer packing into existing bins early on
        }
    }

    // Mild pressure toward filling fuller bins (lower residual relative to mean).
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; new bins less penalized when few open.
    score += (open_bins_count as f64) * 0.5;

    // Dead space relative to mean residual: if this bin leaves much less than average, it's a good consolidation.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Lookahead: if the next item fits the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // If next item cannot fit in the leftover gap, penalize creating wasted space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // New-bin candidate: prefer new bin only when existing residuals are poor.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    // Slight progression awareness: late in stream, be more conservative about new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose post_residual can host the next item exactly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post >= next {
            // Slack matching: exact fit for next item is heavily rewarded.
            let slack = post - next;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
            score -= 5.0 * (next / bin_capacity as f64);
        } else {
            // Next item cannot fit here; penalize proportionally to wasted potential.
            score += 8.0 * (next - post) / bin_capacity as f64;
        }
        // Two-step coupling: prefer residuals that leave room for an average-sized follow-up.
        let avg_next = (item_size as f64 + next) / 2.0;
        score += 0.15 * (post - avg_next).abs();
    } else {
        // Last item: prefer tightest fit only.
        score += 0.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - progress);
    }

    // Relative-to-mean residual: prefer bins already below mean residual (consolidating waste).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when current bin fits are poor (high post_residual).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 20.0 + 0.5 * pressure - 10.0 * progress;
    }

    // Mild preference for fuller bins as stream progresses.
    score -= progress * (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is best.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize small-but-nonzero dead space (waste that can't fit typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only one bin can fit this item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead: favor bins whose leftover can hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else if post_residual > 0 && (next_item_size as f64) > (post_residual as f64) * 3.0 {
            score += 10.0; // leftover too small for next item => dead space risk
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Global residual pressure: if mean residual is high, prefer using existing space.
    score -= 0.3 * mean_residual;

    // Time horizon: early on, be conservative about new bins; late, prioritize closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 30.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate penalty: only open a new bin when no good fit exists.
    if bin_residual == bin_capacity {
        score += 70.0 + 40.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Base: squared normalized post-residual (dead-space penalty, convex)
    let norm_post = post / cap;
    let mut score = norm_post * norm_post * cap;

    // Smooth cubic coupling with stream progress: later in stream, waste hurts more
    score += (0.5 + progress) * norm_post * norm_post * norm_post * cap;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - progress) * 0.0 + progress * (1.0 - norm_post) * 2.0;

    // Penalize creating residual that cannot fit next item (smooth hinge)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post).max(0.0) / cap;
        score += gap * gap * cap * 1.5;
    }

    // Last-chance bin bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 6.0;
    }

    // Mild penalty for opening new bins when others fit; grows with open bins
    if is_new_bin {
        score += 3.0 + 0.15 * open_bins_count as f64;
        // But if existing bins are all fragmented, new bin is attractive
        score -= 2.0 * (mean_residual / cap).min(1.0);
    }

    // Fragmentation-aware adjustment relative to mean residual of open bins
    score += 0.3 * (post - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 200.0; // near-perfect fill
    }

    // Harmonic class logic: classify post_residual by decade buckets (mod 10).
    // Small residues in "usable" classes (1..=20) are valuable for future small items.
    let residue_class = post_residual % 10;
    if post_residual <= 20 && post_residual >= 1 {
        // usable small residual: reward mildly, especially if next item can use it
        score -= 30.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 150.0; // lookahead confirms reuse
        }
    } else if post_residual > 20 && post_residual <= 50 {
        // medium residual: neutral-ish, small penalty to avoid scattering
        score += 10.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 120.0;
        }
    } else if post_residual > 50 {
        // large residual: wasteful split unless it's a fresh bin
        score += 25.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 100.0;
        }
    }

    // Penalize residues that are awkward classes (e.g., post_residual % 10 == 1..3 with no tiny items expected)
    if residue_class >= 1 && residue_class <= 3 && post_residual < 15 {
        score += 5.0; // dead sliver
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // New-bin candidate: default mild preference so it loses to good fits but
    // wins over wasteful placements in nearly-full bins.
    if bin_residual == bin_capacity {
        score = 60.0 + post_residual as f64; // empty bin: post_residual == capacity
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative, must open
        }
        // Late in stream, prefer closing out open bins rather than opening new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 * progress;
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 40.0; // existing bins still have room on average
        }
    }

    // Prefer bins whose residual is close to the item (minimize fragmentation).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 50.0 * waste_ratio * waste_ratio;

    // Coupling with mean residual: choose bins below-mean residual (nearly full) to close them out.
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are penalized super-linearly. Useful gap threshold ~ 10..30.
    let dead_threshold = 30u32;
    if post_residual > 0 && post_residual < dead_threshold {
        let deadness = (dead_threshold - post_residual) as f64 / dead_threshold as f64;
        score += 40.0 * deadness * deadness;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward leaving a gap that exactly (or nearly) accommodates the lookahead item.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 45.0;
        } else if gap > 0 && gap <= 10 {
            score -= 20.0 - 2.0 * gap as f64;
        } else if gap < 0 && (-gap) <= 8 {
            // near-miss: item almost fits the leftover, mild penalty
            score += 2.0 * (-gap) as f64;
        }
    }

    // Open-bin pressure: prefer already-open bins when many are open,
    // but allow opening new bins when few exist and fit is poor.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // New-bin candidate handling: make fresh bin attractive only when the
    // best alternative would create dead space; otherwise discourage it.
    if bin_residual == bin_capacity {
        if post_residual == 0 {
            score -= 10.0; // opening a bin for a perfect-fit item is fine
        } else {
            score += 25.0 + mean_residual * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins whose residual is close to the item (tight fit relative measure).
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score += 15.0 * tightness;

    // Mild preference to balance residuals toward the mean.
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual exactly matches next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 500.0;
        } else {
            score += diff * 0.5;
        }
    }

    // Relative to mean residual: prefer bins with less residual than average
    // (tighter bins get filled first, keeping roomy bins flexible).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin unless it's early or the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 150.0 * progress * (1.0 - item_frac);
        // But allow new bin when no open bin is a good fit.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild penalty for leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small to hold typical future items,
    // scaled by how far along the stream we are.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 {
        let dead = if post_residual < 10 { post_residual as f64 } else { 0.0 };
        score += 30.0 * dead * (0.5 + progress);
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 / (1.0 + slack);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * fill_ratio;
    }

    // New-bin candidate handling: opening a bin is expensive; only attractive
    // when no open bin fits well (high mean residual dispersion vs item).
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64;
        let fit_pressure = (mean_residual - item_size as f64).abs();
        score += 60.0 + 3.0 * crowding - fit_pressure.min(50.0) - 40.0 * progress;
    } else {
        // Slight preference for bins already below-average residual (denser bins).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
        // Mild load balancing: discourage spreading across too many bins early.
        score += 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic penalty on wasted residual, amplified by stream progress.
    let mut score = post * post / cap + post * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward; if next item is slightly larger than post residual,
    // penalize creating a "just barely unusable" gap.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = nxt - post;
        if gap <= 0.0 {
            let fit_frac = post / nxt;
            score -= 10.0 * (1.0 - (fit_frac - 1.0).abs() / cap) * (post / cap);
        } else {
            let dead = (gap / cap).min(1.0);
            score += 15.0 * dead * dead;
        }
    }

    // Last chance: if this is the only fitting bin, heavily reward using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild preference among many candidates: keep residual spread near mean.
        score += (post - mean_residual).abs() * 0.2;
    }

    // New-bin candidate: empty bin has large post residual; make it less
    // attractive unless progress is late and bins are few (smooth coupling).
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 8.0 * (1.0 - progress) * (1.0 - openness) + 5.0;
    }

    // Smooth progress interaction: late in the stream, waste is costlier.
    score += progress * (post / cap) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is best.
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Harmonic class of post_residual: small dead space classes are worse
    // than residual that can still host common item sizes.
    let pr = post_residual;
    let class = pr % 10;
    // Residuals in classes that align with typical item sizes (multiples of 5/10)
    // are more reusable; odd remainders are dead space.
    match class {
        0 => score -= 8.0,          // reusable by any multiple-of-10 item
        5 => score -= 5.0,          // reusable by multiples of 5
        1 | 9 => score += 6.0,      // nearly dead
        2 | 8 => score += 3.0,
        _ => {}
    }

    // Integer-division thresholds: how many standard slots remain.
    let slots10 = pr / 10;
    let slots5 = pr / 5;
    if slots10 >= 1 {
        score -= 2.0 * slots10 as f64;
    }
    if slots5 == 0 && pr > 0 {
        score += 4.0; // residual smaller than 5 is nearly unusable
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this placement.
    if next_item_size > 0 && next_item_size <= pr {
        let gap = pr - next_item_size;
        if gap == 0 {
            score -= 30.0; // chain fill: item + next item close bin exactly
        } else if gap <= 10 {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item cannot use leftover: leftover likely becomes dead space
        score += (pr.min(30)) as f64 * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: keep it high enough that decent fits win.
        score += 15.0;
        // But if open bins are fragmented (mean residual low relative to item),
        // a new bin is attractive: reduce penalty.
        if (item_size as f64) > mean_residual {
            score -= 25.0;
        }
        // Late in stream with many open bins, prefer consolidating.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
    }

    // Mild preference for filling bins with low residual among many open bins.
    score -= 0.05 * mean_residual.min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    // A residual is "dead" if no plausible item (>=1) can ever be a good fit,
    // i.e. tiny residuals that will likely never be filled.
    if post_residual > 0 && post_residual < 10 {
        // Extremely small gap: nearly guaranteed waste.
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Small gap: only items <= residual could fit; penalize moderately.
        score += 25.0;
    }

    // Reward tight fits strongly (small but useful post_residual).
    if post_residual > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 18.0 * tightness * tightness;
    } else {
        // Perfect fill: heavily reward.
        score -= 40.0;
    }

    // If the next item fits exactly into the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover < 5 {
            score -= 22.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item cannot use this gap: penalize dead space proportionally.
        score += 12.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: discourage spreading across many bins when
    // alternatives exist; mild term so it never overrides dead-space logic.
    score += (open_bins_count as f64) * 1.5;

    // Slight preference for bins below mean residual (consolidate fullness).
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // New-bin candidate: only attractive when the item is huge relative to
    // capacity or all open bins would leave bad dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Large items justify fresh bins.
        score -= (item_size as f64 / bin_capacity as f64) * 55.0;
        // If no open bin fits, opening is mandatory anyway (fitting_bins_count
        // counts only open bins), so soften the penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild stream-position damping: early on, be more willing to open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (post_residual close to 0).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward when the next item fits the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Tighter lookahead matches get bigger rewards; penalize large leftover slack.
            score -= 120.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
            if slack <= 10.0 {
                score -= 60.0;
            }
        } else {
            // Next item cannot fit here; penalize proportionally to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 20.0 + 0.5 * over;
        }
    }

    // Prefer bins whose residual deviates below the mean (tighter bins used first),
    // keeping larger residuals available for larger future items.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 40.0 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Mild penalty for spreading across many bins when plenty of bins are open.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Penalize opening a brand-new bin unless the current item is large relative
    // to capacity or no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if !large_item && fitting_bins_count > 0 {
            score += 120.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // new bin preserves room for a bigger next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here; slight penalty for wasteful sequencing.
            score += 2.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer reusing open bins unless fit is bad.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty for opening a new bin, softened over time / many open bins.
        let mut new_penalty = 18.0;
        new_penalty -= 6.0 * progress;
        new_penalty -= (open_bins_count as f64).min(10.0) * 0.4;
        // If the item leaves a big hole relative to mean residual elsewhere, reuse is bad.
        if post_residual as f64 > mean_residual + 20.0 {
            new_penalty -= 6.0;
        }
        // Large items are easier to place in fresh bins.
        if item_size >= 70 {
            new_penalty -= 5.0;
        }
        score += new_penalty.max(0.0);
    }

    // Mild penalty for leaving residual far below mean (fragmentation signal).
    if bin_residual < bin_capacity && (post_residual as f64) < mean_residual - 15.0 {
        score += 3.0;
    }

    // Slight preference for filling bins with more remaining space when many bins open.
    score += 0.05 * (bin_residual as f64) / (open_bins_count.max(1) as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (1.0 - prn) * (1.0 - prn);
    score += 40.0 * poly * (0.5 + t);

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - prn) * (1.0 - prn) * 25.0 * (0.3 + 0.7 * t);

    // Penalize dead space relative to mean residual
    let dead = (pr - mean_residual).max(0.0);
    score += 0.15 * dead * dead / cap;

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: reward leaving room for the next item, penalize near-misses
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        if diff >= 0.0 {
            score -= 12.0 * (1.0 - (diff / cap).min(1.0));
        } else {
            score += 8.0 * ((-diff) / cap);
        }
    }

    // Slight preference for consolidating into fewer bins early
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: finer classes near zero are precious.
    let post_class = match post_residual {
        0 => 0,
        1..=5 => 1,
        6..=10 => 2,
        11..=20 => 3,
        21..=30 => 4,
        31..=50 => 5,
        _ => 6,
    };
    // Reward (subtract) for landing in a good class; class 0 (perfect fit) is heavily rewarded.
    let class_reward: [f64; 7] = [60.0, 35.0, 22.0, 12.0, 5.0, 0.0, -4.0];
    score -= class_reward[post_class as usize];

    // Harmonic pairing: does next_item_size divide/match the post_residual class?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits exactly or nearly into the leftover: strong reward.
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 50.0;
        } else if gap <= 5 {
            score -= 25.0;
        } else if gap <= 15 {
            score -= 10.0;
        } else {
            score -= 3.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use this leftover: penalize proportionally to wasted potential.
        score += (next_item_size.min(bin_capacity) as f64) * 0.15;
    }

    // Integer-division threshold: leftover that is a multiple of common item granularities
    // (10s) is more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Tightness ratio: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current leftovers are bad.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: high, so it's chosen only for poor fits elsewhere.
        score = bin_capacity as f64 * 0.75 + 40.0;
        // If mean residual across open bins is large (poorly usable), opening is less bad.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 25.0;
        // Early in stream, be more willing to open bins (diversity of partial bins).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
        // If no open bin can fit, new bin is necessary (fitting_bins_count == 0 handled
        // implicitly since only new-bin call exists).
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Many open bins: prefer consolidating into existing bins to limit bin count.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Small penalty scaled by how close post_residual is to blocking common next sizes.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead space avoidance ---
    // Gaps below the smallest plausible item are pure waste: heavy penalty.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0; // tiny unusable slivers
    } else if post_residual == 0 {
        score -= 25.0; // perfect closure: zero dead space, maximum efficiency
    }

    // Penalize mid-range gaps that few future items can fill efficiently.
    if post_residual > 0 && post_residual < 30 {
        score += 12.0 * (1.0 - post_residual as f64 / 30.0);
    }

    // --- Tight fit reward ---
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio; // strongly favor bins that get nearly full

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0; // if this is the only fitting bin, strongly prefer using it
    }

    // --- New-bin candidate logic ---
    if bin_residual == bin_capacity {
        // Opening a new bin: base cost plus pressure from open bin count.
        let mut new_bin_score = 55.0;
        // Prefer new bin if the item would leave a tiny unusable gap in any existing bin
        if post_residual > 0 && post_residual < 10 {
            new_bin_score -= 70.0;
        }
        // If many bins are open and this item fits poorly everywhere, a fresh bin
        // keeps residuals balanced; scale by open_bins_count pressure.
        new_bin_score -= (open_bins_count as f64).ln().max(0.0) * 4.0;
        // Lookahead: if next item is large, a fresh bin with full residual is valuable.
        if next_item_size > 0 && next_item_size >= post_residual.min(bin_residual) && next_item_size > 50 {
            new_bin_score -= 15.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score -= 10.0 * (1.0 - progress);
        return new_bin_score;
    }

    // --- Lookahead coupling ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0; // residual exactly matches next item: perfect sequencing
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 8.0; // placing item now creates sliver before next item fits
        }
    }

    // --- Mean residual balancing ---
    // Favor bins whose residual is below mean (they are closer to closure).
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff; // lower residual than average -> lower score

    // --- Open bins pressure: encourage closing bins rather than scattering ---
    score += 0.5 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward leaving zero waste.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact chain fit is ideal.
            if post_residual == next_item_size {
                score -= 300.0;
            } else {
                // Reward proportional to how well next item nests in leftover.
                let chain_waste = (post_residual - next_item_size) as f64;
                score -= 60.0 - 0.5 * chain_waste.min(60.0);
            }
        } else {
            // Leftover too small for next item: penalize dead space, more so if tiny.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 40.0;
            }
        }
    }

    // Compare post residual to mean residual of open bins.
    // Placing into a bin with high residual (above mean) is preferred to
    // consolidate space; placing into below-mean bins wastes scarce room.
    let resid_f = bin_residual as f64;
    if resid_f > mean_residual {
        score -= 0.4 * (resid_f - mean_residual);
    } else {
        score += 0.4 * (mean_residual - resid_f);
    }

    // Last chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Early in the stream, favor opening new bins less (keep bins open);
    // later, allow more bin openings since distribution knowledge is richer.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate (empty bin): penalize opening a new bin unless the
    // item would leave a very large residual in every open bin anyway.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 30.0 + 50.0 * progress;
        // If next item is large and current item is large, a fresh bin is fine.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            new_bin_score -= 20.0;
        }
        // Many open bins with small residuals: opening fresh bin is reasonable.
        if mean_residual < 25.0 && open_bins_count > 2 {
            new_bin_score -= 25.0;
        }
        score = score.max(new_bin_score) + (score - score); // keep base, use max logic below
        score = new_bin_score;
    }

    // Mild penalty for creating very small unusable leftovers (1..=5).
    if post_residual >= 1 && post_residual <= 5 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Dead-space penalty: residuals too small for the smallest items are worthless.
    if post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.5 * (next_item_size as f64 / cap);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or bins are few.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64 / (mean_residual / cap).max(0.1);
        score += 25.0 - 0.3 * open_pressure - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // new bin good if next item is large too
        }
    }

    // Mild preference for fuller bins relative to global state.
    score -= 0.1 * (bin_residual as f64 - mean_residual).max(-50.0).min(50.0) * -0.01;
    score -= 0.05 * (1.0 - post / cap) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
