    score += dead_penalty;

    // Reward tight fits (small post_residual) more strongly later in the stream
    let tight_reward = (1.0 - x) * (1.0 - x) * (1.0 + progress) * 10.0;
    score -= tight_reward;

    // Interaction of post_residual with mean residual: prefer bins below/above mean adaptively
    let dev = (pr - mean_residual) / cap;
    score += (dev * dev) * 15.0;

    // Lookahead coupling: penalize if next item cannot use the post_residual
    if next_item_size > 0 {
