        if nx > pr {
            score += (nx - pr) * (0.3 + 0.4 * progress);
        } else {
            score -= (pr - nx) * 0.2;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);

    // New-bin candidate: only attractive when current fit is bad
    if bin_residual == bin_capacity {
        score += 5.0 + 30.0 * (1.0 - x) * (1.0 - x) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: mod-10 classes (capacity=100 grid) ---
    let post = post_residual as i64;
    let cls = post % 10;
    // Dead-space classes: residuals of 1..9 are nearly unusable (items >= 10 in original regime)
    if post > 0 && post < 10 {
        score += 25.0; // unusable sliver -> strong penalty
    } else if cls == 0 {
        score -= 12.0; // perfectly harmonic residual (10/20/.../90) -> reward
    } else if cls <= 3 {
        score += 6.0; // awkward small class
    } else if cls >= 7 {
        score += 2.0; // mildly awkward
    }

    // --- Integer division thresholds on post_residual ---
    if post_residual >= bin_capacity / 2 {
        score -= 5.0; // bin still half usable -> good
    } else if post_residual >= bin_capacity / 4 {
        score += 0.0;
    } else if post_residual > 0 {
        score += 8.0; // below quarter -> poor future utility
    }

    // --- Coupling with lookahead item (k=2) ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect lookahead fit -> strongly favor
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            let gap_cls = gap % 10;
            if gap_cls == 0 {
                score -= 10.0; // gap lands on harmonic class
            } else if gap < 10 {
                score += 10.0; // would leave sliver after next item
            } else {
                score -= (gap / 10) as f64; // larger harmonic gap = more reusable
            }
        } else {
            // next item can't use this residual anyway; residual value depends on class
            score += if cls == 0 { 0.0 } else { 3.0 };
        }
    }

    // --- Tight fit reward ---
    if post_residual == 0 {
        score -= 40.0; // perfect packing
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // --- Last-chance bin: avoid opening a new bin unnecessarily ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate logic ---
    if bin_residual == bin_capacity {
        // Prefer reusing an existing bin with a decent fit; open new bin only
        // when fit elsewhere would be bad (post_residual small or sliver class).
        let bad_existing = post_residual < 15 || (post > 0 && post < 10);
        if bad_existing {
            score -= 20.0; // encourage opening a fresh bin
        } else {
            score += 30.0 + (open_bins_count as f64).sqrt() * 2.0; // discourage new bins
        }
    }

    // --- Stream progression: tighten late in the stream ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual / 20.0); // favor bins matching mean residual late

    // Mild preference to fill fuller bins first (best-fit baseline already in post_residual)
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest item are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 50.0 + (10 - post_residual) as f64 * 5.0;
    } else if post_residual > 0 {
        // Mild superlinear penalty on waste, tight fits rewarded.
        score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual tightly matches the item.
    let tightness = (bin_residual - item_size) as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * (1.0 - tightness);

    // Lookahead: if next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage spreading when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure scaled by how much residual
        // is being wasted across open bins.
        score += 30.0 + 3.0 * open_bins_count as f64 + 0.5 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    } else {
        score -= 2.0 * open_bins_count.min(20) as f64;
    }

    // Early stream: be conservative about fragmentation; late stream: pack aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - gap / (bin_capacity as f64));
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize leaving a sliver the next item cannot use.
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Penalize very small unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin scales with how many bins are open.
        let open_cost = 55.0 + 3.0 * open_bins_count as f64;
        // Cheaper to open a new bin late in the stream (fewer future items to fill it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let time_discount = 25.0 * progress;
        // If existing bins fit poorly (post_residual large relative to item), opening is more attractive.
        let poor_fit = (post_residual as f64) / (bin_capacity as f64);
        score = open_cost - time_discount + 20.0 * poor_fit;
    }

    // Slight preference for bins with lower residual than the mean (consolidation).
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Mild tie-break toward bins that are already fairly full.
    score += 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    let coupling = poly * (0.5 + progress);

    let mut score = pr * (1.0 + 0.8 * progress);

    // Reward tight fits more strongly as stream progresses
    score -= 30.0 * coupling;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            score += 0.15 * gap * (1.0 - progress);
        } else {
            score -= 5.0 * (-gap / cap) * (0.5 + progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 * (1.0 - norm_pr);
    }

    // New-bin candidate: encourage opening when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * (mean_residual / cap);
        score += 10.0 + 8.0 * (1.0 - progress) - 4.0 * crowded.min(4.0);
        if next_item_size > 0 && next_item_size as f64 <= cap {
            score -= 3.0;
        }
    }

    // Mild penalty for spreading across too many bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via squared waste, normalized by capacity.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste * waste;

    // Harmonic class of post_residual: modulo classes on capacity.
    // Residuals that are "harmonic" (divide capacity nicely: 0, 25, 50, 100)
    // are more reusable; penalize odd/awkward residues.
    let pr = post_residual;
    let harmonic = match pr {
        0 => 1.0,
        _ if pr % 50 == 0 => 0.8,
        _ if pr % 25 == 0 => 0.6,
        _ if pr % 10 == 0 => 0.3,
        _ if pr % 5 == 0 => 0.0,
        _ => -0.4,
    };
    score -= 12.0 * harmonic;

    // Dead-space penalty: residuals too small to hold the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 25.0;
    } else if pr > 0 && pr < next_item_size.max(1) as u32 {
        // This residual cannot host the lookahead item either.
        score += 6.0;
    }

    // Perfect fit bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size < pr {
            score -= 8.0 * (1.0 - (pr - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when current fit is bad or many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_badness = (item_size as f64 / bin_capacity as f64);
        // Base new-bin score: slightly above a good existing fit.
        score = 55.0 + 20.0 * fit_badness - 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        if open_bins_count > 8 {
            score += 10.0; // discourage bin proliferation
        }
        return score;
    }

    // Mild congestion: when many bins are open, tighten selection to consolidate.
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // Mean-residual anchoring: prefer bins whose residual deviates below the mean
    // (i.e., we are filling the emptier-but-usable bins consistently).
    score -= 0.05 * (mean_residual - bin_residual as f64);

    // Progress-aware tightening: late in the stream, be stricter about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100)
    // are pure waste -> heavy penalty proportional to the waste.
    let dead_threshold = 10u32.min(bin_capacity);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 3.0 * (dead_threshold - post_residual) as f64;
    }

    // Reward near-perfect fits (tight packing) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: penalize spreading across many bins mildly,
    // scaled by stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Reward bins whose residual is close to the mean residual (balance),
    // but only when the mean is meaningful.
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * dev;
    }

    // Lookahead: if the next item fits into the post-residual, reward this
    // placement (chaining compatible items).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else if post_residual > 0 {
            score += 2.0; // creates a gap the next item cannot use
        }
    }

    // New-bin candidate handling: an empty bin is a fallback; prefer it only
    // when no open bin offers a decent fit (post_residual small there).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are open
        // (amortization) and late in the stream.
        score = bin_capacity as f64 * 0.6
            + 2.0 * open_bins_count as f64
            - 5.0 * progress;
        // If nothing else fits well, opening is attractive.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // If the next item is small, a fresh bin will accommodate it too.
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: best possible outcome.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Perfect 2-step lookahead: this bin's leftover exactly matches the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Near-perfect lookahead: next item almost fills the leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize leftovers too small for the next item (likely dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 80.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Penalize small unusable dead space relative to typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Compare against mean residual: prefer bins whose post-residual is close to mean
    // (keeps flexibility) and penalize extreme fragmentation.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.3 * dev;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        let base = 250.0
            + 20.0 * open_bins_count as f64
            + 100.0 * (step_index as f64 / total_items.max(1) as f64);
        score += base;
        // If next item is large and current item is small, opening fresh may be fine.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 100.0;
        }
    }

    // Mild preference for tighter bins among ordinary candidates.
    score += 0.1 * (bin_residual - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 15.0 * fit_ratio * fit_ratio;

    // Lookahead: strongly reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item can't use this residual: penalize large residuals slightly less
            // if residual is small enough to be near-useless anyway.
            let useless = post_residual as f64 / bin_capacity as f64;
            score += 10.0 * useless;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity (better to start fresh for big items).
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 30.0 - 25.0 * size_ratio;
        score += base * (1.0 + 0.3 * (1.0 - progress));
        // Fewer open bins -> opening new is cheaper; many open bins -> discourage.
        score += (open_bins_count as f64).ln().max(0.0) * 5.0;
    } else {
        // Prefer bins with below-mean residual (consolidate emptier space usage).
        let diff = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 8.0 * diff;
    }

    // Time horizon: early on, be more selective about tight fits; late, just pack.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial coupling to progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Non-linear penalty on tiny unusable residuals, stronger late in the stream
    let dead = (norm_pr * (cap - norm_pr * cap)) / cap; // peaks mid-range, low near 0
    score += 20.0 * (1.0 - dead) * (0.5 + 0.5 * progress);

    // Reward tight fits (post_residual near zero) with smooth exponential term
    score -= 15.0 * (-norm_pr * 8.0).exp();

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize scattering across many open bins relative to mean residual
    score += 0.3 * open_bins_count as f64 * (norm_pr - mean_residual / cap).abs();

    // Lookahead: if next item fits exactly into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_gap = (post_residual - next_item_size) as f64;
        score -= 10.0 * (-fit_gap / cap * 10.0).exp();
    }

    // New-bin candidate: smooth penalty that decays with progress so late stream
    // favors consolidating into open bins
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // classes (10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit: strongly favored
    } else {
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 8.0; }
        if pr % 25 == 0 { score -= 10.0; }
        if pr % 50 == 0 { score -= 15.0; }
        // Harmonic class of the item itself
        if item_size % 10 == 0 { score -= 3.0; }
        if item_size % 25 == 0 { score -= 3.0; }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward it.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.4;
        } else {
            // next item cannot use this residual: penalize large leftover
            score += (next_item_size as f64 - pr as f64).min(40.0) * 0.5;
        }
        // If next item pairs with current item into a clean harmonic class
        if (item_size + next_item_size) % 100 == 0 && pr == 0 {
            score -= 50.0;
        }
    }

    // Dead-space penalty: small unusable residuals are bad.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer fuller bins relative to mean residual of open bins.
    if (bin_residual as f64) > mean_residual {
        score -= (bin_residual as f64 - mean_residual) * 0.15;
    } else {
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    // Early in the stream, allow opening bins more freely; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when
        // decent fitting bins exist.
        let mut new_bin_penalty = 55.0 + 45.0 * progress;
        if fitting_bins_count > 0 && post_residual == bin_capacity {
            // only attractive if existing bins would leave bad residuals
            new_bin_penalty -= 20.0 * (1.0 - progress);
        }
        if open_bins_count > 8 {
            new_bin_penalty += 15.0;
        }
        score += new_bin_penalty;
    }

    // Mild tie-break toward fewer open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit any plausible
    // future item are wasted. Punish sharply when post_residual falls into
    // the "unusable gap" zone (very small but nonzero).
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - pr / 10.0);
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0 * (1.0 - (pr - 10.0) / 10.0);
    }

    // Reward tight fits (item nearly fills the bin).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.85 {
        score -= 30.0 * (fill_ratio - 0.85) / 0.15;
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Perfect-fit lookahead: if the next item exactly fills the post residual,
    // strongly favor this bin (creates a full bin pair).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Mild reward if the next item still fits after this placement.
        score -= 5.0;
    } else if next_item_size > post_residual && post_residual > 0 && next_item_size <= bin_capacity {
        // The leftover would be useless for the imminent item: penalize if
        // the gap is small relative to next item size.
        let gap_deficit = (next_item_size - post_residual) as f64;
        score += 8.0 * (gap_deficit / next_item_size as f64).min(1.0);
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are fragmented
    // (high mean residual spread) or the item cannot fit well anywhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // Attractive when existing bins are mostly full (low mean residual).
        score -= (mean_residual / bin_capacity as f64) * 10.0;
        // Penalize opening new bins when many bins can already fit the item.
        score += 5.0 * (fitting_bins_count as f64).min(5.0);
        // Early in the stream, opening bins is fine; later, prefer packing.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += (open_bins_count as f64).sqrt() * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: next item seals this bin
        } else if next_item_size <= post_residual {
            // partial lookahead fit, scaled by how much of post_residual is used
            let usage = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * usage;
        } else {
            // next item cannot fit here; penalize leaving awkward gaps
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    }

    // Relative to mean residual: bins with residual far below mean are "tighter",
    // prefer packing into them to keep wide bins flexible.
    let dev = mean_residual - post_residual as f64;
    score += 0.5 * dev;

    // Penalize creating dead space relative to typical next item sizes.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-seal bonus
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless no decent fit exists.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If nothing else fits, opening is fine
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild pressure to fill nearly-full bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Penalize wasted residual quadratically, but discount small dead space
    let waste = post_residual as f64;
    score += 0.35 * (waste / cap) * (waste / cap) * cap;

    // Reward tight fits: exact fill is ideal
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead: if next item fits in the post residual, reward this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            score -= 8.0 + 4.0 * (nxt / cap);
        } else {
            // Next item won't fit here; penalize leaving moderately large gaps
            score += 3.0 * (post_residual as f64 / cap);
        }
        // If next item fits better elsewhere, slight nudge
        if (bin_residual as f64 - nxt) >= 0.0 && (bin_residual as i64 - next_item_size as i64) < (post_residual as i64) {
            score -= 2.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Global pressure: many open bins -> prefer filling existing ones
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0));
    score += 0.02 * pressure * (item_size as f64 / cap);

    // Mean residual coupling: if this bin is much tighter than average, prefer it
    let tightness = mean_residual - bin_residual as f64;
    score += 0.15 * tightness;

    // Time horizon: early in stream, be picky about large gaps; late, fill greedily
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.25 * progress;

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 18.0 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing fits, must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Smooth non-linear coupling: post-residual shaped by progress polynomial
    let poly = 1.0 + 0.8 * progress - 0.6 * progress * progress;
    let mut score = pr * poly;

    // Penalize large wasted residual that no plausible item can use, smoothly
    let waste = (x * x) * cap * (0.3 + 0.5 * progress);
    score += waste;

    // Reward tight fits: small post_residual relative to item
    let item = item_size as f64;
    score -= 2.0 * item * (1.0 - x).max(0.0);

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward residual that can host next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if pr as f64 >= nx { 1.0 } else { 0.0 };
        score -= 6.0 * fits_next * (1.0 - (pr - nx) / cap).max(0.0);
        // penalize leaving residual just below next item size (dead space)
        let gap = (nx - pr) / cap;
        if gap > 0.0 {
            score += 8.0 * (gap * (1.0 - gap)).max(0.0);
        }
    }

    // Mild pressure against opening new bins late in stream
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * progress;
    }

    // Balance across open bins: prefer bins below mean residual slightly
    score += 0.15 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into a
    // "usable" residue class (divisible by common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let harmonic_bonus = if pr % 10 == 0 { 12.0 }
            else if pr % 5 == 0 { 6.0 }
            else if pr % 20 == 0 { 15.0 }
            else { 0.0 };
        score -= harmonic_bonus;
        // Penalize tiny unusable slivers harder as they get smaller.
        if pr < 10 {
            score += (10 - pr) as f64 * 2.5;
        }
    } else {
        // Perfect fit is the best outcome.
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chained harmonic match).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = post_residual - next_item_size;
        score -= 18.0;
        if chain % 10 == 0 { score -= 6.0; }
        if chain == 0 { score -= 25.0; }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead-end: next item cannot use this leftover.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin early in the stream or
    // when many open bins still have room matching the item's harmonic class.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 20.0 * progress;
        if open_bins_count > 0 {
            score += 10.0;
        }
        // A new bin is attractive only for large items relative to capacity.
        score -= 10.0 * fill_ratio;
    }

    // Prefer bins whose residual is below the mean residual (better packed).
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Integer-division threshold: leftover >= half capacity is wasteful
    // (should have gone to a fuller bin).
    if post_residual >= bin_capacity / 2 && !is_new_bin {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Penalize leaving gaps that no typical item can use relative to mean residual.
    if post_residual as f64 > mean_residual {
        score += 0.6 * (post_residual as f64 - mean_residual);
    }

    // Open-bin pressure: discourage spreading across many bins when not needed.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., many bins fit but this residual is full capacity) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 + 30.0 * (1.0 - progress) + 1.5 * fitting_bins_count as f64;
        // Lookahead: if next item could pair with this item, opening a fresh bin helps.
        if next_item_size > 0 && (next_item_size as f64 + item_size as f64) <= bin_capacity as f64 {
            score -= 55.0;
        }
    } else {
        // Lookahead synergy: leaving room for the next item is good.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 && post_residual > 0 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect closure: item exactly fills the bin.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins where the next item fits the leftover space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step match: both items tile the bin.
            score -= 150.0;
        } else if next_item_size < post_residual {
            // Next item fits, penalize proportional leftover after that too.
            let two_step_left = post_residual - next_item_size;
            score -= 60.0 - two_step_left as f64 * 0.5;
        } else if next_item_size == post_residual + item_size && item_size >= next_item_size {
            // Next item could pair with current item differently; mild signal.
            score -= 10.0;
        } else {
            // Next item cannot use the leftover: dead space penalty grows with gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Prefer tight fits relative to mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.4;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Discard the brand-new-bin candidate unless current fit is very poor.
    if bin_residual == bin_capacity {
        score += 120.0;
        // But allow new bin when open bins are all crowded.
        score -= (mean_residual < 20.0) as i32 as f64 * 90.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.5;

    // Slight progression term: later in stream, favor closing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0 * (post_residual == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more strongly via non-linear shaping.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for the smallest plausible item (1..100 range):
    // unusable slivers are worthless, but leave room for small follow-ups.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow in this bin: mild penalty, worse if post residual is large.
            score += 8.0 + (post_residual as f64) / (bin_capacity as f64) * 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins with less residual (best-fit pressure).
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score += (mean_residual - item_size as f64) * 0.2;
    }

    // Time horizon: early in the stream, be more willing to open new bins (score for
    // empty bin candidate lower); late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus early-stream discount.
        score = bin_capacity as f64 - 60.0 * (1.0 - progress) + 20.0 * progress;
        // If the item fits nowhere else, opening is forced; handled by fitting_bins_count == 0.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else if progress > 0.7 {
        score -= 10.0 * progress;
    }

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Base: waste left behind, with non-linear polynomial shaping
    let mut score = pr_norm.powf(1.6) * 40.0;

    // Smooth interaction: waste penalized more as stream progresses
    score += pr_norm * progress * 25.0;
    score -= pr_norm * pr_norm * progress * 12.0;

    // Reward tight fits (small post_residual) more strongly via cubic term
    score -= (1.0 - pr_norm).powi(3) * 15.0;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * (1.0 - progress);
    }

    // Many open bins: prefer filling existing ones over opening new
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // New-bin candidate: penalize mildly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 22.0 - 10.0 * progress;
    }

    // Lookahead coupling: if next item fits the post residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0 * (1.0 - (nxt / cap));
        } else {
            score += 5.0 * ((nxt - pr) / cap);
        }
    }

    // Mean residual alignment: prefer bins near mean residual for balance
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Penalize residuals that fall into "dead" harmonic classes:
    // residuals in (0,10] are nearly useless; (10,30] moderately useful.
    let class = (post_residual / 10).min(10);
    match class {
        0 => score += 25.0,                 // 0..=9: dead space
        1 => score += 12.0,                 // 10..=19: poor
        2 | 3 => score += 4.0,              // 20..=39: ok
        4 | 5 | 6 => score -= 6.0,          // 40..=69: good mid-space
        _ => score -= 3.0,                  // large residual
    }

    // Perfect / near-perfect fits strongly rewarded
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Modulo coupling: post_residual that is a multiple of common small sizes
    // (e.g. divisible by 20) is more likely to be reused by future items.
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let nxt = next_item_size as f64;
            let after = post_residual - next_item_size;
            score -= 15.0 - (after as f64) * 0.15;
            // harmonic class of the doubly-post residual
            if after % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this residual: penalize tight fits less harshly
            let slack = (next_item_size - post_residual) as f64;
            score += slack * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // or current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap;
        let fragmentation = (mean_residual - pr).abs();
        score = 30.0 - large_item * 35.0 + fragmentation * 0.3
            + (open_bins_count as f64) * 0.5;
        if next_item_size > item_size {
            score -= 10.0; // reserve fresh bin for bigger next item
        }
    }

    // Stream progression: later in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - frac);

    // Slight preference for bins with residual close to mean (balance)
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fill is the ideal outcome.
        score -= 120.0;
    } else {
        // Reward leaving large, reusable residual space.
        score -= 0.35 * post_residual as f64;
    }

    // Coupling: exact fit of the current item (zero post_residual) is best; near-fit slightly worse.
    if post_residual > 0 && post_residual <= 5 {
        score += 25.0; // tiny dead space is nearly as bad as unusable gap
    }

    // Lookahead synergy: if the next item fits exactly in the post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 30.0; // next item fits snugly
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use: penalize proportionally to how close it is.
        score += 15.0 * (1.0 - (next_item_size - post_residual) as f64 / next_item_size as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open and fit is decent.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin baseline: attractive only if current fit is bad.
        score += 40.0 + 2.0 * open_bins_count as f64;
        // If the item fits tightly in an existing bin, opening a new bin is wasteful.
        if post_residual < 15 && fitting_bins_count >= 1 {
            score += 90.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
    } else {
        // Mild reward for consolidating into bins that are already open.
        score -= 0.05 * open_bins_count as f64;
        // Prefer bins whose residual is below the mean residual (tighter bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 50.0;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 10.0;
    }

    // Penalize dead space that cannot fit the next item (waste)
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Prefer bins tighter than average residual (good fit)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins fit well
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // new bin still allows lookahead match
        }
    }

    // Late in stream: consolidate, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (open_bins_count as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powi(4);

    // Penalize dead space that is too small to be useful later (below min item size 1... use 10 heuristic band).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 8.0; // still-usable pocket
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if next item fits in the post residual, reward; if it barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.15 * next_item_size as f64;
        } else if next_item_size <= bin_residual && post_residual > 0 {
            score += 6.0; // placing here breaks a perfect pair fit
        }
    }

    // Global state: prefer filling bins when many are open (consolidation pressure).
    score -= 0.8 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Mean-residual coupling: if this bin's residual is far below mean, it's a "ragged" bin — fill it.
    let dev = mean_residual - post_residual as f64;
    score += 0.25 * dev;

    // Time horizon: early in stream, be more willing to open new bins (score new bins mildly better);
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 25.0 * (1.0 - progress); // new bins attractive early
        score += 15.0 * progress;         // discouraged late
    } else {
        score -= 10.0 * progress;         // favor existing bins late
    }

    // Mild exact-fill jackpot.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - pr / cap; // how full bin becomes

    // Smooth non-linear coupling: reward tight fits more as stream progresses
    let progress_gain = (tightness * tightness) * (1.0 + 2.0 * t) * 8.0;
    score -= progress_gain;

    // Penalize dead space: cubic penalty on small residuals
    let dead = if pr < 10.0 { (10.0 - pr) * (10.0 - pr) * (10.0 - pr) * 0.05 } else { 0.0 };
    score += dead;

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0 + 6.0 * t;
    }
    // Penalize residual that is unusably small for typical next items
    if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
        score += (next_item_size as f64 - pr) * 0.15;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // New-bin candidate: penalize mildly, more when open bins are empty-ish
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - t);
    }

    // Mean residual alignment: prefer bins below mean residual (tighter bins)
    score += (mean_residual - pr) * 0.1;

    // Slight preference to fill bins when many are open
    score += open_bins_count as f64 * 0.02 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: modulo classes on capacity fractions
    let post_class = post_residual % 10;
    let post_quotient = post_residual / 10;

    // Reward small post_residual, but strongly reward residuals in "useful" classes
    // Classes 0..3 (tiny dead space) are excellent; classes 8..9 are bad.
    match post_class {
        0 => score -= 18.0,
        1 => score -= 14.0,
        2 => score -= 11.0,
        3 => score -= 8.0,
        4 => score -= 3.0,
        5 => score += 2.0,
        6 => score += 4.0,
        7 => score += 6.0,
        8 => score += 9.0,
        _ => score += 12.0,
    }

    // Non-linear bonus for very tight fits (post_residual near zero)
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: if the next item can fit into the post_residual, big reward
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward more when the lookahead leaves a good harmonic class again
            let next_post = post_residual - next_item_size;
            let nc = next_post % 10;
            let lookahead_bonus = 20.0 - 0.15 * (next_post as f64);
            let class_bonus = if nc <= 3 { 8.0 } else if nc >= 8 { -4.0 } else { 0.0 };
            score -= lookahead_bonus + class_bonus;
        } else {
            // Post-residual too small for the next item: penalize by wasted fraction
            let wasted = post_residual as f64 / cap_f;
            score += 6.0 * wasted;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap_f);
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty so we prefer filling existing bins...
        score += 40.0;
        // ...but relax it when mean residual is small (bins nearly full)
        score -= 30.0 * (1.0 - (mean_residual / cap_f).min(1.0));
        // Late in the stream, opening fresh bins is cheaper (less future waste)
        score -= 10.0 * progress;
        // Many open bins with high residual => prefer spreading into new bin
        if mean_residual > 0.5 * cap_f && open_bins_count > 3 {
            score -= 12.0 + 0.5 * pressure.min(20.0);
        }
    }

    // Prefer bins whose residual is close to item_size (best-fit sharpening)
    let diff = (bin_residual as f64 - item_size as f64);
    score += 0.05 * diff;

    // Slight preference to balance residual mass across open bins
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.03 * dev;
    }

    // Integer-division threshold coupling: bins with residual in [40,60] are flexible
    if post_quotient >= 4 && post_quotient <= 6 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly unusable.
    if post_residual > 0 {
        // Penalize tiny leftovers heavily (they are dead space).
        if post_residual <= 10 {
            score += 60.0 * (1.0 - post_residual as f64 / 10.0);
        } else if post_residual < 30 {
            score += 25.0 * (1.0 - (post_residual as f64 - 10.0) / 20.0);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Lookahead: if the post_residual can host the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 10.0 * (1.0 - post_residual as f64 / (post_residual as f64 + next_item_size as f64));
    }
    // If next item would not fit here but nearly fits, slight penalty for wasting potential.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    if bin_residual != bin_capacity {
        score -= 20.0 * pressure;
    } else {
        // New-bin candidate: penalize unless few bins open or current fits are terrible.
        score += 30.0 + 25.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins whose residual is close to the item (relative waste small).
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 40.0 / (post_residual as f64).powf(1.5);
    }

    // 2-step lookahead: if next item fits the post residual, big bonus.
    if next_item_size > 0 {
        let slack = post_residual as i64 - next_item_size as i64;
        if slack == 0 {
            score -= 500.0; // perfect chaining of two items
        } else if slack > 0 {
            // reward chains, more so when the leftover after the chain is small
            score -= 120.0 - (slack as f64).min(60.0) * 1.5;
        } else {
            // chain broken: penalize wasted space relative to next item
            score += (next_item_size as f64 - post_residual as f64) * 0.6;
        }
    }

    // Compare residual against mean residual of open bins: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.35;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive if current bin would leave a large, unusable
    // residual that no plausible next item (min size 1) can chain into.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 60.0;
        // more bins already open -> mild reluctance to add more
        score += open_bins_count as f64 * 1.0;
        // but if placing here would strand a lot of space with no lookahead fit, allow new bin
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= (post_residual as f64) * 0.5;
        }
        // early in stream: opening bins is cheaper (need spread)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 25.0;
    }

    // Mild preference to keep large residuals in fewer bins (consolidation pressure)
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalty scaled down.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64 * 4.0);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: bonus if this bin's post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            // Penalize leaving dead space the next item cannot use.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, but allow it when
    // existing residuals are large relative to the item (poor fits elsewhere)
    // or early in the stream when many items remain to build good bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_alternatives = if fitting_bins_count > 0 {
            (mean_residual - item_size as f64).max(0.0)
        } else {
            10.0
        };
        score += 30.0
            - 0.3 * poor_alternatives
            - 15.0 * (1.0 - progress);
        // Don't open a new bin when a last-chance bin exists.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    }

    // Mild preference for filling bins with larger residuals (balance load),
    // encouraging consolidation as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 0.05 * progress * (bin_residual as f64 - mean_residual);

    // Penalize scattering across many open bins.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer small post-residual, with non-linear polynomial shaping.
    let mut score = post;
    score += 12.0 * norm_post * norm_post * cap;

    // Tight-fit reward: smooth quadratic bonus near zero post-residual.
    let tightness = 1.0 - norm_post;
    score -= 8.0 * tightness * tightness * tightness;

    // Dead-space penalty grows with stream progress (waste matters more later).
    score += (10.0 + 20.0 * progress) * norm_post * norm_post;

    // Lookahead coupling: penalize post-residual that can't fit next item;
    // reward residual that exactly accommodates the next item (smooth kernel).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score += 3.0 * (gap / cap);
        let fit_kernel = (-4.0 * (post - nxt) * (post - nxt) / (cap * cap)).exp();
        score -= 10.0 * fit_kernel;
        // If next item is large, leaving moderate residual is worse.
        score += 0.05 * nxt * norm_post;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: baseline cost plus penalty scaling with open bins
    // and mean residual (fragmentation already present discourages new bins),
    // softened late in the stream.
    if is_new_bin {
        score += 25.0 + 3.0 * open_bins_count as f64 + 0.5 * mean_residual;
        score -= 12.0 * progress;
        // Opening a new bin is more attractive if the item leaves a very
        // tight residual anyway (item nearly fills a bin).
        score += 0.3 * item_size as f64 * (1.0 - progress);
    }

    // Many open bins: prefer consolidating into existing bins.
    score += 0.02 * open_bins_count as f64 * norm_post * cap;

    // Divergence from mean residual: prefer bins with residuals close to the
    // mean to keep fragmentation uniform (smooth quadratic term).
    let dev = (post - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small moduli
    // penalize residuals that are awkward (hard to fill by typical items).
    let pr = post_residual as i64;
    let residue4 = (pr % 4) as f64;
    let residue8 = (pr % 8) as f64;
    let residue16 = (pr % 16) as f64;
    score += 0.8 * residue4 + 0.4 * residue8 + 0.2 * residue16;

    // Integer-division thresholds: reward residuals that sit in "fillable bands"
    // (items 10..80 -> residuals near multiples of 10 are easier to pair).
    let band = pr / 10;
    let band_target = band * 10;
    let band_gap = (pr - band_target) as f64;
    score += 1.5 * band_gap;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead coupling: reward leaving space the next item can use.
    if next_item_size > 0 {
        if post_residual == next_item_size as u32 {
            score -= 40.0;
        } else if post_residual > next_item_size as u32 {
            let leftover = post_residual - next_item_size as u32;
            // good if next item fits and leaves small remainder
            score -= 12.0 - 0.3 * (leftover.min(40) as f64);
        } else {
            // next item cannot fit here: mild penalty scaled by gap
            score += 0.2 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer tighter bins relative to mean residual across open bins.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Discourage spreading across many bins early; encourage consolidation later.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    // New-bin candidate: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 45.0 + 10.0 * progress * open_bins_count as f64;
        // allow new bin when item is large and no bin fits tightly
        if item_size >= 60 && fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Mild penalty for very large dead space zones (unfillable by min item 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 - (post_residual as f64) * 4.0; // gap of 1..10 => +56..+20
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit is excellent
    }

    // Reward tight fits relative to capacity (waste fraction).
    score += (post_residual as f64 / bin_capacity as f64) * 25.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bin would leave a bad gap
    // or the item barely fits elsewhere.
    if bin_residual == bin_capacity {
        let bad_gap = post_residual > 0 && post_residual <= 10;
        if bad_gap {
            score -= 45.0; // opening fresh bin avoids creating dead space
        } else {
            score += 15.0; // default: prefer existing bins
        }
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would be blocked by the resulting gap, penalize slightly.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below mean, it's a
    // good consolidation target.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight non-linearity
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Aggressive 2-step lookahead: reward if next item fits into post_residual exactly
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 0.5 {
            // Perfect pairing: huge reward
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits: good, reward proportional to how much slack remains after next item
            let after_next = post_residual as f64 - next;
            score -= 20.0 - after_next * 0.3;
        } else {
            // Next item won't fit here: penalize wasted pairing potential
            score += 8.0;
        }
    }

    // Reward bins with residual below mean (densely packed bins get filled further)
    score += (mean_residual - post_residual as f64) * 0.15;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large relative to capacity
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 40.0 * (1.0 - fill_ratio);
        // Early in the stream, opening bins is cheaper; later, prefer consolidation
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
    }

    // Slight penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (near-perfect packing).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 40.0;

    // Penalize wasting a nearly-full bin on a small item.
    let fill_ratio = (item_size as f64) / (bin_residual as f64);
    if fill_ratio < 0.35 {
        score += 12.0 * (0.35 - fill_ratio);
    }

    // Lookahead: reward bins whose residual can host the next item (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (next_item_size as f64 / (post_residual as f64).max(1.0));
    }
    // Penalize leaving a residual that is awkwardly larger than the next item.
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap < 10.0 {
            score += gap * 0.8;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }
    // Many fitting bins: mild penalty to keep options open? No — reward any fit slightly.
    if fitting_bins_count > 1 {
        score -= 2.0;
    }

    // New-bin candidate logic: opening a new bin costs ~a full bin of residual.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 55.0;
        // Cheaper to open a new bin when existing bins are crowded with small residuals.
        score -= mean_residual.min(60.0);
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // If the item is large, a fresh bin wastes less; discount.
        score -= (item_size as f64) * 0.3;
        // If no open bin fits (fitting count excludes new bin), discount more.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    } else {
        // Prefer fuller bins: reward using bins with small residual.
        score -= (bin_capacity as f64 - bin_residual as f64) * 0.15;
    }

    // Global pressure: when many bins are open, discourage spreading.
    score += (open_bins_count as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let tightness = 1.0 - (r / cap);

    let mut score = r;

    // Reward tight fits: strongly favor bins where post_residual is small
    let tight_bonus = (r / cap).powf(2.0) * cap * (0.5 + 0.5 * progress);
    score -= tight_bonus;

    // Penalize leaving residuals that are hard to fill (near but below typical item sizes)
    let awkward = (r / cap - 0.5).abs();
    score += awkward * awkward * cap * 0.3;

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= r {
        let combo = (item_size as f64 + next_item_size as f64) / cap;
        score -= (1.5 - combo).abs().max(0.0) * 8.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        // next item won't fit here: slight penalty proportional to wasted opportunity
        score += 2.0 * (r / cap);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - tightness);
    }

    // New-bin candidate: penalize opening new bins, more so early and when fit exists elsewhere
    if bin_residual == bin_capacity {
        let spread = (mean_residual - cap * 0.5).abs();
        score += 25.0 + 10.0 * (1.0 - progress) + 0.05 * open_bins_count as f64 + spread * 0.1;
    }

    // Mild non-linear coupling of fit ratio with progress: prefer big items in fresh space later
    score -= fit_ratio * fit_ratio * 4.0 * progress;

    // Regularize toward mean residual balance across open bins
    score += (mean_residual - r) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by
    // capacity fractions (1/4, 1/2, 3/4) using integer division thresholds.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarters = 3 * bin_capacity / 4;

    // Dead-space penalty: residuals that are too small to host typical items.
    if post_residual < quarter {
        // Very small leftover: mostly dead space, but small residuals are
        // "clean" fills. Penalize proportionally to how far below quarter.
        score += (quarter - post_residual) as f64 * 1.5;
    } else if post_residual < half {
        // Mid-low leftover: good, usable window. Reward.
        score -= (half - post_residual) as f64 * 0.8;
    } else if post_residual < three_quarters {
        // Mid-high leftover: still very reusable, reward more.
        score -= (three_quarters - post_residual) as f64 * 0.6;
    } else {
        // Huge leftover means item barely fit; poor packing, penalize.
        score += (post_residual - three_quarters) as f64 * 0.4;
    }

    // Harmonic modulo logic on post_residual: residues near multiples of
    // small item sizes are more likely to be filled by future items.
    let r = post_residual % 10;
    if r == 0 {
        score -= 4.0; // perfectly divisible residual: harmonically clean
    } else if r <= 3 {
        score -= 1.5;
    } else if r >= 7 {
        score += 1.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if next item is close, mild reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= quarter {
                score -= 10.0 - slack as f64 * 0.2;
            }
        } else {
            // Next item cannot fit here: if this bin is the only fitting one,
            // place here anyway to avoid opening a bin the next item can't use.
            score += 2.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when open
    // bins are fragmented (high mean residual spread vs. this fit).
    if bin_residual == bin_capacity {
        // Base reluctance to open new bins.
        score += 20.0;
        // If many bins fit the item, definitely prefer reusing one.
        if fitting_bins_count > 1 {
            score += 15.0;
        }
        // If mean residual across open bins is large, open bins are wasted;
        // opening fresh may be fine, reduce reluctance.
        if mean_residual > half as f64 {
            score -= 10.0;
        }
        // Late in the stream, fewer items remain to fill leftovers; slight
        // extra reluctance to open bins early, less late.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 5.0;
    }

    // Prefer filling bins that are already partially committed, to compact
    // the packing: reward low residual relative to mean.
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= (mean_residual - bin_residual as f64) * 0.3;
        } else {
            score += (bin_residual as f64 - mean_residual) * 0.2;
        }
    }

    // Slight preference for fewer open bins overall.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard reward for exact / near-exact fits (dead space elimination).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0;
    }

    // Strict dead-space avoidance: residuals too small to be useful later are penalized.
    // A residual gap is "unusable" if it is smaller than the minimum plausible item (1..100
    // stream => treat gaps < 10 as dead, and gaps < next_item_size as dead when lookahead exists).
    let dead_threshold = if next_item_size > 0 { next_item_size.min(10).max(1) } else { 10 };
    if post_residual > 0 && post_residual < dead_threshold {
        score += 120.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= 2.0 * (post_residual - next_item_size) as f64;
        } else {
            // Next item cannot use this gap: penalize proportional to wasted potential.
            score += 0.5 * (next_item_size - post_residual).min(post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 50.0);
    if bin_residual != bin_capacity {
        score -= 0.5 * open_pressure;
    } else {
        // New-bin candidate: penalize more when open bins are still roomy (mean residual high).
        score += 20.0 + 0.3 * mean_residual + 2.0 * open_bins_count as f64;
    }

    // Slight preference for filling bins with small residuals early (tight packing).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Stream progression: late in the stream, be more conservative about new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 30.0 * progress;
        } else {
            score -= 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose residual matches the next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 500.0;
        } else {
            score -= 150.0 * (1.0 - diff as f64 / bin_capacity as f64);
        }
        // Penalize residuals too small for the next item (dead space)
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize large wasted residual relative to mean residual
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize slightly so we prefer reusing open bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 50.0 + 0.2 * item_size as f64;
        // But opening a new bin is attractive late in the stream when many bins are open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * progress;
    }

    // Mild penalty for too many open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic discount for small post_residual.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that no future item can plausibly use
    // (items are 1..=100, so residual < 1 is only relevant via granularity).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver is wasted capacity
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty scaled by how far off
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 * (gap / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Discourage spreading across many open bins when mean residual is high:
    // prefer filling bins that are below-average full (large residual) to consolidate.
    if open_bins_count > 1 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, just close out bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.10 * post_residual as f64;
    score -= progress * 5.0;

    // New-bin candidate: only attractive when nothing fits well anywhere.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin, discounted when current bins fit poorly
        let poor_fit = if post_residual > 0 { 1.0 } else { 0.0 };
        score += 18.0 - 10.0 * poor_fit * (fitting_bins_count as f64).min(3.0) / 3.0;
        // if lookahead item is large, a fresh bin is more valuable
        if next_item_size >= item_size {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: penalize leftover space, with a super-linear (quartic) coupling
    // so large dead space is punished disproportionately more late in the stream.
    let norm_post = post / cap;
    let mut score = post * (1.0 + 2.0 * progress * norm_post * norm_post);

    // Smooth cubic interaction: waste penalty grows as the stream progresses
    // and as the bin approaches exhaustion (small residuals become "dead").
    let fill_ratio = 1.0 - norm_post;
    score += 20.0 * progress * fill_ratio * fill_ratio * fill_ratio * (post / 10.0);

    // Reward tight fits: if the item nearly fills the bin, subtract a bonus.
    let tightness = (item_size as f64 / bin_residual.max(1) as f64).clamp(0.0, 1.0);
    score -= 15.0 * tightness * tightness;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (penalize new-bin opening instead).
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead coupling: if the next item could use the post-residual exactly
    // or nearly, reward leaving that space; otherwise penalize hoarding space
    // that nothing upcoming can use.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (post - next).abs();
        let usable = (1.0 - gap / cap).clamp(0.0, 1.0);
        if next <= post {
            score -= 12.0 * usable * usable;
        } else {
            score += 6.0 * (1.0 - usable);
        }
    }

    // Alignment with mean residual across open bins: bins whose residual is
    // far below the mean are close to closing; prefer placing there to
    // consolidate (smooth sigmoid-like coupling, no piecewise constants).
    let dev = (mean_residual - post) / cap;
    let sigmoid = 1.0 / (1.0 + (-4.0 * dev).exp());
    score += 8.0 * (sigmoid - 0.5);

    // Mild penalty for spreading across too many open bins when residuals
    // are large (fragmentation pressure), scaled smoothly.
    let frag = open_bins_count as f64 / (1.0 + total_items as f64).sqrt();
    score += 2.0 * frag * norm_post;

    // New-bin candidate (empty bin): give it a moderate baseline score so it
    // only wins when existing bins have genuinely bad fits.
    if bin_residual == bin_capacity {
        score += cap * 0.5 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls on coarse
    // granularity classes (multiples of 10/25/50) are more reusable.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -1000.0 // perfect fit, always reward heavily
    } else if pr % 50 == 0 {
        -60.0
    } else if pr % 25 == 0 {
        -40.0
    } else if pr % 10 == 0 {
        -25.0
    } else if pr % 5 == 0 {
        -10.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Dead-space penalty: residuals too small for the smallest plausible item (<= 9)
    // are unusable dead space; penalize proportionally to how close we are to that zone.
    if pr > 0 && pr < 10 {
        score += 80.0 + (10 - pr) as f64 * 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit, penalize mildly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / cap_f);
        } else {
            score += 15.0;
        }
    } else {
        // last item: any placement is fine, prefer tightest
        score += 0.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: empty bin. Score it as a fresh residual minus a
    // moderate opening cost, so it wins only when fits into open bins are bad.
    if bin_residual == bin_capacity {
        score = cap_f - (open_bins_count as f64).ln().max(0.0) * 5.0
              + (item_size as f64 / cap_f) * 10.0
              - if fitting_bins_count == 0 { 200.0 } else { 0.0 };
        // discourage opening when many bins already fit the item
        score += fitting_bins_count as f64 * 30.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "cramped" bin; placing here consolidates fragmentation.
    let res_f = bin_residual as f64;
    let deviation = mean_residual - res_f;
    if deviation > 0.0 {
        score -= deviation * 0.3;
    } else {
        score += (-deviation) * 0.1;
    }

    // Slight preference for filling bins earlier in the stream (keep late flexibility)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: fraction of residual consumed.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Open-bin pressure: penalize placements in bins when many bins are open,
    // encouraging consolidation into fewest bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly
    // everywhere else; the pressure grows with how many bins could fit the item.
    if bin_residual == bin_capacity {
        score += 25.0 + fitting_bins_count as f64 * 10.0;
        // But if the item is large relative to capacity, opening a fresh bin is fine.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Lookahead: if next item would fit into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item cannot fit post residual but could fit bin residual, slight penalty.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Late-stream consolidation: as the stream progresses, avoid spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression factor: early in the stream, be conservative; late, pack tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact match, decaying quadratically with distance.
        score -= 60.0 * (-diff / 12.0).exp();

        // Penalize dead space that the next item cannot use.
        if post_residual < next_item_size {
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: minimize waste directly.
        score += 0.5 * post_residual as f64;
    }

    // Compare against mean residual across open bins: prefer bins whose post_residual
    // sits below the mean (tightening well-packed bins) and penalize above-mean slack.
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, heavily reward using it
    // to avoid opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.3 * progress);
    }

    // New-bin candidate: neutral-ish baseline; only attractive when the item is large
    // (would leave little residual anyway) or many bins are already open.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.4 * item_size as f64 + 2.0 * open_bins_count as f64 * (1.0 - progress);
    }

    // Slight preference for tighter fits overall.
    score += 0.15 * (bin_residual - item_size) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * 1.0;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: residual usable by next item is good; otherwise dead space penalty
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 0.6 * nxt.min(post);
        } else {
            // dead space that next item cannot use
            score += 0.4 * post;
        }
        // waste if residual too small for typical items
        if post < 10.0 {
            score += 0.5 * (10.0 - post);
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening new bins unless current fits are poor
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && next_item_size > post_residual {
            // empty bin can hold next item exactly; slight bonus
            score -= 5.0;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // many open bins with slack: discourage new bin
        score += 2.0 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    }

    // Prefer filling bins with larger residual usage ratio
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    score -= 10.0 * fill;

    // Mild penalty for leaving residual far from common item sizes
    if post > 0.0 {
        let misfit = (post / 10.0).fract();
        score += 0.3 * misfit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 8.0 * coupling;

    // Penalize large waste late in the stream (quadratic in progress)
    score += progress * progress * pr * 0.15;

    // Reward tight fits (small post_residual) with a smooth saturating term
    score -= (item_size as f64 / cap) * (1.0 - norm_pr) * 6.0;

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward if next item fits the post residual (smooth kernel)
    if next_item_size > 0 {
        let fits_next = if (pr >= next_item_size as f64) { 1.0 } else { 0.0 };
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 10.0 * fits_next * (1.0 - gap);
        score += 5.0 * (1.0 - fits_next) * (1.0 - gap);
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += (open_bins_count as f64).ln().max(0.0) * (pr - mean_residual).abs() * 0.05;

    // New-bin candidate: penalize opening a new bin unless current residuals are poor
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that pair well with future items.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else {
        // modulo arithmetic on residual classes
        let m = pr % 10;
        match m {
            0 => score -= 25.0,           // round residual, highly reusable
            1 | 9 => score += 18.0,       // awkward 1-off residuals
            2 | 8 => score += 8.0,
            5 => score -= 6.0,            // half-of-ten class, pairs with many sizes
            _ => {}
        }
        // integer-division thresholds: residual in [10,20) is a sweet spot
        let d = pr / 20;
        match d {
            0 => score += 22.0,           // tiny residual: likely dead space
            1 => score -= 14.0,           // 20..40: excellent
            2 => score -= 6.0,            // 40..60: good
            3 => score -= 2.0,
            _ => score += 4.0,
        }
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0 + (next_item_size as f64) * 0.15;
            // exact pairing bonus
            if pr == next_item_size {
                score -= 30.0;
            }
        } else {
            // wasted lookahead opportunity, worse the closer it was
            let gap = (next_item_size - pr) as f64;
            score += (gap * 0.25).min(20.0);
        }
    } else {
        // last item: prefer tightest fill
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin gets a baseline anchored to mean residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing bins are already fragmented.
        score = cap * 0.55 + mean_residual * 0.6 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // keep fresh capacity for a bigger follower
        }
        // early in stream, fresh bins are cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
    } else {
        // prefer bins whose residual is above the mean (consume the roomy ones)
        score += (mean_residual - bin_residual as f64) * 0.3;
        // slight preference to keep few bins open
        score -= (open_bins_count as f64) * 0.5;
    }

    // Capacity fraction harmonics on fill ratio
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= fill * fill * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item are wasted.
    // Treat post_residual in (0, 10) as pure loss; scale penalty steeply.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead-space penalty: post_residual that cannot host the lookahead item
    // and is below the minimum item size is doubly bad.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }
    // Bonus if the leftover can still fit the next item (keeps bin useful).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 1.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: if this bin's residual is far below mean, it's a poor home.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = (bin_res_f - mean_residual) / mean_residual;
        score += 5.0 * dev.max(0.0);
    }

    // New-bin candidate handling: empty bin is a fallback; prefer it only when
    // no open bin offers a decent fit (fitting_bins_count == 0 handled implicitly,
    // but when only one bin fits, strongly prefer that last-chance bin).
    if bin_residual == bin_capacity {
        // Penalize opening new bins, but less when item is large or many bins open.
        let new_bin_penalty = 40.0 - 0.15 * item_size as f64 - 1.0 * open_bins_count as f64;
        score += new_bin_penalty.max(5.0);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (2-step lookahead archetype core).
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Reward if the next item fits into the post residual (chained placement).
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 60.0 + (post_residual as f64 - next_item_size as f64) * 0.5;
        }
        // Penalize dead space: post residual too small for any future item (min size 1).
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Compare post residual against mean residual across open bins: prefer bins
    // whose remaining space after placement is well below average (tight packing).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr).min(50.0) * 0.4;
    } else {
        score += (pr - mean_residual).min(50.0) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize unless open bins would be left with unusable
    // residual or the item is large relative to capacity (poor fit elsewhere).
    if bin_residual == bin_capacity {
        let tight_elsewhere = fitting_bins_count == 0
            || (next_item_size > 0 && next_item_size > post_residual && post_residual < next_item_size);
        if tight_elsewhere {
            score -= 40.0;
        } else {
            score += 120.0; // discourage opening new bins when decent fits exist
        }
    }

    // Early stream: be slightly more conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score += 30.0;
    }

    // Prefer bins with smaller residual before placement (best-fit flavor).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let mut score = post_residual as f64;

    // Tightness reward: squared post-residual strongly favors snug fits.
    let pr = post_residual as f64;
    score += 0.5 * (pr * pr) / cap;

    // Last-resort bonus: if this is the only fitting bin, heavily favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item (chaining),
    // penalize near-miss post_residuals that block the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 25.0 * (1.0 - (pr - nxt) / cap);
        } else if pr > 0.0 && nxt > pr && nxt <= bin_residual as f64 {
            score += 15.0;
        }
    }

    // New-bin candidate logic: only attractive when no open bin fits well
    // or the stream is early and spreading load is fine.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill_gap = (mean_residual - item).max(0.0);
        // Penalize opening a new bin when open bins already fit well.
        score += 40.0 + 0.3 * avg_fill_gap;
        // Early stream: slightly cheaper to open bins (spread items).
        score -= 30.0 * (1.0 - progress);
        // Many open bins: discourage proliferation.
        score += 2.0 * open_bins_count as f64;
    } else {
        // Reward using existing bins proportional to how full they become.
        let fill = 1.0 - pr / cap;
        score -= 20.0 * fill * fill;
    }

    // Mean-residual coupling: when open bins are on average roomy, prefer
    // consolidating into fuller bins to reduce fragmentation.
    if !is_new_bin {
        let tight = (mean_residual - pr).max(0.0);
        score += 0.2 * tight;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear quadratic coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let coupling = pr_norm * pr_norm * (0.5 + 2.0 * progress) * bin_capacity as f64;
    score += coupling;

    // Reward tight fits (small post_residual) more strongly later in the stream
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (item_size as f64) * (0.3 + 1.2 * progress);

    // Penalize waste relative to mean residual (dead space)
    score += 0.4 * (pr - mean_residual).abs();

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // New-bin candidate: prefer opening a new bin only when existing fits are poor
    if bin_residual == bin_capacity {
        let poor_fit = pr_norm > 0.5;
        let penalty = if poor_fit { -30.0 } else { 40.0 + 30.0 * (1.0 - progress) };
        score += penalty;
    }

    // Mild penalty for spreading across many bins early
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 500.0;
    } else if post_residual <= 15 {
        score -= 200.0;
    }

    // Harmonic class logic: quantize post_residual into capacity-fraction bands.
    // Dead space is worse when it falls into an unusable band (smaller than the
    // minimum plausible item). Use modulo arithmetic on post_residual.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        // unusable sliver: heavy penalty scaled by how "wasted" the bin was
        score += 120.0 + (10 - pr) as f64 * 10.0;
    }

    // Integer division thresholds: which harmonic slot does post_residual land in?
    let slot = pr / 10; // slots of width 10
    let slot_penalty = match slot {
        0 => 0.0,
        1 => -20.0,  // residual 10-19: still usable for small items
        2 => -35.0,  // residual 20-29
        3 => -45.0,  // residual 30-39
        4 => -50.0,  // residual 40-49: very flexible
        _ => -55.0,  // large residual left: bin underused, mild reward
    };
    score += slot_penalty;

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportional to how well it fills remainder
            let chained_waste = pr - next_item_size;
            score -= 150.0 - chained_waste as f64 * 3.0;
        } else {
            // next item won't fit here: slight penalty for leaving a bad gap
            score += 25.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // gives a decent fit. Penalize opening new bins, more so later in stream
    // and when many bins are already open with slack.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let slack_pressure = (mean_residual / cap).clamp(0.0, 1.0);
        score += 250.0 + 200.0 * progress + 150.0 * slack_pressure + (open_bins_count as f64) * 5.0;
    } else {
        // Prefer bins whose residual is below the mean (consolidate slack).
        let diff = mean_residual - bin_residual as f64;
        score += diff.clamp(-50.0, 50.0) * 0.8;
    }

    // Fractional capacity coupling: item_size relative to capacity.
    let item_frac = item_size as f64 / cap;
    // Large items (>= 0.5 capacity) should go into bins with small residual.
    if item_frac >= 0.5 {
        score += (bin_residual as f64 - item_size as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residual gaps that no typical item can use are costly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        // This gap cannot hold the lookahead item -> likely dead space.
        score += 12.0 + 0.3 * (post_residual as f64);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving a gap that exactly or nearly fits the next item.
        let gap_slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - gap_slack / bin_capacity as f64);
    }

    // Reward near-perfect packing (tight fit).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // but allow it when few bins exist (early stream).
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly worse than a decent fit.
        score += 5.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (open_bins_count as f64) * (1.5 + 2.0 * progress);
        // If the new bin would be very attractive for the lookahead item,
        // soften the penalty.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    } else {
        // Slight preference for bins with residual close to the mean
        // (keeps residuals balanced for future items).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Fragmentation risk: filling a large-residual bin with a tiny item is wasteful.
    if item_size <= 20 && bin_residual >= 80 && bin_residual < bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }

    // Partial lookahead: next item fits tightly into the leftover space
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = next_item_size as f64 / post_residual as f64;
        score -= 40.0 * tightness;
    }

    // Penalize dead space that next item cannot use
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Prefer bins below mean residual (tighter bins first)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Discourage opening new bins when many bins are open and fit exists
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Late in stream: consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: small post_residual is good; very small leftovers (<10) are nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: reward if the next item fits into post_residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // perfect chain: post_residual exactly equals next item
            if post_residual == next_item_size {
                score -= 6.0;
            }
        } else if post_residual + next_item_size > bin_capacity {
            // next item can't share with this one anywhere useful; slight penalty for wasting space
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // mild competition normalization: more options -> keep scores comparable
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate logic: opening a new bin is only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64; // full capacity - item
        let avg_fit_quality = (mean_residual - item_size as f64).max(0.0);
        // Base cost of a new bin, discounted early in the stream and when many bins already open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 30.0 - 10.0 * progress + 1.0 * (open_bins_count as f64).sqrt();
        // If no open bin fits well (mean residual after placement still large), opening is cheap.
        if avg_fit_quality > 20.0 {
            new_bin_cost -= 10.0;
        }
        // A new bin gives a perfect fit for large items.
        new_bin_cost -= 0.2 * item_size as f64;
        // Penalize opening new bin for small items (wasteful).
        if waste > 60.0 {
            new_bin_cost += 15.0;
        }
        score = score.min(f64::MAX) * 0.0 + new_bin_cost;
    }

    // Slight preference to fill already-open bins when many are open (bin count control).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: tight fit preferred (small post_residual), quadratic coupling with progress
    let mut score = pr * (1.0 + 0.5 * progress) + 0.0015 * pr * pr;

    // Strongly penalize opening a new bin when other bins can fit the item
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let waste = mean_residual.max(0.0);
        score += cap * (1.2 + 0.8 * (1.0 - progress)) + 0.5 * waste;
    }

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * (1.0 - progress);
    }

    // Lookahead: reward residuals that can still host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / cap) * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        // Penalize dead space that cannot fit the next item, scaled by its size
        score += 0.15 * (next_item_size as f64 / cap) * pr;
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.05 * open_bins_count as f64 * progress;

    // Smooth non-linear residual/mean-residual coupling
    score += 0.01 * (pr - mean_residual) * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 buckets capture typical item granularity.
    let post_mod = post_residual % 10;
    let post_div = post_residual / 10;

    // Reward tight fits: small post_residual is good, but dead space in low classes is worse.
    if post_residual == 0 {
        score -= 50.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    } else {
        // penalize dead space quadratically for unusable remainders
        let dead = post_residual as f64;
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 3.0; // tiny leftover is worst
        }
        score += (dead / bin_capacity as f64) * (dead / 20.0);
    }

    // Harmonic coupling: can next item exactly fill the leftover?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // chain fit
        } else if next_item_size < post_residual {
            let npost = post_residual - next_item_size;
            if npost <= 10 {
                score -= 12.0;
            }
            score -= (npost as f64).min(20.0) * 0.3;
        } else {
            // next item cannot use this residual: residual likely becomes dead space
            score += (post_mod as f64) * 0.8 + (post_div as f64) * 0.5;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing bins over spreading.
    if open_bins_count > 2 {
        score -= (open_bins_count.min(20) as f64) * 0.4;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 10.0;
        // attractive if current fits are poor (large mean residual fragmentation)
        if fitting_bins_count > 0 && mean_residual < item_size as f64 * 0.5 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    } else {
        // existing bin: slight preference over new bin baseline
        score -= 5.0;
    }

    // Mild stream-progress adaptation: early on, be greedy for tight fits; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 4.0;
    score += (1.0 - progress) * (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps that no future item
    // (sizes >= 1, but typically >= 10) can use are heavily penalized.
    let dead_threshold = 9.0;
    if post_residual > 0 && (post_residual as f64) <= dead_threshold {
        score += 25.0 * (dead_threshold - post_residual as f64 + 1.0);
    }

    // Reward exact / near-exact fits (post_residual == 0 is perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Prefer bins whose residual tightly matches the item (small waste ratio).
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste * waste;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another
    // one; prefer consolidating into existing bins.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open,
        // and when the current bin leaves a decent post_residual.
        score += 15.0 + 20.0 * pressure;
        // But if no existing bin fits well (large waste everywhere), allow
        // the new bin: compare against mean residual tightness.
        if (mean_residual - item_size as f64) < 0.0 {
            score -= 25.0;
        }
    } else {
        // Existing bin: slight reward when open-bin count is high.
        score -= 5.0 * pressure;
    }

    // Lookahead coupling: if the next item fits into post_residual exactly,
    // reward this placement strongly (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else if (post_residual as f64) < dead_threshold {
            // next item cannot use the leftover -> dead space penalty stands.
            score += 5.0;
        }
    }

    // Late in the stream, tighten up: prefer minimal residual even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

