}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // small leftover is fine if truly tiny
    } else if post_residual >= 10 && post_residual <= 30 {
        score += 8.0; // mid-size dead space is the worst zone
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 3.0; // next item can't use this bin's remainder
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are poor (large post_residual) or few bins are open.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 34.0
            - 2.0 * open_bins_count as f64
            + 0.15 * mean_residual
            - (post_residual as f64); // = capacity, so this term is constant-ish
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score -= 6.0 * (1.0 - progress);
        // If next item is large, a fresh bin is useful.
        if next_item_size > 60 {
            new_bin_score -= 8.0;
        }
        score = new_bin_score;
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += 0.4 * open_bins_count as f64 * (1.0 - tightness);

    // Time-horizon modulation: late in the stream, tighten more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
