    // early on, waste is cheaper; late, dead space is heavily penalized.
    let waste_penalty = (pr / cap).powi(3) * (0.5 + 2.0 * progress * progress);
    score += waste_penalty * cap;

    // Lookahead: reward residuals that can host the next item.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 3.0 * snug * (1.0 + progress);
