    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // Slight preference for keeping bin count low when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.05;

    // Mild alignment with mean residual: avoid outliers far below mean (fragmented bins).
    score += 0.3 * ((mean_residual - pr).abs() / cap);

    // New-bin candidate: baseline cost so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
