    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        if slack == 0.0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving residual that the next item cannot use (dead space).
        score += 6.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins whose residual is already below mean (consolidating space).
    let mean_gap = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent fits exist, more so later in stream.
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0 && post_residual <= mean_residual;
        let penalty = 10.0 + 20.0 * progress;
        score += if decent_fit_exists { penalty } else { 3.0 };
    } else {
        // Slight bonus for reusing existing bins, scaled by how many are open.
        score -= 2.0 * (open_bins_count.min(20) as f64).sqrt();
    }

    // Late-stream: discourage fragmenting residuals (small unusable leftovers).
    if post_residual > 0 && post_residual < 10 {
        score += 9.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead: reward if the next item fits into the resulting residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.5 * (post_residual - next_item_size) as f64;
    }
    // Penalize leaving a residual that is too small for typical future items (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: mildly penalize opening a new bin when
    // reasonable alternatives exist; encourage it when fits are poor.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 30.0 + 5.0 * fitting_bins_count as f64 };
        score += pressure;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Prefer bins whose residual is already below average (consolidate waste).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.3 * diff;
    }

    // Slight preference for bins in a moderately-sized open set (limit bin sprawl).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit = post_residual as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = (0.5 + 0.5 * progress) * (pr * pr) / cap;
    score += 0.35 * poly;

    // Reward tight fits more strongly as the stream advances
    let tightness = 1.0 - fit;
    score -= (1.0 + 2.0 * progress) * tightness * (item_size as f64);

    // Penalize waste relative to mean residual state
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: favor bins whose post-residual can still fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 6.0 + 4.0 * progress;
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for many open bins (encourage consolidation early)
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize slightly so it only wins on poor fits
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes modulo common item sizes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize residuals that no typical item (1..=100) can use well:
    // small nonzero residuals are dead space unless they are "harmonic" sizes
    if post_residual > 0 {
        let harmonic = (post_residual % 10 == 0) || (post_residual % 20 == 0) || (post_residual % 25 == 0) || (post_residual % 50 == 0);
        if harmonic {
            score -= 5.0; // likely reusable by future items
        } else {
            score += 8.0; // awkward dead space
        }
        // Very small residuals are nearly dead
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Lookahead coupling: if next item fits into post_residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
        // Harmonic bonus: next item leaves another harmonic residual
        let pr2 = post_residual - next_item_size;
        if pr2 % 10 == 0 || pr2 % 25 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        score += 4.0; // this bin won't help the next item
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral baseline; open a new bin only when current fit is bad
    if bin_residual == bin_capacity {
        score = 0.5 * cap - 0.5 * pr; // = 50 for empty bin
        if fitting_bins_count > 0 && (mean_residual - pr).abs() < 10.0 {
            score += 25.0; // decent fits exist, discourage new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    // Tightness reward: filling bin fraction
    score -= 10.0 * (1.0 - pr / cap);

    // Stream progression: later in stream, prefer consolidating into open bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Many open bins: discourage spreading; prefer bins below mean residual (tighter bins)
    if open_bins_count > 2 && bin_residual != bin_capacity {
        if (pr as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for any plausible item
    // (below the minimum item size) are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fill, reward strongly
    } else if post_residual < 10 {
        // unusable dead space in the classic regime: heavy penalty
        score += 40.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 30.0 / (1.0 + fit_ratio);

    // Penalize large leftover gaps that could have served a bigger item.
    if post_residual > 50 {
        score += 0.5 * (post_residual as f64 - 50.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += 0.15 * open_bins_count as f64;

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would leave this bin's post-residual as waste, mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.3 * post_residual as f64;
    }

    // New-bin candidate handling: an empty bin has perfect flexibility but
    // incurs capacity cost; only choose it when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are already open
        // and mean residual is fragmented.
        score = 55.0 + 0.5 * open_bins_count as f64 - 0.2 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        if fitting_bins_count == 1 {
            score += 20.0; // last chance exists elsewhere: keep using it
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item fits snugly into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(40.0);
    }
    // Penalize post-residual that cannot host the next item (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Compare post residual against the mean residual of open bins:
    // leaving less than average waste is good (tight packing).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let tightness = if next_item_size > 0 {
            ((bin_capacity as f64 - next_item_size as f64) / bin_capacity as f64).abs()
        } else {
            0.0
        };
        // Base penalty so new bins are opened only when open bins are bad.
        score += 30.0 + tightness * 10.0;
        // If nothing else fits, new bin is the natural choice.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Mild pressure to fill bins tightly as more bins are open.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item leaves little waste.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item,
    // penalize bins that would strand the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // chain fit: next item nearly fills post-residual
            let chain_waste = post_residual - next_item_size;
            if chain_waste < 10 {
                score -= 10.0;
            }
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 5 {
            score += 8.0; // near-miss: dead space likely
        } else {
            score += (post_residual as f64) * 0.05;
        }
    }

    // Dead-space penalty: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so when
    // decent fitting bins exist and many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 40.0;
        if fitting_bins_count > 0 {
            new_bin_penalty += 20.0 * (fitting_bins_count as f64).ln().max(1.0);
        }
        // later in the stream, consolidating is more valuable
        new_bin_penalty += 20.0 * progress;
        // if mean residual across open bins is large, avoid new bins
        if mean_residual > item_size as f64 {
            new_bin_penalty += 10.0;
        }
        // a fresh bin is attractive only if the item is huge and no bin fits well
        if item_size >= 70 && fitting_bins_count == 0 {
            new_bin_penalty -= 60.0;
        }
        score += new_bin_penalty;
    } else {
        // mild preference for fuller bins among equals
        score += (bin_capacity - bin_residual) as f64 * -0.01;
        // spread items when many bins are open and mean residual is high
        if (bin_residual as f64) > mean_residual {
            score += 3.0;
        } else {
            score -= 3.0;
        }
    }

    // Small exploration jitter-free coupling with stream position
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits (penalize large residuals quadratically).
    // Late: residual less costly as stream ends, smooth decay.
    let phase = (progress * std::f64::consts::PI).sin();
    let w = 0.5 * (1.0 - phase); // 1 early, 0 late, smooth
    score += w * (pr * pr) / cap;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0 * (1.0 - pr / 5.0);
    }

    // Penalize dead space too small for likely future items (10..100 range).
    let min_future = 1.0f64;
    if pr > 0.0 && pr < min_future.max(10.0) {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            score -= 8.0 * (1.0 - (pr - n) / cap);
        } else {
            // Waste that cannot host the next item: mild penalty scaled by waste.
            score += 3.0 * (pr / cap);
        }
    }

    // Prefer denser bins relative to mean residual (best-fit flavor, smooth).
    score -= 2.0 * ((mean_residual - pr) / cap).tanh();

    // New-bin candidate: make it attractive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64).ln().max(0.0);
        score = 10.0 + crowding + 0.5 * mean_residual / cap;
        if fitting_bins_count == 1 {
            score += 30.0; // discourage abandoning the only fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward "perfect" leftovers (0, small), penalize mid-range waste
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 10 {
        score -= 40.0;
    } else if pr <= 20 {
        score -= 15.0;
    } else if pr <= 35 {
        score += 8.0; // awkward dead zone
    } else if pr <= 55 {
        score += 3.0;
    }

    // Integer-division class: residual divisible into big chunks is reusable
    let chunk = pr / 20; // class 0..5
    score -= chunk as f64 * 6.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size <= pr {
            score -= 10.0 + (pr - next_item_size) as f64 * 0.5;
        } else {
            score += 6.0; // next item cannot use this leftover
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are terrible
    if bin_residual == bin_capacity {
        score += 20.0 + 0.3 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin useful for large next item
        }
    }

    // Prefer tighter fits relative to current residual
    score += 0.2 * (bin_residual - item_size) as f64;
    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Moderately awkward gaps (hard to fill with typical small items).
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Open-bin pressure: discourage spreading across many bins when
    // mean residual is already large enough to absorb future items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 3 {
        score += (open_bins_count as f64 - 3.0) * (2.0 + 4.0 * progress);
    }

    // Prefer reusing bins with large residual relative to mean (they'd otherwise waste).
    if bin_residual as f64 > mean_residual * 1.5 {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize leaving a residual that neither fits the next item
    // nor is zero (creates stranded space), but reward leaving exactly what
    // the next item can consume.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // New-bin candidate: opening a fresh bin is attractive early on or when
    // the item would leave a large awkward gap in an existing bin; otherwise
    // it is penalized to prefer reuse.
    if bin_residual == bin_capacity {
        let gap_penalty = if post_residual > 20 { 0.0 } else { 30.0 };
        score = score - 15.0 + 20.0 * progress + gap_penalty + open_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins where the next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect match for the next item is highly desirable
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
            // Extra penalty proportional to leftover after the next item
            score += 0.5 * slack;
        } else {
            // Next item cannot follow in this bin: mild penalty scaled by wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    } else {
        // Last item: any placement is fine, slight preference for tightness already in base
        score -= 5.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual near the mean keeps the fleet of open bins homogeneous and reusable
    let diff = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): only attractive when the fit is poor everywhere.
    // Opening a bin is penalized, but less if the item is large and leaves a useful residual.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = waste + 20.0;
        // If next item could chain into the fresh bin, slightly soften
        if next_item_size > 0 && waste >= next_item_size as f64 {
            score -= 10.0;
        }
        // Late in the stream, opening new bins is cheaper (fewer future items to place)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Many open bins: discourage scattering; prefer consolidating into existing bins
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly reward tight fits (small post_residual)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize leaving dead space that no plausible item (min size 1, typical >= 10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_waste = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - next_waste / bin_capacity as f64);
        } else {
            // next item can't follow here; mild penalty, stronger early when lookahead matters more
            score += 8.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Many open bins: prefer consolidating into bins with above-average fill
    if open_bins_count > 1 {
        let fill_bias = (mean_residual - post_residual as f64) / bin_capacity as f64;
        score -= 10.0 * fill_bias;
        // Encourage closing out small residuals to reduce open bin count
        if (post_residual as f64) < mean_residual * 0.3 {
            score -= 12.0;
        }
    }

    // New-bin candidate handling: opening a bin is only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Early in stream or when many bins already open and fit is poor, allow new bins
        let poor_fit = post_residual as f64 > bin_capacity as f64 * 0.4;
        if poor_fit && (progress < 0.7 || open_bins_count > 8) {
            score -= 5.0;
        } else {
            score += 30.0;
        }
        // Never prefer a fresh bin when an existing bin gives an excellent fit
        if post_residual as f64 <= 0.05 * bin_capacity as f64 {
            score += 200.0;
        }
    }

    // Mild time-horizon modulation: late in stream, be greedier about tight fits
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling: reward tight fits more strongly as stream progresses.
    let tightness = 1.0 - pr / cap;
    score -= tightness * tightness * (30.0 + 40.0 * progress);

    // Penalize residual far from reusable small-item sizes (smooth dead-space proxy).
    let dead = pr / cap;
    score += dead * dead * dead * 25.0;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 + 20.0 * progress;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            let gap = (nxt - pr) / cap;
            score += 15.0 * gap * gap;
        }
    }

    // Mild penalty for spreading across many open bins relative to mean residual.
    score += (open_bins_count as f64).ln().max(0.0) * (mean_residual - pr).abs() * 0.05;

    // New-bin candidate: discourage opening unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - progress) * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is ideal.
    score -= 40.0 * (-post_residual as f64 / 8.0).exp();

    // Harmonic class of post_residual modulo 10: small residues in {0,1,2} are
    // "dead space" classes (hard to fill with items >=10), penalize them hard.
    let pr_class = post_residual % 10;
    if post_residual > 0 && pr_class <= 2 {
        score += 18.0 + 4.0 * pr_class as f64;
    }
    // Residues in the "harmonic sweet spot" (divisible by 10) are reusable.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 12.0;
    }

    // Fractional fill: reward bins that become more than 80% full.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    if fill >= 0.8 {
        score -= 15.0 * (fill - 0.8) / 0.2;
    }

    // Lookahead coupling: if next item fits the post residual exactly-ish, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 20.0 * (-slack as f64 / 6.0).exp();
            // harmonic class of the leftover after the lookahead item
            let l2 = post_residual - next_item_size;
            if l2 % 10 == 0 && l2 > 0 {
                score -= 8.0;
            } else if l2 > 0 && l2 < 10 {
                score += 10.0;
            }
        } else {
            // next item cannot use this bin's remainder; mild penalty scaled by waste
            score += 5.0 + (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin gives a
    // good fit (post_residual large) or when many bins are open and mean
    // residual is small (open bins nearly full).
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count > 0 { mean_residual / cap } else { 1.0 };
        // Default: new bin is a mediocre choice.
        score = 55.0;
        // If existing fits are all poor (post_residual would be tiny/dead),
        // opening fresh is attractive. Approximate via mean_residual low.
        if pressure < 0.15 {
            score -= 25.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // Harmonic class of item: items that split capacity nicely (size % 10 == 0)
        // pair well with a fresh bin.
        if item_size % 10 == 0 {
            score -= 10.0;
        }
    }

    // Mild pressure to use bins with larger residuals when many bins are open.
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are useless, punish them superlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward placing into tight bins (residual close to item size).
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 25.0 * tightness;

    // Reward bins whose residual is close to item (efficient use).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score -= 20.0 / (1.0 + gap);

    // Open-bin pressure: discourage spreading when many bins are open,
    // but encourage using existing bins when few are open.
    if bin_residual != bin_capacity {
        score -= 8.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        score += 12.0 + 2.0 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would fit better in a fresh bin, penalize leaving awkward residue.
    if next_item_size > post_residual as u32 && next_item_size > 0 && post_residual > 0 {
        score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Early stream: prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins with below-mean residual (tighter bins get filled first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual dominates).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // 2-step lookahead: reward residuals that can host the next item exactly/well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score += 0.25 * gap;
        } else {
            // next item can't fit here; slight penalty proportional to shortfall
            let short = (next_item_size - post_residual) as f64;
            score += 0.1 * short;
        }
    } else {
        // Last item: strongly prefer minimal waste.
        score -= 20.0;
    }

    // Compare against mean residual: penalize bins that are already tight
    // (would create dead space relative to fleet average).
    let res = post_residual as f64;
    if res < mean_residual * 0.5 {
        score += 4.0 * (mean_residual - res) / bin_capacity as f64;
    } else if res > mean_residual * 1.5 {
        score -= 2.0 * (res - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only fitting bin, avoid wasting it on a bad fit.
    if fitting_bins_count == 1 {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if waste_ratio > 0.3 {
            score += 15.0 * waste_ratio;
        } else {
            score -= 10.0;
        }
    }

    // New-bin candidate: default mild penalty; allow opening a new bin only when
    // all open bins would leave large dead space.
    if bin_residual == bin_capacity {
        let best_possible = if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            0.0 // chainable pair, new bin is attractive
        } else {
            8.0
        };
        score = 25.0 + best_possible - (fitting_bins_count as f64) * 3.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large wasted residual, superlinearly (dead space is the enemy).
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(3) * (bin_capacity as f64);

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 12.0 / (1.0 + tightness);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, unless it enables a
    // perfect pairing with the lookahead item (or stream is young).
    if bin_residual == bin_capacity {
        score += 8.0;
        if next_item_size > 0 {
            // Perfect pair: item + next fills a fresh bin exactly.
            if item_size + next_item_size == bin_capacity {
                score -= 60.0;
            } else if item_size + next_item_size <= bin_capacity {
                score -= 10.0 / (1.0 + (bin_capacity - item_size - next_item_size) as f64);
            }
        }
        // Late in the stream, opening new bins is cheap; early, avoid sprawl.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
        // Many open bins with high mean residual: consolidation is better.
        if open_bins_count > 2 && mean_residual > item_size as f64 * 2.0 {
            score += 6.0;
        }
    }

    // Lookahead coupling: leaving residual exactly matching next_item_size is ideal.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 4.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
    }

    // Mild pressure to fill fuller bins when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * (bin_residual - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += norm_pr * norm_pr * cap * (0.5 + 0.5 * progress) * 0.25;
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 8.0 * (1.0 + p3);

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * tightness * (6.0 + 10.0 * p2);

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 5.0 * (1.0 - n / cap) * (1.0 - 0.5 * progress);
        } else {
            score += 3.0 * (n - pr) / cap * 10.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 * (1.0 + progress);
    }

    // Penalize proliferation of open bins with large mean residual
    score += (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap) * 2.0 * (1.0 - progress);

    // New-bin candidate: make it unattractive unless nothing fits well
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space severity via integer division thresholds.
    let dead_class = post_residual / 10; // classes 0..=10
    score += match dead_class {
        0 => -30.0,                       // near-perfect fit
        1 => -15.0,
        2 => -5.0,
        3 | 4 => 0.0,
        5 | 6 => 8.0,                     // half-bin waste zone
        7 | 8 => 15.0,
        _ => 22.0,                        // mostly empty bin used poorly
    };

    // Modulo coupling: residuals that align with common item granularity (multiples of 10)
    // are more likely reusable by future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
            // harmonic class of leftover after hypothetical next placement
            let r2 = post_residual - next_item_size;
            score += (r2 / 10) as f64 * 1.5;
        } else {
            // post_residual cannot host next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // or open bins are already crowded with big residuals.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 25.0 - 30.0 * large_item - 20.0 * crowding;
        if post_residual % 10 == 0 {
            score -= 4.0; // fresh bin leaves a clean multiple-of-10 residual
        }
    } else {
        // Prefer filling bins that are already relatively full (small residual fraction).
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fill_ratio;
    }

    // Mild preference to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Slight drift: later in the stream, tighten packing (waste less).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are heavily penalized,
    // but a perfect fit (post_residual == 0) is strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    } else {
        // Mild preference for smaller (but usable) residuals
        score += (post_residual as f64).sqrt() * 2.0;
    }

    // Reward using bins that are already mostly full (small bin_residual => good consolidation)
    score += (bin_capacity - bin_residual) as f64 * 0.5;

    // Pressure from number of open bins: prefer existing bins when many are open,
    // making new-bin opening less attractive as open_bins_count grows.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin wastes bin_capacity - item_size
    // of space; only attractive if no existing bin fits well. Penalize the new bin
    // unless the current item would leave a large useful gap elsewhere.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, softened when many bins are open
        // (consolidation matters more) and when mean residual is high.
        let open_pressure = open_bins_count as f64 * 3.0;
        let mean_res_bonus = mean_residual * 0.3;
        score += 60.0 + open_pressure - mean_res_bonus;
        // If the next item could combine with this one in the fresh bin, soften penalty
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0;
        }
    }

    // Lookahead coupling: if post_residual exactly matches the next item size,
    // this placement sets up a perfect follow-up fit.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    }
    // Penalize leaving a gap slightly smaller than the next item (dead space for it)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Early in the stream, be slightly more willing to open bins (build diversity);
    // late in the stream, consolidate aggressively.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score -= progress * 10.0;
        } else {
            score += progress * 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual (already in score).

    // 2-step lookahead: strongly reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if post_residual >= next_item_size {
            // Perfect match: next item exactly fills this bin.
            score -= 40.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize residual smaller than next item (dead space).
            score += 0.35 * gap as f64;
        }
    }

    // Reward leaving residuals that are generally reusable relative to mean residual.
    let mean_r = mean_residual.max(1.0);
    if (post_residual as f64 - mean_r).abs() < mean_r * 0.25 {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Among multiple candidates, prefer tighter fit slightly more.
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score += 18.0 - 8.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild penalty for wasting a large bin on a small item early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let waste = post_residual as f64 / bin_capacity as f64;
    score += waste * (2.0 + 3.0 * (1.0 - progress));

    // Slight preference to keep number of open bins bounded.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.09;
    score
