pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // residual waste is penalized more heavily as the stream advances.
    let progress_weight = 1.0 + 2.0 * progress * progress;
    score += progress_weight * pr_norm * pr_norm * cap * 0.5;

    // Reward tight fits via smooth saturating polynomial of fill ratio.
    let fill = 1.0 - pr_norm;
    score -= 20.0 * fill * fill * fill;

    // Coupling with mean residual: prefer bins whose post-residual deviates
    // favorably from the mean residual across open bins.
    let dev = pr - mean_residual;
    score += 0.3 * dev * (1.0 + progress);

    // Lookahead: reward leaving space that fits the next item (smooth kernel).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let diff = pr - n;
        let kernel = (-diff * diff / 200.0).exp();
        score -= 8.0 * kernel;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty on opening many bins late in the stream.
    score += (open_bins_count as f64).ln().max(0.0) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into a
    // "friendly" residue class (divisible by common item sizes) are rewarded.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Reward residuals that are multiples of small harmonics (waste reusability)
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 5.0; }
        // Penalize awkward residues near harmonic boundaries
        let r = pr % 10;
        if r >= 1 && r <= 4 { score += 2.0 * (5 - r) as f64; }
    } else {
        // Perfect fill: best possible outcome
        score -= 40.0;
    }

    // Fraction-of-capacity classes
    let frac = pr as f64 / cap;
    if frac > 0.0 && frac < 0.10 { score += 8.0; }        // dead space
    else if frac < 0.30 { score -= 2.0; }                  // compact fit good

    // Lookahead coupling: does the leftover fit the next item?
    if next_item_size > 0 && pr >= next_item_size {
        // Harmonic match between leftover class and next item class
        if pr % next_item_size.max(1) == 0 { score -= 8.0; }
        else { score -= 3.0; }
    } else if next_item_size > 0 {
        // leftover unusable for next item -> penalize proportionally
        score += (next_item_size - pr) as f64 * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Tightness reward: item fills most of the bin
    let tight = item_size as f64 / bin_residual.max(1) as f64;
    score -= tight * 6.0;

    // Late in stream: prefer closing bins tightly rather than spreading
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0 * (post_residual as f64 / cap);

    // Prefer bins below mean residual (keeps residuals balanced)
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    // New empty bin candidate: only attractive when current bin would be a bad fit
    if bin_residual == bin_capacity {
        score += 12.0;
        if fitting_bins_count == 0 { score -= 20.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 25.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving a gap that the next item can exactly use.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Penalize leaving a gap the next item cannot fit into.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Open-bin pressure: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it attractive only when existing residuals are large.
    if bin_residual == bin_capacity {
        let mean_post = mean_residual - item_size as f64;
        if mean_post >= 0.0 && mean_post < dead_threshold as f64 {
            // Existing bins would all leave dead space; open a new bin.
            score -= 80.0;
        } else {
            score += 40.0 + mean_residual * 0.2;
        }
    }

    // Slight preference for tighter fits relative to residual.
    score += (item_size as f64 / bin_residual.max(1) as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: post_residual exactly matches the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Penalize residuals that cannot host the next item (dead space), scaled by how "wasted" they are.
    if next_item_size > 0 && post_residual < next_item_size {
        let waste_ratio = post_residual as f64 / next_item_size as f64;
        score += 30.0 * (1.0 - waste_ratio);
    }

    // Penalize post_residual that is too small to ever be useful (below min item size 1..100 range: use 10 as floor).
    if post_residual < 10 {
        score += 20.0;
    }

    // Compare against mean residual: avoid creating much-smaller-than-average residuals.
    let diff = mean_residual - post_residual as f64;
    if diff > 0.0 {
        score += 0.3 * diff;
    } else {
        score += 0.1 * diff; // slight reward for keeping residual above average
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when other bins can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 80.0;
        } else {
            score -= 5.0;
        }
        // New bins are more acceptable early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * (1.0 - progress);
    }

    // Mild pressure on bin count: prefer filling existing bins when many are open.
    score += 0.5 * open_bins_count as f64;

    // Reward tight fits overall.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill_frac * fill_frac;

    // Penalize small dead space (< ~10) that likely becomes unusable,
    // but only mildly when the fit was otherwise tight.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 - 0.5 * post_residual as f64;
    }

    // Lookahead: reward if the next item can fit into post_residual (chaining),
    // penalize if the leftover is nonzero but too small for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_quality = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * chain_quality;
        } else if post_residual > 0 {
            score += 5.0;
        }
    } else {
        // Last item: waste minimization dominates.
        score += 0.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // When many bins are open and mean residual is high, be pickier about
    // wasting space; when few bins are open, opening new bins is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * mean_residual * (1.0 - progress) * (open_bins_count as f64).ln().max(1.0) * 0.1;

    // New-bin candidate (empty bin): make it attractive only when the item is
    // large relative to typical open-bin residuals or fits are poor.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Empty bin starts with score = capacity; adjust to compete.
        score -= 20.0 * item_frac;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 6.0; // good chance of a perfect pair in a fresh bin
        }
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;

    // Base: prefer small post_residual, with non-linear penalty for tiny dead space
    let mut score = post;
    score += 40.0 * (post / cap).powi(3);

    // Smooth quadratic coupling of post_residual with stream progress:
    // early on, tolerate slack; late, tighten packing
    score += (1.0 - progress) * 20.0 * (post / cap);
    score -= progress * 15.0 * (1.0 - (post / cap)).powi(2);

    // Reward tight fits (post_residual small relative to residual)
    let fit_ratio = if res > 0.0 { post / res } else { 1.0 };
    score -= 12.0 * (1.0 - fit_ratio).powi(2);

    // Lookahead: if next item fits exactly in post_residual, strongly favor
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            score -= 18.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit: penalize leaving large unusable gap
            score += 8.0 * (post / cap);
        }
    }

    // Last-chance bin: reward strongly to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Mean-residual coupling: prefer bins whose residual deviates below mean
    // (consolidate fullness) with smooth interaction with progress
    let dev = (res - mean_residual) / cap;
    score += 10.0 * dev * (0.5 + progress);

    // New-bin candidate: penalize unless it genuinely beats poor fits
    if bin_residual == bin_capacity {
        score += 30.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: bins whose leftover is a "usable" residue class
    // are favored. Classify leftover by capacity fraction.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left

    // Dead-space penalty: leftover that cannot hold the next item (or a min item)
    let min_item = 1u32;
    if post_residual > 0 && post_residual < next_item_size.max(min_item) && next_item_size > 0 {
        score += 25.0; // unusable for lookahead
    }

    // Reward leftover that exactly fits next item (harmonic pairing)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Reward leftover that can hold next item with room to spare
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * (post_residual - next_item_size) as f64;
    }

    // Modulo arithmetic on post_residual: leftovers divisible by common size classes
    // (e.g. multiples of 10, 20, 25, 50) are more "reusable" in typical streams.
    let pr = post_residual;
    if pr % 50 == 0 && pr > 0 { score -= 12.0; }
    else if pr % 25 == 0 && pr > 0 { score -= 8.0; }
    else if pr % 20 == 0 && pr > 0 { score -= 6.0; }
    else if pr % 10 == 0 && pr > 0 { score -= 4.0; }

    // Integer-division thresholds: penalize leaving slivers (1..=9) heavily
    if pr >= 1 && pr < 10 {
        score += 40.0;
    }

    // Tightness reward: fraction of bin consumed by this item
    let tightness = item_size as f64 / cap;
    score -= 20.0 * tightness;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 70.0;
        // but if no open bin fits well (post_residual would be a sliver),
        // opening new bin becomes attractive
        if post_residual < 10 && bin_residual == bin_capacity {
            score -= 0.0; // empty bin has post_residual == capacity anyway
        }
        // encourage new bin when many open bins exist with low mean residual
        score += 0.3 * open_bins_count as f64;
        score -= 10.0 * (mean_residual / cap);
    } else {
        // existing bins: slight preference when mean residual is high (bins are roomy)
        score -= 0.1 * (mean_residual / cap);
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 60.0 }
                   else if post_residual < 20 { 25.0 }
                   else if post_residual < 40 { 8.0 }
                   else { 0.0 };
        score += dead;
    } else {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Prefer bins whose residual tightly matches the item (good fit ratio).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fit_ratio;

    // Open-bin pressure: with many open bins, discourage spreading; but if
    // this is the last fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }
    score += 0.35 * open_bins_count as f64;

    // New-bin candidate: only attractive when item is large relative to
    // remaining capacity elsewhere or many bins are open.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        if item_size >= 70 {
            score -= 55.0;
        }
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would be blocked by the leftover gap, penalize small gaps more.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Penalize leaving space that only slightly exceeds the next item (wasteful).
            let gap = (post_residual - next_item_size) as f64;
            score += 0.6 * gap;
        } else {
            // Next item can't fit here; mild reward for smaller leftover.
            let gap = (next_item_size - post_residual) as f64;
            score -= 0.15 * gap.min(30.0);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize bins whose residual is far below the mean (fragmented bins).
    score += 0.4 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate: prefer it only when it yields a tight future fit;
    // make opening a new bin moderately costly so existing bins are preferred.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 300.0;
        }
    }

    // Slight preference for tighter fits overall (non-linear).
    let pr = post_residual as f64;
    score += 0.05 * (pr * pr) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // dead space penalty grows super-linearly for small leftovers
        let pr = post_residual as f64;
        score += (bin_capacity as f64 / pr).max(1.0) * 2.0;
        // leftover that can't fit a typical next item is worse
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0 + (next_item_size - post_residual) as f64 * 0.5;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // this bin can also host the next item: strong reward
            score -= 25.0 + (next_item_size as f64) * 0.3;
        }
    }

    // Exact-ish fit relative to residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * 40.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize spreading when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual is below mean residual (denser bins)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New empty bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 120.0 * desperation + open_bins_count as f64 * 2.0;
        // Opening early in stream is cheaper than late
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
        // If next item is large, a fresh bin is more valuable
        if next_item_size > item_size && next_item_size > 50 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: quadratic waste coupling, weighted more as stream progresses
    let mut score = pr * (1.0 + 1.5 * progress) + 0.004 * pr * pr;

    // Reward tight fits (small post_residual) non-linearly
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize large dead space relative to smallest plausible item
    if pr > 0.0 && pr < 10.0 {
        score -= 6.0; // nearly perfect fill
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening bins, more so early and when
    // existing bins have plenty of room
    if is_new_bin {
        let mut nb = 8.0 + 10.0 * (1.0 - progress);
        nb += (mean_residual / cap) * 6.0;
        // if next item is large, a fresh bin is more attractive
        nb -= (next_item_size as f64 / cap) * 5.0;
        // few fitting bins means we may need this bin anyway
        if fitting_bins_count <= 1 {
            nb -= 10.0;
        }
        score += nb;
    }

    // Lookahead: penalize leaving a residual that neither fits next item well
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            // good: next item can go here
            let slack = pr - nx;
            score -= 4.0 * (1.0 - slack / cap);
        } else {
            // residual too small for next item: waste
            score += 0.05 * (nx - pr);
        }
    }

    // Mild penalty for bin proliferation
    score += 0.15 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modular structure over capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward near-perfect fits (post_residual in low harmonic classes).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= eighth {
        score -= 25.0;
    } else if post_residual <= quarter {
        score -= 8.0;
    } else if post_residual > quarter && post_residual < 2 * quarter {
        score += 6.0;
    }

    // Dead-space penalty: residuals that can never host small items (>=10) are useless.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Modulo-class logic: residuals congruent to small multiples of 8 keep future
    // 8/16/24/32-sized items fittable; reward those classes, penalize awkward ones.
    let m = post_residual % 16;
    if m == 0 {
        score -= 5.0;
    } else if m >= 10 {
        score -= 2.0;
    } else {
        score += 4.0;
    }

    // Lookahead: if the next item fits the post-residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            let gap = post_residual - next_item_size;
            if gap <= eighth as u32 {
                score -= 8.0; // chain of near-perfect fits
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the final fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when all open bins are nearly full
    // (mean residual low) or fit would create big dead space.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        if mean_r < 20.0 {
            score -= 15.0;
        } else {
            score += 20.0 + mean_r * 0.2;
        }
        // Early stream: keep bins open, avoid bin proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    }

    // Slight preference for fuller bins (tie-breaking toward tight packing).
    score += (1.0 - bin_residual as f64 / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to ever be useful
    // (below the minimum plausible item size) are heavily punished.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0; // exact fit -> ideal, but keep baseline
    }
    // Non-linear dead-space curve: gaps in [1, 10) are near-wasted space.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * (10.0 - pr) * 2.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Lookahead: strongly reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.1 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover can't host next item: mild penalty proportional to waste
        score += 0.15 * pr;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // into new/loose bins; with few open bins, consolidation is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline high enough that only good reasons
        // (poor fits elsewhere) justify opening it.
        score += 25.0 + pressure;
        // Opening a new bin is more attractive early on / for large items.
        score -= 0.2 * item_size as f64;
    } else {
        // Slightly favor bins with below-average residual (fill emptier bins).
        if pr > mean_residual {
            score += 0.1 * (pr - mean_residual);
        } else {
            score -= 0.1 * (mean_residual - pr);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match of post_residual with next item is highly desirable
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward exact/near match with next item size
        score -= 60.0 * (-diff / 20.0).exp();
        // Penalize dead space: post_residual too small for next item AND below typical small-item threshold
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    } else {
        // Last item: strongly prefer tightest fit
        score *= 2.0;
    }

    // Relative to mean residual: bins with residual near mean are "normal"; prefer
    // filling bins whose residual is above mean (consolidate slack)
    if post_residual as f64 > mean_residual {
        score -= 8.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;
    } else {
        score += 6.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 20.0 + 30.0 * poor_fit - 15.0 * (fitting_bins_count == 0) as i32 as f64;
        // Late in stream, prefer closing out existing bins
        score += 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Slight preference for more filled bins when many bins are open
    score += 0.5 * open_bins_count as f64 / (total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item can still fit: mildly good, but scaled by how much slack remains.
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: penalize leaving large awkward residuals.
            let waste = post_residual as f64 - (next_item_size as f64).min(post_residual as f64);
            score += 5.0 * (waste / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 20.0;
        // Penalize more when many bins are already open (encourage consolidation).
        score += 2.0 * (open_bins_count as f64).sqrt();
        // But if no existing bin fits well (large post_residual elsewhere), opening
        // a fresh bin becomes attractive: discount the penalty.
        let poor_fit_elsewhere = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        if poor_fit_elsewhere > 0.0 {
            score -= 45.0;
        }
        // If current item is large relative to mean residual, fresh bin is reasonable.
        if (item_size as f64) > mean_residual {
            score -= 10.0;
        }
    }

    // Global state: when many bins are open with high mean residual, favor filling
    // bins with large residuals (cleanup phase).
    if open_bins_count > 3 {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.3 * diff;
    }

    // Time horizon: late in the stream, be more conservative about opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Mild penalty for leaving residual in the awkward 1..10 dead zone.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let next = next_item_size as f64;
    let tightness = 1.0 - (item_size as f64 / cap);
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);
    score -= 6.0 * norm_pr * (1.0 - progress);
    if next > 0.0 {
        let next_norm = next / cap;
        let match_bonus = 1.0 - (pr - next).abs() / cap;
        score -= 5.0 * match_bonus * match_bonus * (1.0 - progress);
        score += 3.0 * next_norm * tightness * progress;
    }
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress);
    }
    score += 2.0 * (mean_residual - pr) / cap;
    score += 0.5 * (open_bins_count as f64).sqrt() * norm_pr * progress;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but exact fits are gold.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Harmonic class of the leftover: leftover divisible by small integers
        // is more likely to be filled by future items.
        let pr = post_residual;
        let mut harmonic_bonus = 0.0;
        if pr % 10 == 0 { harmonic_bonus += 6.0; }
        if pr % 5 == 0 { harmonic_bonus += 3.0; }
        if pr % 2 == 0 { harmonic_bonus += 1.5; }
        // Leftover in "hard-to-fill" band (1..10) is dead space -> penalize extra.
        if pr < 10 {
            harmonic_bonus -= 12.0;
        }
        score -= harmonic_bonus;

        // If the next item exactly matches the leftover, strongly favor this bin.
        if next_item_size > 0 && next_item_size == pr {
            score -= 50.0;
        }
        // If the next item fits the leftover, mild bonus.
        else if next_item_size > 0 && next_item_size <= pr {
            score -= 8.0;
        }
        // If next item cannot use the leftover, penalize proportionally.
        else if next_item_size > pr {
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual < 10 {
            score += 8.0; // still penalize creating tiny dead space
        }
    }

    // Penalize opening a new bin when plenty of open bins exist with room,
    // but allow it early in the stream or when few bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base score high; relax when few bins open or stream is young.
        score += 25.0 + 20.0 * (1.0 - progress) - 5.0 * (open_bins_count.min(10) as f64);
        // If next item is large, a fresh bin is attractive.
        if next_item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    // Slight preference for bins whose residual deviates favorably from mean
    // (placing into below-mean-residual bins consolidates space).
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Mild penalty for wasting a large residual on a small item.
    if item_size < bin_residual / 3 && bin_residual != bin_capacity {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harsh penalty for small unusable dead space (post_residual < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Reward perfect fits
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space penalty scaled by how small the gap is relative to typical item sizes
    let dead = post_residual as f64 / bin_capacity as f64;
    if dead > 0.0 && dead < 0.10 {
        score += (0.10 - dead) * 300.0;
    }

    // Open bins pressure: penalize placements that keep many bins open
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward leaving a gap that can fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates from mean toward tighter fits
    score += (mean_residual - bin_residual as f64).abs() * 0.3;

    // Prefer filling bins that are already relatively full
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    // New-bin candidate penalty: discourage opening new bins early / when many bins open
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 2.0;
    }

    // Mild stream progression: later in stream, tolerate more open bins slightly less
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly
    // matches the next item's size (perfect chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Slack left after hypothetically serving the next item too.
            let two_step_slack = (post_residual - next_item_size) as f64;
            score -= 20.0 / (1.0 + two_step_slack / 10.0);
        } else {
            // Next item cannot follow; the leftover is likely dead space.
            let dead = next_item_size - post_residual;
            score += (dead as f64).sqrt() * 4.0;
        }
    } else {
        // Last item of the stream: just minimize leftover.
        score -= 15.0;
    }

    // Compare against the fleet's mean residual: placing into a bin that is
    // already tighter than average concentrates waste in few bins.
    let tightness = mean_residual - post_residual as f64;
    score += 0.6 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin candidates mildly so we only open new bins when no
    // open bin yields a decent fit.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Opening a new bin is more attractive late in the stream when many
        // bins are open and mean residual is large (fragmentation).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress * (mean_residual / bin_capacity as f64);
    }

    // Slight bonus for large items consuming big chunks (good packing).
    score -= (item_size as f64) * 0.15;

    // Tie-break: prefer bins with more residual overall when nearly equal,
    // to keep tight bins free for small items.
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize leaving residual space that is likely unusable:
    // dead space is worst when post_residual is small but nonzero.
    if post_residual > 0 {
        let small_gap_penalty = if post_residual < 10 {
            12.0
        } else {
            let pr = post_residual as f64;
            6.0 * (1.0 - (pr / bin_capacity as f64)).exp()
        };
        score += small_gap_penalty;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: slight penalty for wasting space
            score += 3.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (mean_residual - post_residual as f64).abs();
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * consolidation * 0.1;

    // Early in stream: be more willing to open/keep diverse bins (mild new-bin bonus),
    // late in stream: strongly prefer filling existing bins.
    if bin_residual == bin_capacity {
        let new_bin_bonus = 15.0 * (1.0 - progress) - 10.0 * progress;
        score += new_bin_bonus.max(-5.0);
    } else {
        // Favor bins whose residual is close to item size (best-fit flavor)
        let fit_gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += 10.0 * fit_gap * (0.5 + progress);
    }

    // Prefer bins with residual below the mean (denser bins) slightly.
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer small post-residual, with smooth polynomial coupling to progress.
    let mut score = pr * (1.0 + 0.35 * progress * pr / cap);

    // Reward tight fits: normalized fill fraction, amplified non-linearly by progress.
    let fill = it / cap;
    score -= 18.0 * fill * fill * (0.5 + progress);

    // Penalize tiny dead space that is hard to reuse, smoothly via quadratic term.
    if pr < it {
        let waste = (it - pr) / cap;
        score += 10.0 * waste * waste;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            score -= 8.0 * (1.0 - (pr - n) / cap) * (0.4 + 0.6 * progress);
        } else {
            score += 4.0 * (n - pr) / cap;
        }
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Contextual coupling with mean residual: penalize placing into a bin far from the mean
    // when post-residual is large (creates fragmented space).
    score += 0.5 * ((pr - mean_residual) / cap) * ((pr - mean_residual) / cap) * (1.0 - progress);

    // New-bin candidate handling: make empty bins mildly unattractive unless residuals
    // across open bins are all poor (high mean residual / few fitting bins).
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.5 * progress)
            - 6.0 * (fitting_bins_count == 0 as bool) as i32 as f64
            + 0.3 * mean_residual * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fraction.
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Penalize residuals that fall into "unusable" harmonic bands.
    // Classes: (0,10] excellent, (10,25] good, (25,50] mediocre, (50,100] bad.
    let class_penalty = if post_residual == 0 {
        -40.0 // perfect fit
    } else if post_residual <= 10 {
        -30.0
    } else if post_residual <= 25 {
        -10.0
    } else if post_residual <= 50 {
        5.0
    } else {
        25.0
    };
    score += class_penalty;

    // Modulo arithmetic: residual congruence classes mod 10 — small remainders
    // are more likely to be filled by future small items.
    let r_mod = post_residual % 10;
    score -= (10 - r_mod) as f64 * 0.6;

    // Integer-division thresholds: how many 10-sized chunks still fit.
    let chunks = post_residual / 10;
    score -= chunks as f64 * 0.8;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.35;
            // harmonic match: same decade class
            if (next_item_size / 10) == (post_residual / 10) {
                score -= 8.0;
            }
        } else {
            // next item won't fit here regardless; slight penalty for wasted space
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: baseline score so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.3 * open_bins_count as f64
            - 10.0 * (step_index as f64 / total_items.max(1) as f64);
        // If nothing else fits well (large post residuals elsewhere), new bin wins.
    }

    // Prefer tighter bins: reward closeness of item to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // Mild preference to keep mean residual balanced across open bins.
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    // Prefer filling bins when many are open (bin consolidation).
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - post_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the closer post_residual is to 0, the better.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual gap is "dead" if it is smaller than the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0; // mildly risky gap: only small items can use it
    } else if post_residual == 0 {
        score -= 25.0; // perfect closure is excellent
    }

    // If the leftover gap can exactly host the lookahead item, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0; // gap too small for the next item: less useful
    }

    // Open-bin pressure: discourage spreading into many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin (which would waste its full residual).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when nothing fits well elsewhere.
        // Base cost of a fresh bin is high; relax it when bins are few or
        // the current bin would leave a bad gap.
        let bad_gap = post_residual > 0 && post_residual < 20;
        let mut new_bin_cost = 45.0;
        if open_bins_count == 0 {
            new_bin_cost = 0.0;
        }
        if bad_gap {
            new_bin_cost -= 30.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size {
            new_bin_cost -= 5.0;
        }
        score += new_bin_cost;
    }

    // Mild stream-progression term: late in the stream, prefer closing bins
    // tightly since fewer future placements remain to use leftover gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    // Mean-residual coupling: if the fleet average residual is high, we have
    // slack; be pickier about poor fits (penalize large post_residual more).
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect lookahead match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Reward near matches within a tolerance band.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap <= 10.0 {
            score -= 120.0 - 12.0 * gap;
        } else {
            // Penalize post_residuals that are too small for the next item (dead space).
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.6;
            }
        }
    }

    // Penalize large leftover space relative to mean residual (wasteful fit).
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Discourage opening a new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 60.0;
        // Allow new bin if the best open fit would leave awkward residue.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 100.0;
        }
    }

    // Slight preference for tighter bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += tight * tight * 30.0;

    // Exact or near-exact fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // Lookahead coupling: reward bins whose leftover matches the next item.
    if next_item_size > 0 {
        let gap = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            (next_item_size - post_residual) as f64 * 1.5
        };
        score += gap * 0.8;
        if post_residual == next_item_size {
            score -= 60.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize spreading across many open bins; encourage consolidation
    // when open bin count is high relative to typical packing density.
    let density = open_bins_count as f64 / (1.0 + step_index as f64);
    score += density * 2.0;

    // Global residual pressure: if mean residual is small, prefer bins
    // that keep residuals aligned with the pack mean (harmonization).
    let drift = (post_residual as f64 - mean_residual).abs();
    score += drift * 0.3 * (mean_residual / bin_capacity as f64);

    // Time horizon: late in the stream, be greedier about tight fits;
    // early on, allow some slack to keep options open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= tight * tight * 40.0 * progress;
    score += (1.0 - progress) * 3.0;

    // New-bin candidate: only attractive when nothing fits well or the
    // stream is early and residuals are fragmented.
    if bin_residual == bin_capacity {
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = bin_capacity as f64 * 0.9
            + poor_fits * 100.0
            - progress * 20.0
            + (mean_residual / bin_capacity as f64) * 30.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin perfectly fits the next item if current leftovers don't.
            if post_residual == 0 {
                score -= 25.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear polynomial coupling to stream progress.
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr);

    // Penalize large dead space quadratically, stronger late in the stream.
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 8.0 * progress;
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 6.0 * (ni / cap) * (1.0 - progress);
        } else {
            score += 4.0 * (ni / cap);
        }
    }

    // New-bin candidate: penalize mildly early (reuse bins), less late.
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Small penalty for bins far below mean residual (keeps balance).
    score += 0.05 * (mean_residual - pr).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead space reward (harmonic classes of post_residual)
    if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    } else if post_residual <= 30 {
        score -= 8.0;
    }

    // Penalize residuals that are "unusable" for typical small items (1..100 unknown)
    // modulo classes: residuals mod 10 near 0 are more reusable
    let r = post_residual % 10;
    score -= (5 - r as i32).abs() as f64 * 1.5;

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 + (post_residual - next_item_size) as f64 * 0.3;
        }
        // penalize if next item cannot fit in post_residual (dead space likely)
        if next_item_size > post_residual && post_residual > 0 {
            score += post_residual as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: prefer new bin only when existing fits are terrible
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 120.0;
        // cheaper to open new bin late in stream when many bins already open
        score -= (open_bins_count as f64).ln() * 10.0;
        if next_item_size > 0 && next_item_size > bin_residual - item_size.min(bin_residual) {
            // new bin can host next item too
            score -= 30.0;
        }
    }

    // Favor bins tighter than the mean residual (good packing density)
    score += (mean_residual - post_residual as f64) * 0.5;

    // Early stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual == 0 {
        // Perfect fit is strongly rewarded.
        score -= 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Moderately reusable gap: mild reward proportional to size.
        score -= 5.0;
    }

    // Reward tight fits generally (small waste relative to item).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin pressure: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when the item would leave a large,
    // reusable residual and open bins are numerous / fragmented.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base cost of opening a new bin grows with number of open bins.
        score += 20.0 + open_bins_count as f64 * 2.0;
        // A new bin is better if existing bins are fragmented (low mean residual)
        // yet none fit well, or late in the stream with big lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size as u32 {
            score -= 15.0; // new bin can also host the next item
        }
        if mean_residual < 10.0 && open_bins_count > 3 {
            score -= 25.0 * progress;
        }
    }

    // Coupling with mean residual: prefer bins whose residual is near the mean
    // (keeps bin pool homogeneous), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Gap too small for the known next item: it is dead space for the lookahead.
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Bonus if the next item fits exactly after this placement.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize residuals too small for the next item (dead space).
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 30.0;
    }

    // Reward tight fits relative to mean residual of open bins.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // Penalize creating residual far below the mean residual (fragmentation).
    if (post_residual as f64) < mean_residual * 0.5 {
        score += (mean_residual - post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so it is chosen only when open bins fit poorly,
    // but allow it when many bins are open and residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 - 10.0 * progress;
        if open_bins_count > 3 && mean_residual < item_size as f64 {
            score -= 20.0; // fragmented state: fresh bin is fine
        }
    }

    // Prefer bins with small pre-placement residual (best-fit bias).
    score += bin_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
