pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: quadratic waste coupling
    let mut score = pr + 40.0 * pr_norm * pr_norm;

    // Smooth stream-progress coupling: later in stream, penalize large residuals more
    score += 30.0 * pr_norm * (0.5 + 0.5 * progress) * (1.0 - fit_ratio);

    // Reward tight fits with smooth saturation
    let tight = 1.0 - (pr_norm * 2.0).min(1.0);
    score -= 25.0 * tight * tight;

    // Last-chance bonus (smooth)
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: bonus if next item fits the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 12.0 * (1.0 - nx / cap);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Crowd/bin-count pressure
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);
    score -= 5.0 * (pr - mean_residual) / cap;

    // New-bin candidate: penalize slightly so it's only chosen when residuals are large
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls on coarse
    // capacity fractions (>= half) remain usable; small leftovers are dead space.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual >= half {
        score -= 15.0; // room for another medium/large item
    } else if post_residual >= quarter {
        score += 2.0;
    } else if post_residual > 0 {
        score += 12.0; // near-dead sliver
    }

    // Modulo-class coupling: reward when post_residual exactly accommodates
    // the lookahead item (perfect harmonic match).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
        // extra bonus if post_residual == next_item_size (perfect fill)
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // leftover cannot host the next item: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Integer-division threshold on item size vs residual: tight fits preferred.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.9 {
        score -= 25.0;
    } else if fit_ratio > 0.7 {
        score -= 10.0;
    } else if fit_ratio < 0.3 {
        score += 8.0; // dumping small item into big bin wastes structure
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (this bin is the empty candidate when residual == capacity).
    if bin_residual == bin_capacity {
        let crowd = if fitting_bins_count == 0 { 0.0 } else { 40.0 + 10.0 * fitting_bins_count as f64 };
        // early stream: keep bins open, avoid bin explosion
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += crowd + 20.0 * (1.0 - progress) + open_bins_count as f64 * 2.0;
        // if next item is huge, a fresh bin is more tolerable
        if next_item_size >= 60 { score -= 15.0; }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Slight preference for bins below mean residual (balance load).
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for the smallest plausible item are waste.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(20)) {
        score += 40.0; // unusable sliver
    }

    // Penalize residuals that cannot fit the lookahead item (unless post_residual is 0, a perfect fit).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward tight fits (small post_residual that is still useful).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Pressure from number of open bins: discourage spreading when many bins are open.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it neutral-ish; only attractive when fits are poor.
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.2;
    }

    // Slight preference for bins with residuals near mean (balance load).
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
