pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: squared dead-space penalty, scaled by capacity.
    let tight = (post_residual as f64) / cap;
    score += 2.0 * tight * tight * cap;

    // Reward near-perfect fills.
    if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt && (post_residual as f64) - nxt <= 5.0 {
            score -= 15.0;
        } else if nxt > post_residual as f64 && nxt <= bin_residual as f64 {
            // next item won't fit here after placement but fits now — mild penalty
            score += 8.0;
        }
        // If next item exactly fills this bin now, prefer placing here.
        if next_item_size == item_size && bin_residual == item_size {
            score -= 20.0;
        }
    }

    // Penalize bins with residuals far below the mean (fragmented bins),
    // unless the item fits tightly there.
    let frag = mean_residual - (bin_residual as f64);
    if frag > 0.0 {
        score += 0.15 * frag;
    } else {
        score += 0.05 * frag.abs();
    }

    // New-bin candidate logic: only open a new bin when existing fits are poor
    // or few bins are open / early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let avg_fit_waste = if fitting_bins_count > 0 { mean_residual } else { cap };
        let poor_existing = avg_fit_waste > 0.6 * cap;
        let few_open = (open_bins_count as f64) < 2.0 + 8.0 * progress;
        if poor_existing || few_open {
            score -= 18.0;
        } else {
            // penalize opening new bins mid-stream when decent fits exist
            score += 20.0 + 15.0 * progress;
        }
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += 0.02 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let fit = item_size as f64 / cap;

    let mut score = pr;

    // smooth polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (1.0 + t) + prn * (1.0 - t);
    score += 40.0 * poly;

    // reward tight fits more strongly later in the stream
    score -= (1.0 - fit) * (1.0 + t) * 10.0;

    // penalize dead space relative to mean residual
    score += 0.5 * (pr - mean_residual).abs();

    // lookahead: reward leaving space usable by next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 8.0 * (1.0 - (pr - ni) / cap);
        } else {
            score += 6.0 * (ni - pr) / cap;
        }
    }

    // last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // discourage opening new bins early, allow later
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - t) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;

    // Reward small post_residuals strongly (tight fits).
    if pr == 0 {
        score -= 1000.0;
    } else if pr <= 10 {
        score -= 200.0 + (10 - pr) as f64 * 10.0;
    } else {
        // Dead-space classes: residuals that no item (1..=100, practically >=1) can use well.
        // Class by integer division thresholds (harmonic bands of capacity).
        let band = pr / 25; // 0..=3 harmonic quartiles
        score += match band {
            0 => -20.0,                       // 1..24: small leftover, still usable
            1 => 15.0,                        // 25..49: awkward mid residual
            2 => 5.0,                         // 50..74: half-ish, often fillable
            _ => 25.0,                        // 75..: large residual, wasteful fit
        };
        // Modulo-10 class: residuals divisible by 10 pair well with common sizes.
        if pr % 10 == 0 {
            score -= 12.0;
        } else if pr % 5 == 0 {
            score -= 5.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as i64;
        if nxt == pr {
            score -= 300.0;
        } else if nxt <= pr {
            score -= 30.0 + (pr - nxt) as f64 * 0.5;
        } else {
            // next item won't fit here; penalize leaving a gap it nearly fits.
            let gap = nxt - pr;
            if gap <= 10 {
                score += 20.0 + gap as f64;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // current fit is bad. New bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: prefer it only over wasteful placements.
        score = 0.35 * cap as f64; // ~35: beats placements leaving >35 dead space
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        }
        if next_item_size as f64 > 0.8 * cap as f64 {
            score -= 40.0; // big next item: fresh bin attractive
        }
    }

    // Progress coupling: late in the stream, tighten up (avoid spreading).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (mean_residual / cap as f64);

    // Slight preference for bins with below-average residual (keep big bins free).
    if (bin_residual as f64) > mean_residual {
        score += 8.0;
    } else {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are pure waste.
    if post_residual < 10 {
        score -= 60.0; // perfect/near-perfect fit is excellent
    } else if post_residual <= 20 {
        score -= 15.0; // still a good fit
    } else if post_residual <= 40 {
        score += 10.0; // mediocre gap
    } else {
        score += 30.0; // large leftover: bad unless bin was nearly empty
    }

    // But a large residual is fine if the bin was mostly empty (avoid wasting fresh bins).
    if bin_residual >= bin_capacity - 5 && post_residual > 30 {
        score += 25.0; // discourage dumping small items into fresh bins
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits the post-residual exactly-ish, reward it.
    if next_item_size > 0 {
        let nd = post_residual as i64 - next_item_size as i64;
        if nd == 0 {
            score -= 40.0; // chain fit
        } else if nd > 0 && nd < 10 {
            score -= 20.0; // next item nearly fills the gap
        } else if nd < 0 && (-nd) <= 10 {
            score += 20.0; // next item barely misses: bad placement
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Prefer bins tighter than the mean residual (better packing candidates).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Mild bonus for new-bin candidate when nothing else is attractive.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to bin capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness * 4.0).max(-1.0); // bonus for very tight fits

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Perfect chain: next item exactly fills the remainder.
        if slack < 1.0 {
            score -= 60.0;
        } else {
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item cannot use the leftover: dead space penalty, worse when dead space is large.
        score += 12.0 + 0.3 * post_residual as f64;
    }

    // Penalize leaving a residual that nothing in a typical stream can use (very small gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: mildly discourage opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if lookahead chains perfectly into a fresh bin, allow it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual above the mean (consolidate big gaps).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Slight late-stream conservatism: keep bins tighter as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: residuals that are too small to hold the smallest
    // plausible future item (<= 10) are wasted; penalize small nonzero leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty proportional to how far off it is.
        score += 3.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoids fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // open bins are, on average, nearly full (high mean residual pressure).
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Penalize new bins early / when many bins are open with slack.
        score += 20.0 * (1.0 - pressure);
        score += 0.5 * open_bins_count as f64;
        // Slight decay of the penalty late in the stream (consolidation phase).
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 6.0 * t;
    } else {
        // Mild preference for reusing bins as the stream progresses.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 2.0 * t;
    }

    // Global balance: prefer bins whose residual is close to the mean residual
    // (keeps open bins uniformly loaded, preserving flexibility).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Non-linear waste penalty: squared normalized residual
    score += 40.0 * pr_norm * pr_norm * cap;

    // Smooth coupling of residual with stream progress
    score += 25.0 * pr_norm * (progress - 0.5).abs();

    // Reward tight fits (small post_residual) increasingly with progress
    let tightness = 1.0 - pr_norm;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize if post residual is unusable but nonzero (dead space)
    if let Some(next) = (next_item_size > 0).then_some(next_item_size) {
        let nx = next as f64;
        if pr > 0.0 && pr < nx {
            score += 20.0 * (1.0 - pr / nx);
        } else if pr >= nx {
            // reward leaving room for the lookahead item
            score -= 15.0 * (pr - nx) / cap;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 + progress);
    }

    // Prefer bins with residual below mean (fill the emptier ones)
    score += 5.0 * (pr - mean_residual) / cap;

    // Mild penalty for too many open bins early on
    score += 2.0 * open_bins_count as f64 * (1.0 - progress);

    // Smooth polynomial term coupling fit ratio and progress
    score += 10.0 * fit_ratio * fit_ratio * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by small classes are more reusable.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -60.0 // perfect fill
    } else if pr % 10 == 0 {
        -18.0
    } else if pr % 5 == 0 {
        -9.0
    } else if pr % 2 == 0 {
        -3.0
    } else {
        4.0 // odd residue: harder to pair
    };
    score += class_bonus;

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.35;
        } else {
            score += (next_item_size - pr) as f64 * 0.12;
        }
    }

    // Penalize leaving dead space relative to mean residual.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64 - mean_residual).max(0.0) * (0.25 + 0.35 * t);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly, but allow it when fit is terrible.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        let poor_fit = if item_size > 0 && waste / bin_capacity as f64 > 0.5 { 1.0 } else { 0.0 };
        score += 30.0 - 55.0 * poor_fit + 3.0 * open_bins_count as f64 * (1.0 - poor_fit);
    }

    // Prefer tighter absolute fits.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero post_residuals are wasted space.
    if post_residual > 0 {
        if post_residual < 10 {
            // Tiny unusable gap -> heavy penalty scaled by how tiny it is.
            score += (10 - post_residual) as f64 * 6.0;
        } else if post_residual < 20 {
            score += (20 - post_residual) as f64 * 2.0;
        }
    } else {
        // Perfect fit is the ideal outcome.
        score -= 40.0;
    }

    // Reward residual that can still host plausible future items (1..=100 range).
    if post_residual >= 50 {
        score -= 8.0;
    } else if post_residual >= 25 {
        score -= 3.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 5.0; // double-penalize near-dead gaps
    }

    // Lookahead coupling: if next item fits in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward if next item would fill the bin nearly perfectly.
        if post_residual - next_item_size < 5 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Post-residual too small for the next known item: mildly penalize.
        score += 3.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
        if post_residual < 10 {
            score += 12.0; // but not if it creates dead space
        }
    }

    // Open-bin pressure: discourage spreading across many bins when mean residual is high.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.4 * (mean_residual / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has large post_residual; make it attractive
    // only when no open bin offers a decent fit (large items or fragmented open bins).
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0 && mean_residual >= item_size as f64 * 1.05;
        if decent_fit_exists {
            score += 25.0; // prefer existing bins with usable space
        } else {
            score -= 5.0; // opening fresh is reasonable
        }
        // Late in the stream, slightly prefer reusing bins to limit total count.
        score += progress * 6.0;
    }

    // Prefer bins whose residual is close to the item (snug fit) beyond raw post_residual.
    let snugness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += snugness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Partial lookahead: how close is post_residual to the next item
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + gap / 10.0);
    }

    // Penalize dead space that is too small to ever be useful (min item size assumed small, but
    // relative to item scale): very small leftovers are wasted
    if post_residual > 0 {
        let pr = post_residual as f64;
        if next_item_size > 0 && pr < next_item_size as f64 {
            score += (next_item_size as f64 - pr) * 0.5; // unusable slack penalty
        }
        // tiny leftover generally useless
        if pr < 5.0 {
            score += 25.0 * (5.0 - pr) / 5.0;
        }
    } else {
        score -= 20.0; // perfect fill
    }

    // Prefer bins whose residual is already below mean (they are "nearly done")
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when open bins exist and could fit decently
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 30.0;
        }
        // slightly prefer new bins early in stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild tie-break: fewer open bins is better overall
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where post_residual is small.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 8.0;

    // Penalize dead space that no future item can use: post_residual < 10 is perfect,
    // but residual in (0,10) wastes less than large awkward residuals.
    if post_residual < 10 {
        score -= 6.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = next_item_size as f64 / post_residual as f64;
        score -= 4.0 + 4.0 * chain;
    }
    // If next item cannot fit into post_residual nor into mean residual, penalize
    // leaving a bin that fragments the stream.
    if next_item_size > post_residual && next_item_size > mean_residual as u32 {
        score += 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate logic: an empty bin gets a baseline score near its residual,
    // penalize it mildly so we prefer reusing bins with decent fits, but reward
    // opening a new bin when all open bins would leave large post residuals.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 0.5;
        // Open a fresh bin early when mean residual is fragmented.
        if mean_residual < (item_size as f64) * 0.6 {
            score -= 12.0;
        }
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    // Prefer bins below the mean residual slightly (pack into emptier bins,
    // keep fuller bins for small future items).
    if (bin_residual as f64) > mean_residual {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer tight fits (low post_residual), with a non-linear penalty
    // that grows superlinearly for large wasted space.
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth stream-progress coupling: later in the stream, waste is more costly.
    score += 12.0 * norm_post * norm_post * progress;

    // Penalize post_residuals that are unusably small relative to the smallest
    // plausible item (dead space), via a smooth quadratic dip around mid residuals.
    let dead = (norm_post - 0.05).max(0.0);
    score -= 6.0 * (1.0 - dead.min(1.0)) * (1.0 - dead.min(1.0));

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Mild reward when many bins compete (encourages consolidating choices).
        score -= 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward if next item fits the post residual (chaining good fits).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let fit_quality = 1.0 - ((post - nxt) / cap);
            score -= 10.0 * fit_quality;
        } else {
            // Next item won't fit here: penalize proportional to the shortfall.
            score += 5.0 * ((nxt - post) / cap);
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (fill the fuller bins first, keep emptier bins flexible).
    score += 3.0 * (mean_residual - post) / cap;

    // Discard spreading across too many open bins when a tight fit exists.
    score += 0.5 * (open_bins_count as f64) * norm_post;

    // New-bin candidate guard: an empty bin has post == capacity - item;
    // make it attractive only for large items that would leave small waste elsewhere.
    if bin_residual == bin_capacity {
        score += 15.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "usable"
    // for common small item sizes (multiples of small moduli).
    let pr = post_residual;
    let mut usable_bonus = 0.0f64;
    if pr > 0 {
        if pr % 10 == 0 { usable_bonus += 6.0; }
        else if pr % 5 == 0 { usable_bonus += 3.0; }
        if pr % 20 == 0 { usable_bonus += 3.0; }
        if pr % 25 == 0 { usable_bonus += 2.0; }
        if pr % 4 == 0 { usable_bonus += 1.0; }
        // Very small dead space: harshly penalize awkward leftovers
        if pr < 10 {
            score += (10 - pr) as f64 * 1.5;
        }
    } else {
        // Perfect fill
        usable_bonus += 15.0;
    }
    score -= usable_bonus;

    // Exact-fit class via integer division thresholds
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac <= 0.05 { score -= 8.0; }
    else if frac <= 0.10 { score -= 4.0; }
    else if frac >= 0.80 { score += 5.0; } // large leftover, poor packing

    // Lookahead coupling: does post_residual accommodate next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: strongly reward, scaled by tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 4.0 + 0.05 * next_item_size as f64 - 0.02 * tight;
            if (post_residual - next_item_size) % 10 == 0 { score -= 2.0; }
        } else {
            // next item won't fit here: mild penalty proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.02 * gap.min(40.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: opening fresh bins is costly early,
    // more acceptable late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * progress;
        // If no open bin fits well, new bin becomes attractive
        if fitting_bins_count == 0 { score -= 25.0; }
    }

    // Prefer spreading load when many open bins have large mean residual
    if bin_residual as f64 > mean_residual {
        score += 0.5 * (bin_residual as f64 - mean_residual).min(30.0) / (open_bins_count.max(1) as f64).sqrt();
    }

    // Slight preference for tighter fits overall
    score -= 0.03 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual == 0 {
        // Perfect fit is ideal.
        score -= 40.0;
    }

    // Penalize post_residual relative to capacity more aggressively when gap
    // cannot plausibly hold a future item (typical min size ~10, but be safe
    // with interface range down to 1: only treat gaps < 10 as dead).
    let dead_ratio = if (post_residual as f64) < 10.0 { 1.0 } else { 0.0 };
    score += dead_ratio * (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Slight preference for bins whose residual is close to mean residual
    // (keeps residuals balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }
    // If next item cannot fit in post residual, this bin may become dead space.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with tight fits win.
        score += 30.0;
        // But if many open bins already exist and this item is large, a fresh
        // bin keeps flexibility.
        if open_bins_count > 3 && item_size >= 50 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Progress-based mild tightening: later in stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
