pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) with a non-linear boost.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Exact fit is extremely desirable.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Penalize opening a new bin when decent alternatives exist,
    // but relax the penalty as the stream progresses.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual == bin_capacity {
        score += 30.0 - 10.0 * progress;
        // Opening a new bin is more attractive when open bins are crowded.
        score -= (open_bins_count as f64).min(10.0);
        // If the next item is large, a fresh bin preserves large residual for it.
        if next_item_size > 0 {
            let slack = bin_capacity as f64 - next_item_size as f64;
            score -= 0.15 * slack;
        }
    }

    // Lookahead: penalize leaving a residual that is just barely too small
    // for the next item (wasted potential), reward residuals that fit it.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else if post_residual >= next_item_size * 3 / 4 {
            score += 5.0; // dead-ish space: too small for next, hard to reuse
        }
    }

    // Slight preference for bins whose residual is below the mean
    // (consolidate waste into few bins, keep large residuals free).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.05 * dev;
    }

    // Mild time-horizon modulation: earlier in the stream, be more
    // conservative about residual waste; later, prioritize closure.
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress (smooth, bounded).
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog01 = progress.clamp(0.0, 1.0);

    // Normalized residuals.
    let post_n = (post_residual as f64 / bin_capacity as f64).clamp(0.0, 1.0);
    let item_n = (item_size as f64 / bin_capacity as f64).clamp(0.0, 1.0);

    // Reward tight fits: quadratic coupling of post_residual with progress.
    // Late in the stream, small residuals matter more (bins are nearly closed out).
    score -= 8.0 * (1.0 - post_n) * (1.0 - post_n) * (0.5 + prog01);

    // Penalize large dead space non-linearly (cubic growth in post_residual).
    score += 4.0 * post_n * post_n * post_n;

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = next_item_size as f64 / bin_capacity as f64;
        score -= 6.0 * chain_fit * (1.0 - prog01);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize leaving a gap too small for the next item (unusable sliver).
        let gap = post_residual as f64 / bin_capacity as f64;
        score += 3.0 * gap * gap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 * (1.0 + item_n);
    }

    // New-bin candidate handling: opening a fresh bin should only win when no
    // open bin fits well. Make the empty bin mildly unattractive by default,
    // but attractive when mean residual across open bins is very low.
    if bin_residual == bin_capacity {
        let mean_n = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Penalize new bins more as stream progresses (consolidation pressure).
        score += 6.0 + 4.0 * prog01 - 5.0 * (1.0 - mean_n) * (1.0 - mean_n);
    }

    // Mild penalty for spreading across many open bins: prefer filling existing
    // bins when open_bins_count is large.
    let spread = open_bins_count as f64;
    score += 0.02 * spread * post_n;

    // Smooth non-linear interaction: post_residual vs progress coupling.
    score += 2.0 * post_n * (1.0 - prog01) * (1.0 - post_n);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how it decomposes modulo common item sizes
    let pr = post_residual;
    if pr > 0 {
        // Residuals divisible by small sizes are more reusable
        let mut reusability = 0.0f64;
        for m in [10u32, 20, 25, 50].iter() {
            if pr % m == 0 { reusability += 6.0; }
        }
        if pr % 5 == 0 { reusability += 2.0; }
        score -= reusability;

        // Dead-space penalty: tiny unusable leftovers
        if pr < 10 {
            score += (10 - pr) as f64 * 3.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does the post-residual exactly host the next item?
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 45.0;
        } else if pr > next_item_size {
            let nxt = next_item_size as f64;
            let left = (pr - next_item_size) as f64;
            // penalize leaving a next-leftover that is awkward (small dead zone)
            if left < 10.0 {
                score += (10.0 - left) * 2.0;
            }
            // reward harmonic alignment of leftover with next item class
            if (pr % next_item_size.max(1)) == 0 {
                score -= 12.0;
            }
            score += 0.0 * nxt;
        } else {
            // next item cannot fit here; mild penalty unless residual is large & generic
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin
        score += 40.0;
        // if many bins fit the item, discourage opening a new one
        score += fitting_bins_count as f64 * 10.0;
        // early in the stream, new bins are cheap
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 25.0;
        // large items leave large residuals in a fresh bin; fine
        if item_size >= 50 { score -= 10.0; }
    } else {
        // prefer bins whose residual is close to the item (tight fit)
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.15;
        // prefer using bins with below-mean residual (consolidate emptier bins)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Slight preference to spread across many open bins when they're numerous
    score -= open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // impossible, guard
    }

    // Penalize small unusable gaps strongly (non-linear "dead zone").
    // A gap that cannot plausibly host a future item (typical small items ~1..10,
    // but gaps < 10 are near-useless) is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual < 20 {
        // medium-dead zone: moderate penalty
        score += 12.0 + (20 - post_residual) as f64 * 1.5;
    }

    // Reward near-perfect fits exponentially.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack.min(20.0); // best when next item fills residual
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here; slight penalty proportional to wasted potential
        score += 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, heavily favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of a fresh bin plus its future flexibility.
        score += 25.0 + 2.0 * open_bins_count as f64;
        // A fresh bin is more attractive early in the stream (more items to come
        // benefit from a fresh large residual).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If mean residual across open bins is high, opening a new bin is wasteful.
        score += 0.3 * mean_residual;
    } else {
        // Slight preference for bins with tighter residuals among fitting bins
        // (best-fit flavor, reinforces dead-space avoidance).
        score += 0.05 * (bin_residual as f64 - post_residual as f64);
    }

    // Mild noise-free tiebreaker: prefer earlier bins implicitly via residual order.
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for perfect fit
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr == nxt {
            score -= 300.0;
        } else if pr > nxt {
            // leftover after both items still usable-ish; mild penalty proportional to gap
            score += (pr - nxt) * 0.5;
        } else {
            // next item won't fit here after placement: dead space penalty
            score += (nxt - pr) * 1.5;
        }
    }

    // Penalize waste relative to mean residual across open bins
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when nothing else fits well
    if bin_residual == bin_capacity {
        score += 150.0 + open_bins_count as f64 * 5.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 50.0; // pairing lookahead with fresh bin is fine
        }
    }

    // Slight late-stream tightening: prefer compacting as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-perfect fills
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 18.0 * tight * tight;

    // Reward bins that can still host the next item after this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 5.0; // dead-end penalty
            // extra penalty if next item would fit tightly in this bin otherwise
            if bin_residual - item_size as u32 >= 0 && next_item_size <= bin_residual {
                score += 4.0 * (1.0 - (bin_residual - next_item_size) as f64 / bin_capacity as f64);
            }
        }
    }

    // Last-chance bonus: only one bin fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when many open bins already fit the item
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin
        score += 30.0;
        // Cheaper to open a new bin early in the stream
        score -= 15.0 * (1.0 - progress);
        // If few fitting bins and mean residual is low, opening may be right
        if fitting_bins_count <= 1 {
            score -= 12.0;
        }
        // If mean residual across open bins is large, prefer reusing them
        score += 0.25 * mean_residual;
        // If the next item is large, a fresh bin is valuable
        score -= 0.15 * next_item_size as f64 * progress;
    } else {
        // Mild preference for fuller bins (best-fit bias)
        score -= 0.1 * (bin_residual as f64 / bin_capacity as f64);
        // Encourage consolidation when many bins are open
        score += 0.05 * open_bins_count as f64 * (1.0 - progress);
        // Prefer bins whose residual is close to item size (tight reuse)
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.08 * gap;
    }

    // Slight global pressure: as stream progresses, discourage fragmentation
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress, smooth non-linear coupling
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress_sq = progress * progress;
    let progress_mix = 0.5 + 0.5 * progress_sq; // later in stream => more waste-averse

    // Reward tight fits: subtract a smooth function of fill ratio
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * fill * fill * fill * progress_mix;

    // Penalize dead space relative to mean residual of open bins
    let dead = (post_residual as f64 - mean_residual) / cap;
    score += 15.0 * dead * dead.abs() * (0.5 + progress);

    // Last-chance bin: strongly favor using it (avoid opening new bin)
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * (1.0 - progress_sq);
    }

    // Lookahead: reward bins whose post-residual still fits next item
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64) >= nr {
            score -= 10.0 * (nr / cap) * (1.0 + progress);
        } else {
            score += 8.0 * (1.0 - (post_residual as f64 / cap)) * (nr / cap);
        }
    }

    // New-bin candidate: penalize opening new bins, more so early/mid stream
    if bin_residual == bin_capacity {
        score += 40.0 + 30.0 * (1.0 - progress) + 5.0 * (open_bins_count as f64).sqrt();
    }

    // Mild penalty for too many open bins relative to progress
    score += 2.0 * (open_bins_count as f64) * (1.0 - progress_mix);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls on coarse
    // capacity fractions (multiples of 25) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else {
        let class = pr % 25;
        match class {
            0 => score -= 18.0,
            10 | 20 => score -= 6.0,
            5 | 15 => score -= 3.0,
            _ => score += 4.0, // awkward residues
        }
        // Integer-division thresholds: residual too small for the smallest
        // plausible item is dead space.
        if pr < 10 {
            score += 50.0;
        } else if pr < 20 {
            score += 12.0;
        }
    }

    // Coupling with lookahead: if next item fits exactly into post_residual,
    // strongly reward; if it just misses (needs <= 5 more), penalize.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack <= 5 {
                score -= 10.0;
            } else {
                score -= (slack as f64).sqrt() * 2.0;
            }
        } else {
            let miss = next_item_size - pr;
            if miss <= 5 {
                score += 15.0; // near-miss creates unusable space
            } else {
                score += (miss as f64).sqrt() * 1.5;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using
    // it over opening a new bin (unless residual becomes tiny).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if pr < 10 { score += 35.0; } // but avoid trapping dead space
    }

    // New-bin candidate: penalize opening a new bin mildly; more when many
    // bins are open and mean residual is large.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64 + mean_residual * 0.3;
    } else {
        // Prefer bins tighter than the mean (best-fit flavor).
        let dev = post_residual as f64 - mean_residual;
        score += dev * 0.25;
    }

    // Late in the stream, consolidate: favor filling existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Reward tight fits strongly
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: favor residual that can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += 6.0;
        }
    }

    // Open bins pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 8.0 + 3.0 * open_bins_count as f64;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Mean residual coupling: prefer bins with residual near the mean (balanced use)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild progression term: tighten packing as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match between leftover
    // space and the next item's size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u32 == next_item_size {
            score -= 60.0; // perfect chain: bin becomes exactly full next step
        } else if (post_residual as u32) >= next_item_size {
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // leftover too small for the next item: dead space risk
            score += 10.0 + 0.5 * diff;
        }
    }

    // Penalize unusable slivers (< 10) harder since min item is 1..100 but
    // small leftovers rarely match.
    if post_residual < 5 {
        score -= 30.0; // bin essentially full: great outcome
    } else if post_residual < item_size {
        score += 5.0; // awkward leftover smaller than current item
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates
    // favorably from the average open-bin residual.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Progress-based pressure: late in the stream, tighten up (avoid
    // spreading items across many partially-filled bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 0.1 * post_residual as f64;

    // New-bin candidate: opening a new bin wastes the residual of existing
    // bins; only allow it when nothing decent fits. Base penalty scaled by
    // how many bins are already open.
    if bin_residual == bin_capacity {
        let waste = open_bins_count as f64 * mean_residual.max(0.0);
        score += 35.0 + 0.2 * waste;
        // But if next item would fit perfectly in a fresh bin and this item
        // leaves a bad leftover everywhere, a fresh bin is still reachable
        // via the lookahead reward; keep the penalty dominant enough.
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0;
        }
    }

    score
}
